insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('f278a6b4-fe0e-5876-b200-fcafbc456ff4', '2026-27', 'flexible', 'Full acceptance uses a Composite Predictive Index (CPI) of 18 or higher built from high school GPA and ACT/SAT (the formula is not printed), with a GPA of at least 2.25; CPI 16 plus a 2.25 GPA gives conditional acceptance. A waiver page lets first-year applicants (U.S. residents and international students) be admitted without ACT/SAT with a final high school GPA of at least 2.25; the international page says tests are waived for admission but required for scholarship eligibility. The waiver page is worded around COVID-19 restrictions and prints no end date, so confirm it is still active for fall 2027.', '7ceb4d19-0299-5f72-b8a9-759df33a6ab3');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('f278a6b4-fe0e-5876-b200-fcafbc456ff4', '2026-27', array['own']::text[], 30, 'Apply through AAMU''s own application (Future Bulldog portal); the Common App is not mentioned. The freshman page lists a $30 non-refundable application fee. International freshmen send the high school transcript to WES or another NACES member for a U.S.-equivalency and GPA evaluation (minimum GPA 2.25). The I-20 is issued only after all admission requirements are met and the required deposits for one academic year are paid; I-20 requests are accepted 60 to 120 days before the term (fall: April 15 to June 15).', '34fc5eb5-f238-5e14-83f9-6b404f3a29ba');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('bbf55098-7999-5b8e-b17f-1923c3a309bf', 'f278a6b4-fe0e-5876-b200-fcafbc456ff4', '2026-27', 'application', 'RD', 'International application deadline (fall 2027)', '2027-05-15', 'International page: fall May 15, spring October 1, summer March 15; applications must be received by these dates. The page prints no year; treated as fall 2027. No separate domestic freshman deadline is printed on the pages read.', '34fc5eb5-f238-5e14-83f9-6b404f3a29ba');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('f278a6b4-fe0e-5876-b200-fcafbc456ff4', 'required_nonnative', 'Not required for native English speakers. One year of college coursework completed in an English-speaking country may waive the TOEFL/IELTS requirement. Duolingo, PTE and Cambridge are not mentioned, and no ESL or conditional-admission pathway is described on the page.', '34fc5eb5-f238-5e14-83f9-6b404f3a29ba');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
select 'f278a6b4-fe0e-5876-b200-fcafbc456ff4'::uuid, 'required_option', '34fc5eb5-f238-5e14-83f9-6b404f3a29ba'::uuid, v.* from (values
 ('TOEFL_IBT', 61, 'Paper-based 500 or computer-based 178 also listed. No 1-6 band value given.'),
 ('IELTS', 5.5, null)) v;
insert into score_codes (institution_id, test_key, code, notes, source_id)
select 'f278a6b4-fe0e-5876-b200-fcafbc456ff4'::uuid, v.* from (values
 ('sat', null, 'No SAT code is printed on the pages read.', '22d72da8-4f97-5d70-a2f3-400326c3aa2c'::uuid),
 ('act', null, 'No ACT code is printed on the pages read.', '22d72da8-4f97-5d70-a2f3-400326c3aa2c'::uuid),
 ('toefl', '1003', 'Institution code listed with the English proficiency requirement.', '34fc5eb5-f238-5e14-83f9-6b404f3a29ba'::uuid),
 ('ielts', null, 'No institution code is listed.', '34fc5eb5-f238-5e14-83f9-6b404f3a29ba'::uuid)) v;
insert into cost_aid (institution_id, year, tuition_intl_usd, intl_aid_policy, intl_need_aid, meets_full_need, merit_scholarships, notes, source_id) values
 ('f278a6b4-fe0e-5876-b200-fcafbc456ff4', '2026-2027', 19312, 'merit_only', false, false, true, 'Value is the Fall 2026 non-resident flat rate for 12-18 credit hours, commuting ($9,656 per semester), doubled; it includes mandatory fees. The page prints no separate international rate. The ''Boarding'' column is $13,848 per semester but the page does not define it, so room and board are left null (listed separately: traditional hall $1,955, Bulldog 21 meal plan $2,240; billing period not stated). Mandatory international health insurance is $1,014 (period not stated), not included.; The international page says academic scholarships are available to F-1 visa students and that test scores are required for scholarship eligibility. Out-of-state awards on the scholarship page include Normalite Opportunity ($8,610 per year, must live outside Alabama, CPI 20+) and Academic Recognition ($5,000 for out-of-state students, 3.00 GPA); that page does not say whether international students qualify, so confirm with scholarships@aamu.edu.', '9941ee8e-6590-5361-a564-19cbbebb9fc8');
insert into institution_tiers (institution_id, tier_code, category_key, rationale)
select 'f278a6b4-fe0e-5876-b200-fcafbc456ff4'::uuid, 'D', v.* from (values
