 ('9521067b-245f-520c-8f5a-f8cf94dbefff', 'alabama-state', 'Alabama State University', 'Alabama State', 'US', 'AL', 'Montgomery', 32.364317, -86.295677, 'urban', 'public', 'https://www.alasu.edu/', 'https://www.alasu.edu/admissions/index.php', 100724, 3521, 2.47, 15, 'semester');
insert into sources (id, institution_id, kind, title, url, cds_year, accessed_on) values
 ('c92b76d1-c273-5f04-b5c0-9d89eb36bf96', '9521067b-245f-520c-8f5a-f8cf94dbefff', 'ipeds', 'IPEDS / College Navigator - Alabama State University (fall 2024 admissions, test scores, enrollment, 2024-25 costs)', 'https://nces.ed.gov/collegenavigator/?id=100724', '2024-2025', '2026-10-26'),
 ('1bcc89a4-a815-5fde-bd29-c94dd6c76a84', '9521067b-245f-520c-8f5a-f8cf94dbefff', 'other', 'NCES IPEDS fall 2024 admissions and fall enrollment counts (Urban Institute Education Data Portal)', 'https://educationdata.urban.org/api/v1/college-university/ipeds/admissions-enrollment/2024/?unitid=100724', '2024-2025', '2026-10-26'),
 ('a47a0df1-da52-5e75-84cf-c970ffebb670', '9521067b-245f-520c-8f5a-f8cf94dbefff', 'admissions_site', 'Alabama State University - Admissions (freshman requirements, test-optional policy, deadlines, fee)', 'https://alasu.edu/admissions/', null, '2026-10-26'),
 ('dd3c316d-ec25-58ab-b769-a0a96a80a914', '9521067b-245f-520c-8f5a-f8cf94dbefff', 'admissions_site', 'Alabama State University - International Student Admissions', 'https://alasu.edu/admissions/international-students.php', null, '2026-10-26'),
 ('e3735484-ebf6-5f36-8c48-f4d7c8f714bf', '9521067b-245f-520c-8f5a-f8cf94dbefff', 'admissions_site', 'Alabama State University - International Student Checklist', 'https://www.alasu.edu/_qa/international-student-checklist.php', null, '2026-10-26');
insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, pct_submit_sat, pct_submit_act, notes, source_id, source_note) values
 ('9521067b-245f-520c-8f5a-f8cf94dbefff', '2024-2025', 7229, 7052, 1056, 1, 34, 'Baseline from IPEDS fall 2024 (College Navigator percentages; exact counts from the NCES ADM2024 file via the Urban Institute Education Data Portal). Alabama State''s institutional data page links Common Data Sets only through 2021-2022, so no CDS is used: international applicants/admits, GPA, SAT total and admission factors are not included. College Navigator prints 98% admitted. SAT/ACT ranges cover enrolled first-time students who submitted scores (SAT 1%, ACT 34%), so the SAT range rests on very few students; no 50th percentiles are printed. Undergraduate enrollment 3,521 and nonresident-alien undergraduates 87 are IPEDS fall 2024 enrollment.', 'c92b76d1-c273-5f04-b5c0-9d89eb36bf96', 'admissions_site');
insert into test_score_percentiles (institution_id, cds_year, source_id, test, p25, p75)
select '9521067b-245f-520c-8f5a-f8cf94dbefff'::uuid, '2024-2025', 'c92b76d1-c273-5f04-b5c0-9d89eb36bf96'::uuid, v.* from (values
 ('SAT_ERW', 399, 505),
 ('SAT_MATH', 350, 462),
 ('ACT_COMPOSITE', 15, 20)) v;
insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('9521067b-245f-520c-8f5a-f8cf94dbefff', '2026-27', 'optional', 'The freshman admissions page says ASU is test-optional, but ACT/SAT scores still decide which admission tier applies (sliding GPA/test scale; applicants with a 2.4+ GPA and no score fall in Tier II). The international page lists ACT or SAT among its required documents with its own GPA/score table (for example GPA 3.50+ with SAT 720 or ACT 15), so international applicants should confirm whether scores are needed.', 'a47a0df1-da52-5e75-84cf-c970ffebb670');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('9521067b-245f-520c-8f5a-f8cf94dbefff', '2026-27', array['own']::text[], 30, 'Apply with ASU''s own online application; the Common App is not mentioned. $30 application fee on both the freshman and international pages. International applicants also send transcripts evaluated by Lisano International, WES or another NACES member, a notarized Confidential Financial Support Affidavit covering first-year expenses, a health evaluation with TB results, and proof of health insurance with repatriation and medical evacuation cover. The Form I-20 is issued only after all requirements are met.', 'dd3c316d-ec25-58ab-b769-a0a96a80a914');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('38f83b5a-85db-5649-abf7-10b0d73f3792', '9521067b-245f-520c-8f5a-f8cf94dbefff', '2026-27', 'application', 'RD', 'International application deadline, fall 2027', '2027-06-01', 'International page: fall (begins August) June 1, spring November 1, summer April 1; the checklist repeats these dates. The pages print no year, so this is treated as fall 2027. The freshman page lists a July 30 fall deadline for domestic applicants.', 'dd3c316d-ec25-58ab-b769-a0a96a80a914'),
 ('842ea630-e1ba-5439-80dd-dcc214af5ddf', '9521067b-245f-520c-8f5a-f8cf94dbefff', '2026-27', 'scholarship', null, 'Academic scholarship application (applications open October 1)', '2027-02-15', 'Freshman page: scholarship applications open October 1 and are accepted through February 15; no year printed, treated as the 2026-27 cycle. The international page says international students are eligible for academic scholarships.', 'a47a0df1-da52-5e75-84cf-c970ffebb670');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('9521067b-245f-520c-8f5a-f8cf94dbefff', 'required_nonnative', 'Students from English-speaking countries (the page names the UK, Canada except Quebec, and Nigeria) and applicants who completed a degree at a regionally accredited U.S. institution are exempt. The requirement is also met by completing Level 112 at a Language Center (as printed).', 'dd3c316d-ec25-58ab-b769-a0a96a80a914');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
select '9521067b-245f-520c-8f5a-f8cf94dbefff'::uuid, 'required_option', 'dd3c316d-ec25-58ab-b769-a0a96a80a914'::uuid, v.* from (values
 ('TOEFL_IBT', 70, 'Regular admission: 70 iBT (525 paper, 193 computer). Conditional admission is offered at 69 iBT (523-477 paper, 190 computer) as printed. The same page''s application-process section lists lower minimums (61 iBT / 500 paper / 173 computer), so the two passages conflict; 70 is used here as the safer figure. No 1-6 band value is given.'),
 ('IELTS', 5.5, 'Regular admission 5.5; 4.5-5.0 for conditional admission.'),
 ('DUOLINGO', 100, null)) v;
insert into score_codes (institution_id, test_key, notes, source_id)
select '9521067b-245f-520c-8f5a-f8cf94dbefff'::uuid, v.* from (values
 ('sat', 'No SAT code is printed on the pages read.', 'a47a0df1-da52-5e75-84cf-c970ffebb670'::uuid),
 ('act', 'No ACT code is printed on the pages read.', 'a47a0df1-da52-5e75-84cf-c970ffebb670'::uuid),
