insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('dc9b61eb-b8b5-53e3-b7cf-7bc255f62cfd', '2026-27', 'optional', 'SAT or ACT is optional for the 2026-27 cycle; the most advantageous combination (superscore) is used; ACT Science is optional. Self-reported scores accepted; official scores only if admitted and enrolling.', 'aba2df83-6f1c-51c7-9376-aa667df19ef8');
