insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('dc9b61eb-b8b5-53e3-b7cf-7bc255f62cfd', 'required_nonnative', 'Required for applicants whose first language is not English. Waiver only for applicants who completed the two most recent years of secondary education at a school with English as the primary language of instruction, or who are native English speakers; no other waivers. Amherst offers no provisional admission or ESL instruction. Self-reported scores accepted; official scores required on enrollment.', 'd5276794-8417-5cf4-839e-3377f7e7cfb6');
