insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, intl_applicants, intl_admits, in_state_applicants, in_state_admits, out_state_applicants, out_state_admits, pct_submit_sat, pct_submit_act, gpa_avg, pct_reporting_gpa, gpa_distribution, notes, source_id) values
 ('978223ee-9daa-5e55-a85f-279a5ae13b2f', '2025-2026', 6865, 5479, 1359, 57, 55, 6547, 5225, 261, 199, 29.07, 43.56, 3.71, 88.52, '{"4.0": 19.2, "3.75-3.99": 27.35, "3.50-3.74": 24.85, "3.25-3.49": 15.96, "3.00-3.24": 6.57, "2.50-2.99": 4.24, "2.0-2.49": 1.58, "1.0-1.99": 0.08}'::jsonb, 'CDS C1 (Fall 2025 entering class): 6,865 applied, 5,479 admitted (79.8%), 1,359 enrolled; residency rows (in-state / out-of-state / international) sum to the totals. International (nonresident) first-years: 57 applied, 55 admitted (96%), 35 enrolled. No early decision or early action, no waitlist, rolling admission. GPA columns are the ''all enrolled students'' set; 0.17% had a GPA below 1.0 and is omitted. Undergraduate enrollment 10,103 and nonresident count 295 are the B1/B2 ''Total Undergraduates'' figures. The CDS lists SAT composite 25th/50th percentiles (860/990) but the 75th percentile cells are blank (#REF!), so the SAT/ACT percentile ranges shown come from IPEDS (fall 2024) instead.', 'd8d2e15f-646a-5c06-80e3-3488d71d137c');
