insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('c06e200e-13d7-51e2-aced-d0a390ea7e7a', '2026-27', 'optional', 'The international undergraduate FAQ requires only a 2.0 GPA, English proficiency and secondary-school records; SAT, ACT or ACCUPLACER scores are encouraged. Students admitted without scores take the ACCUPLACER on arrival before registering. (Domestic applicants must submit ACT/SAT under an Arkansas state requirement, per the CDS.)', '255fd512-25ea-5967-88f4-b938ec149caa');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('c06e200e-13d7-51e2-aced-d0a390ea7e7a', '2026-27', array['own']::text[], 50, 'Apply in the ATU international application portal. The $50 application fee must be paid before the in-office credential evaluation of foreign secondary records. First-time students submit mark sheets/certificates showing 12 years of schooling (unofficial uploads are accepted for admission). Evidence of funding of $29,950 for 9 months (plus $3,000 per dependent) is needed before an I-20 is issued. Minimum entering GPA 2.0; the CDS shows an almost-open admit rate (3,701 of 3,797 admitted).', '255fd512-25ea-5967-88f4-b938ec149caa');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('67e49418-c9ca-5d0c-96fd-8dbfb47599ee', 'c06e200e-13d7-51e2-aced-d0a390ea7e7a', '2026-27', 'application', 'ROLLING', 'International application deadline for NEW visa applicants (fall 2027 entry)', '2027-06-01', 'Dates are printed without a year; treated as fall 2027. For new visa applicants the spring deadline is Nov. 1 and summer April 1.', '255fd512-25ea-5967-88f4-b938ec149caa'),
 ('95d45ab1-3cca-56c9-a3cc-8beb9f71e98a', 'c06e200e-13d7-51e2-aced-d0a390ea7e7a', '2026-27', 'application', 'ROLLING', 'Deadline for CURRENT visa holders already inside the U.S. (fall 2027 entry)', '2027-07-15', 'For current visa holders the spring deadline is Dec. 1 and summer May 10.', '255fd512-25ea-5967-88f4-b938ec149caa'),
 ('5418f88b-fd3f-5669-b5a2-358502b4505a', 'c06e200e-13d7-51e2-aced-d0a390ea7e7a', '2026-27', 'scholarship', null, 'International Excellence / IB scholarship file complete (fall 2027 entry)', '2027-03-31', 'Complete file = international undergraduate application, scholarship application, high school transcript with GPA and two letters of recommendation, received by March 31 for fall (September 30 for spring).', 'beb19b35-c9ca-5b46-82f8-df24095a9f17');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('c06e200e-13d7-51e2-aced-d0a390ea7e7a', 'required_nonnative', 'Applicants from traditionally English-speaking countries who believe the requirement should be waived must email internationaladmissions@atu.edu after applying. Transfer students from U.S. colleges may instead show College English Composition I and II with a C or better. Scores must be no more than 2 years old. A copy of an official TOEFL, IELTS or PTE report can be uploaded to the application portal.', '907c81a9-1f7c-5079-9ed0-ed9c8fc38eb3');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
select 'c06e200e-13d7-51e2-aced-d0a390ea7e7a'::uuid, 'required_option', '907c81a9-1f7c-5079-9ed0-ed9c8fc38eb3'::uuid, v.* from (values
 ('TOEFL_IBT', 61, 'Valid MyBest TOEFL scores accepted. Other accepted TOEFL forms: written 500, computerized 173, TOEFL Essentials 8. The graduate minimum (79) does not apply to undergraduates.'),
 ('TOEFL_IBT_2026', 3.5, 'iBT on the 1-6 scale (graduate minimum is 4.0).'),
 ('IELTS', 5.5, 'IELTS Academic.'),
 ('PTE', 42, 'Pearson Test of English. EIKEN Grade 2A is also accepted. Duolingo and Cambridge are not listed.')) v;
insert into score_codes (institution_id, test_key, code, notes, source_id)
select 'c06e200e-13d7-51e2-aced-d0a390ea7e7a'::uuid, v.* from (values
 ('sat', null, 'ATU''s international pages give no SAT code; look it up in the College Board code search.', '255fd512-25ea-5967-88f4-b938ec149caa'::uuid),
 ('act', null, 'ATU''s international pages give no ACT code; look it up at act.org.', '255fd512-25ea-5967-88f4-b938ec149caa'::uuid),
 ('toefl', '6010', 'ATU ETS school code for sending TOEFL scores directly.', '907c81a9-1f7c-5079-9ed0-ed9c8fc38eb3'::uuid)) v;
insert into cost_aid (institution_id, year, tuition_intl_usd, required_fees_usd, intl_extra_fees_usd, room_board_usd, books_usd, total_coa_usd, intl_aid_policy, intl_need_aid, intl_merit_aid, intl_need_aid_awarded, intl_avg_award_usd, meets_full_need, merit_scholarships, notes, source_id) values
 ('c06e200e-13d7-51e2-aced-d0a390ea7e7a', '2026-2027', 12720, 2864, 1646, 11390, 1330, 29950, 'merit_only', false, true, 26, 9723, false, true, 'ATU international estimate for 12 credit hours per semester: tuition $12,720 ($529.98 per credit hour), fees $2,864 (include a $50 international student services fee), room and board $11,390, books $1,330, mandatory health insurance $1,646 (shown as the international extra), total $29,950. A student entering with a 2.25 GPA can get the in-state rate (roughly half the tuition), so the real cost may be lower. The CDS G1 listed in-state tuition $7,718 and out-of-state $15,436 but marked 2026-27 costs as not yet final.; First-time international students (high school seniors with a 3.25+ cumulative GPA) can compete for the International Excellence Scholarship ($4,500 per semester for up to 8 semesters, must live on campus) or the International Baccalaureate Scholarship ($2,550 per semester); awards are competitive and may be taxable depending on the home country. Federal aid is not available to international students. ATU also lets a student who enrolls with a 2.25 GPA pay in-state tuition (about half of the out-of-state rate). CDS H6: nonresidents can receive institutional non-need-based aid; 26 did, averaging $9,723.', '3ab422c9-8a2a-56c9-a017-8d00a3f0a362');
