insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('7718df68-68f3-50e9-843d-2c37df75ec0d', '2026-27', 'recommended', 'For international freshmen the SAT or ACT is used for academic advisement and placement (a placement test is given before enrollment if no score arrives) and is required to be considered for scholarships; the page also says UA recommends that freshman applicants sit for the SAT. No minimum score for admission is listed.', 'b7ffecdb-b3a2-595c-ab73-c90588bb56ab');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('7718df68-68f3-50e9-843d-2c37df75ec0d', '2026-27', array['own']::text[], 65, 'Online application plus $65 non-refundable fee. Also needed: Summary of Educational Experience form, unofficial transcripts (official ones if admitted), passport name page, official English score, and a bank statement or support letter before an I-20 is issued. Entering freshmen need the equivalent of a 3.0 GPA and four years of English plus three each of math, natural science and social studies (catalog).', 'b7ffecdb-b3a2-595c-ab73-c90588bb56ab');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('687bec78-55e4-5012-9928-ed290072fc83', '7718df68-68f3-50e9-843d-2c37df75ec0d', '2026-27', 'priority', null, 'Priority admission deadline (fall 2027, international)', '2026-11-01', 'Listed under ''Scholarship Deadlines'' on the international page; the page prints no year, so it is taken as the current cycle.', 'b7ffecdb-b3a2-595c-ab73-c90588bb56ab'),
 ('e91a83d6-7435-5561-bf39-c2a2d97cf7b9', '7718df68-68f3-50e9-843d-2c37df75ec0d', '2026-27', 'scholarship', null, 'Priority scholarship deadline', '2026-11-15', 'SAT or ACT must be received by the scholarship deadline; contact scholars@uark.edu.', 'b7ffecdb-b3a2-595c-ab73-c90588bb56ab'),
 ('66d70a90-b225-50c9-a340-290412ef0051', '7718df68-68f3-50e9-843d-2c37df75ec0d', '2026-27', 'scholarship', null, 'Final scholarship deadline', '2027-02-01', null, 'b7ffecdb-b3a2-595c-ab73-c90588bb56ab'),
 ('8ae7b0aa-d8b4-51ba-a57d-8f975f13f961', '7718df68-68f3-50e9-843d-2c37df75ec0d', '2026-27', 'application', 'ROLLING', 'Fall semester application deadline (international)', '2027-06-01', 'Priority is given to applications by this date; later ones are processed as space is available. The undergraduate catalog says May 31 instead. Spring deadline is Oct. 1 (catalog: Oct. 31).', 'b7ffecdb-b3a2-595c-ab73-c90588bb56ab');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('7718df68-68f3-50e9-843d-2c37df75ec0d', 'required_nonnative', 'Native speakers from listed English-speaking countries are exempt; also exempt: English Composition I and II with A-C at a U.S. regionally accredited college, grades 10-12 at a U.S. accredited high school, or a case-by-case waiver from the Director of International Admissions. A degree from India, Pakistan, Philippines, Hong Kong, Nigeria, Singapore, Ghana or Kenya does not exempt. Tests must be under two years old. Undergraduate-only alternatives: SAT EBRW 500 or ACT English 19. Applicants below the minimum may get conditional admission and take the Intensive English sequence (ELAC), completing Level VI with a B average to satisfy the requirement.', '5a64c511-f703-5706-a894-acaf544470d2');
