 ('TOEFL_IBT', 79, 'Old 0-120 scale value from the 2026-27 catalog. Institutional TOEFL 550 is accepted only through UA Testing Services.', '9b5be1f1-3469-5c6d-beb7-62879c21efb7'::uuid),
 ('TOEFL_IBT_2026', 4.0, 'The English proficiency page lists ''TOEFL Internet-Based 4.0''; it does not name the 1-6 scale but the value matches it.', '5a64c511-f703-5706-a894-acaf544470d2'::uuid),
 ('IELTS', 6.5, 'IELTS Academic only; General Training not accepted.', '5a64c511-f703-5706-a894-acaf544470d2'::uuid),
 ('DUOLINGO', 110, null, '5a64c511-f703-5706-a894-acaf544470d2'::uuid),
 ('PTE', 58, 'PTE Academic.', '5a64c511-f703-5706-a894-acaf544470d2'::uuid),
 ('CAMBRIDGE', 176, 'C1 Advanced. iTEP Academic 3.9 is also accepted.', '5a64c511-f703-5706-a894-acaf544470d2'::uuid)) v;
