insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, pct_submit_sat, pct_submit_act, notes, source_id, source_note) values
 ('2124b79d-268d-5633-bf8a-4c31491311aa', '2023-2024', 3633, 2927, 519, 2, 54, 'Baseline from IPEDS (fall 2023 entering class, ADM2023); the newest Common Data Set Ashland posts that was found is 2022-2023 (ashland.edu/sites/default/files/2024-08/CDS_2022-2023.pdf), which is older than the IPEDS baseline and was not used. College Navigator also shows fall 2024: 3,814 applicants, 76% admitted (exact admit count not given), SAT EBRW 505/560/610 and Math 530/560/598 for 32 submitters (7%), ACT composite 20/22/25 for 225 submitters (48%). SAT percentiles are not listed because only 9 enrolled students (2%) submitted SAT in fall 2023; ACT percentiles rest on 278 students (54%). International applicant and admit counts, GPA distribution and SAT total are not available from IPEDS; Ashland reported 230 international students from over 35 countries in spring 2025 (all levels).', '7c13d74d-dfb9-510a-9418-e885fc426562', 'admissions_site');
insert into test_score_percentiles (institution_id, cds_year, p75, source_id, test, p25, p50)
select '2124b79d-268d-5633-bf8a-4c31491311aa'::uuid, '2023-2024', 25, '2268d389-34e9-5509-a1d7-8fbdf819956c'::uuid, v.* from (values
 ('ACT_COMPOSITE', 20, 22),
 ('ACT_ENGLISH', 19, 21),
 ('ACT_MATH', 19, 22)) v;
insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('2124b79d-268d-5633-bf8a-4c31491311aa', '2026-27', 'optional', 'Sending ACT, CLT or SAT scores is optional for all majors except Nursing (scores required).', '9c80f202-928e-528a-b568-3d748d80b7e0');
insert into application_requirements (institution_id, cycle, platforms, notes, source_id) values
 ('2124b79d-268d-5633-bf8a-4c31491311aa', '2026-27', array['common_app','own']::text[], 'First-year students apply with Ashland''s free application or the Common App; the international page says a non-refundable application fee is charged and cannot be waived but prints no amount, so the fee is left blank. International undergraduates need the online application and official education credentials/transcripts (an evaluation of foreign records by a NACES member is required before admission; applicants from Ghana, Nigeria, Sierra Leone, Liberia and The Gambia also send official WAEC/WASSCE scores). Minimum GPA 2.5 (3.5 for Nursing). A $1,000 USD enrollment deposit is required before the I-20 is issued (refundable only if the visa is denied). Decisions take about 10-14 business days once all documents are in. Essay and recommendations are not listed.', '8d9c8f4b-d141-5ee6-83af-585a08caf2c5');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, notes, source_id) values
 ('3e3ce4fc-b19c-5d5e-a499-cfed1bbdbbad', '2124b79d-268d-5633-bf8a-4c31491311aa', '2026-27', 'application', 'ROLLING', 'International undergraduate application (fall 2027 entry): no deadline published', 'The international and undergraduate admissions pages print no application deadline for fall 2027. Decisions come about 10-14 business days after documents are complete, then the I-20 takes about 5-7 business days. Academic-scholarship eligibility uses grades on file through August 1 for fall; students admitted after that use their grades at admission.', '8d9c8f4b-d141-5ee6-83af-585a08caf2c5');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('2124b79d-268d-5633-bf8a-4c31491311aa', 'required_nonnative', 'Proof of English is required before admission and ''Medium of Instruction is not an acceptable English proficiency waiver''. Ashland no longer has an English language program or IEP, so there is no conditional-admission pathway for students below the minimums. Other exemptions are not listed on the page. Nursing sets higher minimums.', '8d9c8f4b-d141-5ee6-83af-585a08caf2c5');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
select '2124b79d-268d-5633-bf8a-4c31491311aa'::uuid, 'required_option', '8d9c8f4b-d141-5ee6-83af-585a08caf2c5'::uuid, v.* from (values
 ('TOEFL_IBT', 67, 'Undergraduate minimum; Nursing 84. Page footnote: TOEFL scores are transitioning from the 0-120 scale to the 1-6 scale in 2027.'),
 ('TOEFL_IBT_2026', 3.5, 'Undergraduate minimum printed as ''67 or 3.5''; Nursing 4.5.'),
 ('IELTS', 6.0, 'Undergraduate minimum; Nursing 7.0.'),
 ('DUOLINGO', 120, 'Undergraduate minimum; Nursing 130.'),
 ('PTE', 50, 'PTE Academic; Nursing 59.')) v;
insert into score_codes (institution_id, test_key, notes, source_id)
select '2124b79d-268d-5633-bf8a-4c31491311aa'::uuid, v.* from (values
 ('sat', 'Ashland''s admissions pages print no SAT code; look it up in the College Board code search.', '9c80f202-928e-528a-b568-3d748d80b7e0'::uuid),
 ('act', 'Ashland''s admissions pages print no ACT code; look it up at act.org.', '9c80f202-928e-528a-b568-3d748d80b7e0'::uuid),
 ('toefl', 'The international page prints no TOEFL code; select Ashland University in the ETS list.', '8d9c8f4b-d141-5ee6-83af-585a08caf2c5'::uuid)) v;
insert into cost_aid (institution_id, year, tuition_intl_usd, required_fees_usd, room_board_usd, books_usd, other_usd, total_coa_usd, intl_aid_policy, intl_need_aid, meets_full_need, merit_scholarships, merit_separate_app, notes, source_id) values
 ('2124b79d-268d-5633-bf8a-4c31491311aa', '2026-2027', 35400, 1360, 13530, 800, 1810, 52900, 'merit_only', false, false, true, false, 'International page, undergraduate 2026-27 yearly estimate: comprehensive tuition $35,400; activity/service fee $300 plus campus access fee $1,060 (= $1,360); board (regular, double/triple) $7,250 plus meal plan $6,280 (= $13,530); estimated health insurance $1,810 (other); books and supplies $800; total $52,900. 2025-26 total was $48,722.; International first-year academic scholarships for 2026-27 by high school GPA, amounts as printed (the page does not label them per year): AU International Gold 4.00+ $14,000; Presidential 3.80-3.99 $13,000; Provost 3.50-3.79 $12,000; Director 3.00-3.49 $11,000; Ambassador 2.70-2.99 $9,000; below 2.70 nothing. Renewal needs a 3.00 GPA for Gold and Presidential and 2.00 for the others. No separate application; must be full-time, pursuing a first bachelor''s degree and charged the comprehensive tuition rate; not available in summer. Ashland offers no full-tuition scholarships and international students are not eligible for U.S. federal or state aid; athletic awards come from the coach.', '840ff535-8040-51c7-a04a-edaa29bf927a');
