insert into cost_aid (institution_id, year, tuition_usd, tuition_out_of_state_usd, tuition_intl_usd, required_fees_usd, room_board_usd, books_usd, intl_aid_policy, intl_need_aid, intl_need_aid_awarded, intl_avg_award_usd, meets_full_need, merit_scholarships, notes, source_id) values
 ('94f0d91e-dec0-5225-bc09-a809e2d1db5e', '2026-2027', 12527, 36065, 39412, 1007, 18819, 1320, 'merit_only', false, 3344, 12660, false, true, 'CDS G1 (first-year, 2026-27). H6: only institutional NON-need-based aid is available to nonresidents; 3,344 nonresidents received it (avg $12,660). Tuition varies by program (G4).; International students do not qualify for federal/state aid. Merit-based New American University Scholarship (NAMU) is awarded to a limited number of qualified international undergraduates; colleges/departments also award scholarships. CDS H6: 3,344 nonresidents received institutional non-need-based aid, avg $12,660.', 'e24f6f1c-75bc-5776-b504-2fdf87417a85');
