insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, pct_submit_sat, pct_submit_act, notes, source_id, source_note) values
 ('ea8fc0ba-0290-5417-aa95-3e7545a023e1', '2023-2024', 5892, 5262, 1224, 56, 20, 'Baseline from IPEDS (fall 2023 entering class); exact counts. No public Common Data Set was found on augusta.edu (the Institutional Effectiveness reporting page links none), so GPA, residency and international applicant/admit counts are null. College Navigator for fall 2024 shows 6,011 applicants and 86% admitted (percentage only).', '84b51146-bebb-5eb2-bfae-8e8ad8734125', 'admissions_site');
