insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('ea8fc0ba-0290-5417-aa95-3e7545a023e1', '2026-27', 'required', 'Freshmen must submit SAT, ACT or CLT scores (one is enough; SAT/ACT are superscored). Minimums: SAT Evidence-Based Reading and Writing 480 and Math 440; ACT English or Reading 17 and Math 17. Meeting the minimums does not guarantee admission.', '33c8513c-e201-5c4d-add8-effecb2fe4e5');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('ea8fc0ba-0290-5417-aa95-3e7545a023e1', '2026-27', array['own']::text[], 60, 'Apply on Augusta''s own online application; $60 non-refundable (NACAC, College Board and ACT fee waivers accepted). Minimum 3.00 GPA recalculated on the 17 required high school courses (4 English, 4 math, 4 science, 3 social science, 2 foreign language). International applicants send official transcripts from every school; a NACES course-by-course evaluation is recommended, not required. Nursing applicants apply separately through NursingCAS. Enrollment deposit $200. International applicants should confirm acceptance at least 90 days before the semester starts to allow I-20 processing.', '33c8513c-e201-5c4d-add8-effecb2fe4e5');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('3c358447-1fa7-5678-bed0-ea107fa193a5', 'ea8fc0ba-0290-5417-aa95-3e7545a023e1', '2026-27', 'application', 'EA', 'Early Action deadline (fall 2027 entry)', '2026-10-31', 'Decisions released on or before Nov 15, 2026. The page is headed ''Important Dates for 2027 Applications'' and does not give separate international dates.', '33c8513c-e201-5c4d-add8-effecb2fe4e5'),
 ('31fe831a-0340-55ca-97ff-b8b3fb9ce7a1', 'ea8fc0ba-0290-5417-aa95-3e7545a023e1', '2026-27', 'scholarship', null, 'AU scholarship deadline', '2027-02-01', null, '33c8513c-e201-5c4d-add8-effecb2fe4e5'),
 ('b44d9bc4-d35e-5124-94e6-777e53b8ef75', 'ea8fc0ba-0290-5417-aa95-3e7545a023e1', '2026-27', 'application', null, 'Final application deadline (fall 2027)', '2027-07-01', 'The international page says documents are due before the ''assigned application deadline'' without listing a separate date.', '33c8513c-e201-5c4d-add8-effecb2fe4e5');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('ea8fc0ba-0290-5417-aa95-3e7545a023e1', 'required_nonnative', 'Waived with graduation from a U.S. high school, completion of an approved University System of Georgia ESL program, a degree earned where English is the language of instruction, or English 1101/1102 with a C or better at an accredited U.S. institution. Alternative test minimums: SAT EBRW 480, ACT English 17, EIKEN Pre-1, MET 59, IGCSE/O-level English D, GCSE or GCE A-level English C. No conditional-admission or ESL pathway for first-year international applicants was found on the page.', '372cf6c8-0c07-55f9-b11d-4adb5e0f967e');
