insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('5b842314-18fb-575b-9d9c-b60c62c5291b', '2026-27', 'optional', 'Test optional since 2007. ACT/SAT scores are supplemental and are considered only if self-reported or sent; test-optional applicants are fully eligible for academic scholarships. Some students may be asked to complete an interview. The admissions policy page lists ACT/SAT, or TOEFL/IELTS for international students, among the scores reviewed.', '201c184a-5ed8-5ac6-8edf-888709b36e3e');
insert into application_requirements (institution_id, cycle, platforms, notes, source_id) values
 ('5b842314-18fb-575b-9d9c-b60c62c5291b', '2026-27', array['common_app','own']::text[], 'Augustana Application or Common App (reviewed the same). Application fee: not stated on the pages read and the CDS fee boxes did not extract, so left null. Writing sample required of all applicants (case-by-case exceptions); admissions interview required for Early Decision and highly recommended for others; teacher/school letter of recommendation recommended, not required; international applicants must submit a Certification of Finances. Unofficial transcripts can be uploaded to apply, official ones are needed to matriculate. International applicants may enter in fall (late August) or spring (late January).', '4929cf7e-4d0a-5451-a2c0-aea597c95e9c');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notification_date, notes, source_id) values
 ('0672dfa9-d6d1-57e8-a285-7d351f9fdcab', '5b842314-18fb-575b-9d9c-b60c62c5291b', '2026-27', 'application', 'ED', 'Early Decision (binding), fall 2027 entry', '2026-11-01', '2026-12-01', 'Requires an admissions interview and signed ED agreement; tuition deposit due Dec. 20. Page prints no year; taken as the fall 2027 cycle.', '594c6fbc-2aaa-5425-a476-c236316d7c3f'),
 ('a420c25e-7b52-5d6d-a2da-c5239bf798e5', '5b842314-18fb-575b-9d9c-b60c62c5291b', '2026-27', 'application', 'EA', 'Early Action (non-binding), fall 2027 entry', '2026-11-01', '2026-12-18', 'Deposit due May 1. Page prints no year; taken as the fall 2027 cycle.', '594c6fbc-2aaa-5425-a476-c236316d7c3f'),
 ('657f78b7-b6cc-5d1f-b86c-f99f4f913520', '5b842314-18fb-575b-9d9c-b60c62c5291b', '2026-27', 'application', 'RD', 'Regular Decision, fall 2027 entry', '2027-04-01', null, 'Rolling decisions starting in early January; deposit due May 1. Page prints no year; taken as 2027.', '594c6fbc-2aaa-5425-a476-c236316d7c3f'),
 ('3c4ce5ce-cd8e-5060-970d-40a91553c96d', '5b842314-18fb-575b-9d9c-b60c62c5291b', '2026-27', 'application', 'RD', 'Regular Decision, spring 2027 entry', '2026-11-01', '2026-11-15', 'Spring enrollment deadline Nov. 1; decision Nov. 15; tuition deposit due Dec. 1.', '594c6fbc-2aaa-5425-a476-c236316d7c3f'),
 ('75f72c4e-7849-5bf6-90d4-49e830c1f571', '5b842314-18fb-575b-9d9c-b60c62c5291b', '2026-27', 'deposit', null, 'Tuition deposit (Early Action and Regular Decision, fall)', '2027-05-01', null, null, '594c6fbc-2aaa-5425-a476-c236316d7c3f');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('5b842314-18fb-575b-9d9c-b60c62c5291b', 'required_nonnative', 'Required for applicants whose first language is not English. Exemptions: graduation from an accredited U.S. high school after at least three consecutive years, U.S. associate''s degree, full IB Diploma in English, CEA-accredited intensive English program, secondary diploma/citizenship from a listed English-speaking country, IB English A grade 5+, AP English Language 4+, IGCSE English First Language C/4+, A-level English B+, or B+ in college composition courses. Test scores must be under 2 years old. Scores may be self-reported to get a decision; official scores are required at deposit. No conditional admission or ESL pathway was found on the international admissions pages (ELS Level 112 completion is accepted as proof).', '3ccda2c1-ad90-5351-b99e-4848872e4052');
