insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, intl_applicants, intl_admits, pct_submit_sat, pct_submit_act, gpa_avg, pct_reporting_gpa, gpa_distribution, notes, source_id, source_note) values
 ('97cbc3c6-40b6-511e-a213-214853769290', '2024-2025', 2694, 2467, 364, 638, 621, 4, 53, 3.44, 96, '{"4.0": 7, "3.75-3.99": 18, "3.50-3.74": 22, "3.25-3.49": 23, "3.00-3.24": 19, "2.50-2.99": 7, "2.0-2.49": 3}'::jsonb, 'Fall 2024 first-time first-year class from the 2024-25 CDS. Applicants 2,694 / admitted 2,467 / enrolled 364 are the sums of the C1 men and women rows and match College Navigator (2,694 applicants, 92% admitted, 15% of admits enrolled). The C1 residency table in the same CDS does not reconcile (its totals are 2,512 applicants / 162 enrolled, and out-of-state shows 57 applied but 199 admitted), so only the international row is used: 638 applied, 621 admitted, 30 enrolled (the 30 matches the B2 nonresident first-time count); the in-state/out-of-state split is left out. The 2025-26 CDS (fall 2025) reports 410 applicants, 407 admits and 407 enrolled in C1, i.e. the enrolled count in all three rows, so it was not used for admit rates. GPA is the ''all enrolled students'' column of C11 (sums to 99 as printed). Admission factors, test-score percentiles, enrollment (3,649 undergraduates, 120 nonresident, fall 2025) and costs come from the 2025-26 CDS. SAT percentiles come from only 11 enrolled students (3%); 208 students (51%) submitted ACT.', '4a2497cb-60a5-57b9-b004-6016ad014b40', 'admissions_site');
