insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('97cbc3c6-40b6-511e-a213-214853769290', '2026-27', 'optional', 'AUM says ACT/SAT scores are not required for admission and that scholarships and admission are considered without a score on file; scores can still help with scholarships. Freshman minimums on the admissions page: 2.3 unweighted high school GPA and ACT 18 or SAT 940 (minimum) when a score is submitted. The 2025-26 CDS ticks ''Recommended'' for SAT/ACT. AUM evaluates GPA, grade trends and course rigor.', '46920665-27f7-5c4b-a058-2c0629cf7c2b');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('97cbc3c6-40b6-511e-a213-214853769290', '2026-27', array['own']::text[], 0, 'International applicants use AUM''s online international application, which has no application fee (domestic freshmen pay $25 per CDS C13). Send a passport copy, the official high school transcript (with English translation if needed), proof of English proficiency (unless exempt), a bank statement and sponsor letter (the requirements page says the statement should show at least $33,233) and a supplemental international student form. A non-refundable $100 I-20 processing fee is charged after acceptance. CDS C7 lists essays and recommendations as not considered; no interview.', '10debc9c-6179-572f-bf81-bb5682e507d4');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('e8513e83-cc6a-5163-ba1f-7c1f7a0a5320', '97cbc3c6-40b6-511e-a213-214853769290', '2026-27', 'application', 'ROLLING', 'International applicants: fall 2027 application deadline', '2027-07-15', 'AUM''s international requirements page says it accepts students throughout the year and asks fall applicants to apply by July 15 (no year printed; treated as fall 2027). Spring: Nov 15; summer: April 15. The domestic undergraduate page lists Aug 1 for fall, but the international date is used here. Undergraduate international applications are processed in 5 to 8 business days once complete.', '10debc9c-6179-572f-bf81-bb5682e507d4');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('97cbc3c6-40b6-511e-a213-214853769290', 'required_nonnative', 'Exempt: students with 24 semester credit hours (or AUM English composition equivalent) from an accredited US college, a US secondary diploma or US bachelor''s/master''s degree, citizens of listed English-speaking countries (UK, Ireland, Canada except Quebec, Australia, New Zealand, Nigeria, Ghana, Jamaica and others), or students in certain government/military contract programs. Also accepted instead of a test: ACT composite 18 with English 18 (code 0057), SAT 860 combined with 450 Critical Reading (code 1036), iTEP 3.7, AP English Language or Literature 3+, IB English A 4+, or completion of AUM''s Intensive English Program, AUGlobal GLOB 0310 or ELS Level 112. Submit only one test.', 'e60a4572-c76a-5660-aa79-7245bec7fc5d');
insert into english_requirements (institution_id, source_id, test_key, status, min_total, notes)
select '97cbc3c6-40b6-511e-a213-214853769290'::uuid, 'e60a4572-c76a-5660-aa79-7245bec7fc5d'::uuid, v.* from (values
 ('TOEFL_IBT', 'required_option', 61, 'Institution code 1036. Paper-based TOEFL minimum 500.'),
 ('TOEFL_IBT_2026', 'required_option', 3.5, 'The test-score page lists ''New Scale of 1-6 band: 3.5''.'),
 ('IELTS', 'required_option', 5.5, null),
 ('DUOLINGO', 'required_option', 100, null),
 ('PTE', 'required_option', 44, null),
 ('CAMBRIDGE', 'accepted', null, 'Page asks for CEFR level B2 on Cambridge English exams (Preliminary, First, Advanced, Proficient, Business Preliminary, Vantage and Higher); no numeric score is given.')) v;
