insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('390e7c21-63ee-549d-92f1-3faf350421fc', '2026-27', 'flexible', 'F-1 applicants must submit ACT/SAT scores or placement (Accuplacer) scores; the Accuplacer may be taken online. Regular admission for freshmen needs the college-prep courses plus one of: high school GPA 2.85+, ACT 20+, or SAT 1020+ (EBRW + Math); an SAT of about 1100 clears the SAT threshold. Opportunity admission: GPA 2.75-2.84, ACT 19 or SAT 980. The international page states no minimum GPA or test score. CDS C8A box markings are not legible in the PDF text.', 'df8a559b-d9d2-59df-a44c-5eeede7d236a');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('390e7c21-63ee-549d-92f1-3faf350421fc', '2026-27', array['own']::text[], 25, 'Nonrefundable $25 application fee for F-1, J-1 and other non-U.S. citizen applicants. Required: passport biographical page, proof of financial support (affidavit of support and bank documents dated within one year of the intake term; the I-20 is not issued until it is on file), official high school completion record (original or certified/attested copies sent from the school), ACT/SAT or placement scores sent directly to APSU, and English proficiency evidence if needed. Immunization records are required before registering.', 'df8a559b-d9d2-59df-a44c-5eeede7d236a');
insert into deadlines (id, institution_id, cycle, kind, label, due_date, notes, source_id) values
 ('aa8e4a18-bb9f-5036-b7e6-2eec1a785663', '390e7c21-63ee-549d-92f1-3faf350421fc', '2026-27', 'application', 'Recommended application deadline, F-1 first-time students (fall 2027 entry)', '2027-07-01', 'The international page lists F-1 first-time deadlines as Fall July 1, Spring November 1, Summer April 1 (titled ''recommended''). Printed without a year, treated as fall 2027. CDS C14 separately lists an overall fall application closing date of August 5. Conditional admission is only available to students enrolled in the APSU English Language Institute who have submitted all other documents.', 'df8a559b-d9d2-59df-a44c-5eeede7d236a');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('390e7c21-63ee-549d-92f1-3faf350421fc', 'required_nonnative', 'Not needed if the applicant completed an entire U.S.-equivalent high school degree of at least four years in English; completed one full semester of non-remedial English composition at an accredited U.S. college with a C or better; or has ACT, SAT or Accuplacer scores meeting the minimum in all placement areas (Admissions director approval). Scores are valid for two years and must be sent from the testing agency. Applicants below the minimums can be admitted to the APSU English Language Institute''s Intensive English Program (online or in person); completing ELI university-transfer Level 5 can earn a score waiver.', '204cf1f3-3040-5013-8870-968890ec973c');
insert into english_requirements (institution_id, source_id, test_key, status, min_total, notes)
select '390e7c21-63ee-549d-92f1-3faf350421fc'::uuid, '204cf1f3-3040-5013-8870-968890ec973c'::uuid, v.* from (values
 ('TOEFL_IBT', 'required_option', 61, 'Minimum for tests taken before January 2026. TOEFL Essentials minimum 6.5; TOEFL ITP not accepted.'),
 ('TOEFL_IBT_2026', 'required_option', 3.5, 'Page lists ''TOEFL iBT Minimum - 3.5'' for tests from January 2026 without naming the scale; read as the new 1-6 scale.'),
 ('IELTS', 'required_option', 5.5, 'Overall score of 5.5 or better.'),
 ('DUOLINGO', 'required_option', 85, '85 or better.'),
 ('PTE', 'required_option', 52, 'PTE Academic, 52 or better; the online version is also accepted.'),
 ('CAMBRIDGE', 'accepted', 167, 'B2 First, C1 Advanced or C2 Proficiency, score 167 or better. Other accepted tests include GTEC 1051 (Unified GTEC 1067), TOEIC 580, Manchester Exam 301 and Clarity English 61.')) v;
