insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, pct_submit_sat, pct_submit_act, notes, source_id, source_note) values
 ('8202cb2b-ef85-56cf-ad89-bb0f8cfcab42', '2023-2024', 3850, 3060, 420, 13, 4, 'Baseline from IPEDS (fall 2023 entering class; exact counts). APU''s own Common Data Set page lists files only through 2020-21, so no recent CDS was used; GPA, international and residency splits are not added. College Navigator for fall 2024 shows 3,404 applicants, 88% admitted, 14% of admits enrolled, but only 12 SAT (3%) and 7 ACT (2%) score submitters (SAT EBRW 515/615, Math 468/623, ACT 25/30 as 25th/75th), so the fall 2023 scores are kept. Undergraduate enrollment 2,759 and student-faculty ratio 9:1 are from College Navigator (fall 2024).', '78e73e1b-cf53-5cd5-af94-eeeb62b7473b', 'admissions_site');
