 ('656374ef-2d78-57f1-9a00-9c0611d30fdb', 'e31573d2-ec9c-5a9a-95e7-c128bcbead6d', 'financial_aid_site', 'Ball State - Scholarships (International Student scholarships)', 'https://www.bsu.edu/admissions/financial-aid-and-scholarships/types/scholarships', null, '2026-10-26');
insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, intl_applicants, intl_admits, in_state_applicants, in_state_admits, out_state_applicants, out_state_admits, pct_submit_sat, pct_submit_act, gpa_avg, pct_reporting_gpa, gpa_distribution, notes, source_id) values
 ('e31573d2-ec9c-5a9a-95e7-c128bcbead6d', '2025-2026', 22193, 19141, 3720, 1520, 1443, 13125, 13125, 7548, 4573, 31, 1, 3.58, 99.57, '{"4.0": 24.3, "3.75-3.99": 15.77, "3.50-3.74": 15.06, "3.25-3.49": 15.63, "3.00-3.24": 14.93, "2.50-2.99": 14.2, "2.0-2.49": 0.08, "1.0-1.99": 0.03}'::jsonb, 'CDS C1 (Fall 2025 first-time first-year): 22,193 applied, 19,141 admitted (86%); international 1,520 applied and 1,443 admitted (95%), 42 enrolled. C9 SAT/ACT figures describe enrolled students: 31% submitted SAT (1,156) but only 1% ACT (21), so the ACT percentiles rest on very few students. No early decision or early action; no waitlist. C7 factor checkboxes were not readable from the PDF text and are omitted. Undergraduate enrollment is B1 total undergraduates (15,950); the nonresident count in B2 was not readable, so intl_undergrads is left null.', 'fd587caa-233b-54d5-9576-bbe59884391c');
insert into test_score_percentiles (institution_id, cds_year, source_id, test, p25, p50, p75)
select 'e31573d2-ec9c-5a9a-95e7-c128bcbead6d'::uuid, '2025-2026', 'fd587caa-233b-54d5-9576-bbe59884391c'::uuid, v.* from (values
 ('SAT_TOTAL', 1090, 1170, 1240),
 ('SAT_ERW', 560, 600, 650),
 ('SAT_MATH', 530, 570, 610),
 ('ACT_COMPOSITE', 23, 26, 27)) v;
insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('e31573d2-ec9c-5a9a-95e7-c128bcbead6d', '2026-27', 'optional', 'International first-time undergraduate page: SAT/ACT are not required for admission, but scores may be used to meet the English proficiency requirement (SAT EBRW 500 or ACT English 21).', '21363b16-7595-5a2a-aa18-3cc57ecbfa3c');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, fee_waiver, notes, source_id) values
 ('e31573d2-ec9c-5a9a-95e7-c128bcbead6d', '2026-27', array['own']::text[], 60, false, 'International applicants apply through the Ball State international admissions portal and pay $60; no individual fee waivers. Needs secondary school transcripts and English proficiency proof; some majors require a design portfolio, audition or essay. The page says no GPA guarantees admission, but the CDS shows 95% of international first-year applicants admitted in Fall 2025.', '21363b16-7595-5a2a-aa18-3cc57ecbfa3c');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('5f67ada7-711d-5f3f-83f5-8c14261e93ae', 'e31573d2-ec9c-5a9a-95e7-c128bcbead6d', '2026-27', 'priority', 'ROLLING', 'Priority date (fall 2027 entry)', '2027-03-01', 'CDS C14 lists March 1 as the priority date without a year; treated as 2027. Ball State admits on a rolling basis.', 'fd587caa-233b-54d5-9576-bbe59884391c'),
 ('625e74a7-df57-5428-9ffa-4f672c02e000', 'e31573d2-ec9c-5a9a-95e7-c128bcbead6d', '2026-27', 'application', 'ROLLING', 'International application materials due (fall 2027 entry)', '2027-06-15', 'Page says ''Fall Term - application materials due by June 15th'' without a year; treated as 2027. Spring term: November 15.', '21363b16-7595-5a2a-aa18-3cc57ecbfa3c'),
 ('d08802b2-8070-5b77-9f8f-1dbb36ea8701', 'e31573d2-ec9c-5a9a-95e7-c128bcbead6d', '2026-27', 'scholarship', null, '#YouAreWelcomeHere Scholarship application (essay or video)', '2027-03-31', 'Two annual $14,000 awards for incoming first-year international students; the page gives March 31 without a year (treated as 2027). The Global scholarships need no separate application per the page.', '656374ef-2d78-57f1-9a00-9c0611d30fdb');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('e31573d2-ec9c-5a9a-95e7-c128bcbead6d', 'required_nonnative', 'Required for all applicants with an education history outside the U.S. unless waived. Waived with a U.S. high school diploma, U.S. college degree or 24 credit hours at an accredited U.S. university, or the same from a listed English-speaking country (e.g. UK, Ireland, Canada excluding Quebec, Australia, New Zealand, Singapore, Nigeria, Ghana, Philippines), or at the discretion of International Admissions for English-medium study. Scores valid 24 months. SAT EBRW 500 or ACT English 21 also satisfies the requirement.', '32e636b7-1190-5a9e-9ce7-52776b5a0342');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
select 'e31573d2-ec9c-5a9a-95e7-c128bcbead6d'::uuid, 'required_option', '32e636b7-1190-5a9e-9ce7-52776b5a0342'::uuid, v.* from (values
 ('TOEFL_IBT', 79, 'MyBest scores accepted. Academic Bridge Program (part-time Intensive English Institute plus degree classes) at 75-78. Conditional admission to the Intensive English Institute from 42; the degree requirement must then be met before starting degree classes. The page does not give the new 1-6 TOEFL scale.'),
 ('IELTS', 6.5, 'IELTS Academic. Bridge Program at 6.0; Intensive English Institute conditional admission from 4.5.'),
 ('DUOLINGO', 110, 'Bridge Program at 100-105; Intensive English Institute conditional admission from 65.'),
 ('PTE', 53, 'Bridge Program at 51-52; Intensive English Institute conditional admission from 40.')) v;
insert into score_codes (institution_id, test_key, code, notes, source_id)
select 'e31573d2-ec9c-5a9a-95e7-c128bcbead6d'::uuid, v.* from (values
 ('toefl', '1051', 'Ball State school code 1051 as printed on the English proficiency page; scores must be sent electronically.', '32e636b7-1190-5a9e-9ce7-52776b5a0342'::uuid),
 ('sat', '1051', 'The same page prints school code 1051 for test reports; confirm in the College Board code search if the portal does not accept it.', '32e636b7-1190-5a9e-9ce7-52776b5a0342'::uuid),
 ('act', null, 'No ACT code is printed on the Ball State pages read; look it up at act.org.', null),
 ('ielts', null, 'Send electronically to Ball State University Admissions (admissions@bsu.edu); no numeric code listed.', '32e636b7-1190-5a9e-9ce7-52776b5a0342'::uuid),
 ('duolingo', null, 'No institution code is listed on the page.', '32e636b7-1190-5a9e-9ce7-52776b5a0342'::uuid),
 ('pte', null, 'No institution code is listed on the page.', '32e636b7-1190-5a9e-9ce7-52776b5a0342'::uuid)) v;
insert into cost_aid (institution_id, year, tuition_usd, tuition_out_of_state_usd, tuition_intl_usd, required_fees_usd, room_board_usd, books_usd, intl_aid_policy, intl_need_aid, intl_merit_aid, intl_need_aid_awarded, intl_avg_award_usd, meets_full_need, merit_scholarships, notes, source_id) values
 ('e31573d2-ec9c-5a9a-95e7-c128bcbead6d', '2026-2027', 8948, 27496, 27496, 2134, 12832, 782, 'merit_only', false, true, 189, 19716, false, true, 'CDS G1 first-year 2026-27: in-state tuition $8,948, nonresident tuition $27,496 (international students pay the nonresident rate), required fees $2,134, on-campus food and housing $12,832; G5 books $782. Tuition varies by program (G4). H6: only institutional NON-need-based aid is available to nonresidents; 189 nonresidents received institutional aid, average $19,716.; Admission-based international scholarships pay part of nonresident tuition, per year for up to 8 semesters, for full-time on-campus degree students (not usable for Intensive English Institute study): Global Achievement $12,000, Global Distinction $14,000, Global Presidential $16,000 (awarded from Spring 2025 onward; the page does not publish the criteria for each level). Recipients must meet the English requirement first.', 'fd587caa-233b-54d5-9576-bbe59884391c');
