insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('8f28c049-3703-53ed-a256-c7b987593a70', '2026-27', 'optional', 'Test-optional for students applying through the 2027 first-year and transfer cycles; SAT and ACT are superscored if submitted; self-reporting allowed, official scores required on enrollment.', '38c578d0-4a7f-57f8-ac03-5d41b138a6bf');
insert into application_requirements (institution_id, cycle, platforms, supplemental_essays, teacher_recs, counselor_rec, interview, app_fee_usd, notes, source_id) values
 ('8f28c049-3703-53ed-a256-c7b987593a70', '2026-27', array['common_app','questbridge']::text[], true, 2, true, 'not_offered', 75, 'Common App personal essay plus two required short answers (50-word and 200-250-word). Two teacher letters in core academic subjects and one counselor letter. No admissions interviews; an optional Glimpse video is offered, and international applicants may submit paid InitialView or Vericant interviews. Financial aid review uses the FAFSA and CSS Profile (international filing rules not confirmed on pages checked). The rounds page does not state the entry year; dates are for the 2027 entering class.', '226b79a4-a93f-5356-81aa-aa08ecf2a909');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('2410acb0-5232-586b-8d86-2c38198796c2', '8f28c049-3703-53ed-a256-c7b987593a70', '2026-27', 'application', 'ED', 'Early Decision (binding)', '2026-11-01', 'Notification mid-December (no exact date).', 'b1e2cbb4-c5bc-57c2-8fb9-886f56452d5f'),
 ('a89ce4c1-f728-5809-8650-e7ac59d0f9d4', '8f28c049-3703-53ed-a256-c7b987593a70', '2026-27', 'application', 'RD', 'Regular Decision', '2027-01-01', 'Notification late March (no exact date); reply by May 1.', 'b1e2cbb4-c5bc-57c2-8fb9-886f56452d5f');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('8f28c049-3703-53ed-a256-c7b987593a70', 'required_nonnative', 'Waived if English is one of your first languages, you attended a secondary school with English as the primary language of instruction for your entire secondary career, you are in or completed the IB Diploma or A Levels taught in English, or you scored 700+ on SAT EBRW or 29+ on ACT English or Reading. TOEFL Essentials and MyBest scores are not accepted; scores are valid two years.', '0d761106-cc81-5ff1-a3c9-da71ea88650c');
insert into english_requirements (institution_id, status, source_id, test_key, recommended_total, notes)
select '8f28c049-3703-53ed-a256-c7b987593a70'::uuid, 'required_option', '0d761106-cc81-5ff1-a3c9-da71ea88650c'::uuid, v.* from (values
 ('TOEFL_IBT', 105, 'Listed as what the most competitive candidates generally receive, not a minimum. Home Edition accepted. The page gives a separate figure for exams after 2026-01-20 that looks inconsistent, so it is not recorded.'),
 ('IELTS', 7.5, 'Most competitive candidates generally receive 7.5 or higher; IELTS Indicator accepted.'),
 ('DUOLINGO', 135, 'Most competitive candidates generally receive 135 or higher.')) v;
