insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('1a8d45fd-0b47-5915-80c5-46f827e3ae42', '2026-27', 'optional', 'Test-optional: applicants choose whether to submit SAT/ACT, and merit scholarships do not require scores. Exception: international students whose native language is not English and who attend high school outside the U.S. must submit TOEFL, IELTS or MELAB (or may submit an ACT/SAT in place of them). Middle-50% of admitted students who submit scores: ACT 22-27, SAT 1060-1260; median admitted GPA 3.7.', '91f889d5-aaee-58b5-b807-d8174168c07d');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('1a8d45fd-0b47-5915-80c5-46f827e3ae42', '2026-27', array['common_app','own']::text[], 0, 'Apply through Common App or the Bellarmine App; the deadlines page says early action applicants pay no application fee and online applicants have the fee waived. International applicants must also send a course-by-course credential evaluation (The Evaluation Company or WES for non-U.S. schools), proof of funding for one academic year, and at least one letter of recommendation from a teacher or counselor who knows their language skills. Minimum high school units: 4 English, 3 math, 3 social studies/history, 2 lab sciences, 2 foreign language. A full-tuition scholarship also needs a recommendation letter.', '92bde98c-2d48-57b9-8602-92dc861ae3fb');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('df360f13-4dd2-567a-8b27-582703cec329', '1a8d45fd-0b47-5915-80c5-46f827e3ae42', '2026-27', 'application', 'EA', 'Early Action (fall 2027 entry)', '2026-11-01', 'Page prints Nov 1 with no year; treated as Nov 1, 2026 for fall 2027 entry (the year is inferred, not printed). Early action applicants pay no fee and are notified of institutional scholarships in November.', '4a4accb8-6f36-5725-82b9-9755a3cc6721'),
 ('965d5b68-3bdf-5af1-bfaa-3e154d38d75a', '1a8d45fd-0b47-5915-80c5-46f827e3ae42', '2026-27', 'scholarship', null, 'Bellarmine Scholars and Fellows (full-ride / full-tuition) application', '2026-12-01', 'Page prints Dec 1 with no year (treated as Dec 1, 2026). Five Scholar awards (four-year full ride) and five Fellow awards (four-year full tuition); applicants must be admitted before Dec 1 to apply. Whether international students are eligible is not stated.', '4a4accb8-6f36-5725-82b9-9755a3cc6721'),
 ('960a47a6-9e63-5070-8efa-ed1a6f384315', '1a8d45fd-0b47-5915-80c5-46f827e3ae42', '2026-27', 'application', 'RD', 'Regular Decision requested date (fall 2027 entry)', '2027-02-01', 'The page ''requests'' standard applications by Feb 1 (no year printed; treated as Feb 1, 2027). The 2025-26 CDS reports rolling notification and an Aug 15 closing date. No separate international deadline is published.', '4a4accb8-6f36-5725-82b9-9755a3cc6721');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('1a8d45fd-0b47-5915-80c5-46f827e3ae42', 'required_nonnative', 'Met without a test if the student earned a secondary diploma in a TOEFL-exempt country, or completed at least one year of full-time university study (24 credit hours, 2.0 GPA) in an exempt country; ''language training at an approved center'' is also listed as evidence. Students with outstanding English skills may instead submit ACT 21 composite or SAT 1060. Some programs, such as nursing, may set higher language minimums; check the program page.', '2361810c-87fd-52ca-a64b-c09701614485');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
select '1a8d45fd-0b47-5915-80c5-46f827e3ae42'::uuid, 'required_option', '2361810c-87fd-52ca-a64b-c09701614485'::uuid, v.* from (values
 ('TOEFL_IBT', 80, 'The page prints ''Internet-based test 79 or 80'' (paper-based 550, computer-based 213); 80 is shown as the safer figure. MELAB 78 is also accepted.'),
 ('IELTS', 6.0, null),
 ('DUOLINGO', 105, 'Results are sent with a video interview and writing sample.')) v;
insert into score_codes (institution_id, test_key, notes, source_id)
select '1a8d45fd-0b47-5915-80c5-46f827e3ae42'::uuid, v.* from (values
 ('sat', 'No SAT code was found on Bellarmine''s admissions pages; look up Bellarmine University in the College Board code search.', '6350a322-5a5d-53d0-8c8a-375185a7583f'::uuid),
 ('act', 'No ACT code was found on Bellarmine''s admissions pages; look it up at act.org.', '6350a322-5a5d-53d0-8c8a-375185a7583f'::uuid),
 ('toefl', 'No TOEFL institution code was found on Bellarmine''s international pages.', '2361810c-87fd-52ca-a64b-c09701614485'::uuid),
 ('ielts', 'No institution code is listed.', '2361810c-87fd-52ca-a64b-c09701614485'::uuid),
 ('duolingo', 'Send results to Bellarmine through the Duolingo account; no code is listed.', '2361810c-87fd-52ca-a64b-c09701614485'::uuid),
 ('pte', 'PTE is not listed among accepted tests.', '2361810c-87fd-52ca-a64b-c09701614485'::uuid)) v;
insert into cost_aid (institution_id, year, tuition_usd, required_fees_usd, room_board_usd, books_usd, other_usd, intl_aid_policy, intl_need_aid, intl_need_aid_awarded, intl_avg_award_usd, meets_full_need, merit_scholarships, notes, source_id) values
 ('1a8d45fd-0b47-5915-80c5-46f827e3ae42', '2026-2027', 50660, 1600, 11770, 500, 3628, 'merit_only', false, 40, 45317, false, true, 'CDS G1 for 2026-27 (first-year and all undergraduates): tuition 50,660; required fees 1,600; food and housing 11,770 (housing 5,890 + meals 5,880); books 500; residential transportation 1,080 not included in other. CDS H6: institutional non-need-based aid is available to nonresidents; 40 degree-seeking nonresident undergraduates received institutional aid, average 45,317 (total 1,812,685); H7 asks them only for an International Student''s Certification of Finances.; Bellarmine says 100% of incoming first-year students receive institutional gift aid; Scarlet Scholarships (tuition awards, priority date Feb 1) are based on the admission application with no separate application. The CDS shows 40 degree-seeking nonresident undergraduates received institutional aid averaging $45,317, and international aid is non-need-based. Need-based grants require the FAFSA. Bellarmine Scholars/Fellows need a separate scholarship application by Dec 1.', 'aa620220-245e-5471-99a7-93c540466b26');
