 ('712b116d-3f66-57dc-8e94-067fee77f0f4', '2023-2024', 3318, 3224, 402, 25, 100, 'Baseline from IPEDS (fall 2023 entering class): 3,318 applied, 3,224 admitted, 402 enrolled. No Common Data Set was found for Bethel (TN), so GPA and international applicant/admit counts are not available. SAT percentiles rest on only 101 submitters. Newer College Navigator figures (fall 2024) differ sharply: 1,486 applicants, about 60% admitted (rounded %), ACT 15/18/21, SAT ERW 410/460/570, SAT Math 420/460/550; 2,674 undergraduates (used for enrollment here). Test optional with weighted GPA 2.25 or above.', '9e72db97-d611-5254-9deb-3ceeaedab3da', 'admissions_site');
insert into test_score_percentiles (institution_id, cds_year, source_id, test, p25, p50, p75)
select '712b116d-3f66-57dc-8e94-067fee77f0f4'::uuid, '2023-2024', '9e72db97-d611-5254-9deb-3ceeaedab3da'::uuid, v.* from (values
 ('SAT_ERW', 300, 475, 525),
 ('SAT_MATH', 325, 500, 575),
 ('ACT_COMPOSITE', 16, 20, 24),
 ('ACT_ENGLISH', 16, 19, 24),
 ('ACT_MATH', 16, 20, 24)) v;
insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('712b116d-3f66-57dc-8e94-067fee77f0f4', '2026-27', 'optional', 'Test optional for applicants with a weighted GPA of 2.25 or above; applicants below 2.25 must submit ACT or SAT. Writing is not considered and tests are superscored.', '15081020-fd16-5e19-825b-607b459682ac');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('712b116d-3f66-57dc-8e94-067fee77f0f4', '2026-27', array['common_app','own']::text[], 30, 'Non-refundable $30 fee; apply on Bethel''s online application or the Common App. Official transcripts must come directly from the high school. The admissions pages are dated to the 2025-26 cycle (applications open Aug. 1, 2025), so dates for fall 2027 are assumed to repeat.', '15081020-fd16-5e19-825b-607b459682ac');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('36e15384-d31b-5f74-bca7-5c813b267ab7', '712b116d-3f66-57dc-8e94-067fee77f0f4', '2026-27', 'application', 'ROLLING', 'Application deadline, fall 2027 entry', '2027-07-31', 'Fall July 31, spring Dec. 15, summer May 15 (same dates on the international page). Printed for the 2025-26 cycle with no fall 2027 date, so this assumes the date repeats. The page also lists Dec. 1, 2025 as the ''Application Deadline for Top Scholarships''; the equivalent date for fall 2027 entry is not yet published.', '00fac932-9072-532b-b72f-dd39c3c844ec');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('712b116d-3f66-57dc-8e94-067fee77f0f4', 'required_nonnative', 'International page lists minimums for TOEFL (paper 513, computer-based 183, internet 65), iTEP 3.6, IELTS 5 overall with 5 in each area, and Duolingo 80 or above. PTE is not listed. If TOEFL is not available, the page describes a video and audio interview as an alternative. Conditional admission / ESL pathway is not described.', '00fac932-9072-532b-b72f-dd39c3c844ec');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, min_subscores, notes)
select '712b116d-3f66-57dc-8e94-067fee77f0f4'::uuid, 'required_option', '00fac932-9072-532b-b72f-dd39c3c844ec'::uuid, v.* from (values
 ('TOEFL_IBT', 65, null, 'Internet-based minimum 65 (paper 513, computer-based 183). No 1-6 scale minimum is given.'),
 ('IELTS', 5.0, '{"each_section": 5.0}'::jsonb, '5 overall with 5 in each exam area.'),
 ('DUOLINGO', 80, null, '80 or above.')) v;
insert into score_codes (institution_id, source_id, test_key, notes)
select '712b116d-3f66-57dc-8e94-067fee77f0f4'::uuid, '00fac932-9072-532b-b72f-dd39c3c844ec'::uuid, v.* from (values
 ('sat', 'No SAT code is printed on the admissions pages found.'),
 ('act', 'No ACT code is printed on the admissions pages found.'),
 ('toefl', 'No TOEFL institution code is printed on the admissions pages found.'),
 ('ielts', 'No institution code is listed.'),
 ('duolingo', 'No institution code is listed.'),
 ('pte', 'PTE is not listed on the international page.')) v;
insert into cost_aid (institution_id, year, tuition_usd, tuition_intl_usd, intl_extra_fees_usd, room_board_usd, total_coa_usd, merit_scholarships, notes, source_id) values
 ('712b116d-3f66-57dc-8e94-067fee77f0f4', '2026-2027', 20160, 20160, 2114, 11520, 31680, true, 'International in-person 2026-27: tuition for 12-18 hours $10,080 per semester ($20,160 per year); residence hall and meal plan $5,760 per semester ($11,520 per year; varies by hall and plan). Page estimate $31,680 per year excludes course fees and books (books $37 per credit hour, opt-out possible). Required international student insurance $2,114 per year. 2024-25 College Navigator listing was $18,712 tuition and fees.; The international tuition/aid page lists first-year academic merit awards of $4,000-$12,000 per year (Presidential $12,000, Trustee $10,000, Provost $8,000, Deans $6,000, Bethel Honor $4,000); a 3.0 cumulative GPA or ACT 20 (if submitted) is considered competitive. Hendrix Scholarship (full tuition/fees/room/meals or tuition/fees) needs 3.5 GPA or ACT 24/SAT 1190; its listed deadline was Dec. 1, 2025. Athletic and Renaissance (audition) scholarships also exist. Need-based aid for international students is not described. Awards cover fall and spring for up to ten semesters.', '6330442f-f337-58ed-b5f9-a27068bc715b');
insert into institution_tiers (institution_id, tier_code, category_key, rationale)
select '712b116d-3f66-57dc-8e94-067fee77f0f4'::uuid, 'D', v.* from (values
 ('general', 'Admit rate 97.2%'),
 ('nursing', 'Editorial judgment (v1, reviewed 2026-10-20)')) v;
insert into major_admissions (id, institution_id, program, category_key, admit_model, capped, notes) values
 ('8a122968-c8e9-54f4-8fd0-31384ff87cc8', '712b116d-3f66-57dc-8e94-067fee77f0f4', 'Nursing, Direct Entry B.S.N.', 'nursing', 'direct_major', false, 'First-year direct entry needs a 3.0 high school GPA or ACT 20 / SAT 1030. The page does not state enrollment caps or whether international students are eligible, so confirm with admissions.');

