insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('a4d5a870-eb91-5f1d-acd3-9f1963d4ade7', '2026-27', 'optional', 'Test-optional. Applicants must indicate on their application whether SAT/ACT scores should be included in the review. For international students, SAT/ACT can also serve as proof of English proficiency.', 'e9838afb-c723-5ef1-94d1-e11e508a3d3a');
insert into application_requirements (institution_id, cycle, platforms, teacher_recs, app_fee_usd, notes, source_id) values
 ('a4d5a870-eb91-5f1d-acd3-9f1963d4ade7', '2026-27', array['common_app','coalition','own']::text[], 1, 50, 'Common App, Coalition App or SUNY App. $50 fee; international students are not eligible for fee waivers, but the fee is free during ''Binghamton Free Application Weeks'' (Oct 19 to Nov 2, no code needed). One teacher OR counselor recommendation. Official transcripts for the most recent three years. Some programs (BFA, music, etc.) have their own deadlines and portfolio/audition requirements.', 'e9838afb-c723-5ef1-94d1-e11e508a3d3a');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notification_date, notes, source_id) values
 ('2048808e-1ceb-568b-83b7-2fe188ce0985', 'a4d5a870-eb91-5f1d-acd3-9f1963d4ade7', '2026-27', 'application', 'EA', 'International first-year early action', '2026-11-01', '2027-01-15', 'From the international priority-deadline table (late applications are reviewed on a space-available basis). The first-year page lists a materials deadline of Dec 1 for early action. The page is dated 7/6/26 and gives no year next to the date.', 'e9838afb-c723-5ef1-94d1-e11e508a3d3a'),
 ('bd60a9fc-e199-5145-aa04-9f5d5684a0db', 'a4d5a870-eb91-5f1d-acd3-9f1963d4ade7', '2026-27', 'application', 'RD', 'International first-year regular admission (priority)', '2027-03-15', '2027-04-01', 'International page gives March 15 with decisions ''by April 1''; the domestic first-year page lists regular admission on Jan 15. Late applications are reviewed on a space-available basis.', 'e9838afb-c723-5ef1-94d1-e11e508a3d3a');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('a4d5a870-eb91-5f1d-acd3-9f1963d4ade7', 'required_nonnative', 'All non-native-English-speaking international students must submit at least one English proficiency score, even if their school teaches in English or they are SAT/ACT test-optional. Students who attended four years of English-medium schooling may request a waiver at international@binghamton.edu. Scores must be under two years old and sent officially. Accepted: TOEFL iBT (incl. Home Edition), IELTS, Duolingo, PTE, Cambridge B2/C1/C2, SAT, ACT, IB HL, O-level English.', 'e9838afb-c723-5ef1-94d1-e11e508a3d3a');
insert into english_requirements (institution_id, status, source_id, test_key, recommended_total, notes)
