insert into cost_aid (institution_id, year, tuition_usd, tuition_out_of_state_usd, tuition_intl_usd, required_fees_usd, intl_extra_fees_usd, room_board_usd, books_usd, other_usd, total_coa_usd, intl_aid_policy, meets_full_need, merit_scholarships, notes, source_id) values
 ('a74f253c-0b62-54dc-b2e7-4e640be39963', '2026-2027', 8024, 11292, 11292, 1203, 400, 8438, 1000, 1422, 24227, 'merit_only', false, true, 'Intl page, undergraduate 2026-27: tuition $376.40/credit x 30 = $11,292; general activity fees $1,203; international student fee $400 ($200/semester); discipline fees about $472 (not split out); standard double room $4,338 plus standard meal plan $4,100; health insurance $1,422 (shown in other_usd); books $1,000; total $24,227, excluding $2,000-$5,000 personal spending per semester. SD resident tuition $8,024 from the Tuition & Fees page; that page''s financial-aid cost of attendance for a nonresident living on campus is $29,356 (includes miscellaneous and transportation).; F-1 students are eligible for the Global Ambassador Scholarship (competitive, international-only; free on-campus housing for up to eight semesters, estimated at about $14,000 over four years; chosen on essay, GPA, test scores and activities) and for Scholarships of Distinction (up to $4,000 per year based on unweighted GPA and/or ACT/SAT). International students are not eligible for federal aid.', '162d80e3-e3ef-57fb-82cb-91cc47a72983');
