insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, intl_applicants, intl_admits, in_state_applicants, in_state_admits, out_state_applicants, out_state_admits, pct_submit_sat, pct_submit_act, gpa_avg, pct_reporting_gpa, gpa_distribution, notes, source_id, source_note)
select '218cdcc6-8cc0-56b2-8ea0-231b57cd7372'::uuid, v.* from (values
 ('2025-2026', 17582, 14749, 3881, 67, 51, 9980, 7920, 7535, 6778, null, null, null, null, null, 'CDS C1 (fall 2025 first-time first-year): 17,582 applied, 14,749 admitted (83.9%), 3,881 enrolled; residency table in-state 9,980/7,920, out-of-state 7,535/6,778, international 67/51 (76% admitted). Only about 67 international first-year applicants per year, so the international sample is small. In the 2025-26 CDS file the C7 factor boxes, C8 policy boxes, C9-C12 test-score/GPA tables and the G tuition table are blank in the text layer, so test scores, GPA and factors are not taken from it. Undergraduate enrollment is B1 ''Total All Undergraduates'' (25,308 incl. part-time and non-degree); 155 nonresident undergraduates is the B2 total column. No early decision/action; student-to-faculty ratio 20:1 (CDS I-2). Boise State is not test-blind for internationals (see test policy) but domestic admission ignores SAT/ACT.', 'ea070dd5-38e5-5fcb-a80d-959749bece36'::uuid, null),
 ('2024-2025', 16082, 14025, 3379, 74, 56, 9420, 7957, 6588, 6012, 49, 5, 3.44, 99.8, '{"4.0": 5.0, "3.75-3.99": 26.6, "3.50-3.74": 21.7, "3.25-3.49": 17.2, "3.00-3.24": 15.2, "2.50-2.99": 12.9, "2.0-2.49": 0.7, "1.0-1.99": 0.0}'::jsonb, 'Fall 2024 first-year class from the 2024-25 CDS (the latest Boise State CDS whose GPA table is readable). C11 also lists 0.8% below 1.0 as printed, so the bands sum to about 100%. Residency: international 74 applied, 56 admitted, 13 enrolled. C9: 49% of enrollees submitted SAT (1,646) and 5% ACT (168); among submitters SAT composite 25th/75th percentile 960/1180, SAT ERW 490/610, ACT composite 20/26 (50th percentile and SAT math were not readable, so no score row is stored).', '9b756b6c-d0fe-54df-ad43-a7137d16746f'::uuid, 'admissions_site')) v;
insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('218cdcc6-8cc0-56b2-8ea0-231b57cd7372', '2026-27', 'optional', 'International students are not required to submit SAT or ACT; if sent they will be considered. Domestic (nonresident) admission uses cumulative unweighted high school GPA only and states test scores are not used. College Navigator (IPEDS) lists SAT/ACT as not considered (test blind). SAT EBRW 450 or ACT English 18 can also prove English proficiency.', 'c4f68ebb-ba2a-5a73-8700-c74468005abc');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, fee_waiver, notes, source_id) values
 ('218cdcc6-8cc0-56b2-8ea0-231b57cd7372', '2026-27', array['own']::text[], 85, false, 'Boise State does not accept the Common App; use the Boise State application. International first-year file: application, $85 non-refundable fee (no waivers for international students), high school transcripts or marksheets (unofficial accepted for review; official required later), proof of English proficiency, passport name page. Considered mainly on past academic achievement; no minimum GPA is published for international applicants (domestic nonresidents are automatically admitted at 3.00 unweighted). Recommendations and personal statement are optional. Decisions typically within two weeks of a complete file. Admitted F-1 applicants must send a Financial Documentation Form and proof of funds.', 'c4f68ebb-ba2a-5a73-8700-c74468005abc');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('98e40e24-a87c-5c5a-bf2e-f440216e65b3', '218cdcc6-8cc0-56b2-8ea0-231b57cd7372', '2026-27', 'scholarship', null, 'Merit scholarship deadline (fall 2027 entry)', '2026-12-15', 'All admission materials (application, fee, English scores, transcripts, passport copy) must be received by this date for automatic merit scholarship consideration. The International Admissions home page also shows a Global Scholarships deadline of March 1 but under outdated ''Fall 2025'' labels; the scholarships page lists Dec. 15, 2026 for fall 2027.', '556c9677-c560-5fa9-912d-c6ab1d95b69b'),
 ('10e8a8eb-a81d-593d-9efe-86dffa3df25a', '218cdcc6-8cc0-56b2-8ea0-231b57cd7372', '2026-27', 'priority', 'ROLLING', 'Priority application deadline (fall 2027 entry)', '2027-04-01', 'Fall priority date from the international first-year page (printed without a year; treated as fall 2027). No later final international deadline is published; decisions are rolling. Spring 2027: Oct. 1, 2026 for both priority and scholarships.', 'c4f68ebb-ba2a-5a73-8700-c74468005abc');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('218cdcc6-8cc0-56b2-8ea0-231b57cd7372', 'required_nonnative', 'Exempt with 3 or more years of secondary education in English-medium schools in an approved country list (e.g. US, UK, Ireland, Canada excl. Quebec, Australia, New Zealand, South Africa, Nigeria, Ghana, Kenya, Jamaica). Other accepted proof: ACT English 18, SAT EBRW 450, AP English Language or Literature 3, IB English A 4 (completed IB Diploma within 2 years), IGCSE/O Level English C, WASSCE B3 and others. The office may ask for more proof case by case. Applicants below the minimums are considered for the Pathway Program: Accelerated 1 semester (IELTS 5.5, TOEFL 62-67, Duolingo 86-99), Standard 2 semesters (IELTS 5.0, TOEFL 45-61, Duolingo 75-85), Extended 3 semesters (IELTS 4.5, TOEFL 38-44, Duolingo 65-74); on completion students are fully admitted to their degree program, tuition is the nonresident rate less about a 30% scholarship, and Pathway students are not eligible for merit scholarships.', 'c4f68ebb-ba2a-5a73-8700-c74468005abc');
insert into english_requirements (institution_id, source_id, test_key, status, min_total, notes)
