insert into cost_aid (institution_id, year, tuition_intl_usd, room_board_usd, books_usd, other_usd, total_coa_usd, intl_aid_policy, meets_full_need, merit_scholarships, notes, source_id) values
 ('218cdcc6-8cc0-56b2-8ea0-231b57cd7372', '2026-2027', 29477, 16894, 800, 4378, 51549, 'merit_only', false, true, 'International undergraduate estimate for 2026-27 from Boise State International Admissions: tuition and fees $29,477 (published as one figure), room and board $16,894, books $800, health insurance $2,175 and personal $2,203 (other_usd = 2,175 + 2,203), total $51,549. Pathway Program total is $38,427. Idaho resident tuition does not apply to international students.; International undergraduates are automatically considered for merit scholarships of $5,000 to $17,000 per year if materials are complete by the deadline: Non-Resident scholarship ($5,000 at 3.10-3.29 cumulative unweighted GPA, $10,000 at 3.30+; the Financial Aid Office page names these Ridgeline and Summit with slightly different GPA bands) plus a Global Scholarship for international students only ($5,000 at 3.50-3.749, $6,000 at 3.75-3.999, $7,000 at 4.00+), capped at $17,000 total. Global awards depend on availability. First-year awards are renewable for up to four years (eight semesters). Not available for Nursing, Pre-Nursing, Construction Management, Radiological Science, online or self-supported programs, and not for Pathway students. No fully funded scholarships. Need-based aid for international students is not described.', 'e3544484-6904-5c02-ada8-fc1f1243dbe7');
