insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('04cf3b47-2569-5e90-88bc-892d892aec23', 'not_required', 'Submitting an English proficiency test is optional and there is no minimum score; scores cannot be deleted once submitted. Accepted: TOEFL, IELTS, Duolingo English Test, Cambridge English. Bowdoin offers no ESL courses, so students are expected to be highly proficient in English.', '3e0474d9-0140-5b52-b913-bb87a9a6300a');
