insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('abb7ef91-4abf-56c8-8c33-5e2c1d215274', '2026-27', 'optional', 'SAT/ACT are not required for admission. International applicants must submit one of them only to be considered for merit scholarships (SAT composite of verbal and math, or ACT composite with a competitive English band score).', 'd0585955-de24-53ba-ac96-c50e94274576');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, fee_waiver, notes, source_id) values
 ('abb7ef91-4abf-56c8-8c33-5e2c1d215274', '2026-27', array['own']::text[], 75, false, 'International application fee $75, no fee waivers. Requires official secondary transcripts (and any college transcripts) and proof of English; no essays or recommendation letters. Minimum cumulative high school GPA 2.5 on a 4.0 scale. College Navigator lists a $45 undergraduate fee for 2024-25; the international page says $75.', 'cb4c459c-475b-5a35-9c9c-2d7a86be88b1');
