insert into cost_aid (institution_id, year, tuition_usd, room_board_usd, books_usd, other_usd, total_coa_usd, intl_aid_policy, intl_need_aid, merit_scholarships, notes, source_id) values
 ('af0bdaaa-8391-58d4-9cf4-3aef2df3ad94', '2023-2024', 70957, 20954, 1000, 1200, 90169, 'need_aware_limited', true, true, 'College Scorecard (IPEDS 2023-24): tuition includes required fees; on-campus cost of attendance.; Brandeis scholarships for international students are based on academic and personal records and are need-sensitive; competition is strong. Scholarship funds are generally awarded only at admission, and international students must reapply for aid each year with the CSS Profile (school code 3092). The Wien International Scholarship meets the full demonstrated need of each recipient; there is no separate application. Whether Brandeis meets full need for all international admits is not stated.', '4352a201-b84c-5ff3-91c6-cfdb6ba98630');
insert into institution_tiers (institution_id, category_key, tier_code, rationale)
