insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, intl_applicants, intl_admits, in_state_applicants, in_state_admits, out_state_applicants, out_state_admits, gpa_avg, pct_reporting_gpa, gpa_distribution, notes, source_id) values
 ('25beb90f-00ad-5604-80e5-6bb7620f3e23', '2025-2026', 14532, 12230, 1366, 537, 199, 12907, 11189, 1088, 842, 3.44, 100.0, '{"4.0": 15.7, "3.75-3.99": 14.3, "3.50-3.74": 19.1, "3.25-3.49": 15.3, "3.00-3.24": 16.8, "2.50-2.99": 16.8, "2.0-2.49": 1.8, "1.0-1.99": 0.2}'::jsonb, 'CDS C1 fall 2025 first-year class: 14,532 applied, 12,230 admitted (84%), 1,366 enrolled. Residency split as printed: international 537 applicants and 199 admitted (about 37%), versus 12,907 in-state applicants and 11,189 admitted; the international admit rate is much lower than the domestic one. Only 15 international first-years enrolled. intl_undergrads is the CDS B2 count of degree-seeking nonresident undergraduates (100); undergrad_enrollment is the CDS B total of all undergraduates (9,897). SAT/ACT: CSU campuses are test-blind (CDS C8A answers No); the C9 score tables cover only a few dozen enrolled students and the C7 factor check boxes could not be read reliably, so scores and factors are omitted. College Navigator (fall 2024) shows 13,229 applicants and 94% admitted.', '151d7ee7-20e2-56aa-a2dd-610a8582206c');
insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('25beb90f-00ad-5604-80e5-6bb7620f3e23', '2026-27', 'blind', 'CSUB''s CDS (C8A) answers No to using SAT/ACT in admission decisions, and College Navigator (IPEDS fall 2024) lists SAT/ACT as ''Not considered (Test Blind)''. The international admission page lists an SAT EBRW score of 550 only as one way to show English proficiency. Eligibility for international freshmen is a 2.5 overall GPA.', '151d7ee7-20e2-56aa-a2dd-610a8582206c');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('25beb90f-00ad-5604-80e5-6bb7620f3e23', '2026-27', array['own']::text[], 70, 'Apply through Cal State Apply (not the Common App); $70 fee paid online by credit card. Minimum 2.5 overall GPA for freshmen. Needed: Affidavit of Financial Support, international student health insurance agreement, bank statements in English dated within 6 months showing at least $38,956 in liquid funds, official transcripts in English with proof of graduation (non-U.S. transcripts need a course-by-course evaluation from a NACES member such as WES), and a passport copy. The CDS shows essays and recommendations are not considered.', 'f3c2aeae-f6c7-521d-90da-648c19e4d804');
insert into deadlines (id, institution_id, cycle, kind, label, due_date, notes, source_id) values
 ('30a2ba3e-6bdc-5723-be78-3ae8b041db60', '25beb90f-00ad-5604-80e5-6bb7620f3e23', '2026-27', 'application', 'Undergraduate international application and document submission deadline (fall 2027)', '2027-06-01', 'Applications for fall 2027 open Aug 1, 2026. The dates page lists a single ''Undergraduate International Application and document submission deadline'' of June 1, 2027 (the page does not split freshman and transfer); the spring 2027 equivalent is Sept 28, 2026. Domestic first-year dates are earlier and do not apply to international applicants.', '88d81a2a-e418-5b7e-804d-827ffc78a571');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('25beb90f-00ad-5604-80e5-6bb7620f3e23', 'required_nonnative', 'CSUB may waive the test for citizens of listed countries (for example Australia, Canada except Quebec, England, Ireland, Scotland, Wales, New Zealand, Singapore, Nigeria and others on the page). Other ways to meet it: SAT Evidence-Based Reading and Writing 550 or higher, or a college English course with a C or better (online English courses not accepted).', 'f3c2aeae-f6c7-521d-90da-648c19e4d804');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, min_subscores, notes)
select '25beb90f-00ad-5604-80e5-6bb7620f3e23'::uuid, 'required_option', 'f3c2aeae-f6c7-521d-90da-648c19e4d804'::uuid, v.* from (values
 ('TOEFL_IBT', 61, null, 'Page text: ''Score of 3.5 or 61 iBT required.'' Send scores to school code 4110.'),
 ('TOEFL_IBT_2026', 3.5, null, 'From the same line (''3.5 or 61 iBT''); the page does not name the 1-6 scale.'),
 ('IELTS', 5.5, '{"each_section": 5.5}'::jsonb, 'Overall 5.5 with at least 5.5 in each section.'),
 ('DUOLINGO', 95, null, 'Duolingo English Test minimum score of 95.'),
 ('PTE', 43, null, 'Pearson Test of English Academic, minimum 43. The page does not list Cambridge.')) v;
insert into score_codes (institution_id, test_key, code, notes, source_id) values
 ('25beb90f-00ad-5604-80e5-6bb7620f3e23', 'toefl', '4110', 'CSUB school code for TOEFL results.', 'f3c2aeae-f6c7-521d-90da-648c19e4d804');
insert into cost_aid (institution_id, year, tuition_usd, tuition_out_of_state_usd, tuition_intl_usd, required_fees_usd, meets_full_need, notes, source_id) values
 ('25beb90f-00ad-5604-80e5-6bb7620f3e23', '2026-2027', 6838, 20968, 20968, 2104, false, 'Computed from Fall 2026 published rates: tuition $3,419 per semester (6.1+ units) twice, plus the nonresident charge of $471 per unit for an assumed 30 units a year ($14,130). Required fees $1,052 per semester twice (ASB 249, Health Facility 3, Health Service 207.75, IRA 91.25, RunnerPass 6, Student Body 468, Campus Programming 25, Student Involvement 2). Housing, food, books and insurance not added because no international budget was found; spring 2027 fees were assumed equal to fall 2026.; The CSUB international undergraduate pages checked list no scholarships or financial aid for international applicants (scholarships are mentioned only as sponsor types for financial documents). No conditional-admission or ESL pathway is described on these pages; confirm with CSUB International Student Programs.', 'f34125fa-640d-5fd7-a56e-1c7b90102436');
