insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, notes, source_id, source_note) values
 ('1140af00-e2b0-58f7-b9c7-65135fc894f9', '2024-2025', 19921, 18586, 1732, 'Baseline from IPEDS fall 2024 (ADM2024): 19,921 applicants, 18,586 admitted (93%), 1,732 enrolled (1,627 full-time plus 105 part-time). CSUDH''s newest Common Data Set on its site is 2022-2023, too old to use, so GPA, residency and international splits are not added. CSU campuses are test-blind (College Navigator lists SAT/ACT as ''Not considered (Test Blind)''), so there are no score ranges. undergrad_enrollment is the College Navigator fall 2024 undergraduate count.', 'ee06fc75-0d99-5225-9db8-bbecd009d146', 'admissions_site');
insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('1140af00-e2b0-58f7-b9c7-65135fc894f9', '2026-27', 'blind', 'College Navigator (IPEDS fall 2024 admissions) lists SAT/ACT as ''Not considered (Test Blind)'' and the CSU system does not use SAT/ACT in admission decisions. SAT EBRW 550 or ACT English 22 only count as ways to show English proficiency. CSUDH''s international pages list no minimum GPA.', 'f4b2c80e-793c-59f3-b410-d012b8019cde');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('1140af00-e2b0-58f7-b9c7-65135fc894f9', '2026-27', array['own']::text[], 70, 'Apply through Cal State Apply (not the Common App); $70 non-refundable fee. Freshmen send photocopies of all upper secondary and external exam results (certified English translations if not issued in English), English proficiency proof, financial certification of $38,292 for the first year (the page gives no year), an Affidavit of Financial Support if sponsored, and an Educational History form for gaps of a year or more. Unofficial photocopies are enough for review; official records are required if admitted. No minimum GPA is stated on the international pages. College Navigator shows essays and recommendations are not considered.', '8c02ea5d-16ca-5203-a35a-bb02aa57a6c1');
insert into deadlines (id, institution_id, cycle, kind, label, due_date, notes, source_id) values
 ('d9af0648-57b4-5b24-8eef-1ccd57182060', '1140af00-e2b0-58f7-b9c7-65135fc894f9', '2026-27', 'application', 'International undergraduate application deadline, fall (Cal State Apply)', '2027-05-01', 'The checklist page gives Fall = May 1 with no year, and labels Fall 2026 as Oct 1, 2025 to May 1, 2026; treated as May 1, 2027 for fall 2027 (inferred, not printed). Applicants abroad are urged to submit documents by May 1.', '38c0017a-57c8-5d35-9f4a-4d1d06547e2c'),
 ('3983a892-bbaa-57e3-8c9a-403be4a54079', '1140af00-e2b0-58f7-b9c7-65135fc894f9', '2026-27', 'other', 'International undergraduate document deadline, fall', '2027-06-01', 'Page gives ''Fall = June 1'' without a year; treated as 2027. The domestic first-year page lists June 30, 2027 as its Fall 2027 document deadline, which is a different date.', '38c0017a-57c8-5d35-9f4a-4d1d06547e2c');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('1140af00-e2b0-58f7-b9c7-65135fc894f9', 'required_nonnative', 'Not required after at least three full-time years of secondary school or higher education in the U.S. or in a listed country where English is the sole language of instruction. Conditional admission through the American Language and Culture Program (ALCP) leads to an English proficiency waiver for the next available term. Test scores are valid for two years.', 'f0481805-f527-5da5-a760-7370db37c0eb');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
select '1140af00-e2b0-58f7-b9c7-65135fc894f9'::uuid, 'required_option', 'f0481805-f527-5da5-a760-7370db37c0eb'::uuid, v.* from (values
 ('TOEFL_IBT', 61, 'TOEFL iBT 61. The page does not give a new-scale (1-6) minimum. TOEFL institution code 4098.'),
 ('IELTS', 5.5, 'IELTS 5.5; the page gives no sub-score minimums.'),
 ('DUOLINGO', 95, 'Duolingo English Test 95.'),
 ('PTE', 44, 'Pearson Test of English Academic 44. Cambridge is not listed. Other accepted evidence: SAT EBRW 550, ACT English 22, AP English Language or Literature 3, IB English HL 4, or a GE English Composition course with C-.')) v;
insert into score_codes (institution_id, test_key, code, notes, source_id) values
 ('1140af00-e2b0-58f7-b9c7-65135fc894f9', 'toefl', '4098', 'CSUDH institution code for TOEFL results.', 'f0481805-f527-5da5-a760-7370db37c0eb');
insert into cost_aid (institution_id, year, tuition_usd, tuition_out_of_state_usd, tuition_intl_usd, required_fees_usd, intl_aid_policy, intl_need_aid, meets_full_need, merit_scholarships, notes, source_id) values
 ('1140af00-e2b0-58f7-b9c7-65135fc894f9', '2026-2027', 6838, 20968, 20968, 1868, 'none', false, false, false, 'Computed from the official 2026-27 fee schedule: undergraduate tuition $3,419 per semester (6.1+ units) twice, plus the nonresident charge of $471 per unit for an assumed 30 units a year ($14,130). Required fees: $936.36 in fall and $931.36 in spring ($1,867.72, rounded). CSUDH''s own international budget on the Financial Certification page totals $38,292 but uses an older $396 per unit nonresident rate and states no year, so it is not used.; The Financial Certification page states there are no scholarships or financial aid available at CSUDH to international students; limited on-campus work only. Conditional admission through ALCP (American Language and Culture Program) is for applicants who meet all other requirements but not the English score; ALCP charges a $55 fee to CSUDH plus a $150 CSUDH Foundation fee, the page does not guarantee admission, and program tuition is not stated.', '5eb11bef-8c69-515e-aa3f-c57b275fbfab');
insert into institution_tiers (institution_id, tier_code, category_key, rationale)
select '1140af00-e2b0-58f7-b9c7-65135fc894f9'::uuid, 'D', v.* from (values
 ('general', 'Admit rate 93.3%'),
 ('computer_science', 'Editorial judgment (v1, reviewed 2026-10-20)'),
 ('business', 'Editorial judgment (v1, reviewed 2026-10-20)'),
 ('biology_life_sci', 'Editorial judgment (v1, reviewed 2026-10-20)'),
 ('math_physics', 'Editorial judgment (v1, reviewed 2026-10-20)'),
 ('humanities', 'Editorial judgment (v1, reviewed 2026-10-20)'),
 ('arts_design', 'Editorial judgment (v1, reviewed 2026-10-20)'),
 ('nursing', 'Editorial judgment (v1, reviewed 2026-10-20)')) v;

