insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, notes, source_id, source_note) values
 ('e93c81fd-f3e5-5f3c-9ed7-e7df4f9f7488', '2023-2024', 13274, 12851, 994, 'Baseline from IPEDS (fall 2023 first-time, first-year class: 13,274 applicants, 12,851 admitted, 994 enrolled). College Navigator also shows fall 2024: 11,867 applicants, 97% admitted, 7% of admitted students enrolled (rounded percentages; no counts given). No public Common Data Set was found on csueastbay.edu (the Institutional Effectiveness & Research office publishes dashboards instead), so applications by residency (international applicants and admits), GPA and score ranges are not available and are left null. Undergraduate enrollment is the fall 2024 College Navigator figure (9,909); international undergraduate headcount is not published there (only 4% of first-time students came from foreign countries in fall 2023), so intl_undergrads is null. CSU campuses are test-blind, so no SAT/ACT percentiles.', '70917f3e-63a7-5479-a103-85cdf6e680bd', 'admissions_site');
insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('e93c81fd-f3e5-5f3c-9ed7-e7df4f9f7488', '2026-27', 'blind', 'College Navigator (IPEDS fall 2024 admissions) lists SAT/ACT as ''Not considered (Test Blind)'', and the international freshman page says SAT/ACT are not required for admission. Scores are optional and are used only for English/Math placement, as an alternative proof of English (SAT 550 Verbal or ACT 22 English), and for the Global Excellence Scholarship. Eligibility for non-U.S. high school graduates is a 3.0 GPA.', '4926632d-b6c2-51a5-adf8-f871956ae74d');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('e93c81fd-f3e5-5f3c-9ed7-e7df4f9f7488', '2026-27', array['own']::text[], 70, 'Apply through Cal State Apply (not the Common App) and pay the $70 non-refundable fee. Needs a 3.0 GPA for applicants who graduated outside the U.S.; A-G coursework is not required for them. College Navigator shows the secondary school GPA, record and college-prep program are required while essays and recommendations are not considered. Documents: transcripts, proof of English proficiency, and financial documents (official bank statement or letter showing at least one year of expenses) for the I-20.', '4926632d-b6c2-51a5-adf8-f871956ae74d');
insert into deadlines (id, institution_id, cycle, kind, label, due_date, notes, source_id) values
 ('029eba1c-ba38-52f5-8b3b-5426bc7408b1', 'e93c81fd-f3e5-5f3c-9ed7-e7df4f9f7488', '2026-27', 'application', 'International first-year application deadline, Cal State Apply (fall 2027)', '2027-05-31', 'Filing opens Oct 1, 2026. The page prints ''May 31'' without a year and its landing page says fall 2027 applications are open, so it is treated as May 31, 2027. The office strongly encourages applying early because visa processing can take weeks after the I-20 is issued; some academic programs may have earlier deadlines.', '6dda78fc-3f40-5904-a35a-b26053231229'),
 ('5613453d-1953-5249-940c-3a657cf56ddf', 'e93c81fd-f3e5-5f3c-9ed7-e7df4f9f7488', '2026-27', 'other', 'International Admissions document deadline (fall applicants)', '2027-06-15', 'The page prints ''June 15'' without a year; treated as 2027. Official documents must be submitted before registering for classes.', '6dda78fc-3f40-5904-a35a-b26053231229');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('e93c81fd-f3e5-5f3c-9ed7-e7df4f9f7488', 'required_nonnative', 'Waived for applicants educated in countries the school lists as having official English-medium instruction (for example the United States, United Kingdom, Ireland, Canada except Quebec, Australia, New Zealand, South Africa, Ghana, Fiji, Jamaica; Singapore and India are not on the list). Scores are valid for two years. IELTS General Training, IELTS One Skill Retake, TOEFL Essentials and TOEFL My Best Score are not accepted. Other accepted proofs: Michigan English Test 51, DAAD B2, CBSE Year 12 English A2 84, SAT 550 Verbal, AP English 3, ACT 22 English, IB English A 6 SL / 5 HL. Applicants who are academically qualified but below the English minimum can get conditional admission and attend the Global Academy Intensive English Program.', '58cc720b-a8c8-5c61-bf23-f06c748be909');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
select 'e93c81fd-f3e5-5f3c-9ed7-e7df4f9f7488'::uuid, 'required_option', '58cc720b-a8c8-5c61-bf23-f06c748be909'::uuid, v.* from (values
 ('TOEFL_IBT', 61, 'Exams taken before Jan 21, 2026 (0-120 scale); Home Edition accepted. Graduate minimum is 80.'),
 ('TOEFL_IBT_2026', 3.5, 'Exams taken on or after Jan 21, 2026; the page lists 3.5 for undergraduates and 4.0 for graduates without naming the scale (assumed to be the new 1-6 band scale).'),
 ('IELTS', 6.0, 'IELTS Academic overall 6 for undergraduates (6.5 graduate).'),
 ('DUOLINGO', 95, 'Graduate minimum is 105.'),
 ('PTE', 44, 'PTE Academic; graduate minimum is 58.')) v;
insert into cost_aid (institution_id, year, tuition_intl_usd, room_board_usd, other_usd, total_coa_usd, intl_aid_policy, meets_full_need, merit_scholarships, merit_separate_app, notes, source_id) values
 ('e93c81fd-f3e5-5f3c-9ed7-e7df4f9f7488', '2026-2027', 24496, 18509, 1500, 44505, 'merit_only', false, true, true, 'From the school''s non-resident estimate for students beginning Spring 2027 (15 units per semester): tuition and fees $24,496 combined (stored as tuition_intl_usd; the page does not split fees out), health insurance $1,500 (stored in other_usd), living expenses $18,509 (stored in room_board_usd), total I-20 amount $44,505. Dependents need $5,000 extra per spouse and per child.; Global Scholarships (separate application in the Pioneer Scholarships Portal after submitting Cal State Apply): Global Excellence Scholarship is a limited number of full non-resident tuition waivers (over $14,000 per year), renewable up to four years, for freshmen with a 3.3+ GPA; Global Honors Scholarship is a limited number of one-year awards of $2,900+. Both ask applicants to demonstrate financial need and enroll in 15 units a semester; awards are competitive and not guaranteed. International students may apply only for merit-based awards in the general Pioneer Scholarships Portal (most $300 to $3,000). Conditional admission with the Global Academy Intensive English Program is available for students below the English minimum.', 'f3c4eecb-1db7-5631-8df7-31ada15ddf78');
insert into institution_tiers (institution_id, tier_code, category_key, rationale)
select 'e93c81fd-f3e5-5f3c-9ed7-e7df4f9f7488'::uuid, 'D', v.* from (values
 ('general', 'Admit rate 96.8%'),
 ('computer_science', 'Editorial judgment (v1, reviewed 2026-10-20)'),
 ('engineering', 'Editorial judgment (v1, reviewed 2026-10-20)'),
 ('business', 'Editorial judgment (v1, reviewed 2026-10-20)'),
 ('biology_life_sci', 'Editorial judgment (v1, reviewed 2026-10-20)'),
 ('economics', 'Editorial judgment (v1, reviewed 2026-10-20)'),
 ('math_physics', 'Editorial judgment (v1, reviewed 2026-10-20)'),
 ('humanities', 'Editorial judgment (v1, reviewed 2026-10-20)')) v;

