insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('bbfc906e-fab3-5038-b302-d0c4299fa697', '2026-27', 'blind', 'College Navigator (IPEDS fall 2024 admissions) lists SAT/ACT as ''Not considered (Test Blind)'', as for the rest of the CSU. CSUSB''s own CDS C7/C8 form fields conflict with that (see the stats notes), so the CSU-wide policy is used. A first-year international applicant may use an SAT English score of 550+ or an ACT English score of 22+ as proof of English only. Eligibility for foreign high school graduates is a 2.5 overall GPA.', '3aa7303c-4875-55f2-ad3d-b3131853e7c0');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('bbfc906e-fab3-5038-b302-d0c4299fa697', '2026-27', array['own']::text[], 70, 'Apply through CSUApply / Cal State Apply (not the Common App); the $70 fee is non-refundable and international students are not eligible for a fee waiver (Admission FAQs). Needs a 2.5 overall GPA. Foreign high school applicants send official transcripts and diploma sealed in an envelope by the school, with certified English translations; also a passport copy and a statement of financial responsibility (bank statement / affidavit of support) plus proof of medical insurance. CDS C7: essays, recommendations and interviews are not considered.', '74d88507-a781-53c4-b0d1-997d57242ddd');
insert into deadlines (id, institution_id, cycle, kind, label, due_date, notes, source_id) values
 ('8c707fdd-18dc-54fd-829d-3be272db47b1', 'bbfc906e-fab3-5038-b302-d0c4299fa697', '2026-27', 'application', 'International undergraduate application deadline, Cal State Apply (fall 2027)', '2027-06-01', 'Application opens Aug 1, 2026 for fall 2027. CSUSB''s CDS also lists a Nov 30 priority date for first-year applicants, which is the domestic date; the international page gives June 1, 2027. Some programs may have different deadlines.', '795899aa-d3b7-516c-a759-a890627ed431'),
 ('df4f53cf-7480-5b39-b7c2-404142370a38', 'bbfc906e-fab3-5038-b302-d0c4299fa697', '2026-27', 'other', 'International document deadline (fall 2027)', '2027-06-30', 'Undergraduate and graduate document deadline for fall 2027.', '795899aa-d3b7-516c-a759-a890627ed431');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('bbfc906e-fab3-5038-b302-d0c4299fa697', 'required_nonnative', 'Exempt if a first-time freshman attended a high school in the U.S. for 3+ years or a high school where English is the principal language of instruction for 3+ years (listed countries include Antigua and Barbuda, Australia, Bahamas, Canada except Quebec/northern New Brunswick/Nunavut, Ireland, Jamaica, Kenya, Nigeria, New Zealand, South Africa, the United Kingdom and the United States). Scores must be valid within two years; TOEFL ITP is not accepted. Other accepted proofs for freshmen: iTEP 3.7, EIKEN Pre-1 (CSE 2304-3000), SAT English 550+, ACT English 22+, or completing Level 3 of CSUSB''s English Language Program. Conditional admission lets academically qualified applicants below the English minimum enter the English Language Program first.', '74d88507-a781-53c4-b0d1-997d57242ddd');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
select 'bbfc906e-fab3-5038-b302-d0c4299fa697'::uuid, 'required_option', '74d88507-a781-53c4-b0d1-997d57242ddd'::uuid, v.* from (values
 ('TOEFL_IBT', 61, 'Exams taken before Jan 21, 2026 (0-120 scale); Home Edition accepted. Graduate minimum 79.'),
 ('TOEFL_IBT_2026', 3.5, 'Exams taken on or after Jan 21, 2026; the page lists 3.5 for undergraduates, 4 for graduates and 5 for post-graduate programs without naming the scale (assumed to be the new 1-6 band scale).'),
 ('IELTS', 5.5, 'IELTS Academic overall; submit through the Cal State Apply e-delivery account. Graduate minimum 6.0.'),
 ('DUOLINGO', 95, 'Send online through your Duolingo account. Graduate minimum 105.'),
 ('PTE', 43, 'PTE Academic; send online through your PTE account. Graduate minimum 53.'),
 ('CAMBRIDGE', 168, 'Cambridge B2 First score of 168 for undergraduates (C1 Advanced 180 for graduates).')) v;
insert into score_codes (institution_id, test_key, code, notes, source_id) values
 ('bbfc906e-fab3-5038-b302-d0c4299fa697', 'toefl', '4099', 'CSUSB school code for TOEFL results.', '74d88507-a781-53c4-b0d1-997d57242ddd');
insert into cost_aid (institution_id, year, tuition_intl_usd, room_board_usd, books_usd, other_usd, total_coa_usd, intl_need_aid_awarded, meets_full_need, notes, source_id) values
 ('bbfc906e-fab3-5038-b302-d0c4299fa697', '2026-2027', 20359, 19786, 880, 9276, 50301, 0, false, 'From CSUSB''s 2026-27 suggested international budget (undergraduate, 24 units): tuition and fees $20,359 combined, including the $471 per unit non-resident charge (stored as tuition_intl_usd; the page does not split fees out); living expenses $19,786 (stored in room_board_usd), books and supplies $880, and other = transportation $2,906 plus health insurance $1,956 plus personal $4,414. Total $50,301. Dependents need $6,000 each per academic year.; CDS H6 reports no institutional aid awarded to degree-seeking nonresident undergraduates (0 recipients). The CDS tuition fields were not used; costs come from CSUSB''s international tuition-and-fees page.; The CSUSB catalog says scholarship aid for entering students is limited and none are specifically reserved for students from another country; no international merit scholarship or tuition waiver was found for undergraduates. The CDS (H6) reports no institutional aid recipients among degree-seeking nonresident undergraduates. Conditional admission is offered: students who are academically qualified but below the English minimum attend the CSUSB English Language Program (Level 3 for undergraduates, with an accelerated one-semester Level 3 option) before starting their degree; this needs two applications (one to the International Extension Program and one through Cal State Apply).', '1a3c2c2b-b5cc-5399-8f7f-707ff26078b4');
