insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, intl_applicants, intl_admits, in_state_applicants, in_state_admits, out_state_applicants, out_state_admits, pct_submit_sat, pct_submit_act, gpa_avg, pct_reporting_gpa, gpa_distribution, notes, source_id) values
 ('6c3e8639-f65c-565d-becf-9cf682d65265', '2025-2026', 20881, 19864, 2705, 173, 162, 19682, 18757, 986, 924, 2.3, 0.4, 3.316, 99.67, '{"4.0": 6.63, "3.75-3.99": 13.53, "3.50-3.74": 16.64, "3.25-3.49": 19.64, "3.00-3.24": 17.94, "2.50-2.99": 21.98, "2.0-2.49": 3.96, "1.0-1.99": 0.0}'::jsonb, 'CDS C1 fall 2025 first-year class: 20,881 applied, 19,864 admitted (95%), 2,705 enrolled (full-time plus part-time). Residency split as printed: international 173 applicants and 162 admitted (about 94%); 40 applicants (21 admitted) have unknown residency. The C11 GPA column for all enrolled students sums to 100.32% as printed. CSU campuses are test-blind; only 2.3% (SAT, 64 students) and 0.4% (ACT, 13 students) of enrollees had scores, so the SAT/ACT percentiles in C9 are omitted. intl_undergrads is the CDS B2 count of degree-seeking nonresident undergraduates (148); undergrad_enrollment is the CDS B total of all undergraduates (15,770). College Navigator (fall 2024) shows 19,721 applicants and 95% admitted.', '043c64cb-cc6c-5bcb-aa4d-56b3c48ad2c2');
insert into admission_factors (institution_id, cds_year, source_id, factor, importance)
