insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('6c3e8639-f65c-565d-becf-9cf682d65265', '2026-27', 'blind', 'CSUSM''s CDS (C8A) answers No to using SAT/ACT in admission decisions, and the CSU system is test-blind; only 64 SAT and 13 ACT submitters among 2,705 enrolled first-years. The international freshman page says SAT or ACT is ''recommended but not required''; treat them as not used for admission. Eligibility for international freshmen is the equivalent of a C+ (2.5) GPA, 2.0 for conditional admission.', '043c64cb-cc6c-5bcb-aa4d-56b3c48ad2c2');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('6c3e8639-f65c-565d-becf-9cf682d65265', '2026-27', array['own']::text[], 70, 'Apply through CSUSM International Admissions (online application, or a paper application if the online one is difficult); the CDS lists a $70 application fee (the international page does not state one). Needed: official transcripts with certified English translation (copies accepted for the decision), passport copy, Affidavit of Financial Support with a bank statement dated within 6 months, and English proficiency proof. CDS C7: GPA is very important; essay, recommendations, interview and test scores are not considered.', '7aa8fbc8-294e-57f7-9f4b-d6e2f848195b');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('2f2df231-1106-549b-9621-d23bb6c2968f', '6c3e8639-f65c-565d-becf-9cf682d65265', '2026-27', 'application', 'ROLLING', 'International first-year application deadline, out-of-country applicants (fall 2027)', '2027-06-01', 'Fall 2027 applications open Oct. 1, 2026 and close June 1, 2027 for applicants outside the U.S.; applicants already in the U.S. must contact International Admissions for their deadline. Decisions are made on a continuing basis once all records are received; classes start Aug. 30, 2027.', 'da39e2b1-7be6-5dff-a8a4-135322d0aaa6'),
 ('89693876-88d2-50c7-b3e8-d207fc1e3223', '6c3e8639-f65c-565d-becf-9cf682d65265', '2026-27', 'other', null, 'Final document deadline (fall 2027)', '2027-07-15', 'Final academic records with all term grades and proof of graduation. Official transcripts and test scores must arrive before an I-20 is issued; in-progress records are enough for an admission decision.', 'da39e2b1-7be6-5dff-a8a4-135322d0aaa6');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('6c3e8639-f65c-565d-becf-9cf682d65265', 'required_nonnative', 'Freshmen may instead show 3 years at a high school where English was the principal language of instruction (confirm eligibility with International Admissions). Guaranteed conditional admission is available through the American Language and Culture Institute if there is no passing score.', 'a3ef2ebb-b21e-5672-ab73-b65d05bfe2e3');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, min_subscores, notes)
