 ('TOEFL_IBT', 61, '{"writing": 19, "each_section": 14}'::jsonb, 'Writing no lower than 19 and no section below 14. The page does not give a new-scale (1-6) minimum.'),
 ('IELTS', 5.5, '{"writing": 5.5, "each_section": 5.0}'::jsonb, 'Writing no lower than 5.5 and no section below 5.0.'),
 ('DUOLINGO', 95, null, 'Duolingo English Test score of 95.'),
 ('PTE', 50, null, 'Pearson Test of English Academic.'),
 ('CAMBRIDGE', 168, null, 'B2 First, C1 Advanced or C2 Proficiency; 160 and above is eligible for the pathway program.')) v;
insert into cost_aid (institution_id, year, tuition_usd, tuition_out_of_state_usd, tuition_intl_usd, required_fees_usd, room_board_usd, other_usd, total_coa_usd, intl_aid_policy, meets_full_need, merit_scholarships, notes, source_id) values
 ('6c3e8639-f65c-565d-becf-9cf682d65265', '2026-2027', 6838, 20968, 18142, 2496, 19245, 8813, 48696, 'merit_only', false, true, 'CSUSM international estimate for 2026-27 at the 12-unit minimum load: tuition and fees $20,638 (basic tuition $6,838 + $471/unit non-resident charge for 24 units + fees $2,496, so tuition_intl is 20,638 minus fees), room and board $19,245, living expenses $8,813 (mandatory 12-month health insurance, books and personal), total $48,696; summer not included. tuition_usd, tuition_out_of_state_usd (30 units) and required_fees_usd are CDS G1 2026-27 values.; The #YouAreWelcomeHere scholarship for first-year international applicants is advertised on the freshman page as covering up to 50% of non-resident tuition; the 2021 application form says a minimum of 50%, renewable up to 4 years with a 3.0 GPA, with a 500-1,000 word essay or short video and an April 1 deadline (confirm current terms with iapply@csusm.edu). Partial tuition waivers are only open to F-1 students after one semester in residence. International students are not eligible for most aid. Conditional admission: the Intensive English Pathway takes any English level, the University Access Program needs TOEFL 51 or IELTS 5.0; both lead to guaranteed admission (program fees not checked).', '3165aa75-1db4-56dc-8340-edc32da67334');
