insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, notes, source_id, source_note) values
 ('ea8a9058-d10b-5749-becc-91361225ca39', '2024-2025', 6956, 6064, 616, 'Baseline from IPEDS (fall 2024 entering class); no Common Data Set was found on Campbell''s website or by web search. Counts from the IPEDS ADM2024 file (via the Urban Institute API mirror): 6,956 applicants, 6,064 admitted, 616 enrolled (598 full-time + 18 part-time). The same source shows 3,680 applicants / 3,470 admitted for fall 2023, so the 2024 applicant count may include a reporting change. Campbell is test-optional and College Navigator shows no SAT/ACT percentiles. International applicant counts, GPA and class-rank data are not published. College Navigator shows 2% of undergraduates as U.S. nonresidents. Undergraduate enrollment (2,699) is the main campus; total enrollment is 4,963 with graduate and professional programs.', '8800530a-d3a0-57c0-b86c-bde07cd1a589', 'admissions_site');
insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('ea8a9058-d10b-5749-becc-91361225ca39', '2026-27', 'optional', 'Fall undergraduate applicants may be reviewed for admission and merit scholarships without SAT, ACT or CLT scores; scores are ''highly encouraged'' and used for course placement (placement exams are offered if none are submitted). The international page, however, says an SAT or ACT score is required for scholarship consideration and can also show English proficiency.', '7e525089-8875-5719-b29e-9d68cf9cc6d4');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('ea8a9058-d10b-5749-becc-91361225ca39', '2026-27', array['common_app','own']::text[], 0, '''There''s no cost or deadline to apply''. Campbell is a Common App member and also has its own application. Personal essay and teacher recommendations are not required but are reviewed if sent. International documents: application, transcripts and national exam results (translated and evaluated into English by an agency such as IEE, The Evaluation Company or WES, or any NACES member; certified as true copies), a statement of financial support for one year (dated within six months), and a Visa Clearance form for applicants already at a U.S. high school. Recommended high school units: 4 English, 3 math (Algebra II and Geometry), 2 social science, 2 lab science. Christian university.', 'bf4da355-0a9d-5029-bd15-2accc40087c0');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, notes, source_id) values
 ('1328e6c6-766e-5562-8e5c-997a06694716', 'ea8a9058-d10b-5749-becc-91361225ca39', '2026-27', 'application', 'ROLLING', 'Rolling admission (fall 2027 entry)', 'No application deadline is published for any applicant: ''There isn''t a deadline''; applications are reviewed once complete and accepted until the semester start date, though Campbell advises against waiting. The Early Campbell Commitment Program offers priority housing and additional scholarships to early applicants (dates not printed on the pages read).', '8de9faac-5cee-554f-b40f-b71061f7f3b9');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('ea8a9058-d10b-5749-becc-91361225ca39', 'required_all_international', 'The international page says English proficiency ''may be demonstrated by'' TOEFL, IELTS (Cambridge Examinations), SAT or ACT, and prints no exemption rules for native speakers or English-medium schools. Campbell''s TOEFL, SAT and ACT institutional code is 5100. The page lists the TOEFL as iBT 61, computer-based 173 or paper-based 500. The undergraduate catalog could not be reached (its host has a certificate error), so a Duolingo or PTE minimum, if any, is not confirmed. No conditional-admission or ESL pathway was found on the pages read.', 'bf4da355-0a9d-5029-bd15-2accc40087c0');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
select 'ea8a9058-d10b-5749-becc-91361225ca39'::uuid, 'required_option', 'bf4da355-0a9d-5029-bd15-2accc40087c0'::uuid, v.* from (values
 ('TOEFL_IBT', 61, 'Internet-based TOEFL 61; the page also lists computer-based 173 and paper-based 500. The page does not mention the 2026 1-6 scale.'),
 ('IELTS', 5.5, 'Page text: ''Cambridge Examinations IELTS can be used instead of the TOEFL with a grade of 5.5''.')) v;
insert into score_codes (institution_id, source_id, test_key, code, notes)
select 'ea8a9058-d10b-5749-becc-91361225ca39'::uuid, 'bf4da355-0a9d-5029-bd15-2accc40087c0'::uuid, v.* from (values
 ('sat', '5100', 'Institutional code for SAT/ACT/TOEFL printed on the international page.'),
 ('act', '5100', 'Institutional code for SAT/ACT/TOEFL printed on the international page.'),
 ('toefl', '5100', 'Institutional code printed on the international page.'),
 ('ielts', null, 'No institution code is listed.'),
 ('duolingo', null, 'Duolingo is not listed on the undergraduate international page.'),
 ('pte', null, 'PTE is not listed on the undergraduate international page.')) v;
insert into cost_aid (institution_id, year, tuition_usd, tuition_out_of_state_usd, tuition_intl_usd, required_fees_usd, room_board_usd, books_usd, total_coa_usd, merit_scholarships, notes, source_id) values
 ('ea8a9058-d10b-5749-becc-91361225ca39', '2026-2027', 41250, 41250, 41250, 2060, 15030, 830, 68749, true, 'Estimated 2026-27 cost of attendance living on campus: tuition $41,250 (full-time, 12+ hours), fees $2,060, housing $8,280 and food $6,750 (room_board is their sum), books $830, supplies $1,100, transportation $2,178, personal $5,642, course materials $586, federal loan fees $73; total $68,749. No separate international tuition rate is published.; Merit scholarships (Scott-Ellis program) are determined automatically at admission for main-campus applicants, and the international page requires an SAT or ACT score sent by the testing agency ''for scholarship consideration''. No international-specific scholarship amounts are published; the FAQ gives an average aid package of $27,203 for all students. Federal aid does not apply to international students.', 'da0cc375-5a87-5e54-960d-0354910e0967');
insert into institution_tiers (institution_id, tier_code, category_key, rationale)
