insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, notes, source_id, source_note) values
 ('9ab76ce3-518d-5095-9fd1-2b2d5322b17c', '2024-2025', 5000, 3987, 557, 'Baseline from IPEDS (fall 2024 entering class); no Common Data Set was found on Campbellsville''s website. Counts come from the IPEDS ADM2024 file (via the Urban Institute API mirror): 5,000 applicants, 3,987 admitted (80%), 557 enrolled (537 full-time + 20 part-time). The same source shows 1,015 applicants / 998 admitted for fall 2023, so the 2024 applicant count may include a reporting change. Campbellsville is test-optional and reports no SAT/ACT percentiles; international applicant counts, GPA and class-rank data are not published. Undergraduate enrollment (6,848, College Navigator fall 2024) includes online and regional-center students, not just the Campbellsville campus.', '5dcfd5d8-e940-552b-bfe0-cd512d508ad3', 'admissions_site');
insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('9ab76ce3-518d-5095-9fd1-2b2d5322b17c', '2026-27', 'optional', 'ACT/SAT are not required for undergraduate admission (catalog and admissions page); scores may be used for course placement, athletic eligibility and scholarship eligibility. The minimum high school GPA is generally 2.0. The admissions page says some international programs may require SAT/ACT, but the catalog international steps ask for SAT/ACT only from native English speakers.', '6ebf63d8-6778-5f26-b1cb-581b682fea1c');
insert into application_requirements (institution_id, cycle, platforms, notes, source_id) values
 ('9ab76ce3-518d-5095-9fd1-2b2d5322b17c', '2026-27', array['own']::text[], 'Campbellsville''s own online application (Workday). The fee is unclear: the international catalog steps say an application fee and enrollment deposit are required, the admissions page says waivers exist, and the apply roadmap calls the application ''FREE''. International checklist: transcripts in the original language and English, a NACES credential evaluation (WES, ECE, Josef Silny, SpanTran, etc.), passport copy, bank statement showing funds for one year (dated within 6 months) with an affidavit of support, housing application and medical history form; the admissions page also lists a letter of recommendation and an interview ''if required''. No international deadline is printed. Christian university (Christ-centered); a prior-conduct clearance applies to applicants with a criminal or expulsion history.', 'cd8dd16e-d011-58c8-af28-8e081681bdff');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('60657802-d3d8-5d44-a366-ac6e01d4c9fb', '9ab76ce3-518d-5095-9fd1-2b2d5322b17c', '2026-27', 'application', 'ROLLING', 'Rolling admission (fall 2027 entry)', null, 'No application deadline is published for international undergraduates; the apply roadmap says to apply August-November before a fall start. The international page says to apply early for visa time.', 'a75bc00a-66e4-58ec-8434-0cac634650b0'),
 ('e427f7b1-26a0-5b0a-9a57-c69e0b181d62', '9ab76ce3-518d-5095-9fd1-2b2d5322b17c', '2026-27', 'scholarship', null, 'Competitive scholarship applications', '2026-12-31', 'Apply roadmap: ''Submit Competitive Scholarship Applications by December 31st'' (no year printed; taken as the cycle for fall 2027). Faith-based and community scholarships close March 15. The page does not say whether these are open to international students.', 'a75bc00a-66e4-58ec-8434-0cac634650b0'),
 ('275644f5-719a-5d6d-ac4f-ce68eb176dcf', '9ab76ce3-518d-5095-9fd1-2b2d5322b17c', '2026-27', 'deposit', null, 'Enrollment decision deadline', '2027-05-01', 'Apply roadmap: tell Campbellsville your decision by May 1 (National College Decision Day). Written for on-campus undergraduates generally; the catalog says international students must pay an enrollment deposit.', 'a75bc00a-66e4-58ec-8434-0cac634650b0');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('9ab76ce3-518d-5095-9fd1-2b2d5322b17c', 'required_nonnative', 'Required for students whose native language is not English. Accepted proof (2026-27 catalog): TOEFL paper 500 or iBT 3.5, IELTS, PTE 52, Duolingo 95, an approved test from another agency, or successful completion of Campbellsville''s ESL Institute (ESLI) program. Native English speakers send SAT or ACT scores instead. No separate conditional-admission policy was found; Campbellsville also runs ESL, Intensive English (IELP) and EFL certificate programs.', '93f7b23f-2ad3-5b8b-b941-c7bcf62ed364');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
select '9ab76ce3-518d-5095-9fd1-2b2d5322b17c'::uuid, 'required_option', '93f7b23f-2ad3-5b8b-b941-c7bcf62ed364'::uuid, v.* from (values
 ('TOEFL_IBT_2026', 3.5, 'Catalog: ''TOEFL ... 3.5 or higher on the internet-based test'' (paper-based 500). The catalog does not name the scale; 3.5 cannot be a 0-120 score, so it is read as the new 1-6 scale. No minimum on the old 0-120 scale is printed on Campbellsville''s own pages (third-party sites list 61).'),
 ('IELTS', 6.0, 'The same 2026-27 catalog page contradicts itself: the admissions-requirements table says IELTS 5, the International Student Admission section says IELTS 6. The higher value is shown.'),
 ('DUOLINGO', 95, 'Listed in the catalog''s International Student Admission section, not in its requirements table.'),
 ('PTE', 52, null)) v;
insert into score_codes (institution_id, test_key, notes, source_id)
select '9ab76ce3-518d-5095-9fd1-2b2d5322b17c'::uuid, v.* from (values
 ('sat', 'No SAT code is printed on the Campbellsville admissions pages.', '6ebf63d8-6778-5f26-b1cb-581b682fea1c'::uuid),
 ('act', 'No ACT code is printed on the Campbellsville admissions pages.', '6ebf63d8-6778-5f26-b1cb-581b682fea1c'::uuid),
 ('toefl', 'No TOEFL code is printed on the Campbellsville admissions pages.', 'cd8dd16e-d011-58c8-af28-8e081681bdff'::uuid),
 ('ielts', 'No institution code is listed.', 'cd8dd16e-d011-58c8-af28-8e081681bdff'::uuid),
 ('duolingo', 'No institution code is listed.', 'cd8dd16e-d011-58c8-af28-8e081681bdff'::uuid),
 ('pte', 'No institution code is listed.', 'cd8dd16e-d011-58c8-af28-8e081681bdff'::uuid)) v;
insert into cost_aid (institution_id, year, tuition_usd, tuition_out_of_state_usd, tuition_intl_usd, required_fees_usd, room_board_usd, books_usd, total_coa_usd, notes, source_id) values
 ('9ab76ce3-518d-5095-9fd1-2b2d5322b17c', '2026-2027', 29760, 29760, 29760, 500, 10984, 800, 48362, 'Campbellsville campus, traditional undergraduate living on campus: tuition $14,880 per semester (12-18 hours) x 2 = $29,760; technology fee $300 + activity fee $200; food and housing $10,984; books $800; total COA $48,362 including personal expenses, transportation and loan fees (published). The tuition page lists room and board of $4,884-$5,920 per semester depending on the hall. No separate international tuition rate is published.; No international-specific scholarship was found. Freshman merit scholarships on the Campbellsville campus are set by high school GPA (Trustees up to $16,500, Provost up to $15,500, Dean up to $14,500, Founders up to $13,500 per year, renewable with a 2.0 GPA); a Presidential Scholarship (full tuition, housing and books) needs a 3.5 GPA or 25 ACT / 1200 SAT plus an essay and interview. The scholarships page does not say whether international students qualify, so eligibility is unconfirmed. International students cannot use FAFSA-based aid.', '9e70f53b-737d-5921-ac91-47fa872d3e37');
