insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('7e265859-92d1-5be8-b5aa-69601baaa5de', '2026-27', 'optional', 'Case Western Reserve is test optional; SAT or ACT scores may be submitted if the applicant chooses.', '110f7407-c72b-5c21-9536-718311cc6c48');
insert into application_requirements (institution_id, cycle, platforms, teacher_recs, counselor_rec, app_fee_usd, fee_waiver, notes, source_id) values
 ('7e265859-92d1-5be8-b5aa-69601baaa5de', '2026-27', array['common_app','coalition']::text[], 2, true, 75, true, 'Common App or Coalition with Scoir. Required: official high school transcript, School Report, counselor recommendation, two teacher recommendations, an essay (all first-year students) and the $75 fee (waivers available). Music and music-education applicants need an Arts Supplement. Pre-Professional Scholars applicants write two additional essays plus an interview in late March if selected as a finalist. Applicants seeking need-based aid must indicate it on the application and submit financial aid documents for the application to be complete: non-U.S. residents submit the CSS Profile only (CSS code 1105); U.S. citizens and permanent residents submit FAFSA plus CSS Profile. The page does not state a year, so dates are taken as the current cycle.', '110f7407-c72b-5c21-9536-718311cc6c48');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notification_date, notes, source_id) values
