insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, notes, source_id, source_note) values
 ('7e2fef4e-f682-5d6d-8660-c42316655c62', '2023-2024', 5874, 4925, 861, 'Baseline from IPEDS (fall 2023 entering class; exact counts). No Common Data Set could be reached (the Institutional Research site returned 403 and its data library needs a university login), so GPA, international and residency splits are not added; the international admit rate is unknown. CUA does not consider SAT/ACT scores and IPEDS reports no score percentiles or submission rates. College Navigator for fall 2024 shows 6,714 applicants, 83% admitted and 13% of admits enrolled (admit count not given as an exact number). Undergraduate enrollment 3,177 and student-faculty ratio 11:1 are from College Navigator (fall 2024).', 'c056ff96-6197-5f8c-bd85-43daa7cb6f82', 'admissions_site');
insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('7e2fef4e-f682-5d6d-8660-c42316655c62', '2026-27', 'blind', 'The application page says the university makes admission decisions without requiring SAT or ACT scores. The admissions policy (reviewed 2021) says the Committee on Admission does not consider standardized tests for admission, the Honors Program or merit scholarships, including for international candidates; the scholarship page calls CUA ''test-optional'' but says scores will not be reviewed for admission or scholarships. Graduates of U.S. high schools who use a diploma to waive the English test must still submit SAT/ACT scores.', '5dd1c6b7-4c5e-5824-83c1-dee2bea82119');
insert into application_requirements (institution_id, cycle, platforms, supplemental_essays, teacher_recs, counselor_rec, app_fee_usd, notes, source_id) values
 ('7e2fef4e-f682-5d6d-8660-c42316655c62', '2026-27', array['common_app']::text[], 'Common App essay required; the policy page also lists the activities profile, recommendation letters and essay as part of the review. No separate supplement is described.', 1, true, 0, 'No application fee (''apply for free'' with the Common App). International checklist: proof of English proficiency, confirmation of financial support, a secondary school report with translated transcripts, and the admission packet with visa information; the policy page (2021) adds one teacher recommendation and a counselor report, and says transcripts from outside the U.S. must be certified by an evaluator such as WES or AACRAO. Interview policy is not stated. Evaluation takes about 2-4 weeks after the file is complete.', '84dc1b70-3627-5f61-bf84-0cf7e7389c7b');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('8d83331e-b520-5274-837b-cae79c89cdb6', '7e2fef4e-f682-5d6d-8660-c42316655c62', '2026-27', 'application', 'EA', 'Early Action (non-binding), fall 2027 entry', '2026-11-01', 'Decision and merit scholarship notice before Jan. 1; reply by the May 1 candidate reply date. Same date applies to Early Decision I (binding).', '5dd1c6b7-4c5e-5824-83c1-dee2bea82119'),
 ('cadc0a61-6cb2-555d-90f7-ea76e6851f63', '7e2fef4e-f682-5d6d-8660-c42316655c62', '2026-27', 'application', 'ED', 'Early Decision I (binding), fall 2027 entry', '2026-11-01', 'Decision by Jan. 1; enrollment deposit due Jan. 15.', '5dd1c6b7-4c5e-5824-83c1-dee2bea82119'),
 ('0ce5785c-04b7-570c-9b7c-4320a78acf45', '7e2fef4e-f682-5d6d-8660-c42316655c62', '2026-27', 'application', 'RD', 'Regular Decision and Early Decision II, fall 2027 entry', '2027-02-01', 'The international page''s deadline table and the first-year page say Feb. 1; the same international page''s checklist says ''Apply online by Jan. 15'' (older policy page also says Jan. 15), so apply by Jan. 15 to be safe. ED II deposit due Mar. 16; Regular Decision notification around Mar. 20.', '84dc1b70-3627-5f61-bf84-0cf7e7389c7b');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('7e2fef4e-f682-5d6d-8660-c42316655c62', 'required_nonnative', 'All applicants whose native language is not English must submit a TOEFL, IELTS, Duolingo or PTE result before final admission (the page''s narrative names TOEFL or IELTS; its score table also lists Duolingo and PTE). The requirement can be waived case by case for: a college-level English Composition course equivalent to ENG 101 with a grade of B or above; or a degree from an accredited U.S. institution, or a U.S. high school diploma (U.S. high school graduates must then submit SAT/ACT). No conditional-admission or ESL bridge for first-year applicants is described on the pages reviewed.', '2a9831a2-25ec-5205-94b9-8593e0d5f8c9');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
select '7e2fef4e-f682-5d6d-8660-c42316655c62'::uuid, 'required_option', '2a9831a2-25ec-5205-94b9-8593e0d5f8c9'::uuid, v.* from (values
 ('TOEFL_IBT', 80, 'Exams taken before Jan. 21, 2026. The page lists no section minimums (an older policy page asked for 20 in each section).'),
 ('TOEFL_IBT_2026', 4.5, 'Exams taken after Jan. 21, 2026. The page prints ''4.5'' without naming the 1-6 scale.'),
 ('IELTS', 6.5, 'Older policy page: individual module scores are also reviewed.'),
 ('DUOLINGO', 120, 'A third-party listing and an older graduate PDF show 105; the university''s current page says 120.'),
 ('PTE', 58, 'PTE Academic.')) v;
