 ('ielts', null, 'Have results sent directly to the university; no IELTS code is listed.', '2a9831a2-25ec-5205-94b9-8593e0d5f8c9'::uuid),
 ('duolingo', null, 'No institution code is listed.', '2a9831a2-25ec-5205-94b9-8593e0d5f8c9'::uuid),
