insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, intl_applicants, intl_admits, in_state_applicants, in_state_admits, out_state_applicants, out_state_admits, pct_submit_sat, pct_submit_act, gpa_avg, pct_reporting_gpa, gpa_distribution, notes, source_id) values
 ('709a39a5-13b7-5550-97c1-80c55c753cb7', '2025-2026', 10176, 8070, 1762, 390, 70, 8577, 7164, 1209, 836, 42.6, 0.8, 3.15, 98, '{"4.0": 6.3, "3.75-3.99": 7.9, "3.50-3.74": 14.1, "3.25-3.49": 16.9, "3.00-3.24": 17.0, "2.50-2.99": 27.7, "2.0-2.49": 9.6, "1.0-1.99": 0.4}'::jsonb, 'CDS C1 (fall 2025): international first-year applicants 390, admitted 70 (18%), enrolled 10, far below the 79% overall admit rate, so international applicants are not near-certain admits. No waitlist, no early decision or early action. GPA distribution is the ''all enrolled students'' column of C11 (average 3.15 on a 4.0 scale, reported by 98%). SAT percentiles are of the 751 enrolled first-years who submitted SAT; ACT is reported by only 6 students so ACT percentiles are omitted. Undergraduate enrollment 9,463 is CDS B1 and the 164 nonresident undergraduates are CDS B2 (156 degree-seeking). Student-to-faculty ratio 14:1 is College Navigator.', 'efeca790-6cde-5bcd-ac3c-27d0db17184b');
