insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('709a39a5-13b7-5550-97c1-80c55c753cb7', '2026-27', 'optional', 'SAT/ACT scores are optional for first-year and international applicants (CDS C8A: not required, but considered if submitted). Candidates offered admission have achieved a minimum 2.0 GPA and a class rank in the top 50 percent.', '27c5801f-a584-56aa-b6b3-34ab4f71304f');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('709a39a5-13b7-5550-97c1-80c55c753cb7', '2026-27', array['own']::text[], 50, 'Online application with a $50 fee or fee waiver, a personal essay, official secondary records (a NACES credential evaluation is recommended; SpanTran is the recommended service), passport copy and an Affidavit of Support. Letters of recommendation and SAT/ACT are optional. Admissions counselors usually send a decision within about two weeks of a complete application.', 'af19ccff-5d8f-5bbe-90cd-e989a259a4ef');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('868ce3b4-0c49-555a-ad84-68f033211d8f', '709a39a5-13b7-5550-97c1-80c55c753cb7', '2026-27', 'priority', 'ROLLING', 'International first-year apply-by date, fall 2027', '2027-04-01', 'Rolling admissions; international students ''should apply by'' April 1 (fall) and November 1 (spring). The page prints no year; taken as fall 2027. The university may stop processing applications once class capacity is met. Domestic first-years have a May 1 preferred date; the CDS lists an application closing date of Aug 24, 2027.', 'af19ccff-5d8f-5bbe-90cd-e989a259a4ef');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('709a39a5-13b7-5550-97c1-80c55c753cb7', 'required_nonnative', 'Applicants whose native language is not English must submit one of the listed tests; the page lists no waivers. Applicants below the minimum may enroll in CCSU''s Intensive English Language Program (IELP, 16-week full-time, 20 hours a week, seven levels) before gaining full admission.', 'af19ccff-5d8f-5bbe-90cd-e989a259a4ef');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
select '709a39a5-13b7-5550-97c1-80c55c753cb7'::uuid, 'required_option', 'af19ccff-5d8f-5bbe-90cd-e989a259a4ef'::uuid, v.* from (values
 ('TOEFL_IBT', 79, 'Internet-based minimum 79; the page also lists computer-based 213 and paper-based 550.'),
 ('TOEFL_IBT_2026', 4.5, 'Page prints ''Internet minimum score of 4.5 (as of 1/1/26)'' for the new TOEFL; read as the 1-6 band scale.'),
 ('IELTS', 6.5, 'Minimum band score of 6.5.'),
 ('DUOLINGO', 95, 'Duolingo English Test.'),
 ('PTE', 59, 'Pearson PTE.')) v;
