insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('5eca8745-e717-5cba-97cd-f2f51ae21e77', '2026-27', 'optional', 'CDS C8 (fall 2027): SAT/ACT are not required for admission but considered if submitted. International admission needs transcripts and proof of English; the SAT (EBRW 520) or ACT (English 21) can be used to meet the English requirement.', '5a2aba51-4438-5fbe-bf07-bb1daa01558c');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('5eca8745-e717-5cba-97cd-f2f51ae21e77', '2026-27', array['common_app','own']::text[], 55, 'Apply with CMU''s own application or the Common App (CMU''s Common App code is shown on the page as Central27). The $55 non-refundable fee is waived through Oct 31 of the 2026 fall season; the page does not say what the fee will be for later applicants. Currently enrolled high-school students need grade 9-11 transcripts for a decision and must graduate before starting. CMU''s international page reports a 52.8% acceptance rate for international freshmen in fall 2023.', '3e1da1f6-f1c5-5a9f-ba5d-47c6d871374b');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('7937a895-9d38-58e5-899b-8717876228e8', '5eca8745-e717-5cba-97cd-f2f51ae21e77', '2026-27', 'application', 'ROLLING', 'International preferred admission date, fall 2027', '2027-05-15', 'Page recommends applying by May 15 for fall (late August) and Oct 1 for spring. No hard deadline is printed. Year assumed for fall 2027.', '3e1da1f6-f1c5-5a9f-ba5d-47c6d871374b');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('5eca8745-e717-5cba-97cd-f2f51ae21e77', 'required_nonnative', 'Not required for applicants from a list of English-speaking countries (list on the apply page), graduates of a US high school with at least 3 years of attendance, or completion of English-medium secondary or post-secondary study, or 24+ graded post-secondary credits at a 2.50 GPA from an English-medium institution. Other proofs: IB English HL 5, AP English 4, GCSE A or B, MET 52, ELS Level 112. Scores are valid two years. The page lists scores ''for regular admission'', but does not describe a conditional-admission route.', '5a2aba51-4438-5fbe-bf07-bb1daa01558c');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
