 ('258cf4f6-f744-52e6-96fd-ce158a5b94f5', 'd8057782-44e3-5e2c-998a-2f53fcba2556', 'financial_aid_site', 'UCO Office of Global Affairs - Scholarships for international students', 'https://www.uco.edu/students/oga/future-students/scholarships.PHP', null, '2026-10-26'),
 ('b6b6f6c8-b88e-54fa-ac0c-8ad2da43cade', 'd8057782-44e3-5e2c-998a-2f53fcba2556', 'financial_aid_site', 'UCO Office of Global Affairs - International tuition and fees', 'https://www.uco.edu/students/oga/future-students/tuition-and-fees.PHP', null, '2026-10-26');
insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, pct_submit_sat, pct_submit_act, notes, source_id, source_note) values
 ('d8057782-44e3-5e2c-998a-2f53fcba2556', '2023-2024', 4945, 4043, 1889, 0, 89, 'IPEDS ADM2023 (fall 2023 first-time students): 4,945 applicants, 4,043 admitted, 1,889 enrolled. College Navigator fall 2024: 5,855 applicants, 78% admitted. IPEDS reports no nonresident-alien applicant counts for UCO, so international admit figures are null; nonresidents are about 3% of undergraduates (fall 2024, rounded). UCO reports ACT only (no SAT percentiles). Undergraduate enrollment 10,777 and 18:1 ratio are fall 2024. No readable Common Data Set was found for this college, so this is the IPEDS baseline; GPA, residency and class-rank details are not included.', '70271a3d-1ee2-585b-8210-7f60baf732c9', 'admissions_site');
insert into test_score_percentiles (institution_id, cds_year, source_id, test, p25, p50, p75)
select 'd8057782-44e3-5e2c-998a-2f53fcba2556'::uuid, '2023-2024', '70271a3d-1ee2-585b-8210-7f60baf732c9'::uuid, v.* from (values
 ('ACT_COMPOSITE', 17, 20, 24),
 ('ACT_ENGLISH', 17, 21, 24),
 ('ACT_MATH', 16, 18, 23)) v;
insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('d8057782-44e3-5e2c-998a-2f53fcba2556', '2026-27', 'optional', 'International first-year applicants qualify with a high school GPA of 2.70 or equivalent (SAT/ACT not required), or with SAT 1030+ (reading + math) or ACT 20+. Students admitted on grades without scores take UCO''s Computerized Placement Test before enrolling.', 'f7c98104-162e-57b1-a940-a53f8daa3085');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('d8057782-44e3-5e2c-998a-2f53fcba2556', '2026-27', array['own']::text[], 40, 'Online application on UCO''s own portal; $40 non-refundable fee. Documents: transcripts (equivalent of 12 years of schooling, with certified English translation if needed), English proficiency, passport, and for F-1 a bank statement (minimum $29,950 for a degree-seeking undergraduate) plus a Statement of Financial Sponsorship. UCO School of Music applicants also submit an audition form.', 'a2cac4a8-c2a9-5d42-99bb-ad6897899cfc');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('4b03775e-f12a-5ece-9750-eeed9983a20c', 'd8057782-44e3-5e2c-998a-2f53fcba2556', '2026-27', 'application', 'ROLLING', 'Application (fall 2027): no published deadline', null, 'UCO states there are no specific application deadlines for undergraduate international applicants and recommends applying as early as possible for processing, visa and travel.', 'f7c98104-162e-57b1-a940-a53f8daa3085'),
 ('69ea92b9-9dd4-5ac7-be78-14596186d483', 'd8057782-44e3-5e2c-998a-2f53fcba2556', '2026-27', 'scholarship', null, 'Priority deadline for automatic international admission scholarships (fall 2027)', '2027-05-31', 'The scholarships page lists ''May 31 (Fall)'' with no year, treated as fall 2027. No separate scholarship application is needed.', '258cf4f6-f744-52e6-96fd-ce158a5b94f5');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('d8057782-44e3-5e2c-998a-2f53fcba2556', 'required_nonnative', 'Applicants from UCO''s approved native English-speaking countries are exempt. Alternative: 12 weeks of intensive English at an approved U.S. ESL program after reaching a minimum TOEFL 48 iBT (460 PBT), IELTS 5.0, PTE 36 or iTEP 3.0. Students below the test minimums can apply for conditional admission and attend an approved 12-week Oklahoma ESL program, such as The Language Company on UCO''s campus, before enrolling.', 'a2cac4a8-c2a9-5d42-99bb-ad6897899cfc');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
select 'd8057782-44e3-5e2c-998a-2f53fcba2556'::uuid, 'required_option', 'a2cac4a8-c2a9-5d42-99bb-ad6897899cfc'::uuid, v.* from (values
 ('TOEFL_IBT', 61, '500 on the paper-based test is also accepted. The page does not give a new 1-6 scale minimum.'),
 ('IELTS', 5.5, 'Overall band.'),
 ('PTE', 44, 'PTE Academic. iTEP Academic 3.5 is also accepted.')) v;
insert into score_codes (institution_id, test_key, code, notes, source_id)
select 'd8057782-44e3-5e2c-998a-2f53fcba2556'::uuid, v.* from (values
 ('sat', null, 'UCO''s international pages do not print an SAT code; look it up in the College Board code search.', 'f7c98104-162e-57b1-a940-a53f8daa3085'::uuid),
 ('act', null, 'No ACT code is printed on the pages read; look it up at act.org.', 'f7c98104-162e-57b1-a940-a53f8daa3085'::uuid),
 ('toefl', '6091', 'UCO ETS institutional code for TOEFL.', 'a2cac4a8-c2a9-5d42-99bb-ad6897899cfc'::uuid),
 ('ielts', null, 'No institution code is listed.', 'a2cac4a8-c2a9-5d42-99bb-ad6897899cfc'::uuid),
 ('duolingo', null, 'Duolingo is not listed among UCO''s accepted undergraduate English tests.', 'a2cac4a8-c2a9-5d42-99bb-ad6897899cfc'::uuid),
 ('pte', null, 'No institution code is listed.', 'a2cac4a8-c2a9-5d42-99bb-ad6897899cfc'::uuid)) v;
insert into cost_aid (institution_id, year, tuition_intl_usd, room_board_usd, other_usd, total_coa_usd, intl_aid_policy, intl_need_aid, meets_full_need, merit_scholarships, merit_separate_app, notes, source_id) values
 ('d8057782-44e3-5e2c-998a-2f53fcba2556', '2026-2027', 19900, 10300, 2260, 32460, 'merit_only', false, false, true, false, 'International tuition page (undated, accessed 2026-10-26; labeled 2026-2027 as the current page): undergraduate tuition and fees $19,900 per year at 12 credit hours per semester, housing and dining $10,300 (nine months), books, insurance and miscellaneous $2,260 (in other_usd), total $32,460.; College Navigator 2024-25: tuition and fees in-state $8,818, out-of-state $19,704; on-campus food and housing $9,700, other $8,400; total_coa_usd is the out-of-state on-campus total.; Applying for admission also applies for automatic freshman scholarships: Distinguished Global Scholar up to $16,000 over four years ($4,000/yr) for GPA 3.50 or SAT 1300 or ACT 28; Merit Global Scholar up to $12,000 ($3,000/yr) for GPA 3.25 or SAT 1250 or ACT 26; Honor Global Scholar up to $8,000 ($2,000/yr) for GPA 3.00 or SAT 1200 or ACT 24. Renewable with a 3.00-3.25 GPA. Extra funding (up to $4,500/yr total) for residents of Nigeria, Ghana, Malaysia, Vietnam, Thailand or Ivory Coast. UCO says it awards about $700,000 a year to international students.', 'b6b6f6c8-b88e-54fa-ac0c-8ad2da43cade');
