insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, in_state_applicants, in_state_admits, out_state_applicants, out_state_admits, gpa_avg, pct_reporting_gpa, gpa_distribution, notes, source_id) values
 ('ea3382eb-01e4-5bef-a9f9-45507552ef54', '2024-2025', 8918, 8081, 1619, 7090, 6674, 1352, 1220, 3.2, 98.83, '{"4.0": 3.0, "3.75-3.99": 17.0, "3.50-3.74": 15.0, "3.25-3.49": 14.0, "3.00-3.24": 14.0, "2.50-2.99": 27.0, "2.0-2.49": 9.0, "1.0-1.99": 0.0}'::jsonb, 'CDS C1 fall 2024 first-year class from the CDS PDF''s fillable fields: applicants 3,855 men + 5,063 women = 8,918, admitted 3,444 + 4,637 = 8,081, enrolled 759 + 860 = 1,619 (College Navigator shows 8,919 applicants, 91% admitted, 20% of admits enrolled). The CDS residency table sums to only 8,442 applicants / 7,894 admits / 1,612 enrolled and leaves the international column blank, so international applicants and admits are null. CDS C11 lists a further 1% with GPA below 1.0. CWU has no waitlist, no early decision or early action, and no application closing date (C14); applicants are admitted until classes start (C14 priority date 3/1, which differs from the Jan 31 on CWU''s admissions page). C6 (open admission) answered ''Other'': a 2.0 GPA with rare exceptions. SAT/ACT ranges (C9) and the C7 factor grid could not be read reliably from the 2024-25 CDS, so scores and factors are omitted.', 'fff59c59-ba38-595d-add8-f1de37692985');
insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('ea3382eb-01e4-5bef-a9f9-45507552ef54', '2026-27', 'optional', 'CWU says it is a test-optional school: SAT/ACT scores are not required for admission but can be sent for class placement. The 2024-25 CDS (C8) says scores are not considered unless they would have a positive effect on the decision, and College Navigator lists SAT/ACT as ''Not considered (Test Blind)''. Admission is by high school GPA (2.7+ is guaranteed admission through the CWU Guaranteed Admission Program; 2.50-2.69 may need a personal statement; 2.00-2.49 requires a personal statement and holistic review) plus core courses (4 English, 4 math, 3 science, 3 social science, 2 world language, 1 arts for out-of-state applicants).', '7257ca1d-0af6-51e5-9011-9c0f953d7ea8');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('ea3382eb-01e4-5bef-a9f9-45507552ef54', '2026-27', array['common_app','own']::text[], 60, 'Apply through the CWU portal or the Common App; $60 nonrefundable fee. A $400 enrollment deposit is required from first-year international students before the I-20 is issued. Documents: proof of English proficiency unless exempt, official transcripts (electronic accepted; a course-by-course evaluation may be requested), Confidential Financial Statement signed by the student and sponsor plus a bank statement dated within three months showing funds for one academic year (no dollar amount given). CDS C7 lists essays and recommendations as not considered (letters are read only on appeal).', '014988b5-d7b8-532b-adcb-6478a39004bc');
insert into deadlines (institution_id, cycle, source_id, id, kind, plan_key, label, notes)
select 'ea3382eb-01e4-5bef-a9f9-45507552ef54'::uuid, '2026-27', '014988b5-d7b8-532b-adcb-6478a39004bc'::uuid, v.* from (values
 ('9f2262ed-612a-5387-b4cb-82c6ad255f23'::uuid, 'priority', null, 'First-year priority date for fall 2027: not yet published', 'CWU''s international page lists Fall Quarter 2026 as ''January 31st, 2025'' (almost certainly a typo for 2026; the domestic first-year page says January 31, 2026) and no fall 2027 date. The 2024-25 CDS lists a 3/1 priority date. Winter 2027 entry: Nov 1, 2026; spring 2027: Feb 1, 2027. Confirm the fall 2027 date with CWU.'),
 ('7413d7cf-e18c-55dd-911b-3cbdaa863e54'::uuid, 'application', 'ROLLING', 'Application (fall 2027): rolling after the priority date', 'Applications after the priority date are accepted on a space-available basis. The CDS says there is no closing date and applicants are admitted until classes start.')) v;
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('ea3382eb-01e4-5bef-a9f9-45507552ef54', 'required_nonnative', 'Exempt: applicants from listed countries (including Australia, Canada except Quebec, Ireland, New Zealand, the United Kingdom, Singapore, Nigeria, Ghana, Kenya, South Africa, Jamaica and others on the page). Also accepted instead of a test: SAT EBRW 530 or ACT English 19, IB Higher Level English grade 5+, Cambridge IGCSE/GCE/GCSE/A-level English First Language grade C+, two U.S. college English composition courses at C, completing school outside the U.S. taught in English (official school letter), PEAP level 6, LanguageCert 65, or UESL with a B or higher plus recommendation. Test scores must be under two years old.', '014988b5-d7b8-532b-adcb-6478a39004bc');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
select 'ea3382eb-01e4-5bef-a9f9-45507552ef54'::uuid, 'required_option', '014988b5-d7b8-532b-adcb-6478a39004bc'::uuid, v.* from (values
 ('TOEFL_IBT', 71, 'Institutional TOEFL (ITP) not accepted. Conditional admission: students below the minimum can apply to the UESL English program at the same time (UESL application fee $50) and be fully admitted after UESL levels 4 and 5 (at least two academic terms) with B or higher in every class plus a program recommendation, or by reaching a qualifying test score during UESL.'),
 ('TOEFL_IBT_2026', 3.5, 'The page states ''71 iBT/3.5 on the new scale''.'),
 ('IELTS', 6.0, 'Scores sent directly from IELTS.'),
 ('DUOLINGO', 105, 'Duolingo English Test.'),
 ('PTE', 50, 'Pearson PTE Academic.'),
 ('CAMBRIDGE', 180, 'C1 Advanced score of 180 or higher; C2 Proficiency 200 or higher.')) v;
insert into score_codes (institution_id, code, source_id, test_key, notes)
select 'ea3382eb-01e4-5bef-a9f9-45507552ef54'::uuid, '4044', '014988b5-d7b8-532b-adcb-6478a39004bc'::uuid, v.* from (values
 ('toefl', 'CWU school code, as printed on the international admissions page.'),
 ('ielts', 'The page prints ''#4044'' as CWU''s school code under the IELTS test as well.')) v;
insert into cost_aid (institution_id, year, tuition_usd, tuition_out_of_state_usd, tuition_intl_usd, required_fees_usd, room_board_usd, books_usd, other_usd, total_coa_usd, intl_aid_policy, meets_full_need, merit_scholarships, notes, source_id) values
 ('ea3382eb-01e4-5bef-a9f9-45507552ef54', '2026-2027', 7716, 27041, 27041, 2396, 16280, 900, 2766, 49383, 'merit_only', false, true, 'CWU 2026-27 cost of attendance for a non-resident undergraduate on the Ellensburg campus: tuition $27,041, mandatory fees $2,396, housing $9,718 and food $6,562 (room_board_usd $16,280), books and supplies $900, personal $1,500, transportation $1,200 and loan fees $66 (other_usd $2,766), annual total $49,383. In-state tuition $7,716 per the cost page.; All admitted international students are automatically considered for merit scholarships by incoming GPA: 2.7-2.9 gets $6,979, 3.0-3.6 gets $9,294, 3.7-4.0 gets $12,380 (annual amounts as listed, re-awarded each year from spring-quarter cumulative GPA). Eligible students are emailed within 2-3 weeks of admission and confirm through the International Student Scholarship form. Exchange, government-sponsored, UESL and resident-tuition students are not eligible. The CDS H6 nonresident aid figures could not be read consistently, so they are not used.', '6329f8be-4528-5650-a7ce-868989a6bb38');
