 ('e2d90edb-f384-5215-8da4-2255c9bd9a91', '89897322-018b-5e9a-8a7f-714dc8cfc89d', 'financial_aid_site', 'Charleston Southern University - Student Financial Services (2026-2027 scholarships and cost of attendance)', 'https://www.charlestonsouthern.edu/admissions/financial-aid/', null, '2026-10-26'),
 ('0b616e70-ba3a-5a32-928c-c0204287e290', '89897322-018b-5e9a-8a7f-714dc8cfc89d', 'financial_aid_site', 'Charleston Southern University - Tuition and Costs (fees, deposits)', 'https://www.charlestonsouthern.edu/admissions/financial-aid/tuition-and-costs/', null, '2026-10-26'),
