insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, pct_submit_sat, pct_submit_act, notes, source_id, source_note) values
 ('89897322-018b-5e9a-8a7f-714dc8cfc89d', '2024-2025', 4660, 4495, 795, 49, 31, 'Baseline from IPEDS (fall 2024 entering class); no Common Data Set was found on Charleston Southern''s website or by web search. Counts from the IPEDS ADM2024 file (via the Urban Institute API mirror): 4,660 applicants, 4,495 admitted, 795 enrolled (788 full-time + 7 part-time). The same source shows 6,072 applicants / 4,620 admitted for fall 2023. Test scores are for enrolled first-time students who submitted them (387 SAT, 246 ACT). International applicant counts and GPA data are not published. College Navigator shows 2% of undergraduates as U.S. nonresidents.', '55647fdf-2a3b-5727-ba13-90843ea5ca0a', 'admissions_site');
insert into test_score_percentiles (institution_id, cds_year, source_id, test, p25, p50, p75)
select '89897322-018b-5e9a-8a7f-714dc8cfc89d'::uuid, '2024-2025', '55647fdf-2a3b-5727-ba13-90843ea5ca0a'::uuid, v.* from (values
 ('SAT_ERW', 480, 530, 600),
 ('SAT_MATH', 450, 510, 560),
 ('ACT_COMPOSITE', 18, 21, 24),
 ('ACT_ENGLISH', 16, 21, 24),
 ('ACT_MATH', 17, 19, 24)) v;
insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('89897322-018b-5e9a-8a7f-714dc8cfc89d', '2026-27', 'optional', 'Test Flexible policy: SAT/ACT/CLT scores are not required for admission but are encouraged; a student who opts out needs a school counselor or teacher academic reference form, and a 3.9 unweighted GPA or higher never needs scores. If submitted, regular admission uses 530 EBRW / 490 Math (SAT), 19 E / 19 M (ACT) or 64 (CLT); Bridge admission uses 450/440, 17/17 or 57. For international applicants SAT/ACT is optional with a GPA above 2.5, and scores may also be used to meet the English requirement.', '39d1c095-2810-5050-a5d0-1321e3d203ff');
insert into application_requirements (institution_id, cycle, platforms, notes, source_id) values
 ('89897322-018b-5e9a-8a7f-714dc8cfc89d', '2026-27', array['own']::text[], 'Charleston Southern''s own online application. The fee schedule lists an undergraduate online application fee of $25 ''including military, international, and high school non degree exempt'', which reads as waived for international applicants; the admissions pages state no fee. International freshmen send secondary transcripts (original language plus official English translation); no credential evaluation is required for incoming freshmen (transfers need a NACES course-by-course evaluation), a passport copy, and a bank statement (no older than 180 days) with an International Sponsor Statement if someone else pays. Recommended high school units: 4 English, 3 math, 3 science (2 lab), 3 social science/history, each with C or better. Christian university.', '23014a81-c34e-5d3a-b0ae-774ede736857');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('7d22779e-8d7c-5d33-a404-36a66e5748c9', '89897322-018b-5e9a-8a7f-714dc8cfc89d', '2026-27', 'application', 'ROLLING', 'International admission deadline (fall 2027 entry)', null, 'Printed rule: ''The deadline for admission for international students is 60 days prior to the first day of classes of the academic term of entry''. No calendar date is printed, so none is given. No first-year deadline is published for domestic applicants either.', '23014a81-c34e-5d3a-b0ae-774ede736857'),
 ('832363f1-b654-5925-abb8-1f411d0e5c81', '89897322-018b-5e9a-8a7f-714dc8cfc89d', '2026-27', 'scholarship', null, 'Global Ambassador Scholarship priority date', '2026-12-01', 'One full-tuition award a year for an international student whose parents serve in Christian ministry outside the U.S. Priority goes to completed applications by December 1st (no year printed; taken as the cycle for fall 2027). Other international scholarships are automatic at admission with no separate application.', '23014a81-c34e-5d3a-b0ae-774ede736857');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('89897322-018b-5e9a-8a7f-714dc8cfc89d', 'required_nonnative', 'Confirmed English proficiency is required for non-native English speakers. Besides the tests below, it can be met with an SAT EBRW of 530 or two years at a U.S. college/university or high school with a C or better in core subjects. Conditional acceptance: applicants who meet every degree requirement except English may be conditionally accepted pending completion of CSU''s Intensive English Program (IEP entry minimums: TOEFL iBT 45, IELTS 4.0, Duolingo 60; SEVP-certified, evening classes, available for undergraduate and graduate conditional acceptance).', '23014a81-c34e-5d3a-b0ae-774ede736857');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
select '89897322-018b-5e9a-8a7f-714dc8cfc89d'::uuid, 'required_option', '23014a81-c34e-5d3a-b0ae-774ede736857'::uuid, v.* from (values
 ('TOEFL_IBT', 71, 'iBT; CSU code 5079. The page does not mention the 2026 1-6 scale.'),
 ('IELTS', 6.0, null),
 ('DUOLINGO', 105, null),
 ('PTE', 51, 'Pearson Test of English Academic. The page also accepts iTEP 3.7.')) v;
insert into score_codes (institution_id, source_id, test_key, code, notes)
