insert into major_admissions (id, institution_id, program, category_key, admit_model, capped, notes) values
 ('d8ad9ac2-b391-5c8c-b648-82356d6f60ad', 'a78f30f6-0a85-54d2-9fa0-1bb370c87ce9', 'Nursing, BSN', 'nursing', 'pre_major_competitive', true, 'Apply to Cal State Apply as Pre-Nursing (the page says pre-nursing typically closes before other majors), then submit a separate NursingCAS application (Jan 1 to Mar 1 for fall). The BSN page states applicants must be legal residents of California, so international students appear not to be eligible.');

