insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('8a277593-1fe5-517c-a6dc-89613a207f44', '2026-27', 'optional', 'UC states it is test-optional for all programs; the international first-year page also says SAT or ACT are optional. SAT EBRW 480 / ACT English 19 can be submitted to meet the English requirement.', '55bcecd8-0597-5233-8699-3b0a69a0a1c8');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('8a277593-1fe5-517c-a6dc-89613a207f44', '2026-27', array['common_app']::text[], 100, 'International applicants apply with the Common App, pay a $100 non-refundable fee (the deadlines page says the fee is waived for fall applicants who apply by the Nov 1 Early Action deadline) and submit transcripts and test scores; a letter of recommendation is optional. Students are admitted directly into a major and may list two majors. Engineering, Business, Nursing, Design (DAAP), Music (CCM) and Medicine often fill early, so apply by Nov 1.', 'b7dec23f-f64f-5bba-8b54-f123e8c76e37');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notification_note, notes, source_id) values
 ('ebc62483-ad99-5988-96d5-aaec8dbffa29', '8a277593-1fe5-517c-a6dc-89613a207f44', '2026-27', 'application', 'EA', 'Early Action (fall 2027 entry)', '2026-11-01', 'Decisions are released on Cincinnati Decision Day, the second Wednesday in December.', 'Non-binding. Needed for priority consideration for competitive programs, the University Honors Program and merit-based scholarships (including the International Outreach Award). The pages give month/day only; the year is assumed for fall 2027 entry.', 'e18eb53d-718b-5c64-865c-0cf1f3dd715d'),
 ('3349effb-8368-5af6-822b-1fecb0c11fb7', '8a277593-1fe5-517c-a6dc-89613a207f44', '2026-27', 'application', 'ROLLING', 'Rolling deadline (fall 2027 entry)', '2027-03-01', null, 'Space-available basis after Nov 1; applications after Nov 1 are not considered for scholarships and some programs may already be closed. The conditional admission (English pathway) fall deadline is also March 1. Spring deadline is Nov 1 and summer is March 1.', 'e18eb53d-718b-5c64-865c-0cf1f3dd715d'),
 ('6d6118d2-9a3f-53d8-93d2-6473cc55579d', '8a277593-1fe5-517c-a6dc-89613a207f44', '2026-27', 'scholarship', null, 'Complete application by this date to guarantee International Outreach Award consideration', '2026-11-01', null, 'No separate scholarship application; awards are announced shortly after the admission decision.', 'b8a7cc01-998d-5267-9218-3a5cf198596c'),
 ('5dd2e123-dc92-50a5-abd5-b2d2f3596284', '8a277593-1fe5-517c-a6dc-89613a207f44', '2026-27', 'deposit', null, 'Confirmation deadline (fall)', '2027-05-01', null, 'Online form plus a non-refundable confirmation fee.', 'e18eb53d-718b-5c64-865c-0cf1f3dd715d');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('8a277593-1fe5-517c-a6dc-89613a207f44', 'required_nonnative', 'Exempt (decided by International Admissions) if: one year of US or first-language-English-country high school with a C or better in standard English; IGCSE/O-Level English (first language) C or higher; IB English A / Language & Literature (HL 4+, SL 5+, not English B); or 24 semester hours at a US accredited university with C- or higher in English Composition. Scores must be no more than 2 years old. SAT EBRW 480 or ACT English 19 (the only tests accepted for Nursing) or ELS level 112 also satisfy the requirement. Conditional admission with the Cincinnati ELS center is offered for Allied Health, Arts & Sciences, CECH, Engineering (not Aerospace or Freshman Engineering), Business and DAAP (not Architecture, Fashion, Communication, Industrial or Interior Design).', 'b7dec23f-f64f-5bba-8b54-f123e8c76e37');
insert into english_requirements (institution_id, source_id, test_key, status, min_total, min_subscores, notes)
select '8a277593-1fe5-517c-a6dc-89613a207f44'::uuid, 'b7dec23f-f64f-5bba-8b54-f123e8c76e37'::uuid, v.* from (values
 ('TOEFL_IBT', 'required_option', 79, '{"writing": 20, "speaking": 20, "other_sections": 15}'::jsonb, 'Exams before Jan 2026. Applies to all colleges except CCM (66 overall, 15 each section) and Nursing (TOEFL not accepted; SAT/ACT English only).'),
 ('TOEFL_IBT_2026', 'required_option', 4.0, '{"writing": 4.0, "speaking": 4.0, "other_sections": 3.5}'::jsonb, 'Exams after Jan 2026, same colleges as above; CCM requires 3.5 on every section. The page lists these values without naming the 1-6 scale.'),
 ('IELTS', 'required_option', 6.5, '{"writing": 6.0, "speaking": 6.0, "other_sections": 5.5}'::jsonb, 'CCM: 6.0 overall, 5.0 each section. Not accepted for Nursing.'),
 ('DUOLINGO', 'required_option', 100, '{"production": 100, "conversation": 100}'::jsonb, 'CCM: 100 overall, 80 production and 80 conversation. Not accepted for Nursing.'),
 ('PTE', 'required_option', 53, null, 'Not accepted for Nursing.'),
 ('CAMBRIDGE', 'accepted', 176, null, 'C1 Advanced is the recommended exam. Not accepted for Nursing.')) v;
insert into score_codes (institution_id, source_id, test_key, code, notes)
select '8a277593-1fe5-517c-a6dc-89613a207f44'::uuid, 'b7dec23f-f64f-5bba-8b54-f123e8c76e37'::uuid, v.* from (values
 ('sat', '1833', 'College Board code for University of Cincinnati; scores can also be emailed to international.admissions@uc.edu for online verification.'),
 ('act', '3340', 'ACT code for University of Cincinnati.'),
 ('toefl', '1833', 'ETS code; scores can also be emailed for verification.'),
 ('ielts', null, 'No code: email the score report to international.admissions@uc.edu or have the test center send it to UC Undergraduate Admissions.'),
 ('duolingo', null, 'No code listed: send the report electronically from your Duolingo English Test account to University of Cincinnati.'),
 ('pte', null, 'No code listed: send the report electronically from Pearson and email a copy to international.admissions@uc.edu.')) v;
insert into cost_aid (institution_id, year, tuition_usd, tuition_out_of_state_usd, tuition_intl_usd, required_fees_usd, room_board_usd, books_usd, intl_aid_policy, intl_need_aid, intl_need_aid_awarded, intl_avg_award_usd, meets_full_need, merit_scholarships, merit_separate_app, notes, source_id) values
 ('8a277593-1fe5-517c-a6dc-89613a207f44', '2026-2027', 13146, 28480, 28480, 1678, 14546, 1300, 'merit_only', false, 958, 14548, false, true, false, 'CDS G1 first-year 2026-27 (in-state figure is the instructional fee). The CDS lists one nonresident rate, used here as the international rate; UC''s international web page only shows outdated 2022-23 costs. CDS H6: 958 nonresidents received non-need-based institutional aid, average $14,548.; UC does not offer full-tuition or need-based scholarships to undergraduate international students. The International Outreach Award is $5,000-$15,000 per year (Uptown/Main campus; $2,000-$4,000 at regional campuses), needs a 3.0+ unweighted GPA, is applied to the non-resident surcharge only and is renewable for up to 8 semesters. It is reviewed automatically from the admission application.', '02860089-7adb-563a-ae1d-0702b239a7b8');
insert into institution_tiers (institution_id, category_key, tier_code, rationale)
select '8a277593-1fe5-517c-a6dc-89613a207f44'::uuid, v.* from (values
