insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, pct_submit_sat, pct_submit_act, notes, source_id, source_note) values
 ('8e7062c4-4bad-515b-9e22-b2dd6ca06669', '2023-2024', 1782, 1258, 504, 46, 18, 'Baseline from IPEDS (fall 2023 entering class, exact counts). No Common Data Set was found on clayton.edu (only a Fact Book), so SAT total, GPA, residency and international splits are not available. College Navigator fall 2024: 1,870 applicants, 68% admitted, 40% of admitted enrolled (admit count not published as a number). Undergraduate enrollment 5,551 is fall 2024; student-faculty ratio 20:1 has no year label.', '86e8882a-6641-5804-8cf6-1dd409be0983', 'admissions_site');
