insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('8e7062c4-4bad-515b-9e22-b2dd6ca06669', '2026-27', 'required', 'Test-optional (no SAT/ACT needed with a 3.0+ core GPA) only through Summer 2027. The freshman and international pages state ''Test score requirements will resume Fall 2027'', so fall 2027 applicants must submit SAT or ACT. Minimums when required: SAT 480 EBRW and 440 Math, or ACT 17 English (or Reading), 17 Math (the international page also lists 17 composite). Core GPA minimum 2.0 with a passing test score.', '78ce652e-a915-5c60-81cb-03d0f94b9c60');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, fee_waiver, notes, source_id) values
 ('8e7062c4-4bad-515b-9e22-b2dd6ca06669', '2026-27', array['common_app','own']::text[], 40, true, 'Apply with the Clayton State application or the Common App; $40 nonrefundable fee (fee waivers accepted). Required units: English 4, Math 4, Science 4, Social Science 3, Foreign Language 2. International transcripts need a document-by-document evaluation with GPA (WES, Josef Silny or a NACES member). F-1 applicants submit a Financial Verification Form with sponsor''s affidavit and bank letter; the dollar amount is on the form, not the web page. GED scores are not accepted for new freshmen. Letters of recommendation and essays are not mentioned.', '78ce652e-a915-5c60-81cb-03d0f94b9c60');
insert into deadlines (id, institution_id, cycle, kind, label, due_date, notes, source_id) values
 ('21b0e4a2-9c01-59ac-a732-f438c4f0176a', '8e7062c4-4bad-515b-9e22-b2dd6ca06669', '2026-27', 'application', 'International application deadline, fall 2027 entry', '2027-07-15', 'Deadline page prints ''Fall: July 15'' for international applicants without a year (treated as fall 2027); late or incomplete applications are deferred to the following year. Spring deadline Nov. 15; international F-1 students cannot apply for summer terms. For comparison, domestic full-term fall dates are priority July 15 and regular Aug. 1.', 'b827811f-51e5-537c-b2b5-588b7a38e8ff');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('8e7062c4-4bad-515b-9e22-b2dd6ca06669', 'required_nonnative', 'Required if English is not the applicant''s primary language. Other accepted routes: MET 59, EIKEN Pre-1, Cambridge IGCSE/O Level or Edexcel IGCSE/A-Level English grade D or better, UK GCSE or GCE A-Level English grade C or better, completion of an approved USG intensive ESL program, a U.S. college English composition course with C or better, or two years of U.S. high school English (not ESL) with C or better. Paper TOEFL 540+ is accepted where the iBT is unavailable. Duolingo and the new TOEFL 1-6 scale are not listed. The catalog page shows higher minimums (TOEFL iBT 75, IELTS 6.5, Cambridge C1 180); this record follows the current admissions page.', '12e03e18-00ee-5eb1-85c6-3f5a2dd37aab');
insert into english_requirements (institution_id, source_id, test_key, status, min_total, recommended_total, notes)
select '8e7062c4-4bad-515b-9e22-b2dd6ca06669'::uuid, '12e03e18-00ee-5eb1-85c6-3f5a2dd37aab'::uuid, v.* from (values
 ('TOEFL_IBT', 'required_option', 69, 79, 'Minimum total 69, recommended 79 (admissions page). Catalog page says 75.'),
 ('IELTS', 'required_option', 6.0, null, '6.0 total (admissions page). Catalog page says 6.5.'),
 ('PTE', 'required_option', 58, null, 'Pearson PTE Academic 58.'),
 ('CAMBRIDGE', 'accepted', 169, null, 'Page lists Cambridge C1 Advanced, B2 or C2 with a minimum score of ''169 to 177'' depending on exam; catalog says C1 Advanced 180. Confirm with admissions.')) v;
