insert into cost_aid (institution_id, year, tuition_usd, tuition_out_of_state_usd, tuition_intl_usd, required_fees_usd, room_board_usd, books_usd, notes, source_id) values
 ('8e7062c4-4bad-515b-9e22-b2dd6ca06669', '2026-2027', 5280, 20400, 20400, 1116, 12226, 1250, 'Clayton State financial aid 2026-27 cost of attendance, on campus: Georgia resident tuition $5,280, non-resident $20,400, fees $1,116, housing + food $12,226, books $1,250, transportation $1,385, personal $4,405; page totals $25,742 in-state and $40,862 out-of-state (incl. an $80 loan fee). International F-1/J-1 students are classed as non-residents for tuition (International Student Services page), so the international figure uses the non-resident tuition.; No international-specific scholarships are listed on the admissions, financial aid or International Student Services pages read; the admissions page says freshmen are automatically considered for university-administered scholarships.', '5ea43798-5c35-5ee0-b0f5-5b10f7838ab6');
