 ('eb7c0573-7d7d-5bb4-9d50-1a0b4acfce30', 'ac92fb49-45d0-5adb-b5b1-e81459c44faa', 'financial_aid_site', 'Cleveland State - Freshmen scholarships (fall 2027)', 'https://www.csuohio.edu/financial-aid/freshmen-scholarships', null, '2026-10-26');
insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, notes, source_id, source_note) values
 ('ac92fb49-45d0-5adb-b5b1-e81459c44faa', '2024-2025', 11050, 10089, 1580, 'Baseline from IPEDS (fall 2024 entering class; 91% admitted per College Navigator): the latest Cleveland State Common Data Set on its site is 2021-2022, so no CDS was used. Enrolled is full- plus part-time first-time students (1,550 full-time). International applicant counts, GPA and test-score percentiles are not in the baseline: College Navigator lists SAT/ACT as ''not considered'' and shows no score table. Navigator shows U.S. nonresidents at about 6% of undergraduates (rounded), so intl_undergrads is left null. Undergrad enrollment 9,482 is fall 2024.', '5f1ddf90-787c-51ff-b780-f9a17cd46273', 'admissions_site');
insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('ac92fb49-45d0-5adb-b5b1-e81459c44faa', '2026-27', 'optional', 'The international requirements page asks for no SAT/ACT (they appear only as English-proficiency alternatives: ACT English 20, SAT Reading and Writing 530 from March 2016). IPEDS fall 2024 lists SAT/ACT as ''not considered'' for admission, while a search-result excerpt of CSU''s catalog describes the university as test-optional through fall 2026 with scores used for scholarships and placement; the catalog page itself could not be loaded, so verify with CSU.', '1c77a86b-117d-5c9b-ae51-cdcf392a81ba');
insert into application_requirements (institution_id, cycle, platforms, notes, source_id) values
 ('ac92fb49-45d0-5adb-b5b1-e81459c44faa', '2026-27', array['own']::text[], 'Apply through CSU''s own application portal. Minimum 2.3 cumulative high school GPA. Required: transcripts, passport copy and English proof; official transcripts must be evaluated by TEC, ECE or WES. Proof of funds for one year is needed for the I-20. First-year students must meet a math placement score. The international application fee is not stated on the pages read, so it is left null.', '46b962fe-4995-5f3a-95c9-b367410d488c');
insert into deadlines (id, institution_id, cycle, kind, label, due_date, notes, source_id) values
 ('f8cf9163-1314-521f-a8c3-ba62285b3b84', 'ac92fb49-45d0-5adb-b5b1-e81459c44faa', '2026-27', 'application', 'International fall application deadline (fall 2027, assumed)', '2027-07-01', 'Published dates are for fall 2026 (July 1, 2026) and summer 2026 (April 13, 2026); the fall 2027 date is not yet posted, so July 1, 2027 is assumed from the pattern. The I-20 transfer deadline matched the application deadline.', '7af5ff8d-08a4-5224-b9b0-c0e4c1c133ae');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('ac92fb49-45d0-5adb-b5b1-e81459c44faa', 'required_nonnative', 'Applicants from countries on CSU''s English proficiency exemption list may be exempt. Alternatives to test scores: ACT English 20, SAT Reading and Writing 530 (tests from March 2016), iTEP 3.8, or ELS Level 112. If a student misses the GPA or English requirement, CSU''s ESL Program offers pathway courses and the Intensive English Language Program (IELP, 20 hours per week) is available; the pages do not publish conditional-admission scores.', '46b962fe-4995-5f3a-95c9-b367410d488c');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, min_subscores, notes)
select 'ac92fb49-45d0-5adb-b5b1-e81459c44faa'::uuid, 'required_option', '46b962fe-4995-5f3a-95c9-b367410d488c'::uuid, v.* from (values
 ('TOEFL_IBT', 78, '{"each_section": 17}'::jsonb, 'Tests taken before Jan 21, 2026; no section below 17.'),
 ('TOEFL_IBT_2026', 4, '{"reading": 3.5, "listening": 3.5, "speaking": 3.5, "writing": 4}'::jsonb, 'Tests taken on or after Jan 21, 2026: overall 4.0, at least 3.5 in Reading, Listening and Speaking and 4.0 in Writing.'),
 ('IELTS', 6.0, '{"each_section": 5.0}'::jsonb, 'No individual band below 5.0.'),
 ('DUOLINGO', 105, null, null)) v;
insert into score_codes (institution_id, source_id, test_key, notes)
select 'ac92fb49-45d0-5adb-b5b1-e81459c44faa'::uuid, '46b962fe-4995-5f3a-95c9-b367410d488c'::uuid, v.* from (values
 ('sat', 'CSU''s international pages do not print an SAT code; look it up in the College Board code search.'),
 ('act', 'CSU''s international pages do not print an ACT code; look it up at act.org.'),
 ('toefl', 'CSU''s international pages do not print a TOEFL institution code.'),
 ('ielts', 'No institution code is listed.'),
 ('duolingo', 'No institution code is listed.'),
 ('pte', 'PTE is not listed among accepted English tests on the requirements page.')) v;
insert into cost_aid (institution_id, year, tuition_usd, tuition_out_of_state_usd, tuition_intl_usd, room_board_usd, books_usd, other_usd, total_coa_usd, meets_full_need, notes, source_id) values
 ('ac92fb49-45d0-5adb-b5b1-e81459c44faa', '2026-2027', 12988, 18510, 22457, 16800, 800, 7093, 47150, false, 'CSU''s international planning estimate for a bachelor''s student (page does not state the year; assumed 2026-27): tuition and fees $22,457, room and meals $16,800, books $800, health insurance $3,523, local transportation $1,770 and personal expenses $1,800 (other = $7,093); total $47,150. Extra fees: $100 one-time international matriculation fee and $30 per semester international services fee. The CSU Guarantee locks tuition for four years.; College Navigator estimated expenses for full-time beginning undergraduates, 2024-25 (tuition and fees; on-campus food and housing).; No international-specific scholarship is published. CSU''s automatic freshman merit scholarships ($2,000-$7,000 per year) and the CLE Gateway Grant are restricted to U.S. citizens and permanent residents, and the international scholarship page only links to outside resources. Treat aid for international freshmen as unconfirmed.', 'b1cd8c83-ad20-5c13-9c8d-353d249cacd8');
