insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('9278dac9-8285-5b9b-9ec7-2601048bfe53', '2026-27', 'optional', 'International page: ''The SAT or ACT test is optional but recommended''; students without scores may need math and English placement exams. CDS C6 reports an open admission policy for all students and C8 lists SAT/ACT as not required but considered if submitted.', 'f51fa824-8193-59ce-9ecc-9543de7c753c');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('9278dac9-8285-5b9b-9ec7-2601048bfe53', '2026-27', array['common_app','own']::text[], 40, 'International file: online application with a $40 non-refundable fee (the brochure says a waiver code is available on request; a ''Free Application Week'' banner was shown on the international page), official secondary transcript, proof of English proficiency, and for the I-20 the CMU Notarized Statement of Financial Support plus bank statements covering one year of costs (add $5,000 for a spouse and $4,000 per child). Health insurance is automatically billed through CMU''s international group plan. No minimum GPA is published; the merit scholarship uses a U.S.-equivalent 3.0. The CDS lists essay, recommendations and interview as ''considered'' only.', 'f51fa824-8193-59ce-9ecc-9543de7c753c');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('b5638890-d999-5a2e-bd09-d3757c4116b7', '9278dac9-8285-5b9b-9ec7-2601048bfe53', '2026-27', 'application', 'ROLLING', 'International: fully admitted with I-20 issued (fall 2027 entry)', '2027-05-01', 'The international page states that for fall an applicant must be fully admitted and have an I-20 issued by May 1 (visa appointment secured by Aug. 1); the page prints no year, so treated as fall 2027. Spring: admitted with I-20 by Oct. 1. Applicants who miss it defer to the next semester. Applying earlier is needed because the I-20 requires financial documents.', 'f51fa824-8193-59ce-9ecc-9543de7c753c');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('9278dac9-8285-5b9b-9ec7-2601048bfe53', 'required_nonnative', 'Minimum Reading and Writing subscores apply to TOEFL and IELTS, but the values are not printed on the pages read. Also accepted: Oxford ELLT minimum 6; completion of an approved intensive English program (pre-approved by the CMU International Student Admissions Office); full-time enrollment at a U.S. high school, college or university (case by case); other evidence case by case. Medium-of-instruction certificates are not accepted. Students below the minimums can apply for conditional admission to CMU and attend an approved intensive English provider (stated in the 2023-24 international brochure; not repeated on the current requirements page). PTE and Cambridge are not listed.', 'f51fa824-8193-59ce-9ecc-9543de7c753c');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
