insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, intl_applicants, intl_admits, in_state_applicants, in_state_admits, out_state_applicants, out_state_admits, gpa_avg, pct_reporting_gpa, gpa_distribution, notes, source_id) values
 ('9aede4fb-48fd-5348-bd08-f3f35b3b44a2', '2025-2026', 10839, 7999, 632, 1491, 689, 3230, 2503, 6118, 4807, 3.43, 100, '{"4.0": 17.88, "3.75-3.99": 15.98, "3.50-3.74": 14.08, "3.25-3.49": 16.77, "3.00-3.24": 15.98, "2.50-2.99": 16.14, "2.0-2.49": 3.17}'::jsonb, 'CDS C1: international first-year applicants 1,491, admitted 689 (46%), enrolled 14, versus a 74% overall admit rate. Admission is test-free, so no SAT/ACT data are reported (C9 is blank). No early decision or early action; no waitlist. GPA distribution and 3.43 average are C11/C12 (all enrolled first-years). Factors are C7 ''general'' admission (programs with specific criteria, such as BFA/BMus portfolios and auditions, are decided on the work submitted). Undergraduate enrollment 4,346 and 221 nonresident undergraduates are CDS B1/B2 (fall 2025).', '15d6bff4-edba-572d-8905-e80666fd0d97');
