insert into cost_aid (institution_id, year, tuition_usd, tuition_out_of_state_usd, tuition_intl_usd, required_fees_usd, room_board_usd, books_usd, other_usd, intl_aid_policy, intl_need_aid_awarded, intl_avg_award_usd, meets_full_need, merit_scholarships, merit_separate_app, notes, source_id) values
 ('9aede4fb-48fd-5348-bd08-f3f35b3b44a2', '2026-2027', 35498, 35498, 35498, 1892, 19466, 1950, 4340, 'merit_only', 178, 10942, false, true, false, 'CDS G1/G5: tuition $35,498 (12-18 credits, two semesters), required fees $1,892 (includes the estimated U-Pass), food and housing $19,466, books $1,950, transportation $1,100 plus other $3,240 (other_usd = $4,340). CDS H6: 178 degree-seeking nonresidents received institutional aid averaging $10,942 (total $1,947,625); the CDS marks both need-based and non-need-based institutional aid as available to nonresidents.; International students are automatically considered for the renewable Columbia Excellence Award by high school GPA: 3.75+ $12,500; 3.30-3.74 $10,500; 3.00-3.29 $8,500 (amounts as printed on the international page). A competitive, renewable talent-based scholarship (up to four years) needs creative work samples in the intended major. The FAFSA is US citizens and permanent residents only. CDS H6 marks both need-based and non-need-based institutional aid as available to nonresidents, but the international page describes only merit and talent awards.', '15d6bff4-edba-572d-8905-e80666fd0d97');
insert into institution_tiers (institution_id, category_key, tier_code, rationale)
