insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, intl_applicants, intl_admits, in_state_applicants, in_state_admits, out_state_applicants, out_state_admits, pct_submit_sat, pct_submit_act, gpa_avg, pct_reporting_gpa, notes, source_id) values
 ('7c466251-3d10-59ed-a023-73ba15a4957c', '2024-2025', 3651, 3617, 1175, 15, 15, 3400, 3370, 236, 232, 13, 12, 3.18, 99.0, 'CDS 2024-2025 (fall 2024 entering class); the 2025-2026 edition was not posted on Columbus State''s CDS page. C1 residency split (in-state / out-of-state / international): applicants 3,400 / 236 / 15, admits 3,370 / 232 / 15, enrolled 1,084 / 85 / 6; the extracted PDF layout was garbled, but each row sums exactly to the printed totals (3,651 / 3,617 / 1,175). The GPA band distribution is omitted because the C11 column layout could not be read reliably; the C12 average of 3.18 is explicit. Only 13% submitted SAT and 12% ACT scores, so the score ranges describe a small self-selected group. The CDS C7 factor checkboxes were unreadable and are omitted. No early decision or early action; no waitlist.', 'd59c43cb-e063-5d29-9949-b177a4be3920');
insert into test_score_percentiles (institution_id, cds_year, source_id, test, p25, p50, p75)
