insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('852a57a1-f08c-52b4-94e1-bae80989c193', '2026-27', 'optional', 'Test-optional for 2027-28; applicants who submit a high school transcript receive full consideration for admission and scholarships. Some programs set their own requirements (e.g. SAT 1200+/ACT 25 to be considered for the accelerated 3+2 Physician Assistant interview, TEAS 65+ for Lock Haven ASN nursing, music audition). For international applicants an SAT of 980 (EBRW 500+) or ACT 20 can also satisfy English proficiency.', '12733d41-e552-5a4d-9442-4b7bf14b4f9d');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('852a57a1-f08c-52b4-94e1-bae80989c193', '2026-27', array['own']::text[], 35, 'Apply with the university''s own online application (one application can name one, two or all three campuses). $35 non-refundable fee, paid by credit card at submission. International first-years send official English-translated secondary records and certificates (unofficial copies may be uploaded first); the university may ask for a credential evaluation (WES, IERF, ECE or The Evaluation Company). The pages checked do not state essay or recommendation requirements.', 'b84a71b8-18e0-55a2-af99-263d9424f599');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('f936a68c-2970-58d9-bfee-9a3dfb6f4beb', '852a57a1-f08c-52b4-94e1-bae80989c193', '2026-27', 'application', 'ROLLING', 'International first-year application deadline, fall 2027 entry', '2027-06-01', 'International page prints ''Fall Semester: June 1st'' with no year (treated as fall 2027 entry). Spring semester is Nov. 1. Domestic applicants: most programs are rolling with no closing date (CDS C14).', 'b84a71b8-18e0-55a2-af99-263d9424f599'),
 ('e65f0516-9f04-5058-a803-cd9c01d39c5c', '852a57a1-f08c-52b4-94e1-bae80989c193', '2026-27', 'priority', null, 'Priority deadline for selective programs (nursing, accelerated health science, medical imaging)', '2026-11-15', 'Nov. 15 priority consideration for Nursing (BSN at Bloomsburg and Mansfield, ASN at Lock Haven), accelerated 3+2 PA and 3+3 PT, Medical Imaging; Music (BS/BM) is Dec. 15. Year not printed; taken as the 2027-28 cycle.', 'c5f64a97-61de-5b36-902a-61067d2c4091'),
 ('4b05ebf7-defd-5f6c-b1c2-5853fa9632ad', '852a57a1-f08c-52b4-94e1-bae80989c193', '2026-27', 'scholarship', null, 'International merit scholarship: complete application and pay deposit by May 1', '2027-05-01', 'Scholarship page: international students must complete their application and pay the deposit by May 1 of the senior year (year not printed; taken as 2027). Funding is limited and first come, first served.', 'ec5afd36-9e94-5dd9-8967-9b133a87f5c9');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('852a57a1-f08c-52b4-94e1-bae80989c193', 'required_nonnative', 'Not required for applicants from: American Samoa, Australia, Bahamas, Barbados, Belize, Canada (except Quebec), Dominica, Grenada, Grand Cayman, Ghana, Guyana, Ireland, Jamaica, Liberia, New Zealand, South Africa, Trinidad & Tobago, UK (England, N. Ireland, Scotland, Wales), U.S. Pacific Trust. Students with more than one semester of for-credit study at a U.S. institution may be exempt. Scores must come directly from the testing body. No conditional admission or ESL pathway program is described on the page.', 'b84a71b8-18e0-55a2-af99-263d9424f599');
