insert into cost_aid (institution_id, year, tuition_usd, tuition_out_of_state_usd, tuition_intl_usd, required_fees_usd, room_board_usd, books_usd, intl_aid_policy, intl_need_aid_awarded, intl_avg_award_usd, meets_full_need, merit_scholarships, notes, source_id) values
 ('852a57a1-f08c-52b4-94e1-bae80989c193', '2026-2027', 8338, 20846, 20846, 4227, 12538, 1200, 'merit_only', 31, 10413, false, true, 'CDS G1 (first-year, 2026-27; the CDS says final 2026-27 costs were due about Aug 1, 2026). Out-of-state and international tuition are the same ($20,846). CDS H6: institutional need-based aid is available to nonresidents (31 received it, avg $10,413) and non-need-based aid is marked ''No'', but the university''s scholarship page lists GPA-based merit scholarships for international students (see cycle file).; Scholarship page: GPA-based merit scholarships for international first-years who apply and pay the deposit by May 1; the page says award amounts will be finalized once the institutional aid budget is approved, so no amounts are given here. CDS H6 instead marks need-based (not non-need-based) institutional aid for nonresidents, with 31 recipients averaging $10,413. International students are not eligible for federal aid.', '7e67abc6-d0fc-5a20-9b1b-2bda6b8d0558');
