insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, pct_submit_sat, pct_submit_act, notes, source_id, source_note) values
 ('1bbe09ea-c82d-57d3-a188-7b59559c8497', '2023-2024', 1587, 1429, 381, 1, 6, 'No Common Data Set found on cune.edu (searched 2026-10-26), so this is the IPEDS baseline for the fall 2023 entering class (ADM2023). College Navigator''s newer fall 2024 figures: 1,583 applicants, 86% admitted, 25% of admitted enrolled (no admit count printed, so none is computed). Counts are institution-wide first-time students; IPEDS gives no international split or GPA data. Test-score percentiles rest on tiny groups (5 SAT and 18 ACT submitters in 2023). Undergraduate enrollment 3,000 (College Navigator fall 2024) is institution-wide and includes online students; the Seward campus itself has about 1,200 students per the international page. Student-to-faculty ratio 14:1.', '4a2e3de2-8ac5-5813-b7bb-9e91aed8d8be', 'admissions_site');
insert into test_score_percentiles (institution_id, cds_year, source_id, test, p25, p50, p75)
