insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, pct_submit_sat, pct_submit_act, notes, source_id, source_note) values
 ('c94c3281-178d-540d-badc-47c8d10093d4', '2024-2025', 2902, 2754, 618, 1, 3, 'Baseline from IPEDS fall 2024 (admit rate 94.9%). The 2025-2026 Common Data Set exists on csupueblo.edu but the www.csupueblo.edu host refused connections from this environment in several attempts, so no international split, GPA or residency data. Test scores from College Navigator cover only 18 ACT submitters (3%) and 4 SAT submitters (1%), so the ACT percentiles rest on a very small sample and SAT percentiles are not reported. International applicant counts are not published.', 'd41e1528-f175-5aa0-84fe-af8643b45ab0', 'admissions_site');
