insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('c94c3281-178d-540d-badc-47c8d10093d4', '2026-27', 'optional', 'First-year applicants are not required to submit SAT/ACT scores for admission; some scholarships may consider them and scores can help with math placement. Minimum cumulative weighted high school GPA 2.3 (4.0 scale); below 2.3 can still be admitted after a Statement Regarding Academic Performance. The catalog page states its standards for entry in Fall 2025, Spring 2026 or Summer 2026, so Fall 2027 rules are assumed unchanged.', '07ad687c-9c1e-5634-8c0f-e23802f0ed33');
insert into application_requirements (institution_id, cycle, platforms, supplemental_essays, app_fee_usd, notes, source_id) values
 ('c94c3281-178d-540d-badc-47c8d10093d4', '2026-27', array['own','common_app']::text[], 'Not listed as required.', 30, '$30 non-refundable fee for international undergraduate applicants ($25 on the first-year page; the FAQ says Colorado residents apply free). International applicants send official transcripts of all secondary or college work, evaluated by an approved credential agency (course-by-course, US GPA on a 4.0 scale), a passport copy and, for F-1/J-1 students, a financial statement (no dollar amount printed). First-year students must submit final transcripts showing graduation before the end of their first semester. Non-refundable $85 enrollment deposit.', '1885d763-8643-565f-ae26-36f6d98a4f08');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('be44e7d1-1b02-553c-ba99-72dbcfc88def', 'c94c3281-178d-540d-badc-47c8d10093d4', '2026-27', 'priority', null, 'Recommended application date for maximum scholarship eligibility', '2026-11-01', 'The FAQ recommends that high school seniors apply by November 1 of the senior year for maximum scholarship eligibility; the year is not printed (assumed the fall 2027 cycle).', '73678348-38fc-58b3-8daa-cf0d9dee20a2'),
 ('601b2c86-fdb5-5dcc-bbe9-754dabf5ec53', 'c94c3281-178d-540d-badc-47c8d10093d4', '2026-27', 'application', 'ROLLING', 'Fall semester preferred deadline (fall 2027 entry)', '2027-08-01', 'Catalog: ''preferred deadlines'' (fall Aug. 1, spring Jan. 2, summer Mar. 1), which the Office of Admissions may extend; the page prints no year and no separate international date, so it is treated as fall 2027. International applicants needing an F-1 visa should allow time for the financial statement and I-20.', '573d9765-53fe-59cd-977b-2389cded5d97');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('c94c3281-178d-540d-badc-47c8d10093d4', 'required_nonnative', 'Residents of the UK, Ireland, Australia, New Zealand and Canada are exempt. Other applicants may instead email a U.S. transcript showing full-time degree enrollment with a 2.5+ GPA for 2 or more semesters. A search extract of the Center for International Programs page says conditional admission is offered to applicants who lack English proficiency; the catalog page does not describe it.', '1885d763-8643-565f-ae26-36f6d98a4f08');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
select 'c94c3281-178d-540d-badc-47c8d10093d4'::uuid, 'required_option', '1885d763-8643-565f-ae26-36f6d98a4f08'::uuid, v.* from (values
 ('TOEFL_IBT', 61, 'Exams taken before 2026-01-21. Undergraduate nursing: 79-80. Paper-based TOEFL 500 also accepted (nursing 550).'),
 ('TOEFL_IBT_2026', 3.5, 'Exams taken after 2026-01-21 (1-6 scale). Undergraduate nursing: 4 (the nursing row prints the cutoff as 2026-01-26).'),
 ('IELTS', 5.5, 'IELTS Academic band score. Undergraduate nursing: 6.0.'),
 ('DUOLINGO', 95, 'Not accepted for undergraduate nursing, which requires 110 per the same table.')) v;
