insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('9f12f824-60d6-5b2e-9a12-4e2d8e67257b', '2026-27', 'optional', 'CUNY-wide: test optional for undergraduate admission; first-year applicants may choose whether to submit SAT or ACT scores and the absence of scores cannot be used to deny admission. College Navigator quotes the policy as in force through the spring 2027 semester; the CUNY page gives no end date, so fall 2027 entry is not separately confirmed. City Tech applies this policy (College Navigator note).', 'cb53611c-5d01-527b-a127-493fcb341669');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('9f12f824-60d6-5b2e-9a12-4e2d8e67257b', '2026-27', array['own']::text[], 65, 'Apply with the CUNY Application (one application, up to 6 CUNY colleges); freshman fee $65, non-refundable (CUNY-wide). Official transcripts go to CUNY; international applicants also send photocopies/translations per CUNY. City Tech minimums: associate programs need a high school diploma with a 70 average (Allied Health associate programs 75); bachelor''s programs need a 75 average. College Navigator lists GPA and school record as required, and essay and recommendations as not considered. A $100 tuition deposit is due after admission.', 'a00ec53a-eaf2-5f2f-a0fb-4a08d3cb09fa');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('949d7147-3061-5f2f-b1eb-0d00958bc856', '9f12f824-60d6-5b2e-9a12-4e2d8e67257b', '2026-27', 'priority', 'ROLLING', 'CUNY international applicant deadline - application (fall 2027 entry)', '2026-12-01', 'CUNY-wide: international applicants (those requesting a student visa or with credentials from outside the U.S.) must apply by December 1 and send supporting documents by December 15; decisions are rolling from January to July. The CUNY page prints no year, so treated as fall 2027. City Tech''s own pages show only the general date (Fall: February 1); the CUNY international column is used here.', '0cd0a8bf-13ce-55d6-94fd-fd7ba8b5bf78'),
 ('fc822f16-e12b-50d2-a6bf-a4fb22426f6b', '9f12f824-60d6-5b2e-9a12-4e2d8e67257b', '2026-27', 'other', 'ROLLING', 'CUNY international applicant deadline - supporting documents (fall 2027 entry)', '2026-12-15', 'CUNY-wide supporting-document date for international applicants.', '0cd0a8bf-13ce-55d6-94fd-fd7ba8b5bf78'),
 ('e43e5059-976d-5baf-8871-707c69217b70', '9f12f824-60d6-5b2e-9a12-4e2d8e67257b', '2026-27', 'priority', 'ROLLING', 'City Tech general freshman priority date (also shown on City Tech''s international page)', '2027-02-01', 'City Tech has rolling admissions and says to apply early. The CUNY page gives the international date as December 1; confirm with City Tech admissions which date applies to F-1 applicants.', '0c1e1b66-4d04-56f0-959c-3fa01a0932b6');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('9f12f824-60d6-5b2e-9a12-4e2d8e67257b', 'required_nonnative', 'CUNY-wide: applicants on a temporary (F-1) visa who were educated in a non-English-speaking environment must submit official TOEFL, IELTS (Academic), PTE (Academic) or Duolingo scores; the minimums are set by each college (CUNY comparison chart). Copies uploaded to the application are unofficial; scores must be sent by the testing agency (CUNY code 2950 on the CUNY page). No waiver rules are published on the CUNY page.', '11caa8fe-2e3b-541a-8c90-0d024c83309e');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
select '9f12f824-60d6-5b2e-9a12-4e2d8e67257b'::uuid, 'required_option', '11caa8fe-2e3b-541a-8c90-0d024c83309e'::uuid, v.* from (values
 ('TOEFL_IBT', 61, 'CUNY comparison chart (internet-based TOEFL); City Tech''s page agrees and also lists paper-based TOEFL 500. No score on the new 1-6 scale is given.'),
 ('IELTS', 6.0, 'IELTS Academic overall band; academic exam only.'),
 ('DUOLINGO', 85, 'CUNY comparison chart.'),
 ('PTE', 44, 'PTE Academic (CUNY comparison chart).')) v;
insert into score_codes (institution_id, test_key, code, notes, source_id)
select '9f12f824-60d6-5b2e-9a12-4e2d8e67257b'::uuid, v.* from (values
 ('sat', null, 'No SAT code is printed on the CUNY or college pages checked; pick the college by name in the College Board search.', 'cb53611c-5d01-527b-a127-493fcb341669'::uuid),
 ('act', null, 'No ACT code is printed on the CUNY or college pages checked; look it up at act.org.', 'cb53611c-5d01-527b-a127-493fcb341669'::uuid),
 ('toefl', '2950', 'CUNY-wide university code 2950 (CUNY application page: list this code when registering for exams). City Tech does not publish a separate code.', '0cd0a8bf-13ce-55d6-94fd-fd7ba8b5bf78'::uuid),
 ('ielts', null, 'No IELTS institution code is listed; send results to CUNY through the IELTS system.', '0cd0a8bf-13ce-55d6-94fd-fd7ba8b5bf78'::uuid),
 ('duolingo', null, 'No Duolingo institution code is listed.', '0cd0a8bf-13ce-55d6-94fd-fd7ba8b5bf78'::uuid),
