insert into cost_aid (institution_id, year, tuition_usd, tuition_out_of_state_usd, room_board_usd, books_usd, other_usd, total_coa_usd, meets_full_need, notes, source_id) values
 ('9f12f824-60d6-5b2e-9a12-4e2d8e67257b', '2024-2025', 7332, 15282, 22260, 1500, 6216, 37308, false, 'College Navigator 2024-25: tuition includes required fees; off-campus (City Tech has no campus housing) food and housing; total is the in-state off-campus figure (out-of-state off-campus $45,258). F-1/J-1 students pay the New York State non-resident rate. CUNY''s 2026-27 rates: $620 per credit non-resident, $3,465 per semester NYS resident full-time (12+ credits) plus fees.; International (F-1/J-1) students pay the NYS non-resident rate ($620 per credit in 2026-27, CUNY-wide). City Tech has a scholarships office, but no merit scholarship for international first-year students was found, so the policy is left null.', '6104b106-58e7-5323-9014-6748a0095c4f');
