 ('fb6f9272-6757-5e36-b5f4-1158e9d9bdf4', '17beae99-fcfb-53dd-b194-b252dde85241', 'financial_aid_site', 'CUNY - Undergraduate tuition and college costs (F-1/J-1 pay the NYS non-resident rate)', 'https://www.cuny.edu/financial-aid/tuition-and-college-costs/tuition-fees/', null, '2026-10-26'),
 ('87980837-9bcc-573a-aaab-e34551a68b54', '17beae99-fcfb-53dd-b194-b252dde85241', 'admissions_site', 'Medgar Evers College - International Applicant (deadlines, F-1 services)', 'https://www.mec.cuny.edu/admissions/international-applicant/', null, '2026-10-26'),
