insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, pct_submit_sat, notes, source_id, source_note) values
 ('17beae99-fcfb-53dd-b194-b252dde85241', '2023-2024', 11239, 9372, 757, 3, 'Baseline from IPEDS ADM2023 (fall 2023 entering class; exact counts). No Common Data Set was found on Medgar Evers'' institutional research page (it lists fact sheets and dashboards only), so no international split, GPA or residency data; international applicant counts are not published. College Navigator fall 2024: 12,015 applicants, 86% admitted, 6% of admits enrolled (admit counts not shown). SAT percentiles are for only 20 enrolled students (3%) who submitted SAT in fall 2024, so they are a thin sample. Mixed associate/bachelor''s college: IPEDS counts include associate-degree applicants.', 'c03bac8e-a998-56eb-9711-72b126173d05', 'admissions_site');
insert into test_score_percentiles (institution_id, cds_year, source_id, test, p25, p50, p75)
select '17beae99-fcfb-53dd-b194-b252dde85241'::uuid, '2024-2025', 'cb30562c-1a14-5e75-bf9e-d452b1aa3998'::uuid, v.* from (values
 ('SAT_ERW', 440, 480, 520),
