insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('17beae99-fcfb-53dd-b194-b252dde85241', '2026-27', 'optional', 'CUNY-wide: test optional for undergraduate admission; first-year applicants may choose whether to submit SAT or ACT scores. College Navigator quotes the policy as in force through the spring 2027 semester; the CUNY page gives no end date, so fall 2027 entry is not separately confirmed. Medgar Evers applies this policy (College Navigator note).', '5696af99-9204-580d-b02c-6e3a1df1c4c5');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('17beae99-fcfb-53dd-b194-b252dde85241', '2026-27', array['own']::text[], 65, 'Apply with the CUNY Application (one application, up to 6 CUNY colleges); freshman fee $65, non-refundable (CUNY-wide). Medgar Evers freshman requirements: official high school transcript (or GED/TASC) sent to CUNY, and a high school GPA of 65 or better (GED 2250 or TASC 2500). College Navigator lists GPA and school record as required, essay and recommendations as not considered. Medgar Evers is a mixed associate/bachelor''s college with 20+ majors.', '0e37220a-849e-5d7b-9019-3b49620ef719');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('5c3e20f7-2891-510b-9bd5-7017c7916ac7', '17beae99-fcfb-53dd-b194-b252dde85241', '2026-27', 'priority', 'ROLLING', 'International applicant deadline - application (fall 2027 entry)', '2026-12-01', 'Medgar Evers and CUNY both list the international freshman/transfer application deadline as December 1 and supporting documents by December 15, with rolling decisions January to July. The pages print no year, so treated as fall 2027. U.S.-educated freshmen use a February 1 priority date instead.', '87980837-9bcc-573a-aaab-e34551a68b54'),
 ('ec83c59f-e405-5377-9b0c-e31b8bdb2d4b', '17beae99-fcfb-53dd-b194-b252dde85241', '2026-27', 'other', 'ROLLING', 'International applicant deadline - supporting documents (fall 2027 entry)', '2026-12-15', 'Supporting-document date for international applicants (Medgar Evers international page, same as CUNY-wide).', '87980837-9bcc-573a-aaab-e34551a68b54');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('17beae99-fcfb-53dd-b194-b252dde85241', 'required_nonnative', 'CUNY-wide: applicants on a temporary (F-1) visa who were educated in a non-English-speaking environment must submit official TOEFL, IELTS (Academic), PTE (Academic) or Duolingo scores; minimums are set by each college (CUNY comparison chart). Scores must be sent by the testing agency (CUNY code 2950); copies uploaded to the application are unofficial. No waiver rules are published and no conditional-admission or ESL pathway is described on the pages checked.', 'f241dcb6-d535-59b9-aabe-945da7c3dde7');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
select '17beae99-fcfb-53dd-b194-b252dde85241'::uuid, 'required_option', 'f241dcb6-d535-59b9-aabe-945da7c3dde7'::uuid, v.* from (values
 ('TOEFL_IBT', 52, 'CUNY comparison chart (internet-based TOEFL), Medgar Evers row. No score on the new 1-6 scale is given.'),
 ('IELTS', 5.5, 'IELTS Academic overall band.'),
 ('DUOLINGO', 80, 'CUNY comparison chart.'),
 ('PTE', 41, 'PTE Academic (CUNY comparison chart).')) v;
insert into score_codes (institution_id, test_key, code, notes, source_id)
