 ('sat', null, 'No SAT code is printed on the CUNY or college pages checked; pick the college by name in the College Board search.', '5696af99-9204-580d-b02c-6e3a1df1c4c5'::uuid),
 ('act', null, 'No ACT code is printed on the CUNY or college pages checked; look it up at act.org.', '5696af99-9204-580d-b02c-6e3a1df1c4c5'::uuid),
 ('toefl', '2950', 'CUNY-wide university code 2950 (CUNY application page: list this code when registering for exams). Medgar Evers does not publish a separate code.', 'bf1db9aa-b33e-580d-b096-af227a57202c'::uuid),
 ('ielts', null, 'No IELTS institution code is listed; send results to CUNY through the IELTS system.', 'bf1db9aa-b33e-580d-b096-af227a57202c'::uuid),
 ('duolingo', null, 'No Duolingo institution code is listed.', 'bf1db9aa-b33e-580d-b096-af227a57202c'::uuid),
