insert into admission_stats (institution_id, cds_year, applicants, pct_submit_sat, notes, source_id, source_note) values
 ('d885527f-0a9b-5759-bdcc-91faf00629a7', '2024-2025', 14002, 7, 'Baseline from College Navigator (IPEDS fall 2024): 14,002 applicants, 92% admitted (rounded; the number of admits is not shown), 17% of admits enrolled. Admits and enrolled left null because only rounded percentages are published; no Common Data Set was found on CSI''s site (two attempts) and CSI is missing from the IPEDS ADM2023 file, so no exact counts, international split or GPA. CSI says the average high school average of its fall 2025 students was 87.9 (an average, not a cutoff).', 'b84cd77a-4566-5fea-b951-30863ad41b41', 'admissions_site');
