insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('d885527f-0a9b-5759-bdcc-91faf00629a7', '2026-27', 'optional', 'CUNY-wide: test optional for undergraduate admission; first-year applicants may choose whether to submit SAT or ACT scores and the absence of scores cannot be used to deny admission. College Navigator quotes the policy as in force through the spring 2027 semester; the CUNY page gives no end date, so fall 2027 entry is not separately confirmed. CSI''s freshmen page repeats that CUNY is test optional.', '41ca9863-c0b4-5ccd-b276-193f1e0e9ae0');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('d885527f-0a9b-5759-bdcc-91faf00629a7', '2026-27', array['own']::text[], 65, 'Apply with the CUNY Application (freshman), $65 non-refundable. International documents: photocopies of secondary school transcripts or marksheets, official transcripts from any U.S. high school, photocopy of the diploma or external exam certificates (e.g. CXC, GCSE, GCE, WASSCE), certified English translations, emailed to international@csi.cuny.edu; the application cannot be completed without them. Baccalaureate admission is a holistic review of grades and trends; the average high school average of fall 2025 students was 87.9 (not a cutoff). Applicants not admitted to a bachelor''s program may be offered an associate program (guaranteed to applicants with a high school or equivalency diploma) or request a baccalaureate appeal.', '8b7c8eb4-ba3a-5972-b1f7-20cc5118726b');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('e0bd23fa-122d-5d4d-95e1-72cd7870284f', 'd885527f-0a9b-5759-bdcc-91faf00629a7', '2026-27', 'priority', 'ROLLING', 'International first-year application deadline (fall 2027 entry)', '2026-12-01', 'Fall: application due December 1 and supporting documents due December 15 (CSI international page; same as the CUNY-wide international column). The pages print no year, so treated as fall 2027. CSI''s general admissions calendar shows February 1 as the (domestic) priority date, with first decisions March 15 and an April 30 end of the application period; the international dates above are used.', '8b7c8eb4-ba3a-5972-b1f7-20cc5118726b'),
 ('69da70ba-1f47-5bd6-aa88-88cfafe4b711', 'd885527f-0a9b-5759-bdcc-91faf00629a7', '2026-27', 'other', 'ROLLING', 'International supporting documents due (fall 2027 entry)', '2026-12-15', 'Transcripts/marksheets, diploma or exam certificates and English translations emailed to international@csi.cuny.edu.', '8b7c8eb4-ba3a-5972-b1f7-20cc5118726b'),
 ('2c013182-6b1f-5b19-8340-5ec25f29f5a7', 'd885527f-0a9b-5759-bdcc-91faf00629a7', '2026-27', 'deposit', 'RD', 'Fall deposit / national reply date', '2027-05-01', 'If admitted after May 1 the deposit is due 15 days after notification.', '4935513c-4e98-50c5-b62f-591dbbfaffb1');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('d885527f-0a9b-5759-bdcc-91faf00629a7', 'required_nonnative', 'Required if educated in a non-English-speaking environment; CSI asks applicants to email international@csi.cuny.edu to confirm before testing. Applicants without proof of English proficiency who are otherwise admissible can apply for conditional admission, meeting the requirement with CSI''s institutional TOEFL exam or through the English Language Institute (ELI).', '8b7c8eb4-ba3a-5972-b1f7-20cc5118726b');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
