 ('TOEFL_IBT', 45, 'Internet-based TOEFL; CSI''s minimum is the lowest of the CUNY four-year colleges on the CUNY chart (CUNY chart and CSI page agree). No score on the new 1-6 scale is given.'),
 ('IELTS', 5.0, 'IELTS Academic overall band; academic exam only.'),
 ('DUOLINGO', 75, 'CSI page and CUNY chart agree.'),
 ('PTE', 39, 'PTE Academic.')) v;
insert into score_codes (institution_id, test_key, code, notes, source_id)
select 'd885527f-0a9b-5759-bdcc-91faf00629a7'::uuid, v.* from (values
 ('sat', null, 'No SAT code is printed on the CUNY or college pages checked; pick the college by name in the College Board search.', '8fc7f1c2-94f9-5d62-9f4a-bae3d24e9440'::uuid),
 ('act', null, 'No ACT code is printed on the CUNY or college pages checked; look it up at act.org.', '8fc7f1c2-94f9-5d62-9f4a-bae3d24e9440'::uuid),
 ('toefl', '2778', 'CSI institutional code for score reporting is 2778 (CSI page); the CUNY-wide code on the CUNY page is 2950.', '8b7c8eb4-ba3a-5972-b1f7-20cc5118726b'::uuid),
 ('ielts', null, 'No IELTS institution code is listed; send results to CUNY through the IELTS system.', 'ed3eaeea-5348-59bf-bf52-7ba4d5b7f899'::uuid),
