 ('sat', null, 'No SAT code is printed on the pages reviewed; look it up in the College Board code search.', 'dbb03e62-322e-5e6c-a06d-73bbb9d92c40'::uuid),
 ('act', null, 'No ACT code is printed on the pages reviewed; look it up at act.org.', 'dbb03e62-322e-5e6c-a06d-73bbb9d92c40'::uuid),
 ('toefl', '6159', 'Institution code printed on the English test score sheet.', '06eba1ba-4e18-552a-9d53-2a414480c3a0'::uuid),
 ('ielts', null, 'No institution code is listed.', '06eba1ba-4e18-552a-9d53-2a414480c3a0'::uuid),
 ('duolingo', null, 'No institution code is listed.', '06eba1ba-4e18-552a-9d53-2a414480c3a0'::uuid),
