insert into cost_aid (institution_id, year, tuition_usd, required_fees_usd, room_board_usd, books_usd, other_usd, total_coa_usd, intl_aid_policy, intl_need_aid, merit_scholarships, notes, source_id) values
 ('0c99222f-7d00-530a-a8b3-5f60aa695cce', '2026-2027', 41190, 2370, 12898, 1290, 2892, 60640, 'need_aware_limited', true, true, 'DBU 2026/27 on-campus cost of attendance: block tuition $41,190 ($20,595 per semester, 12-18 hours), fees $2,370, housing $5,898 and meals $7,000 (budget estimates), books $1,290, other = transportation $1,150 + personal $1,650 + loan fees $92. The same rates apply to international students.; The larger international awards are restricted: International Academic Scholarships ($8,000-$14,000 a year, tuition only, by GPA/test/class rank, up to eight semesters) and the Christian Service Scholarship ($4,000 a year, plus up to $3,000 Christian Leadership) are open to students from Canada, Mexico, or affiliated with ACSI schools or DBU Global Community partner schools, and require on-campus housing. The International Student Scholarship, open to any new international student on need and merit, is generally a one-time grant of $500 to $2,500. International students are not eligible for federal aid. Percentages of aid recipients are not published for international students.', '5db49b02-9815-57b6-a068-b933e6cdffd9');
