insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('2d3f8334-1622-5d6c-b5d8-bb94e5907301', 'required_nonnative', 'Required if your first language is not English and your curriculum has not been delivered in English for at least two years. No minimum scores. TOEFL Essentials and TOEFL MyBest are not accepted; TOEFL iBT Home Edition and IELTS Indicator are accepted.', '8dc23489-9375-578b-b9e3-9fdedc054337');
