insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('7f6fd8d9-ae39-54ae-b057-c88033c8ea88', '2026-27', 'optional', 'Catalog and international page: high school applicants do not need to submit an SAT or ACT score for most undergraduate programs but may choose to; some programs may require one. A competitive SAT or ACT score can also serve as English proficiency for freshman applicants.', 'bde1432a-72f4-5dac-bcd5-59a559c4e84e');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('7f6fd8d9-ae39-54ae-b057-c88033c8ea88', '2026-27', array['common_app','own']::text[], 0, 'Apply on Detroit Mercy''s own application or the Common App. International freshman checklist: high school transcript, 250-word essay on any topic, one letter of recommendation (guidance counselor or teacher), bank statement showing funds for the first year, Statement of Financial Support form if the account is a sponsor''s, and a passport copy. CDS C13 (2024-25) says Detroit Mercy has no application fee; the admissions pages do not mention a fee. Some programs have earlier deadlines or extra requirements (5-year Physician Assistant and 7-year Dental: January 15).', 'bde1432a-72f4-5dac-bcd5-59a559c4e84e');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notification_date, notes, source_id) values
 ('99279450-00c8-5ef1-ac70-3522018a4991', '7f6fd8d9-ae39-54ae-b057-c88033c8ea88', '2026-27', 'application', 'EA', 'Early Action (fall 2027 entry)', '2026-11-01', '2026-12-01', 'Non-binding. The international page prints ''Early Action: November 1'' with no year; taken as fall 2027. The catalog says early action applicants are notified by December 1.', 'bde1432a-72f4-5dac-bcd5-59a559c4e84e'),
 ('b982bc61-c88f-5e99-9e3f-1f991081a58f', '7f6fd8d9-ae39-54ae-b057-c88033c8ea88', '2026-27', 'scholarship', null, 'Scholarship priority deadline', '2026-12-01', null, 'Applicants by this date are considered first for scholarships (catalog).', 'bde1432a-72f4-5dac-bcd5-59a559c4e84e'),
 ('bd924a7d-c578-50c6-a333-ebd448dd53f0', '7f6fd8d9-ae39-54ae-b057-c88033c8ea88', '2026-27', 'application', 'ROLLING', 'Regular/rolling admission deadline (fall 2027 entry)', '2027-03-01', null, 'Decisions are released as applications are completed; the international page urges applying early because of visa time. CDS C14 also lists March 1 as the closing date and December 1 as the priority date.', 'bde1432a-72f4-5dac-bcd5-59a559c4e84e');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('7f6fd8d9-ae39-54ae-b057-c88033c8ea88', 'required_nonnative', 'Not required for admission to most programs, but proficiency must be shown before classes start: citizenship of an English-official country, a degree from a U.S. or English-medium institution, a minimum test score, or (freshmen only) a competitive SAT or ACT score. Students without a qualifying score take an English placement test on arrival; those who do not pass must enroll in the American Language and Culture Program (ALCP) and may have to defer the start of classes a semester or more. ALCP classes do not count toward full-time status for scholarships. Nursing applicants must have TOEFL iBT 83 (4 on the new scale) on file before a decision.', '36af6891-6d6b-546b-a95c-44691fc65be3');
insert into english_requirements (institution_id, status, test_key, min_total, notes, source_id)
select '7f6fd8d9-ae39-54ae-b057-c88033c8ea88'::uuid, 'required_option', v.* from (values
 ('TOEFL_IBT', 81, 'Paper-based minimum 550. Nursing 83. Some older catalog pages (2024-25) list iBT 80; the 2026-27 catalog and the admission page say 81.', '36af6891-6d6b-546b-a95c-44691fc65be3'::uuid),
 ('TOEFL_IBT_2026', 4, 'The international page gives ''4 in the new scale'' alongside the 81 iBT minimum; nursing also 4 (83 on the old scale).', 'bde1432a-72f4-5dac-bcd5-59a559c4e84e'::uuid),
 ('IELTS', 6.5, 'Overall band score.', '36af6891-6d6b-546b-a95c-44691fc65be3'::uuid),
 ('DUOLINGO', 105, null, '36af6891-6d6b-546b-a95c-44691fc65be3'::uuid)) v;
