insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('b77cf73f-067f-55a3-a9b8-84bbaca99ff0', '2026-27', 'optional', 'Students with a weighted high school GPA of 2.8 or higher are not required to submit SAT/ACT; below 2.8 an ACT or SAT score is required (page text says ''Fall 2026 and Spring 2027''; the counselor page applies the same rule to Spring and Fall 2027). The international page lists SAT/ACT only as English-proficiency options.', '709b98a8-bd09-502c-be07-d1ac3b892e4f');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('b77cf73f-067f-55a3-a9b8-84bbaca99ff0', '2026-27', array['common_app','own']::text[], 75, 'Apply with the ECU application, CFNC or the Common App; rolling admission. International first-year applicants send official secondary-school records (officially translated into English) directly to international@ecu.edu, and non-US university coursework needs a course-by-course NACES evaluation. The international page does not list financial documents or a recommendation requirement.', 'aaf67c3b-f614-5d20-865d-ed9603b00146');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('4fda0d7f-5fee-560f-a33e-94c1d3d4e4ab', 'b77cf73f-067f-55a3-a9b8-84bbaca99ff0', '2026-27', 'priority', null, 'Priority freshman application deadline (fall 2027 entry)', '2026-11-01', 'Domestic freshman page; ECU has rolling admission. Spring 2027 term deadline is Dec 1, 2026.', '709b98a8-bd09-502c-be07-d1ac3b892e4f'),
 ('109a3dd1-9bc6-5ef0-ac23-3e7a44396b52', 'b77cf73f-067f-55a3-a9b8-84bbaca99ff0', '2026-27', 'scholarship', null, 'Deadline to be eligible to apply for other merit-based university scholarships', '2026-12-15', 'Freshman page wording. Scholarships are applied for through the ECUAWard portal after admission; which awards are open to international students is not stated.', '709b98a8-bd09-502c-be07-d1ac3b892e4f'),
 ('e2fbe272-7e6a-5b85-b37c-7ddd5fc5f717', 'b77cf73f-067f-55a3-a9b8-84bbaca99ff0', '2026-27', 'priority', null, 'Final freshman priority application deadline (fall 2027 entry)', '2027-04-01', 'Domestic freshman page.', '709b98a8-bd09-502c-be07-d1ac3b892e4f'),
 ('2303b34d-10a9-58ae-bb5d-18ff4cc84697', 'b77cf73f-067f-55a3-a9b8-84bbaca99ff0', '2026-27', 'application', 'ROLLING', 'International fall application deadline (fall 2027 entry)', '2027-06-30', 'International page: fall (August) applicants apply by June 30 each year, spring (January) applicants by Dec 15; ECU encourages applying 100 days before the term starts. The page prints no year, so fall 2027 is assumed.', 'aaf67c3b-f614-5d20-865d-ed9603b00146');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('b77cf73f-067f-55a3-a9b8-84bbaca99ff0', 'required_nonnative', 'Exempt: diploma from a US high school with two years of attendance; diploma from a high school in an exempt country (list not shown); or a B or better in an academic English writing/composition course at a US college. SAT EBRW 450 and ACT English/Writing 19 are also accepted as proof. An older ECU guide (2018) says applicants who meet academic requirements but not the English requirement can start in the ECU Language Academy (ECULA) under conditional admission; that guide''s minimums (TOEFL 71, Duolingo 95) are out of date versus the current page, so confirm with international@ecu.edu.', 'aaf67c3b-f614-5d20-865d-ed9603b00146');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
select 'b77cf73f-067f-55a3-a9b8-84bbaca99ff0'::uuid, 'required_option', 'aaf67c3b-f614-5d20-865d-ed9603b00146'::uuid, v.* from (values
 ('TOEFL_IBT', 71, 'Page wording: ''before 2026, a minimum score of 71''.'),
 ('TOEFL_IBT_2026', 4, 'Page wording: ''2026 onward, a minimum score of 4''; the page does not name the scale or iBT, so it is read as the new 1-6 scale.'),
 ('IELTS', 6.0, 'Overall minimum 6.0.'),
 ('DUOLINGO', 105, 'Current page lists 105 (the 2018 guide lists 95).')) v;
insert into score_codes (institution_id, test_key, code, notes, source_id)
