 ('act', '3094', 'ECU ACT code.', '709b98a8-bd09-502c-be07-d1ac3b892e4f'::uuid),
 ('toefl', null, 'The undergraduate pages list no TOEFL code. The Graduate School page gives ECU''s institutional code as 5180 (the same as the SAT code); confirm before sending.', '138666e4-5e4b-5d0e-a611-765cdba12253'::uuid),
 ('ielts', null, 'No institution code is listed.', 'aaf67c3b-f614-5d20-865d-ed9603b00146'::uuid),
 ('duolingo', null, 'No institution code is listed.', 'aaf67c3b-f614-5d20-865d-ed9603b00146'::uuid)) v;
insert into cost_aid (institution_id, year, tuition_usd, tuition_out_of_state_usd, tuition_intl_usd, required_fees_usd, room_board_usd, books_usd, intl_aid_policy, intl_need_aid, intl_need_aid_awarded, intl_avg_award_usd, meets_full_need, merit_scholarships, notes, source_id) values
 ('b77cf73f-067f-55a3-a9b8-84bbaca99ff0', '2024-2025', 4452, 20729, 20729, 2909, 11350, 1510, 'merit_only', false, 53, 19182, false, true, 'CDS G1 (2024-25, first-year): in-state tuition $4,452, out-of-state/nonresident $20,729, required fees $2,909, on-campus housing $6,498 + food $4,852 = $11,350; books $1,510. The CDS shows 2025-26 costs were not yet final. H6: 53 degree-seeking nonresident undergraduates received institutional aid (average $19,182, total $1,016,624); the CDS text does not show whether it was need- or non-need-based. The tuition_usd field is the in-state figure.; No international-specific scholarship, amount or need-based program is published on the pages read. Merit scholarships are applied for through the ECUAWard portal after admission (freshman deadline Dec 15, 2026 for eligibility); some also consider FAFSA need, which F-1 students cannot file. CDS H6: 53 nonresident undergraduates received institutional aid, average $19,182.', '679f1dd2-17ce-58a5-bb8f-5598ec239a40');
