insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, pct_submit_sat, pct_submit_act, notes, source_id, source_note) values
 ('30b8d056-c77f-5f72-8c70-f47ccc203ee1', '2023-2024', 9903, 8622, 2141, 7, 80, 'Baseline from IPEDS (fall 2023 entering class); no recent Common Data Set is published (ETSU''s CDS page lists only 2004-05 through 2010-11). College Navigator''s fall 2024 figures: 10,050 applicants, 86% admitted, 25% of admits enrolled; SAT 7% and ACT 76% of enrollees; middle-50% SAT EBRW 510-620, SAT Math 470-580, ACT composite 19-26. International applicant and admit counts, GPA and residency splits are not available. 10,829 undergraduates is the fall 2024 College Navigator count; the international undergraduate count is left blank (ETSU says nearly 350 international students of all levels, from 60+ countries).', '3734b3f5-b6d0-5837-8bbc-0ecde4a47024', 'admissions_site');
insert into test_score_percentiles (institution_id, cds_year, source_id, test, p25, p50, p75)
select '30b8d056-c77f-5f72-8c70-f47ccc203ee1'::uuid, '2023-2024', '3734b3f5-b6d0-5837-8bbc-0ecde4a47024'::uuid, v.* from (values
