insert into cost_aid (institution_id, year, tuition_usd, tuition_out_of_state_usd, tuition_intl_usd, required_fees_usd, room_board_usd, books_usd, other_usd, intl_aid_policy, intl_need_aid, intl_need_aid_awarded, intl_avg_award_usd, meets_full_need, merit_scholarships, notes, source_id) values
 ('03788304-1a02-55e9-929c-46778bc8c026', '2025-2026', 4790, 16940, 16940, 5236, 10950, 1240, 3398, 'need_aware_limited', true, 24, 9622, false, true, 'CDS G1/G5 (first-year; ''other'' is the resident-student figure). Tuition and fees are flat per year under the university''s guaranteed tuition plan; the university cost page for 2025-26 shows a slightly different non-resident tuition-and-fees total ($22,266 vs $22,176 here). H6: institutional need-based and non-need-based aid are both available to nonresidents; 24 received it (average $9,622, total $230,923).; CDS H6: institutional need-based and non-need-based aid are both available to degree-seeking nonresident undergraduates (24 recipients, average $9,622). The international admissions page describes no scholarship amounts, and the cost page lists no non-resident tuition waiver.', '35e79ea9-996f-558b-803d-aa74a6f77658');
