insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, pct_submit_sat, notes, source_id, source_note) values
 ('37e3a003-e2a7-59b9-9746-83376dac260e', '2025-2026', 12388, 8804, 798, 3, 'No current Common Data Set is posted (EIU''s CDS page stops at 2019-20), so this is a baseline: first-time freshman applications/acceptances/enrollments for fall 2025 from EIU Institutional Research''s Key Publication Facts (fall 2024 was 12,539 / 8,194 / 779). SAT percentiles and the 3% SAT-submission rate (22 students) are IPEDS fall 2024 via College Navigator; no ACT figures were reported. International applicant/admit counts, GPA and residency splits are not published in these sources. Undergraduate enrollment 4,058 is fall 2025 and excludes 2,673 high-school dual-credit students (College Navigator''s fall 2024 figure of 6,785 includes them).', '114767d2-c125-51ab-b4c8-3daa1565784c', 'admissions_site');
insert into test_score_percentiles (institution_id, cds_year, source_id, test, p25, p50, p75)
select '37e3a003-e2a7-59b9-9746-83376dac260e'::uuid, '2024-2025', '2f72086d-fb7e-59e1-8d34-82c7602a3f4d'::uuid, v.* from (values
 ('SAT_ERW', 460, 510, 560),
