insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('37e3a003-e2a7-59b9-9746-83376dac260e', '2026-27', 'optional', 'First-year applicants may apply without SAT/ACT: guaranteed admission with a 2.8 GPA and college-prep coursework; 2.5-2.79 is reviewed individually. With scores, the standard is a 2.5 GPA plus SAT 960 or ACT 18. The international undergraduate pages do not mention SAT/ACT.', '0f0f0c02-277f-54e4-ab96-6c63a585477e');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('37e3a003-e2a7-59b9-9746-83376dac260e', '2026-27', array['own']::text[], 30, 'International application fee is a non-refundable $30 (valid one year). Required: official secondary transcripts (the checklist says minimum 2.5 GPA on a 4.0 scale, the requirements page says 2.00), English proficiency scores or a waiver, financial affidavit with a bank statement showing one year of funding, and a passport copy. No I-20 is issued without official records. The page gives no year with the deadlines; treated as fall 2027.', 'e759277f-3e49-552e-b75d-bc3b3554d773');
insert into deadlines (id, institution_id, cycle, kind, label, due_date, notification_date, notes, source_id) values
 ('5688f71a-2a07-555d-92d1-02254bcc4b4c', '37e3a003-e2a7-59b9-9746-83376dac260e', '2026-27', 'application', 'International application deadline, fall term (fall 2027 entry)', '2027-05-15', null, 'The checklist prints ''May 15 for Fall Admission / November 1 for Spring Admission'' without a year; treated as fall 2027 (the spring 2028 deadline would be Nov. 1, 2027).', 'e759277f-3e49-552e-b75d-bc3b3554d773'),
 ('10eaa29b-3c29-591d-a600-a657592e3f3c', '37e3a003-e2a7-59b9-9746-83376dac260e', '2026-27', 'application', 'Nursing (prelicensure BSN) direct-entry application, opens Oct. 1', '2026-12-01', '2027-01-31', 'Competitive, limited seats, needs a 3.75 high-school GPA; decisions by Jan. 31. Dates have no year on the page; treated as for fall 2027 entry. Other pre-nursing students apply to the major by March 1 of freshman year.', 'effcaf4c-da1b-51c1-88ff-665183619023');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('37e3a003-e2a7-59b9-9746-83376dac260e', 'required_nonnative', 'Waived with 24 semester hours at a U.S. college, ELS Level 112 certificate, Language Company Level 9, Kaplan Proficiency Level, two consecutive years of study in an English-primary country within the past two years, or two terms of EAP Level 6 at SIU Carbondale CESL. Scores are valid two years. Conditional admission is possible for applicants who meet everything except the English requirement; they must then show English mastery to the Office of International Students and Scholars.', '5047a2bf-472c-58dd-a68c-92039cd653e0');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
