insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, pct_submit_sat, pct_submit_act, notes, source_id, source_note) values
 ('b256e2a3-2fd9-577c-9a7f-428106a5c807', '2024-2025', 17024, 13212, 2635, 1, 97, 'Baseline from IPEDS fall 2024 (admit rate 77.6%). No Common Data Set could be read: EKU''s Institutional Research data page is a login/JavaScript app and no CDS PDF was found in two attempts, so no international split, GPA or residency data. Test scores from College Navigator cover enrolled first-time students (2,561 ACT, 97%; only 9 SAT, 1%, so SAT percentiles are omitted). International applicant counts are not published.', 'fedba8a0-fb85-52b0-8937-17a544fc6112', 'admissions_site');
insert into test_score_percentiles (institution_id, cds_year, source_id, test, p25, p50, p75)
select 'b256e2a3-2fd9-577c-9a7f-428106a5c807'::uuid, '2024-2025', '79a21866-2a27-55ac-bf5c-a3c4cb7f41fc'::uuid, v.* from (values
