insert into major_admissions (id, institution_id, program, category_key, admit_model, notes) values
 ('bda89cb0-7e07-5998-af22-33121525a52c', 'b256e2a3-2fd9-577c-9a7f-428106a5c807', 'Nursing, Pre-RN Bachelor of Science in Nursing (BSN)', 'nursing', 'pre_major_competitive', 'Students enter as pre-baccalaureate nursing majors and apply after the first three semesters; admission is competitive (minimum EKU GPA 2.5, C or better in prerequisites). Fall applications due Mar. 31, spring Oct. 31. Seat count not published.');

