 ('SAT_ERW', 480, 540, 600),
 ('SAT_MATH', 440, 520, 570),
 ('ACT_COMPOSITE', 18, 23, 27),
 ('ACT_ENGLISH', 18, 21, 26),
 ('ACT_MATH', 16, 23, 26)) v;
insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('dd7d3e1b-ab8f-5e06-bf19-6cfb443a96b0', '2026-27', 'optional', 'IPEDS fall 2024 lists SAT/ACT as ''not required, but considered (test optional)''. The international scholarship has a higher award for applicants who submit a 25+ ACT or 1200+ SAT. SAT EBRW 480 or ACT English 19 can be used to meet the English requirement.', '8bf2aa6b-3b05-521b-9bdb-bcc7ca77957b');
insert into application_requirements (institution_id, cycle, platforms, notes, source_id) values
 ('dd7d3e1b-ab8f-5e06-bf19-6cfb443a96b0', '2026-27', array['own']::text[], 'Apply through EMU''s own application (app.emich.edu). Decisions can be made on academic performance, but admission is not final until the English requirement is met and the I-20 process is complete. Application fee, GPA minimums and document lists were not read: emich.edu blocks automated access, and these notes come from search-result excerpts of the EMU pages, so verify on the page.', '9a3b3854-5f84-580f-8fa1-11f57f704dbe');
insert into deadlines (id, institution_id, cycle, kind, label, due_date, notes, source_id) values
 ('01885732-8deb-57ca-9b7f-f766b4e55075', 'dd7d3e1b-ab8f-5e06-bf19-6cfb443a96b0', '2026-27', 'application', 'International fall application deadline (fall 2027)', '2027-06-24', 'Search-result excerpt of EMU''s international undergraduate deadlines: fall 2027 applications due June 24, 2027 and financial documents for the I-20 due July 8, 2027 (winter 2027: Nov 11, 2026). EMU''s general undergraduate pages describe rolling admission; confirm the date with international admissions.', '877306a9-61d6-55f4-9cee-377d1c6f15bc');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('dd7d3e1b-ab8f-5e06-bf19-6cfb443a96b0', 'required_nonnative', 'SAT EBRW 480 or ACT English 19 can replace an English test. Waivers depend on the country where the education took place, regardless of the language of instruction. Admission can be offered before the English requirement is met, but it is not finalized until it is met. The pages read do not name a specific ESL or pathway program.', '9a3b3854-5f84-580f-8fa1-11f57f704dbe');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
select 'dd7d3e1b-ab8f-5e06-bf19-6cfb443a96b0'::uuid, 'required_option', '9a3b3854-5f84-580f-8fa1-11f57f704dbe'::uuid, v.* from (values
 ('TOEFL_IBT', 71, null),
 ('IELTS', 6.0, 'IELTS Indicator also accepted. Michigan English Test (MET) 53 is also accepted.'),
 ('DUOLINGO', 105, null),
 ('PTE', 50, null)) v;
insert into score_codes (institution_id, source_id, test_key, notes)
select 'dd7d3e1b-ab8f-5e06-bf19-6cfb443a96b0'::uuid, '9a3b3854-5f84-580f-8fa1-11f57f704dbe'::uuid, v.* from (values
 ('sat', 'EMU''s international pages read did not print an SAT code; look it up in the College Board code search.'),
 ('act', 'EMU''s international pages read did not print an ACT code; look it up at act.org.'),
 ('toefl', 'The EMU pages read did not print a TOEFL code; EMU accepts a copy of the official result emailed to admissions for verification.'),
 ('ielts', 'No institution code is listed.'),
