insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('09b10dd7-9a83-5110-87d2-4fa5d134884a', '2026-27', 'optional', 'Test-optional: applicants do not need to submit SAT or ACT scores to be considered; the international page lists SAT/ACT only as English-proficiency alternatives. Admission looks at grade trends from freshman through junior year and course rigor; at the Admission Review Board''s discretion an applicant may be asked for an interview, essay or teacher evaluation form. No minimum GPA is published.', 'a4ab7e08-c327-5b58-b3e9-677db54f2fd9');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('09b10dd7-9a83-5110-87d2-4fa5d134884a', '2026-27', array['common_app','own']::text[], 0, 'No application fee. International first-year file: application, secondary transcript for all years (certified English translation if needed), IB/AP/CLEP scores if any, proof of English proficiency, then Declaration of Finances and Affidavit of Support (collected Mar. 1-Jun. 1 for fall). Fall I-20s are sent from June 1. Some majors require an audition or portfolio.', '1d3f35e7-8b9c-5778-85c7-7fe77c63f92d');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('8647d1df-e04f-5393-bd04-68b196ba5e1b', '09b10dd7-9a83-5110-87d2-4fa5d134884a', '2026-27', 'application', 'ROLLING', 'International first-year application window closes (fall 2027 entry)', '2027-05-01', 'Page says apply between September 1 and May 1, or until all spaces are filled, with no priority date. No year is printed; taken as the fall 2027 cycle (opens Sep 1, 2026). Spring entry: Aug 1 to Nov 1.', '1d3f35e7-8b9c-5778-85c7-7fe77c63f92d');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('09b10dd7-9a83-5110-87d2-4fa5d134884a', 'required_nonnative', 'Waived for citizens who attended high school in listed English-speaking countries (e.g. Canada''s English-speaking provinces, Australia, Ireland, UK, Jamaica); also for two semesters of U.S. college English (B or better), an American international school with passing English grades, an English-language IB program, South Korean CSAT English 1, or (I)GCSE English First Language C/4 / A-level English C. SAT EBRW 520 or ACT English and Reading 22 also satisfy the requirement. No conditional admission or ESL pathway is mentioned on the page.', '1d3f35e7-8b9c-5778-85c7-7fe77c63f92d');
