insert into cost_aid (institution_id, year, tuition_usd, required_fees_usd, room_board_usd, books_usd, intl_aid_policy, intl_need_aid, meets_full_need, merit_scholarships, notes, source_id) values
 ('09b10dd7-9a83-5110-87d2-4fa5d134884a', '2026-2027', 45258, 600, 13170, 1290, 'merit_only', false, false, true, 'Full-time undergraduate tuition $45,258 (2026-27), student fee $300 per term, room $7,454 plus 17-meal board $5,716.30; first-year students also pay a $275 matriculation fee. The cost-of-attendance page lists different room ($8,150) and food ($7,880) estimates, so budgets can differ from billed charges.; Tuition, student fee ($300 per term) and room/board from Elmhurst''s 2026-27 tuition page (room $7,454 + 17-meal board $5,716.30, rounded); books from its cost-of-attendance page. New full-time first-year students also pay a one-time $275 matriculation fee. Private university: no separate international tuition.; International first-year awards need no separate application and are based on the admission application: International Chairman''s Award up to $20,000 and International Discovery Award $1,000-$5,000 (academic merit), plus international student tuition grants (amounts not listed). The overview page says merit awards can be worth up to $20,000 per year. International students are not eligible for federal aid.', '9761ec6c-95a2-5562-86a4-6c3909680063');
insert into institution_tiers (institution_id, tier_code, category_key, rationale)
