insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('155e099a-d60f-5245-8ac1-8def9a091d6d', '2026-27', 'optional', 'ACT or SAT scores are not required for undergraduate international applicants (except athletes); submitting them can qualify students for academic scholarships.', 'a63fea35-beaf-5598-9831-bf04e24fbdb3');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('155e099a-d60f-5245-8ac1-8def9a091d6d', '2026-27', array['own']::text[], 60, 'Own online application; $60 non-refundable fee. New freshmen need completion of secondary school with a cumulative GPA of 2.5 or better (converted to the US scale). Steps: apply, apply for scholarships, receive admission package, apply for visa. Essays and recommendations are not listed.', 'a63fea35-beaf-5598-9831-bf04e24fbdb3');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('4da58d19-6ee0-55ee-b38b-16960f8f9672', '155e099a-d60f-5245-8ac1-8def9a091d6d', '2026-27', 'application', 'ROLLING', 'International fall 2027 application deadline', '2027-05-01', 'Rolling admission; the cost page prints Fall: May 1 without a year (treated as 2027). Spring: Oct. 1; summer: March 1.', '73dac77d-8ea8-5635-ae10-dd5061666e58');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('155e099a-d60f-5245-8ac1-8def9a091d6d', 'required_nonnative', 'Proficiency is shown by citizenship of Australia, Belize, Canada (except Quebec), Commonwealth Caribbean, Ghana, Ireland, Liberia, New Zealand, Nigeria, UK or US; a degree completed in one of those countries; or four years of Cambridge International curriculum / two years of AS or A level. Scores below the exemption level do not necessarily block admission: students are tested at orientation and may receive an I-20 for the Intensive English Program (IEP) first. Scores may be submitted until the first day of international orientation.', '39501620-ef98-5140-a0a8-2934aa6db940');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, min_subscores, notes)
