 ('TOEFL_IBT', 72, '{"each_section": 15}'::jsonb, 'This is the exemption level from the ESU English placement test (academic I-20); no new 1-6 scale value is listed.'),
 ('IELTS', 6.0, '{"each_section": 5.5}'::jsonb, 'Exemption level.'),
 ('DUOLINGO', 95, null, 'Exemption level.'),
 ('PTE', 49, '{"each_section": 40}'::jsonb, 'Exemption level.')) v;
