insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, intl_applicants, intl_admits, in_state_applicants, in_state_admits, out_state_applicants, out_state_admits, pct_submit_sat, pct_submit_act, gpa_avg, pct_reporting_gpa, gpa_distribution, notes, source_id) values
 ('fba2b72a-0833-5d07-991f-bb06848c19be', '2024-2025', 10748, 6802, 1822, 17, 13, 10497, 6639, 234, 150, 19, 2, 3.27, 99, '{"4.0": 13, "3.75-3.99": 9, "3.50-3.74": 17, "3.25-3.49": 12, "3.00-3.24": 20, "2.50-2.99": 25, "2.0-2.49": 4, "1.0-1.99": 0}'::jsonb, 'CDS C1 (fall 2024 first-year class; residency by known physical address): only 17 international applicants (13 admitted, 1 enrolled) and 234 other out-of-state applicants, so Farmingdale is overwhelmingly a Long Island/New York commuter college and the international admit rate rests on a tiny sample. 19% (340 students) submitted SAT and 2% (35) ACT. The GPA bands were read from the PDF text in high-to-low order and agree with the 3.27 average. No early decision/early action. Undergrad enrollment (10,007) is from College Navigator, fall 2024 (3% nonresident, no headcount).', '0deb0092-1c88-5d67-a5d0-40f4a8558cba');
insert into test_score_percentiles (institution_id, cds_year, source_id, test, p25, p50, p75)
