insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('fba2b72a-0833-5d07-991f-bb06848c19be', '2026-27', 'optional', 'The admissions FAQ states ''Farmingdale is now SAT/ACT optional''. Some programs still list scores: the admission chart gives SAT 1100 or ACT 22 for the Dental Hygiene entry-level BS.', '2f6381ba-1c23-561a-ba7c-c3c6b2730521');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('fba2b72a-0833-5d07-991f-bb06848c19be', '2026-27', array['common_app','own']::text[], 50, 'SUNY Application or Common App, $50 fee (the FAQ says fee waivers exist but also that a state campus cannot waive it; unresolved). Official high school transcript required; recommendation letters and a personal statement are highly recommended, not required. Coursework from outside the US needs a NACES credential evaluation (''applications lacking a NACES evaluation will not be reviewed''); international applicants also submit the SUNY autobiographical essay and passport copy. Applicants are typically notified about two weeks after all documents arrive.', '71aa9ace-d38c-5633-9601-699d1b67fd7e');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('0e79c706-5b0d-5f99-b41a-44190821ef7b', 'fba2b72a-0833-5d07-991f-bb06848c19be', '2026-27', 'application', 'ROLLING', 'Fall application deadline, fall 2027 entry (domestic and international)', '2027-06-01', 'Fall June 1 and spring Nov. 1 (international page) / Jan. 3 (first-year page); no year is printed, so treated as fall 2027. Rolling admissions. The 2024-25 CDS also lists a priority date of Jan. 3.', 'ad9482ac-4a46-5565-b541-80cb46d8da79'),
 ('5d164392-973c-51ce-a66f-49cde7358d35', 'fba2b72a-0833-5d07-991f-bb06848c19be', '2026-27', 'application', null, 'Earlier deadline for Nursing and Professional Pilot (fall 2027)', '2027-01-15', 'Dates page: Nursing application and document deadline January 15 (TEAS by February 15); Professional Pilot application January 15, documents February 1; Dental Hygiene first priority January 15. No year printed; treated as fall 2027.', '4795ed39-7d12-51c1-ab71-ba8e81e29b16'),
 ('bcae75bb-0464-5d4a-ab42-3bea6c175908', 'fba2b72a-0833-5d07-991f-bb06848c19be', '2026-27', 'deposit', null, 'Tuition deposit ($100)', '2027-05-01', 'Due May 1, or within 30 days of acceptance for students accepted after April 1.', '2f6381ba-1c23-561a-ba7c-c3c6b2730521');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('fba2b72a-0833-5d07-991f-bb06848c19be', 'required_nonnative', 'The only alternative listed is an official transcript from an accredited US college with C+ or better in a college-level writing course. Scores must be within two years before the application term. The SAT Evidence-Based Reading score of 400 is also listed as accepted proof.', 'cd538bbf-911c-52f5-b308-85d0207aac42');
