insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, pct_submit_sat, pct_submit_act, notes, source_id, source_note) values
 ('680e7294-5030-558a-92ad-40ef25b62fa9', '2024-2025', 6515, 5352, 794, 2, 8, 'Baseline from IPEDS fall 2024 (exact counts from the NCES ADM2024 file via the Urban Institute Education Data Portal; nonresident-alien undergraduates from NCES IPEDS fall 2024 enrollment by race (same portal)). No Common Data Set could be found on the university''s institutional effectiveness pages, so international applicants/admits, GPA and admission factors are not included. SAT/ACT ranges cover enrolled first-time students who submitted scores (SAT 2%, ACT 8%). Undergraduate enrollment 6,074 and 90 nonresident-alien undergraduates are IPEDS fall 2024; College Navigator prints the student-to-faculty ratio as 20 to 1.', 'cfafe99b-6e09-5225-ad2b-70e5dfee2056', 'admissions_site');
