insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('680e7294-5030-558a-92ad-40ef25b62fa9', '2026-27', 'optional', 'Freshman page: applicants with a weighted high school GPA of 2.50 up to (not including) 2.80 must submit an ACT of 17+ or SAT of 930+; no test requirement is listed for other applicants. The international page says SAT/ACT is required if the calculated GPA is between 2.5 and 2.8 (GPA must be at least 2.5).', 'a0d923fd-ca39-5471-a00b-2a490b9da8e7');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('680e7294-5030-558a-92ad-40ef25b62fa9', '2026-27', array['own']::text[], 50, 'Apply through the Broncoville portal, NC Connect (CFNC) or Choose NC; $50 non-refundable fee. Letters of recommendation are not required. International applicants also need transcripts with a course-by-course evaluation and GPA calculation from a NACES member (Atlas Credential Evaluations also accepted) and financial documents: the page says proof of funding for at least one academic year for admission, and, in a separate section, four academic years for the I-20; confirm with the Office of International Programs.', '764f35e0-b3ab-5027-a0b9-b2a7c7f72504');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('14907afa-3dbe-5a65-9d84-237451813266', '680e7294-5030-558a-92ad-40ef25b62fa9', '2026-27', 'application', 'RD', 'Fall 2027 first-year application deadline (general; no separate international date published)', '2027-07-30', 'The dates page, titled for Spring, Summer and Fall 2027, lists July 30 for fall first-year applicants. No separate international undergraduate deadline is printed (the only international deadline listed is March 1 for graduate applicants), so confirm timing for the I-20 with the Office of International Programs.', 'e94102fe-44cb-53c9-b39c-13539340b364'),
 ('53d1e481-348b-5480-8980-4c5a783772ef', '680e7294-5030-558a-92ad-40ef25b62fa9', '2026-27', 'scholarship', null, 'Scholarship application deadline (portal opens October 31, 2026)', '2027-03-01', 'First-year applicants are automatically considered for merit scholarships; whether international students qualify is not stated.', 'e94102fe-44cb-53c9-b39c-13539340b364');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('680e7294-5030-558a-92ad-40ef25b62fa9', 'required_nonnative', 'The international page lists English proficiency scores ''(If applicable)'' and prints no exemption list. An older International Education Center page says a TOEFL report is required unless the applicant is from an official English-speaking country (countries not listed on that page).', '764f35e0-b3ab-5027-a0b9-b2a7c7f72504');
