insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, pct_submit_sat, notes, source_id, source_note) values
 ('0e3ee02e-3db2-5c38-8ea3-6c4800d64363', '2023-2024', 4259, 4085, 606, 1, 'Baseline from IPEDS via College Navigator (fall 2024, Metropolitan Campus only): 5,826 applicants, 91% admitted, 12% of admits enrolled; admit and enrollee counts are not printed, so they are left null. The Common Data Set is published for the whole university (Metropolitan plus Florham: 11,478 applicants, 10,665 admitted) and has no international split, so it is not used for campus figures. Only 4 enrolled first-years (1%) submitted SAT scores, so SAT/ACT percentiles are not reported. Undergraduate enrollment 5,690 is fall 2024. Applicant/admit/enrolled counts replaced with exact IPEDS ADM2023 (fall 2023) figures, because the newer source gives only a rounded admit rate.', 'df2110c3-e9ab-5403-9a3d-5595746569b4', 'admissions_site');
insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('0e3ee02e-3db2-5c38-8ea3-6c4800d64363', '2026-27', 'optional', 'Freshman admissions page: standardized test scores are optional, except for several partnership programs (for example the joint 8-year program with LECOM, per College Navigator). For English, SAT EBRW 480 or ACT English 22 is also accepted by the English proficiency page.', '7f2d7ef0-dc6e-549c-bef8-73c215d43eb1');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('0e3ee02e-3db2-5c38-8ea3-6c4800d64363', '2026-27', array['common_app','own']::text[], 50, 'International applicants (anyone needing a visa) apply through FDU''s international application (fdu.edu/myintlapp); Common App is used by U.S. citizens. Needs academic records from all secondary schools, English test or exemption, two academic letters of recommendation, passport copy, and bank statement plus affidavit of support for F-1. The $50 fee is from College Navigator and the CDS; the international pages do not state a fee.', 'fe486ee3-7d27-554a-9a28-755d71ad24ca');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('09819629-82a9-5242-946a-4fb17bc53c04', '0e3ee02e-3db2-5c38-8ea3-6c4800d64363', '2026-27', 'application', 'ROLLING', 'International fall 2027 application deadline', '2027-07-01', 'Rolling admissions, allow 3-4 weeks for processing. Spring (January) deadline is December 1. The page prints no year; taken as fall 2027. Applicants already living in the U.S. have an August 1 fall date on the pathway page. Deadlines may vary by program.', '653e31a9-bfcd-5e07-beb0-670634dbdea2');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('0e3ee02e-3db2-5c38-8ea3-6c4800d64363', 'required_nonnative', 'Exempt at application with: U.S. college English Composition I (C or higher); two years at a U.S. high school with passing college-prep English; or at least two years of study in a listed English-speaking country (UK, Ireland, Canada except Quebec, Australia, New Zealand, Nigeria, Singapore and others). New students may still be tested at orientation and placed in the English for Professional Success (EPS) course.', 'b3602e2e-de69-5ee8-9e5e-1974e5a34b8d');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
select '0e3ee02e-3db2-5c38-8ea3-6c4800d64363'::uuid, 'required_option', 'b3602e2e-de69-5ee8-9e5e-1974e5a34b8d'::uuid, v.* from (values
 ('TOEFL_IBT', 70, 'Regular (direct) admission. The Pre-University Program accepts 50; conditional admission needs no new score.'),
 ('TOEFL_IBT_2026', 4.5, 'The page prints 70/4.5 for TOEFL iBT without naming the scale; 4.5 is read as the new 1-6 band score. Pre-University Program 3.5.'),
 ('IELTS', 6.0, 'Regular admission. Pre-University Program 5.'),
 ('DUOLINGO', 100, 'Regular admission. Pre-University Program 80.'),
 ('PTE', 53, 'PTE Academic. Pre-University Program 45.')) v;
