insert into cost_aid (institution_id, year, tuition_usd, tuition_out_of_state_usd, tuition_intl_usd, required_fees_usd, room_board_usd, books_usd, intl_aid_policy, intl_need_aid, intl_need_aid_awarded, intl_avg_award_usd, meets_full_need, merit_scholarships, notes, source_id) values
 ('99030f47-acca-5a5f-a607-18966c80d0cc', '2025-2026', 4191, 22328, 22328, 1927, 10102, 1200, 'merit_only', false, 179, 10330, false, true, 'CDS G1 (2025-26, first-year): in-state tuition $4,191, non-resident tuition $22,328, required fees $1,927, on-campus food and housing $10,102; G5 books $1,200, transportation $2,750, other $2,750. College Navigator lists out-of-state tuition and fees of $25,162 (about $900 more than the CDS sum). H6: only non-need-based institutional aid is available to nonresidents; 179 received it (avg $10,330).; International students are not eligible for federal aid. Per the CDS (H6), 179 nonresident undergraduates received non-need-based institutional aid averaging $10,330; the admissions pages publish no international merit amounts. Global Learning Grant: up to $500 per semester for F-1/F-2/H-1B students who have completed two semesters at FGCU.', '7da6a947-d840-533a-b55a-f05e9aeefd6c');
