insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, notes, source_id, source_note) values
 ('9e45c152-3ff6-59c2-8160-dd2406c37d95', '2023-2024', 3760, 3246, 613, 'Baseline from College Navigator (IPEDS fall 2024 entering class): 4,065 applicants, 83% admitted, 17% of admitted enrolled; exact admit and enrolled counts and SAT/ACT percentiles are not shown, so they are left null. A Common Data Set could not be found (the Institutional Research page links an IPEDS Data Feedback Report, not a CDS). About 2% of undergraduates are U.S. nonresidents (rounded percentage, so no count is given). Undergraduate enrollment 4,062 is the fall 2024 total. Applicant/admit/enrolled counts replaced with exact IPEDS ADM2023 (fall 2023) figures, because the newer source gives only a rounded admit rate.', 'c2ffafa0-1b90-573f-b14f-49e3403109d6', 'admissions_site');
insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('9e45c152-3ff6-59c2-8160-dd2406c37d95', '2026-27', 'optional', 'ACT/SAT are optional; if submitted they are considered for merit scholarships and scholarship competition days and cannot lower merit aid. The international page says the ACT or SAT is not required. Minimum GPA: the international page says 2.0 on a 4.0 scale, while the main first-year page says 3.0 cumulative; confirm with the admissions office.', 'fe3a466b-1fcb-5eec-a905-5938f39335d9');
insert into application_requirements (institution_id, cycle, platforms, notes, source_id) values
 ('9e45c152-3ff6-59c2-8160-dd2406c37d95', '2026-27', array['own']::text[], 'Apply through the university''s own portal (apply.findlay.edu). The application fee is not stated on the pages read (other search snippets conflict), so it is left null. International freshmen need high school transcripts and leaving certificate or diploma, a passport bio page copy, and a bank statement showing funds for at least the first year. No personal essay or recommendation letters are mentioned on the first-year page.', '6567686b-29e1-50ec-88ab-8e065d5f5e19');
insert into deadlines (id, institution_id, cycle, kind, label, due_date, notes, source_id) values
 ('bc0fb297-d2fc-57d3-9f9d-189bfd2cff26', '9e45c152-3ff6-59c2-8160-dd2406c37d95', '2026-27', 'application', 'International application deadline, fall (August) start (fall 2027 entry)', '2027-06-20', 'The international criteria page lists Fall: June 20 and Spring: November 10 without a year, so the dates are treated as fall 2027. Start terms are Fall (August) and Spring (January). The first-year page lists no deadlines.', '6567686b-29e1-50ec-88ab-8e065d5f5e19');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('9e45c152-3ff6-59c2-8160-dd2406c37d95', 'required_nonnative', 'No test needed for citizens of, or those who completed studies in, the UK, USA, Canada, Australia, Ireland, New Zealand or Ghana (Ghanaian high school degrees). Graduates of an English Medium high school with school verification are exempt; English Version schools must show CEFR B2 equivalent, ACT 20 or SAT 1040 and complete the Foundations/Bridge Program in year one. Students below the direct-admit score can enter the Intensive English Language Program (IELP, four levels, about one semester each, classes start fall, spring and an 8-week summer ELS section); completing IELP waives the test requirement. New USCIS rules mean IELP students get an IELP-only I-20 first. Students with no score and no waiver take Accuplacer at orientation.', 'e41164e2-0134-5209-b87c-3a22ce2ef3d5');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
select '9e45c152-3ff6-59c2-8160-dd2406c37d95'::uuid, 'required_option', '6567686b-29e1-50ec-88ab-8e065d5f5e19'::uuid, v.* from (values
 ('TOEFL_IBT', 61, 'Undergraduate direct admission. Some older pages still show 500 (paper scale).'),
 ('IELTS', 6.0, 'Undergraduate direct admission.'),
 ('DUOLINGO', 95, 'Listed on the criteria and waiver pages; some pages omit Duolingo.'),
 ('PTE', 50, 'PTE Academic. iTEP 3.5 and completion of Level 8 of The Language Company are also accepted.')) v;
insert into cost_aid (institution_id, year, tuition_usd, tuition_out_of_state_usd, tuition_intl_usd, required_fees_usd, room_board_usd, books_usd, other_usd, total_coa_usd, intl_aid_policy, intl_need_aid, intl_merit_aid, merit_scholarships, notes, source_id) values
 ('9e45c152-3ff6-59c2-8160-dd2406c37d95', '2026-2027', 40698, 40698, 40698, 1500, 13740, 1000, 1544, 56868, 'merit_only', false, true, true, '2026-27 undergraduate on-campus estimate (standard program, before aid): tuition $40,698, mandatory fees $1,500, housing $7,120 plus food $6,620, books and supplies $1,000, miscellaneous personal $1,544, transportation $1,030 (not included in other). The page shows no total, so total_coa is left null. Pharmacy, Equestrian and Animal Science programs have different rates.; College Navigator 2024-25 (superseded by the 2026-27 figures in the cycle file): tuition and fees $41,164; on-campus room and board $11,200; books $2,000; other $2,504.; International undergraduate merit scholarships (2026-27) are applied automatically at admission with no separate application: Trustee $25,000 (GPA 4.0+, ACT 27/SAT 1290), Presidential $24,000 (3.9; 24/1190), Deans $22,500 (3.65; 21/1090), Faculty $20,000 (3.3), Merit $18,500 (3.29 or lower); a 30 ACT or 1360 SAT adds $2,000, and the highest applicable amount is used. Renewal terms are not stated. IELP students receive $750 per semester. No international need-based aid is described.', 'c5036c85-f649-5054-8ada-546424ae618b');
