insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('6308ba22-3cfb-5c56-93cf-a663b1bb0853', '2026-27', 'optional', 'First-year applicants: test-optional (not test-blind) with a ''Do No Harm'' approach, so submitted scores are used only if they help. Homeschooled and GED applicants cannot use the test-optional path. International applicants must still show English proficiency with SAT, ACT, TOEFL, IELTS, Duolingo or listed national exams, and official scores must be submitted with the application.', 'b0d1d704-bd6f-5635-a05d-fa386dd80760');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('6308ba22-3cfb-5c56-93cf-a663b1bb0853', '2026-27', array['common_app','own']::text[], 50, '$50 first-year application fee. Transcripts sent electronically by the school (email, Parchment, SCOIR or Common App), an essay of at least 250 words, test scores or English proficiency evidence, and credit evaluation from a NACES service for non-US study. The international page calls teacher/counselor recommendations optional but recommended; the first-year page says one academic recommendation is required, so plan to submit one. A bank letter showing funds for one academic year is required before an I-20 is issued.', '5cc80126-6cca-5812-bb2c-413fb5a6a5bd');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('5d2818ee-f3cd-5757-ba20-fe2f6f245536', '6308ba22-3cfb-5c56-93cf-a663b1bb0853', '2026-27', 'application', 'ED', 'Early Decision application due (fall 2027 entry)', '2026-11-01', 'Binding. Page prints ''November 1'' without a year; treated as fall 2027 entry. Admission decision before Dec. 15; ED enrollment deposit due Jan. 15. No Early Action; no separate international dates are published.', 'f17f943e-409b-5fcc-bb32-bcf5e6db1e09'),
 ('b81f960a-01e9-545a-a5a4-6c4829c6ca13', '6308ba22-3cfb-5c56-93cf-a663b1bb0853', '2026-27', 'application', 'RD', 'Regular Decision application due (fall 2027 entry)', '2027-03-01', 'Printed without a year; treated as fall 2027. RD enrollment deposit due May 1. Some programs have different deadlines.', 'f17f943e-409b-5fcc-bb32-bcf5e6db1e09');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('6308ba22-3cfb-5c56-93cf-a663b1bb0853', 'required_all_international', 'Applicants whose native language is not English may satisfy the requirement with SAT, ACT, TOEFL, IELTS, Duolingo English Test, or passing English scores on GCE, GCSE, IGCSE, BGCSE, CXC, CSEC, CAPE, CEFR (B2 or higher) or IB exams. No minimum scores are published on the current pages. Flagler does not offer intensive English (ESL) courses, and students who are not proficient in English will not be admitted. Duolingo scores must be sent through the shared Duolingo portal.', '5cc80126-6cca-5812-bb2c-413fb5a6a5bd');
insert into english_requirements (institution_id, status, source_id, test_key, notes)
select '6308ba22-3cfb-5c56-93cf-a663b1bb0853'::uuid, 'accepted', '5cc80126-6cca-5812-bb2c-413fb5a6a5bd'::uuid, v.* from (values
 ('TOEFL_IBT', 'Accepted; no minimum score is published.'),
 ('IELTS', 'Accepted; no minimum score is published.'),
 ('DUOLINGO', 'Accepted; no minimum score is published. Send through the shared Duolingo portal.')) v;
insert into score_codes (institution_id, source_id, test_key, code, notes)
