 ('sat', '5235', 'Flagler SAT code printed on the international How to Apply page.'),
 ('act', '0772', 'Flagler ACT code printed on the international How to Apply page.'),
 ('toefl', null, 'No TOEFL institution code is printed on the admissions pages; search for Flagler College when ordering.'),
 ('ielts', null, 'No institution code is listed.'),
 ('duolingo', null, 'Send through the shared Duolingo portal; no code is listed.'),
 ('pte', null, 'PTE is not mentioned on the international pages.')) v;
insert into cost_aid (institution_id, year, tuition_usd, tuition_intl_usd, room_board_usd, books_usd, total_coa_usd, intl_aid_policy, intl_need_aid, meets_full_need, merit_scholarships, notes, source_id) values
 ('6308ba22-3cfb-5c56-93cf-a663b1bb0853', '2024-2025', 29900, 29900, 15130, 1260, 50442, 'merit_only', false, false, true, 'College Navigator 2024-25: tuition and fees combined $29,900; on-campus food and housing $15,130; books and supplies $1,260; total on-campus estimate $50,442. The international FAQ says international students pay the same costs as U.S. citizens plus a required health insurance policy (amount not published). 2026-27 prices were not found.; International FAQ: only merit-based and athletic aid are available to international students; no separate application for merit scholarships and no amounts are published.', '6d1dfddc-b951-52da-93b2-83657c5a85e3');
insert into institution_tiers (institution_id, category_key, tier_code, rationale) values
 ('6308ba22-3cfb-5c56-93cf-a663b1bb0853', 'general', 'D', 'Admit rate 78.1%');

