insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('e255622a-e1b6-59ed-af98-7513808cd6de', '2026-27', 'required', 'Florida Board of Governors regulation 6.002 requires first-year applicants to submit an ACT, CLT or SAT score. Common App self-reported scores are not accepted; self-report on the Admissions Portal. Last usable test date is February.', '6027fd1a-bced-5e6e-a0f9-15febb9e664e');
insert into application_requirements (institution_id, cycle, platforms, teacher_recs, app_fee_usd, notes, source_id) values
 ('e255622a-e1b6-59ed-af98-7513808cd6de', '2026-27', array['common_app','own']::text[], 0, 30, 'Common App adds a $5 processing fee. Essay and resume/list of activities are uploaded in the Admissions Portal. Letters of recommendation are not required and not used. International applicants also complete an International School Form and usually submit official records with a foreign credential evaluation. Early decision is for domestic students only and early action is for Florida residents only, so international applicants use regular decision or rolling.', '4cd0d1a2-ae12-59be-8c96-54f91484f319');
