 ('f6462cc1-ef10-50e0-a1ea-68ee9446847e', 'e255622a-e1b6-59ed-af98-7513808cd6de', '2026-27', 'application', 'ROLLING', 'Rolling admission', '2027-03-01', null, 'Materials deadline Mar 8; decisions on a rolling basis in April.', '4cd0d1a2-ae12-59be-8c96-54f91484f319'),
 ('19925f16-2b32-5129-adc2-7f7e71ff7e13', 'e255622a-e1b6-59ed-af98-7513808cd6de', '2026-27', 'deposit', 'RD', 'Enrollment deposit', '2027-05-01', null, null, '4cd0d1a2-ae12-59be-8c96-54f91484f319');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
