insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('896861bc-d8aa-5153-8b28-3fbed6e8adae', '2026-27', 'optional', 'SAT/ACT not required; no penalty for not submitting. Optional sections (SAT Writing, ACT Science/Writing) are up to the student. Superscored. To change testing status, do so in the applicant portal by Nov 20 (EA/ED I) or Jan 20 (RD/ED II).', 'fe347b4a-72bc-5eda-9fe5-401e40dc0a4a');
insert into application_requirements (institution_id, cycle, platforms, interview, app_fee_usd, notes, source_id) values
 ('896861bc-d8aa-5153-8b28-3fbed6e8adae', '2026-27', array['common_app']::text[], 'optional_informational', 80, 'Application = Common App, essay, high school transcript, letter of recommendation, $80 fee. Interviews are not required; Fordham accepts partner interviews (Duolingo, InitialView, Vericant) from international applicants, with interview deadlines Nov 15 (EA/ED I) and Feb 15 (RD/ED II). International CSS Profile due Nov 1 (EA/ED I) or Jan 3 (RD/ED II).', '9f2c7b8f-ca01-5c69-b038-d3f6e884e0a6');
