insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, pct_submit_sat, pct_submit_act, notes, source_id, source_note) values
 ('6956975b-d504-5733-8283-1364b242dbf1', '2023-2024', 2174, 1995, 886, 5, 91, 'No current Common Data Set: the newest file FHSU posts is 2019-20, so this is the IPEDS baseline for the fall 2023 entering class (ADM2023). College Navigator''s newer fall 2024 figures: 2,619 applicants, 90% admitted, 42% of admitted enrolled. These are institution-wide first-time counts that can include online and partnership-program students; neither IPEDS nor an available CDS separates on-campus (Hays) first-year applicants, so no on-campus split is given. Undergraduate enrollment 10,172 (College Navigator fall 2024) is also institution-wide (it includes online students), not the Hays campus alone. Student-to-faculty ratio 15:1 is College Navigator fall 2024. IPEDS gives no international applicant/admit split and no GPA data.', 'b874e7a4-2327-5d51-9754-004c0d64dc77', 'admissions_site');
insert into test_score_percentiles (institution_id, cds_year, source_id, test, p25, p50, p75)
select '6956975b-d504-5733-8283-1364b242dbf1'::uuid, '2023-2024', 'b874e7a4-2327-5d51-9754-004c0d64dc77'::uuid, v.* from (values
 ('SAT_ERW', 490, 550, 600),
 ('SAT_MATH', 480, 530, 600),
 ('ACT_COMPOSITE', 19, 22, 25),
 ('ACT_ENGLISH', 18, 21, 24),
 ('ACT_MATH', 17, 21, 25)) v;
insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('6956975b-d504-5733-8283-1364b242dbf1', '2026-27', 'optional', 'FHSU''s international scholarship page states that an ACT/SAT score is not required to apply for admission as an international student; it is only needed to qualify for the Freshman Scholarship. Admission rests on a 2.5 GPA (4.0 scale) from the secondary transcript.', '1a75b33e-56cb-5c82-b42c-3da52277da54');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('6956975b-d504-5733-8283-1364b242dbf1', '2026-27', array['own']::text[], 50, 'Apply through the FHSU international application portal; the $50 fee is non-refundable and valid for 12 months. Required: passport ID page, official transcripts (English or with NACES word-for-word translation; first-year minimum 2.5/4.0), English proficiency, and the International Student Financial Data and I-20 Request Form with a certified bank statement covering one year (at least the current estimated expenses, $30,239 for 2026-27). Essays and recommendations are not listed. These are the on-campus (Hays) rules; online and partnership programs have different, later deadlines.', 'd7ebfa88-f5db-57cd-bfb3-719170a63b93');
insert into deadlines (id, institution_id, cycle, kind, label, due_date, notes, source_id) values
 ('b3de5a02-d599-5ab1-a5aa-e1c58e46a687', '6956975b-d504-5733-8283-1364b242dbf1', '2026-27', 'application', 'Fall 2027 on-campus international application deadline', '2027-06-01', 'Last day to submit a completed application including all admission documents. The page prints June 1 without a year; treated as 2027. Spring 2028 entry: Nov. 1 (the same page also prints Oct. 1 once). Summer is not permitted for on-campus international students.', '244a39d5-e107-546e-be1b-d1cf77346f62'),
 ('c8be8cfb-c2d7-546f-a350-70d3cadee7e0', '6956975b-d504-5733-8283-1364b242dbf1', '2026-27', 'other', 'Last day FHSU issues I-20s for fall 2027 (on-campus)', '2027-06-15', 'Spring entry: Nov. 15.', 'd7ebfa88-f5db-57cd-bfb3-719170a63b93');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('6956975b-d504-5733-8283-1364b242dbf1', 'required_nonnative', 'Exceptions: 24 or more accredited US college credits with the admission GPA; English as the home country''s native language; or current US high school enrollment with a 2.5 GPA and two years of English. Institutional TOEFL, TOEFL Essentials and institutional completion scores are not accepted. Applicants below the minimum can be admitted and sent an I-20 if they complete the online Intensive English Program of The Language Company (TLC) at Level 9. iTEP 3.6 is also accepted. The page gives no PTE or Cambridge minimum.', 'b3e3159e-816e-5be2-b48a-a7f22e8155a6');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
select '6956975b-d504-5733-8283-1364b242dbf1'::uuid, 'required_option', 'b3e3159e-816e-5be2-b48a-a7f22e8155a6'::uuid, v.* from (values
 ('TOEFL_IBT', 61, 'No new 1-6 scale minimum is listed.'),
 ('IELTS', 5.5, null),
 ('DUOLINGO', 95, null)) v;
insert into score_codes (institution_id, test_key, notes, source_id)
select '6956975b-d504-5733-8283-1364b242dbf1'::uuid, v.* from (values
 ('sat', 'The international pages print no SAT code; look it up in the College Board code search.', 'd7ebfa88-f5db-57cd-bfb3-719170a63b93'::uuid),
 ('act', 'The international pages print no ACT code; look it up at act.org.', 'd7ebfa88-f5db-57cd-bfb3-719170a63b93'::uuid),
 ('toefl', 'No TOEFL institution code is printed; look it up in the ETS code search. Scores must come from the testing company directly to FHSU.', 'b3e3159e-816e-5be2-b48a-a7f22e8155a6'::uuid),
 ('ielts', 'No institution code is listed.', 'b3e3159e-816e-5be2-b48a-a7f22e8155a6'::uuid),
 ('duolingo', 'No institution code is listed.', 'b3e3159e-816e-5be2-b48a-a7f22e8155a6'::uuid),
 ('pte', 'PTE is not listed as an accepted test.', 'b3e3159e-816e-5be2-b48a-a7f22e8155a6'::uuid)) v;
insert into cost_aid (institution_id, year, tuition_intl_usd, room_board_usd, books_usd, other_usd, total_coa_usd, intl_aid_policy, intl_need_aid, meets_full_need, merit_scholarships, merit_separate_app, notes, source_id) values
 ('6956975b-d504-5733-8283-1364b242dbf1', '2026-2027', 15624, 9725, 700, 4190, 30239, 'merit_only', false, false, true, false, 'FHSU international undergraduate estimate (12 credits per semester): tuition and fees $15,624 ($651 per credit before the July 1 final rate, entered as one combined figure); McMindes Hall room and board $9,725; mandatory health insurance $3,000, miscellaneous $1,000, orientation/registration $150, housing contract fee $40 (together $4,190, entered as other); books $700; total $30,239. Figures are provisional until July.; FHSU World Ready International Scholarship: $1,000 per year ($500 per semester), awarded automatically to new first-time on-campus international students who stay at a 2.5 GPA (undergraduate). The Freshman Scholarship ($1,500-$3,750 per year, automatic, based on ACT/SAT and high school GPA) is open to first-time on-campus international students who submit scores. Stouffer and Solko & Olliff scholarships (amounts vary) need an application after admission. No international need-based aid is described.', '6308a4c8-153a-5b5b-8eaa-99e7f7211e39');
insert into institution_tiers (institution_id, tier_code, category_key, rationale)
select '6956975b-d504-5733-8283-1364b242dbf1'::uuid, 'D', v.* from (values
 ('general', 'Admit rate 91.8%'),
 ('computer_science', 'Editorial judgment (v1, reviewed 2026-10-20)'),
 ('business', 'Editorial judgment (v1, reviewed 2026-10-20)'),
 ('biology_life_sci', 'Editorial judgment (v1, reviewed 2026-10-20)'),
 ('economics', 'Editorial judgment (v1, reviewed 2026-10-20)'),
 ('math_physics', 'Editorial judgment (v1, reviewed 2026-10-20)'),
 ('humanities', 'Editorial judgment (v1, reviewed 2026-10-20)'),
 ('arts_design', 'Editorial judgment (v1, reviewed 2026-10-20)'),
 ('nursing', 'Editorial judgment (v1, reviewed 2026-10-20)')) v;

-- ── Francis Marion University ──
