insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, pct_submit_sat, pct_submit_act, notes, source_id, source_note) values
 ('4d0ed9a5-fb50-58c8-ad53-7b302603f48a', '2023-2024', 3489, 2869, 632, 19, 15, 'Baseline from IPEDS (fall 2023 entering class): 3,489 applied, 2,869 admitted, 632 enrolled. No Common Data Set could be found on fmarion.edu (the institutional research pages link none), so GPA, international applicant/admit counts and SAT total are not available. Newer College Navigator figures (fall 2024): 3,616 applicants, 86% admitted and 22% of those enrolled (rounded percentages), SAT EBRW 450/510/575, SAT Math 420/480/540, ACT composite 16/20/24, 3,692 undergraduates (used for enrollment here), student-to-faculty ratio 13 to 1. Test optional; 16% of fall 2024 enrollees submitted SAT and 11% ACT.', '9aef871f-8426-5a22-8a5f-9e64f15d661a', 'admissions_site');
insert into test_score_percentiles (institution_id, cds_year, source_id, test, p25, p50, p75)
select '4d0ed9a5-fb50-58c8-ad53-7b302603f48a'::uuid, '2023-2024', '9aef871f-8426-5a22-8a5f-9e64f15d661a'::uuid, v.* from (values
 ('SAT_ERW', 470, 530, 590),
 ('SAT_MATH', 430, 500, 548),
 ('ACT_COMPOSITE', 17, 20, 23),
 ('ACT_ENGLISH', 16, 19, 22),
 ('ACT_MATH', 16, 18, 23)) v;
insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('4d0ed9a5-fb50-58c8-ad53-7b302603f48a', '2026-27', 'optional', 'The requirements page says submission of ACT and SAT scores is optional (SAT code 5442, ACT code 3856). The international requirements list no test scores. No minimum GPA is printed for freshmen; admission looks at HS academics, recommendations and activities, plus the core course units (4 English, 4 math, 3 lab science, 2 same foreign language, 3 social science incl. U.S. history, 1 fine arts, 1 elective, 1 PE/ROTC).', 'a0579beb-69db-5d89-87b7-1e19d4174553');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('4d0ed9a5-fb50-58c8-ad53-7b302603f48a', '2026-27', array['own']::text[], 41, 'Online application at fmarion.edu/applynow; $41 non-refundable fee (the international section does not state a separate fee). International applicants send official transcripts or school certificates directly from the school with an English-evaluated translation and a grading-scale explanation; university-level work from outside the U.S. must be certified by WES. Proof of funds (bank, employer or sponsor statement plus the Certificate of Financial Support) is required before the I-20; the page states a cost of attendance of ''approximately U.S. $33,139'' per year, which looks older than the 2026-27 fee sheet. A health history form, immunization record, TB (PPD) test and proof of health insurance (F-1: $50,000 major medical, $25,000 repatriation, $50,000 evacuation, deductible up to $100) are required before registering. Faxes and applicant-mailed copies are not accepted. Contact: International Programs, melissa.dungan@fmarion.edu.', 'a0579beb-69db-5d89-87b7-1e19d4174553');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('169b218b-0a2f-5185-93a2-9b4f9a0a33de', '4d0ed9a5-fb50-58c8-ad53-7b302603f48a', '2026-27', 'application', 'ROLLING', 'International degree-seeking students must be accepted by this date (fall 2027)', '2027-07-01', 'Accepted by July 1 for the fall semester (Nov. 1 spring; April 1 late spring/summer). Printed without a year; treated as fall 2027. Domestic undergraduate admission is rolling with a final cutoff at noon on the Friday before classes start; decisions are made as soon as the file is complete.', 'a0579beb-69db-5d89-87b7-1e19d4174553'),
 ('338d60e6-05d7-5874-a0eb-24414385030e', '4d0ed9a5-fb50-58c8-ad53-7b302603f48a', '2026-27', 'scholarship', null, 'Admissions Scholarship application due', '2027-03-15', 'FMU Admission Scholarship application (also used for out-of-state waivers and other admissions scholarships) is due March 15; the year is not printed and is treated as 2027. Merit awards go out in rounds with larger awards earlier, so apply early.', 'b45f4ea7-88e4-5ed6-8fb9-099b98252640');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('4d0ed9a5-fb50-58c8-ad53-7b302603f48a', 'required_nonnative', 'The TOEFL, IELTS or Duolingo English Test is required of all international students except those whose native language is English. U.S. transfer students may be admitted without TOEFL if they have a high SAT verbal score or good grades in freshman English. The page does not list a country-exemption list, conditional admission or an ESL pathway.', 'a0579beb-69db-5d89-87b7-1e19d4174553');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
select '4d0ed9a5-fb50-58c8-ad53-7b302603f48a'::uuid, 'required_option', 'a0579beb-69db-5d89-87b7-1e19d4174553'::uuid, v.* from (values
 ('TOEFL_IBT', 61, '''At least a 500 (61 on the internet based version)''. The page does not give a 1-6 scale minimum.'),
 ('IELTS', null, 'IELTS may be used in lieu of TOEFL; no minimum score is printed.'),
 ('DUOLINGO', null, 'Duolingo English Test may be used in lieu of TOEFL; no minimum score is printed.')) v;
insert into score_codes (institution_id, source_id, test_key, code, notes)
select '4d0ed9a5-fb50-58c8-ad53-7b302603f48a'::uuid, 'a0579beb-69db-5d89-87b7-1e19d4174553'::uuid, v.* from (values
 ('sat', '5442', 'FMU SAT code.'),
 ('act', '3856', 'FMU ACT code.'),
 ('toefl', null, 'The international requirements page does not print a TOEFL institution code; look it up with ETS.'),
 ('ielts', null, 'No institution code is listed.'),
 ('duolingo', null, 'No institution code is listed.'),
 ('pte', null, 'PTE is not mentioned on the international page.')) v;
insert into cost_aid (institution_id, year, tuition_usd, tuition_out_of_state_usd, tuition_intl_usd, required_fees_usd, room_board_usd, intl_aid_policy, intl_need_aid, meets_full_need, merit_scholarships, notes, source_id) values
 ('4d0ed9a5-fb50-58c8-ad53-7b302603f48a', '2026-2027', 10384, 20768, 20768, 776, 11370, 'merit_only', false, false, true, 'From the 2026-27 fee sheet, full-time undergraduate per semester: tuition $5,192 for SC residents and $10,384 for non-residents, plus required fees (registration $20, activity $156, IT $112, facility $100 = $388); annual figures here are two semesters. Resident example total on the sheet: $5,580 per semester. Housing and dining: residence hall double room including the All-Access Plus meal plan is $5,685 per semester ($11,370 a year); apartments and other meal plans cost less or more. The sheet text is garbled in places; the non-resident tuition and housing figures were matched to the sheet''s own structure (non-resident total = $10,772 per semester, which equals College Navigator''s $21,544 annual tuition and fees for 2024-25). Books and other expenses not stated.; The international page says international undergraduates pay all expenses and the University does not award financial aid to them, although some scholarships are available for qualified students. The Academic Distinction Award ($1,000+ for top 40% of class, SAT 1100/ACT 22, 3.0 GPA) is for South Carolina residents. The Admissions Scholarships application (due March 15) covers out-of-state waivers and other admissions scholarships ($500 up to full tuition, room and board); strong GPA (3.0 weighted), class rank and test scores are considered, and eligibility for international students is not spelled out. Students from Brandenburg, Thuringia, Rhineland-Palatinate (Germany), Queensland (Australia) and Taiwan may qualify for in-state tuition under the Sister-State initiative.', '1ad5fc7a-9670-55a4-a65e-26984c3c632a');
insert into institution_tiers (institution_id, category_key, tier_code, rationale) values
 ('4d0ed9a5-fb50-58c8-ad53-7b302603f48a', 'general', 'D', 'Admit rate 82.2%');

