insert into admission_stats (institution_id, cds_year, applicants, admits, notes, source_id) values
 ('06ee363a-0847-5bac-84f7-79af740aa7fe', '2025-2026', 4839, 4389, 'Only B1 and C1 are filled in the CDS PDF (first-year applicants 2,285 men + 2,554 women; admits 2,070 + 2,319). The enrolled count is left null because the form''s C1 enrollee fields disagree with each other; the international and in-state/out-of-state split is blank; no test, GPA or C7 factor data. College Navigator (IPEDS fall 2024): 5,037 applicants, 89% admitted, 13% of admits enrolled. Undergraduate enrollment 3,436 is CDS B1 total undergraduates, fall 2025; student-faculty ratio 13:1 from College Navigator (the CDS gives 12:1).', 'd00b8ee6-8466-5128-8dfc-c10a567c5178');
insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('06ee363a-0847-5bac-84f7-79af740aa7fe', '2026-27', 'optional', 'Frostburg is test optional: submitted SAT/ACT scores are considered but do not hurt an application, and applicants without scores get full consideration, including for merit scholarships.', '51d2ade0-b200-5e6b-bf8c-262b55607108');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, fee_waiver, notes, source_id) values
 ('06ee363a-0847-5bac-84f7-79af740aa7fe', '2026-27', array['common_app','own']::text[], 45, true, '$45 non-refundable fee (a waiver may be provided through the applicant''s high school). Personal statement and 1-2 recommendation letters are optional. International applicants also submit a course-by-course foreign credential evaluation of all transcripts (ECE, ICDE, Josef Silney or WES), a financial certification form with a bank statement showing support for one year, a passport copy and proof of English proficiency. International students cannot use payment plans.', 'c040cace-3dce-5a6a-a159-cb9d9259719a');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('089bf712-8f88-51c0-8552-f2773f181608', '06ee363a-0847-5bac-84f7-79af740aa7fe', '2026-27', 'application', 'ROLLING', 'International application deadline, fall 2027 entry', '2027-06-01', 'Page says ''apply by June 1st for Fall and October 15th for Spring'' to allow time for visa processing; no year printed, taken as 2027. Domestic applications open August 1 and are accepted until space runs out.', '6333ecf6-9086-5926-8aa5-aeb44b58b2b1'),
 ('85cc8c2c-8ac5-5760-be13-5d3b56f01c3c', '06ee363a-0847-5bac-84f7-79af740aa7fe', '2026-27', 'application', 'EA', 'Early Action (non-binding)', '2026-11-15', 'Domestic first-year page: apply by November 15 for a decision in 2-4 weeks; regular applications are ''encouraged by February 1''. No year printed, taken as the fall 2027 cycle. International applicants have the June 1 deadline above.', 'eeedc36d-8815-5e23-997d-b0bbcb346296'),
 ('6ae7dbaf-d5b2-5d9a-a004-8888bbc1686d', '06ee363a-0847-5bac-84f7-79af740aa7fe', '2026-27', 'scholarship', null, 'Foundation scholarship priority deadline', '2027-03-01', 'Foundation scholarship applications are accepted until August 1. Year not printed; taken as 2027.', 'e1116e3f-268e-5d38-9f5e-3c53292d5856');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('06ee363a-0847-5bac-84f7-79af740aa7fe', 'required_nonnative', 'Proof of English proficiency is needed if English is not the first language; the procedures page says it may be waived for students whose primary language is English. Scores must be sent directly by the testing agency.', 'c040cace-3dce-5a6a-a159-cb9d9259719a');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
select '06ee363a-0847-5bac-84f7-79af740aa7fe'::uuid, 'required_option', '6333ecf6-9086-5926-8aa5-aeb44b58b2b1'::uuid, v.* from (values
 ('TOEFL_IBT_2026', 3.5, 'Page lists ''TOEFL 3.5'' without naming the scale; 3.5 can only be the new 1-6 scale. Older catalogs (2020-22) gave a 0-120 minimum of 61, which the current pages no longer list.'),
 ('IELTS', 5.5, 'Undergraduate and exchange minimum.'),
 ('DUOLINGO', 85, 'Undergraduate minimum.')) v;
