insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('b0e7c0b2-088c-546d-9fb6-0034a581bc20', '2026-27', 'optional', 'Score optional since 2007 for SAT/ACT, including international applicants. Applicants to Computer Science or Engineering may be considered without scores if they meet the math requirements (four years of high school math including a course above Algebra II, grades of B or higher). If scores are submitted, official results must arrive before the first day of classes.', '62e68b84-5a86-544d-812b-7110bf7b7ab1');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, fee_waiver, notes, source_id) values
 ('b0e7c0b2-088c-546d-9fb6-0034a581bc20', '2026-27', array['common_app','own']::text[], 75, true, 'Common App or Mason''s own application are reviewed equally; $75 freshman fee, waivers available. Certified official, original transcripts and leaving/entrance exam results (certified English translation if needed). Personal statement (about 250 words) is optional but strongly encouraged; two recommendation letters (one counselor, one teacher) are suggested, not required. Resume only for applicants with enrollment gaps.', '62e68b84-5a86-544d-812b-7110bf7b7ab1');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('25bad202-e00f-577e-a1f6-2064ca673541', 'b0e7c0b2-088c-546d-9fb6-0034a581bc20', '2026-27', 'application', 'EA', 'Early Action (non-binding; international Honors College consideration)', '2026-11-01', 'Decision in mid-December. Early applicants get priority for the Honors College and merit scholarships. The page prints no year; taken as the current (fall 2027) cycle.', '7fbcc738-8e9e-5b3d-8dfa-af026f39364e'),
 ('614012ce-a2d5-5fb8-8fe4-c5b380ac6023', 'b0e7c0b2-088c-546d-9fb6-0034a581bc20', '2026-27', 'application', 'RD', 'Regular Decision', '2027-02-01', 'Decision in spring. Later applications are reviewed on a space-available basis.', '7fbcc738-8e9e-5b3d-8dfa-af026f39364e'),
 ('463fb45f-5862-5a99-af92-62617b81b539', 'b0e7c0b2-088c-546d-9fb6-0034a581bc20', '2026-27', 'application', 'ROLLING', 'International final deadline for fall semester', '2027-06-01', 'Listed only for international freshman applicants; applications after Feb. 1 are space-available.', '7fbcc738-8e9e-5b3d-8dfa-af026f39364e');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('b0e7c0b2-088c-546d-9fb6-0034a581bc20', 'required_nonnative', 'Waivers include four years at a George Mason-recognized accredited US secondary school with a C or better in each non-ESL college-prep English course; four years of non-ESL English with C/4 or better under IB or UK curricula (fall 2026 applicants onward); four years at a school in a listed waiver-eligible country where English is the primary language of instruction; six English Composition credits (C or better) from a recognized US institution; or a bachelor''s or higher degree from a recognized US institution. Also accepted: SAT EBRW 500+, ACT English and Reading 20+ each, IB HL English A 6. Scores must be under two years old; TOEFL MyBest and Home Edition accepted; IELTS Indicator not accepted. Pathway: the Gateway Freshman International Direct program admits academically qualified applicants (high school GPA 2.9+) with English slightly lower (TOEFL iBT 70 / new 4.0 with 3.5 each skill, IELTS 6.0 with 5.5 each skill, PTE 53, Duolingo 100): one semester of English and transition courses (14-16 credits) with a direct-entry I-20, then progression to a degree; the Gateway page says its information applies to students starting spring 2027 and later.', '2e02183d-1124-56c7-aad1-0259591531c5');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, min_subscores, notes)
select 'b0e7c0b2-088c-546d-9fb6-0034a581bc20'::uuid, 'required_option', '2e02183d-1124-56c7-aad1-0259591531c5'::uuid, v.* from (values
 ('TOEFL_IBT', 80, '{"each_section": 18}'::jsonb, 'Tests taken before Jan. 21, 2026. College of Engineering and Computing applicants: 80 overall, no section minimum. TOEFL institution code 5827.'),
 ('TOEFL_IBT_2026', 4.5, '{"each_section": 4.0}'::jsonb, 'Tests taken on or after Jan. 21, 2026; the page does not name the 1-6 scale. Engineering and Computing applicants: 4.5, no section minimum.'),
 ('IELTS', 6.5, '{"each_section": 6.0}'::jsonb, 'Engineering and Computing applicants: 6.5, no section minimum. IELTS Indicator not accepted; One Skill Retake accepted.'),
 ('DUOLINGO', 110, null, null),
 ('PTE', 59, null, 'Pearson Test of English Academic.')) v;
