select 'b0e7c0b2-088c-546d-9fb6-0034a581bc20'::uuid, v.* from (values
 ('sat', null, 'George Mason''s admissions pages do not print an SAT code; have the College Board send scores to George Mason University (Fairfax).', 'deb96e50-458b-5e61-97f2-f27ad5417d6d'::uuid),
 ('act', null, 'George Mason''s admissions pages do not print an ACT code; look it up at act.org.', 'deb96e50-458b-5e61-97f2-f27ad5417d6d'::uuid),
 ('toefl', '5827', null, '2e02183d-1124-56c7-aad1-0259591531c5'::uuid)) v;
insert into cost_aid (institution_id, year, tuition_usd, tuition_out_of_state_usd, tuition_intl_usd, room_board_usd, books_usd, other_usd, total_coa_usd, intl_aid_policy, meets_full_need, merit_scholarships, merit_separate_app, notes, source_id) values
 ('b0e7c0b2-088c-546d-9fb6-0034a581bc20', '2024-2025', 14220, 38688, 38688, 15725, 1288, 3667, 34900, 'merit_only', false, true, false, 'College Navigator estimated expenses for full-time beginning undergraduates, 2024-25: tuition and fees $14,220 in-state / $38,688 out-of-state; on-campus food and housing $15,725; books $1,288; other $3,667; total on-campus $34,900 in-state / $59,368 out-of-state. 2026-27 rates were not checked.; Mason offers a limited number of merit-based scholarships to highly qualified international freshmen and transfers on F-1 visas; all admitted applicants are considered automatically (no separate application) through a holistic review in which GPA and test scores matter most. Awards renew for up to four years for freshmen. Amounts are not published. Non-US citizens are not eligible for federal aid; the page does not describe need-based institutional aid for international students.', '59f5a73c-cba3-5a59-bd99-6ef56eb9cdfa');
