insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('ce5c7cad-f0c4-5b50-a6eb-dbb0b8446827', '2026-27', 'required', 'Georgetown requires either SAT or ACT. Exception only in exceptional cases where a student is physically unable to access a test center (must explain). AP scores highly recommended.', 'bb83133a-3211-5c2e-a170-1557743fa5aa');
insert into application_requirements (institution_id, cycle, platforms, supplemental_essays, teacher_recs, counselor_rec, interview, css_profile_required, midyear_report, notes, source_id) values
 ('ce5c7cad-f0c4-5b50-a6eb-dbb0b8446827', '2026-27', array['common_app','own']::text[], 'Georgetown Writing Supplement: two 250-word short essays, a 650-word personal/creative essay, and a 500-word school-specific essay.', 1, true, 'required', true, true, 'Apply with the Georgetown Application or the Common Application. One counselor and one teacher recommendation (an optional second teacher). Alumni interview is required when assigned; some internationally based students may not be assigned one with no negative effect. Midyear School Report due Feb 10. CSS Profile is required for aid applicants. Application fee not stated on the pages read.', 'bb83133a-3211-5c2e-a170-1557743fa5aa');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notification_date, notes, source_id) values
 ('9a6afe19-78f8-5f9d-9597-c5ece0b1b39d', 'ce5c7cad-f0c4-5b50-a6eb-dbb0b8446827', '2026-27', 'application', 'EA', null, '2026-11-01', '2026-12-15', 'Listed as ''Early Action''; decision ''by December 15''. The page does not state the calendar year; CDS 2025-26 listed a Jan 10 closing date for the previous cycle.', '9e70b71b-5fca-5da0-9e35-ff4d9669f863'),
 ('c1cc2b8f-ec3a-5ca8-89a6-b18f5ccae82b', 'ce5c7cad-f0c4-5b50-a6eb-dbb0b8446827', '2026-27', 'application', 'RD', null, '2027-01-01', '2027-04-01', 'Decision ''by April 1''. The page does not state the calendar year.', '9e70b71b-5fca-5da0-9e35-ff4d9669f863'),
 ('9b121835-923b-58eb-aee4-32a1a9747b0f', 'ce5c7cad-f0c4-5b50-a6eb-dbb0b8446827', '2026-27', 'financial_aid', 'EA', 'Financial aid application (EA and RD)', '2027-02-01', null, null, '9e70b71b-5fca-5da0-9e35-ff4d9669f863'),
 ('e79f8a61-b34a-527d-88d1-b41d219c0a8c', 'ce5c7cad-f0c4-5b50-a6eb-dbb0b8446827', '2026-27', 'deposit', 'RD', 'Reply date for admitted students (both plans)', '2027-05-01', null, null, '9e70b71b-5fca-5da0-9e35-ff4d9669f863');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('ce5c7cad-f0c4-5b50-a6eb-dbb0b8446827', 'recommended', 'Georgetown recommends, but does not require, an English proficiency test for applicants whose school does not teach in English. Accepts Duolingo (DET), IELTS or TOEFL (PBT, iBT, iBT IPT Plus). No minimum scores are published.', 'fb0d726a-4a03-5831-8292-68b0a581f1ce');
