 ('act', '0828', 'ACT code 0828.', '6296cb59-38bb-547b-9f84-48ace382a267'::uuid),
 ('toefl', '5252', 'ETS institution code 5252, per the International Admissions checklist.', '25979e82-9ec6-51d4-ae57-e9276bb9516c'::uuid),
 ('ielts', null, 'No institution code; request the report from the IELTS test center where you took the exam.', '25979e82-9ec6-51d4-ae57-e9276bb9516c'::uuid),
 ('duolingo', null, 'Duolingo English Test is not listed among accepted English proficiency options for undergraduate applicants.', 'b4df7462-8fde-5a8a-9ac4-0ecc31bbdab1'::uuid),
