insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('b61d0a90-cb73-50f3-a9b9-d3b98291c91e', '2026-27', 'optional', 'The freshman page labels SAT/ACT optional (''please send official copies''); preferred minimums are SAT EBRW 480 and Math 440, or ACT English or Reading 17 and Math 17. Regular admission uses a Freshman Index of at least 1940 combining high school GPA and test scores; applicants below it can enter through University College (2.0 GPA). The international page lets test scores double as English proof.', 'e4ab6c19-41ec-5116-a588-75bf4756152e');
insert into application_requirements (institution_id, cycle, platforms, notes, source_id) values
 ('b61d0a90-cb73-50f3-a9b9-d3b98291c91e', '2026-27', array['own']::text[], 'Freshmen apply through the GAfutures portal (the Common App is not mentioned). International applicants also need a NACES or AICE document-by-document evaluation of the high school transcript, the Declaration and Certification of Finances with a bank letter, and a passport copy; allow at least four weeks for processing. The deadline and freshman pages print no application fee (College Navigator lists $25 for 2024-25).', 'e6a8c41e-9f1f-5def-9e53-98470cf463a0');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('b32cf0b8-411d-51c0-a30f-afcfdb5ab858', 'b61d0a90-cb73-50f3-a9b9-d3b98291c91e', '2026-27', 'application', 'RD', 'International student application deadline (fall 2027)', '2027-07-01', 'Deadlines page: fall July 1, spring November 14, summer April 15 for international students (general undergraduate fall deadline July 21). Dates print without a year; treated as fall 2027. Allow time for the I-20 and visa.', 'c11e9f8b-2a71-55f1-9de6-988a19d982bb'),
 ('76882341-3cda-5125-8627-de1c4f013ed2', 'b61d0a90-cb73-50f3-a9b9-d3b98291c91e', '2026-27', 'scholarship', null, 'Freshman scholarship deadline (fall)', '2027-02-01', 'Also the priority date for the Promise Scholarship and the President Carter Leadership Program. Printed without a year; treated as 2027.', 'c11e9f8b-2a71-55f1-9de6-988a19d982bb');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('b61d0a90-cb73-50f3-a9b9-d3b98291c91e', 'required_nonnative', 'Applicants from or graduating from a school in a non-native English-speaking country may submit TOEFL, IELTS, SAT, ACT, an English Language Institute (ELI) Advanced Completion Certificate, or qualifying Accuplacer scores (Next Gen Reading 237, WritePlacer 4+). Applicants with more than two years of U.S. high school or from a native English-speaking country submit SAT or ACT instead. Duolingo, PTE and Cambridge are not mentioned; the ELI route is a campus English program.', 'e6a8c41e-9f1f-5def-9e53-98470cf463a0');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
select 'b61d0a90-cb73-50f3-a9b9-d3b98291c91e'::uuid, 'required_option', 'e6a8c41e-9f1f-5def-9e53-98470cf463a0'::uuid, v.* from (values
 ('TOEFL_IBT', 69, 'Page lists 69 iBT (523 paper, 193 computer). No 1-6 scale value is given. SAT EBRW 480+/Math 440+ or ACT 17/17 also satisfies it.'),
 ('IELTS', 6.5, null)) v;
insert into score_codes (institution_id, test_key, code, notes, source_id)
select 'b61d0a90-cb73-50f3-a9b9-d3b98291c91e'::uuid, v.* from (values
