insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('9bd85eba-6736-55de-ba4f-0bfbfa121f33', '2026-27', 'optional', 'SAT/ACT are optional for admission; all admitted students are considered for merit scholarships without scores, but the top scholarships require scores. The undergraduate application page says scores are ''not required for domestic undergraduate applicants'' and the international page lists no test requirement beyond English proficiency.', '366fcf0a-8f48-55e7-9b4f-775b03e37130');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('9bd85eba-6736-55de-ba4f-0bfbfa121f33', '2026-27', array['common_app','own']::text[], 0, 'No application fee. Apply with the GVSU application or the Common App. Needs an official transcript in English (WAEC results for West African applicants). Admission is rolling and reviewed holistically (courses, cumulative GPA, GPA trend, test scores if sent). Admission to GVSU does not guarantee entry to some programs (including Engineering, Nursing and Seidman College of Business), which have extra requirements listed in the catalog. After admission an international student sends the Financial Verification Form for the I-20.', 'eabb6f3c-37b6-5a2e-96a6-dce51c043db3');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('656eebb3-8dde-5558-b299-eaaec0086cdc', '9bd85eba-6736-55de-ba4f-0bfbfa121f33', '2026-27', 'application', 'ROLLING', 'International application deadline, fall 2027', '2027-06-01', 'The page prints ''June 1'' for Fall Semester (August) with no year; taken as fall 2027. GVSU admits on a rolling basis and says admission to any term is subject to earlier closing without notice. The winter (January) deadline is Nov 1.', 'eabb6f3c-37b6-5a2e-96a6-dce51c043db3'),
 ('1064c7b5-5add-5fb5-bd90-1b3fcafbe6b8', '9bd85eba-6736-55de-ba4f-0bfbfa121f33', '2026-27', 'other', null, 'Financial Verification Form for I-20 due (fall 2027)', '2027-07-01', 'Deadline to submit the Financial Verification Form for the I-20 (fall semester). Year assumed 2027; for winter it is Nov 15.', 'eabb6f3c-37b6-5a2e-96a6-dce51c043db3'),
 ('5fa0b891-2398-5f7b-949a-5d8c54ee6c2d', '9bd85eba-6736-55de-ba4f-0bfbfa121f33', '2026-27', 'scholarship', null, 'International Merit Scholarship application (recommended date)', '2027-02-15', 'GVSU recommends applying by Feb 15; review begins in October and continues until funds are awarded. Fall-start students only.', 'e8c36957-b9bc-5169-a39d-6111f7465643');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('9bd85eba-6736-55de-ba4f-0bfbfa121f33', 'required_nonnative', 'Waived for applicants from a list of English-speaking countries (e.g. Australia, Canada, Ghana, Ireland, Kenya, Nigeria, New Zealand, South Africa, United Kingdom), for non-citizens with a U.S. high school/college diploma, 30+ U.S. college credits with C or higher in college English, or at least two years at an accredited U.S. high school. Alternatives to a test: SAT EBRW 470, ACT English 15, AP English Language 3, IB English HL 5, Michigan English Test 52. Scores must be sent by the testing agency. No conditional admission or ESL pathway is described on GVSU''s official admissions pages.', 'eabb6f3c-37b6-5a2e-96a6-dce51c043db3');
insert into english_requirements (institution_id, source_id, test_key, status, min_total, notes)
