insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('9c86dfbf-11f2-574a-82ad-4aca309eb19d', '2026-27', 'optional', 'Test-optional for most applicants (since 2015). SAT/ACT still required for B.A./B.S.-M.D. applicants, homeschooled applicants, and applicants from schools that give only narrative evaluations. Superscores SAT and ACT. Choose test-optional before submitting; changes allowed only within 2 weeks of submission.', 'e117a730-b12b-58ae-9ad5-fd8d7258a9ae');
insert into application_requirements (institution_id, cycle, platforms, teacher_recs, counselor_rec, interview, app_fee_usd, notes, source_id) values
 ('9c86dfbf-11f2-574a-82ad-4aca309eb19d', '2026-27', array['common_app','coalition']::text[], 0, true, 'not_offered', 80, 'One letter of recommendation required, from a counselor or an academic teacher. Optional writing supplement. Evaluative interviews are not required or offered; an optional InitialView video interview does not replace the English requirement. BFA applicants (except Interior Architecture) need a portfolio.', 'e117a730-b12b-58ae-9ad5-fd8d7258a9ae');
