insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, pct_submit_sat, pct_submit_act, notes, source_id, source_note) values
 ('41c72258-131f-5984-aa99-07cbd4bdaf1b', '2024-2025', 2714, 1914, 854, 18, 75, 'Baseline from IPEDS fall 2024 (no Common Data Set found on harding.edu): 2,714 applied, 1,914 admitted (71%), 854 enrolled (45% yield). College Navigator: SAT/ACT, GPA, secondary school record, recommendations and an English proficiency test are ''required to be considered''; essay and rank are not considered. SAT submitted by 157 enrolled first-time students (18%), ACT by 643 (75%); Harding also accepts the CLT. No SAT total percentile is published (only section scores). International applicant counts, GPA distribution and residency splits are not published.', 'dc56c25d-e0ff-5a9f-9c04-d3ba50861a80', 'admissions_site');
insert into test_score_percentiles (institution_id, cds_year, source_id, test, p25, p50, p75)
select '41c72258-131f-5984-aa99-07cbd4bdaf1b'::uuid, '2024-2025', 'c4162596-4f57-5fb2-92e6-b4b97a6dd2db'::uuid, v.* from (values
 ('SAT_ERW', 530, 590, 660),
 ('SAT_MATH', 520, 560, 630),
 ('ACT_COMPOSITE', 20, 24, 29),
 ('ACT_ENGLISH', 20, 24, 31),
 ('ACT_MATH', 18, 23, 26)) v;
insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('41c72258-131f-5984-aa99-07cbd4bdaf1b', '2026-27', 'required', 'Official SAT, ACT or CLT scores are a required part of admission (ACT science section not needed). Admission and scholarship eligibility for all international students require meeting minimum test score requirements, but the page does not publish the minimums. Send scores with SAT code 6267 or ACT code 0124.', 'b81422ee-88c5-5bf0-89c2-32a88f4bdbfa');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('41c72258-131f-5984-aa99-07cbd4bdaf1b', '2026-27', array['own']::text[], 50, 'Nonrefundable $50 fee. International steps: apply online; send transcripts through myiee.org (the $120 ''Document report + GPA'' option for a non-U.S. high school, or the school counselor sends a U.S. transcript); TOEFL or IELTS if English is not the official language; passport copy; confidential reference (required); and a $1,000 international deposit applied to first-semester tuition (refundable if the student cannot attend; no acceptance without it). The I-20 is sent only after acceptance. After acceptance, a $250 international enrollment fee and housing choice are due by May 1.', 'ea65c8e7-e09a-5970-8fe9-12b0b55ea830');
insert into deadlines (id, institution_id, cycle, kind, label, due_date, notes, source_id) values
 ('d6ab7f63-7b65-5b14-84cd-a52d94878ce4', '41c72258-131f-5984-aa99-07cbd4bdaf1b', '2026-27', 'application', 'International application deadline (fall 2027 entry)', '2027-06-01', 'Dates are printed without a year; treated as fall 2027. Spring semester application deadline is October 1.', 'ea65c8e7-e09a-5970-8fe9-12b0b55ea830'),
 ('1862cb04-11e5-5c63-b26f-81da5132b186', '41c72258-131f-5984-aa99-07cbd4bdaf1b', '2026-27', 'other', 'All required items for international admission due (fall 2027 entry)', '2027-07-01', 'Spring semester: all required items due November 1.', 'ea65c8e7-e09a-5970-8fe9-12b0b55ea830'),
 ('d3a54741-f4b8-55fa-95b9-22a5900aba2c', '41c72258-131f-5984-aa99-07cbd4bdaf1b', '2026-27', 'deposit', 'Enrollment fee and housing preferences (fall 2027 entry)', '2027-05-01', 'International page: $250 enrollment fee, deadline May 1. Domestic applicants get a discounted fee during the Oct. 1 to March 15 priority commitment period.', 'ea65c8e7-e09a-5970-8fe9-12b0b55ea830'),
 ('302e880f-83a0-57d6-977d-d55459a42586', '41c72258-131f-5984-aa99-07cbd4bdaf1b', '2026-27', 'scholarship', 'Walton International Scholarship Program deadline (as listed on Harding''s aid page)', '2026-10-31', 'The aid page lists the program (run by wispweb.org) with ''Deadline: October 31'' and no year; check eligibility and the year with WISP.', 'bb614480-3a11-5f9c-b1ed-2954f4d8cd15');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('41c72258-131f-5984-aa99-07cbd4bdaf1b', 'required_nonnative', 'TOEFL or IELTS is required ''if the official language is not English''; the page does not list other exemptions. Harding runs a full-time English as a Second Language (ELS/ESL) program and a hybrid International Advance Program (9-12 hours of major classes while studying English); the ESL page describes the TOEFL 70 / IELTS 6.0 as the level for unconditional admission, so lower scores go through the ESL pathway. Scores must be sent directly from the testing center.', 'ea65c8e7-e09a-5970-8fe9-12b0b55ea830');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
select '41c72258-131f-5984-aa99-07cbd4bdaf1b'::uuid, 'required_option', 'ea65c8e7-e09a-5970-8fe9-12b0b55ea830'::uuid, v.* from (values
 ('TOEFL_IBT', 70, 'Page states TOEFL 550 (paper) or an equivalent combined 70 on the iBT. Duolingo, PTE, Cambridge and the 1-6 TOEFL scale are not listed.'),
 ('IELTS', 6.0, null)) v;
insert into score_codes (institution_id, test_key, code, notes, source_id)
select '41c72258-131f-5984-aa99-07cbd4bdaf1b'::uuid, v.* from (values
 ('sat', '6267', 'Harding SAT code.', 'b81422ee-88c5-5bf0-89c2-32a88f4bdbfa'::uuid),
 ('act', '0124', 'Harding ACT code.', 'b81422ee-88c5-5bf0-89c2-32a88f4bdbfa'::uuid),
 ('toefl', null, 'No TOEFL institution code is listed on Harding''s international pages; look it up in the ETS code search.', 'ea65c8e7-e09a-5970-8fe9-12b0b55ea830'::uuid)) v;
insert into cost_aid (institution_id, year, tuition_usd, required_fees_usd, room_board_usd, total_coa_usd, intl_need_aid, meets_full_need, merit_scholarships, notes, source_id) values
 ('41c72258-131f-5984-aa99-07cbd4bdaf1b', '2026-2027', 28350, 1200, 10400, 39950, false, false, true, 'First-year estimate for 30 credit hours on Harding''s cost page (the page does not label its year, so 2026-27 is assumed): tuition $945 per hour = $28,350, technology fee $1,200, freshman housing $5,000, all-access meals $5,400 = $39,950 billable. The international admissions page still shows an older estimate ($37,484 including a $500 international fee and $1,692 health insurance with tuition $25,590), so budget extra for the international fee and mandatory insurance.; Federal aid is not available to international students and the university will not give assistance above actual tuition. Admitted freshmen can receive an Academic Achievement Scholarship of $7,000-$11,000 per year for four years based on test scores and GPA (full-time, 3.0 GPA to renew); the Trustee Scholar full-tuition award needs a 3.5 GPA and ACT 31 / SAT 1390 / CLT 100. The pages do not say whether these awards are open to international students. The College of Business lists a Sam Walton Scholarship ($3,000 per year, preference to non-U.S. business majors).', 'bb614480-3a11-5f9c-b1ed-2954f4d8cd15');
