insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, pct_submit_sat, pct_submit_act, notes, source_id, source_note) values
 ('43a686bf-a60b-569d-a483-40eff0b42d0f', '2023-2024', 2562, 2300, 367, 23, 41, 'Baseline from IPEDS (fall 2023 entering class; exact counts). UH Hilo does not publish a Common Data Set that could be found (its Institutional Research pages list none), so GPA, international and residency splits are not added; the international admit rate is unknown. College Navigator for fall 2024 shows 2,301 applicants, 61% admitted and 25% of admits enrolled (admit count not given as an exact number), SAT EBRW 490/610 and Math 455/565, ACT composite 15/22 (25th/75th), with 15% SAT and 41% ACT submitters. Undergraduate enrollment 2,292 and student-faculty ratio 11:1 are from College Navigator (fall 2024).', 'e1e788ea-fc82-5a6c-ae33-329bc9dec12d', 'admissions_site');
