insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('43a686bf-a60b-569d-a483-40eff0b42d0f', '2026-27', 'optional', 'The international page says a standardized test is not required for admission; SAT, ACT, IB Diploma or A-level results may earn college credit or exempt applicants from English requirements. The domestic freshman page considers a cumulative GPA below 2.7 on a sliding scale with official ACT/SAT scores.', '2b559aa7-91cb-5d84-9240-91dcdc250176');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('43a686bf-a60b-569d-a483-40eff0b42d0f', '2026-27', array['own']::text[], 50, 'Apply through the UH Hawaii Central Application (Fall 2027 link on the admissions pages); no Common App link was found. International first-years send an official English-language high school transcript, a passport copy, the International Student Supplemental Information Form and a sponsor bank statement or bank verification. Admission is based on the secondary school record: minimum 2.7 GPA (4.0 scale) and four years of English, three of math (Algebra I, Geometry, Algebra II), three of natural science and seven of college-preparatory electives. The financial support requirement is $37,080 on the international admission page and $39,258 on the 2026-27 cost page. Essays, recommendations and interviews are not mentioned.', '2b559aa7-91cb-5d84-9240-91dcdc250176');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('53b2ca68-caac-559a-bf0c-68e2ca4e769b', '43a686bf-a60b-569d-a483-40eff0b42d0f', '2026-27', 'priority', null, 'Recommended date for F-1 applicants (fall 2027 entry)', '2027-03-01', 'Recommended so there is time for the I-20, SEVIS fee and visa interview. No year is printed; the page links the Fall 2027 application, so this is taken as March 1, 2027.', '2b559aa7-91cb-5d84-9240-91dcdc250176'),
 ('87d0e7ed-88c3-517c-8635-52b3a9827df7', '43a686bf-a60b-569d-a483-40eff0b42d0f', '2026-27', 'application', 'ROLLING', 'International application deadline (fall 2027 entry)', '2027-05-01', 'Listed on the page as the ''International Student Priority Deadline'' for Fall: May 1. The domestic freshman deadline is July 1 (documents July 15). Spring entry: October 1. No decision dates are published.', '2b559aa7-91cb-5d84-9240-91dcdc250176');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('43a686bf-a60b-569d-a483-40eff0b42d0f', 'recommended', 'A test score is not required if the other admission requirements are met: applicants with no score, or a score below the direct-admission levels, are admitted first to the English Language Institute (ELI). Applicants with three years of full-time schooling in English (documented) at a school in Australia, Canada (not Quebec), Ireland, New Zealand, the UK or the US need no test. Scores in the placement ranges (TOEFL iBT 61-99, IELTS 5.5-6.5, Duolingo 90) allow degree-program admission but require the English Language Placement Assessment on arrival and possible ESL classes; TOEFL iBT 100+ or IELTS 7.0+ avoids the placement assessment. SAT EBRW 525+ or ACT English plus Reading 40 (each 18+) also counts for direct admission.', '2b559aa7-91cb-5d84-9240-91dcdc250176');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
select '43a686bf-a60b-569d-a483-40eff0b42d0f'::uuid, 'recommended_option', '2b559aa7-91cb-5d84-9240-91dcdc250176'::uuid, v.* from (values
 ('TOEFL_IBT', 61, 'Direct admission to a degree program (paper-delivered TOEFL: 46). 61-99 requires the placement assessment; 100+ does not. Applicants without a score can enter the ELI. The page gives no section minimums.'),
 ('IELTS', 5.5, 'Direct admission to a degree program; 5.5-6.5 requires the placement assessment, 7.0+ does not (ELI page).'),
 ('DUOLINGO', 90, 'Direct admission to a degree program; the ELI page lists 90 as still requiring the placement assessment.')) v;
insert into score_codes (institution_id, source_id, test_key, notes)
select '43a686bf-a60b-569d-a483-40eff0b42d0f'::uuid, '2b559aa7-91cb-5d84-9240-91dcdc250176'::uuid, v.* from (values
 ('sat', 'No SAT institution code is printed on the UH Hilo admissions pages reviewed; look it up in the College Board code search.'),
 ('act', 'No ACT institution code is printed on the UH Hilo admissions pages reviewed.'),
 ('toefl', 'No TOEFL institution code is printed on the pages reviewed; the page says to send official results to the Admissions Office.'),
 ('ielts', 'No institution code is listed.'),
 ('duolingo', 'No institution code is listed.')) v;
insert into cost_aid (institution_id, year, tuition_intl_usd, required_fees_usd, room_board_usd, books_usd, other_usd, total_coa_usd, intl_aid_policy, intl_need_aid, meets_full_need, merit_scholarships, notes, source_id) values
 ('43a686bf-a60b-569d-a483-40eff0b42d0f', '2026-2027', 20448, 770, 10814, 1350, 5876, 39258, 'need_aware_limited', true, false, true, 'UH Hilo 2026-27 international budget as on the I-20: tuition $20,448, estimated fees $770, meals and housing $10,814, books and supplies $1,350, and other $5,876 (transportation $1,500 + personal care $2,776 + required medical insurance $1,600), total $39,258. The page''s summary line for books and medical insurance ($2,935) does not match its itemized $2,950, so the itemized figures are used.; UH Hilo International Student Scholarship: a limited number are awarded each year to F-1 students with outstanding academic merit and financial need; admitted new international students are considered automatically (no separate application) and notified by email. No amounts are published. International students can also use the UH System Common Scholarship Application (the 2026-27 deadline was March 2; 2027-28 dates not yet posted) and college dean''s scholarships. International students on F-1 visas do not file the FAFSA.', 'dfe4b065-5132-5cc7-8101-9ae3f2f8df58');
