insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('4c2e2e25-41ca-544c-95a4-53d4e6f86916', '2026-27', 'optional', 'The how-to-apply page says domestic students may apply without SAT/ACT scores; the international admissions requirements list only transcripts and proof of English, so no SAT/ACT is required. A strong SAT (EBRW 500) or ACT (no sub-score below 19) can also satisfy the English requirement.', '292f4a4d-934a-59dd-8799-368d05c73f1f');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('4c2e2e25-41ca-544c-95a4-53d4e6f86916', '2026-27', array['common_app','own']::text[], 45, 'First-year applicants use the HPU application or the Common App. International applicants send transcripts (unofficial accepted for review, official before registration; English translation required) and proof of English; the HPU page says to allow 7-10 business days for review. A personal statement of any length is part of the application, and recommendation letters and activities are also considered. After admission, a Statement of Financial Sponsorship plus bank documents are needed for the I-20. New full-time undergraduates pay a one-time $200 orientation fee.', 'cfb0b749-e090-5b58-b860-eae944780633');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notification_date, notes, source_id) values
 ('229974f4-dadd-5152-bbcd-5452c1ffcebb', '4c2e2e25-41ca-544c-95a4-53d4e6f86916', '2026-27', 'application', 'ED', 'Early Decision (fall 2027 entry)', '2026-11-15', '2026-12-31', 'Binding. If admitted, the enrollment deposit is due Feb. 1, 2027. The international pages list no separate international dates; the first-year dates apply.', 'c7d403ac-986d-58c4-b653-2302b4f48c61'),
 ('206d491f-2d6d-59d2-808b-1ca7d988171e', '4c2e2e25-41ca-544c-95a4-53d4e6f86916', '2026-27', 'application', 'EA', 'Early Action (fall 2027 entry)', '2026-11-15', '2026-12-31', 'Non-binding; admitted students have until May 1, 2027 to pay the enrollment deposit.', 'c7d403ac-986d-58c4-b653-2302b4f48c61'),
 ('3f5d0580-3af7-54a7-a37c-129df4ccdf05', '4c2e2e25-41ca-544c-95a4-53d4e6f86916', '2026-27', 'other', null, 'Residential Honors, Global Business Scholars, Engineering, Marine Science and Nursing Scholars program applications', '2026-12-01', null, 'Separate program deadlines for the cohort programs, per the HPU deadlines page.', 'c7d403ac-986d-58c4-b653-2302b4f48c61'),
 ('aa389f5e-c774-5909-a82c-4769178ff10e', '4c2e2e25-41ca-544c-95a4-53d4e6f86916', '2026-27', 'application', 'RD', 'Regular Decision (fall 2027 entry)', '2027-01-15', '2027-02-16', null, 'c7d403ac-986d-58c4-b653-2302b4f48c61'),
 ('2d975a40-a35d-5550-9569-ca86ef109a6e', '4c2e2e25-41ca-544c-95a4-53d4e6f86916', '2026-27', 'priority', null, 'Priority deadline (fall 2027 entry)', '2027-03-01', '2027-04-01', 'Applications after March 1, 2027 are reviewed on a rolling basis.', 'c7d403ac-986d-58c4-b653-2302b4f48c61'),
 ('b880afaf-959e-5126-99fc-a474d7a6f1aa', '4c2e2e25-41ca-544c-95a4-53d4e6f86916', '2026-27', 'scholarship', null, '#YouAreWelcomeHere Scholarship (50% of tuition, new F-1 international students)', '2027-03-01', null, 'Separate paper application with an essay emailed to international@hpu.edu; recipients notified in April. The page gives March 1 without a year, so it is treated as 2027. Not stackable with other scholarships; fall term only.', '1a03a785-678b-5f00-8c08-94fd6bc0232c'),
 ('f2c7834b-c53b-5248-a5c2-763475124bab', '4c2e2e25-41ca-544c-95a4-53d4e6f86916', '2026-27', 'deposit', null, 'Enrollment deposit for Early Action and other admitted students', '2027-05-01', null, 'Early Decision admits pay by Feb. 1, 2027.', 'c7d403ac-986d-58c4-b653-2302b4f48c61');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('4c2e2e25-41ca-544c-95a4-53d4e6f86916', 'required_nonnative', 'Test scores must be no more than two years old by the entry term. Other accepted proof: SAT EBRW 500; ACT with no sub-score below 19; AP English 3; IB English (HL or SL, Language A or B) 5; iTEP 3.7; 1 year at an English-medium college or 2 years at an English-medium high school (no ESL classes); completion of listed English-school levels (for example ELS 110, EF B2, Global Village Hawaii Level 6 or entry to 7); certain national exam grades from Denmark, Finland, Germany, Netherlands, Norway, Sweden; Gaokao needs an interview. Native English speakers from a long list of countries (for example the US, UK, Canada, Australia, Ireland, New Zealand, South Africa, Nigeria, the Philippines) are waived. HPU says it has programs to accommodate all levels of English; the page names no formal conditional-admission or ESL pathway program. The table on the page is headed ''graduate students'' but its intro and values describe undergraduate direct entry, and HPU''s online graduate pages list higher scores (TOEFL 80, IELTS 6.5, Duolingo 110).', 'ebbd0f4c-bf92-51ad-b1cc-a87bd227120d');
