insert into cost_aid (institution_id, year, tuition_usd, tuition_intl_usd, required_fees_usd, room_board_usd, books_usd, other_usd, total_coa_usd, intl_aid_policy, intl_need_aid, meets_full_need, merit_scholarships, merit_separate_app, notes, source_id) values
 ('4c2e2e25-41ca-544c-95a4-53d4e6f86916', '2026-2027', 37536, 37536, 1070, 22024, 800, 4532, 65962, 'merit_only', false, false, true, false, 'HPU 2026-27 cost of attendance, independent undergraduate, non-nursing (nursing tuition is $44,616). Food and housing is an estimate; other_usd is personal $1,800 + transportation $2,600 + loan fees $132. No separate international tuition rate is listed.; HPU says international scholarships cover up to 50% of tuition. International first-year and transfer applicants are considered for academic merit scholarships automatically at admission (no separate application; no amounts are published). Talent (vocal ensemble, band, orchestra, E-Sports) and athletic scholarships also exist. The Guaranteed Scholarship and Admission Program ($15,000/yr) is only for Hawaii high school seniors. International need-based aid is not mentioned.', 'f0c11851-58f6-5ff1-9b68-c9e03498a3a7');
