insert into major_admissions (id, institution_id, program, category_key, admit_model, capped, notes) values
 ('1af14e71-e88f-5756-9dbb-f5dcd5f2c46c', '4c2e2e25-41ca-544c-95a4-53d4e6f86916', 'Nursing, BSN', 'nursing', 'pre_major_competitive', true, 'First-year applicants choose Nursing-Pre Nursing, then apply separately to the BSN. HPU''s BSN page lists a Feb. 1 Guaranteed Pathway deadline, a Feb. 15 Competitive Pathway priority deadline and an April 1 secondary deadline (space permitting) for fall 2027 admission.');

