insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('acda72c5-7e79-50ed-bfd6-8d012ead41bc', '2026-27', 'optional', 'SAT/ACT are optional. UH Manoa uses a ''Do No Harm'' policy: a submitted score that would hurt your chance of admission or scholarship is left out. Admitted students'' middle 50% was SAT 1130-1350 and ACT 21-29 (fall 2025). International applicants may also submit IB, A-Level, Gaokao or other national exam results in place of SAT/ACT, per the international page.', 'd9f0bd79-9741-54a1-8a4c-24960a09fd53');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('acda72c5-7e79-50ed-bfd6-8d012ead41bc', '2026-27', array['own']::text[], 70, 'Apply through UH Manoa''s own application ($70, nonrefundable). International freshmen need a cumulative GPA comparable to a U.S. B (3.00) or higher, and official secondary-school transcripts mailed directly by the school or ministry, a Supplementary Information Form for international applicants, and certification of financial support with bank statements for the I-20. Admitted fall 2025 first-years had a middle 50% GPA of 3.49-4.04. Required courses: 4 English, 3 math, 3 science, 3 social science, 4 college-prep, 5 electives. Nursing, social work, education and some other programs have earlier deadlines.', '12379c66-5e93-5f96-a4e2-9bd48dad5e05');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('ad3b4d5b-10f4-5877-93d2-c15dd42a30ee', 'acda72c5-7e79-50ed-bfd6-8d012ead41bc', '2026-27', 'priority', 'ROLLING', 'Priority deadline (fall 2027)', '2027-01-05', 'Freshman priority deadline for the best access to financial aid and housing. This is also the deadline to apply to be considered for New Warrior Scholarships, including the Manoa International Excellence Scholarship (supplemental application due Feb 2, 2027).', 'd9f0bd79-9741-54a1-8a4c-24960a09fd53'),
 ('70d617d5-62ca-529a-beab-896ecb20a6f0', 'acda72c5-7e79-50ed-bfd6-8d012ead41bc', '2026-27', 'application', 'ROLLING', 'International fall 2027 final application deadline', '2027-04-01', 'Late applications may be accepted after the final deadline. Incomplete applications are not considered. Spring entry is Oct 1.', '12379c66-5e93-5f96-a4e2-9bd48dad5e05'),
 ('b70c1043-96ef-5d97-b505-0745399754cd', 'acda72c5-7e79-50ed-bfd6-8d012ead41bc', '2026-27', 'scholarship', null, 'International Merit Award priority date (fall entry)', '2027-06-01', 'Awarded to admitted F-1 applicants with a 3.3+ GPA; no separate application, the Office of Admissions selects recipients. Earlier is better.', '2b335ebf-4e4d-5bef-9582-d5ce7fd4e6a3');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('acda72c5-7e79-50ed-bfd6-8d012ead41bc', 'required_nonnative', 'Everyone not born in the U.S. must show English proficiency. Scores in the lower column let you be admitted through the English Language Institute (ELI), which adds English courses; scores in the higher column make you ELI exempt. Exempt by experience: native English speaker; last 6 years of schooling in the U.S. or American Samoa, Australia, Canada (except Quebec), Guam, Ireland, New Zealand, Saipan, Singapore or the UK; 60 transferable U.S. credits at 2.00 GPA; a UH community college A.A.; or a bachelor''s degree from the U.S. or those countries. Last 3 years of U.S. high school with 3.20 GPA plus SAT reading 470 admits through ELI.', '12379c66-5e93-5f96-a4e2-9bd48dad5e05');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, recommended_total, notes)
select 'acda72c5-7e79-50ed-bfd6-8d012ead41bc'::uuid, 'required_option', '12379c66-5e93-5f96-a4e2-9bd48dad5e05'::uuid, v.* from (values
 ('TOEFL_IBT', 61, 100, '61 = admission through the English Language Institute (ELI); 100 = ELI exempt. TOEFL PBT 500 / 600; TOEFL Essentials 7.0 / 10.5.'),
 ('TOEFL_IBT_2026', 3.5, 5.0, 'Same thresholds on the 1-6 scale: 3.5 for admission through the ELI, 5 for ELI exempt.'),
 ('IELTS', 5.5, 7.0, 'Academic test. 5.5 = admission through the ELI; 7.0 = ELI exempt.'),
 ('DUOLINGO', 90, 135, '90 = admission through the ELI; 135 = ELI exempt.'),
 ('PTE', 44, 68, 'PTE Academic. 44 = admission through the ELI; 68 = ELI exempt.'),
 ('CAMBRIDGE', 161, 185, 'Cambridge English scale: 161 = admission through the ELI; 185 = ELI exempt.')) v;
