insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('b349dd4c-cf43-5e9f-830b-8f568ddcc644', '2026-27', 'optional', 'Freshmen may apply ''test optional'': SAT or ACT scores are not required to be considered for admission (the traditional option submits scores, which are then considered). International applicants outside the U.S. still need proof of English proficiency, which SAT/ACT scores can supply (SAT 480 EBRW and 1010 combined; ACT 20 English and 21 composite per the English page).', 'ffd1181f-521f-5d25-bead-606561a96d53');
insert into application_requirements (institution_id, cycle, platforms, supplemental_essays, app_fee_usd, notes, source_id) values
 ('b349dd4c-cf43-5e9f-830b-8f568ddcc644', '2026-27', array['own']::text[], 'No essay component on the HCU application.', 0, 'HCU''s own online application (the page does not mention the Common App); ''no fee for undergraduate applications'' (CDS C13 also says no application fee). International freshmen outside the U.S. submit: high school transcripts for grades 9, 10 and 11 (a foreign transcript evaluation may be requested; WAEC-type regional exam results are not accepted), proof of English proficiency, a passport copy valid 6 months beyond arrival, and financial documentation (HCU Financial Affidavit plus 3 months of bank statements or an official bank letter showing one academic year of funds) for the I-20. Interview and recommendation requirements are not stated on the pages reviewed.', '7bf4ebfa-b03f-581b-924a-1a86b4f395d0');
insert into deadlines (id, institution_id, cycle, kind, label, due_date, notes, source_id) values
 ('1b6f4e43-a68f-549a-9e23-4232589cd612', 'b349dd4c-cf43-5e9f-830b-8f568ddcc644', '2026-27', 'application', 'International application deadline, fall 2027 entry', '2027-06-01', 'HCU''s International Student Admissions Guide gives Fall: June 1, Spring: November 1, Summer: March 1 (no year printed; treated as fall 2027). CDS C14 says the university has no application closing date for domestic first-years, and admission decisions are quick once all documents are in. Allow time for the I-20 and visa.', 'c9b3bcd2-c6ea-592a-b8a6-ef7ce8860490');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('b349dd4c-cf43-5e9f-830b-8f568ddcc644', 'required_nonnative', 'Only one option is needed: an English test, two semesters of non-remedial U.S. college freshman English (grade C or better), an HCU-approved English language program (Language Consultants International, The Learning Institute of Texas, or BEI), graduation from an accredited U.S. high school or an international high school taught fully in English, or citizenship of a listed English-speaking country (e.g. Australia, Canada, Ghana, Ireland, Jamaica, Kenya, New Zealand, Nigeria, South Africa, United Kingdom). Official scores must come directly from the testing agency. The pages do not describe a conditional-admission or ESL bridge at HCU.', '033bdf95-2ef8-52ae-a4f9-5d2f5ac51ff3');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
select 'b349dd4c-cf43-5e9f-830b-8f568ddcc644'::uuid, 'required_option', '033bdf95-2ef8-52ae-a4f9-5d2f5ac51ff3'::uuid, v.* from (values
 ('TOEFL_IBT', 80, 'Exams taken before 2026-01-21. HCU''s TOEFL code is 6282. No section minimums are listed.'),
 ('TOEFL_IBT_2026', 4.0, 'Exams taken after 2026-01-21. The page lists ''4.0'' without naming the 1-6 scale.'),
 ('IELTS', 6.5, 'Academic module. HCU has no IELTS institution code; scores are sent directly.'),
 ('DUOLINGO', 105, null),
 ('PTE', 53, 'PTE Academic.')) v;
insert into score_codes (institution_id, source_id, test_key, code, notes)
select 'b349dd4c-cf43-5e9f-830b-8f568ddcc644'::uuid, '033bdf95-2ef8-52ae-a4f9-5d2f5ac51ff3'::uuid, v.* from (values
 ('sat', '6282', 'College Board code for HCU as listed on the English proficiency page.'),
 ('act', '4101', 'ACT code for HCU as listed on the English proficiency page.'),
 ('toefl', '6282', 'ETS institution code.'),
 ('ielts', null, 'HCU states there is no institution code for IELTS; scores are sent directly.'),
 ('duolingo', null, 'No institution code is listed.'),
 ('pte', null, 'No institution code is listed.')) v;
insert into cost_aid (institution_id, year, tuition_usd, required_fees_usd, room_board_usd, books_usd, other_usd, total_coa_usd, intl_aid_policy, intl_need_aid, intl_need_aid_awarded, intl_avg_award_usd, meets_full_need, merit_scholarships, notes, source_id) values
 ('b349dd4c-cf43-5e9f-830b-8f568ddcc644', '2026-2027', 42050, 2680, 13642, 1330, 4721, 64423, 'need_aware_limited', true, 113, 31106, false, true, 'CDS G1/G5 (2026-27, residential): tuition $42,050; required fees $2,680; housing $9,072 + meals $4,570 = $13,642; books $1,330; transportation $1,919 + other $2,802 = $4,721. total_coa_usd is the sum of those components (not a printed total). CDS H6: institutional need-based and non-need-based aid are both marked available to nonresidents; 113 degree-seeking nonresidents received it, average $31,106, total $3,514,978.; HCU merit scholarships are applied automatically and ''open to international students; the requirements remain the same for all applicants.'' Freshman awards for the 2027-28 year (unweighted HS GPA, test-optional): Founders up to $27,000 (GPA 3.88-4.0), President''s up to $24,000 (3.68-3.87), Legacy up to $22,000 (3.30-3.67), University Grant I up to $16,000 (3.0-3.29), University Grant II up to $14,000 (2.99 or below), per year; SAT/ACT awards of $2,000-$3,000 stack on top. Merit renewal needs a 3.0 (Founders, President''s) or 2.5 (Legacy, grants) HCU GPA and full-time enrollment. International students cannot receive federal aid. CDS H6 marks both institutional need-based and non-need-based aid as available to nonresidents (113 recipients, average $31,106); the website describes only merit awards.', 'c0752305-fd48-535b-9dd4-4efa2786bc94');
