insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('cc15eeaa-d36e-578b-9aee-3d7593f9fe34', '2026-27', 'optional', 'Standardized test scores are not required and submitting them cannot hurt an application. International freshmen need not submit SAT/ACT unless they attended a U.S. high school for three or more years, but scores may make them eligible for scholarships.', '3dde5303-0a2e-54b1-bd90-b043a933c892');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('cc15eeaa-d36e-578b-9aee-3d7593f9fe34', '2026-27', array['common_app','own']::text[], 65, 'Application fee $65 for summer/fall 2027 ($55 spring 2027). International undergraduates apply through the Student Application Portal (the Common App is also accepted for fall freshmen, with no preference); applicants recruited by INTO use the INTO Illinois State application. Required: unofficial academic records with official word-for-word English translation, English proficiency score (unless waived), passport, and a declaration of finances (bank statement within 6 months). Optional ~500-word academic personal statement; may be requested if the application needs further review. Fine arts majors have extra requirements.', '3dde5303-0a2e-54b1-bd90-b043a933c892');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('2b195063-4e3f-5c11-b2e1-a11bc08af46e', 'cc15eeaa-d36e-578b-9aee-3d7593f9fe34', '2026-27', 'priority', null, 'Freshman priority deadline, fall 2027 (priority window Aug. 1 - Nov. 1)', '2026-11-01', 'Apply before the priority date for best consideration for scholarships and for competitive or limited-enrollment majors. Page is the general freshman schedule and prints no year; taken as the fall 2027 cycle. Not specific to international applicants.', '7e7dc82f-bfe8-5e2f-821d-63692121b8c3'),
 ('d3406418-d9bf-58a7-a57e-86bd9cbaeb4e', 'cc15eeaa-d36e-578b-9aee-3d7593f9fe34', '2026-27', 'application', 'ROLLING', 'Freshman application and required-document deadline, fall 2027 (final documents for enrollment July 15)', '2027-04-01', 'Deadlines for summer and fall freshmen are subject to change without notice. Spring 2027 entry: application Nov. 1, documents Nov. 15, 2026. No separate international deadline is published; international students need extra time for the visa process.', '7e7dc82f-bfe8-5e2f-821d-63692121b8c3');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('cc15eeaa-d36e-578b-9aee-3d7593f9fe34', 'required_nonnative', 'Required for non-native speakers from non-Anglophone countries unless waiver qualifications are met (see ISU English Waiver Guidelines). Waiver-eligible countries include Australia, Canada, Ireland, New Zealand, the UK, Anglophone African countries (e.g. Ghana, Kenya, Nigeria, South Africa) and the Anglophone Caribbean. Scores must be dated within two years; PDF copies are fine for the application and official scores are needed after admission. Academic English and Pathway programs (including INTO Illinois State) are available for applicants who need English support.', '3dde5303-0a2e-54b1-bd90-b043a933c892');
