insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('3d7af03f-1881-5da3-8aed-79037d39e6a9', '2026-27', 'optional', 'The admissions page states test score submission is optional and the Apply page says no tests are required. An older Admissions Terminology page still says first-year students must submit ACT/SAT (no minimum score); the current pages take precedence. Freshman English-proficiency alternatives: SAT EBRW 520+ or ACT English 20+.', 'bfeb57cc-dcf0-576c-b078-a7a7140e94e5');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('3d7af03f-1881-5da3-8aed-79037d39e6a9', '2026-27', array['common_app','own']::text[], 0, 'No application fee for freshmen. Apply through UIW''s portal, ApplyTexas or the Common App; international applicants use the separate international application (applyintl.uiw.edu). Required: online application, official high school transcript in English, proof of English proficiency, passport copy and any US visa, proof of financial support. A minimum 2.5 GPA (4.0 scale) is required for unconditional admission. The international page prints no application fee.', '8f2bb24d-b839-5144-b4e4-c1246fbb0077');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('314e2dce-4c34-5c39-bf4c-0e6d8a1b9759', '3d7af03f-1881-5da3-8aed-79037d39e6a9', '2026-27', 'application', 'ROLLING', 'Rolling admission: no international application deadline published (fall 2027)', null, 'UIW says applications are accepted all year and reviewed on a rolling basis. The international page prints no deadline; allow time for the I-20 and visa. Contact intladmis@uiwtx.edu to confirm.', '8f2bb24d-b839-5144-b4e4-c1246fbb0077'),
 ('04eae10a-fc84-5c54-9c12-b663f6e8bcfb', '3d7af03f-1881-5da3-8aed-79037d39e6a9', '2026-27', 'priority', null, 'Freshmen encouraged to apply by Nov. 1 (fall 2027)', '2026-11-01', 'The freshman admissions page encourages applying by Nov. 1 for the following fall; it does not say this applies to international applicants and prints no year (treated as fall 2027).', 'bfeb57cc-dcf0-576c-b078-a7a7140e94e5');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('3d7af03f-1881-5da3-8aed-79037d39e6a9', 'required_nonnative', 'Exempt: graduates of US high schools; international or bi-national curriculum schools that award a US diploma, hold US regional accreditation or offer the IB diploma; third-country nationals who completed secondary or tertiary education in Australia, Canada (excluding Quebec), New Zealand or the UK (other English-speaking countries case by case). Freshman alternatives: SAT EBRW 520+, ACT English 20+, WAEC/SSCE English C4+, GCSE/IGCSE English First Language C+, KCSE English C+. TOEIC 650 is also accepted. Applicants below the minimum can be conditionally admitted into an ESL pathway with UNAM - San Antonio (see aid notes).', 'f7ce6d0c-20f1-527e-9d7e-193cc4967789');
insert into english_requirements (institution_id, source_id, test_key, status, min_total, notes)
select '3d7af03f-1881-5da3-8aed-79037d39e6a9'::uuid, 'f7ce6d0c-20f1-527e-9d7e-193cc4967789'::uuid, v.* from (values
 ('TOEFL_IBT', 'required_option', 79, 'The page lists no minimum for the new 1-6 TOEFL.'),
 ('IELTS', 'required_option', 6.5, 'IELTS Academic, overall band.'),
 ('DUOLINGO', 'required_option', 110, null),
 ('PTE', 'required_option', 53, 'PTE Academic.'),
 ('CAMBRIDGE', 'accepted', null, 'Cambridge Advanced (CAE) at level C1; the page gives no numeric score.')) v;
insert into score_codes (institution_id, test_key, notes)
select '3d7af03f-1881-5da3-8aed-79037d39e6a9'::uuid, v.* from (values
 ('sat', 'UIW pages read do not print a numeric SAT code; look it up in the College Board code search.'),
 ('act', 'UIW pages read do not print a numeric ACT code; look it up at act.org.'),
 ('toefl', 'No TOEFL institution code is printed on the pages read (UIW lists code 6303 for TOEIC only).'),
 ('ielts', 'No institution code is listed on the pages read.'),
 ('duolingo', 'No institution code is listed on the pages read.'),
 ('pte', 'No institution code is listed on the pages read.')) v;
insert into cost_aid (institution_id, year, tuition_usd, required_fees_usd, room_board_usd, books_usd, other_usd, intl_aid_policy, intl_need_aid_awarded, intl_avg_award_usd, meets_full_need, merit_scholarships, notes, source_id) values
 ('3d7af03f-1881-5da3-8aed-79037d39e6a9', '2025-2026', 36450, 2200, 15290, 300, 2368, 'merit_only', 150, 28829, false, true, 'CDS G1 (2025-2026): tuition $36,450, required fees $2,200, food and housing $15,290; G5 books $300. CDS H6 (2024-25): 150 degree-seeking nonresidents received institutional aid, average $28,829 (total $4,324,408); the need/non-need boxes were not readable.; First-time freshmen are automatically considered for academic scholarships based on high school GPA: $9,000-$22,000 per year (effective Fall 2026); the page gives no per-GPA tiers. Renewal needs a 2.0 cumulative GPA and 12 UIW credits each semester. 15% tuition discounts (Fall 2026) for undergraduates applying independently of an agent from Latin America, or from Indonesia, the Philippines, Thailand or Vietnam. CDS H6: 150 nonresidents received institutional aid, average $28,829. Conditional admission: UIW partners with UNAM - San Antonio for intensive English; students may apply without English scores, UNAM issues an I-20 for English courses only, intakes August and January (the page does not say how students move into degree courses). No international need-based aid is described.', '162413c7-358e-57d9-933f-7d6d21d43573');
