insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('d38493d8-6926-5a58-8acd-9f39efe3e7bb', '2026-27', 'optional', 'SAT/ACT are not required for admission; scores are needed only for certain merit-based scholarships and must be sent officially. Freshman admission asks for a cumulative GPA of 2.4 or higher on a 4.0 scale and a rigorous college-preparatory curriculum. The international page states no separate minimum GPA or score.', 'd1ff99c9-f101-5d56-8027-55bedcd1ac26');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('d38493d8-6926-5a58-8acd-9f39efe3e7bb', '2026-27', array['own']::text[], 65, 'Indiana State''s own online application (the Common App is not mentioned). Nonrefundable $65 fee. Required: credential evaluation from a NACES member or official transcripts sent directly by the school, financial guarantee (affidavit of support) plus an original current bank statement mailed by the bank, official English scores unless exempt, and a passport copy. Essays and recommendations are not mentioned.', '4eb67fbb-a58b-5a2e-9ad2-6f2f9e2647d3');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('a4b908bc-eb2f-5bde-a1d1-1325d16a873c', 'd38493d8-6926-5a58-8acd-9f39efe3e7bb', '2026-27', 'priority', 'ROLLING', 'International priority deadline, fall 2027 entry', '2027-06-01', 'Printed without a year, treated as fall 2027. Domestic freshman priority deadline is Aug. 1; the CDS lists application closing date Aug. 1 and priority June 1.', '4eb67fbb-a58b-5a2e-9ad2-6f2f9e2647d3'),
 ('ec01bf28-64f5-521a-9c2d-7191a726d1cc', 'd38493d8-6926-5a58-8acd-9f39efe3e7bb', '2026-27', 'application', 'ROLLING', 'Admission needed by this date for an I-20 (fall 2027 entry)', '2027-07-01', 'Page says students must be admitted by July 1 to receive an I-20 for fall; spring is Oct. 15 priority and Nov. 15 admit-by. Printed without a year, treated as fall 2027.', '4eb67fbb-a58b-5a2e-9ad2-6f2f9e2647d3');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('d38493d8-6926-5a58-8acd-9f39efe3e7bb', 'required_nonnative', 'Exempt: citizens of exempt countries, a degree or diploma from an approved exempt country, or 24 transferable credits completed in an exempt country (entering undergraduates). Accepted alternatives: completion of listed intensive English programs (e.g., ELS level 112, IU level 6, Spring International level 6) or an accepted NACES credential evaluation covering English. Scores must be two years old or less by the first day of class. The page does not mention conditional admission.', '1229bbe9-81ac-5ab0-a672-4138343839ce');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
