insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('3a0e4180-56b3-5912-93c3-0d67ad9fa3aa', '2026-27', 'optional', 'IU Bloomington is test-optional: applicants choose whether SAT, ACT or CLT scores are considered, though the university encourages sharing them. Scores received by Jan 15 can still count for scholarship consideration.', '7bba2c0d-3bf0-5372-84dd-da1d1fb01ecd');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('3a0e4180-56b3-5912-93c3-0d67ad9fa3aa', '2026-27', array['common_app','own']::text[], 65, 'Apply IU application or Common App (no preference). An essay is required on either platform (Apply IU: IU-specific essay of 200-400 words). Fee shown on the freshman application page; the international page lists no separate fee.', '8db47fc9-1a29-5f38-871a-9c8401edfa21');
