insert into cost_aid (institution_id, year, tuition_usd, tuition_out_of_state_usd, tuition_intl_usd, required_fees_usd, room_board_usd, books_usd, intl_aid_policy, intl_need_aid, intl_need_aid_awarded, intl_avg_award_usd, meets_full_need, merit_scholarships, notes, source_id) values
 ('301a78d8-1851-554b-8cea-bbdf8bb12255', '2025-2026', 9530, 28578, 28578, 1561, 10928, 800, 'merit_only', false, 566, 13144, false, true, 'CDS G1 first-year rates (the CDS ticks ''2026-27 costs not available yet'', so these are treated as 2025-26 rates; the ''Nonresident'' tuition line is used for international students). H6 (final 2024-25): only institutional non-need-based aid is available to nonresidents; 566 degree-seeking nonresidents received institutional aid, averaging $13,144 ($7,439,681 total). Tuition varies by program (G4: 63% pay more than the G1 figure).; Automatic International Student Excellence Award for admitted first-years, no separate application: President''s $56,000 total ($14,000/yr, needs SAT/ACT), Dean''s $48,000 ($12,000/yr, needs SAT/ACT), Innovator''s $40,000 ($10,000/yr, GPA 3.70+, no test needed), Launchpad $24,000 ($6,000/yr, GPA 3.50-3.69, no test needed); up to 8 semesters. Cannot be combined with the competitive International Merit Scholarship (OneApp; up to $40,000 or $16,000). Must accept the offer by May 1.', 'c6f2514d-f515-5985-858e-14dea830b637');
