insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, pct_submit_sat, pct_submit_act, notes, source_id, source_note) values
 ('a01d88d5-9140-53ef-abee-71d13acb7594', '2023-2024', 1749, 1246, 336, 23, 8, 'Baseline from IPEDS (fall 2023 entering class; exact counts). IU''s Common Data Set viewer (crimsoncatalog.iu.edu/cds) requires an IU login, so no CDS was read; GPA, international and residency splits are not added. College Navigator for fall 2024 shows 2,035 applicants and 67% admitted (exact count not published there); undergraduate enrollment and the 15:1 student-faculty ratio are fall 2024. IU East reports no campus housing to IPEDS.', '04964984-575a-5b29-8a38-649538a5c70a', 'admissions_site');
