insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('a01d88d5-9140-53ef-abee-71d13acb7594', '2026-27', 'optional', 'Test-optional since the 2021 terms: applicants choose on the application whether IU East considers SAT/ACT scores. The School of Education requires a test score, and IU East''s merit-based scholarships require submitted scores.', '787ccaac-4a3e-54ce-9b56-50b8b36ea2e6');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('a01d88d5-9140-53ef-abee-71d13acb7594', '2026-27', array['own']::text[], 65, 'Apply IU application (select IU East as home campus); the international page states a $65 non-refundable fee. Holistic review of diploma type (Indiana Academic Honors or Core 40 expected, comparable credits for other systems), GPA, class rank (upper half) and test scores if submitted; conditional admission may be available to those below the criteria. International applicants submit official academic records sent directly by the issuing school, with certified English translations; private credential evaluations (ECE, WES) do not replace official transcripts. The pages reviewed look partly dated (banner from 2020).', 'fadca433-4950-586f-8142-20a0d5b5a952');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('d138fce8-5865-543b-9900-517430f1b60a', 'a01d88d5-9140-53ef-abee-71d13acb7594', '2026-27', 'scholarship', 'ROLLING', 'Early-application scholarship date, fall', '2027-03-01', 'Printed as an early application scholarship date of March 1 with no year; taken as fall 2027 entry.', 'dec7e23c-c117-528f-98e4-e2b871c76b4f'),
 ('eb8952db-1642-5321-8466-a2aa121dbf7f', 'a01d88d5-9140-53ef-abee-71d13acb7594', '2026-27', 'priority', 'ROLLING', 'Application priority date, fall 2027 entry', '2027-05-01', 'Printed as ''May 1 - Application priority date for Fall Semester'' with no year; taken as fall 2027. Spring priority date is October 1. Applications are reviewed daily and the page says an update comes within 48 hours of a complete file. No separate international deadline is printed.', 'dec7e23c-c117-528f-98e4-e2b871c76b4f');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('a01d88d5-9140-53ef-abee-71d13acb7594', 'required_nonnative', 'Not required for citizens of, or those with three full years of secondary school in, the listed approved English-speaking countries (e.g. Australia, Canada, UK, Singapore, Hong Kong, Nigeria, Philippines), or with 26+ credit hours from a U.S. post-secondary institution including a 100-level English composition course. Alternatives to a language test: SAT EBRW 560 or ACT English 21; STEP Eiken Pre-First Grade for residents of Japan. No ESL or conditional pathway is described for international applicants.', 'fadca433-4950-586f-8142-20a0d5b5a952');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
select 'a01d88d5-9140-53ef-abee-71d13acb7594'::uuid, 'required_option', 'fadca433-4950-586f-8142-20a0d5b5a952'::uuid, v.* from (values
 ('TOEFL_IBT', 79, 'Printed as a ''provisional minimum of 79+'' internet-based score (also 550 paper / 213 computer-based). The page does not list the new 1-6 TOEFL scale.'),
 ('IELTS', 6.0, 'Overall 6.0 or higher.'),
 ('DUOLINGO', 100, 'Duolingo English Test 100+.')) v;
insert into cost_aid (institution_id, year, tuition_usd, tuition_out_of_state_usd, tuition_intl_usd, notes, source_id) values
 ('a01d88d5-9140-53ef-abee-71d13acb7594', '2026-2027', 8424, 23255, 23255, 'IU 2025-27 approved rates for IU East full-time undergraduates, 2026-27: resident tuition $7,716.78 + mandatory fee $707.34 = $8,424.12; nonresident tuition $22,547.78 + mandatory fee $707.34 = $23,255.12. International students are assumed to pay the nonresident rate; the pages do not say so explicitly. IU East has no campus housing (IPEDS), so room and board are not listed. Program differentials apply to some majors.; International students are not eligible for U.S. federal aid or loans. IU East points them to IU East scholarships (use the ''Citizenship'' filter) and external scholarships; no international scholarship amounts are published on the pages reviewed.', 'fbafa734-4868-5d86-8235-a5e4db8bec83');
