insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('9d758500-4eec-590c-84ee-6021c91b5b97', '2026-27', 'optional', 'Test-optional: the applicant chooses whether SAT or ACT scores are considered. For international applicants an SAT EBRW score of 410 or ACT English 17 can also satisfy the English requirement.', 'fffaf618-e7e7-5666-86a6-3540719f37d5');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('9d758500-4eec-590c-84ee-6021c91b5b97', '2026-27', array['common_app','own']::text[], 65, 'Apply with Apply IU or the Common App (submit only one). CDS C13 and the steps page give a $65 nonrefundable fee; the steps page also shows $70 for one international application path (graduate and non-degree), so $65 is used for first-year applicants. Transcript required; applicants above a 3.0 GPA need only the final high school transcript. International applicants must document finances for a visa.', '4ae9e949-f2c7-568d-a9ae-47f3d5f3e8e0');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('5907b3d5-83ba-54b5-9e61-05a279e5c685', '9d758500-4eec-590c-84ee-6021c91b5b97', '2026-27', 'scholarship', null, 'International ''apply by'' date for Honors College admission-timing and scholarship consideration (fall 2027 entry)', '2026-12-15', 'Page lists December 15 without a year (2026-27 cycle); treated as December 2026 for fall 2027. The Honors College application itself is shown as February 15 on the dates page and March 1 on the scholarships page.', 'b8e5db9f-4a16-58e4-bfc9-0e3430da1d49'),
 ('10e8d112-b447-5e72-98bc-b8be126f3015', '9d758500-4eec-590c-84ee-6021c91b5b97', '2026-27', 'scholarship', null, 'International ''apply by'' date to be considered for admissions-based scholarships (fall 2027 entry)', '2027-02-15', 'Page lists February 15 without a year; treated as 2027.', 'b8e5db9f-4a16-58e4-bfc9-0e3430da1d49'),
 ('89608356-7095-575e-b5a8-3892868f8c73', '9d758500-4eec-590c-84ee-6021c91b5b97', '2026-27', 'application', 'ROLLING', 'International ''apply by'' deadline, fall 2027 entry', '2027-05-01', 'Page lists May 1 without a year; treated as 2027. Domestic fall deadline is July 1 (CDS lists June 1). Spring entry: December 8.', 'b8e5db9f-4a16-58e4-bfc9-0e3430da1d49'),
 ('61c148b5-e4d2-5bcc-a908-ba9bf8174860', '9d758500-4eec-590c-84ee-6021c91b5b97', '2026-27', 'deposit', null, 'Priority date for $100 international enrollment deposit', '2027-05-01', 'If admitted on or after April 2, the deadline is 30 days after admission.', 'b8e5db9f-4a16-58e4-bfc9-0e3430da1d49');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('9d758500-4eec-590c-84ee-6021c91b5b97', 'required_nonnative', 'English can also be shown by completing upper secondary school with at least three years of study in a designated English-speaking country, IU Indianapolis Program for Intensive English (PIE) Level 5, ELS Level 109, GCSE/O Level English language grade C, IB HL English A grade 4, or a C in a U.S. freshman English composition course. Scores must be no more than two years old. Separate IU Indianapolis placement testing (EAP) may apply to some students after admission.', 'fffaf618-e7e7-5666-86a6-3540719f37d5');
