insert into cost_aid (institution_id, year, tuition_usd, tuition_out_of_state_usd, tuition_intl_usd, required_fees_usd, intl_extra_fees_usd, room_board_usd, books_usd, intl_aid_policy, intl_merit_aid, intl_need_aid_awarded, intl_avg_award_usd, meets_full_need, merit_scholarships, merit_separate_app, notes, source_id) values
 ('9d758500-4eec-590c-84ee-6021c91b5b97', '2026-2027', 9518, 33983, 33983, 1244, 331, 13656, 1290, 'merit_only', true, 117, 12369, false, true, false, 'CDS G1 first-year 2026-27: in-state tuition $9,518, out-of-state $33,983 (international students pay the out-of-state rate), required fees $1,244, on-campus food and housing $13,656; G5 books $1,290. The international office estimates $36,110 tuition and fees (incl. the $331/year international services fee) and $56,258 total for 9 months. H6: 117 nonresident undergraduates received institutional aid, average $12,369; the need-based/non-need-based checkboxes in H6 are ambiguous in the text, so intl_need_aid is left unset.; International applicants are considered automatically for an admission-based scholarship when they apply; scholarship amounts for international students are not published on the pages read. Students must be enrolled full-time; funds cannot be used for intensive English study. Further scholarships (including Honors College) need separate applications. CDS H6: 117 nonresident undergraduates received institutional aid, average $12,369.', 'bc8f8cf5-e440-52c4-a1cf-81eb57272085');
