 ('act', null, 'The admissions pages reviewed print no ACT code; look it up at act.org.', '84d18950-3dec-586e-a7a2-4de375dc28fd'::uuid),
 ('toefl', '1339', 'IU South Bend''s TOEFL test center code; scores must come directly from ETS (hand-carried reports are not accepted).', '685aad4b-0a53-5a8a-8c83-3034c37293dd'::uuid),
 ('ielts', null, 'No institution code is listed.', '685aad4b-0a53-5a8a-8c83-3034c37293dd'::uuid),
 ('duolingo', null, 'No institution code is listed.', '685aad4b-0a53-5a8a-8c83-3034c37293dd'::uuid),
