insert into cost_aid (institution_id, year, tuition_usd, tuition_out_of_state_usd, tuition_intl_usd, required_fees_usd, room_board_usd, books_usd, other_usd, intl_aid_policy, intl_need_aid_awarded, intl_avg_award_usd, meets_full_need, merit_scholarships, notes, source_id) values
 ('7590938f-4869-5fb6-b0c7-c4936a9b14db', '2026-2027', 7717, 22548, 22548, 707, 9816, 1290, 2724, 'merit_only', 23, 8059, false, true, 'Indiana University''s approved 2026-27 full-time undergraduate rates for South Bend: resident tuition $7,716.78, nonresident tuition $22,547.78, combined mandatory fee $707.34 (nonresident total $23,255.12); international students are charged the nonresident rate (the CDS G1 shows $22,325, which equals the 2025-26 nonresident rate). Food and housing $9,816, books $1,290, and other $2,724 (transportation $364 + other expenses $2,360, resident student) are from CDS G1/G5; the CDS box says final 2026-27 costs were not yet available, so the room-and-board and expense figures may be 2025-26 estimates. No total cost of attendance is printed. CDS H6 (the aid year appears to be 2024-25 final; the checkbox is ambiguous in the text): both need-based and non-need-based institutional aid are ticked as available to nonresidents; 23 undergraduate nonresidents received it, average $8,059 (total $185,367). Program differentials (for example nursing $4,478.40) are extra.; Up to twelve $2,000 first-year scholarships for F-1/J-1 students admitted for fall by June 15 (first year only). The International Student Fee Remission Scholarship ($4,000-$6,000 a year on average) is for students with at least one year of study, a 3.0 GPA and demonstrated need. IU Foundation and college scholarships are due March 1. The Chancellor''s Merit Award (pay 150% of in-state tuition, 3.0 GPA) lists ''eligible non-citizen'' and the page cites an Indiana law limiting institutional scholarship funds for non-citizens, so F-1 eligibility is unclear; the OISS page says it is open to F-1/J-1 undergraduates who come from a U.S. high school or college. CDS H6: 23 nonresident undergraduates received institutional aid, average $8,059.', '4e136f8a-7027-5b4c-8fee-72f764cc70bc');
insert into institution_tiers (institution_id, category_key, tier_code, rationale) values
 ('7590938f-4869-5fb6-b0c7-c4936a9b14db', 'general', 'D', 'Admit rate 81.5%; SAT middle 50% 950-1150');

