insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, pct_submit_sat, pct_submit_act, notes, source_id, source_note) values
 ('989bf249-9bec-5933-94a2-f374281befcb', '2023-2024', 14141, 12873, 978, 12, 29, 'Baseline from IPEDS (fall 2023 entering class, exact counts). JSU''s newest posted Common Data Set is 2019-2020, too old to use, so SAT total, GPA, residency and international splits are not available. College Navigator fall 2024: 15,487 applicants, 93% admitted, 7% of admitted enrolled (admit count not published as a number). Undergraduate enrollment 4,650 is fall 2024.', '913cd6b2-d24d-5f8c-9816-1733ee8bd5a3', 'admissions_site');
insert into test_score_percentiles (institution_id, cds_year, source_id, test, p25, p50, p75)
