insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('989bf249-9bec-5933-94a2-f374281befcb', '2026-27', 'optional', 'Policy document (updated 9.12.25): JSU is test optional; freshmen with an unweighted 3.20 GPA need no ACT/SAT. Other routes: 2.50 GPA or top 50% with ACT 16, or 2.00 GPA with ACT 18 (SAT equivalents accepted). For applicants from non-U.S. high schools the policy says ''ACT or SAT scores may be required'', and the JSU Global admissions page (copyright 2023) lists ACT 16 or SAT 790 (excluding writing) for international undergraduates. Confirm with JSU Global.', '9f05bff7-990e-547c-ab05-e481cca4f8de');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('989bf249-9bec-5933-94a2-f374281befcb', '2026-27', array['own']::text[], 25, 'Non-refundable $25 application fee (admission policy, freshman). Applications go through JSU''s own Future Tigers portal. International transcripts need a professional course-by-course evaluation (WES, Josef Silny, ECE, IEE or similar). A Certified Declaration of Financial Support covering one academic year is submitted to JSU Global after admission (no dollar amount published). International students need an IGRA blood test and chest X-ray done in the U.S. no more than six weeks before classes. Decisions are said to take 7-10 business days after documents arrive.', '9f05bff7-990e-547c-ab05-e481cca4f8de');
insert into deadlines (id, institution_id, cycle, kind, label, due_date, notes, source_id) values
 ('9f277967-7dbc-5ccc-be8e-3f8a483449bc', '989bf249-9bec-5933-94a2-f374281befcb', '2026-27', 'priority', 'International priority deadline, fall 2027 entry', '2027-08-12', 'International admissions page prints ''Fall: August 12'' (priority) without a year (treated as fall 2027). It advises applying four months before the term. The admission policy separately says students are encouraged to apply on or before July 15 for fall. Spring priority date Jan. 13.', '7a109fb2-2a8c-517a-a493-145c5c6bdb40'),
 ('8efb09dd-d3cf-5c96-a124-18d8cd420ae8', '989bf249-9bec-5933-94a2-f374281befcb', '2026-27', 'other', 'Recommended apply-by date for fall (admission policy)', '2027-07-15', 'Policy document: ''encouraged to apply on or before'' July 15 for fall; year not printed (treated as 2027).', '9f05bff7-990e-547c-ab05-e481cca4f8de'),
 ('48461115-c589-5db1-91c3-71ba51b8096a', '989bf249-9bec-5933-94a2-f374281befcb', '2026-27', 'scholarship', 'Freshman academic scholarship application window: Nov. 1 to Feb. 1', null, 'Provost (3.25 GPA + ACT 25 or SAT 1130; tuition only) and Presidential (3.5 GPA + ACT 32 or SAT 1420; full tuition, fees, room and board) scholarships. The page shows no year and does not say whether international students are eligible, so no date is recorded.', '1d2b66f6-7b61-57b5-83f6-5950a4f7367b');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('989bf249-9bec-5933-94a2-f374281befcb', 'required_nonnative', 'Exempt: non-citizens who graduated from a U.S. high school; transfers from a U.S. college with 30 transfer hours; citizens of English-speaking countries on JSU Global''s list (e.g. UK, Australia, Canada, New Zealand, Ireland, Nigeria, Ghana, certain Caribbean islands); students who complete JSU''s English as a Second Language Institute (ESLI). The ISSS page also accepts ACT English 19 or SAT Critical Reading 480. Duolingo, Cambridge and the new TOEFL 1-6 scale are not listed for undergraduates (the graduate school lists 4.0 on the 1-6 scale).', '9f05bff7-990e-547c-ab05-e481cca4f8de');
insert into english_requirements (institution_id, status, test_key, min_total, notes, source_id)
select '989bf249-9bec-5933-94a2-f374281befcb'::uuid, 'required_option', v.* from (values
 ('TOEFL_IBT', 69, 'Minimum iBT 69 (CBT 194, PBT 525).', '9f05bff7-990e-547c-ab05-e481cca4f8de'::uuid),
 ('IELTS', 6.5, 'Admission policy (9.12.25) and JSU Global admissions page say 6.5; the ISSS page says 6.0. The higher figure is recorded.', '9f05bff7-990e-547c-ab05-e481cca4f8de'::uuid),
 ('PTE', 53, 'PTE-A 53 appears only on the ISSS page, not in the admission policy.', '1014394d-0241-50de-afaa-2e43443f5464'::uuid)) v;
insert into cost_aid (institution_id, year, tuition_usd, tuition_out_of_state_usd, required_fees_usd, merit_scholarships, notes, source_id) values
 ('989bf249-9bec-5933-94a2-f374281befcb', '2026-2027', 9408, 13408, 440, true, 'JSU 2026-27 undergraduate fee sheet, per semester at 12-19 credit hours: Mississippi-resident tuition $4,704, non-resident adds $2,000 (total tuition $6,704), mandatory fees $220; totals $4,924 resident / $6,924 non-resident. Annual figures here are two semesters (tuition $9,408 resident, $13,408 non-resident; fees $440). F-1 students also pay a $100 international student fee per semester (JSU Global). Whether international students are billed the non-resident rate is not stated, so the international tuition field is blank. Housing and meal prices for 2026-27 were not clear enough to record.; ISSS page: no minimum test score for admission of international students, but ACT 25 (verbal and math) or SAT 1130 (reading and math) or higher qualifies for an out-of-state tuition fee waiver (the older fee-waiver form also needs a 3.25 GPA to renew). No scholarships are named specifically for international students.', 'f665caf8-ea10-530f-bca9-4e04b8a42f83');
insert into institution_tiers (institution_id, category_key, tier_code, rationale) values
 ('989bf249-9bec-5933-94a2-f374281befcb', 'general', 'D', 'Admit rate 91.0%');

