insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, pct_submit_sat, pct_submit_act, gpa_avg, pct_reporting_gpa, gpa_distribution, notes, source_id) values
 ('9e2085cf-76e3-54d0-8305-7adfe5d9c12f', '2025-2026', 11273, 8256, 1641, 4.6, 42.6, 3.45, 85.25, '{"4.0": 30.2, "3.75-3.99": 7.2, "3.50-3.74": 17.7, "3.25-3.49": 12.3, "3.00-3.24": 13.1, "2.50-2.99": 11.7, "2.0-2.49": 7.7, "1.0-1.99": 0.1}'::jsonb, 'CDS C1 (fall 2025): 3,951 men + 7,322 women applied, 2,858 + 5,398 were admitted, 1,641 enrolled (full- and part-time). The CDS leaves the in-state / out-of-state / international split of applicants and admits blank, so international applicant and admit counts are not available. No early decision or early action. Only 76 enrolled students submitted SAT scores (4.6%), so the SAT percentiles rest on a small group. Undergrad enrollment is the B1 total (9,028); intl_undergrads is the B2 nonresident total (231; IPEDS fall 2024 reports 373). The GPA distribution is as printed in C11 (30.2% at 4.0). Test-optional; the C7 importance checkboxes are not readable in the PDF, so no factors are recorded.', '4075863c-0ab9-5216-aa4c-8a90fdab088a');
insert into test_score_percentiles (institution_id, cds_year, source_id, test, p25, p50, p75)
select '9e2085cf-76e3-54d0-8305-7adfe5d9c12f'::uuid, '2025-2026', '4075863c-0ab9-5216-aa4c-8a90fdab088a'::uuid, v.* from (values
 ('SAT_TOTAL', 950, 1070, 1210),
 ('ACT_COMPOSITE', 17, 20, 24)) v;
insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('9e2085cf-76e3-54d0-8305-7adfe5d9c12f', '2026-27', 'optional', 'JSU is test-optional for freshman admission: ACT/SAT are not required and admission is based on high school GPA. International freshmen need a high school GPA of 2.0/4.0 (evaluated on the US scale). Scores can still help with placement, some programs and merit scholarship upgrades (test scores can only raise a scholarship, not lower it).', '653b790e-fe8e-5c6b-af0e-bdec2037de45');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('9e2085cf-76e3-54d0-8305-7adfe5d9c12f', '2026-27', array['own']::text[], 50, 'International freshmen apply on JSU''s own application: $50 non-refundable fee (the Bursar fee table lists $35; the international admissions page and FAQ say $50). Documents: international high school records showing a 2.0/4.0 GPA (translated if not in English), passport copy, English proficiency proof unless from an exempt country, and a financial statement (at least $38,300 effective spring 2027). Documents are uploaded to the application portal, not emailed; SAT/ACT/iTEP scores must come from the testing agency. An admitted student pays a $200 international application deposit before the I-20 is issued. Essays and recommendations are not mentioned.', 'c9259897-2aef-57eb-b012-3cb67f1d3ddf');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('33decd5f-5ce8-5d33-8b98-b8a93caabd7d', '9e2085cf-76e3-54d0-8305-7adfe5d9c12f', '2026-27', 'application', 'ROLLING', 'International application period closes (fall 2027 entry)', '2027-06-01', 'Fall 2027 application period is Aug. 10, 2026 to June 1, 2027 (classes begin Aug. 18, 2027). Spring 2027 period is June 1 to Nov. 1, 2026. JSU offers no summer intake for undergraduate international students. No earlier priority date is printed for admission.', 'c9259897-2aef-57eb-b012-3cb67f1d3ddf'),
 ('490ffd4b-7504-55d9-9496-9ec2644665ee', '9e2085cf-76e3-54d0-8305-7adfe5d9c12f', '2026-27', 'scholarship', null, 'Jones International House Program application deadline (priority March 1)', '2027-04-01', 'Program gives a tuition and fees scholarship plus a housing scholarship for up to 2 years. The page prints March 1 (priority) and April 1 without a year; treated as 2027. Applicant must already have a JSU ID and be admitted; undergraduate international applicants need a 2.5/4.0 high school GPA.', 'abf4a687-ca0d-5feb-bb03-e0be80b2f2c3'),
 ('345f77af-5652-5eb8-babc-5a3b3fe4d2a4', '9e2085cf-76e3-54d0-8305-7adfe5d9c12f', '2026-27', 'scholarship', null, 'Test scores due for freshman merit-scholarship upgrades (fall admits)', '2027-05-01', 'Merit scholarships are awarded automatically on admission from the highest cumulative high school GPA; scores received by May 1 can raise the award. Year not printed; treated as 2027.', '0095eb09-096f-51bb-a03c-bb9f02bc4efc');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('9e2085cf-76e3-54d0-8305-7adfe5d9c12f', 'required_nonnative', 'Students from listed English-speaking countries (e.g. Australia, Canada except Quebec, Ireland, Jamaica, Kenya, Nigeria, New Zealand, South Africa, United Kingdom) are exempt from the test requirement; transfers with 24+ credit hours from accredited US institutions may also be exempt. Alternatives to a test: completion of JSU''s English Language Institute (ELI) Level 4, iTEP 3.7, ACT composite 18 (English 14+) or SAT composite 960. The page also prints a SAT Critical Reading minimum of 19, which looks like a typo and is not recorded. Scores must be sent from the testing agency.', 'ab9e66ec-7d5f-5988-bd75-eef066d68f9e');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
select '9e2085cf-76e3-54d0-8305-7adfe5d9c12f'::uuid, 'required_option', 'ab9e66ec-7d5f-5988-bd75-eef066d68f9e'::uuid, v.* from (values
 ('TOEFL_IBT', 61, 'Undergraduate minimum for tests taken before 2026-01-21 (graduate: 79).'),
 ('TOEFL_IBT_2026', 3.5, 'Undergraduate minimum for tests taken on or after 2026-01-21. The page lists 3.5 without naming the 1-6 scale.'),
 ('IELTS', 5.5, 'Undergraduate minimum (graduate: 6.0).'),
 ('DUOLINGO', 85, 'Undergraduate minimum (graduate: 100).'),
 ('PTE', 45, 'Undergraduate minimum (graduate: 56).')) v;
