insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, pct_submit_sat, pct_submit_act, notes, source_id, source_note) values
 ('c33484bc-27e6-571b-a450-a6c1148de81b', '2023-2024', 8841, 7400, 1056, 14, 2, 'Baseline from IPEDS via College Navigator (fall 2024). JWU does not publish a Common Data Set that could be found (jwu.edu is behind a bot-protection page); the www.jwu.edu pages could not be read, so deadlines, test policy and requirements come from the JWU online catalog. College Navigator prints 7,828 applicants and 88% admitted (85% men, 90% women) but not the admit count, so admits is left null rather than back-computed; 16% of admitted students enrolled. Undergraduate enrollment is fall 2024 (3,908 of 4,303 total). International applicant counts, GPA, ED and residency splits are not available from this source. Applicant/admit/enrolled counts replaced with exact IPEDS ADM2023 (fall 2023) figures, because the newer source gives only a rounded admit rate.', 'cfbdc98f-84ab-5bb7-b41a-73395d6692d9', 'admissions_site');
insert into test_score_percentiles (institution_id, cds_year, source_id, test, p25, p50, p75)
