insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('f6040c2d-ba4d-59dc-aba6-4510dba616b5', '2026-27', 'optional', 'Kent State''s international first-year page states applicants are not required to submit ACT or SAT scores under its Test-Optional Policy. SAT EBRW 510 or ACT English 21 can be used to satisfy the English requirement.', '198bdc41-3466-5af3-9401-aeb01822b165');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('f6040c2d-ba4d-59dc-aba6-4510dba616b5', '2026-27', array['own']::text[], 70, 'International fee is $70 (CDS C13 lists $50 for domestic applicants). Minimum 2.5 GPA on a US 4.0 scale; some majors have selective requirements and applicants who miss them may be considered for the pre-major. Documents: passport page, English scores, secondary diploma and transcripts (certified English translation), and financial documents after acceptance. The page does not mention the Common App.', '198bdc41-3466-5af3-9401-aeb01822b165');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('97f0f409-39b6-5626-8023-5fffca94f397', 'f6040c2d-ba4d-59dc-aba6-4510dba616b5', '2026-27', 'priority', null, 'Priority date (fall 2027)', '2027-02-01', 'CDS C14 priority date 2/1 (not specific to international students).', 'db54cf06-8b82-5c2f-a74d-c14c513267c9'),
 ('fe561bba-9560-55e7-91bf-e4989565e701', 'f6040c2d-ba4d-59dc-aba6-4510dba616b5', '2026-27', 'application', 'ROLLING', 'International fall application deadline (fall 2027)', '2027-06-01', 'Spring deadline is Oct 1. Late applications are accepted, but international students are urged to apply early. CDS C14 lists a general closing date of Aug 1 and rolling notification beginning Oct 1.', '198bdc41-3466-5af3-9401-aeb01822b165'),
 ('de338ab3-ca8c-57a2-89aa-350bee42c6d5', 'f6040c2d-ba4d-59dc-aba6-4510dba616b5', '2026-27', 'scholarship', null, 'Admitted by this date to be considered for the Global Scholarship (fall)', '2027-07-01', 'Automatic consideration on admission; Spring deadline Nov 1, summer March 1. Honors College scholarship application is due Jan 15 for fall.', '4ad4299f-063d-5383-8212-f9359d536f5d'),
 ('c7e0e44d-0c45-52a4-bdd2-1519284916d7', 'f6040c2d-ba4d-59dc-aba6-4510dba616b5', '2026-27', 'deposit', null, 'Reply date (May 1 or within 2 weeks if admitted later)', '2027-05-01', 'CDS C17.', 'db54cf06-8b82-5c2f-a74d-c14c513267c9');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('f6040c2d-ba4d-59dc-aba6-4510dba616b5', 'required_nonnative', 'All international undergraduate applicants must submit a score unless they qualify for an English proficiency waiver (depends on educational background and country; see Kent State''s country list) or apply for conditional admission. Other accepted routes: SAT EBRW 510, ACT English 21, Kent State ESL Center Level 8 with 3.75 GPA, ELS Level 112, or a revised paper TOEFL average of 18. Applicants below the minimum may be admitted conditionally and take English classes at the ESL Center first.', '198bdc41-3466-5af3-9401-aeb01822b165');
