insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, pct_submit_sat, pct_submit_act, notes, source_id, source_note) values
 ('d96a0bac-de17-57d9-bec2-b993cb522a8f', '2024-2025', 1976, 1497, 146, 16, 4, 'Baseline from IPEDS (fall 2024 entering class, ADM2024); applicants, admits and enrollees are the exact IPEDS totals (enrolled = full-time 143 + part-time 3). College Navigator shows the same 1,976 applicants, 76% admitted and 10% of admits enrolled. No Common Data Set could be found on La Roche''s site or by search, so GPA, international applicant counts and in-state/out-of-state splits are not available. SAT/ACT percentiles are for enrolled first-time students and are test-optional self-selected: SAT 21 students, ACT only 5 students.', 'a35c22f6-e62d-5eee-976a-d56ef569a426', 'admissions_site');
