insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('d96a0bac-de17-57d9-bec2-b993cb522a8f', '2026-27', 'optional', 'SAT and ACT scores are optional for first-year and international applicants; they are considered if submitted and may also be used to determine direct admission. Some majors and programs have their own test score and GPA requirements. IPEDS (fall 2024) lists a high school GPA and record as required to be considered.', '04ead4a7-0c0a-553d-805a-bc348e776a7a');
insert into application_requirements (institution_id, cycle, platforms, supplemental_essays, notes, source_id) values
 ('d96a0bac-de17-57d9-bec2-b993cb522a8f', '2026-27', array['common_app','own']::text[], 'Optional short essay (250 words or less) on why a La Roche degree matters.', 'Apply with the Common App, the LRU online application or a paper form. International applicants send a high school transcript and diploma with notarized English translation, a TOEFL/IELTS/Duolingo score if available (otherwise La Roche''s English placement test decides Pathway or ESL placement), a passport photo page, a signed Affidavit of Support and an official sponsor bank statement dated within three months of the semester start. The pages do not state an application fee, a minimum GPA or recommendation requirements (IPEDS lists recommendations as required to be considered).', '2c3914ef-bef2-5fc9-9d46-049e6af996c8');
insert into deadlines (id, institution_id, cycle, kind, label, due_date, notes, source_id) values
 ('e7eed9e7-b3a7-5867-86f5-0f3fb0bb2c21', 'd96a0bac-de17-57d9-bec2-b993cb522a8f', '2026-27', 'priority', 'Recommended complete-application date, fall 2027 entry', '2026-11-01', 'The first-year page says applicants can apply at any time and recommends a complete application by Nov. 1 (fall) or Dec. 15 (spring) for the best financial aid and housing options; decisions come 10-14 days after a complete application. No year is printed, so Nov. 1 is taken as 2026 for fall 2027. No separate international deadline is published; contact international@laroche.edu or 412-536-1279.', '04ead4a7-0c0a-553d-805a-bc348e776a7a'),
 ('212703da-6428-5e3e-b6ed-7c3a3fb78fbe', 'd96a0bac-de17-57d9-bec2-b993cb522a8f', '2026-27', 'deposit', 'Nonrefundable $5,000 payment toward first-semester tuition', null, 'Required to be registered (and for the I-20); $2,000 for the ESL-only program. No due date is published.', '2c3914ef-bef2-5fc9-9d46-049e6af996c8');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('d96a0bac-de17-57d9-bec2-b993cb522a8f', 'required_nonnative', 'Applicants submit TOEFL, IELTS or Duolingo scores if available. Scores set the track: direct admission to the degree, a one-semester or two-semester Pathway (English courses plus degree credits), or ESL below that. Applicants without scores take La Roche''s English placement test. No exemption by country or school is listed on the pages read.', '07010f91-6d70-5b01-b6bd-6bf85a60df1a');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
select 'd96a0bac-de17-57d9-bec2-b993cb522a8f'::uuid, 'required_option', '07010f91-6d70-5b01-b6bd-6bf85a60df1a'::uuid, v.* from (values
 ('TOEFL_IBT', 79, 'Minimum for direct admission; the Pathway page lists the test as ''TOEFL'' without naming iBT. One-semester Pathway 60-78, two-semester Pathway 46-59, ESL 45 or lower. A search-result snippet of a linked 2026 Pathway flyer (404 when fetched) showed higher cutoffs (direct admission TOEFL 87), so confirm with the international office.'),
 ('IELTS', 6.5, 'Minimum for direct admission. One-semester Pathway 6.0, two-semester Pathway 5.5, ESL 5.0 or lower.'),
 ('DUOLINGO', 115, 'Minimum for direct admission. One-semester Pathway 105-110, two-semester Pathway 90-100, ESL 85 or lower.'),
 ('PTE', 58, 'PTE Academic, minimum for direct admission. One-semester Pathway 50-57, two-semester Pathway 42-49, ESL 41 or lower.')) v;
insert into cost_aid (institution_id, year, tuition_usd, tuition_intl_usd, required_fees_usd, room_board_usd, books_usd, intl_aid_policy, intl_merit_aid, meets_full_need, merit_scholarships, notes, source_id) values
 ('d96a0bac-de17-57d9-bec2-b993cb522a8f', '2026-2027', 35018, 35018, 1520, 14942, 1000, 'merit_only', true, false, true, 'Figures are the ''Undergraduate (International)'' academic-year costs on La Roche''s international cost page (tuition $17,509 + fees $760 per semester; resident room $9,294 + meal plan $5,630 per year; books estimated $1,000; off-campus commuter living estimated $11,000). The page does not name an academic year (it says the figures are the average costs for a nine-month term as shown on the Form I-20), so 2026-2027 is assumed because the page is current in fall 2026; verify with the university. A nonrefundable $5,000 payment toward first-semester tuition is required to be registered ($2,000 for ESL-only). College Navigator''s 2024-25 tuition and fees were $34,052.; All international undergraduate applicants are automatically considered for the La Roche International Merit Award; the FAQ says directly admitted international undergraduates can receive up to $17,000 per year based on academic performance, renewable for four years with good standing (not for ESL, Pathway or summer courses). The #YouAreWelcomeHere Scholarship is $19,000 per year, renewable, for first-year international applicants who submit a 500-1,000 word essay or 2-5 minute video on intercultural learning; its fall 2026 deadline has passed and the fall 2027 date is to be announced. No international need-based aid is described.', 'faa02988-f11e-5eac-9ff6-82d4b4bd17f8');
insert into institution_tiers (institution_id, tier_code, category_key, rationale)
