insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, intl_applicants, intl_admits, in_state_applicants, in_state_admits, out_state_applicants, out_state_admits, pct_submit_sat, pct_submit_act, gpa_avg, pct_reporting_gpa, notes, source_id) values
 ('3156867a-8289-5bee-bcf6-75237cf83b9e', '2025-2026', 7460, 6231, 1685, 68, 60, 7260, 6063, 132, 108, 45, 5, 3.6, 98, 'CDS C1 (fall 2025): 7,460 applied, 6,231 admitted, 1,685 enrolled; residency split in-state 7,260 / out-of-state 132 / international 68 applicants (60 admitted, 11 enrolled). Texas-based applicant pool: only 68 international applicants. The printed SAT composite row is inconsistent with the section scores, so no SAT total is stored; section and ACT percentiles are from C9 (45% of enrolled first-years submitted SAT, 5% ACT). The GPA-range table in C11 is garbled in the PDF text, so no GPA distribution is stored. No early decision or early action; admission is rolling with no closing date. Intl undergraduate count is the B2 nonresident total (82; 80 degree-seeking). The CDS student-to-faculty line is outdated (fall 2022), so the ratio is from College Navigator (20 to 1).', '9412e9fc-c0f9-5711-bdbc-a4b2e1bc4c94');
insert into test_score_percentiles (institution_id, cds_year, source_id, test, p25, p50, p75)
