 ('act', null, 'The international pages do not print an ACT code; look it up at act.org.', 'bc82f7d8-2bab-5e75-a875-e10908a72854'::uuid),
 ('toefl', '6360', 'Lamar University institutional code for TOEFL and PTE.', '92b16283-68ee-5374-bb10-a8bd3d2096fc'::uuid),
 ('ielts', null, 'No institution code; email the PDF score card to admissions@lamar.edu.', '92b16283-68ee-5374-bb10-a8bd3d2096fc'::uuid),
 ('duolingo', null, 'No institution code is listed.', '92b16283-68ee-5374-bb10-a8bd3d2096fc'::uuid),
