insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, pct_submit_sat, pct_submit_act, notes, source_id, source_note) values
 ('3cc32b0f-0601-51fc-b30f-10df1a451491', '2023-2024', 5184, 3521, 846, 36, 18, 'Baseline from IPEDS (fall 2023 entering class): 5,184 applied, 3,521 admitted, 846 enrolled. No readable Common Data Set was found on Lander''s site, so GPA, international applicant/admit counts and SAT total are not available. Newer College Navigator figures (fall 2024): 4,565 applicants, about 81% admitted (rounded %), 3,776 undergraduates (used for enrollment here). Test optional; students submitting SAT/ACT are a minority.', '7ff5bedf-9018-5855-a369-673d2761a49b', 'admissions_site');
