insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('3cc32b0f-0601-51fc-b30f-10df1a451491', '2026-27', 'optional', 'Freshman page: SAT/ACT is test optional, but scores are required for Lander academic scholarships. Applicants are evaluated on course prerequisites, high school GPA and SAT/ACT scores if submitted. No minimum GPA is printed. The international page does not require SAT/ACT; an SAT verbal 450 or ACT verbal 18 is one optional way to show English proficiency.', '9d97bfed-65dc-501a-94e8-32368c7f9b54');
insert into application_requirements (institution_id, cycle, platforms, notes, source_id) values
 ('3cc32b0f-0601-51fc-b30f-10df1a451491', '2026-27', array['own']::text[], 'Online application on Lander''s site (no Common App listed). International applicants need official school records in the original language plus certified English translations, a course-by-course evaluation from a NACES-certified service (applicant pays), an affidavit of support stating the amount and length of funds, and English proficiency evidence; credentials must arrive at least 6 months before the term. Application fee is not stated on the admissions pages. Mandatory student health insurance applies after enrollment.', '1b97b0e7-e8e9-52e0-b1ab-4059ebccfc37');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('2dbe4b0e-2880-5c00-8cf9-42bf99d36c09', '3cc32b0f-0601-51fc-b30f-10df1a451491', '2026-27', 'application', 'ROLLING', 'International application deadline, fall 2027 entry', '2027-06-15', 'Fall June 15, spring Nov. 1, summer March 15 (international). Printed without a year; treated as fall 2027. The same page asks for credentials at least 6 months before the term, which is earlier than June 15 for an August start. Domestic freshmen apply by Aug. 1 on a rolling basis.', '1b97b0e7-e8e9-52e0-b1ab-4059ebccfc37');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('3cc32b0f-0601-51fc-b30f-10df1a451491', 'required_nonnative', 'Not required if English is the official native language, ENGL 101 and 102 were completed at a U.S. regionally accredited college, SAT verbal 450 or ACT verbal 18 is submitted, or the applicant holds a bachelor''s degree from a regionally accredited U.S. institution. TOEIC 600 is also accepted. Lander contracts with ELS Language Centers for English instruction; the ESL page says students can be admitted to Lander on completing ELS program level 112. Conditional admission is not described.', '1b97b0e7-e8e9-52e0-b1ab-4059ebccfc37');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, min_subscores, notes)
select '3cc32b0f-0601-51fc-b30f-10df1a451491'::uuid, 'required_option', '1b97b0e7-e8e9-52e0-b1ab-4059ebccfc37'::uuid, v.* from (values
 ('TOEFL_IBT', 70, null, 'Institution code 5363. The page does not give a separate 1-6 scale minimum.'),
 ('IELTS', 6.0, '{"each_section": 5.0}'::jsonb, '6.0 overall with no subscore below 5.0.'),
 ('DUOLINGO', 105, null, 'Minimum 105.'),
 ('PTE', 53, null, 'Minimum 53.')) v;
