insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, intl_applicants, intl_admits, in_state_applicants, in_state_admits, out_state_applicants, out_state_admits, pct_submit_sat, pct_submit_act, gpa_avg, pct_reporting_gpa, gpa_distribution, notes, source_id) values
 ('fd9aaeee-9ca2-5ac4-9b71-3d46885cc78b', '2024-2025', 2388, 1684, 589, 95, 34, 1271, 954, 1018, 694, 21, 69, 3.63, 96, '{"4.0": 17, "3.75-3.99": 36, "3.50-3.74": 19, "3.25-3.49": 12, "3.00-3.24": 9, "2.50-2.99": 5, "2.0-2.49": 1, "1.0-1.99": 1}'::jsonb, 'CDS 2024-25 C1 (fall 2024): 2,388 applied, 1,684 admitted, 589 enrolled. International first-year applicants: 95 applied, 34 admitted, 23 enrolled, so international admission was much more selective than the overall admit rate. The 2025-26 CDS is listed on lee.edu but its PDF could not be retrieved, so 2024-25 is used. Undergraduate enrollment (3,271) and intl_undergrads (85 nonresidents, all undergraduates) are CDS B1. No waitlist, ED or EA; no application closing date (C14).', '212172a0-226c-5b2b-a841-a7adb08bfc4d');
