insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('fd9aaeee-9ca2-5ac4-9b71-3d46885cc78b', '2026-27', 'optional', 'The admissions requirements page says applicants can apply without test scores; its minimums for those who submit are ACT 17, SAT 900, CLT 57, with a 2.0 high school GPA. The international page says to submit a TOEFL score or an SAT/ACT score. The 2024-25 CDS lists SAT/ACT as ''recommend'' and rates test scores very important in its factor table.', '65bd129b-af7f-5bee-8337-73a9f7ac34e8');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, fee_waiver, notes, source_id) values
 ('fd9aaeee-9ca2-5ac4-9b71-3d46885cc78b', '2026-27', array['own']::text[], 25, true, 'Apply on Lee''s own application. International applicants also submit certified English-language transcripts, a sponsor''s guarantee form with an original bank statement (US$41,000 for the first two semesters, plus US$5,000 per spouse and US$2,500 per child), a signed estimate-of-expenses form and a US$200 housing deposit. The $25 fee is from the booklet and the 2024-25 CDS (the web page does not state it).', '2e6ca049-0da3-5363-9e6a-bffc3ec0a2db');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('9679c47d-e16c-5266-a8d5-e31ad0df936a', 'fd9aaeee-9ca2-5ac4-9b71-3d46885cc78b', '2026-27', 'application', 'ROLLING', 'Rolling admission, no application closing date (fall 2027 entry)', null, 'CDS C14 says there is no application closing date and C16 says decisions are rolling beginning Aug. 1; no international deadline is published, only advice to apply well ahead of entry for the I-20 and visa.', '2e6ca049-0da3-5363-9e6a-bffc3ec0a2db'),
 ('eece9304-a37f-54a2-8983-d9ca9bee3cf6', 'fd9aaeee-9ca2-5ac4-9b71-3d46885cc78b', '2026-27', 'scholarship', null, 'Early action date for scholarships and financial aid (fall 2027 entry; assumed)', '2026-12-01', 'The financial aid page says applicants who complete the Lee application, Scholarship Profile and FAFSA before December 1 are early action candidates, with rolling decisions after; it notes the fall 2026 early action date was moved to Feb. 14 because of FAFSA delays. The December 1, 2026 date for fall 2027 is an assumption. The FAFSA applies to U.S. aid applicants, not international students.', '54118f0f-b2e8-503d-a75c-12a0575acb7b');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('fd9aaeee-9ca2-5ac4-9b71-3d46885cc78b', 'required_nonnative', 'All international students must submit an English proficiency score; this may be waived for native English speakers or those educated in English. Official SAT scores are also accepted. If a score is below the minimum, email international@leeuniversity.edu to discuss probationary admission.', '2e6ca049-0da3-5363-9e6a-bffc3ec0a2db');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
select 'fd9aaeee-9ca2-5ac4-9b71-3d46885cc78b'::uuid, 'required_option', '2e6ca049-0da3-5363-9e6a-bffc3ec0a2db'::uuid, v.* from (values
 ('TOEFL_IBT', 45, 'Internet-based 45 or higher (paper 450). No minimum is given on the 1-6 scale.'),
 ('IELTS', 6.0, 'Minimum score of 6.'),
 ('DUOLINGO', 80, 'Minimum 80; 110 is preferred.')) v;
