insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, pct_submit_sat, pct_submit_act, gpa_avg, notes, source_id, source_note) values
 ('111a9f5e-4c3a-5ca0-a716-c89e02bba57c', '2024-2025', 6302, 4493, 686, 24, 4, 3.57, 'No Common Data Set was found on lewisu.edu, so this is a baseline: first-year applicants/accepts/enrolled and average GPA (3.57) are from Lewis Quick Facts (fall 2024); test percentiles and submission rates (SAT 24%, ACT 4% of enrolled) are IPEDS fall 2024 via College Navigator. Quick Facts also gives averages (ACT 23.7, SAT 1084) and says 3.6% of the first-year class is international; international applicant/admit counts are not published. Undergraduate enrollment 4,326 is fall 2024.', '87e2e7aa-e735-55f1-bcd5-e31b1d063bd5', 'admissions_site');
insert into test_score_percentiles (institution_id, cds_year, source_id, test, p25, p50, p75)
