insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('111a9f5e-4c3a-5ca0-a716-c89e02bba57c', '2026-27', 'optional', 'Lewis is test-optional for first-year applicants for all programs, with the same consideration for admission and merit scholarships (scores, if sent, are also used in the scholarship review). Test-optional applicants submit a personal statement or graded school assignment. Official scores are requested before registration for course placement. The international page lists no SAT/ACT requirement.', 'ccf414d0-619d-54f5-9e8e-5c29faf1ae13');
insert into application_requirements (institution_id, cycle, platforms, notes, source_id) values
 ('111a9f5e-4c3a-5ca0-a716-c89e02bba57c', '2026-27', array['common_app','own']::text[], 'International first-year documents: application, secondary transcripts or national exam results, secondary school completion certificate, English proficiency scores, passport copy; then an affidavit of support for the I-20. Holistic review focuses on cumulative and core GPA and course rigor; recommendations are optional. No application fee amount is stated on the pages reviewed.', 'a14a407f-7ce9-537f-a5a7-27e09ceacbd1');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('9d752668-1a5c-5fa8-bbaf-5623dd82f9fa', '111a9f5e-4c3a-5ca0-a716-c89e02bba57c', '2026-27', 'application', 'EA', 'First-year early action, fall term (fall 2027 entry)', '2026-12-01', 'From the first-year deadline chart (no year printed; treated as fall 2027); early action decisions come before the holiday break. The international page lists no separate international deadline.', 'fbcadbba-a9fa-522d-a9bb-baf495004418'),
 ('371fd3ec-e396-5d07-b0b9-5bdd47f4289c', '111a9f5e-4c3a-5ca0-a716-c89e02bba57c', '2026-27', 'scholarship', null, 'Lasallian Scholarship Program deadline (apply and be admitted by this date)', '2027-01-01', 'Same chart; year treated as 2027.', 'fbcadbba-a9fa-522d-a9bb-baf495004418'),
 ('8a468db9-9e39-5b79-8953-f42a87b64b3d', '111a9f5e-4c3a-5ca0-a716-c89e02bba57c', '2026-27', 'priority', null, 'Priority scholarship consideration (fall 2027 entry)', '2027-03-01', 'The chart says applicants have the best chance for admission and scholarship consideration by applying before March 1.', 'fbcadbba-a9fa-522d-a9bb-baf495004418'),
 ('1f4df0ec-3a7e-5749-8bd8-479e5be829f9', '111a9f5e-4c3a-5ca0-a716-c89e02bba57c', '2026-27', 'application', 'RD', 'First-year regular admission, fall term (fall 2027 entry)', '2027-05-01', 'Spring term regular admission is January 1. Lewis aims to review a complete file in one to two weeks.', 'fbcadbba-a9fa-522d-a9bb-baf495004418');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('111a9f5e-4c3a-5ca0-a716-c89e02bba57c', 'required_nonnative', 'Applicants whose previous education was taught primarily in English may be exempt: citizens of countries on Lewis''s waiver list need no test; others can combine IGCSE/A Level or IB results with an ACT or SAT score, or submit an ESL graduation certificate from a partner school (ELS, Kaplan, LaSallian Language Center, local community colleges). U.S.-based transfer students with a degree or two college English courses may be waived. Lewis may test English on arrival and place students in support courses.', 'bd656243-611a-52d1-9a86-249c068e584d');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
