 ('TOEFL_IBT', 79, 'The page gives no minimum on the new 1-6 TOEFL scale.'),
 ('IELTS', 6.5, null),
 ('DUOLINGO', 105, 'Listed as ''Duolingo Academic''.'),
 ('PTE', 52, 'PTE Academic.')) v;
