 ('act', '2792', null, 'd219d428-37cc-5048-b8cf-de6230ffb42e'::uuid),
 ('toefl', null, 'No TOEFL institution code was found on the LIU pages read.', 'bc34083f-8e4a-5278-8ef1-d337291c08a1'::uuid),
 ('ielts', null, 'No IELTS code is listed.', 'bc34083f-8e4a-5278-8ef1-d337291c08a1'::uuid),
 ('duolingo', null, 'Scores are shared through Duolingo; no code is listed.', 'bc34083f-8e4a-5278-8ef1-d337291c08a1'::uuid),
 ('pte', null, 'Scores are shared through Pearson; no code is listed.', 'd219d428-37cc-5048-b8cf-de6230ffb42e'::uuid)) v;
insert into cost_aid (institution_id, year, tuition_usd, tuition_intl_usd, required_fees_usd, room_board_usd, intl_aid_policy, meets_full_need, merit_scholarships, merit_separate_app, notes, source_id) values
 ('00a10265-a322-5e53-bfed-25afa70d758d', '2026-2027', 41874, 41874, 2116, 18938, 'merit_only', false, true, false, 'Annual undergraduate tuition (24-36 credits) $41,874; full-time university fee $2,116; standard double room $12,384 plus Residential Meal Plan One $6,554 (room_board is their sum); student health insurance charge $2,158 and $150 dining dollars are listed separately. Same rates apply to international students. College Navigator lists books at $2,000 (2024-25).; LIU FAQ: international students are eligible for merit-based scholarships and are automatically reviewed by the admissions committee at admission. No award amounts are published for international freshmen; scholarships apply to tuition only and are renewable subject to a GPA minimum. Federal and state aid are not available to international students; whether any institutional need-based aid exists for them is not stated.', '1ed9d79a-31b5-51d6-bce6-5df43ea3c7ba');
