insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, pct_submit_sat, pct_submit_act, notes, source_id, source_note) values
 ('bab9c38a-480c-5349-80a7-fc1a10245b68', '2023-2024', 6078, 5154, 793, 31, 3, 'Baseline from IPEDS (fall 2023 entering class, ADM2023); Longwood''s Common Data Set page lists files only through 2019-2020, so no recent CDS was read. College Navigator also shows fall 2024: 5,391 applicants, 90% admitted (exact admit count not given), SAT EBRW 530/580/630 and Math 500/540/580 for 205 submitters (25%). Longwood''s admission-requirements page prints ''accepted students at a glance'' (undated): mid-range GPA 3.35-4.02, SAT 1040-1230, ACT 21-27. ACT percentiles are not listed because only 23 enrolled students (3%) submitted ACT in fall 2023. International applicant and admit counts, GPA distribution and SAT total are not available from IPEDS.', '784dfa57-b322-5a92-ad85-0e482ee08610', 'admissions_site');
insert into test_score_percentiles (institution_id, cds_year, source_id, test, p25, p50, p75)
select 'bab9c38a-480c-5349-80a7-fc1a10245b68'::uuid, '2023-2024', '75209217-0b1f-5b1c-bcd2-f2d23271b849'::uuid, v.* from (values
 ('SAT_ERW', 520, 570, 620),
 ('SAT_MATH', 500, 540, 570)) v;
insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('bab9c38a-480c-5349-80a7-fc1a10245b68', '2026-27', 'optional', 'SAT/ACT are not required for fall 2027 admission to majors other than nursing, and not submitting is not penalized; scores can be sent after applying and official scores are required before enrolling. Nursing applicants must submit SAT, ACT or TEAS. The international page says SAT scores are reviewed if submitted and may qualify an applicant for larger scholarship awards.', 'facde757-d543-571e-af38-3f371d886838');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('bab9c38a-480c-5349-80a7-fc1a10245b68', '2026-27', array['common_app']::text[], 50, 'International first-year file: Common App international application with $50 fee, certified official transcripts and leaving-certificate scores with certified English translations, English proficiency proof, Undergraduate Financial Certification Form with bank statements, passport information page. Applications are complete when the fee, official transcripts and required test scores arrive. The domestic page says a personal statement and recommendations are strongly encouraged (not required). The international page lists no separate international deadline; see the high-school deadlines.', 'f7c522a9-c55a-576c-aca9-37177808d4f3');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('cd77b563-24b6-5c63-9736-a77fc4b45a94', 'bab9c38a-480c-5349-80a7-fc1a10245b68', '2026-27', 'application', 'ED', 'Early Decision, nursing applicants only (fall 2027 entry)', '2026-11-01', 'Binding. Candidates are notified by mid-December. Nursing applicants not admitted can be considered in Early Action. Published on the high school students page; the international page lists no separate date.', 'a2e3994f-7d10-5d7e-9230-5a42b3e85b6b'),
 ('7fb0d28d-b839-523f-a7d7-b3d1d30e3709', 'bab9c38a-480c-5349-80a7-fc1a10245b68', '2026-27', 'application', 'EA', 'Early Action (fall 2027 entry); also the final deadline for nursing and the Honors portfolio', '2026-12-01', 'Non-binding; most decisions by mid-December (nursing and transfer decisions differ). Early Action applicants get the highest merit-scholarship consideration (guaranteed award by GPA for those applying by Dec 1, 2026). Published on the high school students page; the international page lists no separate date.', 'a2e3994f-7d10-5d7e-9230-5a42b3e85b6b'),
 ('ad065317-302e-519f-b759-2f4e1b91d897', 'bab9c38a-480c-5349-80a7-fc1a10245b68', '2026-27', 'application', 'RD', 'Regular Admission (fall 2027 entry)', '2027-02-01', 'Applications after Feb 1 are reviewed on a rolling basis. Nursing applicants cannot apply under Regular Admission. Applications without transcripts close May 1. Published on the high school students page; the international page lists no separate date.', 'a2e3994f-7d10-5d7e-9230-5a42b3e85b6b');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('bab9c38a-480c-5349-80a7-fc1a10245b68', 'required_nonnative', 'Required of non-native English speakers through TOEFL, IELTS, Duolingo or Cambridge. Waived for applicants with an International Baccalaureate Diploma. Native English speakers are contacted by International Admissions about other test scores. Non-native transfer students with 2+ years at a U.S. university need no English scores. Applicants below the minimums can enter through the English Language Bridge Program (EBP), a first-semester academic-transition program whose credits count toward the degree.', 'f7c522a9-c55a-576c-aca9-37177808d4f3');
insert into english_requirements (institution_id, source_id, test_key, status, min_total, notes)
select 'bab9c38a-480c-5349-80a7-fc1a10245b68'::uuid, 'f7c522a9-c55a-576c-aca9-37177808d4f3'::uuid, v.* from (values
 ('TOEFL_IBT', 'required_option', 79, 'Page prints ''minimum score of 79/80''. English Language Bridge Program: TOEFL 60-79. The 1-6 scale minimum is not published.'),
 ('IELTS', 'required_option', 6.5, 'English Language Bridge Program: IELTS 5.0-6.5.'),
 ('DUOLINGO', 'required_option', 115, 'English Language Bridge Program: Duolingo 95-114.'),
 ('CAMBRIDGE', 'accepted', null, 'Page says ''Cambridge English score of C1'' with no numeric score. English Language Bridge Program: Cambridge B1 or B2.')) v;
insert into score_codes (institution_id, test_key, notes, source_id)
select 'bab9c38a-480c-5349-80a7-fc1a10245b68'::uuid, v.* from (values
 ('sat', 'Longwood''s admissions pages print no SAT code; look it up in the College Board code search.', 'facde757-d543-571e-af38-3f371d886838'::uuid),
 ('act', 'Longwood''s admissions pages print no ACT code; look it up at act.org.', 'facde757-d543-571e-af38-3f371d886838'::uuid),
 ('toefl', 'The international page prints no TOEFL code; select Longwood University in the ETS list.', 'f7c522a9-c55a-576c-aca9-37177808d4f3'::uuid),
 ('ielts', 'No institution code is listed.', 'f7c522a9-c55a-576c-aca9-37177808d4f3'::uuid),
 ('duolingo', 'No institution code is listed.', 'f7c522a9-c55a-576c-aca9-37177808d4f3'::uuid)) v;
insert into cost_aid (institution_id, year, tuition_intl_usd, room_board_usd, merit_scholarships, merit_separate_app, notes, source_id) values
 ('bab9c38a-480c-5349-80a7-fc1a10245b68', '2026-2027', 29180, 14570, true, false, 'International page and the 2026-2027 Financial Certification Form: tuition and fees combined $29,180, room $9,300 plus meal plan $5,270 = $14,570, subtotal $43,750 (the minimum annual support to show; excludes books, transportation, health insurance). Longwood''s cost page estimates $22,140 per semester for out-of-state students including room and the default meal plan (banded 12-18 credits).; The international page lists merit scholarships for freshman applicants with a 3.0+ GPA (priority for applying by Dec 1), renewable for four years with a 3.0 GPA and 30 credits a year, plus Cormier Honors College scholarships (two full rides) and NCAA Division I athletic scholarships. Fall 2027 amounts on the financial aid page, Early Action (by Dec 1, 2026) / later: Presidential (4.0+) up to $7,000 / $6,000; Provost (3.75-3.99) up to $6,000 / $5,000; Dean''s (3.50-3.74) up to $5,000 / $4,000; Rotunda (3.25-3.49) up to $3,000 / $2,000; Lancer Distinction (3.0-3.24) up to $2,000 / $1,000 per year. That page does not name international students, but the international page links to the same awards. Need-based aid for international students is not described.', '21c9e7dd-ce65-536c-9baf-7fc32895cf51');
