insert into major_admissions (id, institution_id, program, category_key, admit_model, capped, notes) values
 ('239b35a8-b789-5a7c-8db7-8a7517c0604a', 'bab9c38a-480c-5349-80a7-fc1a10245b68', 'Nursing', 'nursing', 'direct_major', false, 'Applicants apply to nursing as first-year students through Early Decision (Nov 1, binding) or Early Action (Dec 1, final deadline); not available under Regular Admission. SAT, ACT or TEAS scores are required. Seat counts are not published on the pages read.');

