insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('9a7251f1-26c2-54b2-a6be-c1df5b422279', '2026-27', 'optional', 'SAT/ACT scores are optional for admission and many automatic scholarships. Some programs set score-based criteria (for example Engineering: GPA 3.0 with SAT 1200 or ACT 25, plus a math sub-score) and applicants to Engineering, Nursing or Business who meet the GPA but have no qualifying score can show readiness through the Accuplacer.', '5235eab1-3baa-5527-a91b-20fe8e339b61');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('9a7251f1-26c2-54b2-a6be-c1df5b422279', '2026-27', array['common_app','own']::text[], 30, 'UofL''s Take Flight application or the Common App; $30 non-refundable fee; international applicants must specify an intended major. No essays or recommendation letters. Non-U.S. transcripts need a notarized, ATA-certified translation; send to adetran@louisville.edu.', '02605501-105b-519c-b8fd-1eb79e445e62');
insert into deadlines (id, institution_id, cycle, kind, label, due_date, notes, source_id) values
 ('81bd071d-c720-5825-b98c-d58c7f46b3cd', '9a7251f1-26c2-54b2-a6be-c1df5b422279', '2026-27', 'priority', 'Priority application deadline, fall 2027', '2027-02-15', 'Applications after the priority date are reviewed as space allows. The international requirements page gives no separate international deadline.', '5235eab1-3baa-5527-a91b-20fe8e339b61');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('9a7251f1-26c2-54b2-a6be-c1df5b422279', 'required_nonnative', 'Alternatives to a test: two consecutive years of full-time high school in the U.S. or where English is the primary language of instruction with a C or better in English; or the same at university level (C or better in English 101/102). SAT EBRW 490+, ACT English 18+, AP English Language 4+ or IB English Language and Literature 5+ also count. No intensive-English conditional-admission pathway was found on UofL''s pages.', '02605501-105b-519c-b8fd-1eb79e445e62');
