insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, intl_applicants, intl_admits, in_state_applicants, in_state_admits, out_state_applicants, out_state_admits, waitlist_offered, waitlist_accepted, waitlist_admitted, pct_submit_sat, pct_submit_act, gpa_avg, pct_reporting_gpa, gpa_distribution, notes, source_id) values
 ('9e6800a6-39f0-573a-ab14-465b2dcc7b52', '2025-2026', 43954, 33009, 2605, 7973, 3769, 20089, 15546, 15530, 13530, 0, 0, 0, 39, 15, 3.74, 100, '{"4.0": 42.6, "3.75-3.99": 19.7, "3.50-3.74": 16.3, "3.25-3.49": 11.5, "3.00-3.24": 6.6, "2.50-2.99": 3.3}'::jsonb, 'Fall 2025 entering class (CDS C1; the PDF page headers still say 2024-2025 but the data are for Fall 2025 and the file is the 2025-26 CDS on the OIRA page). Residency split: in-state 20,089 / out-of-state 15,530 / international 7,973 / unknown 362 applicants (international admit rate about 47%). No early decision or early action (C21/C22) and no waitlist. Test-optional: only 39% (SAT) and 15% (ACT) of enrollees submitted scores, so the 25th-75th percentiles describe submitters, who are a stronger group than the whole class. The SAT section percentiles in C9 do not add up to the composite, so only the composite and ACT composite are stored. Undergraduate enrollment 12,640 is B1 total undergraduates; international 275 is the B2 nonresident total-undergraduates column. C7 factor boxes and C16 notification were not reliably readable, so factors are omitted.', 'dc2a0c17-faec-5bbb-9238-1a6c88a03095');
insert into test_score_percentiles (institution_id, cds_year, source_id, test, p25, p75)
select '9e6800a6-39f0-573a-ab14-465b2dcc7b52'::uuid, '2025-2026', 'dc2a0c17-faec-5bbb-9238-1a6c88a03095'::uuid, v.* from (values
 ('SAT_TOTAL', 1220, 1390),
 ('ACT_COMPOSITE', 26, 31)) v;
insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('9e6800a6-39f0-573a-ab14-465b2dcc7b52', '2026-27', 'optional', 'Loyola is test-optional; applicants decide whether to include ACT/SAT scores. Loyola superscores. If admitted, official scores must reach Loyola by May 1. International applicants may also submit the SAT or ACT as proof of English proficiency.', '87c2c332-225e-57b6-9acc-5282cd691be8');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('9e6800a6-39f0-573a-ab14-465b2dcc7b52', '2026-27', array['common_app','own']::text[], 0, 'No application fee. Common App or Loyola''s own application. Send official transcripts from every secondary school attended (translated into English if needed). A letter of recommendation from a teacher or counselor is listed as a step but is not stated to be mandatory; resume and essay/personal statement are optional. I-20 documents (passport copy, proof of funds, affidavit of support) are requested only after admission.', '87c2c332-225e-57b6-9acc-5282cd691be8');
insert into deadlines (id, institution_id, cycle, kind, label, due_date, notes, source_id) values
 ('0ea7ba42-bf2a-5ae1-a37a-17e4322b3674', '9e6800a6-39f0-573a-ab14-465b2dcc7b52', '2026-27', 'priority', 'Priority application deadline, fall 2027 entry', '2026-12-01', 'Loyola keeps admitting after Dec. 1 as long as space is available; the page prints no year, taken as fall 2027. No early decision or early action. For merit scholarship consideration the Financial Aid Office asks for a completed application by Dec. 1 so the student can be admitted by Feb. 1.', '87c2c332-225e-57b6-9acc-5282cd691be8'),
 ('d83eacda-8727-5740-90f8-38b2fa91a01d', '9e6800a6-39f0-573a-ab14-465b2dcc7b52', '2026-27', 'priority', 'Priority application deadline, spring 2027 entry', '2026-11-01', 'Spring start; enrollment deposit due Jan. 1. The page prints no year, taken as spring 2027.', '87c2c332-225e-57b6-9acc-5282cd691be8'),
 ('1a56c1b8-8845-5c16-b259-92fb5b3fcded', '9e6800a6-39f0-573a-ab14-465b2dcc7b52', '2026-27', 'deposit', 'Enrollment deposit deadline (fall 2027)', '2027-05-01', 'Deposits continue to be accepted after May 1 if space is available.', '87c2c332-225e-57b6-9acc-5282cd691be8');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('9e6800a6-39f0-573a-ab14-465b2dcc7b52', 'required_all_international', 'Loyola does not waive English proficiency based on country of origin or medium of instruction. Students taking AP or IB classes can have their transcripts reviewed for a waiver, and the SAT or ACT may be submitted instead as proof of English proficiency (scores sent directly by the testing agency). The page says the application ''may require'' official TOEFL, IELTS, PTE or Duolingo scores. No conditional admission or ESL pathway program was found on the page (a Rome Start option lets international students begin at Loyola''s Rome campus).', '87c2c332-225e-57b6-9acc-5282cd691be8');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
