insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('6a4ed774-1391-5028-986c-4e24aa41b776', '2026-27', 'optional', 'Test-optional: SAT and ACT scores are not required for admission, and applicants choose on the application whether scores are used for admission and merit scholarships (if they opt out, scores are not used even if already on file). Louisiana TOPS applicants and recruited NAIA athletes are the exceptions. International applicants must still show English proficiency, which SAT/ACT, TOEFL, IELTS or Duolingo can satisfy.', 'e7662a37-bd14-52f8-b139-e40742775449');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('6a4ed774-1391-5028-986c-4e24aa41b776', '2026-27', array['common_app','own']::text[], 0, 'Apply with the free Loyola application or the Common App; Loyola reviews both equally. CDS C13 reports no application fee. A high school transcript is required (non-English transcripts need an official course-by-course evaluation; SPANTRAN recommended). The international page says the affidavit of financial support and a passport copy are needed after admission/enrollment for I-20 processing, not to complete the application. Essay and recommendations are rated ''not considered'' in CDS C7; audition or portfolio material is required for music, theatre, design, visual arts, music industry and digital film applicants. Deadlines are the same for domestic and international students.', '54396396-9fa5-506e-8d16-89e8ef88107e');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notification_date, notes, source_id) values
 ('8a477130-ecfd-5dd4-bb21-7408658e4466', '6a4ed774-1391-5028-986c-4e24aa41b776', '2026-27', 'application', 'EA', 'Early Action (fall 2027 entry)', '2026-11-15', '2026-12-01', 'Page prints ''November 15'' without a year; CDS (Fall 2027 cycle) confirms a Nov. 15 priority/early action closing date and Dec. 1 notification. Test scores from October and November are considered.', '631f9a06-e3b8-5197-8327-e470ea7a3e7f'),
 ('b6cc3498-52ba-52fd-bc6b-2cf0844b951a', '6a4ed774-1391-5028-986c-4e24aa41b776', '2026-27', 'priority', 'RD', 'Priority admission (fall 2027 entry)', '2027-02-15', null, 'Page: priority applicants are considered for all scholarship and financial aid packages. Year not printed; treated as fall 2027.', '631f9a06-e3b8-5197-8327-e470ea7a3e7f'),
 ('49d3f4be-9247-5524-8345-ccccc42c5afa', '6a4ed774-1391-5028-986c-4e24aa41b776', '2026-27', 'application', 'RD', 'Regular admission (fall 2027 entry)', '2027-04-15', null, 'Applications after this date are considered ''as space and funds are available.'' Year not printed; treated as fall 2027.', '631f9a06-e3b8-5197-8327-e470ea7a3e7f'),
 ('7cf35637-a5ce-5177-9cdf-8e98862e83f8', '6a4ed774-1391-5028-986c-4e24aa41b776', '2026-27', 'scholarship', null, 'Ignatian Scholarship application', '2026-12-01', null, 'Full tuition and fees for four years; minimum 3.75 GPA and 30 ACT or 1360 SAT. The scholarships page does not say whether international students may apply.', '427395c6-d56d-5d52-86af-a33deebc9595'),
 ('aa1896aa-8d4f-5b77-8b0b-bdafd7d9b523', '6a4ed774-1391-5028-986c-4e24aa41b776', '2026-27', 'deposit', null, 'Enrollment deposit', '2027-05-01', null, 'Admitted students confirm their place by May 1 (CDS C17: reply by May 1).', '631f9a06-e3b8-5197-8327-e470ea7a3e7f');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('6a4ed774-1391-5028-986c-4e24aa41b776', 'required_nonnative', 'The requirement can be waived with an SAT Reading and Writing score of 560 or above, or an A in AP or IB English; instruction at a U.S. accredited high school also satisfies it (test-optional page). Applicants just below the degree-seeking minimums (TOEFL iBT 61-78, IELTS 5.5-6.0, Duolingo 100-114, CEFR B2) can be conditionally admitted to a Pilot Program that combines intensive English with credit-bearing classes; below TOEFL 61 / IELTS 5.5 / Duolingo 100 the route is conditional admission to the Loyola Intensive English Program (LIEP).', '54396396-9fa5-506e-8d16-89e8ef88107e');
insert into english_requirements (institution_id, test_key, status, min_total, notes, source_id)
select '6a4ed774-1391-5028-986c-4e24aa41b776'::uuid, v.* from (values
 ('TOEFL_IBT', 'required_option', 79, 'Degree-seeking minimum is 79 and above (0-120 scale). Pilot Program (conditional) 61-78. A 1-6 scale minimum is not published.', '54396396-9fa5-506e-8d16-89e8ef88107e'::uuid),
 ('IELTS', 'required_option', 6.5, 'Degree-seeking 6.5 and above. Pilot Program 5.5-6.0.', '54396396-9fa5-506e-8d16-89e8ef88107e'::uuid),
 ('DUOLINGO', 'required_option', 115, 'Degree-seeking 115 and above (CEFR C1/C2). Pilot Program 100-114.', '54396396-9fa5-506e-8d16-89e8ef88107e'::uuid),
 ('CAMBRIDGE', 'accepted', null, 'The undergraduate bulletin lists the Cambridge English exam as accepted; no minimum score is published. PTE is not mentioned on the pages reviewed.', 'f98c1ee3-7811-5350-959b-ddfc4f5b9766'::uuid)) v;
