insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, pct_submit_sat, pct_submit_act, notes, source_id, source_note) values
 ('31bfe15e-cf47-57e9-ba0b-bc8a83d96498', '2023-2024', 949, 785, 285, 5, 81, 'Baseline from IPEDS (fall 2024): 1,917 applicants and a 51% admit rate (31% of admitted students enrolled). The admits figure is derived (51% x 1,917, rounded), because IPEDS publishes only the percentage. Enrolled count, residency splits, international applicant/admit numbers and GPA are not published: no Common Data Set newer than 2016-17 is posted on lsus.edu. Undergraduate enrollment is the fall 2024 IPEDS figure; the student-faculty ratio of 30 to 1 is as printed by College Navigator (year not stated). SAT percentiles rest on only 15 submitting students; 247 submitted ACT. Applicant/admit/enrolled counts replaced with exact IPEDS ADM2023 (fall 2023) figures, because the newer source gives only a rounded admit rate.', '29085499-6827-53d7-a259-2343733c947b', 'admissions_site');
insert into test_score_percentiles (institution_id, cds_year, source_id, test, p25, p50, p75)
