 ('sat', '6355', 'LSUS SAT school code (freshman guidebook).', '979b96f1-bf2a-5428-90af-4741dded49cc'::uuid),
 ('act', '1593', 'LSUS ACT school code (freshman guidebook).', '979b96f1-bf2a-5428-90af-4741dded49cc'::uuid),
 ('toefl', null, 'No TOEFL institution code is listed on the pages checked; look it up in the ETS code search.', '132dd5db-6995-540c-aa20-e87df8dd3585'::uuid),
 ('ielts', null, 'No institution code is listed.', '132dd5db-6995-540c-aa20-e87df8dd3585'::uuid),
