insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, pct_submit_sat, pct_submit_act, notes, source_id, source_note) values
 ('ab57ea63-f51e-5e1b-a9f3-13e2ae779039', '2024-2025', 7285, 5352, 715, 16, 4, 'Baseline from IPEDS (fall 2024 entering class: 7,285 applied, 5,352 admitted, 715 enrolled; 109 enrolled students submitted SAT, 27 ACT). Lynn''s 2025-26 Common Data Set is on spiral.lynn.edu/common-data-set/11 but could not be downloaded (HTTP 403 to scripted requests), so international applicants/admits, GPA and SAT total are not filled in. SAT/ACT percentiles are for enrolled students who submitted scores (a small, self-selected group of a test-optional school); no SAT total percentile is published.', 'a5928fff-2c49-56f6-b409-151b72c2c07f', 'admissions_site');
