insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('ab57ea63-f51e-5e1b-a9f3-13e2ae779039', '2026-27', 'optional', 'SAT, ACT and CLT scores are not required; international applicants may choose whether to submit them. Only the SAT composite is used. Athletes still need NCAA Eligibility Center scores. Lynn''s published admit rate for fall 2024 was 73%.', '01054f36-98a7-5678-bc14-b25a06e34f17');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('ab57ea63-f51e-5e1b-a9f3-13e2ae779039', '2026-27', array['common_app','own']::text[], 0, 'No application fee (Lynn, Oct 2026). Required: application, official high school transcript in English or with certified translation (NACES evaluation if from outside the US system) and proof of English proficiency. Personal statement, counselor/teacher recommendation and activity resume are listed as supporting documents (not required). Interviews are not required; BFA Drama and the Conservatory of Music require an audition.', '52da13a5-8ce0-5366-960c-ac03856f14de');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notification_date, notes, source_id) values
 ('0650ab40-573a-5dca-bcd0-24529b29db4d', 'ab57ea63-f51e-5e1b-a9f3-13e2ae779039', '2026-27', 'application', 'ED', 'Early Decision (binding) - fall 2027 entry', '2026-11-01', '2026-12-01', 'Complete application by Nov 1, documents by Nov 8, enrollment deposit by Jan 15. Dates print without a year; treated as fall 2027 entry.', '52da13a5-8ce0-5366-960c-ac03856f14de'),
 ('cb66a9f5-1634-5355-a706-3b344dfd0bdb', 'ab57ea63-f51e-5e1b-a9f3-13e2ae779039', '2026-27', 'application', 'EA', 'Early Action I (non-binding) - fall 2027 entry', '2026-11-15', '2026-12-15', 'Documents due Dec 1. Professional pilot applicants use Nov 15 (documents Nov 22, decision Dec 1).', '52da13a5-8ce0-5366-960c-ac03856f14de'),
 ('d170e1ca-1885-5a5d-9f1d-9f8e797c20a2', 'ab57ea63-f51e-5e1b-a9f3-13e2ae779039', '2026-27', 'application', 'EA', 'Early Action II (non-binding) - fall 2027 entry', '2027-01-15', '2027-02-15', 'Documents due Feb 1.', '52da13a5-8ce0-5366-960c-ac03856f14de'),
 ('452ab49d-0f9c-55d7-920e-1aec515826f3', 'ab57ea63-f51e-5e1b-a9f3-13e2ae779039', '2026-27', 'application', 'RD', 'Regular Decision - fall 2027 entry', '2027-03-01', '2027-03-15', 'Applications after March 1 are considered as space allows (rolling). The page lists these dates for all first-year applicants; there is no separate international date.', '52da13a5-8ce0-5366-960c-ac03856f14de'),
 ('c08813b6-3eec-59dc-a651-a2e1412606dc', 'ab57ea63-f51e-5e1b-a9f3-13e2ae779039', '2026-27', 'scholarship', null, 'Admission offer needed by this date to be invited to apply for the Presidential Scholarship', '2027-02-01', null, 'Presidential applicants invited by Feb 15 submit a question response and video by Mar 15; recipients notified by Apr 1 (from the page''s 2025 version). One award a year goes to a student attending high school abroad.', '7192fea1-1124-5b9a-92b5-79585e57ad07'),
 ('e0e0db6c-e700-55aa-95d2-d38d8761c89e', 'ab57ea63-f51e-5e1b-a9f3-13e2ae779039', '2026-27', 'deposit', null, 'Enrollment deposit (EA and RD)', '2027-05-01', null, 'Residential deposit is $500 (commuter $300); fall deposits are non-refundable after May 1.', '52da13a5-8ce0-5366-960c-ac03856f14de');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('ab57ea63-f51e-5e1b-a9f3-13e2ae779039', 'required_nonnative', 'Required for most international applicants; official scores go with the application. Applicants from Australia, Bermuda, Canada, the Commonwealth Caribbean, New Zealand, Ireland, South Africa or the UK may be exempt, and waivers can be granted case by case for schools following a US or British-style curriculum. Scores below the minimums are reviewed individually. Versant 60+ is also accepted (not in the tracker''s test list). No conditional admission or ESL pathway to the degree was found; Lynn''s Institute for Achievement and Learning is a paid academic-support program, not an English course.', '0bf4ade4-4a5f-5c8a-bc51-400bd52b2390');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
select 'ab57ea63-f51e-5e1b-a9f3-13e2ae779039'::uuid, 'required_option', '0bf4ade4-4a5f-5c8a-bc51-400bd52b2390'::uuid, v.* from (values
 ('TOEFL_IBT', 71, 'Older pages (the Feb 2025 international page and the Oct 2026 test-optional FAQ) still quote 71 iBT.'),
 ('TOEFL_IBT_2026', 3.5, 'Current international page, ''as of January 2026'', per search-result text; I could not open the live page, so confirm with Lynn admission.'),
 ('IELTS', 6.0, null),
 ('DUOLINGO', 105, null),
 ('PTE', 50, 'PTE Academic.')) v;
