insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, notes, source_id, source_note) values
 ('a826f7b1-80e1-58d5-9336-23d374a467e1', '2023-2024', 755, 733, 132, 'Baseline from IPEDS / College Navigator (fall 2024): 757 applicants, 100% admitted (rounded; the admit count is not shown), 19% of admitted enrolled. The newest Common Data Set UMPI posts is 2021-2022 (umpi.edu/about/common-data-set), so it was not used; SAT/ACT percentiles, GPA, intl applicants/admits and C7 factors are not filled in. IPEDS lists SAT/ACT as not considered, while the admissions site says scores are optional and can qualify a student for the Merit Award. Enrollment (2,758 undergraduates) includes UMPI''s large online/competency-based YourPace program; admissions figures are not split out by on-campus vs online. Applicant/admit/enrolled counts replaced with exact IPEDS ADM2023 (fall 2023) figures, because the newer source gives only a rounded admit rate.', '9080c52f-9a47-5943-bf43-f0cdf4905aa2', 'admissions_site');
insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('a826f7b1-80e1-58d5-9336-23d374a467e1', '2026-27', 'optional', 'SAT/ACT scores are optional for first-year applicants; the First-Year page says they can be used to determine eligibility for the Merit Award (SAT 1100 or ACT 25 with a 3.3 GPA, or a 3.7 GPA). IPEDS (fall 2024) lists admission test scores as not considered.', '65aae9d8-9b47-56ac-8d35-970a41de43bb');
insert into application_requirements (institution_id, cycle, platforms, notes, source_id) values
 ('a826f7b1-80e1-58d5-9336-23d374a467e1', '2026-27', array['common_app','own']::text[], 'Apply with ApplyMaine or the Common App. The application fee is not stated on the pages read. First-year documents: official high school transcript (sent by a school representative); essay, recommendation letters and test scores are optional. International applicants must send a credential evaluation (NACES or AICE member, must include a GPA; WES or Incred recommended) unless exempt (high school transcripts from China and English-speaking provinces of Canada). UMPI also has a separate fully online, competency-based YourPace program for international students; this file describes the on-campus path.', 'b63c407c-1254-5fbc-81b5-b2ea2c6ad1d3');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, notes, source_id) values
 ('5c9a14bc-0f12-50b7-954a-935cf8035d84', 'a826f7b1-80e1-58d5-9336-23d374a467e1', '2026-27', 'application', 'ROLLING', 'Non-Canadian international freshman: application and I-20 document deadline (fall entry)', 'The page lists July 15 for fall 2026 (semester begins Sept. 3, 2026) and Nov. 15 for spring 2026 entry; no fall 2027 table is published yet, so no 2027 date is recorded. Expect a mid-July date and confirm with umpi-admissions@maine.edu; allow time for the I-20 and visa.', 'b63c407c-1254-5fbc-81b5-b2ea2c6ad1d3');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('a826f7b1-80e1-58d5-9336-23d374a467e1', 'required_nonnative', 'Proficiency is shown by: (1) being from a listed English-speaking country (e.g. Australia, Canada, Ghana, Ireland, Jamaica, Kenya, New Zealand, Nigeria, South Africa, United Kingdom; passport copy required); (2) a test score; or (3) instruction in English: a high school transcript stating English was the language of instruction for all subjects, or 2+ years of in-person, non-ESL study at an accredited college in the U.S., Canada or England. Scores must be from the last 2 years and sent by the testing agency.', 'b63c407c-1254-5fbc-81b5-b2ea2c6ad1d3');
insert into english_requirements (institution_id, source_id, test_key, status, min_total, notes)
select 'a826f7b1-80e1-58d5-9336-23d374a467e1'::uuid, 'b63c407c-1254-5fbc-81b5-b2ea2c6ad1d3'::uuid, v.* from (values
 ('TOEFL_IBT', 'required_option', 79, 'Minimum before Jan. 21, 2026; paper-based TOEFL 550. TOEFL Essentials needs 8.5.'),
 ('TOEFL_IBT_2026', 'required_option', 4, 'Page: minimum of 4 for TOEFL iBT as of Jan. 21, 2026. It does not name the 1-6 scale, but 4 is the post-January 2026 score (79 applied before).'),
 ('IELTS', 'required_option', 6.5, null),
 ('DUOLINGO', 'required_option', 105, null),
 ('PTE', 'required_option', 53, null),
 ('CAMBRIDGE', 'accepted', null, 'Cambridge C1 Advanced is accepted; no numeric minimum is printed.')) v;
