insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, notes, source_id, source_note) values
 ('7bbdecd0-1a14-5af7-857e-8f25967d4bee', '2023-2024', 13995, 13395, 1868, 'Baseline from IPEDS / College Navigator (fall 2024): 14,044 applicants, 97% admitted (rounded; the admit count is not shown). UMaine''s 2025-2026 Common Data Set exists (umaine.edu/oira/common-data-set) but is a Word file on a sign-in-protected SharePoint link, so it could not be read; SAT/ACT percentiles, GPA, intl applicants/admits and C7 factors are therefore not filled in. Applicant/admit/enrolled counts replaced with exact IPEDS ADM2023 (fall 2023) figures, because the newer source gives only a rounded admit rate.', 'a1f4d47d-a3cc-50d1-b892-65aac47d1a69', 'admissions_site');
insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('7bbdecd0-1a14-5af7-857e-8f25967d4bee', '2026-27', 'optional', 'UMaine is test optional for all programs; SAT/ACT are not required for admission or for merit scholarships.', '7f094355-360d-5e0f-9da1-2a2db71e94a7');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('7bbdecd0-1a14-5af7-857e-8f25967d4bee', '2026-27', array['common_app','own']::text[], 0, 'Apply with the Common App or the ApplyMaine application. The Apply and Application Information pages say it is free to apply; an older UMaine International Programs FAQ mentions a $50 international fee, which the current international page does not repeat. International applicants must submit a NACES-accredited transcript evaluation (exemptions: WASSCE, IB, US/Canadian schools, Cambridge International) unless waived. A school recommendation is part of a complete first-year application and an essay is recommended; Nursing applicants answer extra essay prompts.', '7f094355-360d-5e0f-9da1-2a2db71e94a7');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('7d86c43c-fba7-5920-9945-a3517268ab6c', '7bbdecd0-1a14-5af7-857e-8f25967d4bee', '2026-27', 'application', 'EA', 'First-year Early Action (fall 2027 entry)', '2026-12-01', 'Completing the application and all documents by Dec. 1 gives a guaranteed decision before year end and consideration for the maximum merit scholarships (an extra $3,000 Early Action Award on the international scholarship page).', '65dde65d-e60f-584b-afe2-05ba5f270fcb'),
 ('7214cb45-6e03-5570-8af1-cc9212474981', '7bbdecd0-1a14-5af7-857e-8f25967d4bee', '2026-27', 'application', 'RD', 'Regular application deadline (fall 2027 entry)', '2027-03-01', 'First-year and transfer; scholarships awarded as funds are available. Admission is rolling.', '65dde65d-e60f-584b-afe2-05ba5f270fcb'),
 ('7208fb12-9672-54f4-b9bb-b5eaa10ea6d4', '7bbdecd0-1a14-5af7-857e-8f25967d4bee', '2026-27', 'application', 'ROLLING', 'Final international deadline, living outside the US and Canada (fall 2027)', '2027-07-15', 'Later applications are reviewed on a space-available basis and most are moved to spring. The page prints no year; treated as 2027 for fall 2027 entry. International applicants residing in the US or Canada: final deadline Aug. 1, 2027.', '65dde65d-e60f-584b-afe2-05ba5f270fcb');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('7bbdecd0-1a14-5af7-857e-8f25967d4bee', 'required_nonnative', 'Waived for native English speakers or those educated in English (listed countries incl. Canada except Quebec, Ireland, Kenya, Nigeria, UK, Australia, NZ, Ghana); 2+ years studying in the US or Canada in a non-ESL track; passing a US college English Composition course with C or higher; South African NSC English Home Language; a school letter or transcript stating English is the language of instruction for all subjects; SAT Reading/Writing 550+ or ACT English 24+. CEFR level B2 completed is also accepted. Official scores must come from the testing agency. UMaine accepts TOEFL MyBest scores.', '65dde65d-e60f-584b-afe2-05ba5f270fcb');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
select '7bbdecd0-1a14-5af7-857e-8f25967d4bee'::uuid, 'required_option', '65dde65d-e60f-584b-afe2-05ba5f270fcb'::uuid, v.* from (values
 ('TOEFL_IBT', 79, 'Minimum for tests taken before January 2026. TOEFL Essentials (not a selectable test here) needs 8.5.'),
 ('TOEFL_IBT_2026', 4.5, 'Minimum for the new TOEFL (post-January 2026); the page does not name the 1-6 scale but 4.5 is listed as the post-January 2026 score.'),
 ('IELTS', 6.5, null),
 ('DUOLINGO', 110, 'Effective Spring 2024 semester.'),
 ('PTE', 53, null)) v;
