insert into cost_aid (institution_id, year, tuition_usd, tuition_out_of_state_usd, tuition_intl_usd, required_fees_usd, room_board_usd, books_usd, other_usd, total_coa_usd, intl_aid_policy, meets_full_need, merit_scholarships, notes, source_id) values
 ('7bbdecd0-1a14-5af7-857e-8f25967d4bee', '2026-2027', 13230, 38340, 38340, 1070, 14696, 1000, 2200, 57006, 'merit_only', false, true, 'UMaine cost of attendance 2026-27 (Orono): Maine/Canadian resident tuition $13,230; the Out-of-State and International rate is $38,340 (15 credits per semester); fees $1,070; double room plus Unlimited Flex meal plan $14,696; books $1,000; travel/misc $2,200; international students must have health insurance. Total COA $57,006 is for the out-of-state/international rate.; International scholarships (Fall 2027) are awarded at admission from high school GPA and rigor, minimum 2.5 GPA, no extra application: Flagship Leaders Commitment $9,000-$12,000 per year, an Early Action Award of up to $3,000 more, and a Flagship Match Commitment listed at $16,200 per year (the page gives no eligibility detail). The Global Flagship Match ($25,110) is only for international students from Maine high schools. Renewable up to 4 years if GPA and credit rules are met. Need-based federal aid (FAFSA) is not available to international students; no international need-based aid is described.', 'bc451b6f-a3e9-58c2-8ef6-8a4ba226cdca');
