insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, notes, source_id, source_note) values
 ('75ba06b5-d901-54f5-b510-1667170cbdd7', '2023-2024', 3883, 3702, 620, 'Baseline from IPEDS (fall 2023 entering class). No Common Data Set could be found on marian.edu. IPEDS reports no SAT/ACT figures and the 2026-27 catalog says the university is test blind, so no score ranges are recorded. International applicant/admit counts and GPA are not available.', '87f8cb14-ed37-534a-84c1-f494245f03b6', 'admissions_site');
insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('75ba06b5-d901-54f5-b510-1667170cbdd7', '2026-27', 'blind', '2026-27 catalog: ''Marian University is test blind. ACT and/or SAT scores are not used for admission or scholarship consideration.''', 'b858d4b8-c956-557a-b00a-fc90fcb166f4');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('75ba06b5-d901-54f5-b510-1667170cbdd7', '2026-27', array['own','common_app']::text[], 0, 'Free online application or the Common App. Admission is decided mainly on the weighted cumulative GPA over at least six semesters: 2.75 is required, and 2.0-2.74 needs a personal statement and two faculty letters reviewed by the committee. International applicants submit transcripts (unofficial copies for review), a financial verification form with a bank statement under six months old, and a $100 enrollment deposit before the I-20 is issued; nursing, engineering and education have additional program requirements.', 'b858d4b8-c956-557a-b00a-fc90fcb166f4');
insert into deadlines (id, institution_id, cycle, kind, label, due_date, notes, source_id) values
 ('fb7baab3-60de-5565-bf5c-56e2dc7e472c', '75ba06b5-d901-54f5-b510-1667170cbdd7', '2026-27', 'application', 'International application deadline (fall 2027 entry)', '2027-06-01', 'Admission decisions are made on a rolling basis. The page prints no year, so the fall date is taken as 2027. The catalog also asks international applicants to apply at least 60 days before the start term.', '12984587-c22d-51d5-8096-7c4f591aca37'),
 ('9dfced67-e1a1-514e-8902-57a4c3ad7a48', '75ba06b5-d901-54f5-b510-1667170cbdd7', '2026-27', 'other', 'International application materials deadline (fall)', '2027-06-08', null, '12984587-c22d-51d5-8096-7c4f591aca37'),
 ('6e63cfb5-afc3-58d3-ab99-6846f709f34e', '75ba06b5-d901-54f5-b510-1667170cbdd7', '2026-27', 'other', 'I-20 document deadline (fall)', '2027-06-15', 'Admitted students must submit official final documents, the $100 enrollment deposit, passport copy and proof of finances by this date.', '12984587-c22d-51d5-8096-7c4f591aca37');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('75ba06b5-d901-54f5-b510-1667170cbdd7', 'required_nonnative', 'Required if the first language is not English or high school was in a country where English is not an official or widely spoken language. May be waived with three years of upper secondary school in a listed English-speaking country, one year at a U.S. high school, or 24 credits from an accredited U.S. college. ELS Level 112 is also accepted. Nursing (BSN) has no exemptions: TOEFL iBT 83 with speaking 26, IELTS 6.5 with speaking 7, or Duolingo 120 before clinical courses.', '12984587-c22d-51d5-8096-7c4f591aca37');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
select '75ba06b5-d901-54f5-b510-1667170cbdd7'::uuid, 'required_option', '12984587-c22d-51d5-8096-7c4f591aca37'::uuid, v.* from (values
 ('TOEFL_IBT', 69, 'Tests taken before Jan 21, 2026. The 2026-27 catalog still lists 69 as the TOEFL iBT minimum.'),
 ('TOEFL_IBT_2026', 4.0, 'Tests taken on or after Jan 21, 2026 (''4.0 overall'').'),
 ('IELTS', 6.0, 'IELTS Academic.'),
 ('DUOLINGO', 95, null),
 ('PTE', 48, 'PTE Academic.')) v;
insert into cost_aid (institution_id, year, tuition_usd, room_board_usd, books_usd, meets_full_need, merit_scholarships, notes, source_id) values
 ('75ba06b5-d901-54f5-b510-1667170cbdd7', '2026-2027', 43400, 15040, 1200, false, true, 'Marian''s tuition page for 2026/2027: full-time (12-19 hours) $21,700 per semester ($43,400 per year), room and board $15,040, book estimate $1,200 per year. The page''s total on-campus cost is $58,440 (tuition plus room and board); the page does not state other expenses, so no total cost of attendance is recorded. Fall 2027 rates are not yet published.; The international admissions page says international students may qualify for academic, talent, athletic and faith-based scholarships. Marian Scholars awards of $8,000 to $18,000 per year are applied at admission for a cumulative GPA of 2.75 or higher (first-year scholarships page; it does not say whether international students are included). International need-based aid is not described.', '848819d3-6497-5b41-a2e8-fa811ee4fbc9');
