insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('05de2d4c-d45d-5bd4-b748-d03cc469394c', '2026-27', 'optional', 'Test scores are not required for admission. Admission needs a high school GPA of at least 2.00; a GPA of 3.00+ (or 2.00+ with ACT 19 / SAT 990) is admitted directly to the major''s college, and test-free applicants with a 2.00-2.99 GPA enter University College. International applicants may need official SAT/ACT for direct entry to some programs (e.g. Science, Engineering and Computer Sciences, Nursing). Scores are also used for scholarships.', '32822c22-add6-5de5-aaf5-4aa420eba427');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('05de2d4c-d45d-5bd4-b748-d03cc469394c', '2026-27', array['own']::text[], 0, 'International degree-seeking application fees are currently waived (CDS C13 also lists $0). Required: official secondary coursework sent from the issuing school (a NACES/AICE evaluation is an optional alternative), minimum 2.00 GPA (converted by the International Admissions Office), proof of English proficiency, and ACT/SAT for some majors. CDS C7 checkboxes were unreadable, so essay/recommendation policy is not recorded.', '6b93210c-8485-517d-b95e-527313567173');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('eb31d649-0f1c-51fd-beb1-cc99574e5e7a', '05de2d4c-d45d-5bd4-b748-d03cc469394c', '2026-27', 'application', 'ROLLING', 'International fall application deadline (fall 2027 entry)', '2027-06-15', 'All required documents must be received by the Fall June 15 date to guarantee consideration (Spring Oct. 15, Summer Mar. 15). The page prints no year; fall 2027 assumed. The CDS lists a domestic priority/closing date of 8/23 and rolling notification from Sept. 1.', '6b93210c-8485-517d-b95e-527313567173');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('05de2d4c-d45d-5bd4-b748-d03cc469394c', 'required_nonnative', 'Exempt: equivalent of a U.S. high school diploma or college degree from an approved English-speaking country (list on the page); one year of study at a U.S. high school with a C or higher in English; 24 undergraduate credits at a U.S.-accredited university; transfer credit equivalent to ENG 101 with C or better; completion of an approved ESL program; IGCSE/O-Level English First Language C or higher; IB English A (HL 4+, SL 5+). SAT EBRW 480 or ACT English/Reading 18 also satisfy the requirement. Marshall''s pages do not describe a conditional admission pathway.', '2c44e62a-9d1e-5593-b62f-e88c848578cd');
insert into english_requirements (institution_id, source_id, test_key, status, min_total, notes)
select '05de2d4c-d45d-5bd4-b748-d03cc469394c'::uuid, '2c44e62a-9d1e-5593-b62f-e88c848578cd'::uuid, v.* from (values
 ('TOEFL_IBT', 'required_option', 61, 'Exams taken before 2026-01-21; undergraduate minimum.'),
 ('TOEFL_IBT_2026', 'required_option', 4.0, 'Exams taken after 2026-01-20: the page lists ''4.0 or 72'' for undergraduates (4.5 or 86 for graduate). The 1-6 band is assumed from the 4.0/4.5 values.'),
 ('IELTS', 'required_option', 6.0, 'IELTS Academic overall.'),
 ('DUOLINGO', 'required_option', 90, null),
 ('PTE', 'required_option', 57, 'PTE Academic or PTE Express. The undergraduate catalog lists PTEA 50, which conflicts with the international admissions page (57); 57 is the international page value.'),
 ('CAMBRIDGE', 'accepted', 169, 'Cambridge English overall score.')) v;
