 ('act', null, 'No ACT code is printed on the international admissions pages; look it up at act.org.', '6b93210c-8485-517d-b95e-527313567173'::uuid),
 ('toefl', null, 'No TOEFL institution code is printed on Marshall''s English proficiency page.', '2c44e62a-9d1e-5593-b62f-e88c848578cd'::uuid),
 ('ielts', null, 'No institution code is listed.', '2c44e62a-9d1e-5593-b62f-e88c848578cd'::uuid),
