insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('c9742a05-7ff6-523b-a29a-cca274eb9e65', '2026-27', 'blind', 'The first-year requirements page says Marymount does not consider SAT/ACT scores for admission or scholarships unless the applicant is home-schooled or from an unaccredited or ungraded school (those must submit SAT, ACT or CLT; recommended 980 SAT or 18 ACT). The international page still lists SAT/ACT as ''optional'' items, and an SAT EBRW of 450 or ACT 18 can serve as English proficiency proof.', '27cd89dc-d3f5-5a86-8aa4-84291338cd32');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('c9742a05-7ff6-523b-a29a-cca274eb9e65', '2026-27', array['common_app','own']::text[], 0, 'CDS C13 (2023-24) reports no application fee; not re-confirmed on the current admissions pages. International first-year applicants submit official transcripts sent by the school (with certified English translations; national exam results where relevant), English proficiency proof and, optionally, recommendations and a personal statement. A resume is requested for any gaps in enrollment. Admission is rolling with no deadline; decisions take about 4-6 weeks.', 'eca88216-68f8-57ad-9b7c-7790a7f96e04');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('0f1c9a24-4daa-529a-8dbf-c2fd7e978c8a', 'c9742a05-7ff6-523b-a29a-cca274eb9e65', '2026-27', 'application', 'ROLLING', 'Rolling admission, no application deadline', null, 'Both the first-year and the international pages say there is no application deadline; applications are reviewed as they become complete.', '27cd89dc-d3f5-5a86-8aa4-84291338cd32'),
 ('9583203f-6e80-5edb-b3e5-d7bb07a5cedf', 'c9742a05-7ff6-523b-a29a-cca274eb9e65', '2026-27', 'scholarship', null, 'Priority consideration for first-year academic scholarships', '2027-03-01', 'The international financial advice page asks for the application and supporting documents by March 1 for priority consideration; no year printed, taken as 2027.', '48a20704-67d6-5ca6-9567-957dcc4be949');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('c9742a05-7ff6-523b-a29a-cca274eb9e65', 'required_nonnative', 'Waived after four consecutive years of college-preparatory English (not ESL or remedial) with C or better at a US high school (excluding Puerto Rico), 30 credits plus an English composition course (C or better) at a US regionally accredited institution, or a US associate, bachelor''s or master''s degree. Alternatives to the tests below: SAT EBRW 450 or ACT 18 on both Reading and Writing. Scores must be under two years old. Applicants who meet every other requirement but not English can apply for conditional admission through the selective Intensive English Language Program (IELP) and receive full admission once the requirement is met.', 'eca88216-68f8-57ad-9b7c-7790a7f96e04');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
select 'c9742a05-7ff6-523b-a29a-cca274eb9e65'::uuid, 'required_option', 'eca88216-68f8-57ad-9b7c-7790a7f96e04'::uuid, v.* from (values
 ('TOEFL_IBT', 79, 'Page words it as ''overall score within the range of 79''. The international transfer page adds a minimum of 4 for exams on or after 2026-01-21, but the first-year page does not.'),
 ('IELTS', 6.0, 'Academic.'),
 ('DUOLINGO', 100, 'Page words it as ''overall score within the range of 100-105''.'),
 ('PTE', 54, null)) v;
insert into cost_aid (institution_id, year, tuition_usd, required_fees_usd, intl_aid_policy, intl_avg_award_usd, merit_scholarships, merit_separate_app, notes, source_id) values
 ('c9742a05-7ff6-523b-a29a-cca274eb9e65', '2026-2027', 42678, 1400, 'merit_only', 18534, true, false, 'Full-time undergraduate (12-18 credits): tuition $21,339 per semester; fees per year: technology $550, student activity $250, health & well-being $200, facility $400. Excludes nursing fee ($2,300 per year), health insurance, and a one-time $450 new first-college freshman fee. Room and board is not on the tuition page (the 2023-24 CDS lists $17,000 for 2024-25). intl_avg_award_usd is the 2023-24 CDS H6 average institutional award to 133 degree-seeking nonresident undergraduates ($18,534).; The international page says eligible full-time first-year applicants are automatically offered the highest scholarship they qualify for with their admission application. The general first-year merit list (not specific to international students) runs from Presidential, up to $28,000 a year with on-campus housing and up to $20,000 for commuters, down to Achievement Award, up to $20,000 / $16,000; renewable for four years with a 2.0 GPA. Need-based aid for international students is not described, so it is left unconfirmed.', '1bc21364-6c3a-5ed9-aabd-694c93e1adaa');
