insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('0d331af3-1054-5cab-a587-0f4abeed11e0', '2026-27', 'optional', 'Maryville is test-optional for freshman and transfer admission: SAT/ACT scores may be sent for admission, scholarship or placement consideration but are not required. The international checklist also says official SAT or ACT scores are optional. (CDS C8A answers No to using SAT/ACT in admission decisions, which is stricter than the catalog wording; the catalog is followed here.) Automatic scholarships can be earned by GPA or by ACT/SAT. Test-optional does not apply to applicants from schools that give only narrative evaluations.', '90b261ab-9f50-5b38-8461-0b945c6c0041');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('0d331af3-1054-5cab-a587-0f4abeed11e0', '2026-27', array['common_app','own']::text[], 0, 'Freshman requirements: high school diploma with 22 units (4 English, 3 math, 3 science, 3 social science, 3 other) and at least a 2.5 GPA; below that, case-by-case with a possible personal statement. International applicants submit the application, passport, secondary transcripts (a third-party evaluation is no longer required but may be requested) and proof of English proficiency. CDS C13 reports no application fee. Some programs (nursing, design and visual art, direct-entry therapy programs and others) require a program-specific minimum GPA.', '90b261ab-9f50-5b38-8461-0b945c6c0041');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('33d4e6d1-2167-5fa1-8391-396677eb8e7c', '0d331af3-1054-5cab-a587-0f4abeed11e0', '2026-27', 'priority', 'ROLLING', 'Priority date and scholarship deadline (fall 2027 entry)', '2026-12-01', 'Maryville admits on a rolling basis (decisions from Sep. 1). CDS C14 gives a Dec. 1 priority date and the freshman scholarships page gives Dec. 1 for the automatic and competitive scholarships. The pages print no year, taken as the 2026-27 cycle (fall 2027 entry).', '3a62f179-6502-517f-9da2-c1da05b06104'),
 ('b2b98e9d-4cf7-5e98-b78e-9ed393703d72', '0d331af3-1054-5cab-a587-0f4abeed11e0', '2026-27', 'application', 'ROLLING', 'Recommended international application date (fall 2027 entry)', '2027-06-01', 'The International FAQ says there is no application deadline, but overseas applicants should apply by June 1 for fall (Nov. 1 for spring) to allow time for the I-20 and the U.S. embassy interview. No year is printed, taken as fall 2027. A $250 advance tuition payment and certified proof of finances (dated within 3 months) are needed for the I-20.', '9e5170d9-7124-5a9e-bd96-67de994b738a');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('0d331af3-1054-5cab-a587-0f4abeed11e0', 'required_nonnative', 'Required for applicants whose first language is not English. Other accepted proofs (non-health majors): ACT English/Writing 21+, SAT Writing 480+ (as printed in the catalog), ELS Level 112 completed with 2.5+, US college English Composition equivalent with C or better, A-levels (1 A in English or 3 Bs outside math), or medium-of-instruction proof from a country AACRAO lists as English-medium. Proof is not required where English is the primary and official language of all study (e.g. Canada except Quebec). Tests must be dated within 2 years of applying (Duolingo and health majors: 1 year). Maryville states it does not offer conditional admission.', '90b261ab-9f50-5b38-8461-0b945c6c0041');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, min_subscores, notes)
select '0d331af3-1054-5cab-a587-0f4abeed11e0'::uuid, 'required_option', '90b261ab-9f50-5b38-8461-0b945c6c0041'::uuid, v.* from (values
 ('TOEFL_IBT', 69, '{"each_section": 15}'::jsonb, 'Undergraduate non-health majors. Health-profession majors (e.g. nursing, therapy): 92 overall, no section below 23. The catalog lists only the 0-120 scale.'),
 ('IELTS', 6.0, '{"each_section": 5}'::jsonb, 'Non-health majors. Health-profession majors: 6.5 overall, no section below 6.'),
 ('DUOLINGO', 95, null, 'Non-health majors; health-profession majors need 115. Must be taken within 1 year of applying. An older 2018 Maryville PDF listed 40; the current catalog says 95.'),
 ('PTE', 47, null, 'PTE Academic; health-profession majors need 62.')) v;
insert into score_codes (institution_id, test_key, code, notes, source_id)
select '0d331af3-1054-5cab-a587-0f4abeed11e0'::uuid, v.* from (values
 ('sat', null, 'No SAT code was found on the admissions pages read; look up Maryville University in the College Board code search.', '8b1056ed-e9ab-5dd7-b67a-2a46287276cd'::uuid),
 ('act', null, 'No ACT code was found on the admissions pages read; look it up at act.org.', '8b1056ed-e9ab-5dd7-b67a-2a46287276cd'::uuid),
 ('toefl', '6399', 'Maryville''s TOEFL institutional code per the online-programs international admission page.', 'a2ae2fec-9892-568c-af2b-b31965012197'::uuid),
 ('ielts', null, 'No institution code is listed.', '90b261ab-9f50-5b38-8461-0b945c6c0041'::uuid),
 ('duolingo', null, 'No institution code is listed.', '90b261ab-9f50-5b38-8461-0b945c6c0041'::uuid),
 ('pte', null, 'No institution code is listed.', '90b261ab-9f50-5b38-8461-0b945c6c0041'::uuid)) v;
insert into cost_aid (institution_id, year, tuition_usd, tuition_intl_usd, required_fees_usd, room_board_usd, intl_aid_policy, intl_need_aid, intl_need_aid_awarded, intl_avg_award_usd, meets_full_need, merit_scholarships, merit_separate_app, notes, source_id) values
 ('0d331af3-1054-5cab-a587-0f4abeed11e0', '2026-2027', 25766, 25766, 2600, 15200, 'need_aware_limited', true, 145, 22996, false, true, false, 'CDS G1 (first-year, 2026-27): tuition $25,766, required fees $2,600, housing $11,100 plus food $4,100. Same tuition for international students. CDS H6: institutional need-based and non-need-based aid are both available to nonresidents; 145 nonresident undergraduates received it (average $22,996, total $3,334,367). CDS G5 lists $0 for books and supplies.; International undergraduates are eligible for scholarships: automatic academic awards are based on GPA and/or test score; competitive awards have a Dec. 1 deadline (fall entry only). The freshman scholarships page lists Saints $14,000/yr (GPA 3.5 or ACT 27/SAT 1290), Big Red $11,000/yr (GPA 3.0 or ACT 24/SAT 1180), Maryville Opportunity Award $9,000/yr (GPA 2.5 or ACT 22/SAT 1110), and Presidential (full tuition plus room and board) and Trustee (full tuition) at GPA 3.75 or ACT 27/SAT 1290. That page does not say these amounts apply to international students, so confirm with admissions. CDS H6: 145 nonresident undergraduates received institutional aid (average $22,996).', '703f7d44-b017-5c18-a51e-ab49680ce582');
