insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('b1147a76-a04c-5818-8e70-d465c7f5120e', '2026-27', 'optional', 'Test-optional: SAT/ACT are the applicant''s choice. The exception is an English proficiency test, which may be required depending on native language and the curriculum of the applicant''s high school.', '90ba23ac-8a94-5238-afb5-cb4f994b6b40');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, fee_waiver, notes, source_id) values
 ('b1147a76-a04c-5818-8e70-d465c7f5120e', '2026-27', array['common_app','own']::text[], 50, true, 'Apply with the Common App or the MCPHS Application. The Common App grid lists a $50 fee for U.S. and international applicants and accepts fee waivers; the fee for the MCPHS Application was not confirmed on mcphs.edu. Required: official high school transcript from the counselor or school (algebra 1 and 2 and geometry, biology and chemistry, 4 years of English, 1 year of history) and one letter of recommendation from a counselor or teacher (math or science preferred). The Common App grid lists the personal essay as required; no interview requirement was found.', '90ba23ac-8a94-5238-afb5-cb4f994b6b40');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('e682c5c2-fb1e-5494-ad6e-04cec49aa798', 'b1147a76-a04c-5818-8e70-d465c7f5120e', '2026-27', 'application', 'EA', 'Early Action Round I (priority filing date, fall 2027 entry)', '2026-11-01', 'International applications are accepted on a rolling basis with these priority filing dates; a decision is made only once the file is complete. Notification mid-December (first-year page). The pages print no year; taken as the 2026-27 cycle.', '8d829274-4b9d-5bde-810b-b6ac1f769667'),
 ('ebfc44f0-ea77-5237-829f-95e77b7e2ad9', 'b1147a76-a04c-5818-8e70-d465c7f5120e', '2026-27', 'application', 'EA', 'Early Action Round II (priority filing date)', '2026-12-01', 'Notification mid-January (first-year page).', '8d829274-4b9d-5bde-810b-b6ac1f769667'),
 ('f8bc9fa8-fb69-5378-a99a-7ce688d8f0d3', 'b1147a76-a04c-5818-8e70-d465c7f5120e', '2026-27', 'application', 'RD', 'Regular Decision (priority filing date)', '2027-02-01', 'Notification mid-February (first-year page). Admission is rolling and MCPHS promises a status update within three weeks of receiving all materials; no hard closing date is published.', '8d829274-4b9d-5bde-810b-b6ac1f769667'),
 ('99902600-a7fc-529f-855e-8941e4a1c619', 'b1147a76-a04c-5818-8e70-d465c7f5120e', '2026-27', 'deposit', null, 'Enrollment deposit', '2027-05-01', 'Confirm through the online deposit gateway by May 1; if admitted after May 1, within two weeks. The enrollment deposit is $500-$750 (tuition page).', '8d829274-4b9d-5bde-810b-b6ac1f769667');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('b1147a76-a04c-5818-8e70-d465c7f5120e', 'required_nonnative', 'Required if English is not the primary spoken language. May be waived individually for applicants with 4 years of US high school (excluding ESL), SAT Evidence-based Reading/Writing 480+ (ACT English 21 is also listed as proof), 4 years at a US-accredited high school abroad, IB or A2-level curriculum, or a US bachelor''s degree or higher. A completion certificate from an agreement ESL school can replace a test score. Three admission types: direct, conditional (for applicants who still need to take a test or more English study) and bridge. The Academic Bridge Program is a one-semester pathway for academically admissible students with about TOEFL 69-78 (or equivalent): two major courses plus three academic English courses, then progression to full-time degree study; entry in September or January for most programs; tuition equals a regular bachelor''s semester. Optional Early Start Program for new international undergraduates (about 10 days in August, Aug. 12-21 in 2026; $300 fee).', '8d829274-4b9d-5bde-810b-b6ac1f769667');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
select 'b1147a76-a04c-5818-8e70-d465c7f5120e'::uuid, 'required_option', '8d829274-4b9d-5bde-810b-b6ac1f769667'::uuid, v.* from (values
 ('TOEFL_IBT', 79, 'Bridge admission minimum 69. Also accepted: TOEFL ITP 550 (bridge 498), iTEP 4.0 (bridge 3.7), SAT ERW 480 or ACT English 21. The page gives no new 1-6 TOEFL score.'),
 ('IELTS', 6.5, 'Bridge admission minimum 5.5.'),
 ('DUOLINGO', 115, 'Bridge admission minimum 105.'),
 ('PTE', 58, 'PTE Academic; bridge admission minimum 50.')) v;
insert into score_codes (institution_id, source_id, test_key, code, notes)
select 'b1147a76-a04c-5818-8e70-d465c7f5120e'::uuid, '8d829274-4b9d-5bde-810b-b6ac1f769667'::uuid, v.* from (values
 ('sat', '3512', 'SAT school code as printed on the MCPHS international applicants page.'),
 ('act', '1860', 'ACT school code as printed on the MCPHS international applicants page.'),
 ('toefl', '3512', 'TOEFL school code as printed on the MCPHS international applicants page.'),
 ('ielts', null, 'No IELTS code is listed; scan the score report and email it to admissions@mcphs.edu.'),
 ('duolingo', null, 'No code is listed; request that Duolingo send the report to MCPHS.'),
 ('pte', null, 'No code is listed; request that Pearson send the report to MCPHS.')) v;
insert into cost_aid (institution_id, year, tuition_usd, room_board_usd, books_usd, other_usd, intl_aid_policy, intl_need_aid, meets_full_need, merit_scholarships, merit_separate_app, notes, source_id) values
 ('b1147a76-a04c-5818-8e70-d465c7f5120e', '2026-2027', 43110, 24930, 872, 3386, 'merit_only', false, false, true, false, 'Boston undergraduate bachelor-degree tuition is $43,110 per academic year for 2026-27 (3-year accelerated programs $62,480; PharmD preprofessional phase also $43,110, professional phase $51,900). Other mandatory fees: comprehensive service fee $705 billed fall and spring (6+ credits), orientation fee $175, graduation fee $390. room_board_usd is the school''s estimated Boston budget for housing $18,990 + food $5,940 (traditional year); other_usd is transportation $1,564 + miscellaneous $1,822. Residence hall rates vary (about $9,300-$9,750 per semester). The tuition page lists one rate; there is no separate international rate.; International page: all first-year applicants are reviewed for merit scholarships at acceptance with no separate application; no award amounts are published. Need-based federal aid is described only for eligible noncitizens (permanent residents, refugees, etc.), and the institutional need-based MCPHS Award is based on the FAFSA, so F-1 students appear not to qualify (inferred, not stated). Government-sponsored students must submit a financial guarantee letter. Annual health insurance is $4,364 (waivable); Flywire is used for international payments.', '0f8b6a89-267a-5203-a5e0-22c8fe74b09b');
