 ('ac2509f9-fcac-561d-b0a4-7c656214089c', '3c886100-e071-59e5-9544-980f29cf6bfc', 'ipeds', 'IPEDS admissions counts, fall 2024 (applicants, admits, enrollees) via Urban Institute Education Data Portal', 'https://educationdata.urban.org/api/v1/college-university/ipeds/admissions-enrollment/2024/?unitid=193016', '2024-2025', '2026-10-26'),
 ('aaa6d9c3-88ea-5a37-90bc-811d7cd58bc4', '3c886100-e071-59e5-9544-980f29cf6bfc', 'ipeds', 'IPEDS Fall Enrollment 2023 (EF2023A): undergraduate total and U.S. nonresident headcount', 'https://nces.ed.gov/collegenavigator/?id=193016', '2023-2024', '2026-10-26'),
 ('41d12334-8d24-546c-ad50-cc9bf79fc55d', '3c886100-e071-59e5-9544-980f29cf6bfc', 'admissions_site', 'Mercy University - International Admissions', 'https://www.mercy.edu/admissions/international', null, '2026-10-26'),
 ('d4eee11b-d8a7-509e-935a-aa31ac24286c', '3c886100-e071-59e5-9544-980f29cf6bfc', 'admissions_site', 'Mercy University - International Student Fast Facts (2026-2027 costs, scholarships)', 'https://mercy.edu/media/international-fact-sheet', null, '2026-10-26'),
 ('768e9e33-3c1f-5b7a-b617-501bbd309825', '3c886100-e071-59e5-9544-980f29cf6bfc', 'other', 'Mercy University Undergraduate Catalog - Undergraduate Admissions', 'https://ug.catalog.mercy.edu/admissions/undergraduate', null, '2026-10-26');
insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, notes, source_id, source_note) values
 ('3c886100-e071-59e5-9544-980f29cf6bfc', '2024-2025', 8642, 7418, 1064, 'Baseline from IPEDS (fall 2024 entering class): applicants, admits and enrollees from the Education Data Portal; enrollment and student-faculty ratio from College Navigator. No public Common Data Set was found. College Navigator shows no SAT/ACT percentiles or submission rates; GPA, residency splits and international applicant counts are not available. Undergraduate enrollment is the IPEDS fall 2024 headcount (6,774) across Mercy''s Westchester, Manhattan and Bronx sites.', 'c8961ab7-b4ca-5ac3-b8fc-b3c3426eaa97', 'admissions_site');
insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('3c886100-e071-59e5-9544-980f29cf6bfc', '2026-27', 'optional', 'SAT/ACT are not required for international undergraduates (required for traditional Nursing and some specialized programs and for NCAA Division II athletes); scores may be submitted for consideration. An SAT Critical Reading score of 500+ is one of the English-waiver routes.', '41d12334-8d24-546c-ad50-cc9bf79fc55d');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('3c886100-e071-59e5-9544-980f29cf6bfc', '2026-27', array['common_app','own']::text[], 40, 'Apply through the Common App or mercy.edu; $40 non-refundable fee (undergraduate catalog). Foreign transcripts need a course-by-course credential evaluation from a NACES/AICE member (waived for some programs). Music Production and Recording, Nursing, Pre-Occupational Therapy Assistant and Veterinary Technology need supplemental documents. International enrollment deposit $400 commuter / $500 resident, refundable if the F-1 visa is denied.', '768e9e33-3c1f-5b7a-b617-501bbd309825');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, notes, source_id) values
 ('299756ba-42d8-59df-90a6-7c8a66bb3a2d', '3c886100-e071-59e5-9544-980f29cf6bfc', '2026-27', 'application', 'ROLLING', 'Rolling admission (fall 2027 entry); no application deadline published', 'Mercy admits on a rolling basis. First-time F-1 applicants are asked to submit documents and the I-20 request at least 60 days before the term starts (30 days for U.S. F-1 transfers). No priority date is listed.', '41d12334-8d24-546c-ad50-cc9bf79fc55d');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('3c886100-e071-59e5-9544-980f29cf6bfc', 'required_nonnative', 'Waived for citizens of listed English-speaking countries (e.g. Canada, UK, Ireland, Australia, Singapore, South Africa), two years of regular English at a U.S. high school, an American GED, 12+ U.S. college credits (2.0 GPA), SAT Critical Reading 500+, AP English 3+, IB English B SL 4+, Cambridge English 160+, GTEC 1,140+, or B2 on the CEFR through an approved school. Conditional admission (bachelor''s only): applicants below the minimum can finish ESL at Oxford International - New York (Manhattan) or other approved schools (EF, ELS, EC) to B2 CEFR, and the TOEFL/IELTS requirement is then met; Mercy also runs a University Pathway Program with Oxford International.', '41d12334-8d24-546c-ad50-cc9bf79fc55d');
insert into english_requirements (institution_id, source_id, test_key, status, min_total, notes)
select '3c886100-e071-59e5-9544-980f29cf6bfc'::uuid, '41d12334-8d24-546c-ad50-cc9bf79fc55d'::uuid, v.* from (values
 ('TOEFL_IBT', 'required_option', 71, 'Undergraduate minimum for exams taken before 2026-01-21.'),
 ('TOEFL_IBT_2026', 'required_option', 4.0, 'Exams on or after 2026-01-21; the page lists ''4'' without naming the 1-6 scale.'),
 ('IELTS', 'required_option', 6.0, 'Undergraduate minimum.'),
 ('DUOLINGO', 'required_option', 105, 'Undergraduate minimum on the current page (an older Mercy page listed 100).'),
 ('PTE', 'required_option', 48, 'Undergraduate minimum.'),
 ('CAMBRIDGE', 'accepted', 160, 'Listed as a waiver, not a test option: B2 First, C1 Advanced or C2 Proficiency with 160+ waives the English requirement for undergraduates.')) v;
insert into score_codes (institution_id, test_key, notes, source_id)
