 ('sat', 'No SAT institution code was found on the pages read; use the College Board code search.', '768e9e33-3c1f-5b7a-b617-501bbd309825'::uuid),
 ('act', 'No ACT institution code was found on the pages read; use the ACT code search.', '768e9e33-3c1f-5b7a-b617-501bbd309825'::uuid),
 ('toefl', 'No TOEFL institution code was found on the pages read.', '41d12334-8d24-546c-ad50-cc9bf79fc55d'::uuid),
 ('ielts', 'No IELTS code is listed.', '41d12334-8d24-546c-ad50-cc9bf79fc55d'::uuid),
 ('duolingo', 'No Duolingo code is listed.', '41d12334-8d24-546c-ad50-cc9bf79fc55d'::uuid),
