insert into cost_aid (institution_id, year, tuition_usd, tuition_intl_usd, room_board_usd, intl_aid_policy, meets_full_need, merit_scholarships, merit_separate_app, notes, source_id) values
 ('3c886100-e071-59e5-9544-980f29cf6bfc', '2026-2027', 23550, 23550, 16130, 'merit_only', false, true, false, 'International fact sheet, cost of attendance per year (2026-2027): undergraduate tuition $23,550; room and board, double occupancy, $16,130 at the Westchester campus ($17,500 at the New York City campus). Required fees are not given.; Fact sheet: undergraduate academic merit scholarships of $4,000-$10,000 per year for freshman applicants ($3,000-$8,000 for transfers). The international page says all incoming full-time freshmen and transfers are automatically reviewed based on academic standing. International students are not eligible for federal or state aid; institutional need-based aid for them is not described.', 'd4eee11b-d8a7-509e-935a-aa31ac24286c');
