 ('88219731-5f09-52f9-aaff-9d2a3379687e', '3d3ac0d3-4281-50eb-95c9-655473f5fba3', 'ipeds', 'College Navigator - Mercyhurst University (enrollment, student-faculty ratio, admissions considerations)', 'https://nces.ed.gov/collegenavigator/?id=213987', '2024-2025', '2026-10-26'),
 ('5dfb5bb9-6422-5ff7-a8dc-31a22293ddfc', '3d3ac0d3-4281-50eb-95c9-655473f5fba3', 'ipeds', 'IPEDS Admissions survey, fall 2024 entering class (ADM2024), via the Urban Institute Education Data Portal', 'https://educationdata.urban.org/api/v1/college-university/ipeds/admissions-enrollment/2024/?unitid=213987', '2024-2025', '2026-10-26'),
 ('339315cb-8f53-5671-b47a-62538cec0a67', '3d3ac0d3-4281-50eb-95c9-655473f5fba3', 'ipeds', 'IPEDS Fall Enrollment 2023 (EF2023A): undergraduate total and U.S. nonresident headcount', 'https://nces.ed.gov/collegenavigator/?id=213987', '2023-2024', '2026-10-26'),
 ('19eda41d-02c7-5db7-ae44-8d4ddd451edb', '3d3ac0d3-4281-50eb-95c9-655473f5fba3', 'admissions_site', 'Mercyhurst University - International Admissions (undergraduate requirements, English minimums, scholarships)', 'https://www.mercyhurst.edu/admissions/international', null, '2026-10-26'),
 ('c113204b-6b2d-594c-9160-2b11067a83fe', '3d3ac0d3-4281-50eb-95c9-655473f5fba3', 'admissions_site', 'Mercyhurst University - Undergraduate Admissions (rolling admission, test-optional, application)', 'https://www.mercyhurst.edu/admissions-aid/undergraduate-admissions', null, '2026-10-26'),
 ('e2916f00-bea5-5256-8878-1ecea4df6e55', '3d3ac0d3-4281-50eb-95c9-655473f5fba3', 'financial_aid_site', 'Mercyhurst University - Financial Aid and Affordability (estimated tuition, fees, housing and meals 2026-2027)', 'https://www.mercyhurst.edu/admissions-aid/financial-aid-guide/financial-aid-and-affordability', null, '2026-10-26'),
