insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, notes, source_id, source_note) values
 ('3d3ac0d3-4281-50eb-95c9-655473f5fba3', '2024-2025', 3567, 2890, 588, 'Baseline: no Common Data Set found on mercyhurst.edu (2 searches, no CDS page). Exact counts are IPEDS ADM2024 (fall 2024 first-time degree-seeking: 3,567 applied, 2,890 admitted = 81%, 588 enrolled), matching College Navigator''s 3,567 applicants and 81% admitted. IPEDS does not split international applicants, so intl_applicants/intl_admits are not available. SAT/ACT scores are not reported to IPEDS (test-optional), so no percentiles.', '5dfb5bb9-6422-5ff7-a8dc-31a22293ddfc', 'admissions_site');
insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('3d3ac0d3-4281-50eb-95c9-655473f5fba3', '2026-27', 'optional', '''We do not require SAT or ACT scores, though students who believe their scores represent a positive component of their admissions portfolio are invited to submit them.'' An older counselor handout says scores are strongly recommended for merit-scholarship consideration; the current undergraduate page does not repeat that.', 'c113204b-6b2d-594c-9160-2b11067a83fe');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('3d3ac0d3-4281-50eb-95c9-655473f5fba3', '2026-27', array['common_app','coalition','own']::text[], 0, 'Mercyhurst''s own application is described as free (apply.mercyhurst.edu); the Common App and Coalition application are also accepted. International undergraduates submit the online application, official transcripts in English and proof of English proficiency, then upload a bank affidavit, certification of finances and passport photo page to the Admissions Portal. Transfer students from non-U.S. universities also need a certified credit evaluation (WES, ECE or SpanTran). Dance and Music applicants need an audition (older counselor handout). F-1 students are automatically billed for the university health insurance plan unless they have qualifying U.S. coverage.', '19eda41d-02c7-5db7-ae44-8d4ddd451edb');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, notes, source_id) values
 ('36a8e905-3006-5f5f-82a4-403d4eb0edf5', '3d3ac0d3-4281-50eb-95c9-655473f5fba3', '2026-27', 'application', 'ROLLING', 'Rolling admission (fall 2027 entry): no international undergraduate deadline published', 'The undergraduate page says admission is rolling and the sooner you apply the sooner you hear back; no date is printed. An older, undated counselor handout lists March 1 as a recommended application date, with offers released weekly from late September and a May 1 confirmation date; that is not repeated on the current site, so it is not recorded as a deadline. Allow time for the I-20 and visa.', 'c113204b-6b2d-594c-9160-2b11067a83fe');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('3d3ac0d3-4281-50eb-95c9-655473f5fba3', 'required_all_international', 'The international page says ''students with demonstrated English proficiency are invited to apply'' and lists the accepted tests; it names no waivers or exemptions. Contact the International Student Office (iso@mercyhurst.edu, 814-824-3059) about exemptions; no ESL or conditional-admission pathway is described.', '19eda41d-02c7-5db7-ae44-8d4ddd451edb');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, min_subscores, notes)
select '3d3ac0d3-4281-50eb-95c9-655473f5fba3'::uuid, 'required_option', '19eda41d-02c7-5db7-ae44-8d4ddd451edb'::uuid, v.* from (values
 ('TOEFL_IBT', 69, '{"each_section": 17.25}'::jsonb, 'Minimum 17.25 in each section. TOEFL Essentials is also accepted (8.0 overall and 8.0 each section) but is not a selectable test here. The page gives no value for the new 1-6 TOEFL scale.'),
 ('IELTS', 5.8, '{"each_section": 5.8}'::jsonb, 'Minimum 5.8 overall and 5.8 in each section.'),
 ('DUOLINGO', 100, '{"each_section": 100}'::jsonb, 'Minimum 100 overall and 100 in each section.'),
 ('PTE', 53, null, 'Page says ''53+''.')) v;
insert into score_codes (institution_id, source_id, test_key, notes)
select '3d3ac0d3-4281-50eb-95c9-655473f5fba3'::uuid, '19eda41d-02c7-5db7-ae44-8d4ddd451edb'::uuid, v.* from (values
 ('sat', 'No SAT code is printed on the admissions pages.'),
