insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, pct_submit_act, notes, source_id, source_note) values
 ('bc4c6efe-3fd4-5c60-b176-eac48d1783e9', '2023-2024', 542, 523, 158, 8, 'Baseline from IPEDS (fall 2023 entering class). No Common Data Set for Metro State was found online, so there is no international applicant split and no GPA data. Only 12 enrolled students (8%) reported ACT scores and none reported SAT, so the ACT range is very thin. College Navigator''s fall 2024 figures: 698 applicants, 99% admitted, 34% of admitted enrolled, ACT 16/19/21 (14 students). The first-year class is tiny because Metro State mainly serves transfer students (1,668 undergraduate transfer-ins in fall 2024). Undergrad 5,904 is fall 2024 (College Navigator).', '09768b07-5b0f-5f48-a0ac-d382c73d310d', 'admissions_site');
insert into test_score_percentiles (institution_id, cds_year, source_id, test, p25, p50, p75)
select 'bc4c6efe-3fd4-5c60-b176-eac48d1783e9'::uuid, '2023-2024', '09768b07-5b0f-5f48-a0ac-d382c73d310d'::uuid, v.* from (values
 ('ACT_COMPOSITE', 16, 19, 23),
 ('ACT_ENGLISH', 14, 20, 23),
 ('ACT_MATH', 16, 18, 24)) v;
insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('bc4c6efe-3fd4-5c60-b176-eac48d1783e9', '2026-27', 'optional', 'Admission is based on high school GPA and record; the IPEDS profile notes that test scores are ''considered only if an admissions decision cannot be made from secondary school grades and records''. The international pages do not ask for SAT/ACT (they only appear as optional ways to prove English: SAT reading 570+ or ACT English 24+).', '771116e1-79f4-5b35-929c-29dc1093bd39');
insert into application_requirements (institution_id, cycle, platforms, notes, source_id) values
 ('bc4c6efe-3fd4-5c60-b176-eac48d1783e9', '2026-27', array['own']::text[], 'Apply through Metro State''s online application. International first-year applicants need official secondary transcripts sent directly to International Student Services; foreign high school records must be evaluated by an accredited agency (e.g. ECE, WES) and must show a U.S. GPA equivalent of at least 3.0 (domestic first-year students are admitted automatically at 2.75+). The application fee is not stated on the pages read. Important limits: F-1 students can only enroll in on-campus programs and only a published list of programs is open to international students; the university has no campus housing (College Navigator) and may not serve students physically outside the U.S.', '771116e1-79f4-5b35-929c-29dc1093bd39');
insert into deadlines (id, institution_id, cycle, kind, label, due_date, notes, source_id) values
 ('6454190f-27b6-5dd8-b904-55a2dbd29a7a', 'bc4c6efe-3fd4-5c60-b176-eac48d1783e9', '2026-27', 'application', 'Final application date for out-of-country international students, fall 2027 entry', '2027-05-01', 'The page prints no year; treated as fall 2027. These are final submission dates, not the date by which materials should arrive; apply well ahead because transcript evaluation takes time. Spring entry: Sept. 1; summer: March 15. In-country transfer students: fall Aug. 1. The domestic first-year priority date is March 1 (not stated for international applicants).', '08926a69-12f9-5f32-a2d1-169026a7eb08');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('bc4c6efe-3fd4-5c60-b176-eac48d1783e9', 'required_nonnative', 'Alternatives to a test: Michigan English Test 56+ (colleges with an ESL program only), ELS level 112, SAT reading/writing 570+, ACT English 24+. Exemptions: 16 credits with 2.5 GPA at a U.S. college, graduation from a U.S. high school, graduation from an English-medium high school or university with 2.5 GPA (principal''s letter required), IGCSE/O-levels with C or above in English, math, a science, a social science and one more subject, a U.S. associate or bachelor''s degree, or citizenship of a listed English-speaking country.', '771116e1-79f4-5b35-929c-29dc1093bd39');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
select 'bc4c6efe-3fd4-5c60-b176-eac48d1783e9'::uuid, 'required_option', '771116e1-79f4-5b35-929c-29dc1093bd39'::uuid, v.* from (values
 ('TOEFL_IBT', 61, 'For exams taken before Jan. 21, 2026.'),
 ('TOEFL_IBT_2026', 3.5, 'For exams taken after Jan. 22, 2026 (page does not name the 1-6 scale).'),
 ('IELTS', 5.5, 'Academic test; score report can be uploaded.'),
 ('DUOLINGO', 95, 'Official report sent through the Metro State dashboard.'),
 ('PTE', 50, 'Only scores accessed via the Score Report Website are valid.')) v;
insert into cost_aid (institution_id, year, tuition_usd, tuition_intl_usd, room_board_usd, books_usd, other_usd, total_coa_usd, notes, source_id) values
 ('bc4c6efe-3fd4-5c60-b176-eac48d1783e9', '2026-2027', 10930, 10930, 15864, 1500, 9064, 37357, 'Metro State charges the same tuition rate to all students regardless of residency ($322.00 per undergraduate credit plus $42.30 per credit in standard course fees). The $10,930 is the university''s own estimate for 15 credits per term over two terms. Cost of attendance page (2026-27): tuition and fees $10,930, books $1,500, living allowance $15,864, personal expenses $5,246, transportation $3,818, total $37,357. Other = personal + transportation. There is no campus housing, so the living figure is an allowance only. Nursing BSN and natural sciences courses carry extra per-credit differentials.; No international-specific scholarship or aid was found on the international pages or the grants and scholarships page. The federal and state grants listed there are applied for through the FAFSA, and the Minnesota State Grant is for Minnesota residents.', 'cc73a159-546a-5db8-b494-290366abd6be');
insert into institution_tiers (institution_id, tier_code, category_key, rationale)
select 'bc4c6efe-3fd4-5c60-b176-eac48d1783e9'::uuid, 'D', v.* from (values
