insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('e8f004d9-e85d-584b-b179-48f5a2d4c46b', '2026-27', 'flexible', 'The testing page says UM requires SAT/ACT scores for Fall 2026 and the requirements page repeats that scores are required; self-reporting is allowed and official scores are needed only on enrollment. Applicants graduating from a high school or secondary school outside the United States may choose to apply with or without scores, as may Frost School of Music performance, BFA and School of Architecture applicants. The page does not state a separate rule for Fall 2027 entry.', '01f74aa6-35aa-584e-a7e5-3e74c6d36dbd');
insert into application_requirements (institution_id, cycle, platforms, supplemental_essays, interview, app_fee_usd, notes, source_id) values
 ('e8f004d9-e85d-584b-b179-48f5a2d4c46b', '2026-27', array['common_app']::text[], 0, 'optional_informational', 75, 'One letter of recommendation, from a counselor or a teacher. The requirements page says no supplemental essay is required. UM does not offer interviews, but international applicants may complete an optional InitialView interview (not rated or graded) by Jan 6. Frost School of Music Early Decision II and Regular Decision deadline is Dec 1 (earlier than below).', '29ef07f7-6f6d-551e-8873-4b06a14de564');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notification_date, notes, source_id) values
 ('4fe503a6-69e5-5e01-a754-1e1f4d2ad471', 'e8f004d9-e85d-584b-b179-48f5a2d4c46b', '2026-27', 'application', 'ED', 'Early Decision I (binding)', '2026-11-01', null, 'Decision mid-December (no exact date published). Final credentials deadline Nov 13. Early Decision Agreement form required.', 'af10984c-39cc-5bd6-bed6-7546b61ee8c7'),
 ('383f5818-cd7d-5721-a6cb-956474fabe68', 'e8f004d9-e85d-584b-b179-48f5a2d4c46b', '2026-27', 'application', 'EA', 'Early Action (non-binding)', '2026-11-01', null, 'Decision late January (no exact date published). Final credentials deadline Nov 20.', 'af10984c-39cc-5bd6-bed6-7546b61ee8c7'),
 ('661392f4-43f7-5333-8acd-adc048acb33a', 'e8f004d9-e85d-584b-b179-48f5a2d4c46b', '2026-27', 'application', 'ED2', 'Early Decision II (binding)', '2027-01-05', null, 'Decision late February (no exact date published). Final credentials deadline Jan 25. Frost School of Music: Dec 1.', 'af10984c-39cc-5bd6-bed6-7546b61ee8c7'),
 ('5da6e9fe-5327-5323-a434-760228360354', 'e8f004d9-e85d-584b-b179-48f5a2d4c46b', '2026-27', 'application', 'RD', 'Regular Decision', '2027-01-05', '2027-04-01', 'Final credentials deadline Feb 5. Frost School of Music: Dec 1.', 'af10984c-39cc-5bd6-bed6-7546b61ee8c7'),
 ('4db529d8-b00d-5c12-9a7c-4e29a1827803', 'e8f004d9-e85d-584b-b179-48f5a2d4c46b', '2026-27', 'financial_aid', 'ED', 'Financial aid deadline (ED I / EA)', '2026-11-15', null, 'CSS Profile required for all applicants seeking aid; FAFSA only for U.S. citizens and eligible non-citizens.', 'af10984c-39cc-5bd6-bed6-7546b61ee8c7'),
 ('77b59f4b-52ee-51e6-a1df-bdd0ca893b4d', 'e8f004d9-e85d-584b-b179-48f5a2d4c46b', '2026-27', 'financial_aid', 'RD', 'Financial aid deadline (ED II / RD)', '2027-01-05', null, 'CSS Profile required for all applicants seeking aid.', 'af10984c-39cc-5bd6-bed6-7546b61ee8c7');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('e8f004d9-e85d-584b-b179-48f5a2d4c46b', 'required_nonnative', 'Waived for e.g. an A or B in AP/IB HL English, 3+ years at a U.S. high school, 3+ years at a high school outside the U.S. taught in English, official SAT EBRW 650+ or ACT English 27+, or 24+ U.S. college credits including 6 in English Composition. Request via the Applicant Portal. Scores are valid for 2 years. TOEFL Essentials is not accepted.', '7f515ded-02e2-5e7a-a25f-9ec53f782374');
