insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, pct_submit_sat, pct_submit_act, notes, source_id, source_note) values
 ('e4cd761f-b3dc-5078-b573-b3b4ccd1c4a3', '2024-2025', 4346, 4332, 1319, 18, 7, 'Baseline from IPEDS fall 2024 (College Navigator percentages; exact counts from the NCES ADM2024 file via the Urban Institute Education Data Portal). Admission is effectively open (99.7% admitted). No Common Data Set was found on MGA''s institutional research pages, so international applicants/admits, GPA, SAT total and admission factors are not included. SAT/ACT percentiles cover enrolled first-time students who submitted scores (SAT 18%, ACT 7%).', '061c1848-5fb8-5f9f-89e0-ad1af736639f', 'admissions_site');
insert into test_score_percentiles (institution_id, cds_year, source_id, test, p25, p50, p75)
select 'e4cd761f-b3dc-5078-b573-b3b4ccd1c4a3'::uuid, '2024-2025', '061c1848-5fb8-5f9f-89e0-ad1af736639f'::uuid, v.* from (values
 ('SAT_ERW', 490, 550, 610),
 ('SAT_MATH', 460, 530, 580),
