insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('749d1c5a-40b4-5875-91af-1172d119a2c6', '2026-27', 'required', 'The first-time freshman page says all students must submit an ACT/SAT score to be considered. Guaranteed admission needs the college-prep courses plus a 3.0 GPA OR ACT 22 / SAT 1100 (EBRW + Math), or a 2.7 GPA with ACT 19 / SAT 990. Others can go to admission by review with a personal statement form.', '19bf4abe-ccaf-5aad-afc2-c3a418619783');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('749d1c5a-40b4-5875-91af-1172d119a2c6', '2026-27', array['own']::text[], 30, 'International applicants apply through MTSU''s own online application ($30 non-refundable; $25 for domestic freshmen). MTSU is no longer on the Common App. Official transcripts must come from the school''s official email; a NACES course-by-course evaluation is needed for any non-U.S. college work. Processing takes up to 30 days once complete. The pages do not mention essays or recommendations for guaranteed admission.', 'f009ac86-de98-54bd-810e-19f24c4c2586');
insert into deadlines (id, institution_id, cycle, kind, label, due_date, notes, source_id) values
 ('56349a8e-13c3-515b-8711-63c468a0de56', '749d1c5a-40b4-5875-91af-1172d119a2c6', '2026-27', 'application', 'International application deadline, fall 2027 entry', '2027-07-01', 'Fall deadline is July 1 of the same year; spring is Nov 1 of the previous year. Printed without a year, treated as fall 2027. A complete file is needed before an I-20 can be issued.', 'f009ac86-de98-54bd-810e-19f24c4c2586'),
 ('6828d323-62d0-51b2-8899-66bd731f50ab', '749d1c5a-40b4-5875-91af-1172d119a2c6', '2026-27', 'scholarship', 'International merit scholarship priority date (fall)', '2027-06-01', 'Funds are distributed first-come, first-served until exhausted; spring priority is Oct 1.', '55d999f4-f4e0-59ea-bd88-b596e33a97ea');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('749d1c5a-40b4-5875-91af-1172d119a2c6', 'required_nonnative', 'F-1 applicants must submit proof of English proficiency unless English is the official language of their country of citizenship, they graduated from a high school (U.S. or abroad) whose main language of instruction is English, have SAT Critical Reading/EBRW 510+ or ACT composite 22+, or completed ENGL 1010 and 1020 (or a year of English with B or higher) or an associate degree or higher at a U.S. college. Scores are valid for two years and must come from the testing agency. MTSU also accepts iTEP 3.5 and ELS Level 110 certificate (iTEP 3.8, ELS 112 for Professional Pilot and Nursing). MTSU has an Intensive English Language Program.', 'f009ac86-de98-54bd-810e-19f24c4c2586');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
select '749d1c5a-40b4-5875-91af-1172d119a2c6'::uuid, 'required_option', 'f009ac86-de98-54bd-810e-19f24c4c2586'::uuid, v.* from (values
 ('TOEFL_IBT_2026', 4, 'Page lists ''TOEFL iBT - 4'' without naming the scale; read as the new 1-6 scale. Professional Pilot and Nursing: 4.5.'),
 ('IELTS', 5.5, 'Professional Pilot and Nursing: 6.0.'),
 ('DUOLINGO', 85, 'Professional Pilot and Nursing: 95.'),
 ('PTE', 59, 'Professional Pilot and Nursing: 70.')) v;
insert into score_codes (institution_id, test_key, notes, source_id)
select '749d1c5a-40b4-5875-91af-1172d119a2c6'::uuid, v.* from (values
 ('sat', 'MTSU pages reviewed do not print a numeric SAT code; look it up in the College Board code search.', '19bf4abe-ccaf-5aad-afc2-c3a418619783'::uuid),
 ('act', 'MTSU pages reviewed do not print a numeric ACT code; look it up at act.org.', '19bf4abe-ccaf-5aad-afc2-c3a418619783'::uuid),
 ('toefl', 'No TOEFL institution code is printed; scores must be sent directly by the testing agency.', 'f009ac86-de98-54bd-810e-19f24c4c2586'::uuid),
 ('ielts', 'No institution code is listed; official scores must be sent by the testing agency.', 'f009ac86-de98-54bd-810e-19f24c4c2586'::uuid),
 ('duolingo', 'No institution code is listed.', 'f009ac86-de98-54bd-810e-19f24c4c2586'::uuid),
 ('pte', 'No institution code is listed.', 'f009ac86-de98-54bd-810e-19f24c4c2586'::uuid)) v;
insert into cost_aid (institution_id, year, tuition_usd, tuition_out_of_state_usd, room_board_usd, books_usd, other_usd, total_coa_usd, intl_aid_policy, intl_need_aid, intl_need_aid_awarded, intl_avg_award_usd, meets_full_need, merit_scholarships, notes, source_id) values
 ('749d1c5a-40b4-5875-91af-1172d119a2c6', '2026-2027', 11424, 34888, 13460, 1260, 5482, 55090, 'merit_only', false, 296, 15064, false, true, 'MTSU financial-aid cost of attendance for 2026-27 (14 credits): out-of-state tuition and fees $34,888 vs in-state $11,424, books $1,260, on-campus living $13,460, misc $2,314 and transportation $3,168 (other = $5,482), total $55,090 out-of-state on campus. MTSU pages do not list a separate international rate, so the out-of-state rate is the relevant one for F-1 students. Mandatory international health insurance $1,729 per year unless covered privately. CDS H6: 296 nonresident undergraduates received institutional non-need aid, average $15,064 (CDS G1 was left blank).; F-1 first-year and transfer students are considered for renewable international merit scholarships: Global Scholar $16,000/year (GPA 3.75-4.0, SAT 1370+ or ACT 30+), International Achievement $12,000 (GPA 3.5-3.74 or SAT 1210+/ACT 25+), International Access $6,000 (GPA 3.0-3.49, SAT 1040+/ACT 20+). Priority deadlines June 1 (fall) and Oct 1 (spring); funds run out first-come, first-served. Contact: international@mtsu.edu. CDS H6 marks only non-need-based institutional aid for nonresidents.', '5a521766-688b-5483-b04a-2fec7fc29dd0');
