 ('52589d2b-d68d-519e-8102-48dbbc0809d1', 'd6b0ce8e-670e-59fc-88da-732f5163e976', 'admissions_site', 'MSU Texas Global Education - International undergraduate (freshman) admission', 'https://msutexas.edu/global-education/international-students/undergraduate-admissions.php', null, '2026-10-26'),
 ('51605b88-b5a9-5e6e-89e4-3e92c84a58f9', 'd6b0ce8e-670e-59fc-88da-732f5163e976', 'admissions_site', 'MSU Texas Global Education - International students: test scores (English proficiency)', 'https://msutexas.edu/global-education/international-students/test-scores.php', null, '2026-10-26'),
