insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('d088e912-36db-5e67-9974-b6dd0235848a', '2026-27', 'optional', '''Minnesota State Mankato is test-optional for admissions.'' International applicants: SAT/ACT optional, and the international page states no ACT/SAT minimum. Domestic automatic admission: HS GPA 3.0+, top 50% of class, or ACT 21+ with 2.7 GPA.', '401f53ad-e70d-522f-b6ac-30d0c7930853');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('d088e912-36db-5e67-9974-b6dd0235848a', '2026-27', array['own']::text[], 20, 'Apply through Minnesota State Mankato''s eServices (create a StarID); $20 non-refundable fee, payable after submitting. International first-year applicants need cumulative secondary results equivalent to a U.S. 3.0 GPA or better. F-1/J-1 applicants are not eligible for the comprehensive-review route. Applicants from Bangladesh, Kyrgyzstan, Malawi, Pakistan and Uganda must also complete an admission interview.', '30351556-6b35-53d5-8e8f-accb985cfea4');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('c9f8f9ab-69d5-5ff0-b97c-d42b32b8b549', 'd088e912-36db-5e67-9974-b6dd0235848a', '2026-27', 'application', 'ROLLING', 'International application deadline, fall 2027 (students needing an F-1 visa)', '2027-05-01', 'Applicants who already hold an active F-1 visa: Aug. 10. Page prints no year; treated as fall 2027. No priority dates are published.', 'ce3c6045-2606-5166-9e9f-bda1730ef6df');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('d088e912-36db-5e67-9974-b6dd0235848a', 'required_nonnative', 'Alternatives to a test: Intensive English Program (IEP) at Minnesota State Mankato with a B+ average and at least a B in each Advanced course; ELS level 112; SAT Reading 400+; ACT English 15+; or one semester of freshman English composition with C or better at a U.S. college. Aviation-Professional Flight and Nursing require higher scores (numbers not given on the page).', 'fd09c38d-ee22-52c7-8e1a-0dd7c643d611');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
