insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, pct_submit_sat, pct_submit_act, notes, source_id, source_note) values
 ('a3e7970e-ba2e-59c1-a882-433a353534c9', '2023-2024', 745, 538, 365, 8, 58, 'No readable Common Data Set: Minot State''s CDS page now points to a login-only SharePoint folder, so this is the IPEDS baseline for the fall 2023 entering class (ADM2023). College Navigator''s newer fall 2024 figures: 701 applicants, 65% admitted, 78% of admitted enrolled (the admit rate fell from 72% in fall 2023, so it is not an open-admission school for every applicant). IPEDS gives no international applicant/admit split and no GPA data. Undergraduate enrollment 2,499 and student-to-faculty ratio 11:1 are College Navigator fall 2024.', 'cfb52f89-6afd-575a-823e-98fe506d0cf0', 'admissions_site');
insert into test_score_percentiles (institution_id, cds_year, source_id, test, p25, p50, p75)
select 'a3e7970e-ba2e-59c1-a882-433a353534c9'::uuid, '2023-2024', 'cfb52f89-6afd-575a-823e-98fe506d0cf0'::uuid, v.* from (values
 ('SAT_ERW', 480, 520, 580),
