insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('e4c071b9-1c42-5ad6-9065-598353629dfc', '2026-27', 'optional', 'ACT is ''not required for admissions but may be requested when enrolling in classes to assist with placement''; MSSU has been test optional since August 2020 (CDS C8F).', '4d7a9324-fd17-5dfe-8108-b4403d32b9b9');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('e4c071b9-1c42-5ad6-9065-598353629dfc', '2026-27', array['own']::text[], 60, 'Own online application; $60 non-refundable international fee (must be paid before acceptance). Freshmen must meet one of: 2.25 cumulative GPA, top 50% of class, or ACT 21 / SAT 1060 (per the international guide). Needs passport photo page, transcripts (university work needs a credential evaluation), proof of finances for one year, and a health center screening. After getting a visa, a $3,000 enrollment deposit is required. CDS C13 shows a $30 fee (resident rate) and an Aug 1 priority date with no closing date for first-year domestic applicants. No faith or interview requirement found.', '07104a66-5d1f-5e1c-a49b-9d7e49fae4c1');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('501d4b50-9c97-5b59-92b3-6334cb9fed0c', 'e4c071b9-1c42-5ad6-9065-598353629dfc', '2026-27', 'application', 'ROLLING', 'International fall 2027 application deadline', '2027-06-01', 'Fall = June 1 on the international page; no year is printed, taken as fall 2027. An older MSSU catalog page gave July 1.', '07104a66-5d1f-5e1c-a49b-9d7e49fae4c1'),
 ('1b2e1e94-7e6b-5127-b616-a0f9f5623805', 'e4c071b9-1c42-5ad6-9065-598353629dfc', '2026-27', 'application', 'ROLLING', 'International spring 2027 application deadline', '2026-11-01', 'Spring = November 1; no year printed, taken as spring 2027 entry. Summer = April 1.', '07104a66-5d1f-5e1c-a49b-9d7e49fae4c1');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('e4c071b9-1c42-5ad6-9065-598353629dfc', 'required_nonnative', 'Waived for freshmen who completed 3 or more years and graduated from a US high school; transfers from US colleges with English Comp I and II at C or higher. Applicants below the minimums can apply to the Intensive English Program. Students with a TOEFL writing score below 25 must take an on-campus placement exam.', '07104a66-5d1f-5e1c-a49b-9d7e49fae4c1');
