insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('e9621290-b819-530e-8686-a29bcd22bd4b', '2026-27', 'optional', 'ACT/SAT are not required for admission or scholarship consideration. Admission needs a 2.5 cumulative high school GPA, or ACT 22, or SAT 1120, or upper-half class rank, plus the college-prep curriculum. Scores can replace MSU''s math placement assessment. International applicants who attended a US or Canadian high school are asked for official SAT/ACT scores.', 'f04e117f-861e-55be-978f-ba9ca21b3202');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('e9621290-b819-530e-8686-a29bcd22bd4b', '2026-27', array['own']::text[], 38, 'International online application (msuadmissions.com/international) with a $38 non-refundable fee ($30 on the paper form; never waived or deferred). Also needed: proof of English proficiency and the high school transcript (unofficial copies reviewed for admission, official required before registration). Financial certificate and bank statement are required for the I-20, not for the admission decision.', '58464e11-27cb-5df2-9ee3-788d06f1731c');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('aa944268-463d-5f6d-8c16-3432eb9c0a80', 'e9621290-b819-530e-8686-a29bcd22bd4b', '2026-27', 'application', 'ROLLING', 'International application deadline, fall 2027', '2027-07-01', 'July 1 for fall (spring Nov. 15, summer March 15); later applications may be considered case by case, and MSU encourages applying six months earlier. The page prints no year; treated as fall 2027. The CDS (C14) lists a 9/15 first priority date with rolling action afterwards.', '58464e11-27cb-5df2-9ee3-788d06f1731c');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('e9621290-b819-530e-8686-a29bcd22bd4b', 'required_nonnative', 'Exempt: IB diploma; IGCSE O-level English C or above (or GCSE English 4+); 2 semesters or 24+ credits at a US regionally accredited college including two college English courses with C or better; the last 2 years at a US high school with B or better in English; a bachelor''s, master''s or doctorate from a US institution or a listed English-speaking country; or secondary school completed in a listed country with English-medium instruction. Also accepted: SAT EBRW 440 (Writing/Language 25+), ACT English 20+, APIEL 3, EIKEN Pre-1, or completing an intensive English program at a listed center (e.g. ELS level 112, EF C-1). Sub-scores are also considered.', '8209f1db-8d2d-5ee6-9a19-cb590dff7005');
insert into english_requirements (institution_id, source_id, test_key, status, min_total, notes)
