insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, intl_applicants, intl_admits, in_state_applicants, in_state_admits, out_state_applicants, out_state_admits, pct_submit_sat, pct_submit_act, gpa_avg, pct_reporting_gpa, gpa_distribution, notes, source_id) values
 ('84320030-d0bf-53e1-8365-da176a4916c8', '2025-2026', 8087, 6735, 1275, 1426, 730, 4857, 4462, 1732, 1543, 4, 82, 3.47, 100, '{"4.0": 8, "3.75-3.99": 28, "3.50-3.74": 21, "3.25-3.49": 15, "3.00-3.24": 10, "2.50-2.99": 13, "2.0-2.49": 4, "1.0-1.99": 0}'::jsonb, 'Fall 2025 first-time first-year class (CDS C1 residency breakdown: 1,426 international applicants, 730 admitted, 44 enrolled; 72 applicants of unknown residency). International admit rate (about half) is far lower than the overall rate. Undergraduate enrollment 7,941 and nonresident 98 are the B2 total-undergraduate figures, which include many non-degree dual-credit students (degree-seeking undergraduates: 4,541). GPA distribution is the ''all enrolled students'' column of C11 (whole percents, summing to 99). SAT percentiles rest on only 45 students (4%); ACT was submitted by 1,041 (82%). CDS C7 factor checkboxes are not legible in the PDF text, so factors are omitted. Student-to-faculty ratio 16:1 is from CDS section I.', '1e00b88e-12b2-5912-b4c3-3983043ecc14');
insert into test_score_percentiles (institution_id, cds_year, source_id, test, p25, p50, p75)
select '84320030-d0bf-53e1-8365-da176a4916c8'::uuid, '2025-2026', '1e00b88e-12b2-5912-b4c3-3983043ecc14'::uuid, v.* from (values
 ('SAT_TOTAL', 940, 1030, 1130),
 ('SAT_ERW', 500, 545, 605),
 ('SAT_MATH', 460, 500, 590),
 ('ACT_COMPOSITE', 18, 21, 24),
 ('ACT_ENGLISH', 17, 21, 25),
 ('ACT_MATH', 16, 19, 23)) v;
insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('84320030-d0bf-53e1-8365-da176a4916c8', '2026-27', 'optional', 'ACT/SAT are generally not required for undergraduate admission, but scores are used for scholarship eligibility and may be needed for placement or specific programs; international applicants may submit them optionally. Admission decision is based on unweighted high school GPA.', '95df8a67-ce1a-55a6-bedb-d91d4395f166');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('84320030-d0bf-53e1-8365-da176a4916c8', '2026-27', array['own']::text[], 30, 'Apply on Morehead State''s own online application. CDS C13 lists a $30 application fee (the international pages do not state a fee). Required: official high school transcript showing graduation, GPA of at least 2.50 (the Admission Requirements page also lists provisional admission for international students with a 2.00-2.49 GPA), English proficiency proof, original bank documents at least $43,125 (the Admission Requirements page says $34,000; confirm the current amount) on bank letterhead and under three months old, and passport/visa/I-20 copy. BSN nursing and imaging sciences need a second, program-level admission step. Federal rules require at least four face-to-face classes for F-1 students.', '2db7298f-d0ad-52b3-9392-70a3615cac1c');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('8af001ae-16df-5fbd-bfab-f1d6119a3706', '84320030-d0bf-53e1-8365-da176a4916c8', '2026-27', 'application', 'ROLLING', 'International application deadline, fall 2027 entry', '2027-08-01', 'Printed without a year, treated as fall 2027. Other terms: spring Jan. 2, winter Dec. 2, summer May 15 (based on course availability). CDS C14 lists a fall closing date of 8/24 and a priority date of 3/15 for all applicants.', '1df41b16-9599-526b-896c-fa106df30d84');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('84320030-d0bf-53e1-8365-da176a4916c8', 'required_nonnative', 'Exempt: applicants from the listed English-speaking countries (e.g., Australia, Canada except Quebec, Ireland, Jamaica, New Zealand, UK, US and several Caribbean nations); graduates of a U.S. high school who submit ACT 20 or SAT 1030; or 24 or more credit hours from an accredited U.S., Australian, Canadian (not Quebec), Irish, New Zealand or UK institution. The pages do not mention conditional admission or an intensive English pathway.', '5bfc2372-4f01-5cbb-955a-f92d7f9b86a1');
insert into english_requirements (institution_id, status, test_key, min_total, notes, source_id)
select '84320030-d0bf-53e1-8365-da176a4916c8'::uuid, 'required_option', v.* from (values
 ('TOEFL_IBT', 61, 'Also TOEFL 173 computer-based or 500 paper. Institution code 1487. The pages do not give a 1-6 scale value.', '5bfc2372-4f01-5cbb-955a-f92d7f9b86a1'::uuid),
 ('IELTS', 5.0, 'Minimum 5.0 for undergraduates.', '5bfc2372-4f01-5cbb-955a-f92d7f9b86a1'::uuid),
 ('DUOLINGO', 105, 'Duolingo English Test (official score), 105; listed on the international admission and requirements pages but not on the English proficiency page.', '2db7298f-d0ad-52b3-9392-70a3615cac1c'::uuid),
 ('PTE', 50, 'Pearson Test of English Academic, 50; listed on the international admission and requirements pages but not on the English proficiency page.', '2db7298f-d0ad-52b3-9392-70a3615cac1c'::uuid)) v;
