insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('b94f5f29-b306-56ea-a3f0-816912446970', '2026-27', 'optional', 'Morgan says applying test-optional does not help or hurt admission and does not affect consideration for merit scholarships or the Honors College. Admission is holistic: weighted and unweighted GPA are considered; no minimum GPA is published. Required courses: 4 English, 3 science (with lab), 3 history/social science, 4 math, 2 foreign language or advanced technology.', '01cc7ee5-c536-59f7-9233-e44086e68686');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('b94f5f29-b306-56ea-a3f0-816912446970', '2026-27', array['common_app','own']::text[], 35, 'Apply with the Morgan application, the Common App or the Common Black College Application (use only one). The $35 non-refundable fee is stated on the freshman page; a separate international fee is not published. International applicants also send financial documents (bank statement or affidavit of support) for the I-20 and applications are not reviewed until complete. Essays and recommendations are not listed.', '01cc7ee5-c536-59f7-9233-e44086e68686');
insert into deadlines (id, institution_id, cycle, kind, label, due_date, notes, source_id) values
 ('546462b1-0851-5f73-b6ca-dda640066d71', 'b94f5f29-b306-56ea-a3f0-816912446970', '2026-27', 'application', 'International applicants: fall 2027 application deadline', '2026-11-15', 'From the International Applicants column of the deadlines table (Fall 2027: Application Nov 15, Documents Due Dec 15). Freshman (domestic) dates differ: priority Dec 1, application Apr 1, documents Apr 30. The OISS page cites Dec 1 for the international fall application; the admissions table is used here.', '4aaf2c28-d253-5006-b672-525b4e4755f0'),
 ('3602fea1-3302-50ec-a09a-53337302df10', 'b94f5f29-b306-56ea-a3f0-816912446970', '2026-27', 'other', 'International applicants: supporting documents due (fall 2027)', '2026-12-15', null, '4aaf2c28-d253-5006-b672-525b4e4755f0');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('b94f5f29-b306-56ea-a3f0-816912446970', 'required_nonnative', 'TOEFL, IELTS or Duolingo scores are usually required; Morgan may waive in some cases, such as studying in English in high school (OISS page). Cambridge and PTE are not listed. Morgan lists a paper-based TOEFL minimum of 550 alongside the iBT.', '80df289f-faa0-5f8c-a09f-5be563adb309');
