insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, pct_submit_sat, notes, source_id, source_note) values
 ('e05eccef-f5c4-52d0-a47c-2dd7755fb89f', '2024-2025', 1577, 1294, 318, 10, 'Baseline from IPEDS (fall 2024 entering class); no Common Data Set was found for Mount Aloysius (search of the college site returned only the 2025-26 and 2026-27 catalogs), so GPA, residency and international applicant splits are not available. Undergraduate enrollment 2,942 and the 11-to-1 student-faculty ratio are from College Navigator (fall 2024). SAT percentiles are for only 32 enrolled first-time students (10% submitting); no ACT percentiles are reported. IPEDS shows 1,577 applicants, 1,294 admitted (82%) and 318 enrolled.', 'd1115c71-946c-5a30-9650-eebdfb115050', 'admissions_site');
insert into test_score_percentiles (institution_id, cds_year, source_id, test, p25, p50, p75)
select 'e05eccef-f5c4-52d0-a47c-2dd7755fb89f'::uuid, '2024-2025', '8f4bb8c5-0cd9-5281-be67-cbd881a5e21d'::uuid, v.* from (values
 ('SAT_ERW', 473, 540, 598),
 ('SAT_MATH', 445, 530, 570)) v;
insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('e05eccef-f5c4-52d0-a47c-2dd7755fb89f', '2026-27', 'optional', 'Test optional for most programs. SAT/ACT are required only to be considered for the cooperative programs in Dental Medicine, Occupational Therapy, Pharmacy, Osteopathic Medicine, Physician Assistant and Physical Therapy. Nursing applicants (2+2 and BSN 3.5) must take the TEAS for direct acceptance. International applicants follow the same policy; SAT/ACT scores taken within the last two years may be submitted.', 'af764bbb-8697-5f5a-bf72-06eb7019c328');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('e05eccef-f5c4-52d0-a47c-2dd7755fb89f', '2026-27', array['common_app','own']::text[], 0, 'The apply page says the college is currently offering a fee-waived application, subject to change; the FAQ lists a $30 application fee without saying whether it applies to undergraduates. Apply with the college application (apply.mtaloy.edu) or the Common App. International applicants send official secondary records with certified English translations (a WES or other NACES evaluation is strongly encouraged), proof of health insurance and health forms, and return a financial affidavit within two weeks of acceptance. A $250 enrollment deposit triggers the I-20. Essays and recommendations are not listed for first-year applicants.', 'f6a3d843-d7b7-56a1-a41e-45ef20cd7030');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('88311c4b-3a0e-55a5-b7d7-73a8a8ea571c', 'e05eccef-f5c4-52d0-a47c-2dd7755fb89f', '2026-27', 'priority', 'ROLLING', 'Priority date for nursing and health sciences (fall 2027 entry)', '2027-01-01', 'The apply page says students interested in nursing and health sciences are encouraged to apply by January 1; no year is printed, so it is taken as January 1, 2027 for fall 2027 entry.', 'f6a3d843-d7b7-56a1-a41e-45ef20cd7030'),
 ('4fe9c6bb-e03e-58a0-9c6a-2836c81885c5', 'e05eccef-f5c4-52d0-a47c-2dd7755fb89f', '2026-27', 'application', 'ROLLING', 'Rolling admission for fall and spring starts', null, 'Applications are accepted throughout the year with no fixed closing date. No separate international application deadline is published; international students may start in the fall or spring semester. Programs and courses can fill or be waitlisted after the national May 1 enrollment date.', 'd7278d9f-7944-5d5d-a904-91c63badb248'),
 ('3fce02c1-68d0-5e91-ac87-a275f560a268', 'e05eccef-f5c4-52d0-a47c-2dd7755fb89f', '2026-27', 'deposit', null, 'National enrollment deadline (fall 2027 entry)', '2027-05-01', 'The FAQ says the college follows the national May 1 enrollment deadline; no year is printed, so it is taken as May 1, 2027. The enrollment deposit is $250 (the I-20 is issued when it is received).', 'd7278d9f-7944-5d5d-a904-91c63badb248');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('e05eccef-f5c4-52d0-a47c-2dd7755fb89f', 'required_nonnative', 'A TOEFL, IELTS, PTE Academic or Duolingo score is required for applicants whose native language is not English, unless they hold a certificate of completion from an English-medium education system. Every applicant is reviewed case by case and admission is never guaranteed.', '3364bef2-908a-5326-b95f-a1ed434c65d4');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
select 'e05eccef-f5c4-52d0-a47c-2dd7755fb89f'::uuid, 'required_option', '3364bef2-908a-5326-b95f-a1ed434c65d4'::uuid, v.* from (values
 ('TOEFL_IBT', 61, 'Minimum 61 (internet-based). The international page also prints a computer-based score of 173. Undergraduates scoring comparable to IELTS 6.0 or below must take a 6-credit transition seminar (see IELTS note).'),
 ('IELTS', 5.5, 'Minimum 5.5. Undergraduate international students scoring 6.0 or below on IELTS (or comparable TOEFL or other scores) must take a six-credit transition seminar course; students who completed an ESL program in the U.S., come from an English-speaking country, or transfer in 24+ credits from a U.S. college with a 2.5+ GPA are exempt.'),
 ('DUOLINGO', 85, null),
 ('PTE', 42, 'PTE Academic.')) v;
insert into score_codes (institution_id, test_key, notes, source_id)
select 'e05eccef-f5c4-52d0-a47c-2dd7755fb89f'::uuid, v.* from (values
 ('sat', 'No SAT code is printed on the admissions pages (the only code listed is Federal School Code 003302, used for the FAFSA); look it up in the College Board code search.', 'd7278d9f-7944-5d5d-a904-91c63badb248'::uuid),
 ('act', 'No ACT code is printed on the admissions pages; look it up at act.org.', 'd7278d9f-7944-5d5d-a904-91c63badb248'::uuid),
 ('toefl', 'No TOEFL institution code is printed on the admissions pages.', 'af764bbb-8697-5f5a-bf72-06eb7019c328'::uuid),
 ('ielts', 'No institution code is listed.', 'af764bbb-8697-5f5a-bf72-06eb7019c328'::uuid),
 ('duolingo', 'No institution code is listed.', 'af764bbb-8697-5f5a-bf72-06eb7019c328'::uuid),
 ('pte', 'No institution code is listed.', 'af764bbb-8697-5f5a-bf72-06eb7019c328'::uuid)) v;
insert into cost_aid (institution_id, year, tuition_usd, required_fees_usd, total_coa_usd, intl_aid_policy, merit_scholarships, notes, source_id) values
 ('e05eccef-f5c4-52d0-a47c-2dd7755fb89f', '2026-2027', 27218, 1504, 50232, 'merit_only', true, 'Tuition is $13,609 per semester (General Studies, doubled to a year); Health Studies $14,773 and Nursing $15,382 per semester. Comprehensive fee $752 per semester. Resident students must buy a meal plan: shared-room housing plus meals runs $5,465 to $7,777 per semester, so room_board_usd is left null. total_coa_usd is the college''s on-campus budget for most majors (Health Studies $52,560, Nursing $53,778). The page does not give a separate international tuition rate. Housing is mandatory for traditional-age full-time international students.; The scholarships page says full-time international students living on campus are eligible for a $17,000 International Grant plus a $2,000 Residence Hall Grant, and those living off campus receive a $12,000 International Grant; the page does not say whether the International Grant is per year (the Residence Hall Grant is described as $2,000 a year). Separate academic awards for new full-time students are set by high school GPA (up to $16,000 to $44,000 over four years). A search-engine snippet of the same page showed older figures ($15,000, $3,000 and $11,000), so confirm current amounts with admissions. Eligible non-citizens with an Alien Registration Number or permanent residency can file the FAFSA; other international students are not eligible for federal aid. Need-based aid for international students is not stated.', '9752c3bd-d3ca-5371-9fc7-f9f419470bec');
insert into institution_tiers (institution_id, tier_code, category_key, rationale)
select 'e05eccef-f5c4-52d0-a47c-2dd7755fb89f'::uuid, 'D', v.* from (values
 ('general', 'Admit rate 82.1%'),
 ('business', 'Editorial judgment (v1, reviewed 2026-10-20)'),
 ('biology_life_sci', 'Editorial judgment (v1, reviewed 2026-10-20)'),
 ('humanities', 'Editorial judgment (v1, reviewed 2026-10-20)'),
 ('nursing', 'Editorial judgment (v1, reviewed 2026-10-20)')) v;
insert into major_admissions (id, institution_id, program, category_key, admit_model, capped, notes) values
 ('8d54eb96-10e1-51c1-beb2-ab73fc08854a', 'e05eccef-f5c4-52d0-a47c-2dd7755fb89f', 'Nursing, traditional pre-licensure BSN (3.5 years)', 'nursing', 'direct_major', false, 'Applicants must take the TEAS and submit scores for direct acceptance; no minimum TEAS score is published on the admissions pages.');

