insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, notes, source_id, source_note) values
 ('21ac3a09-b0df-502c-b216-e1fae3a0d219', '2024-2025', 3546, 3018, 410, 'Baseline from IPEDS (fall 2024 entering class); no Common Data Set was found on the University''s website or by web search. Counts from the IPEDS ADM2024 file (via the Urban Institute API mirror): 3,546 applicants, 3,018 admitted, 410 enrolled (396 full-time + 14 part-time); fall 2023 was 3,775 / 3,195 / 489. UMSV is test-optional: only 8 enrolled first-time students (2%) submitted SAT scores in fall 2024, so SAT/ACT percentiles are not shown. International applicant counts and GPA data are not published. College Navigator shows 3% of undergraduates as U.S. nonresidents and 6% of first-time students from foreign countries. Undergraduate enrollment (2,725) includes 837 transfer-in students.', 'cef8629c-3f7f-517f-93f5-3b65a735154f', 'admissions_site');
insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('21ac3a09-b0df-502c-b216-e1fae3a0d219', '2026-27', 'optional', 'Standardized test scores (SAT code 2088, ACT code 2823) are optional for first-year applicants. However the international pages say every first-year international applicant ''must submit test scores of some kind'': SAT/ACT or an English proficiency test (TOEFL, IELTS, GTECH CBT, Pearson PTE; the checklist also lists Duolingo).', 'b88b05ff-4482-54f3-b012-5a24bfb85f79');
insert into application_requirements (institution_id, cycle, platforms, supplemental_essays, app_fee_usd, notes, source_id) values
 ('21ac3a09-b0df-502c-b216-e1fae3a0d219', '2026-27', array['common_app','own']::text[], 'Optional supplemental essay of 250-300 words.', 0, '''There is no fee to apply to the Mount''. Applications are accepted with a self-reported GPA (nursing applicants submit transcripts). International secondary transcripts must be in English in U.S. format or come with an official grading scale; otherwise a NACES translation/evaluation is needed (SpanTran, Josef Silny, WES, Global Credential Evaluators). Passport copy required. After admission: bank statements with at least three months of history and a final balance above the remaining cost of attendance, then the I-20 is sent by FedEx. Catholic-tradition, nonsectarian university in the Riverdale section of New York City.', '3a2fbf4a-a78a-5eb7-8b2a-851a8a1868d4');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('8804f150-89e2-5a83-8952-f5b4b63b70d2', '21ac3a09-b0df-502c-b216-e1fae3a0d219', '2026-27', 'application', 'EA', 'Early Action, first-year (fall 2027 entry)', '2026-11-15', 'International checklist: ''Early Action: November 15''. No year is printed; taken as fall 2027 entry.', '3a2fbf4a-a78a-5eb7-8b2a-851a8a1868d4'),
 ('04c59065-9fea-5f03-8a1f-42fbf81a7a02', '21ac3a09-b0df-502c-b216-e1fae3a0d219', '2026-27', 'application', 'RD', 'Final deadline, first-year (fall 2027 entry)', '2027-03-01', 'International checklist: ''Final Deadline: March 1'' (no year printed; taken as fall 2027). The first-year page describes rolling admission with a March 1 priority date and a decision within four weeks of a complete application. Spring semester deadline is October 15.', '3a2fbf4a-a78a-5eb7-8b2a-851a8a1868d4');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('21ac3a09-b0df-502c-b216-e1fae3a0d219', 'required_nonnative', 'Required for students from a country whose official language is not English or whose native language is not English. Waived with citizenship, residency and education in a designated English-speaking nation; four years at a U.S. high school with a B or better in non-ESL English and a 2.5 GPA; an international high school taught entirely in English with the same B / 2.5 conditions; or three college credits with a B or better in first-year English composition. Other accepted proof: GTECH CBT 1100, SAT EBRW 550, ACT English 22. Conditional admission: applicants without enough English are directed to an on-campus English language program before applying (the checklist calls it the English Language Service (ELS) program; the 2026-27 catalog says Kings Education).', '3a2fbf4a-a78a-5eb7-8b2a-851a8a1868d4');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
select '21ac3a09-b0df-502c-b216-e1fae3a0d219'::uuid, 'required_option', '3a2fbf4a-a78a-5eb7-8b2a-851a8a1868d4'::uuid, v.* from (values
 ('TOEFL_IBT', 80, 'Listed as ''online TOEFL - 80''; the paper-based minimum is 550. The 1-6 scale is not mentioned.'),
 ('IELTS', 6.5, null),
 ('DUOLINGO', 105, 'Listed on the international checklist and in the 2026-27 catalog.'),
 ('PTE', 58, 'Pearson PTE.')) v;
insert into score_codes (institution_id, test_key, code, notes, source_id)
select '21ac3a09-b0df-502c-b216-e1fae3a0d219'::uuid, v.* from (values
 ('sat', '2088', 'SAT code printed on the first-year checklist.', 'b88b05ff-4482-54f3-b012-5a24bfb85f79'::uuid),
 ('act', '2823', 'ACT code printed on the first-year checklist.', 'b88b05ff-4482-54f3-b012-5a24bfb85f79'::uuid),
 ('toefl', null, 'No TOEFL code is printed on the UMSV admissions pages.', '3a2fbf4a-a78a-5eb7-8b2a-851a8a1868d4'::uuid),
