insert into cost_aid (institution_id, year, tuition_usd, tuition_out_of_state_usd, tuition_intl_usd, required_fees_usd, room_board_usd, merit_scholarships, notes, source_id) values
 ('21ac3a09-b0df-502c-b216-e1fae3a0d219', '2026-2027', 46500, 46500, 46500, 1920, 16200, true, '2026-27 catalog, first-year students: full-time tuition $46,500 per year (12-18 credits a term; $1,350 per credit part-time); room and board $16,200 (shared occupancy); technology fee $800, student activity fee $420 and academic service fee $700 (required_fees is their sum). Student health insurance $3,006 is required unless waived with proof of coverage. Program costs average $1,000 a year for texts and supplies. The catalog does not print a total cost of attendance.; International applicants are reviewed for merit scholarships the same way as domestic ones: the International Student Merit Scholarship is awarded at acceptance (four years for first-year students) based on cumulative GPA and standardized test scores, renewable with a 3.2 GPA. The amount is not published for international students; the Tuition/Fees page says merit scholarships in general range from $17,000 to $30,000 per year. Premier Programs offer full-tuition or room-and-board awards. Federal aid (FAFSA) does not apply to international students.', 'baf094d7-fcb4-5ff5-af90-9e0322a8a7b5');
insert into institution_tiers (institution_id, tier_code, category_key, rationale)
