insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('17d6f0fc-e554-59dd-bdef-7c7223b51257', '2026-27', 'optional', 'Admissions page: ''Test scores are optional''; ACT/SAT or transfer credits can exempt a student from math/English placement exams. The CDS says test scores are not used in admission decisions. Domestic guaranteed admission is a 2.0 unweighted high school GPA; international applicants are not covered by that guarantee on the pages read.', 'ec1ee6ea-86ad-5dc1-ab46-f674654d88a2');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, fee_waiver, notes, source_id) values
 ('17d6f0fc-e554-59dd-bdef-7c7223b51257', '2026-27', array['common_app','own']::text[], 50, false, 'International application fee is $50 (domestic applications are free). Apply with the Roadrunner Application (recommended for international students) or the Common App. Needs official secondary credentials with final results and graduation date (professional English translation if needed), a NACES course-by-course evaluation for any international university work, English proficiency evidence, and financial documentation (bank statement under five months old plus F-1 financial affidavit). No minimum GPA is stated for international applicants.', 'edd8bd99-9d66-55a7-a5d4-5e209bd488d7');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('608df4f5-a48f-5046-9f28-2b3ff21039da', '17d6f0fc-e554-59dd-bdef-7c7223b51257', '2026-27', 'application', 'ROLLING', 'International first-time application deadline (fall 2027 entry)', '2027-06-15', 'From the international deadlines table (first-time international column; transfers from U.S. institutions are July 1, 2027). Spring 2027 is Nov. 1, 2026 and summer 2027 is April 1, 2027. The page recommends applying early.', 'edd8bd99-9d66-55a7-a5d4-5e209bd488d7');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('17d6f0fc-e554-59dd-bdef-7c7223b51257', 'required_nonnative', 'Scores valid 2 years (Cambridge and SAT/ACT/AP 5 years). Also accepted: LanguageCert 65, Michigan English Test 59, ACT 18 English and 17 overall, SAT 470 Reading and Writing, AP English Language or Literature 3+. Exemptions: citizens of listed majority-English countries; completion of an accredited intensive English program within 5 years; US high school graduation after 2+ years, GED/HiSET, US AA/AS, or 24 semester hours of college work within 5 years; and listed national qualifications (e.g. IB English A grade 4, IGCSE/GCSE C or 4, WASSCE C6, India CBSE/ICSE 60%). Medium of instruction is not accepted. TOEFL Essentials and My Best Score are not accepted. Conditional admission is not mentioned on the pages read.', 'ea3a2e99-3a64-5a0f-afac-cd184715e9b4');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
select '17d6f0fc-e554-59dd-bdef-7c7223b51257'::uuid, 'required_option', 'ea3a2e99-3a64-5a0f-afac-cd184715e9b4'::uuid, v.* from (values
 ('TOEFL_IBT', 72, 'Home Edition accepted; no subscore minimums listed.'),
 ('TOEFL_IBT_2026', 4.0, 'Listed as ''TOEFL iBT (New)'' without naming the 1-6 scale.'),
 ('IELTS', 6.0, 'Academic overall band.'),
 ('DUOLINGO', 105, null),
 ('PTE', 49, 'PTE Academic.'),
 ('CAMBRIDGE', 169, 'B2 First, C1 Advanced or C2 Proficiency; valid 5 years.')) v;
