insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('17197bf7-8219-5111-b172-b5e0a469e6ae', '2026-27', 'optional', 'Murray State calls its process test-optional: freshmen with an unweighted high school GPA of 2.75 or higher are admitted, and 2.0-2.74 gets holistic review. International applicants need a high school GPA of at least 2.0 and English proof; an SAT total of 960 is one of the accepted English proofs.', '557a0866-bd37-5355-86db-49e9b926e6c0');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('17197bf7-8219-5111-b172-b5e0a469e6ae', '2026-27', array['own']::text[], 100, 'International application fee is $100 online ($200 if applying for conditional admission through the ESL program); domestic freshmen pay $40. Required uploads: passport, high school transcripts (GPA 2.0+) with certified translation, graduation certificate, bank statement of at least $30,706 or a scholarship letter, and English proof. Common App use not confirmed on the pages read.', '132926c1-d206-587b-b779-d8b551707130');
insert into deadlines (id, institution_id, cycle, kind, label, due_date, notes, source_id) values
 ('f97fd84c-3a96-501c-b9a0-bdee15a000c7', '17197bf7-8219-5111-b172-b5e0a469e6ae', '2026-27', 'application', 'International bachelor''s application deadline, Fall 2027 (August intake)', '2027-07-19', 'From the international application page, which lists the Fall 2027 intake explicitly. Spring 2027 (January intake): Nov. 15. Transfer students already in the US: July 20 for fall.', '132926c1-d206-587b-b779-d8b551707130'),
 ('c477be83-4614-51c4-a5b7-681736205824', '17197bf7-8219-5111-b172-b5e0a469e6ae', '2026-27', 'scholarship', 'General Scholarship Application deadline (competitive scholarships)', '2027-02-01', 'Competitive scholarships are open to all students and require admission first. The first-year Academic Achievement scholarships and the Presidential Fellowship (Dec. 1, 2026 deadline) are stated as available only to domestic students.', 'cf4466a6-8e9b-5ad0-a934-91db0da4fd02');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('17197bf7-8219-5111-b172-b5e0a469e6ae', 'required_nonnative', 'English proof is not required from citizens of the listed English-speaking countries or from graduates of a US high school; it is also met by admission to or completion of Murray State''s ESL program, five O-level passes (GCE/GCSE/IGCSE/AICE/HIGCSE) or Cambridge English B2+, or one full-time semester (12+ credits) at a US institution with a 2.5 GPA. Accepted tests (full admission / admission with condition): IELTS 6.0 / 5.5, TOEFL iBT 71 / 61, SAT 960, GTEC 1190 / 1100, PTE 51 / 45, Duolingo 100 / 90, TOEIC 790 / 700, Kaplan Advanced / Higher Intermediate. Admitted with condition means undergraduates must keep a 2.0 GPA in the first semester. Applicants below those scores can apply for conditional admission starting in the ESL program.', '132926c1-d206-587b-b779-d8b551707130');
insert into english_requirements (institution_id, source_id, test_key, status, min_total, recommended_total, notes)
select '17197bf7-8219-5111-b172-b5e0a469e6ae'::uuid, '132926c1-d206-587b-b779-d8b551707130'::uuid, v.* from (values
 ('TOEFL_IBT', 'required_option', 61, 71, '71 = standard requirement; 61 = full admission with condition (2.0 GPA in the first semester). The page gives no 1-6 scale scores. The older FAQ page says a TOEFL of 60 or less, or an IELTS of 5.0, leads to ESL conditional admission.'),
 ('IELTS', 'required_option', 5.5, 6.0, '6.0 overall = standard; 5.5 = admission with condition.'),
 ('DUOLINGO', 'required_option', 90, 100, '100 or higher = standard; 90 = admission with condition.'),
 ('PTE', 'required_option', 45, 51, '51 = standard; 45 = admission with condition.'),
 ('CAMBRIDGE', 'accepted', null, null, 'Page accepts a level of B2 or higher on the Cambridge English exam (or five O-level subject passes on GCE/GCSE/IGCSE/AICE/HIGCSE); no numeric score is printed.')) v;
insert into score_codes (institution_id, test_key, notes, source_id)
