insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('7a9ba862-21ec-5226-b8d2-260c9d5bd2ca', '2026-27', 'optional', 'NDSU is test-optional: ACT/SAT are not required for admission and decisions rely on high school GPA and core coursework; scores may be sent and are also used for math and English placement. Recommended GPA 2.75+ (4.0 scale) and 14 core high school units.', '613593e2-25d6-5371-a5ef-e250772bd229');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('7a9ba862-21ec-5226-b8d2-260c9d5bd2ca', '2026-27', array['own']::text[], 35, 'The $35 fee is the international undergraduate application fee. International first-year applicants need a U.S.-equivalent GPA of 2.75 or higher (transcripts evaluated in-house) and English proficiency; unofficial transcripts are uploaded with the application, official ones are mailed after admission. The domestic application fee was not checked.', '1d8ecb51-2e8b-56c1-8be9-b9408a6d36b7');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('05af10ba-cc10-5eec-b99f-b4ba6ffd3730', '7a9ba862-21ec-5226-b8d2-260c9d5bd2ca', '2026-27', 'application', 'ROLLING', 'International recommended deadline, fall 2027 (August start)', '2027-05-15', 'Page states May 15 for the Fall 2026 semester; treated as the same date for fall 2027. Rolling admission, documents evaluated as received. Spring entry: November 1.', '1d8ecb51-2e8b-56c1-8be9-b9408a6d36b7'),
 ('e0344c9c-24c2-58d2-9f9e-bfc9311222ae', '7a9ba862-21ec-5226-b8d2-260c9d5bd2ca', '2026-27', 'application', 'ROLLING', 'Domestic first-year application deadline, fall 2027', '2027-08-01', 'Domestic first-year page lists Fall 2027 applications by August 1; decisions typically 2-3 weeks after materials are complete. Shown for reference; international students use the earlier recommended date.', '613593e2-25d6-5371-a5ef-e250772bd229'),
 ('32bb3e64-c87e-56c8-8941-45650f5f97c8', '7a9ba862-21ec-5226-b8d2-260c9d5bd2ca', '2026-27', 'scholarship', null, 'Admitted by this date for automatic international scholarship (August start)', '2027-07-01', 'Applicants admitted before July 1 (fall) are considered automatically; no separate scholarship application.', '44233f2d-5809-5ca6-999c-9974fc7f8580');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('7a9ba862-21ec-5226-b8d2-260c9d5bd2ca', 'required_nonnative', 'Exempt: citizens of listed English-speaking countries (e.g. Australia, Canada except Quebec, Ireland, New Zealand, Nigeria, UK, Ghana); 2 years in good standing at a post-secondary institution in a listed country; 2 years at a U.S. high school or regionally accredited U.S. college; English Composition 1 and 2 with B or higher; U.S. GED taken in English. Scores valid 2 years. ACT English 18 or SAT EBRW 480 also meets the requirement.', '1d8ecb51-2e8b-56c1-8be9-b9408a6d36b7');
