select 'cd94d931-611a-5f28-9d12-e2c1d4d1806d'::uuid, v.* from (values
 ('sat', null, 'No SAT code was found on the admissions pages read; look up University of Nebraska at Kearney in the College Board code search.', '21474aa6-b38c-5c5b-8037-708a80796f56'::uuid),
 ('act', null, 'No ACT code was found on the admissions pages read; look it up at act.org.', '21474aa6-b38c-5c5b-8037-708a80796f56'::uuid),
 ('toefl', '6467', 'UNK''s ETS institution code per the English Proficiency Requirements page.', '9addef25-0296-5fe8-9ec8-a38fa1e53ba4'::uuid),
 ('ielts', null, 'Scores must be sent electronically through IELTS E-Delivery; no institution code is listed.', '9addef25-0296-5fe8-9ec8-a38fa1e53ba4'::uuid),
