insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('f45dc484-939f-5784-a6b0-dac075dc8596', '2026-27', 'optional', 'First-year admission needs the 16 core course units plus any one of: cumulative GPA 3.0, upper half of class, ACT 20+ or SAT 1040+. UNO says test scores may not be needed for admission and are used for placement and scholarships.', '221e1cf2-595f-549d-9ec4-cef10092332d');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('f45dc484-939f-5784-a6b0-dac075dc8596', '2026-27', array['own']::text[], 45, 'International applicants apply online at apply.unomaha.edu (NU application) and pay a $45 non-refundable fee (domestic applicants pay none). Documents: transcripts from every school with certified English translation, passport copy, English proficiency, and for F-1/J-1 a financial affidavit plus bank statements through the iGlobal form after admission.', 'f208868d-bac8-5bd5-95ef-aee7c1666bae');
insert into deadlines (id, institution_id, cycle, kind, label, due_date, notes, source_id) values
 ('e727748b-863a-5973-85fb-3373830e951a', 'f45dc484-939f-5784-a6b0-dac075dc8596', '2026-27', 'application', 'Fall 2027: complete admission file due', '2027-08-16', 'The catalog sets one deadline for all undergraduate applicants, one week before classes start; no separate international deadline is published. I-20s are issued up to 30 days before the admitted session, so apply well ahead. UNO encourages first-year applicants to apply in the first semester of their final year for scholarship consideration.', '15ba6053-1cef-5f73-b964-19723fd09b2f');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('f45dc484-939f-5784-a6b0-dac075dc8596', 'required_nonnative', 'Exempt: applicants from Australia, Canada, Ireland, New Zealand and the United Kingdom whose first language is English. Other ways to show proficiency: UNO Intensive English Program (IEP) completion, a U.S. A.A./A.S. with a 2.5 GPA, English Composition I and Public Speaking with a C or better plus 2.5 GPA, four years of U.S. high school English, or an official medium-of-instruction letter (catalog). TOEFL MyBest scores, TOEFL Essentials and IELTS Indicator are not accepted. Applicants who meet academic standards but not the English requirement can get conditional admission through the IEP.', 'e18ee2cf-79c5-5e33-9faf-64e5b5ccf843');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
select 'f45dc484-939f-5784-a6b0-dac075dc8596'::uuid, 'required_option', 'e18ee2cf-79c5-5e33-9faf-64e5b5ccf843'::uuid, v.* from (values
 ('TOEFL_IBT', 61, 'General undergraduate direct admission. Engineering programs 80 (writing sub-score 20), English major 100.'),
 ('TOEFL_IBT_2026', 3.5, 'Tests taken in 2026 or later, general undergraduate. Engineering 4.0, English major 5.0.'),
 ('IELTS', 6.0, 'Engineering 6.5 (writing 5.5), English major 7.0.'),
 ('DUOLINGO', 95, 'Engineering 110, English major 130.'),
 ('PTE', 44, 'PTE Academic. Engineering 53, English major 66.')) v;
