 ('toefl', null, 'UNO''s TOEFL code was not found on the official pages read; check ETS or UNO International Admissions.', 'e18ee2cf-79c5-5e33-9faf-64e5b5ccf843'::uuid),
 ('ielts', null, 'Scores must be sent directly from the testing agency; no institution code is listed.', 'e18ee2cf-79c5-5e33-9faf-64e5b5ccf843'::uuid),
