select 'a88c321f-2c01-5ce0-9d0c-59dea94f0e2b'::uuid, 'required_option', 'ce479f4a-fbc7-5b63-bf9d-2784b27950e1'::uuid, v.* from (values
 ('TOEFL_IBT', 79, '{"each_section": 18}'::jsonb, 'Old 0-120 scale. College minimums: Engineering 80, Journalism and Mass Communications 100. Paper-based test: 550 with 55 subscores (Journalism 600).'),
 ('TOEFL_IBT_2026', 4.0, '{"each_section": 4.0}'::jsonb, 'New 1-6 scale, general admission.'),
 ('IELTS', 6.5, '{"each_section": 6.0}'::jsonb, 'Journalism and Mass Communications requires 7.0.'),
 ('DUOLINGO', 110, '{"each_section": 105}'::jsonb, 'Architecture and Education and Human Sciences require 120.')) v;
