insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, pct_submit_sat, notes, source_id, source_note) values
 ('67458d8f-f77b-54ff-9ee1-6921f2218365', '2023-2024', 13498, 10872, 1296, 26, 'Baseline from IPEDS via College Navigator (fall 2024): 21,765 applicants, 60% admitted, 10% of admits enrolled; admit and enrollee counts are not printed, so they are left null. No readable Common Data Set was found (the Institutional Research site is behind a campus login), so GPA, residency and international splits are not available. 338 enrolled first-years (26%) submitted SAT; SAT section percentiles are those of submitters and only SAT is reported (no ACT percentiles; no SAT composite percentile is published). Undergraduate enrollment 4,903 is fall 2024. Applicant/admit/enrolled counts replaced with exact IPEDS ADM2023 (fall 2023) figures, because the newer source gives only a rounded admit rate.', '55c5e53e-92d6-5c1e-806d-eeca3a2fb882', 'admissions_site');
insert into test_score_percentiles (institution_id, cds_year, source_id, test, p25, p50, p75)
