insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, pct_submit_sat, pct_submit_act, notes, source_id, source_note) values
 ('db5a2994-d21a-58ef-b5e1-3a1edba1c366', '2024-2025', 7401, 5500, 993, 6, 82, 'Baseline from IPEDS (fall 2024 first-time degree-seeking entering class): 7,401 applicants, 5,500 admitted (74.3%), 993 enrolled (973 full-time). No readable Common Data Set was found (uno.edu lists only 2016-2019 sets and no newer one was found), so GPA, residency and international admission splits are not available (intl_applicants/intl_admits left null). SAT/ACT percentile ranges and the percent submitting scores come from College Navigator (fall 2024). Undergraduate enrollment 5,419 and nonresident alien 90 are IPEDS fall 2024 headcounts (College Navigator rounds nonresidents to 2%). Student-faculty ratio 19:1 from College Navigator. The university was renamed from University of New Orleans to LSU New Orleans on July 1, 2026 when it moved back into the LSU System; IPEDS/College Navigator figures above were published under the old name.', '99aebfa7-351e-5bbd-ad8a-fb7775b55238', 'admissions_site');
insert into test_score_percentiles (institution_id, cds_year, source_id, test, p25, p75)
select 'db5a2994-d21a-58ef-b5e1-3a1edba1c366'::uuid, '2024-2025', 'e846ca23-3fe3-5559-8cd5-6613d931f3f5'::uuid, v.* from (values
 ('SAT_ERW', 480, 616),
 ('SAT_MATH', 455, 625),
 ('ACT_COMPOSITE', 17, 23)) v;
insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('db5a2994-d21a-58ef-b5e1-3a1edba1c366', '2026-27', 'required', 'The freshman requirements page is explicit that LSU New Orleans is ''not test-optional'': domestic applicants without scores must take the Accuplacer. The international checklist asks first-time freshmen for official SAT/ACT results (TOEFL/IELTS is needed too if the SAT/ACT reading score is below the minimum), and the freshman minimums include a math score of ACT 19 or SAT 510 (or prior college math credit). A 2.5 core GPA is also required for international freshmen. The pages do not say whether an international freshman can substitute a placement exam for SAT/ACT; confirm with International Admissions.', '91ec2b73-3314-5bf5-afe1-9d4e7560479b');
insert into application_requirements (institution_id, cycle, platforms, notes, source_id) values
 ('db5a2994-d21a-58ef-b5e1-3a1edba1c366', '2026-27', array['own']::text[], 'Apply with the university''s online application. International freshmen send transcripts from every secondary school (foreign transcripts need a course-by-course evaluation from a NACES member; IEE and SpanTran are preferred partners), official SAT/ACT results, a financial support form, a passport copy and an immunization form or waiver. Domestic undergraduate application fees are currently waived; the pages do not state an international application fee. The I-20 is not processed until financial documents arrive; the university''s estimate is about $35,000 per academic year plus $5,000 per dependent.', '91ec2b73-3314-5bf5-afe1-9d4e7560479b');
insert into deadlines (id, institution_id, cycle, kind, label, due_date, notes, source_id) values
 ('4f20577f-790f-5307-9809-fe37f1fbbb31', 'db5a2994-d21a-58ef-b5e1-3a1edba1c366', '2026-27', 'scholarship', 'Priority date for international scholarships and awards (fall 2027 entry)', '2026-12-15', 'Scholarships page lists a December 15 priority deadline for the International Tuition Award and International Book Award; the international checklist also says transcripts, test results and admission by January 15 are needed for fall scholarship consideration. Year is not printed; treated as the 2026-27 cycle.', '9010bb4d-84ed-5d93-95e3-093855d5c347'),
 ('7cba06ab-fcc4-5279-9d5f-8c66656b9480', 'db5a2994-d21a-58ef-b5e1-3a1edba1c366', '2026-27', 'application', 'International undergraduate application deadline, fall 2027', '2027-06-01', 'Listed as the international fall deadline on both the deadlines page and the International Admissions page (domestic first-time freshmen: August 7). No year is printed; treated as fall 2027. The spring international deadline is November 1 and summer April 1.', '199cc72d-5c22-53c6-87f0-c473eda6190c');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('db5a2994-d21a-58ef-b5e1-3a1edba1c366', 'required_nonnative', 'Meet one: ACT English 18, SAT EBRW 500, TOEFL iBT 4.5, IELTS 6.5, PTE Academic 50, Duolingo 100, or prior credit in a regionally accredited college-level general-education English course. TOEFL/IELTS/Duolingo are not required for undergraduates from a list of English-speaking countries (including Canada excluding Quebec, Ghana, Jamaica, Nigeria, New Zealand, the U.K.) or for applicants who completed high school or college work in the U.S. Applicants who do not meet the English requirement can be admitted conditionally through the Intensive English Language Program (IELP); completing IELP classes and passing its exit exam means no TOEFL is needed, but math scores must still be submitted before full admissibility.', '56b55221-70ec-51cf-a95d-d56325703411');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
select 'db5a2994-d21a-58ef-b5e1-3a1edba1c366'::uuid, 'required_option', '56b55221-70ec-51cf-a95d-d56325703411'::uuid, v.* from (values
 ('TOEFL_IBT_2026', 4.5, 'The requirements page lists ''TOEFL iBT 4.5'', which is on the new 1-6 band scale; no 0-120 minimum is given on the current page. LSU New Orleans'' ETS institution code is 6379.'),
 ('IELTS', 6.5, null),
 ('DUOLINGO', 100, 'Undergraduate minimum 100 (graduate 105).'),
 ('PTE', 50, 'PTE Academic.')) v;
