insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, pct_submit_sat, pct_submit_act, notes, source_id, source_note) values
 ('6d11d793-09df-5f24-bcb0-8111bfb037a2', '2024-2025', 4197, 3667, 533, 17, 3, 'Baseline from IPEDS (fall 2024 entering class): no Niagara Common Data Set could be found online (searches and the institutional-effectiveness page turned up none). Counts are IPEDS ADM values (4,197 applied, 3,667 admitted = 87.4%, 533 enrolled). College Navigator reports 26% of undergraduates as U.S. nonresident (no headcount). SAT/ACT percentiles come from only 91 SAT and 14 ACT submitters (17% and 3% of enrolled first-years), so treat them as indicative; no SAT total or 50th percentiles are published. GPA, residency and international applicant splits are not available.', '2d0a59dd-9a43-5665-8f48-3acbd5ccb9a4', 'admissions_site');
insert into test_score_percentiles (institution_id, cds_year, source_id, test, p25, p75)
