insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('6d11d793-09df-5f24-bcb0-8111bfb037a2', '2026-27', 'optional', 'Niagara has a test-optional admissions policy for first-year applicants that covers all majors and merit scholarship consideration. If scores are submitted, the best SAT or ACT score is used. Some programs may still ask for scores; confirm with admissions (716-286-8700).', 'bc3fd7e3-f99a-5e02-909e-61c67503392e');
insert into application_requirements (institution_id, cycle, platforms, supplemental_essays, notes, source_id) values
 ('6d11d793-09df-5f24-bcb0-8111bfb037a2', '2026-27', array['common_app','own']::text[], '250-word essay is encouraged, not required.', 'Apply with the Common App or Niagara''s own application. Required: official high school transcript (at least 16 academic units); a teacher/counselor recommendation, a 250-word essay and an activities resume are ''highly encouraged'' but not required. Nursing needs 3 years of high school science including chemistry and biology with at least 80%. Foreign transcripts need a course-by-course NACES evaluation. The application fee is not stated on the pages checked.', 'bc3fd7e3-f99a-5e02-909e-61c67503392e');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('3022f2c9-2a5c-5a80-adfe-dc0923e35850', '6d11d793-09df-5f24-bcb0-8111bfb037a2', '2026-27', 'application', 'ROLLING', 'International (non-Canadian) fall application deadline, fall 2027 entry', '2027-05-01', 'The International Admissions page prints ''May 1'' for fall and ''Nov. 1'' for spring with no year; treated as fall 2027. Niagara reviews on a rolling basis (decisions in about 3-4 weeks after the application is complete); domestic first-year applicants have no deadline.', '112b4961-20b0-50c1-a788-6eab1748c913');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('6d11d793-09df-5f24-bcb0-8111bfb037a2', 'required_nonnative', 'Test waived if English is your native language, you were taught in English at your high school (letter required), you spent one year or more studying in the United States, or you attended a US college or university for a year. Niagara approves only three tests: IELTS, TOEFL and Duolingo.', '112b4961-20b0-50c1-a788-6eab1748c913');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
select '6d11d793-09df-5f24-bcb0-8111bfb037a2'::uuid, 'required_option', '112b4961-20b0-50c1-a788-6eab1748c913'::uuid, v.* from (values
 ('TOEFL_IBT', 79, 'Score required for unconditional acceptance. The page does not give a score for the new 1-6 TOEFL scale.'),
 ('IELTS', 6.0, 'Required for unconditional acceptance.'),
 ('DUOLINGO', 110, 'Required for unconditional acceptance.')) v;
insert into score_codes (institution_id, test_key, notes, source_id)
select '6d11d793-09df-5f24-bcb0-8111bfb037a2'::uuid, v.* from (values
 ('sat', 'No SAT institution code is printed on the admissions pages checked; look it up in the College Board code search.', 'bc3fd7e3-f99a-5e02-909e-61c67503392e'::uuid),
 ('act', 'No ACT code is printed on the admissions pages checked; look it up at act.org.', 'bc3fd7e3-f99a-5e02-909e-61c67503392e'::uuid),
 ('toefl', 'No TOEFL institution code is printed on the international admissions page.', '112b4961-20b0-50c1-a788-6eab1748c913'::uuid),
 ('ielts', 'No institution code is listed.', '112b4961-20b0-50c1-a788-6eab1748c913'::uuid),
