insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, pct_submit_sat, pct_submit_act, notes, source_id, source_note) values
 ('2a67d7ff-13ea-54f1-973f-4549ce8759c1', '2024-2025', 3369, 3059, 1082, 3, 82, 'Baseline from IPEDS (fall 2024 entering class). Nicholls'' Common Data Set page (nicholls.edu/irep/common-data-set/) only lists CDS files through 2018-19, too old to use. Counts from the IPEDS ADM2024 file (via the Urban Institute API mirror): 3,369 applicants, 3,059 admitted, 1,082 enrolled (1,075 full-time + 7 part-time). College Navigator shows 3% submitting SAT (34 students) and 82% submitting ACT (884 students); SAT percentiles rest on a small group. International applicant counts, GPA and class rank are not published.', '704617ed-083f-5c74-a4e8-dacae0da947c', 'admissions_site');
insert into test_score_percentiles (institution_id, cds_year, source_id, test, p25, p50, p75)
select '2a67d7ff-13ea-54f1-973f-4549ce8759c1'::uuid, '2024-2025', '704617ed-083f-5c74-a4e8-dacae0da947c'::uuid, v.* from (values
 ('SAT_ERW', 472, 525, 608),
 ('SAT_MATH', 462, 555, 588),
 ('ACT_COMPOSITE', 19, 21, 24),
 ('ACT_ENGLISH', 19, 22, 25),
 ('ACT_MATH', 17, 20, 24)) v;
insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('2a67d7ff-13ea-54f1-973f-4549ce8759c1', '2026-27', 'optional', 'Nicholls'' admissions page lists a 2.35 overall high school GPA and 2.0 core GPA with the 19-unit core curriculum and no ACT/SAT minimum for standard graduates (it says admissions will work with students who have not taken the ACT); the page does not use the words test-optional. The 2025-26 catalog lists ACT/SAT scores among documents for non-US high school graduates, and the international page uses ACT/SAT (or other tests) to show university-level English and math readiness, so international applicants should expect to send some score. Out-of-state freshmen who miss the GPA/core standard can qualify with ACT 23 / SAT 1130 or ACT 21 / SAT 1060 plus a core GPA, per the catalog.', 'ea2a85db-bcb5-5ea1-bccd-d07b57ff251a');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('2a67d7ff-13ea-54f1-973f-4549ce8759c1', '2026-27', array['own']::text[], 30, 'Fee conflict: the international freshman page says a $30 processing fee paid with the online application; the 2025-26 catalog lists a $20 application fee (and $30 late fee) with no separate international fee. International freshman documents: Summary of Educational Background by Years form, official secondary transcripts sent directly by the school with official English translation, Affidavit of Support plus bank statement, immunization form (needed for enrollment), housing application and ACT/SAT scores (catalog). High school GPA minimum 2.35. Nicholls does not charge international students out-of-state fees.', '46ece0da-6a97-557b-87f9-e69d72a6a3c6');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('7ed7807e-a814-57ea-8a1a-f2cc3f5b6e96', '2a67d7ff-13ea-54f1-973f-4549ce8759c1', '2026-27', 'application', 'RD', 'International fall 2027 application deadline', '2027-04-15', 'International deadlines are April 15 (fall) and October 15 (spring); later applications move to the next semester. Domestic priority dates (July 25 fall, December 15 spring) do not apply to international applicants. Years are not printed on the pages; April 15 is taken as 2027 for fall 2027 entry.', '46ece0da-6a97-557b-87f9-e69d72a6a3c6'),
 ('ff626d59-0ac2-524a-8141-53c3c29dc3ef', '2a67d7ff-13ea-54f1-973f-4549ce8759c1', '2026-27', 'scholarship', null, 'Academic scholarship materials (priority)', '2027-01-31', 'Scholarships page: application materials including ACT scores and transcripts are due by January 31 of the senior year (no year printed; taken as 2027). The page does not say whether international students are eligible.', 'e4d6a03b-6a03-5821-a4c7-ac8daa7eb88f');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('2a67d7ff-13ea-54f1-973f-4549ce8759c1', 'required_nonnative', 'Waived for students from countries where English is the native language (list linked from the page); also satisfied by a US high school diploma. University-level English can also be shown with SAT EBRW 500, ACT English 18, ACCUPLACER Next-Generation Writing 250 or ELS level 112 completion. The catalog and international pages mention no ESL pathway or conditional admission.', '46ece0da-6a97-557b-87f9-e69d72a6a3c6');
