select '2a67d7ff-13ea-54f1-973f-4549ce8759c1'::uuid, 'required_option', '46ece0da-6a97-557b-87f9-e69d72a6a3c6'::uuid, v.* from (values
 ('TOEFL_IBT', 80, 'The page prints ''TOEFL: 4.0 (80)''.'),
