insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('8db12264-f605-5e09-813c-7b1b398aa789', '2026-27', 'optional', 'UNA is test optional: students can apply with or without ACT/SAT; scores are encouraged for scholarships and course placement. International students are not required to submit SAT/ACT for admission; applicants without scores take UNA''s Academic Placement Test before registering. Freshman admission generally needs a 2.5 unweighted GPA and 13 core high school units (2.00-2.49 may be considered for conditional admission).', '82bb9dec-ff7b-5b03-b4fb-a052d0b1a339');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('8db12264-f605-5e09-813c-7b1b398aa789', '2026-27', array['own']::text[], 35, 'International applicants pay a non-refundable $35 fee (no waivers, no wire transfers). Required: passport copy, official high school diploma and transcripts (notarized or attested), financial documents for the I-20 (bank letter or statements dated within six months), and an English proficiency test. The international admissions page does not state a minimum GPA; the domestic freshman page says 2.5 unweighted. External credential evaluation (IEE, WES, TEC) is requested case by case. UNA also offers an on-campus Academic English Program (ESL); conditional admission needs two applications, one to the ESL program and one to the degree program.', '82bb9dec-ff7b-5b03-b4fb-a052d0b1a339');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('9677cfe0-8cee-5af7-99e3-ad7eea6bcc6d', '8db12264-f605-5e09-813c-7b1b398aa789', '2026-27', 'application', 'ROLLING', 'International application deadline, fall semester (fall 2027 entry)', '2027-06-01', 'Page says ''Fall Semester: June 1'' (application and all supplemental materials due before June 1). The page prints no year, so treated as 2027. Spring semester deadline is October 1. The CDS reports no application closing date and rolling notification.', 'f7ba43e0-7c12-5c8f-a59b-528cefe280b2');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('8db12264-f605-5e09-813c-7b1b398aa789', 'required_nonnative', 'English proficiency is required of all international students, met either with a test score or through UNA''s Academic English (ESL) Program. The FAQ says a medium-of-instruction (MOI) document can be accepted, and applicants who completed a US-equivalent diploma or degree in English in a listed country (e.g. Australia, Canada except Quebec, Ireland, Jamaica, Kenya, Nigeria, Singapore, South Africa, UK, Zimbabwe) may be exempt from TOEFL/IELTS.', 'f7ba43e0-7c12-5c8f-a59b-528cefe280b2');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
select '8db12264-f605-5e09-813c-7b1b398aa789'::uuid, 'required_option', '82bb9dec-ff7b-5b03-b4fb-a052d0b1a339'::uuid, v.* from (values
 ('TOEFL_IBT', 61, 'UNA ETS code 1735. TOEFL computer-based 173 and TOEIC 600 are also listed. The page gives no minimum on the new 1-6 TOEFL scale.'),
 ('IELTS', 5.5, null),
 ('DUOLINGO', 90, null),
 ('PTE', 46, null)) v;
