insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('46f01fa0-44bc-5759-9b68-e4c7bad0cd91', '2026-27', 'optional', 'SAT/ACT are optional. Bachelor''s admission: either an unweighted 3.0 GPA in the Required High School Curriculum (GPA only, no scores needed), or a 2.4+ GPA with SAT EBRW 480+ and Math 440+ (or ACT English/Reading 17+ and Math 17+) and a freshman index of 2200+ (SAT FI = 500 x GPA + 1.06 x (EBRW + Math) - 74). Associate pathway needs a 2.0 GPA; applicants who miss bachelor''s criteria are automatically considered for an associate pathway. International applicants must also meet these traditional freshman criteria.', 'c0c54b60-89c8-509c-8045-2a846d2670cf');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('46f01fa0-44bc-5759-9b68-e4c7bad0cd91', '2026-27', array['own']::text[], 40, 'Apply through GAFutures: $40 non-refundable fee, online or on paper. International transcripts need a document-by-document evaluation from a NACES or AICE member sent directly to UNG (a GPA calculation is not required). English proficiency scores must come from the testing agency. After admission, request an I-20 from the Center for Global Engagement; proof of about $43,000 in funds is needed for a bachelor''s degree. Essays and recommendations are not mentioned.', 'bf1105eb-4eef-56ff-96e5-f07e73fa3be6');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('ae1d163a-3a6b-56bf-9db8-e551b2cdc93f', '46f01fa0-44bc-5759-9b68-e4c7bad0cd91', '2026-27', 'application', 'ROLLING', 'International application and all supporting documents (fall 2027 entry)', '2027-05-01', 'International column of the deadline table: Fall May 1, Spring Nov. 1, no summer; applications and all supporting documents are due on that date (not available at the Blue Ridge campus or online). Year not printed; treated as fall 2027. UNG warns it will likely reach capacity before a deadline and stop accepting applications, so apply early.', '59d6af48-2b3a-59e0-bbdd-eb9d65661b10');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('46f01fa0-44bc-5759-9b68-e4c7bad0cd91', 'required_nonnative', 'Non-native speakers must submit an approved English proficiency score. A waiver applies after a secondary or college degree where English was the official language of instruction, or after English 1101/1102 with a C or better at a US institution. Bachelor''s-degree minimums are listed (associate pathway is lower: TOEFL iBT 69 / 3.5 new scale, IELTS 6.0, PTE 53, Cambridge 169). Other accepted routes: SAT EBRW 480 or ACT English or Reading 17, Accuplacer Reading 243 + WritePlacer 4, Michigan English Test 59 (bachelor''s), EIKEN Pre-1, IGCSE/GCSE/A-level English, or completion of an approved USG campus-based ESL program. Duolingo is not listed. Scores are valid 2 years.', 'bf1105eb-4eef-56ff-96e5-f07e73fa3be6');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
select '46f01fa0-44bc-5759-9b68-e4c7bad0cd91'::uuid, 'required_option', 'bf1105eb-4eef-56ff-96e5-f07e73fa3be6'::uuid, v.* from (values
 ('TOEFL_IBT', 79, 'Bachelor''s degree; for tests taken before 2026. Includes Home Edition and MyBest. Associate pathway minimum is 69.'),
 ('TOEFL_IBT_2026', 4.0, 'Bachelor''s degree; tests taken in 2026 or later (the page lists 4.0 without naming the 1-6 scale). Associate pathway minimum is 3.5.'),
 ('IELTS', 6.5, 'Bachelor''s degree, IELTS Academic (including Online). Associate pathway minimum is 6.0.'),
 ('PTE', 58, 'Bachelor''s degree, conventional and online. Associate pathway minimum is 53.'),
 ('CAMBRIDGE', 177, 'Cambridge English Scale score (B2 First, C1 Advanced or C2 Proficiency), bachelor''s degree. Associate pathway minimum is 169.')) v;
insert into score_codes (institution_id, test_key, code, notes, source_id)
