insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('14a7a9f5-0010-5198-8dd7-6ba0829052dc', '2026-27', 'recommended', 'The Admission Requirements page lists three routes (any one is enough): 2.70 four-year GPA with upper-50% class rank, 2.7 GPA in the 15 required courses, or ACT 20+ (or an SAT equivalent from a concordance table), and says applicants should have taken the ACT or a similar test. An older admissions FAQ mentions a test-optional pilot for students with a 2.7 GPA; scholarships still need scores. The international admissions page does not mention SAT/ACT.', '85ac2f88-d66c-5219-8eea-1f7a5586fc60');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, fee_waiver, notes, source_id) values
 ('14a7a9f5-0010-5198-8dd7-6ba0829052dc', '2026-27', array['own']::text[], 25, false, 'Online NSU application; $25 non-refundable fee, no fee waivers. International applicants send sealed official transcripts (at least 3 years of high school, with a 4.0-scale GPA) to the Office of International Programs and must show funds for the first year before an I-20/DS-2019 is issued (financial statement form, documents dated within 3 months). College credit earned outside the U.S. needs a WES or ECE course-by-course evaluation to transfer. Required high school units: 15 (4 English, 3 lab science, 3 math, 3 history/citizenship, 2 other).', '9d5bbdda-1e43-5e6b-b561-fa76724f8eb1');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('d9c2169e-03a0-5725-93b6-281e617b89ce', '14a7a9f5-0010-5198-8dd7-6ba0829052dc', '2026-27', 'application', 'ROLLING', 'International application deadline, fall semester (fall 2027 entry)', '2027-07-01', 'Admission Deadlines on the international page: Fall July 1, Spring Nov. 1; no summer or other international-specific date. The page prints no year, so fall 2027 is assumed.', '9d5bbdda-1e43-5e6b-b561-fa76724f8eb1'),
 ('45d6a5b1-b4e9-51c5-a8d7-d3b2299d206f', '14a7a9f5-0010-5198-8dd7-6ba0829052dc', '2026-27', 'scholarship', null, 'International incoming-student scholarship deadline, fall (fall 2027)', '2027-07-01', 'Presidential (3.75 GPA), Academic Excellence (3.0) and International Freshmen (2.75) scholarships; fall deadline July 1, spring Nov. 1; applications go to international@nsuok.edu.', '8d6e7aea-a709-557d-8151-3b891f5213c7'),
 ('4e4e693a-b340-5870-bed5-94af6fa9a318', '14a7a9f5-0010-5198-8dd7-6ba0829052dc', '2026-27', 'scholarship', null, 'Non-resident 50% tuition waiver, fall 2027 starters', '2027-08-01', 'Summer starters June 1, fall starters Aug. 1 (Spring 2027 starters Jan. 1). Incoming freshmen need a 3.0 minimum GPA and must live on campus (exceptions for legacy students).', '8d6e7aea-a709-557d-8151-3b891f5213c7'),
 ('8462e05b-1067-538e-b6d8-44e06d19edbb', '14a7a9f5-0010-5198-8dd7-6ba0829052dc', '2026-27', 'scholarship', null, 'General Foundation Scholarship final deadline (new international students, 2027-2028)', '2027-05-01', 'Priority College Committee deadline March 1, 2027; final General Committee deadline May 1, 2027.', '8d6e7aea-a709-557d-8151-3b891f5213c7');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('14a7a9f5-0010-5198-8dd7-6ba0829052dc', 'required_nonnative', 'One of TOEFL, IELTS, PTE Academic or iTEP Academic is required for international applicants; applicants with more than 24 credit hours at a U.S. university are exempt. The page mentions no Duolingo or Cambridge option, no conditional admission and no ESL pathway.', '9d5bbdda-1e43-5e6b-b561-fa76724f8eb1');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
select '14a7a9f5-0010-5198-8dd7-6ba0829052dc'::uuid, 'required_option', '9d5bbdda-1e43-5e6b-b561-fa76724f8eb1'::uuid, v.* from (values
 ('TOEFL_IBT', 61, 'Institution code 6485. The page does not give the new 1-6 scale.'),
 ('IELTS', 5.5, 'IELTS Academic.'),
 ('PTE', 44, 'PTE Academic. iTEP Academic 3.5 is also accepted (no separate field here).')) v;
insert into score_codes (institution_id, source_id, test_key, code, notes)
select '14a7a9f5-0010-5198-8dd7-6ba0829052dc'::uuid, '9d5bbdda-1e43-5e6b-b561-fa76724f8eb1'::uuid, v.* from (values
 ('sat', null, 'The international admissions page does not print an SAT code; look it up in the College Board code search.'),
 ('act', null, 'No ACT code is printed on the pages read; look it up at act.org.'),
 ('toefl', '6485', 'NSU TOEFL institution code; official report can also be mailed to 600 N Grand Avenue, Tahlequah, OK 74464.'),
 ('ielts', null, 'No institution code is listed.'),
 ('duolingo', null, 'Duolingo is not listed as an accepted test on the page read.'),
 ('pte', null, 'No institution code is listed.')) v;
insert into cost_aid (institution_id, year, tuition_out_of_state_usd, tuition_intl_usd, intl_extra_fees_usd, room_board_usd, books_usd, total_coa_usd, intl_aid_policy, intl_need_aid, meets_full_need, merit_scholarships, notes, source_id) values
 ('14a7a9f5-0010-5198-8dd7-6ba0829052dc', '2026-2027', 18368, 18368, 300, 9020, 800, 29538, 'merit_only', false, false, true, 'NSU''s 2026-27 F-1/J-1 estimate: tuition and fees (out-of-state, 30 credit hours) $18,367.50, international fees $300 (plus a one-time $50 orientation fee), health insurance about $1,000, books $800, housing and food $9,020; estimated total $29,537.50 (rounded to dollars here; the total includes the insurance and one-time fee). Non-resident tuition is $334.25 per undergraduate credit hour. The in-state rate is not on the pages read (College Navigator 2024-25: $7,810 in-state, $17,290 out-of-state).; One-year international scholarships by GPA: Presidential (3.75) $2,000-$5,000, Academic Excellence (3.0) $1,000-$2,000, International Freshmen (2.75) $500-$1,000; applicants need a 2.75 GPA and full degree-program admission. A non-resident 50% tuition waiver (half of the $334.25 per-credit non-resident tuition) requires a 3.0 GPA for freshmen and living on campus. The 2024-2025 CDS (H6) reports no institutional aid awarded to nonresidents that year (0 recipients), so published awards are competitive and not guaranteed.', '9d5bbdda-1e43-5e6b-b561-fa76724f8eb1');
