 ('df77d05b-b631-55bf-9d35-2452aacd83cf', '686653c1-e590-55bd-8477-28552c9b3669', '2026-27', 'application', 'EA', 'Early Action', '2026-11-01', '2027-02-15', 'Non-binding. Notification ''by February 15''.', '989fcffa-a995-54f3-a17b-50261d08a21f'),
 ('b52dabf6-2d7c-5a31-8395-e114496463c1', '686653c1-e590-55bd-8477-28552c9b3669', '2026-27', 'application', 'ED2', 'Early Decision II', '2027-01-01', '2027-03-01', 'Binding. Notification ''by March 1''.', '989fcffa-a995-54f3-a17b-50261d08a21f'),
