insert into cost_aid (institution_id, year, tuition_usd, room_board_usd, books_usd, other_usd, total_coa_usd, intl_aid_policy, intl_need_aid, meets_full_need, merit_scholarships, notes, source_id) values
 ('686653c1-e590-55bd-8477-28552c9b3669', '2023-2024', 69289, 22048, 1000, 1800, 88412, 'merit_only', false, false, true, 'College Scorecard (IPEDS 2023-24): tuition includes required fees; on-campus cost of attendance.; International students are not eligible for need-based aid (institutional grants or federal aid). They are eligible for merit scholarships, which are extremely competitive and do not cover the full cost of attendance; the admission application serves as the scholarship application.', 'd38c51ad-3485-54b9-be43-63e50395bbc7');
