 ('TOEFL_IBT', 72, '{"listening": 16, "reading": 16, "speaking": 18, "writing": 18}'::jsonb, 'Exams taken before 2026-01-20.'),
 ('TOEFL_IBT_2026', 4, '{"listening": 3.5, "reading": 3.5, "speaking": 3.5, "writing": 4}'::jsonb, 'Exams taken on or after 2026-01-20; the page lists these values without naming the 1-6 scale.'),
 ('IELTS', 6.0, '{"each_section": 5.5}'::jsonb, null),
 ('CAMBRIDGE', 169, '{"use_of_english": 160, "reading": 162, "writing": 162, "listening": 162, "speaking": 162}'::jsonb, 'B2 First.')) v;
