insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('aa657be8-4ecf-5b66-b69d-81f91cc59e1c', '2026-27', 'optional', 'International first-year applicants do not need SAT or ACT; scores may be considered for scholarships (International Scholars Award can use SAT 1020+ instead of a 3.0 GPA). CDS C8 lists SAT/ACT as ''considered if submitted''; the University''s Presidential Scholar award uses ACT 29+/SAT 1340+.', '0efa8b37-0854-50be-b343-185814808dd7');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('aa657be8-4ecf-5b66-b69d-81f91cc59e1c', '2026-27', array['common_app','own']::text[], 50, 'International first-year file: application, $50 non-refundable fee, high school transcripts (unofficial accepted for admission, official required later), English test scores and financial documents. Apply with the UNI International Application or the Common App; a paper application is also accepted. Domestic application fee is $40 (CDS C13). Essay, recommendations and interview are not listed as required for international applicants.', '0efa8b37-0854-50be-b343-185814808dd7');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('f14aa9e6-bcb2-59f5-8868-fb598cb82d69', 'aa657be8-4ecf-5b66-b69d-81f91cc59e1c', '2026-27', 'application', 'ROLLING', 'International application (fall 2027 entry): rolling', null, 'UNI admits on a rolling basis with no strict deadline for undergraduates; applying early is encouraged so a visa appointment can be secured before the semester starts. Spring 2027 and fall 2027 intakes are both mentioned on the scholarships page. The FAQ gives no decision-time promise for undergraduates.', 'f08aff59-c430-55b1-9f02-0e98b40d2431'),
 ('52bc85ee-45ba-5835-92ca-2cc8af3c15e5', 'aa657be8-4ecf-5b66-b69d-81f91cc59e1c', '2026-27', 'scholarship', null, 'UNI Scholarship Application priority deadline', '2027-02-01', 'The application opens July 1 and the page prints no year; taken as Feb. 1, 2027. Applicants must be admitted first. The International Scholars Award ($2,000-$5,000/yr) needs no application.', '8a5e7a08-46eb-5c5c-bee5-528d80a87c5c');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('aa657be8-4ecf-5b66-b69d-81f91cc59e1c', 'required_nonnative', 'Proof of English is required of undergraduate non-native speakers. Alternatives to a test include SAT EBRW 480+, ACT English 20+, IB English A1/A2 grade 4-7 (HL or SL), AP English Language 4-5, IGCSE/GCE A-level English grade A-C, MET 57+, Manchester Exam 400+, UNI CIEP completion certificate, or 24+ transferable semester hours from a regionally accredited U.S. college. Students without proof can be admitted conditionally and take the Culture and Intensive English Program (CIEP) on campus after a placement exam, with no separate CIEP application.', '71d136df-e70a-5d92-9737-2581fa05660d');
insert into english_requirements (institution_id, source_id, test_key, status, min_total, notes)
select 'aa657be8-4ecf-5b66-b69d-81f91cc59e1c'::uuid, '71d136df-e70a-5d92-9737-2581fa05660d'::uuid, v.* from (values
 ('TOEFL_IBT', 'required_option', 79, 'Unrestricted (full) admission. English Pathway Program admits at TOEFL 61 (admission-policies page says 61-78): students take special credit-bearing course sections in their first semester. The 1-6 new-scale minimum is not given.'),
 ('IELTS', 'required_option', 6.0, 'Academic overall band; IELTS Indicator also accepted. English Pathway Program: 5.5.'),
 ('DUOLINGO', 'required_option', 105, 'English Pathway Program: 95 (admission-policies page says 95-100).'),
 ('PTE', 'required_option', 52, 'For unrestricted admission.'),
 ('CAMBRIDGE', 'accepted', 169, 'Certificate in C1 Advanced score of 169 or higher, for unrestricted admission.')) v;
