insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('7a6abe7a-cbd8-507c-9228-8c111eec70aa', '2026-27', 'optional', 'NKU directly admits high school seniors with an unweighted GPA of 2.75 or higher (fall 2026 page); the page does not mention test scores. CDS 2023-2024 C8F says ACT/SAT are required for under-21 applicants below a 2.75 GPA, and select programs may require them. International freshmen must submit ONE of TOEFL, IELTS, PTE Academic, SAT or ACT as English proof, so a test report is effectively needed (SAT/ACT can serve as that proof).', '5cd0476a-3875-5837-afc2-494991625599');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('7a6abe7a-cbd8-507c-9228-8c111eec70aa', '2026-27', array['own']::text[], 44, 'International application fee is $44 (non-refundable, paid after submitting the NKU undergraduate online application; the AELP fee is a separate $55). Required: passport copy, official transcripts from all secondary schools (certified English translation), official English test report. Common App use not confirmed on the pages read. Nursing, Health Science, Radiologic Technology, Radiation Therapy and Respiratory Care have higher standards; Music needs an audition.', '262d2ef5-ebf6-58f5-aa58-b237267fc715');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('fc855fe7-e847-5671-b747-991cefbeadcd', '7a6abe7a-cbd8-507c-9228-8c111eec70aa', '2026-27', 'application', 'ROLLING', 'Final overseas application deadline, fall intake (fall 2027 entry)', '2027-04-15', 'Page prints no year; treated as fall 2027. Applications must come with all required documents. NKU admits on a rolling basis (CDS: notification begins mid-August for the fall 2023 cycle). Spring intake: final overseas application Oct. 15.', '262d2ef5-ebf6-58f5-aa58-b237267fc715'),
 ('7f509142-eac4-54ed-865d-b1ddb95ac42b', '7a6abe7a-cbd8-507c-9228-8c111eec70aa', '2026-27', 'other', null, 'Undergraduate confirmation deadline (fall intake)', '2027-05-01', 'Page prints no year; treated as fall 2027. Spring-intake confirmation is Oct. 22.', '262d2ef5-ebf6-58f5-aa58-b237267fc715'),
 ('e000e22b-0dac-5480-a836-6cb0d31b2207', '7a6abe7a-cbd8-507c-9228-8c111eec70aa', '2026-27', 'other', null, 'Final overseas I-20 request deadline (fall intake)', '2027-05-15', 'Page prints no year; treated as fall 2027. Needs the I-20 request form and valid financial documents. Spring-intake I-20 request: Nov. 1.', '262d2ef5-ebf6-58f5-aa58-b237267fc715');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('7a6abe7a-cbd8-507c-9228-8c111eec70aa', 'required_nonnative', 'All non-native English speakers must send official English proficiency scores. International freshmen submit ONE of TOEFL, IELTS, PTE Academic, SAT or ACT. Full admission without restrictions needs TOEFL iBT 79 (reading 14+), IELTS 6.5 (reading 5.5+, writing 5+), PTE 55, or SAT EBRW 480+ (or Writing and Language 25+ and Reading 26+) or ACT English 18 and Reading 20. Lower scores (TOEFL iBT 61, IELTS 5.5 with reading and writing 5+, PTE 44 with reading 42+) give admission with restrictions: placement tests in each deficient area before registering. Applicants below those can get conditional admission through the American English Language Program (full admission there needs IELTS 5.5 or TOEFL iBT 61; students below that start in AELP, levels 1-6).', '262d2ef5-ebf6-58f5-aa58-b237267fc715');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, recommended_total, notes)
select '7a6abe7a-cbd8-507c-9228-8c111eec70aa'::uuid, 'required_option', '262d2ef5-ebf6-58f5-aa58-b237267fc715'::uuid, v.* from (values
 ('TOEFL_IBT', 61, 79, '61 = admission with restrictions (placement tests before registering); 79 with reading 14+ = full admission without restrictions. Paper TOEFL 550 (reading 48) full / 500 restricted. School code 1574.'),
 ('IELTS', 5.5, 6.5, '5.5 with reading and writing 5+ = admission with restrictions; 6.5 with reading 5.5+ and writing 5+ = full admission.'),
 ('PTE', 44, 55, '44 with reading 42+ = admission with restrictions; 55 = full admission.')) v;
insert into score_codes (institution_id, source_id, test_key, code, notes)
select '7a6abe7a-cbd8-507c-9228-8c111eec70aa'::uuid, '262d2ef5-ebf6-58f5-aa58-b237267fc715'::uuid, v.* from (values
 ('sat', '1574', 'NKU SAT school code per the international admissions page.'),
 ('act', '1566', 'NKU ACT school code per the international admissions page.'),
 ('toefl', '1574', 'NKU TOEFL school code per the international admissions page.'),
 ('ielts', null, 'No institution code is listed; send IELTS results to NKU electronically.'),
 ('duolingo', null, 'Duolingo is not listed among NKU''s accepted undergraduate tests.'),
 ('pte', null, 'No institution code is listed.')) v;
insert into cost_aid (institution_id, year, tuition_out_of_state_usd, tuition_intl_usd, required_fees_usd, room_board_usd, books_usd, other_usd, total_coa_usd, intl_need_aid_awarded, intl_avg_award_usd, meets_full_need, notes, source_id) values
 ('7a6abe7a-cbd8-507c-9228-8c111eec70aa', '2025-2026', 15000, 15000, 850, 12314, 900, 1786, 30850, 298, 15100, false, 'NKU international costs page, standard rate: $625 per credit hour, $7,500 per semester (12+ credits); fees $850 (vary by program); residence hall $7,360 + meal plan $4,954 (typical); books $900; required health insurance $1,786; estimate $30,850. A lower $463/credit rate applies only to F-1 students graduating from Kentucky, Ohio or Indiana high schools. 2026-27 rates not yet posted.; CDS 2023-2024 H6: 298 undergraduate degree-seeking nonresidents received institutional aid, average $15,100 (total $4,499,790); the CDS does not say whether it was need- or non-need-based. CDS G1 tuition fields were not readable; tuition and fees come from NKU''s international costs page.; NKU''s international admission and cost pages publish no scholarship amounts for new international freshmen; the international-student scholarship page only lists awards for current NKU students (e.g. Weiss $500). CDS 2023-2024 H6 shows 298 nonresident undergraduates received institutional aid (average $15,100), so institutional aid exists but the program is not published; ask isss@nku.edu.', '1977ad45-e1fa-57bd-bc72-818311160faa');
insert into institution_tiers (institution_id, tier_code, category_key, rationale)
select '7a6abe7a-cbd8-507c-9228-8c111eec70aa'::uuid, 'D', v.* from (values
