insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, pct_submit_sat, pct_submit_act, notes, source_id, source_note) values
 ('16c61149-77aa-5b8c-9cde-09aac5d51eeb', '2023-2024', 1082, 1004, 319, 1, 82, 'Baseline from IPEDS (fall 2023 entering class, ADM2023); no Common Data Set is published on NSU''s Institutional Research page (checked 2026-10-26). College Navigator also shows fall 2024: 1,086 applicants, 93% admitted (exact admit count not given). SAT percentiles are not listed because only 2 enrolled students (1%) submitted SAT scores; the ACT percentiles rest on 260 students (82%). International applicant and admit counts, GPA distribution and SAT total are not available from IPEDS.', '8bcef37f-b717-5a5e-aa4c-32cfb2d6d2b5', 'admissions_site');
insert into test_score_percentiles (institution_id, cds_year, source_id, test, p25, p50, p75)
select '16c61149-77aa-5b8c-9cde-09aac5d51eeb'::uuid, '2023-2024', '062d977a-edba-5d10-b10d-1017a7463a05'::uuid, v.* from (values
 ('ACT_COMPOSITE', 18, 21, 24),
 ('ACT_ENGLISH', 16, 20, 23),
 ('ACT_MATH', 17, 21, 25)) v;
insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('16c61149-77aa-5b8c-9cde-09aac5d51eeb', '2026-27', 'optional', 'ACT or SAT is not required. Applicants can be admitted with any one of: ACT 18 (SAT 960), a high school GPA of 2.6, or top 60% of the graduating class (the international page prints SAT 970 instead of 960). The international page lists SAT/ACT among the tests that can be sent in place of an English test. Some scholarships (WolfPACT) use ACT/SAT scores but also have a no-score track.', 'f579e578-6616-5552-97b7-c7c1d7a165d4');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('16c61149-77aa-5b8c-9cde-09aac5d51eeb', '2026-27', array['own']::text[], 25, 'International degree-seeking first-year file: online application with $25 non-refundable fee, high school transcript/marks sheet (certified English translation if needed; mailed official transcripts required upon admission), one test score (English test or SAT/ACT), passport page, Declaration of Finances form with bank statement, immunization form. Essay and recommendations are not listed. The IPEDS undergraduate application fee for 2024-25 was $20. After admission the student gets an I-20 and F-1 visa instructions.', '647b9183-043b-5be1-863c-50fad49517f0');
insert into deadlines (id, institution_id, cycle, kind, label, due_date, notes, source_id) values
 ('ac8fae79-43f5-5b6b-bc83-0c7fdbea0ff2', '16c61149-77aa-5b8c-9cde-09aac5d51eeb', '2026-27', 'application', 'International application (fall 2027 entry): no deadline published', null, 'Neither the international students page nor the undergraduate requirements page prints an application deadline or a decision timeline. Apply early enough to get an I-20 and an F-1 visa appointment before the semester.', '647b9183-043b-5be1-863c-50fad49517f0'),
 ('e6172bc2-6e7e-576b-a5a5-cde7bedc0684', '16c61149-77aa-5b8c-9cde-09aac5d51eeb', '2026-27', 'scholarship', 'WolfPACT scholarship priority deadline (first-year, fall 2027)', '2027-03-01', 'The page prints ''Priority deadline: March 1'' without a year; taken as March 1, 2027. No separate application: send the admission application, fee, high school transcript and ACT/SAT scores (scores optional for the no-score track) for an official award notice.', '33d527b8-922d-5043-94e2-721a1d40092a');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('16c61149-77aa-5b8c-9cde-09aac5d51eeb', 'required_nonnative', 'The international page asks for one of: TOEFL iBT, IELTS, Duolingo, SAT 970+ or ACT 18+, so a qualifying SAT/ACT can stand in for an English test. The factsheet (titled 2023/2024) says the English score is not required for applicants from English-speaking countries; the current page names no country list. No ESL or conditional-admission pathway is mentioned on the pages read. Nursing (BSN) sets higher English minimums for non-native speakers.', '647b9183-043b-5be1-863c-50fad49517f0');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
select '16c61149-77aa-5b8c-9cde-09aac5d51eeb'::uuid, 'required_option', '647b9183-043b-5be1-863c-50fad49517f0'::uuid, v.* from (values
 ('TOEFL_IBT', 61, 'The page prints ''TOEFL IBT (61-70 or above)''; the exact threshold inside that range is not stated, and 61 is the lowest figure printed (the factsheet says 61 or higher). Nursing BSN: 84 with Speaking 26 (exams before 2026-01-21); for exams on/after 2026-01-21 on the 1-6 scale, 4.5 overall with Speaking 5.0. The general-program minimum on the 1-6 scale is not published. Institution code 6487 per the page.'),
 ('IELTS', 5.5, 'Nursing BSN: 6.5 overall with at least 6.0 in each module.'),
 ('DUOLINGO', 90, 'Nursing BSN: 110.')) v;
insert into score_codes (institution_id, test_key, code, notes, source_id)
select '16c61149-77aa-5b8c-9cde-09aac5d51eeb'::uuid, v.* from (values
 ('sat', '6487', 'SAT school code per the international and undergraduate requirements pages.', '647b9183-043b-5be1-863c-50fad49517f0'::uuid),
 ('act', null, 'NSU''s pages give two different ACT codes (3916 on the requirements page, 3169 on the international page); confirm with NSU before sending.', 'f579e578-6616-5552-97b7-c7c1d7a165d4'::uuid),
 ('toefl', '6487', 'The international page prints school code 6487 next to TOEFL iBT.', '647b9183-043b-5be1-863c-50fad49517f0'::uuid),
 ('ielts', null, 'No institution code is listed.', '647b9183-043b-5be1-863c-50fad49517f0'::uuid),
 ('duolingo', null, 'No institution code is listed.', '647b9183-043b-5be1-863c-50fad49517f0'::uuid)) v;
insert into cost_aid (institution_id, year, tuition_usd, tuition_out_of_state_usd, room_board_usd, merit_scholarships, merit_separate_app, notes, source_id) values
 ('16c61149-77aa-5b8c-9cde-09aac5d51eeb', '2026-2027', 10077, 12379, 11274, true, false, '2026-27 yearly estimates for 30 credit hours: tuition and fees combined $10,077 resident (includes new freshmen from the listed South Dakota Advantage states) and $12,379 out-of-state; housing $6,300 (average residence hall) plus food $4,974 (21 meals/week) = $11,274. The page does not say which rate international students pay, though the factsheet (titled 2023/2024) lists a $200 per-semester international student fee and ~$1,316 health insurance on top of tuition; current amounts are not confirmed. Out-of-state per-credit tuition is $376.40.; The WolfPACT merit scholarship (4-year totals from $4,000 for a 3.00-3.49 GPA with no/low test score, up to $16,000 for a 3.75+ GPA with ACT 28+/SAT 1300+; 3.0 GPA to renew) needs no separate application. The current WolfPACT page says ''all first-year students'' without naming international students; the factsheet (titled 2023/2024) says WolfPACT is available to international degree-seekers and points to patrick.woods@northern.edu for other awards. Whether international students can receive need-based aid is not stated on the pages read.', 'f35ad33e-ae21-5d81-8455-cf7dfb1ee3d2');
insert into institution_tiers (institution_id, tier_code, category_key, rationale)
select '16c61149-77aa-5b8c-9cde-09aac5d51eeb'::uuid, 'D', v.* from (values
 ('general', 'Admit rate 92.8%'),
 ('business', 'Editorial judgment (v1, reviewed 2026-10-20)'),
 ('biology_life_sci', 'Editorial judgment (v1, reviewed 2026-10-20)'),
 ('pre_med', 'Editorial judgment (v1, reviewed 2026-10-20)'),
 ('math_physics', 'Editorial judgment (v1, reviewed 2026-10-20)'),
 ('humanities', 'Editorial judgment (v1, reviewed 2026-10-20)'),
 ('arts_design', 'Editorial judgment (v1, reviewed 2026-10-20)'),
 ('nursing', 'Editorial judgment (v1, reviewed 2026-10-20)')) v;
insert into major_admissions (id, institution_id, program, category_key, admit_model, capped, notes) values
 ('af047097-1c12-5452-9873-d34db8492bb7', '16c61149-77aa-5b8c-9cde-09aac5d51eeb', 'Nursing (BSN)', 'nursing', 'pre_major_competitive', false, 'Apply to NSU as pre-nursing; most students apply to the BSN in sophomore year after prerequisites (min. college GPA 2.7). Direct admission for first-time freshmen with ACT 27+ and HS GPA 3.5+, or HS GPA 3.8+ (keep a 3.0 college GPA). Nursing application window is Aug 15-Sep 30 for fall. Non-native English speakers need TOEFL 84/IELTS 6.5/Duolingo 110 unless exempt. Seat limits are not published on the page.');

