insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('44b758d4-c446-5026-99bc-4dfcadf72d48', '2026-27', 'optional', 'ACT/SAT are optional for international applicants and are not required for admission; if available they may be considered for undergraduate scholarship eligibility.', 'c7897230-d564-5af8-8c99-242fb0c418ef');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('44b758d4-c446-5026-99bc-4dfcadf72d48', '2026-27', array['own']::text[], 0, 'International application has no fee. Needs passport copy, official transcripts (certified, with translations; undergraduate minimum cumulative GPA 2.0 after conversion to the US scale; 5 GCSE/IGCSE/O Level subjects at D or better), and an English score. After acceptance: Statement of Support and a bank statement showing at least $36,858 (the 2025-26 undergraduate estimate on the checklist) before the I-20 is issued. No essay required per the international admissions page.', 'c7897230-d564-5af8-8c99-242fb0c418ef');
insert into deadlines (id, institution_id, cycle, kind, label, due_date, notes, source_id) values
 ('142a0f88-76ad-564c-923f-8756494eef9f', '44b758d4-c446-5026-99bc-4dfcadf72d48', '2026-27', 'application', 'International fall 2027 application deadline (applying from abroad)', '2027-06-15', 'Dates print without a year; treated as fall 2027. Applications incomplete by the deadline roll to the next session. Spring (January) entry: application Nov. 1, documents Nov. 15. Students transferring from a US school have later dates (fall: July 15).', 'df6c3f49-dc14-5593-90a0-36d82ca98215'),
 ('cd75c285-e05e-5e6a-ad20-8cbe7c92612a', '44b758d4-c446-5026-99bc-4dfcadf72d48', '2026-27', 'other', 'International fall 2027 document deadline', '2027-07-01', 'All admission documents must be received by this date (year not printed; treated as 2027).', 'df6c3f49-dc14-5593-90a0-36d82ca98215');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('44b758d4-c446-5026-99bc-4dfcadf72d48', 'required_nonnative', 'Exempt: citizens of listed English-speaking countries/territories; ACT composite 21 or SAT 1060; a US high school diploma (transcript reviewed, extra scores may be required); a US or English-speaking-country degree; IGCSE/GCSE/O Level English first language grade B or better; IB English Language & Literature HL score of 5 or higher. Also accepted: iTEP 3.5, MET 46, GTEC 1100, Oxford ELLT 6, TOEIC 586, EIKEN Pre-1, SAKAE 11-12. No conditional-admission or ESL pathway program is described on the pages read.', '424045cd-6b47-50c9-bbf0-b2725890c243');
