insert into cost_aid (institution_id, year, tuition_intl_usd, room_board_usd, other_usd, total_coa_usd, intl_aid_policy, intl_need_aid, meets_full_need, merit_scholarships, merit_separate_app, notes, source_id) values
 ('44b758d4-c446-5026-99bc-4dfcadf72d48', '2026-2027', 23250, 12620, 2250, 38120, 'merit_only', false, false, true, false, 'Student Account Services estimate for international undergraduates (15 credit hours per semester): tuition $18,000 plus fees $5,250 (entered as one combined figure), on-campus living for 9 months $12,620 (South Complex double, Residential Unlimited food plan), health insurance about $1,650 plus orientation/student service fees $600 (entered as other), total $38,120. Personal expenses ($4,500) and one-time vaccine/TB costs are listed separately and not included. Textbooks and a laptop are provided to eligible students per the cost page, so no books figure. The admissions cost page shows a different ''international'' direct-expense estimate of $39,622.; Northwest International Achievement Scholarship (NIAS): automatic for new international freshmen with a 2.75+ high school GPA; covers the in-state/out-of-state tuition difference (about $9,000 in year one), renewable with a 3.00 Northwest GPA, stackable with academic merit awards. Admission-based academic merit scholarships (GPA plus ACT/SAT chart) are automatic, with exceptional ACT/SAT scores helping; IB diploma award $1,000. No need-based aid for international students.', '0eedf123-1d3f-5e48-b4c2-ab23a679f8a3');
