insert into application_requirements (institution_id, cycle, platforms, supplemental_essays, teacher_recs, counselor_rec, interview, app_fee_usd, fee_waiver, notes, source_id) values
 ('ddfb5add-5745-5e45-871d-72ffc63066da', '2026-27', array['common_app','coalition','questbridge']::text[], true, 1, true, 'optional_informational', 75, true, 'App fee $75 is from the CDS (C13). One counselor and one teacher recommendation. No alumni interviews; applicants from international high schools may submit an optional InitialView interview. Applicants needing aid file the CSS Profile or ISAFA (international).', '74176a15-ba8f-56a2-8fb4-559fb988b3f3');
