insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, pct_submit_sat, pct_submit_act, notes, source_id, source_note) values
 ('a8807814-5574-59af-9b8d-cc7961a36c24', '2024-2025', 13237, 10725, 908, 22, 2, 'Baseline from IPEDS (fall 2024 entering class): applicants, admits and enrollees from the Education Data Portal; test submission rates and percentiles from College Navigator. No public Common Data Set was found (NYIT''s planning pages list a fact sheet only), so GPA, residency splits and international applicant counts are not available. SAT/ACT percentiles cover the 22% (198) / 2% (15) of enrollees who submitted scores. Undergraduate enrollment and the nonresident count (290, about 8%) are IPEDS fall 2024 undergraduate headcounts. NYIT''s test-optional page gives a mid-range of 1050-1270 for admitted students who submit SAT scores.', '46688acc-18e9-5df8-89b9-2db19793e492', 'admissions_site');
insert into test_score_percentiles (institution_id, cds_year, source_id, test, p25, p50, p75)
