insert into cost_aid (institution_id, year, tuition_usd, tuition_out_of_state_usd, tuition_intl_usd, required_fees_usd, room_board_usd, books_usd, other_usd, total_coa_usd, intl_aid_policy, intl_need_aid, intl_need_aid_awarded, intl_avg_award_usd, meets_full_need, merit_scholarships, merit_separate_app, notes, source_id) values
 ('563cfe51-3fa1-54a3-8d58-790c8f2253df', '2026-2027', 15426, 19788, 19788, 0, 11454, 700, 2292, 33534, 'merit_only', false, 127, 5851, false, true, false, 'International page estimate (fall and winter, 12-14 credits per semester): out-of-state tuition $19,788, living expenses $11,454 (entered under room and board), medical insurance $2,292 (under other), total $33,534; budget about $4,000 more for books and personal costs. $15,426 is the in-state-equivalent tuition shown for Canadian/Mexican students with the Non-Resident Award. The page does not date this table. 2026-27 per-credit rates: non-resident lower division $795.75 (upper $853.25); Michigan lower division $574.50. OU charges no mandatory fees.; CDS G1 first-year (labelled 2025-2026); the cycle file''s figures from Oakland''s international page replace these. H6: only institutional non-need-based aid is available to nonresidents; 127 nonresident undergraduates received it (average $5,851).; OU''s scholarship page says international students are not eligible for OU scholarships except where noted; the Non-Resident Award (in-state tuition rate) goes to U.S. out-of-state students and to citizens and permanent residents of Canada and Mexico with a 2.5+ GPA, who must live on campus two years. The international viewbook nevertheless says competitive scholarships for international students exist and CDS H6 shows 127 nonresidents received institutional non-need-based aid (average $5,851), but no international award amounts are published.', 'cc80543d-c0d9-52fd-a1d0-fb6204d553cf');
