insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('2e85a67d-1b3b-514c-97a7-552372c12e68', '2026-27', 'required', 'ACT or SAT scores are required for Columbus-campus first-year applicants (including international). Superscoring of section scores; ACT Science not required; essay not required. Scores must come directly from the testing agency.', '257fd348-6e31-5638-b498-f6529aed4889');
insert into application_requirements (institution_id, cycle, platforms, supplemental_essays, app_fee_usd, fee_waiver, notes, source_id) values
 ('2e85a67d-1b3b-514c-97a7-552372c12e68', '2026-27', array['common_app']::text[], 'Common App personal essay plus Ohio State-specific questions on the Common App (preferred admission plan, etc.).', 60, true, 'The Columbus first-year page states a $60 nonrefundable fee; other Ohio State pages cite $70 for international applicants, which was not confirmed on a first-year page. Recommendation letters are optional (up to two, sent by the counselor); no interview is mentioned.', 'fb2dc9b2-1583-563a-9747-5466fb533c36');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notification_date, notes, source_id) values
