insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('c26da06f-132d-59e8-9957-ab4be91f750c', '2026-27', 'optional', 'Permanent test-optional pathway for Athens first-year applicants; international applications ''do not require submission of ACT or SAT''. Scores may be submitted (SAT code 1593, ACT code 3314) and count as one factor in holistic review; test-optional applicants remain eligible for merit scholarships. SAT 1060 (EBRW 540) or ACT 21 can also serve as English-proficiency evidence.', 'f854e747-4b43-5de5-b75d-f2c1173ae34f');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('c26da06f-132d-59e8-9957-ab4be91f750c', '2026-27', array['common_app','own']::text[], 75, 'Apply via the Common App or OHIO''s own application. International application fee is $75. Records from every secondary school attended (certified English translations if needed); admission requires above-average grades, generally at least 6 Cambridge IGCSE/O-level passes at C or higher or an IB average of about 5 of 7. The early-action application also serves as the merit-scholarship application.', 'd71d4cac-5c38-54ce-b0ac-baeec373af46');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('933402d8-d3ca-57b2-93e0-b9e80be03fd8', 'c26da06f-132d-59e8-9957-ab4be91f750c', '2026-27', 'application', 'EA', 'Fall early action (international, fall 2027 entry)', '2026-11-15', 'No year is printed on the page; taken as the current cycle (the scholarship page names Nov. 15, 2026 for fall 2027 entrants). Early action gives priority for direct entry to academic programs and merit scholarships. Merit scholarships are for fall starters only.', '770fbc70-6830-51a9-9502-0b9baa856a20'),
 ('4b0cf9a3-027e-5add-aa04-a60311e6943c', 'c26da06f-132d-59e8-9957-ab4be91f750c', '2026-27', 'application', 'ROLLING', 'Fall rolling admission deadline (international)', '2027-02-01', 'No year is printed; taken as the current cycle. International spring rolling deadline is Nov. 1 (domestic first-year spring is Dec. 1).', '770fbc70-6830-51a9-9502-0b9baa856a20');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('c26da06f-132d-59e8-9957-ab4be91f750c', 'required_nonnative', 'Exempt unless proof is requested: citizens of listed English-speaking countries (e.g. Australia, Canada except Quebec, Ireland, Jamaica, Nigeria, UK, Zimbabwe) and students with three years of higher secondary schooling in an English-speaking system including three years of non-ESL college-prep English at B or better. Tests must be no more than one year old. Applicants who submit no score or fall short can be admitted to the Ohio Program of Intensive English (OPIE) and move to academic study after reaching the required level; Global Gateway/conditional admission is not mentioned.', 'd71d4cac-5c38-54ce-b0ac-baeec373af46');
