 ('TOEFL_IBT', 'required_option', 72, '{"writing": 17}'::jsonb, 'Pre-2026 scoring; writing subscore at least 17. TOEFL paper edition: 520 with composition 5 or higher.'),
 ('TOEFL_IBT_2026', 'required_option', 4.0, '{"writing": 4.0}'::jsonb, 'New scoring; writing subscore at least 4.'),
 ('IELTS', 'required_option', 6.0, '{"each_section": 5.5}'::jsonb, 'No subscore below 5.5.'),
 ('DUOLINGO', 'required_option', 110, null, null),
 ('PTE', 'required_option', 48, null, 'PTE Academic.'),
 ('CAMBRIDGE', 'accepted', 169, null, null)) v;
