select 'ff88d87f-2080-5255-91cf-71645b8f2cb1'::uuid, 'required_option', '8027490c-b806-5c17-bfc4-3a926a0cffd2'::uuid, v.* from (values
 ('TOEFL_IBT', 79, '{"each_section": 19}'::jsonb, 'Tests before Jan. 21, 2026; TOEFL MyBest accepted with the same minimums.'),
 ('TOEFL_IBT_2026', 4.5, '{"each_section": 4}'::jsonb, 'Tests after Jan. 21, 2026 (1-6 scale).'),
 ('IELTS', 6.0, null, null),
 ('DUOLINGO', 110, null, '100-109 places into IE 090/091.'),
 ('PTE', 53, null, 'PTE Academic.'),
 ('CAMBRIDGE', 169, '{"each_section": 162}'::jsonb, 'B2 First, C1 Advanced or C2 Proficiency score of 169+, no part below 162.')) v;
