insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('4c2b747a-e58e-5677-81da-c27164af9675', '2026-27', 'optional', 'The international application guide says SAT or ACT scores are optional and ''not a required document for admission''. The domestic scholarship page says test scores ''may be considered if provided''. No first-year GPA minimum was found.', '593fdf71-986c-5860-9e59-4c51cbb97418');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('4c2b747a-e58e-5677-81da-c27164af9675', '2026-27', array['own']::text[], 0, 'Olivet''s own online application, described as free for all students. International applicants send transcripts evaluated by WES or ECE if instruction was not in English, plus two recommendation letters (coaches, teachers or clergy). A 2024 helpful-information PDF lists two character references and a statement of personal faith instead; confirm which applies. Olivet''s health insurance is required for admission and enrollment; the one-time $350 SEVIS fee is a federal fee.', '593fdf71-986c-5860-9e59-4c51cbb97418');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('d50eea8e-1394-5174-8d11-0b8e4edb59a9', '4c2b747a-e58e-5677-81da-c27164af9675', '2026-27', 'application', 'RD', 'International complete-application deadline, fall (August term start)', '2027-06-01', 'Printed as ''Fall (August term start date): complete application deadline June 1'' with no year; taken as fall 2027 entry. First month''s payment is due July 1; the $200 enrollment deposit is waived for international students. A catalog page lists August 1 for fall for domestic freshmen (not re-verified as current).', '593fdf71-986c-5860-9e59-4c51cbb97418');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('4c2b747a-e58e-5677-81da-c27164af9675', 'required_nonnative', 'Applicants from countries whose primary language is not English must show proficiency with TOEFL or IELTS; no waiver or alternative test is listed. Duolingo, PTE and Cambridge are not mentioned.', '593fdf71-986c-5860-9e59-4c51cbb97418');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, min_subscores, notes)
select '4c2b747a-e58e-5677-81da-c27164af9675'::uuid, 'required_option', '593fdf71-986c-5860-9e59-4c51cbb97418'::uuid, v.* from (values
 ('TOEFL_IBT', 70, null, 'For undergraduate exams taken before 2026-01-21: minimum iBT 70.'),
 ('TOEFL_IBT_2026', 4, '{"reading": 4, "writing": 4}'::jsonb, 'For exams on or after 2026-01-21: a score of 4 or higher, including at least 4 in Reading and Writing (B2 CEFR band).'),
 ('IELTS', 6.5, null, 'Recent official score report, overall 6.5.')) v;
insert into cost_aid (institution_id, year, tuition_usd, required_fees_usd, room_board_usd, books_usd, total_coa_usd, notes, source_id) values
 ('4c2b747a-e58e-5677-81da-c27164af9675', '2026-2027', 41450, 990, 12290, 920, 60604, 'Olivet cost-of-attendance table, on campus, 2026-27: tuition $41,450, general fee $990, housing and meals $12,290, books $920, plus transportation $725, personal $3,400 and loan fees $59 = $60,604 total (2025-26: $58,894). Same figures are listed for all students; health insurance premium for international students is extra and not published on these pages.; The international page says ''Limited financial assistance may be available for international students'' and gives no amounts. Domestic first-year Academic Scholarship ($19,000-$28,500) and Academic Grant ($12,500-$21,500, minimum GPA 2.0) exist; the pages do not say whether international students qualify. Federal aid is not available to international students.', '45a3c10d-6f91-5e79-951f-ca175e1f8f2e');
insert into institution_tiers (institution_id, tier_code, category_key, rationale)
select '4c2b747a-e58e-5677-81da-c27164af9675'::uuid, 'D', v.* from (values
 ('general', 'Admit rate 66.9%'),
 ('nursing', 'Editorial judgment (v1, reviewed 2026-10-20)')) v;
insert into major_admissions (id, institution_id, program, category_key, admit_model, capped, notes) values
 ('0ac6be2d-6b1e-5c0c-af05-746ae4a7c267', '4c2b747a-e58e-5677-81da-c27164af9675', 'Nursing, BSN (traditional)', 'nursing', 'pre_major_competitive', false, 'Students declaring nursing start as pre-nursing; formal admission to the nursing major comes in NURS 202, which needs BIOL 211/246/247, CHEM 101/103, a passing HESI A2 score and a 2.75 cumulative GPA. The pages do not state a seat cap or how international students are treated.');

