insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('fde2f708-9861-5cf9-ad95-3dd0e55ac312', '2026-27', 'optional', 'SAT/ACT are not required; CDS C8F says Oregon is test-optional. The international page says SAT and ACT are not required and that merit scholarships are decided by holistic review without them. International applicants may use SAT/ACT scores to show English proficiency (EBRW 520 for full admission).', 'b03fe018-4ed0-5d90-befd-7866ac52ebd6');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('fde2f708-9861-5cf9-ad95-3dd0e55ac312', '2026-27', array['common_app','own']::text[], 75, 'Apply with the Oregon application or the Common App; both carry a non-refundable $75 fee that is not waived for international students (the CDS still prints $65). Minimum B (3.00) GPA, English proficiency (conditional admission possible) and proof of financial support. An optional personal statement and two recommendations are only for students with special circumstances. CDS C7 lists essay and recommendations as not considered. Some programs have earlier department deadlines.', 'b03fe018-4ed0-5d90-befd-7866ac52ebd6');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notification_date, notes, source_id) values
 ('e3d04849-b61c-51d1-a683-ed8c939bfddf', 'fde2f708-9861-5cf9-ad95-3dd0e55ac312', '2026-27', 'application', 'EA', 'International first-year Early Action (fall 2027 entry)', '2026-11-01', '2027-01-05', 'Supporting documents due Nov. 15; Clark Honors College early action documents due Nov. 7. Decision by Jan. 5. The page lists ''Early Action Deadline: November 1, 2026''.', 'b03fe018-4ed0-5d90-befd-7866ac52ebd6'),
 ('51fa5f7f-6de2-5b35-a093-52bde069d20e', 'fde2f708-9861-5cf9-ad95-3dd0e55ac312', '2026-27', 'application', 'RD', 'International first-year Regular application (fall 2027 entry)', '2027-01-15', null, 'Supporting documents due Feb. 15; applying by Jan. 15 means automatic consideration for General University Scholarships. Clark Honors College has the same Jan. 15 / Feb. 15 dates. The page prints dates without a year; treated as fall 2027 entry.', 'b03fe018-4ed0-5d90-befd-7866ac52ebd6'),
 ('b1c745be-7ecc-52e9-a5f1-58177a4592b7', 'fde2f708-9861-5cf9-ad95-3dd0e55ac312', '2026-27', 'other', 'ROLLING', 'Last date international applications are accepted for fall 2027', '2027-07-15', null, 'Applications are accepted on a rolling basis until July 15, but scholarships with earlier deadlines may be missed. English test results should arrive at least 12 weeks before International Student Orientation.', 'b03fe018-4ed0-5d90-befd-7866ac52ebd6');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('fde2f708-9861-5cf9-ad95-3dd0e55ac312', 'required_nonnative', 'Not required for citizens of listed English-speaking countries (e.g. Australia, Canada English-speaking provinces, Ireland, New Zealand, United Kingdom, Nigeria, Ghana, Kenya, South Africa, Jamaica and others). Waived for the full IB Diploma, IGCSE English grade C or higher, 2 US college writing courses (C- or better), 3 years of US college-prep language arts (B- or better) or 3 years at a UK/NZ/AU secondary school (B- or better). Scores must be within two years of enrollment.', '0219071e-aa72-57d1-8117-9f882092b9e9');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
select 'fde2f708-9861-5cf9-ad95-3dd0e55ac312'::uuid, 'required_option', '0219071e-aa72-57d1-8117-9f882092b9e9'::uuid, v.* from (values
 ('TOEFL_IBT', 61, 'Taken before Jan 2026. 80-120 = full admission; 61-79 = admitted with Academic English for International Students (AEIS) support; below 61 = conditional admission (intensive English first). min is the lowest score for admission without the intensive program. UO TOEFL code 4846.'),
 ('TOEFL_IBT_2026', 3.6, 'Taken after Jan 2026 (1-6 scale). 4.5 or higher = full admission; 3.6-4.0 = AEIS support; 3.5 or lower = conditional admission. The page prints 3.6 as the AEIS floor.'),
 ('IELTS', 5.5, '6.5-9.0 = full admission; 5.5-6.0 = AEIS support; below 5.5 = conditional admission.'),
 ('DUOLINGO', 100, '110-130 = full admission; 100-109 = AEIS support; below 100 = conditional admission.')) v;
insert into score_codes (institution_id, test_key, code, notes, source_id) values
 ('fde2f708-9861-5cf9-ad95-3dd0e55ac312', 'toefl', '4846', 'UO TOEFL institution code as printed on the international page.', 'b03fe018-4ed0-5d90-befd-7866ac52ebd6');
insert into cost_aid (institution_id, year, tuition_usd, tuition_out_of_state_usd, tuition_intl_usd, room_board_usd, books_usd, other_usd, total_coa_usd, intl_aid_policy, meets_full_need, merit_scholarships, notes, source_id) values
 ('fde2f708-9861-5cf9-ad95-3dd0e55ac312', '2026-2027', 17475, 47466, 47466, 18183, 1434, 4173, 71256, 'merit_only', false, true, 'UO 2026-27 estimated cost of attendance for a nonresident: tuition and fees $47,466 (resident $17,475), on-campus housing and food $18,183, books $1,434, miscellaneous $2,673 plus transportation $1,500 (entered together as other). Excludes the one-time $570 matriculation fee; first-years must live on campus. Tuition is locked for up to five years (Oregon Guarantee). Health insurance for international students is not itemized.; Applicants who apply by Jan. 15 are automatically considered for General University Scholarships (no amounts published on the international pages). Application-based: International Cultural Service Program (ICSP) partial tuition scholarship (need, merit, cultural service; renewable), a work-study program of 50+ awards of $1,000-$4,500, and Division of Global Engagement endowed scholarships of about $1,000-$12,000. CDS H6: 40 nonresident undergraduates received institutional aid, average $15,792. Conditional admission with UO Global Welcome (intensive English) is offered; no pathway fee is published on the pages checked.', '6e13d988-7e95-5482-b007-0315bfa39fad');
insert into institution_tiers (institution_id, category_key, tier_code, rationale)
select 'fde2f708-9861-5cf9-ad95-3dd0e55ac312'::uuid, v.* from (values
 ('general', 'C', 'Admit rate 88.3%; SAT middle 50% 1130-1360'),
 ('computer_science', 'C', 'Solid program at a large research university; not a national top-40 CS department.'),
 ('business', 'C', 'Lundquist College of Business is a respected program, not top-15.'),
 ('biology_life_sci', 'C', 'Strong research university with good life sciences; below national top-40.'),
 ('pre_med', 'D', 'Editorial judgment (v1, reviewed 2026-10-20)'),
 ('economics', 'C', 'Mid-ranked economics department at an AAU school.'),
 ('math_physics', 'D', 'Editorial judgment (v1, reviewed 2026-10-20)'),
 ('humanities', 'C', 'Broad College of Arts and Sciences with strong programs in several fields; mid-tier nationally.'),
 ('arts_design', 'C', 'Design, architecture, journalism and music/dance schools are well regarded; mid-tier nationally.')) v;

