insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('a14127da-626d-5c5e-9f74-19ad2cbaadda', '2026-27', 'optional', 'PLU does not require tests; applicants decide whether to have ACT or SAT scores considered. The admission GPA (weighted for AP/IB/Cambridge/Honors, max 4.50) is used for admission and scholarships.', '7a510296-a6ea-568f-b9d6-f13cc414f853');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('a14127da-626d-5c5e-9f74-19ad2cbaadda', '2026-27', array['common_app','own']::text[], 0, 'Apply with the Common App or PLU''s international first-year application; the page says it is free to apply. Needs a personal essay of at least 250 words, official English-translated transcripts, and an optional academic recommendation. After admission a bank statement, passport copy and $200 enrollment deposit are needed before the I-20/DS-2019.', '674a48ee-673c-5235-a7aa-8217f80e1800');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notification_date, notes, source_id) values
 ('46a2e56e-6605-5954-a19f-3fc068e644da', 'a14127da-626d-5c5e-9f74-19ad2cbaadda', '2026-27', 'application', 'EA', 'Early Action I (fall 2027 entry)', '2026-11-01', '2026-12-01', 'Page prints no year; treated as the fall 2027 cycle. Decision and scholarship notice by Dec. 1.', '674a48ee-673c-5235-a7aa-8217f80e1800'),
 ('c73814ee-c841-5608-9bf3-749c4f9ad03d', 'a14127da-626d-5c5e-9f74-19ad2cbaadda', '2026-27', 'application', 'EA', 'Early Action II (fall 2027 entry)', '2026-12-01', '2027-01-01', 'Decision and scholarship notice by Jan. 1. Also the date to be considered for Presidential Scholarships.', '674a48ee-673c-5235-a7aa-8217f80e1800'),
 ('88d7ae1d-4b47-5ade-9943-3fe336ab6036', 'a14127da-626d-5c5e-9f74-19ad2cbaadda', '2026-27', 'application', 'RD', 'Regular Decision (fall 2027 entry)', '2027-02-01', null, 'Decision and scholarship notice within a month.', '674a48ee-673c-5235-a7aa-8217f80e1800'),
 ('3c937742-8913-52d5-9c10-8f0e67782229', 'a14127da-626d-5c5e-9f74-19ad2cbaadda', '2026-27', 'application', 'ROLLING', 'Final application deadline (fall 2027 entry)', '2027-07-01', null, 'Applications completed after Feb. 1 are reviewed on a rolling basis.', '674a48ee-673c-5235-a7aa-8217f80e1800');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('a14127da-626d-5c5e-9f74-19ad2cbaadda', 'required_nonnative', 'Alternatives to a test: one college English class with B or better (semester system) or two (quarter system); SAT EBRW 500+; ACT English 21+; GCE O-Level English B; a pre-approved non-PLU ESL program (CEFR B2); a secondary diploma from Nordic countries or the Netherlands (English grade 7+) or from a listed English-medium country (e.g. U.S., Canada, UK, Australia, Ireland, Nigeria, South Africa, Philippines); or documentation that all instruction was in English for at least 2 years. No conditional-admission or ESL pathway is described.', '674a48ee-673c-5235-a7aa-8217f80e1800');
