insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, pct_submit_sat, pct_submit_act, notes, source_id, source_note) values
 ('726b80ec-dd61-59b7-8150-d38c40267c04', '2024-2025', 10335, 8474, 841, 25, 14, 'Baseline from IPEDS fall 2024 (College Navigator percentages; exact counts from the NCES ADM2024 file via the Urban Institute Education Data Portal). No Common Data Set was read, so international applicants/admits, GPA, SAT total and admission factors are not included. SAT/ACT percentiles cover enrolled first-time students who submitted scores (SAT 25%, ACT 14%). International undergraduates are left null; the school says students come from about 75-85 countries.', '74973546-98bf-58dd-a84c-bf1a522ecc80', 'admissions_site');
