insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('726b80ec-dd61-59b7-8150-d38c40267c04', '2026-27', 'optional', 'Admission is test optional; SAT, ACT or CLT scores are considered if sent. The international page says freshmen''s scores are not required but may be sent for bonus scholarships. PBA reserves the right to request a score, and some scholarships (Honors, Farish) need one.', 'f409e789-9fbe-50bc-aab7-1b5c591530af');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('726b80ec-dd61-59b7-8150-d38c40267c04', '2026-27', array['own','common_app']::text[], 0, 'Apply on PBA''s own application or the Common App (the international page calls the application free). Official high school transcript, with an official NACES course-by-course evaluation for non-U.S. schools. Decisions come in about 72 hours after the application is complete. A $300 enrollment deposit is needed before International Student Services issues the I-20.', '49d30bd6-b5f9-5210-802b-9b2877bb0ce0');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, notes, source_id) values
 ('95bc9b49-a740-5f43-a729-538a0b5b255a', '726b80ec-dd61-59b7-8150-d38c40267c04', '2026-27', 'application', 'ROLLING', 'Rolling admission (fall 2027 entry); no application deadline published', 'PBA begins reviewing applications each September on a rolling basis. No international-specific or final application deadline is printed on the freshman or international pages. Class selection and housing are first come, first served by deposit date.', 'f409e789-9fbe-50bc-aab7-1b5c591530af');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('726b80ec-dd61-59b7-8150-d38c40267c04', 'required_nonnative', 'Required for students from a country where English is not the primary language. Waived for students who have attended a U.S. school, an English language school, or a non-U.S. school taught in English for at least one academic semester. No conditional admission or ESL pathway is described on the pages read.', '2b44fa1a-36be-560d-af36-e6935bfb4de9');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
select '726b80ec-dd61-59b7-8150-d38c40267c04'::uuid, 'required_option', '2b44fa1a-36be-560d-af36-e6935bfb4de9'::uuid, v.* from (values
 ('TOEFL_IBT', 79, 'From the 2025-26 Articulation Manual (freshmen). The international page names TOEFL, IELTS or Duolingo but prints no scores.'),
 ('IELTS', 6.5, null),
 ('DUOLINGO', 100, 'Freshman minimum is 100 in the manual; the same manual lists 105 in the transfer section, so confirm with admissions.')) v;
