insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('71d86629-d4c5-5398-8a51-c67b4d376a17', '2026-27', 'optional', 'Penn State first-year applicants may choose whether to self-report SAT/ACT scores through MyPennState; no superscoring and ACT Science is not accepted. The Abington CDS C8A agrees: not required, considered if submitted.', '3e6eea03-8d46-5607-a957-66f3788506e2');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('71d86629-d4c5-5398-8a51-c67b4d376a17', '2026-27', array['common_app','own']::text[], 75, 'Penn State application fee is $75 for international applicants ($65 domestic). Application is the same for all Penn State campuses; the Abington campus site returned HTTP 403 to automated access, so deadlines, English minimums and fee are the university-wide Undergraduate Admissions rules and should be confirmed with Penn State Abington Admissions. Abington CDS C7: GPA very important, rigor important; essay, recommendations, interview not considered. Penn State Abington (near Philadelphia) lists 26 four-year majors (for example Accounting, Biology, Business, Computer Science, Cybersecurity, Data Sciences, Finance, Information Technology); for other Penn State majors it offers the first two years, then students change campus (University Bulletin, Abington). First-year students usually must finish two years on the starting campus before a change of campus.', '3e6eea03-8d46-5607-a957-66f3788506e2');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notification_date, notes, source_id) values
 ('6c1636cb-e72b-5ba6-8477-b37207c5f7ce', '71d86629-d4c5-5398-8a51-c67b4d376a17', '2026-27', 'application', 'EA', 'Early Action (university-wide)', '2026-11-01', '2026-12-24', 'Apply by Nov 1 to receive a decision by Dec 24. The Abington CDS (C22) lists the same Nov 1 closing and Dec 24 notification dates.', '3e6eea03-8d46-5607-a957-66f3788506e2'),
 ('a2aae5bd-9875-5568-bd18-3c0eb80ea1bc', '71d86629-d4c5-5398-8a51-c67b4d376a17', '2026-27', 'priority', 'RD', 'Recommended submission deadline for all applications', '2026-12-01', null, 'Dec 1 is a recommended date, not a hard closing date: the Abington CDS (C14) reports no application closing date and admission is rolling. No regular-decision notification date is published on the page.', '3e6eea03-8d46-5607-a957-66f3788506e2');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('71d86629-d4c5-5398-8a51-c67b4d376a17', 'required_nonnative', 'University-wide rule. Required of international applicants whose native language is not English (US citizens and permanent residents are exempt). Alternatives: SAT EBRW 570+ (code 2660), ACT English 24+ (code 3656), GCSE/GCE English language A-C, IB English A 5+, four years at a US high school, or certification from Penn State''s Intensive English Communication Program (IECP). Test scores must be under two years old; TOEFL MyBest is not accepted.', '3c8934b9-c0a8-56bf-a3ac-ff7d12b02483');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
select '71d86629-d4c5-5398-8a51-c67b4d376a17'::uuid, 'required_option', '3c8934b9-c0a8-56bf-a3ac-ff7d12b02483'::uuid, v.* from (values
 ('TOEFL_IBT', 80, 'Exams taken before Jan 21, 2026.'),
 ('TOEFL_IBT_2026', 4.5, 'Exams taken after Jan 21, 2026.'),
 ('IELTS', 6.5, 'Academic test.'),
 ('DUOLINGO', 120, null)) v;
