insert into cost_aid (institution_id, year, tuition_usd, tuition_out_of_state_usd, tuition_intl_usd, required_fees_usd, room_board_usd, books_usd, other_usd, intl_aid_policy, intl_need_aid, intl_need_aid_awarded, intl_avg_award_usd, meets_full_need, merit_scholarships, notes, source_id) values
 ('71d86629-d4c5-5398-8a51-c67b4d376a17', '2026-2027', 14684, 25584, 25584, 630, 12786, 1290, 5356, 'none', false, 0, 0, false, false, 'CDS G1/G5 first-year 2026-27, Penn State Abington campus: tuition in-state $14,684, out-of-state/nonresident $25,584 (international students pay the nonresident rate); required fees $630; food and housing $12,786 as printed (housing $10,786 + food $2,000; the G5 estimate for students living off campus is $18,276); books $1,290; other_usd = transportation $2,244 + other expenses $3,112. Tuition varies by program (G4). CDS H6: institutional scholarship and grant aid is not available to nonresident undergraduates.; Penn State states there is essentially no financial aid available for international undergraduate students, and the Abington CDS (H6) reports no institutional aid for nonresidents.', '9ea3a651-ba7a-5d0c-a1cc-5c61e9d9e6f0');
