insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('18d95775-c403-5bbe-b563-69f8c8b15a99', '2026-27', 'optional', 'Penn State first-year applicants may choose whether to self-report SAT/ACT scores through MyPennState; no superscoring and ACT Science is not accepted. Altoona CDS C8A agrees: not required, considered if submitted.', '0f5653d3-ab10-5844-a490-ed614048359b');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('18d95775-c403-5bbe-b563-69f8c8b15a99', '2026-27', array['common_app','own']::text[], 75, 'Penn State application fee is $75 for international applicants ($65 domestic). Application is the same for all Penn State campuses; altoona.psu.edu returned HTTP 403 to automated access, so deadlines, English minimums and fee are the university-wide Undergraduate Admissions rules and should be confirmed with Penn State Altoona (altoonaadmission@psu.edu). Altoona CDS C7: GPA very important, rigor important; essay, recommendations, interview not considered.', '0f5653d3-ab10-5844-a490-ed614048359b');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notification_date, notes, source_id) values
 ('89388397-f66a-53fc-afbd-d4cc0de27427', '18d95775-c403-5bbe-b563-69f8c8b15a99', '2026-27', 'application', 'EA', 'Early Action (university-wide)', '2026-11-01', '2026-12-24', 'Apply by Nov 1 to receive a decision by Dec 24. The Altoona CDS (C22) lists the same Nov 1 closing and Dec 24 notification dates.', '0f5653d3-ab10-5844-a490-ed614048359b'),
 ('1587797d-d9a7-5c7a-9680-3f7179419653', '18d95775-c403-5bbe-b563-69f8c8b15a99', '2026-27', 'priority', 'RD', 'Recommended submission deadline for all applications', '2026-12-01', null, 'Dec 1 is a recommended date, not a hard closing date: the Altoona CDS (C14) reports no application closing date and admission is rolling. No regular-decision notification date is published on the page.', '0f5653d3-ab10-5844-a490-ed614048359b');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('18d95775-c403-5bbe-b563-69f8c8b15a99', 'required_nonnative', 'University-wide rule. Required of international applicants whose native language is not English (US citizens and permanent residents are exempt). Alternatives: SAT EBRW 570+ (code 2660), ACT English 24+ (code 3656), GCSE/GCE English language A-C, IB English A 5+, four years at a US high school, or certification from Penn State''s Intensive English Communication Program (IECP). Test scores must be under two years old; TOEFL MyBest is not accepted.', 'abe91fd7-7aba-553f-bbf7-38b18f718f32');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
