insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('441ab975-fd7e-5bfa-82f9-ae559dd5d271', '2026-27', 'optional', 'Penn State first-year applicants may choose whether to self-report SAT/ACT scores through MyPennState; no superscoring and ACT Science is not accepted. Harrisburg CDS C8A agrees: not required, considered if submitted.', '13bfd84a-868b-54b4-912a-4abe83177364');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('441ab975-fd7e-5bfa-82f9-ae559dd5d271', '2026-27', array['common_app','own']::text[], 75, 'Penn State application fee is $75 for international applicants ($65 domestic). Application is the same for all Penn State campuses; harrisburg.psu.edu pages returned HTTP 403 to automated access, so deadlines, English minimums and fee are the university-wide Undergraduate Admissions rules and should be confirmed with Penn State Harrisburg (hbgadmit@psu.edu). Harrisburg CDS C7: GPA very important, rigor important; essay, recommendations, interview not considered.', '13bfd84a-868b-54b4-912a-4abe83177364');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notification_date, notes, source_id) values
 ('96738358-d2ba-5528-acb1-f0a52ed08f54', '441ab975-fd7e-5bfa-82f9-ae559dd5d271', '2026-27', 'application', 'EA', 'Early Action (university-wide)', '2026-11-01', '2026-12-24', 'Apply by Nov 1 to receive a decision by Dec 24. The Harrisburg CDS (C22) lists the same Nov 1 closing and Dec 24 notification dates.', '13bfd84a-868b-54b4-912a-4abe83177364'),
 ('0ee0cb73-4fa3-58d8-b837-a3f4c28d4aa5', '441ab975-fd7e-5bfa-82f9-ae559dd5d271', '2026-27', 'priority', 'RD', 'Recommended submission deadline for all applications', '2026-12-01', null, 'Dec 1 is a recommended date, not a hard closing date: the Harrisburg CDS (C14) reports no application closing date and admission is rolling. No regular-decision notification date is published on the page.', '13bfd84a-868b-54b4-912a-4abe83177364');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('441ab975-fd7e-5bfa-82f9-ae559dd5d271', 'required_nonnative', 'University-wide rule. Required of international applicants whose native language is not English (US citizens and permanent residents are exempt). Alternatives: SAT EBRW 570+ (code 2660), ACT English 24+ (code 3656), GCSE/GCE English language A-C, IB English A 5+, four years at a US high school, or certification from Penn State''s Intensive English Communication Program (IECP). Test scores must be under two years old; TOEFL MyBest is not accepted.', '686099ed-1e94-54b3-aa35-20c849839cdb');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
select '441ab975-fd7e-5bfa-82f9-ae559dd5d271'::uuid, 'required_option', '686099ed-1e94-54b3-aa35-20c849839cdb'::uuid, v.* from (values
 ('TOEFL_IBT', 80, 'Exams taken before Jan 21, 2026.'),
 ('TOEFL_IBT_2026', 4.5, 'Exams taken after Jan 21, 2026.'),
 ('IELTS', 6.5, 'Academic test.'),
 ('DUOLINGO', 120, null)) v;
insert into score_codes (institution_id, source_id, test_key, code, notes)
