insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('0a63967c-c5b0-5ad2-a688-ffb3df5f90c9', '2026-27', 'optional', 'SAT/ACT scores are optional: first-year applicants need a 2.50 cumulative GPA (weighted or unweighted) and may submit scores; admissions also reviews course trends, rigor, leadership and activities. Applicants with a 2.0-2.49 GPA may be admitted through the Compass Program, which is open to international first-year applicants. International applicants need a 2.50 GPA as determined by AACRAO Edge or a NACES credential evaluation.', '4dceba03-11cf-5493-85d0-c03dcf968d0d');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('0a63967c-c5b0-5ad2-a688-ffb3df5f90c9', '2026-27', array['common_app','own']::text[], 35, 'Apply with the PennWest online application, the Common App or a paper application; the policy says all applicants pay the $35 fee, waivable by staff. International first-year applicants submit an official high school transcript showing at least a 2.50 GPA (credential evaluated), proof of English proficiency and passport information. Financial and immigration documents (financial guarantee statement, affidavit of support, passport copy) are collected after admission for the I-20. International applicants are not eligible for provisional admission. Essay, recommendations and activities are optional per the international page.', '4dceba03-11cf-5493-85d0-c03dcf968d0d');
insert into deadlines (id, institution_id, cycle, kind, label, due_date, notes, source_id) values
 ('4386d935-780b-54be-8fe1-7287e91d9334', '0a63967c-c5b0-5ad2-a688-ffb3df5f90c9', '2026-27', 'application', 'International application deadline, fall 2027 entry', '2027-06-01', 'The page says June 1 for a fall semester start (November 1 for spring); no year is printed, so June 1 is taken as 2027 for fall 2027. Applications are decided once all documents are received; the page does not say whether admission is rolling.', '13ef880d-2dce-5dc1-81ef-10b8888f3886');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('0a63967c-c5b0-5ad2-a688-ffb3df5f90c9', 'required_nonnative', 'Required for applicants whose primary language of instruction is not English. Besides the tests below, accepted evidence includes ITEP Academic 3.5, ISTEP 60, SAT EBRW 500, ACT English 21, A-Level/IGCSE/GCSE/O-Level English C, IB English 5, completion of ELS Level 112 or a campus-based ESL program at an accredited U.S. college. Exempt: a degree from a U.S. or English-medium institution, 24 credits at a U.S./English-medium college, 2+ years at a U.S. high school, an IB diploma, or citizens of listed English-speaking countries (e.g. UK, Ireland, Australia, Canada except Quebec, Nigeria, Singapore, South Africa). The international page lists TOEFL, IELTS, Duolingo, Pearson, GTEC CBT and STEP-EIKEN.', '4dceba03-11cf-5493-85d0-c03dcf968d0d');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, min_subscores, notes)
select '0a63967c-c5b0-5ad2-a688-ffb3df5f90c9'::uuid, 'required_option', '4dceba03-11cf-5493-85d0-c03dcf968d0d'::uuid, v.* from (values
 ('TOEFL_IBT', 61, null, null),
 ('IELTS', 5.5, '{"each_section": 5.5}'::jsonb, 'IELTS Academic with no sub-score below 5.5 (SE004). Edinboro''s own pages have listed IELTS 6.0, so confirm with the campus.'),
 ('DUOLINGO', 100, null, null),
 ('PTE', 46, null, 'Pearson PTE Academic, per SE004 (not shown on the international page''s minimums).')) v;
insert into cost_aid (institution_id, year, tuition_usd, tuition_out_of_state_usd, tuition_intl_usd, required_fees_usd, room_board_usd, books_usd, intl_merit_aid, meets_full_need, merit_scholarships, notes, source_id) values
 ('0a63967c-c5b0-5ad2-a688-ffb3df5f90c9', '2026-2027', 8338, 12508, 12508, 5141, 12890, 1260, true, false, true, 'Tuition page ''Costs (2026-2027)'', per term, 12-18 credits: in-state tuition $4,169 (tuition + fees $6,262.50); out-of-state/international tuition $6,254 (tuition + fees $8,824.50), so fees are $2,570.50 per term for out-of-state/international. The page gives no annual figures; the annual values here are two terms (semester calendar) x the per-term amounts: tuition $8,338 in-state and $12,508 out-of-state/international, fees $5,141. The page shows a single combined ''out-of-state/international'' rate. room_board_usd = housing $8,100 + food $4,790 from the cost-of-attendance page, which does not name a year and shows different tuition ($11,574) and fees ($4,224) for out-of-state, so verify with the university. Scholarships may lower the tuition rate (see aid notes).; The international pages say students may be eligible for financial aid, scholarships, grants and student employment, and that first-year international students are eligible for housing and need-based scholarships (no amounts). The FAQ describes an undergraduate academic scholarship (minimum 2.5 GPA, kept while a 2.5 GPA is maintained) that reduces tuition to the rate non-resident Pennsylvanians pay; its dollar value is not given and the 2026-27 tuition page lists one combined out-of-state/international rate.', 'f0122692-ee4b-5b27-a4bc-99a391808a13');
insert into institution_tiers (institution_id, tier_code, category_key, rationale)
select '0a63967c-c5b0-5ad2-a688-ffb3df5f90c9'::uuid, 'D', v.* from (values
 ('general', 'Admit rate 94.3%'),
 ('business', 'Editorial judgment (v1, reviewed 2026-10-20)'),
 ('computer_science', 'Editorial judgment (v1, reviewed 2026-10-20)'),
 ('biology_life_sci', 'Editorial judgment (v1, reviewed 2026-10-20)'),
 ('engineering', 'Editorial judgment (v1, reviewed 2026-10-20)'),
 ('nursing', 'Editorial judgment (v1, reviewed 2026-10-20)')) v;
insert into major_admissions (id, institution_id, program, category_key, admit_model, capped, notes) values
 ('e0474908-a1e1-52be-b07e-9d74b482de94', '0a63967c-c5b0-5ad2-a688-ffb3df5f90c9', 'Nursing, BSN (traditional)', 'nursing', 'direct_major', false, 'Minimum 3.0 high school GPA and grades of B or higher in algebra I/II or calculus, biology and chemistry. A separate Associate of Science in Nursing needs a 2.75 GPA and a proficient ATI TEAS score (SE004).');

