insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, intl_applicants, intl_admits, in_state_applicants, in_state_admits, out_state_applicants, out_state_admits, pct_submit_act, gpa_avg, pct_reporting_gpa, gpa_distribution, notes, source_id) values
 ('3ed85bb8-49ac-57bf-904f-ad35eb296c5d', '2024-2025', 4085, 3565, 897, 131, 122, 2439, 2094, 1515, 1349, 64, 3.48, 93.41, '{"4.0": 17.7, "3.75-3.99": 24.4, "3.50-3.74": 15.67, "3.25-3.49": 12.56, "3.00-3.24": 9.09, "2.50-2.99": 13.88, "2.0-2.49": 5.62, "1.0-1.99": 1.08}'::jsonb, 'CDS 2024-2025, Fall 2024 first-time first-year class. C1 residency split: in-state 2,439 applied / 2,094 admitted; out-of-state 1,515 / 1,349; international 131 / 122 (enrolled split by residency was not reported). The enrolled figure 897 is the sum of full-time and part-time enrollees in C1. IPEDS (College Navigator) shows 3,138 applicants and 2,806 admits for the same fall, so the two sources differ. 64% (572 students) submitted ACT; no SAT scores reported. GPA distribution is the ''all enrolled students'' column of C11. Undergraduate enrollment 4,491 and nonresident undergraduates 133 are the B1 ''Total undergraduates'' column (degree- and non-degree-seeking).', '7ba58c57-650f-55bf-8b49-4414ef54567e');
insert into test_score_percentiles (institution_id, cds_year, source_id, test, p25, p50, p75)
