 ('ielts', null, 'No institution code is listed.', 'afb17e9e-6b57-5671-bb69-4c087f835f8d'::uuid),
 ('duolingo', null, 'No institution code is listed.', 'afb17e9e-6b57-5671-bb69-4c087f835f8d'::uuid),
