insert into cost_aid (institution_id, year, tuition_usd, tuition_out_of_state_usd, tuition_intl_usd, intl_extra_fees_usd, room_board_usd, books_usd, total_coa_usd, merit_scholarships, notes, source_id) values
 ('3ed85bb8-49ac-57bf-904f-ad35eb296c5d', '2026-2027', 8884, 20228, 20228, 2741, 10634, 1000, 34603, true, 'Costs page, 2026-27, per year (2 x semester amounts): nonresident flat-rate tuition including campus fees $10,114 per semester = $20,228 (resident $4,442 per semester = $8,884); residence hall living estimate $5,317 per semester = $10,634 (no meal plan is listed); books and supplies $500 per semester = $1,000. International table adds sickness/accident insurance $2,661 and orientation/SEVIS compliance $80 (extra fees $2,741), for an estimated international academic-year total of $34,603. International students are charged the nonresident rate.; Gorilla International Scholarship for new international freshmen and transfers in degree programs: up to $6,000 per year by GPA (3.8-4.0 $6,000; 3.6-3.79 $5,000; 3.4-3.59 $4,000; 3.2-3.39 $3,000; 2.7-3.19 $2,000), a tuition waiver for up to four years of full-time enrollment, rescindable if cumulative GPA falls below 3.0, not valid in summer. English test scores, activities and need are also factors; no deadline is printed. An International Academic Excellence Scholarship also exists (no amount listed). CDS H6 marks both need-based and non-need-based institutional aid as available to nonresidents.', '3a47bbaf-9652-5072-b283-d3d23ea2c8db');
