select 'b797aaaa-4c1d-50d2-b865-5b1f403ec614'::uuid, 'direct_major', false, v.* from (values
 ('2c4f0b5f-d5d8-5d29-8e38-d9b3ef311712'::uuid, 'Nursing (pre-licensure BSN)', 'nursing', 'Requires overall GPA 3.0 or higher, 3.0 or higher in high school science (biology and chemistry required), Algebra I, II and Geometry, and a strong application essay. Seat limits are not stated on the page.'),
 ('199f9068-2b09-519f-a273-befb7b2f4887'::uuid, 'Music and Theatre', 'arts_design', 'Applicants to the Music or Theatre programs must audition.')) v;

