insert into cost_aid (institution_id, year, tuition_usd, tuition_intl_usd, required_fees_usd, room_board_usd, books_usd, intl_aid_policy, intl_need_aid, intl_merit_aid, intl_need_aid_awarded, intl_avg_award_usd, meets_full_need, merit_scholarships, merit_separate_app, notes, source_id) values
 ('98a3d5da-78c7-5d64-86a0-df527ea7de93', '2026-2027', 40260, 40260, 2280, 14440, 1200, 'merit_only', false, true, 113, 31472, false, true, false, 'CDS G1 for the full 2026-2027 year (first-year and all undergraduates): tuition $40,260 (12-18 credits per term), required fees $2,280, food and housing $14,440 (housing $6,400 + meal plan $8,040), books $1,200. H6: only institutional non-need-based aid is available to nonresidents; 113 undergraduate degree-seeking nonresidents received it (average $31,472, total $3,556,282).; Merit-based freshman scholarships of $16,000-$26,000 per year are awarded on high school GPA and English proficiency to full-time traditional freshmen; admitted students are automatically considered and no separate application is described. Awards offset tuition and fees only, require satisfactory academic progress to keep, and do not apply to summer. CDS H6: only institutional non-need-based aid is available to nonresidents (113 recipients, average $31,472).', 'cd4ae34d-bfd5-565e-84ee-deecc2b9a78a');
