insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('c7fe9be4-7bbb-5f8e-b7d5-157c028b8b42', '2026-27', 'optional', 'The freshman criteria page is headed ''Automatic Admissions Requirements/ Test Optional'': automatic admission with the required courses and any one of top 35% of class, cumulative GPA 3.2, or SAT 1060 / ACT 21; others go to holistic review. The same page''s international freshman checklist still lists ''SAT 800 or ACT 15'', which the newer International Admissions page does not; confirm with admissions.', 'f7a7d097-1ba9-5873-8be2-df4a035effac');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('c7fe9be4-7bbb-5f8e-b7d5-157c028b8b42', '2026-27', array['own']::text[], 50, 'Apply through PANTHER Apply or ApplyTexas; the international fee is $50 (domestic $40). International freshmen need a minimum 3.2 GPA (international page), a passing result in the home-country secondary qualification (page lists ''5 passing grades on the GCE, CXC, West African School Certificate or O-levels''), a notarized affidavit of financial support and a bank statement or employment letter; foreign college transcripts need a course-by-course evaluation.', 'f947452b-e4df-5f27-a154-d303d544bfd5');
insert into deadlines (id, institution_id, cycle, kind, label, due_date, notes, source_id) values
 ('0e5583e6-fe4d-5043-a4eb-44114cb7ec0d', 'c7fe9be4-7bbb-5f8e-b7d5-157c028b8b42', '2026-27', 'priority', 'Fall 2027 scholarship priority date (undergraduate FF/FI/TI)', '2026-12-01', 'Deadlines table column ''Fall (Scholarship Priority)'' for rows FF, FI (freshmen international) and TI (transfer international). The page says applications for Fall 2027 are open.', 'c38ed472-8db8-5eac-9f45-292af13ef454'),
 ('d1cdf6e9-4df3-5513-a0fc-09ba8b07d721', 'c7fe9be4-7bbb-5f8e-b7d5-157c028b8b42', '2026-27', 'scholarship', 'Fall scholarship deadline', '2027-03-01', 'Scholarship line of the same page: Fall - March 1.', 'c38ed472-8db8-5eac-9f45-292af13ef454'),
 ('abcf2aa1-97a7-56ee-91de-e156eaaaf675', 'c7fe9be4-7bbb-5f8e-b7d5-157c028b8b42', '2026-27', 'application', 'Fall 2027 application deadline (freshman international)', '2027-05-17', 'Column ''Fall'' for FF/FI/TI. All accompanying documents must be received by the deadline; students receiving a University Scholarship may be considered after it.', 'c38ed472-8db8-5eac-9f45-292af13ef454');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('c7fe9be4-7bbb-5f8e-b7d5-157c028b8b42', 'required_nonnative', 'Required for applicants whose native language is not English. The catalog says a graduate of a U.S. secondary school, or a student with ACT English 18 or SAT Verbal 400, is exempt from the TOEFL; the newer International Admissions page does not repeat this.', 'f947452b-e4df-5f27-a154-d303d544bfd5');
