insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('1b4c4ac0-db93-58da-b4e1-aef54f7acd73', '2026-27', 'optional', 'Test-optional for applicants seeking to enroll in fall 2027 (2026-27 cycle). Princeton returns to requiring SAT or ACT from the 2027-28 cycle (fall 2028 entry). Score choice allowed within one format; no superscoring across paper and digital.', 'e5f6804a-0307-5ed7-ab43-d3781254f3e6');
