insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('98ca9a0f-668c-539c-b3b5-cde3ce0f756c', '2026-27', 'optional', 'PFW is a test-optional institution; SAT/ACT are strongly encouraged (not required) for engineering applicants. Engineering (civil, mechanical, computer, electrical) needs one of: SAT Math 570, ACT Math 24+, PFW math placement 50+, AP Calculus AB 4+, AP Calculus BC 3+, or qualifying dual/college math credit (MA 15400+).', 'fefa5962-fe45-5f90-a890-f0ff87f877db');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('98ca9a0f-668c-539c-b3b5-cde3ce0f756c', '2026-27', array['own']::text[], 30, 'International first-year admission: completed application, $30 application fee, cumulative GPA of at least 2.3 on a 4.0 scale, and proof of English proficiency. Official transcripts are sent directly by the school; PFW''s Office of International Education prepares a credential evaluation for non-U.S. schools. The domestic fee waiver announced in March 2026 applies to domestic students only. Indiana law SB 256 adds a security review for some international applicants (see the PFW SB 256 page).', 'df367144-f47e-5080-8b36-cbb74a459ca1');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('0dbc80f3-87e8-5853-939a-e6d9c5e6f2da', '98ca9a0f-668c-539c-b3b5-cde3ce0f756c', '2026-27', 'application', 'RD', 'International application deadline, fall 2027 entry (residing outside the U.S.)', '2027-05-01', 'Page prints ''May 1 (Fall)'' without a year; treated as fall 2027. Spring deadline for applicants outside the U.S. is Nov. 1.', 'df367144-f47e-5080-8b36-cbb74a459ca1'),
 ('38e45869-dcbe-517f-b02e-53855a56c34f', '98ca9a0f-668c-539c-b3b5-cde3ce0f756c', '2026-27', 'application', 'RD', 'International application deadline, fall 2027 entry (residing within the U.S.)', '2027-07-15', 'Page prints ''July 15 (Fall)'' without a year; treated as fall 2027. Spring deadline for applicants inside the U.S. is Dec. 1.', 'df367144-f47e-5080-8b36-cbb74a459ca1');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('98ca9a0f-668c-539c-b3b5-cde3ce0f756c', 'required_nonnative', 'Citizens of the listed English-speaking countries (e.g. Canada, UK, Ireland, Australia, Nigeria, Singapore, South Africa, Philippines) are exempt. Other ways to show proficiency: SAT EBRW 580 or ACT 20 (sent officially), O/AS/A Level first-language English grade C or better, IB English SL/HL 5+, ELS level 112, ''Academic English for Purdue Fort Wayne'' with a C or better, two years of U.S. high school English with C or better (ESL does not count), or a U.S. university English course with C or better. Results are valid for two years.', 'df367144-f47e-5080-8b36-cbb74a459ca1');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
