insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, pct_submit_sat, pct_submit_act, notes, source_id, source_note) values
 ('88833a3e-a6f3-5039-a30f-9b9476759c18', '2023-2024', 6394, 4516, 1192, 67, 5, 'Baseline from IPEDS (fall 2023 entering class, ADM2023); no readable Common Data Set was found. IPEDS does not split applicants by residency, so international applicants/admits are not available. SAT total, GPA distribution, ED and residency splits are not added. College Navigator also shows fall 2024: 8,617 applicants, 72% admitted, 18% of admits enrolled; about 3% of undergraduates are U.S. nonresidents (fall 2024).', '424f072c-057a-51c9-8e83-f91a9271b8c4', 'admissions_site');
