insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('88833a3e-a6f3-5039-a30f-9b9476759c18', '2026-27', 'optional', 'PNW says it is test-optional for undergraduate admission; SAT/ACT scores are encouraged because they help with math placement. The international page also lists the SAT as one accepted way to show English proficiency but prints no minimum score.', '3b88c35b-ad47-50c0-85e6-a0f559171da3');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('88833a3e-a6f3-5039-a30f-9b9476759c18', '2026-27', array['own']::text[], 25, 'International Undergraduate Student Application on the PNW portal; $25 non-refundable fee for students with no previous college. Proof of secondary-school graduation (unofficial copies accepted to start; no WES/ECE evaluation required); official documents on matriculation. No minimum GPA is published on the pages read. Personal statement is optional. Indiana law SB 256 (from Aug. 15, 2026) adds a research-security review before admission for citizens of listed ''foreign adversary'' countries (China incl. Hong Kong and Macau, Cuba, Iran, North Korea, Russia, Venezuela, others) who are not U.S. citizens, green-card holders, or asylees/refugees (see the PNW SB 256 page).', '5875dbba-f6b0-5fbf-9a24-c4c075b7bd0c');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('6d49e262-1652-5b53-8a0b-3ddb51d06ee6', '88833a3e-a6f3-5039-a30f-9b9476759c18', '2026-27', 'application', 'RD', 'International application deadline, fall 2027 entry', '2027-06-01', 'Page prints ''Fall Semester: June 1'' without a year; treated as fall 2027. All required materials must be received by this date. Spring semester deadline is Oct. 15.', '5875dbba-f6b0-5fbf-9a24-c4c075b7bd0c');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('88833a3e-a6f3-5039-a30f-9b9476759c18', 'required_all_international', 'Applicants must submit one of: TOEFL, IELTS, Duolingo, PTE, SAT, British O-Level English (grade A or B), or at least 12 transferable credits from a U.S. accredited institution including a course equivalent to ENGL 10400. No list of exempt countries is published on the page read.', '5875dbba-f6b0-5fbf-9a24-c4c075b7bd0c');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
select '88833a3e-a6f3-5039-a30f-9b9476759c18'::uuid, 'required_option', '5875dbba-f6b0-5fbf-9a24-c4c075b7bd0c'::uuid, v.* from (values
 ('TOEFL_IBT', 79, 'Exams taken before 2026-01-21 (0-120 scale).'),
 ('TOEFL_IBT_2026', 4, 'Exams taken on or after 2026-01-21; the page states the 1-6 scale.'),
