insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, intl_applicants, intl_admits, in_state_applicants, in_state_admits, out_state_applicants, out_state_admits, pct_submit_sat, pct_submit_act, gpa_avg, pct_reporting_gpa, gpa_distribution, notes, source_id) values
 ('17b00322-4c0b-5f69-b4c2-96508302eb28', '2025-2026', 9169, 8196, 1408, 563, 471, 7388, 6707, 1211, 1016, 11, 1, 3.52, 100, '{"4.0": 19.1, "3.75-3.99": 17.0, "3.50-3.74": 18.5, "3.25-3.49": 14.8, "3.00-3.24": 14.1, "2.50-2.99": 15.4, "2.0-2.49": 1.1, "1.0-1.99": 0.0}'::jsonb, 'CDS C1 (fall 2025): applicants 9,169 (3,306 men + 5,849 women + 14 unknown), admitted 8,196, enrolled 1,408; residency table: in-state 7,388/6,707, out-of-state 1,211/1,016, international 563/471 applied/admitted (18 international enrolled). The CDS reports no waitlist. GPA distribution is the ''all enrolled students'' column of C11 as printed. Undergraduate enrollment is B1 ''Total All Undergraduates'' (6,206). Percent submitting ACT is printed as ''<1%'' (9 students), stored as 1. The CDS C7 factor checkboxes are unreadable as text, so factors are omitted. Student-faculty ratio 14:1 is from College Navigator (fall 2024); the CDS does not print it.', 'f25879c3-c114-53e3-a2a2-d13d4c0d8389');
