insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('17b00322-4c0b-5f69-b4c2-96508302eb28', '2026-27', 'optional', 'Radford is test-optional: SAT, ACT and CLT scores are not required and submitting them will not hurt a decision. Direct admission asks for a 3.0 cumulative GPA and three college-preparatory math courses; successful applicants typically have at least a 2.6 GPA. The CDS (C8) separately ticks SAT/ACT as ''not considered''.', 'f04ae0d9-84a1-5378-80e7-a038f1b44b27');
insert into application_requirements (institution_id, cycle, platforms, supplemental_essays, app_fee_usd, notes, source_id) values
 ('17b00322-4c0b-5f69-b4c2-96508302eb28', '2026-27', array['common_app','own']::text[], 'Optional essay about yourself.', 0, 'No application fee for freshmen. Apply with Radford''s own application or the Common App. High school transcript required (unofficial copy accepted for review, official before enrollment); letters of recommendation are not mentioned. International applicants also submit proof of English proficiency, official transcripts in English, a passport copy, a financial statement and an Affidavit of Support if others are supporting them, and applicants from Ghana, Nigeria, Sierra Leone, The Gambia and Liberia need an official WAEC scratch card. An $800 non-refundable enrollment deposit is due after admission. Music and dance majors must audition.', 'f04ae0d9-84a1-5378-80e7-a038f1b44b27');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('33e51e34-48fa-56a3-9ac4-1f76ed1069e1', '17b00322-4c0b-5f69-b4c2-96508302eb28', '2026-27', 'application', 'EA', 'Early Action (fall 2027 entry)', '2026-11-01', 'The page prints Nov. 1 without a year; taken as fall 2027 entry. Fall decisions begin Nov. 15 and then roll out, typically 2-3 weeks after an application is complete.', 'f04ae0d9-84a1-5378-80e7-a038f1b44b27'),
 ('874dd5dc-5544-5ac3-9e57-4c6b79cec452', '17b00322-4c0b-5f69-b4c2-96508302eb28', '2026-27', 'application', 'RD', 'Regular deadline (fall 2027 entry)', '2027-02-01', 'The page prints Feb. 1 without a year; taken as fall 2027 entry. Rolling review continues through July 31 ''as space is available''.', 'f04ae0d9-84a1-5378-80e7-a038f1b44b27'),
 ('2b683cdf-9262-597e-97f2-40fcfbffbc4c', '17b00322-4c0b-5f69-b4c2-96508302eb28', '2026-27', 'application', 'ROLLING', 'International undergraduate fall deadline', '2027-07-01', 'The international requirements page lists Fall: July 1 and Spring: December 1 for undergraduates (no year printed; taken as fall 2027). The domestic freshman page gives a Feb. 1 regular date, so apply well before July 1 to leave time for the I-20 and visa.', '01186a08-e41a-527a-9f56-71d31e73b40e');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('17b00322-4c0b-5f69-b4c2-96508302eb28', 'required_nonnative', 'Exempt: transfer from a U.S. institution, or prior attendance at an institution in a listed waiver country (including Canada, Australia, the United Kingdom, Ireland, New Zealand, Jamaica and Kenya; full list on the page). Alternatives to the tests listed: SAT with a minimum 480 in Reading/Writing, TIE B2, HKDSE 4, IGCSE/GCSE/GCE grade C in English, Oxford Online Placement Test 60, NCUK EAP grade C, TOEIC 620, EIKEN Pre-1. Scores must be within the last two calendar years. No conditional admission or ESL pathway is mentioned on the page.', '01186a08-e41a-527a-9f56-71d31e73b40e');
insert into english_requirements (institution_id, source_id, test_key, status, min_total, min_subscores, notes)
