 ('TOEFL_IBT', 'required_option', 68, null, 'Undergraduate minimum. A 1-6 band-scale minimum is not published.'),
 ('IELTS', 'required_option', 6.0, '{"reading": 5.5}'::jsonb, 'Minimum 6.0 overall with at least 5.5 in Reading.'),
 ('DUOLINGO', 'required_option', 100, null, null),
 ('PTE', 'required_option', 50, null, null),
 ('CAMBRIDGE', 'accepted', 160, null, 'Listed as B2/160.')) v;
