insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('c69d3daa-bbc3-594e-9e76-c875d3a7c2a3', '2026-27', 'optional', 'URI is test-optional; SAT/ACT scores are not required and are superseded by a holistic review. The international page encourages submitting scores if seeking merit scholarships. 6-year Pharm.D. applicants: SAT/ACT optional but recommended.', '39344087-4e6f-5c0a-a504-a342787d416a');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('c69d3daa-bbc3-594e-9e76-c875d3a7c2a3', '2026-27', array['common_app']::text[], 65, 'Common App, $65 fee (or waiver), official high school transcript (STARS Record only for US-system schools), essay, one letter of recommendation (two for Pharmacy). International applicants also send certified English translations of non-English documents, official English test scores directly from the testing agency, and a gap-year paragraph if applicable. Supplemental essay for Honors, Nursing, Pharmacy and Talent Development only. URI does not offer individual interviews.', 'fbe3c88f-a3de-59d8-8132-39f81ae91ce3');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('7a4549d1-bdf7-5eba-8fab-4260cb55bcd4', 'c69d3daa-bbc3-594e-9e76-c875d3a7c2a3', '2026-27', 'application', 'ED', 'Early Decision (binding), fall 2027 entry', '2026-11-01', 'Decision in early December. Enrollment and housing deposits due Feb. 1 (or within two weeks of a financial aid award if aid was requested). Pages print no year; taken as the fall 2027 entry cycle.', '39344087-4e6f-5c0a-a504-a342787d416a'),
 ('812a924b-23f5-50d6-b21e-1493bc793d4b', 'c69d3daa-bbc3-594e-9e76-c875d3a7c2a3', '2026-27', 'application', 'EA', 'Early Action (non-binding) and priority scholarship consideration', '2026-12-01', 'Decision by Jan. 31; deposit due May 1. Dec. 1 is also the priority scholarship deadline. Same date on the international page. No year is printed; taken as fall 2027 entry.', '39344087-4e6f-5c0a-a504-a342787d416a'),
 ('9d62cb31-0f7e-562b-bcdc-320144622ac6', 'c69d3daa-bbc3-594e-9e76-c875d3a7c2a3', '2026-27', 'application', 'RD', 'Regular Decision / international fall semester deadline', '2027-02-01', 'International page lists ''Fall Semester (September): February 1'' for first-year international applicants, the same date as the domestic Regular Decision deadline; decisions by Mar. 31, deposit due May 1. The prior-year (2024-25) international fact sheet printed June 1 for regular decision, so the current page was used. No year is printed; taken as fall 2027 entry. URI has sometimes extended its regular deadline in past cycles, so confirm on the site.', 'fbe3c88f-a3de-59d8-8132-39f81ae91ce3'),
 ('3fb5b3a0-27b3-5394-b2dd-f77ba207dc95', 'c69d3daa-bbc3-594e-9e76-c875d3a7c2a3', '2026-27', 'financial_aid', null, 'FAFSA priority filing date', '2027-03-01', 'Applies to U.S. citizens/eligible noncitizens; international students are not eligible for need-based aid (CDS H5 priority date Mar. 1).', 'fbe3c88f-a3de-59d8-8132-39f81ae91ce3');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('c69d3daa-bbc3-594e-9e76-c875d3a7c2a3', 'required_nonnative', 'Applicants who attended a secondary or post-secondary school where the language of instruction is English may be exempt from an English proficiency exam, depending on their English grades (AP, IB, O level, A-level, GCSE, American curriculum) and SAT/ACT scores if submitted; decided case by case. Scores must be sent directly by the testing agency.', 'fbe3c88f-a3de-59d8-8132-39f81ae91ce3');
insert into english_requirements (institution_id, test_key, status, min_total, notes, source_id)
select 'c69d3daa-bbc3-594e-9e76-c875d3a7c2a3'::uuid, v.* from (values
 ('TOEFL_IBT', 'required_option', 79, 'From the prior-year (2024-25) international fact sheet; the current international page no longer prints an old-scale (0-120) number for general programs. 6-year Pharm.D.: 100.', '3c60d7f3-6a95-5d4e-8b6d-0d52d57c982b'::uuid),
 ('TOEFL_IBT_2026', 'required_option', 4.5, 'Current page prints ''TOEFL iBT: minimum score of 4.5'' (Pharm.D. 5.0) without naming the scale; 4.5 is on the new 1-6 scale. The same page also prints a Pharm.D. TOEFL minimum of 100 in another section.', 'fbe3c88f-a3de-59d8-8132-39f81ae91ce3'::uuid),
 ('IELTS', 'required_option', 6.5, '6-year Pharm.D.: 7.0.', 'fbe3c88f-a3de-59d8-8132-39f81ae91ce3'::uuid),
 ('DUOLINGO', 'required_option', 105, '6-year Pharm.D.: 125.', 'fbe3c88f-a3de-59d8-8132-39f81ae91ce3'::uuid),
 ('PTE', 'required_option', 53, 'PTE Academic or PTE Express. 6-year Pharm.D.: 68.', 'fbe3c88f-a3de-59d8-8132-39f81ae91ce3'::uuid),
 ('CAMBRIDGE', 'accepted', 176, 'Cambridge English Advanced, scores 176-184 (Pharm.D. 185-190). The page also accepts the Eiken test (completion of Pre-1).', 'fbe3c88f-a3de-59d8-8132-39f81ae91ce3'::uuid)) v;
