insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, ed_applicants, ed_admits, intl_applicants, intl_admits, in_state_applicants, in_state_admits, out_state_applicants, out_state_admits, waitlist_offered, waitlist_accepted, waitlist_admitted, pct_submit_sat, pct_submit_act, gpa_avg, pct_reporting_gpa, gpa_distribution, notes, source_id) values
 ('39006720-3c32-5bfb-9538-2bb95f2eec56', '2025-2026', 21609, 9056, 1231, 1129, 472, 7998, 1453, 4551, 2292, 9060, 5311, 1197, 741, 262, 15.7, 6.4, 3.73, 99.9, '{"4.0": 24.33, "3.75-3.99": 31.57, "3.50-3.74": 25.22, "3.25-3.49": 11.72, "3.00-3.24": 5.55, "2.50-2.99": 1.61}'::jsonb, 'Enrolled by residency: 432 in-state, 546 out-of-state, 253 international. Two ED rounds (11/1 closing with mid-December notification; 1/5 closing with early-February notification); ED counts are for the Fall 2025 entering class and almost one-third of the class applied ED. No early action. Test-optional for all applicants (C8F); only a small share of enrollees submitted scores, so SAT/ACT percentiles describe submitters.', '49cd3bf2-73a6-526c-acf2-dfeb5c32d2d1');
