insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, pct_submit_sat, pct_submit_act, notes, source_id, source_note) values
 ('4c6e3da1-17c6-5e94-bc46-4c846b434738', '2024-2025', 32840, 21768, 531, 23, 3, 'Baseline from IPEDS fall 2024 (College Navigator percentages; exact counts from the NCES ADM2024 file via the Urban Institute Education Data Portal). No Rutgers-Camden Common Data Set was found on the Rutgers or Camden sites, so international applicants/admits, GPA, SAT total and admission factors are not included. College Navigator prints 66% admitted and a 2% yield for these counts. SAT/ACT percentiles cover enrolled first-time students who submitted scores (SAT 23%, ACT 3%). Undergraduate enrollment 3,857 and nonresident-alien undergraduates 88 are IPEDS fall 2024 enrollment.', 'a570efd2-3b9d-5aed-ad88-ac7a0b1f191c', 'admissions_site');
insert into test_score_percentiles (institution_id, cds_year, source_id, test, p25, p50, p75)
select '4c6e3da1-17c6-5e94-bc46-4c846b434738'::uuid, '2024-2025', 'a570efd2-3b9d-5aed-ad88-ac7a0b1f191c'::uuid, v.* from (values
 ('SAT_ERW', 540, 600, 640),
 ('SAT_MATH', 510, 585, 660),
 ('ACT_COMPOSITE', 19, 22, 25)) v;
insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('4c6e3da1-17c6-5e94-bc46-4c846b434738', '2026-27', 'optional', 'Camden is test-optional (Rutgers states test-optional policies ''through 2027''); applicants who do not submit scores get full consideration. Exception: applicants to the BS/DO program must submit at least one ACT or SAT score.', '58cd447b-504b-5e00-b76f-ea064748f44a');
insert into application_requirements (institution_id, cycle, platforms, supplemental_essays, teacher_recs, counselor_rec, app_fee_usd, notes, source_id) values
 ('4c6e3da1-17c6-5e94-bc46-4c846b434738', '2026-27', array['common_app','own']::text[], 'A short original essay is required (Rutgers Application: 3,800 characters; Common App: 250-650 words).', 0, false, 70, 'Apply with the Rutgers Application or the Common App; the $70 non-refundable fee is the same on both. Letters of recommendation are ''not used'' for admission; activities are recommended. Current high school students report coursework through the STARS record. Per the Camden deadlines page, F-1 first-year fall 2027 applicants can enroll full-time in the College of Arts & Sciences, School of Business-Camden or School of Nursing-Camden. Financial documents (ISFS) are due after the offer is accepted, for the I-20.', '58cd447b-504b-5e00-b76f-ea064748f44a');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notification_date, notes, source_id) values
 ('aed3b142-ac9f-5cae-8467-8041b29c4276', '4c6e3da1-17c6-5e94-bc46-4c846b434738', '2026-27', 'application', 'EA', 'Early Action (non-binding), first-year fall 2027', '2026-11-01', '2027-01-31', 'Online decision January 31, 2027; candidate reply May 1, 2027. The page says ''These are not deadlines. You may apply after due dates have passed''; later applications are reviewed in the order received. Required credentials are due two weeks after the application due date. The page lists no separate international date.', '252dc828-5919-5928-9313-4d0b12d52e33'),
 ('3d469fac-64fc-5ccf-8935-c45fac548ca0', '4c6e3da1-17c6-5e94-bc46-4c846b434738', '2026-27', 'application', 'RD', 'Regular Decision, first-year fall 2027', '2026-12-01', '2027-02-28', 'Online decision February 28, 2027; candidate reply May 1, 2027. Not a hard deadline (see Early Action note). The page lists no separate international date.', '252dc828-5919-5928-9313-4d0b12d52e33'),
 ('faef81c7-4ffc-55d2-a629-c195f4aeb1b5', '4c6e3da1-17c6-5e94-bc46-4c846b434738', '2026-27', 'other', 'RD', 'Candidate reply date', '2027-05-01', null, 'Printed as the reply date for both plans; the earlier Rutgers page text says it is not a hard deadline and enrollment stays open while space remains.', '252dc828-5919-5928-9313-4d0b12d52e33');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('4c6e3da1-17c6-5e94-bc46-4c846b434738', 'required_nonnative', 'Required if secondary school was outside the U.S. in a country where English is not the primary language; scores must be under two years old. Waivers for English-medium schooling are decided case by case (email RUinternational@admissions.rutgers.edu after the application is complete). A B or better in a college-level English Composition course at an accredited U.S. college also exempts; ESL courses, courses taken outside the U.S. and correspondence/online courses do not. The page''s table also lists SAT EBRW 550, ACT English 21 and Michigan English Test 56 as accepted proof.', '8d19ce2c-4b04-5a3e-ab48-e5b57409bfaa');
insert into english_requirements (institution_id, source_id, test_key, status, min_total, notes)
select '4c6e3da1-17c6-5e94-bc46-4c846b434738'::uuid, '8d19ce2c-4b04-5a3e-ab48-e5b57409bfaa'::uuid, v.* from (values
 ('TOEFL_IBT', 'required_option', 79, 'Camden minimum for TOEFL iBT / Home Edition taken through January 21, 2026 (old 0-120 scale).'),
 ('TOEFL_IBT_2026', 'required_option', 4.0, 'Camden minimum for tests taken from January 22, 2026 (new 1-6 scale). Nursing requires 5.5 on the new scale (100 on the old scale).'),
 ('IELTS', 'required_option', 6.0, 'Camden minimum; New Brunswick and Newark are 6.5.'),
 ('DUOLINGO', 'required_option', 115, 'Nursing and Pharmacy require 130.'),
 ('PTE', 'required_option', 53, null),
 ('CAMBRIDGE', 'accepted', null, 'Cambridge Assessment test at level B2 (no numeric score printed).')) v;
insert into score_codes (institution_id, test_key, code, notes, source_id)
