insert into cost_aid (institution_id, year, tuition_usd, tuition_out_of_state_usd, room_board_usd, books_usd, other_usd, total_coa_usd, intl_aid_policy, merit_scholarships, notes, source_id) values
 ('4c6e3da1-17c6-5e94-bc46-4c846b434738', '2024-2025', 17764, 37276, 14376, 1418, 4458, 38016, 'merit_only', true, 'College Navigator 2024-25: tuition includes required fees; on-campus cost of attendance for New Jersey residents ($57,528 total at the out-of-state tuition rate).; Rutgers-Camden''s International Chancellor''s Scholarship goes to nonsponsored F-1 first-year and transfer students with no separate application. The two Camden pages disagree on size: the scholarships page says ''up to $17,000 per year'', while the dedicated scholarship page lists weighted-GPA tiers for first-years (2.8-3.19: $16,000; 3.2-3.69: $18,000; 3.7-4.0: $21,000 per year), renewable with a 2.5 GPA; confirm the current amount with the office. The scholarships page also lists a #YouAreWelcomeHere Scholarship covering a minimum of 50% of tuition for first-year international students. No need-based aid for international students is described.', 'a570efd2-3b9d-5aed-ad88-ac7a0b1f191c');
