insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, intl_applicants, intl_admits, in_state_applicants, in_state_admits, out_state_applicants, out_state_admits, notes, source_id) values
 ('e7989fe9-a980-51ae-b240-fddd56b72611', '2023-2024', 17779, 13997, 1408, 2211, 1550, 11913, 9612, 3655, 2835, 'CDS 2023-24 C1 (fall 2023 entering class; newest CDS Rutgers has posted for Newark, no 2024-25 or 2025-26 edition found). International: 2,211 applied, 1,550 admitted (70%), 29 enrolled. SAT/ACT percentiles and GPA (C9, C11, C12) are blank in the CDS; no waitlist policy; no early decision. College Navigator (IPEDS fall 2024) shows 36,793 applicants and 71% admitted, a much larger applicant count than the CDS, so the CDS figures are used here. Enrollment (7,989 undergraduates) and student-faculty ratio (14:1) are College Navigator fall 2024; the CDS has 7,417 and 13:1 for fall 2023.', 'aa941ea1-0044-54be-bf2e-ef1827e8fce5');
insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('e7989fe9-a980-51ae-b240-fddd56b72611', '2026-27', 'blind', 'Rutgers-Newark is test blind: SAT and ACT are not required and are not used for most undergraduate applicants. Only applicants to the Rutgers-Newark 7-year BA/MD joint-degree program must submit a score. Scores on file can be used for placement exemption (CDS). Rutgers states its test-optional and test-blind policies run through 2027.', 'a845621f-3bcc-5569-a631-c6862db2c398');
insert into application_requirements (institution_id, cycle, platforms, supplemental_essays, app_fee_usd, notes, source_id) values
 ('e7989fe9-a980-51ae-b240-fddd56b72611', '2026-27', array['common_app','own']::text[], 'A short original essay is required on the Rutgers Application or Common App (no Common App supplement); a short statement is needed to be considered for honors.', 70, '$70 non-refundable fee, same for Common App and Rutgers Application. Letters of recommendation are not used. International-school applicants self-report courses and grades in STARS; official documents are required of admitted students. Admitted students complete an I-20 financial statement (ISFS) with bank documentation. Open to F-1 first-year applicants for fall 2027 in Arts & Sciences, Rutgers Business School, School of Criminal Justice and School of Public Affairs and Administration (availability chart as of 2026-10-26).', 'a845621f-3bcc-5569-a631-c6862db2c398');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notification_date, notes, source_id) values
 ('122a48a4-7318-554b-a3a7-a1e2c04618aa', 'e7989fe9-a980-51ae-b240-fddd56b72611', '2026-27', 'application', 'EA', 'Early Action (non-binding), fall 2027', '2026-11-01', '2027-01-31', 'Dates apply to all first-year applicants including international; there is no separate international deadline. These are not hard cutoffs: you may apply later while the school still has space. Candidate reply date May 1, 2027.', '8a184ee6-755b-5854-9ca4-9a8997da3a67'),
 ('58b1282f-1f5c-5db7-b3d1-c8899465b188', 'e7989fe9-a980-51ae-b240-fddd56b72611', '2026-27', 'application', 'RD', 'Regular Decision, fall 2027', '2026-12-01', '2027-02-28', 'Decisions posted online no later than Feb 28, 2027; reply date May 1, 2027. Applications after Dec 1 are reviewed only while schools of application have not met enrollment goals. The CDS (fall 2023) described a Dec 1 priority date with rolling notification.', '8a184ee6-755b-5854-9ca4-9a8997da3a67'),
 ('25113f66-f830-5274-8dd9-7d7f453808fc', 'e7989fe9-a980-51ae-b240-fddd56b72611', '2026-27', 'deposit', 'RD', 'Candidate''s reply date (fall 2027)', '2027-05-01', null, 'Students admitted after May 1 must respond within one week of admission.', '8a184ee6-755b-5854-9ca4-9a8997da3a67');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('e7989fe9-a980-51ae-b240-fddd56b72611', 'required_nonnative', 'Required of all students whose secondary schooling was outside the U.S. in a country where English is not the principal language, regardless of residency status; scores must be from the past two years. May be waived case by case for English-medium schooling (email RUinternational@admissions.rutgers.edu). Exempt with a B or better in a college-level English Composition course at an accredited U.S. college (not ESL or online). Also accepted: SAT EBRW 550, ACT English 21, Michigan English Test 56. Nursing and pharmacy have higher minimums.', 'ee7b1ff9-8b89-5ffb-9c81-0863183ea04d');
insert into english_requirements (institution_id, source_id, test_key, status, min_total, notes)
