insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('095edeb3-f3f8-5647-ba8f-e2be1569a1cc', '2026-27', 'optional', 'Rutgers-New Brunswick is test optional (SAT/ACT optional; no disadvantage if not submitted); policy stated through 2027. SAT EBRW 650+ or ACT reading 28+ (if sent to Rutgers) exempts students from the English placement exam.', 'ac93cac2-00f8-5af3-a46c-c6a378e81a28');
insert into application_requirements (institution_id, cycle, platforms, supplemental_essays, teacher_recs, counselor_rec, notes, source_id) values
 ('095edeb3-f3f8-5647-ba8f-e2be1569a1cc', '2026-27', array['common_app','own']::text[], 'None. One short original essay inside the application (Common App 250-650 words, or 3,800 characters on the Rutgers Application); a short extra statement only if applying to Honors.', 0, false, 'Platforms: Common App or the Rutgers Application (own); submit only one. Letters of recommendation are not used. STARS self-reported transcript required for current seniors. Mason Gross School of the Arts requires a portfolio/audition/interview. Application fee amount not stated on the pages opened this session (left blank).', 'ac93cac2-00f8-5af3-a46c-c6a378e81a28');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notification_date, notes, source_id) values
 ('0058b486-e0d7-5ade-b2fd-9c5f23831471', '095edeb3-f3f8-5647-ba8f-e2be1569a1cc', '2026-27', 'application', 'EA', 'Early Action (non-binding), fall 2027', '2026-11-01', '2027-01-31', 'Decision by Jan 31: admitted, not admitted, wait list, or deferred to RD.', '0efdc29b-5985-527b-9367-cc539700f7b9'),
 ('b4b046c6-f64d-50f8-9d80-9b08b7a222cb', '095edeb3-f3f8-5647-ba8f-e2be1569a1cc', '2026-27', 'application', 'RD', 'Regular Decision, fall 2027', '2026-12-01', '2027-02-28', 'Must apply by Dec 1 to be considered for honors and merit scholarships. Later applications are reviewed on a space-available rolling basis. Mason Gross applicants hear by April 1.', '0efdc29b-5985-527b-9367-cc539700f7b9'),
 ('5839c44a-a663-5731-b421-e7579ed4bd8b', '095edeb3-f3f8-5647-ba8f-e2be1569a1cc', '2026-27', 'deposit', 'RD', 'Candidate reply date', '2027-05-01', null, 'Applies to both EA and RD admits.', '0efdc29b-5985-527b-9367-cc539700f7b9');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('095edeb3-f3f8-5647-ba8f-e2be1569a1cc', 'required_nonnative', 'Required for applicants whose secondary schooling was outside the U.S. in a country where English is not the principal language. Case-by-case waivers for English-medium schooling (RUinternational@admissions.rutgers.edu); B or better in a U.S. college English Composition course also exempts. Alternative qualifying scores: SAT EBRW 550, ACT English 21, MET 56. Scores must be under two years old and sent directly by the testing agency.', '5e83d2f4-1421-5d21-bfe3-5ed5a06415d5');
