 ('04325ef0-6ea9-52ce-b80a-788630682c47', '302d28db-3a67-5e2c-8054-f4983c2aa253', 'ipeds', 'IPEDS via NCES College Navigator - Sacramento State admissions considerations (fall 2024)', 'https://nces.ed.gov/collegenavigator/?id=110617', '2024-2025', '2026-10-26');
insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, notes, source_id, source_note) values
 ('302d28db-3a67-5e2c-8054-f4983c2aa253', '2023-2024', 25994, 24336, 3884, 'Baseline from IPEDS (fall 2023 first-time, first-year class); College Navigator also shows fall 2024: 27,702 applicants, 94% admitted, 15% of admitted students enrolled (percentages are rounded). The newest Sacramento State Common Data Set found online is 2022-2023, so it was not used. Undergraduate enrollment and international (nonresident) undergraduates are IPEDS fall 2023 totals. Applications by residency (international applicants and admits), GPA and score ranges are not in IPEDS, so they are left null. The CSU is test-blind, so no SAT/ACT percentiles are reported.', '1ddd52d4-ac15-5c3c-bbf8-e447fa7b4d2a', 'admissions_site');
insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('302d28db-3a67-5e2c-8054-f4983c2aa253', '2026-27', 'blind', 'The CSU system no longer uses SAT/ACT in admission decisions; College Navigator (IPEDS fall 2024 admissions) lists SAT/ACT as ''Not considered (Test Blind)''. Sacramento State''s international page lists no SAT/ACT requirement.', '04325ef0-6ea9-52ce-b80a-788630682c47');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('302d28db-3a67-5e2c-8054-f4983c2aa253', '2026-27', array['own']::text[], 70, 'Apply through Cal State Apply; $70 non-refundable fee by credit/debit card or PayPal. Needs a high school transcript with at least 3.0 on a 4.0 scale (or 80% average) and the diploma. Upload scanned PDFs through the International Admission Documents portal; unofficial transcripts and scores are fine at first. Passport copy required. Proof of funds is not needed for review but is strongly encouraged to avoid I-20 delays. Credential evaluations are not required (WES, ACEI or ECE only if submitted). College Navigator shows essays and recommendations are not considered.', '20aa5749-c6fd-5d4a-b7a3-5aaf28c314c1');
insert into deadlines (id, institution_id, cycle, kind, label, due_date, notes, source_id) values
 ('ec4ebf3b-0b89-5763-ad60-88ca3ecd17f6', '302d28db-3a67-5e2c-8054-f4983c2aa253', '2026-27', 'application', 'International application deadline, Cal State Apply (fall 2027)', '2027-05-15', 'Fall 2027 filing period is Oct 1, 2026 to May 15, 2027. Late-application appeals are accepted through June 15.', '20aa5749-c6fd-5d4a-b7a3-5aaf28c314c1'),
 ('47a76f40-b540-58bb-93cc-08c14a7e953c', '302d28db-3a67-5e2c-8054-f4983c2aa253', '2026-27', 'other', 'International document deadline (fall 2027)', '2027-05-30', null, '20aa5749-c6fd-5d4a-b7a3-5aaf28c314c1');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('302d28db-3a67-5e2c-8054-f4983c2aa253', 'required_nonnative', 'One option required. Sacramento State publishes a PDF list of countries where TOEFL/IELTS is waived (not read). MyBest TOEFL scores are not accepted; scores must come from the testing provider''s portal. Also accepted: GTEC 1125, Sacramento State English Language Institute Level 7, ELS Level 112, FLS Level 16, TLC Level 9, UCLA Extension Level 6. Cambridge exams are not listed.', '20aa5749-c6fd-5d4a-b7a3-5aaf28c314c1');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
select '302d28db-3a67-5e2c-8054-f4983c2aa253'::uuid, 'required_option', '20aa5749-c6fd-5d4a-b7a3-5aaf28c314c1'::uuid, v.* from (values
 ('TOEFL_IBT', 64, 'Tests taken before Jan 21, 2026. ETS code 4671.'),
 ('TOEFL_IBT_2026', 3.5, 'Tests on or after Jan 21, 2026; the page prints ''3.5 IBT'', which appears to be the 1-6 scale (verify with the university).'),
 ('IELTS', 6.0, null),
 ('DUOLINGO', 95, null),
 ('PTE', 50, 'PTE Academic.')) v;
