insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, intl_applicants, intl_admits, in_state_applicants, in_state_admits, out_state_applicants, out_state_admits, gpa_avg, pct_reporting_gpa, gpa_distribution, notes, source_id) values
 ('80e21a51-1e05-5d4a-ab42-e214dfd62d08', '2025-2026', 11586, 9087, 1336, 1558, 1093, 9532, 7650, 496, 344, 3.55, 94.09, '{"4.0": 19.89, "3.75-3.99": 22.28, "3.50-3.74": 17.74, "3.25-3.49": 13.37, "3.00-3.24": 11.3, "2.50-2.99": 12.17, "2.0-2.49": 3.18, "1.0-1.99": 0.08}'::jsonb, 'CDS C1 (fall 2025), residency rows: in-state 9,532 applied / 7,650 admitted / 1,231 enrolled; out-of-state 496 / 344 / 36; international 1,558 / 1,093 / 69 (70% admitted). No waitlist, early decision or early action; no application closing date (rolling). SVSU reports test-blind admissions, so C9 SAT/ACT percentiles and percent submitting are blank and no scores are stored. Undergrad and international counts are B1/B2 ''Total undergraduates'' (6,280; nonresident 252). Student-faculty ratio is the Fall 2025 value from I-2 (16.3).', 'd6f9edff-9f8c-5fb2-b7b0-76cb8ed7903a');
