insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, intl_applicants, intl_admits, in_state_applicants, in_state_admits, out_state_applicants, out_state_admits, gpa_avg, gpa_distribution, notes, source_id) values
 ('ab42e913-a9fd-5154-826f-3ba040325674', '2023-2024', 4289, 3803, 503, 518, 370, 2873, 2650, 898, 783, 3.6, '{"4.0": 24.5, "3.75-3.99": 17.9, "3.50-3.74": 17.7, "3.25-3.49": 17.1, "3.00-3.24": 13.3, "2.50-2.99": 9.3, "2.0-2.49": 0.2, "1.0-1.99": 0.0}'::jsonb, 'Fall 2023 first-years from the 2023-24 CDS, the newest edition readable as text: the 2024-25 and 2025-26 CDS PDFs are on a Google Drive link (the 2025-26 one asks for a sign-in; the 2024-25 one has numbers that cannot be extracted as text), so they were not used. CDS C1 residency table: in-state 2,873 applied / 2,650 admitted / 421 enrolled, out-of-state 898 / 783 / 66, international 518 / 370 / 16; total 4,289 / 3,803 / 503. GPA distribution is the ''all enrolled students'' column of C11 as printed; average GPA is printed to one decimal (3.6). SAT/ACT percentiles, percent submitting scores and the C7 factor checkboxes could not be extracted as text, so they are left out. College Navigator fall 2024 (newer): 5,175 applicants, 87% admitted, 9% of admitted enrolled; undergraduate enrollment 1,954 and student-faculty ratio 10:1 are from College Navigator fall 2024. Saint Mary''s is test-optional.', '099faccc-7ba0-59cd-92c2-95670ee554ea');
insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('ab42e913-a9fd-5154-826f-3ba040325674', '2026-27', 'optional', 'Saint Mary''s College ''will not require an SAT or ACT score for college admission''; submitting scores is optional. For international applicants the SAT (450+ EBRW) and ACT (21+) can also be used in place of an English test.', '3a978d5e-d65a-5a8b-bd3a-be32f0613185');
insert into application_requirements (institution_id, cycle, platforms, notes, source_id) values
 ('ab42e913-a9fd-5154-826f-3ba040325674', '2026-27', array['common_app']::text[], 'Apply through the Common App. Unofficial transcripts can be uploaded to the applicant status page for review (official final transcript required once admitted); transcripts in other languages need English translations; applicants from systems with external exams ((I)GCSE/A levels, CBSE, WAEC, etc.) must submit those results. Letters of recommendation are optional but encouraged. A Certificate of Finances signed by the student and any sponsor, with a passport copy and financial documents, is required; the page gives no dollar amount. The application fee is not stated on the pages reviewed (the 2023-24 CDS listed $60 for the Fall 2025 cycle).', 'dd1af003-78c8-5c13-8806-935102b6550d');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('d51a2ac7-b7d7-5819-9ca5-b17ca9f3a3d6', 'ab42e913-a9fd-5154-826f-3ba040325674', '2026-27', 'application', 'EA', 'Fall term Early Action (fall 2027 entry)', '2026-11-01', 'Non-binding. The page prints Nov. 1 without a year; taken as fall 2027 entry. Same dates are listed on the international page.', 'dd1af003-78c8-5c13-8806-935102b6550d'),
 ('d6b7e446-0c3c-5fa5-8964-f805159c3e5c', 'ab42e913-a9fd-5154-826f-3ba040325674', '2026-27', 'application', 'RD', 'Fall term Regular Decision (fall 2027 entry)', '2027-01-15', 'The page prints Jan. 15 without a year; taken as fall 2027 entry. A Dec. 1 deadline is also listed for spring term.', 'dd1af003-78c8-5c13-8806-935102b6550d');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('ab42e913-a9fd-5154-826f-3ba040325674', 'required_nonnative', 'Applicants from countries on the college''s exempt list are waived. Applicants whose medium of instruction was English for all years of high school may also be waived, subject to verification by an admissions counselor after the transcript is submitted. Accepted alternatives to a test: ELS Language Center Level 112 with a 2.75 GPA or higher, SAT 450+ in Evidence-Based Reading and Writing, ACT 21+. All scores must be taken within 2 years of the application. No conditional admission or ESL pathway is mentioned on the page.', 'dd1af003-78c8-5c13-8806-935102b6550d');
insert into english_requirements (institution_id, source_id, test_key, status, min_total, notes)
select 'ab42e913-a9fd-5154-826f-3ba040325674'::uuid, 'dd1af003-78c8-5c13-8806-935102b6550d'::uuid, v.* from (values
 ('TOEFL_IBT', 'required_option', 80, 'For tests taken before January 2026.'),
 ('TOEFL_IBT_2026', 'required_option', 4, 'The page prints ''4 iBT'' for tests taken after January 2026 without naming the scale; it appears to be the new 1-6 scale.'),
 ('IELTS', 'required_option', 6.5, '6.5 or higher.'),
 ('DUOLINGO', 'required_option', 105, '105 or higher.'),
 ('CAMBRIDGE', 'accepted', null, 'Level C1 or higher; no numeric score is printed. PTE is not listed on the page.')) v;
