select 'ab42e913-a9fd-5154-826f-3ba040325674'::uuid, v.* from (values
 ('sat', '4675', 'The first-year admissions page prints the SAT school code as 004675.', '3a978d5e-d65a-5a8b-bd3a-be32f0613185'::uuid),
 ('act', '0386', 'ACT school code.', '3a978d5e-d65a-5a8b-bd3a-be32f0613185'::uuid),
 ('toefl', null, 'No TOEFL institution code is printed on the pages reviewed; confirm with admissions before sending.', 'dd1af003-78c8-5c13-8806-935102b6550d'::uuid),
