insert into cost_aid (institution_id, year, tuition_usd, required_fees_usd, room_board_usd, books_usd, other_usd, total_coa_usd, intl_aid_policy, intl_need_aid_awarded, intl_avg_award_usd, meets_full_need, merit_scholarships, notes, source_id) values
 ('ab42e913-a9fd-5154-826f-3ba040325674', '2026-2027', 61416, 636, 18900, 1304, 5356, 87612, 'merit_only', 64, 51482, false, true, 'Saint Mary''s own 2026-27 cost of attendance for a full-time, on-campus, non-nursing undergraduate: tuition $61,416 (12-18 units per semester) + fees $636 (student body $216, student enhancement $320, student experience $100) + food and housing $18,900 + books $1,304 + personal expenses $3,970 and transportation $1,386 (other_usd $5,356) = $87,612 as printed. Nursing (BSN) tuition is $76,770, total $102,330. The tuition_usd figure is the sticker price before merit aid. CDS 2023-24 H6 (aid year 2022-23): 64 undergraduate degree-seeking nonresidents received institutional aid, average $51,482 (total $3,294,877); the policy checkboxes are not readable as text.; International first-year merit scholarships are decided at acceptance, need no separate form, and are automatically applied for four consecutive years of full-time study (renewal depends on satisfactory academic progress). The international scholarships page says awards range from $2,000 to $38,000 per academic year; the international admissions page says $2,000 to $29,000. The page lists no per-award table. Departmental scholarships of $5,000 per year are available to selected incoming first-years. The pages do not say whether international students can receive need-based aid.', '649c64b1-51f9-54c9-8c5d-93e7aec64e2f');
insert into institution_tiers (institution_id, category_key, tier_code, rationale) values
 ('ab42e913-a9fd-5154-826f-3ba040325674', 'general', 'D', 'Admit rate 88.7%');

