insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, notes, source_id, source_note) values
 ('5063c0d2-67d6-5c06-985d-9fe988c5971d', '2023-2024', 4381, 3966, 454, 'Baseline from IPEDS ADM2023 (fall 2023 entering class; exact counts). No Common Data Set was found on saintpeters.edu or by web search (the Fact Book is behind a login), so there is no international split, GPA or SAT/ACT data; Saint Peter''s reports no SAT/ACT percentiles to IPEDS (test-optional). College Navigator fall 2024: 5,217 applicants, 90% admitted, 11% of admits enrolled (admit counts not shown).', '9e84c538-395a-5575-b000-744c6cc3c221', 'admissions_site');
insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('5063c0d2-67d6-5c06-985d-9fe988c5971d', '2026-27', 'optional', 'First-year applicants may choose not to submit SAT/ACT. Scores are still required for candidates for high merit scholarships, pre-professional joint programs and home-schooled students unless waived. Scores that are submitted are also used for placement.', '1b309cea-4318-5110-bd91-4c0427877f3c');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('5063c0d2-67d6-5c06-985d-9fe988c5971d', '2026-27', array['common_app','own']::text[], 0, 'Apply with the Common Application or the Saint Peter''s International Student Application (PDF). No application fee (international FAQ). Required: transcripts with English translation sent directly from the school or an EducationUSA advisor, one recommendation, a short essay/personal statement, proof of English proficiency, plus I-20 financial support statement and passport copy. $150 non-refundable tuition deposit after admission. Decisions are typically within 2-3 weeks of a complete file (FAQ and catalog).', '20d22346-c360-561c-94ea-87347657b176');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('ce372ef4-1ffc-512d-b191-c93129266f11', '5063c0d2-67d6-5c06-985d-9fe988c5971d', '2026-27', 'application', 'ROLLING', 'International fall application deadline (fall 2027 entry)', '2027-06-01', 'International FAQ: June 1 for fall and November 1 for spring. The undergraduate catalog instead says August 1 for fall (one month before the term), so the pages disagree; the page prints no year, so treated as fall 2027. Late applications may be considered as time permits; applying at least three months ahead is recommended.', '9e910ecd-be91-5be5-86df-83f182909ac9'),
 ('f1aa4b08-b48b-592b-85e6-d8b6bd54bca3', '5063c0d2-67d6-5c06-985d-9fe988c5971d', '2026-27', 'other', 'ROLLING', 'Catalog international fall deadline (fall 2027 entry)', '2027-08-01', 'Undergraduate catalog date; conflicts with the June 1 date on the international FAQ. Confirm with intadmission@saintpeters.edu.', '1b309cea-4318-5110-bd91-4c0427877f3c');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('5063c0d2-67d6-5c06-985d-9fe988c5971d', 'required_nonnative', 'Students whose native language is not English must submit one approved English test sent directly from the testing agency. In lieu of TOEFL/IELTS, SAT EBRW 510+ or ACT English and Writing 19+ in each section is accepted (the catalog still says SAT Critical Reading 450+, so the pages differ). Also accepted: ELS course completion with score 112, Kaplan Advanced Level, FLS level 15. TOEFL may be waived by the Dean of International Enrollment; the FAQ says citizens of Canada, Australia, Ireland, New Zealand and the UK may be exempt. No conditional-admission or on-campus ESL pathway is described.', '20d22346-c360-561c-94ea-87347657b176');
insert into english_requirements (institution_id, test_key, status, min_total, notes, source_id)
select '5063c0d2-67d6-5c06-985d-9fe988c5971d'::uuid, v.* from (values
 ('TOEFL_IBT', 'required_option', 79, 'Exams taken before January 21, 2026.', '20d22346-c360-561c-94ea-87347657b176'::uuid),
 ('TOEFL_IBT_2026', 'required_option', 4, 'Exams taken on or after January 21, 2026; the page prints "4" without naming the scale (presumably the new 1-6 scale).', '20d22346-c360-561c-94ea-87347657b176'::uuid),
 ('PTE', 'required_option', 53, 'Pearson PTE Academic or Pearson Express test.', '20d22346-c360-561c-94ea-87347657b176'::uuid),
 ('IELTS', 'accepted', null, 'The page and FAQ say IELTS scores are accepted (sent directly by the British Council, IDP or Cambridge) but print no minimum score.', '9e910ecd-be91-5be5-86df-83f182909ac9'::uuid)) v;
