insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('d32b990a-4357-5a99-81ab-626a5c04dcbe', '2026-27', 'blind', 'SJSU (a CSU campus) does not use SAT/ACT in admission decisions; the CDS C8A marks them ''not considered''. SJSU''s international steps page still says SAT/ACT scores are ''encouraged'' (Step 9, optional), which conflicts with the CDS; treat scores as not needed. Admission is based on a converted U.S. GPA of at least 3.0 plus college-prep course requirements.', 'a388079b-d1fe-537b-8b1c-8f83619a1c57');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('d32b990a-4357-5a99-81ab-626a5c04dcbe', '2026-27', array['own']::text[], 70, 'Apply through Cal State Apply (not the Common App). No essays or recommendations are used (CDS C7). Needs a converted U.S. GPA of 3.0+, 4 years of college-prep English (if English is the medium of instruction) and 3 years of college-prep math with C- or better, and partial official high school transcripts; final transcripts due July 15, 2027. All majors are impacted, so some require a higher GPA than 3.0. Animation and Illustration applicants add three drawing exercises.', 'a388079b-d1fe-537b-8b1c-8f83619a1c57');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('4da0ff50-745a-59ad-8eee-e14eb1765437', 'd32b990a-4357-5a99-81ab-626a5c04dcbe', '2026-27', 'application', 'ROLLING', 'International first-year application deadline, Cal State Apply (fall 2027)', '2027-04-01', 'Cal State Apply opens Aug 1, 2026 and submissions open Oct 1, 2026; the domestic first-year deadline is Nov 30, 2026 but international first-year applicants have until Apr 1, 2027. Partial transcripts due Mar 23, 2027. CDS C16: admission decisions are sent on a rolling basis beginning Feb 15, so earlier is safer because majors can fill.', 'c51a5743-e615-5535-ab03-e04f0162c836'),
 ('c31659dd-fb2d-568e-bd66-abc4dc8d0038', 'd32b990a-4357-5a99-81ab-626a5c04dcbe', '2026-27', 'other', null, 'International document deadline', '2027-05-02', 'Outstanding documents and English test scores on the MySJSU To Do List are due by this date.', 'c51a5743-e615-5535-ab03-e04f0162c836'),
 ('b7927999-4e84-5472-b5af-a225b8b7aca3', 'd32b990a-4357-5a99-81ab-626a5c04dcbe', '2026-27', 'deposit', null, 'Intent to Enroll deadline and orientation fee', '2027-05-01', 'Housing application deadline is also May 1 ($50 application fee and $300 initial payment).', 'c51a5743-e615-5535-ab03-e04f0162c836');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('d32b990a-4357-5a99-81ab-626a5c04dcbe', 'required_nonnative', 'Required if the school''s medium of instruction is not English. Waived with 60 semester/90 quarter transferable units at a U.S. college, 3 years of full-time study at a U.S. college, or 3 years full-time at an institution where English is the primary language of instruction; ''O'' level exams passed in one sitting (5 subjects incl. Math and English, not ESL English) also waive the test. Scores older than 2 years are not valid and must be sent electronically by the testing center.', 'e942f6d3-255c-529c-95be-6a9b322f412e');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
select 'd32b990a-4357-5a99-81ab-626a5c04dcbe'::uuid, 'required_option', 'e942f6d3-255c-529c-95be-6a9b322f412e'::uuid, v.* from (values
 ('TOEFL_IBT', 61, 'Tests taken before Jan 21, 2026 (0-120 scale), non-engineering majors. All Engineering majors: 80. TOEFL Home Edition accepted.'),
 ('TOEFL_IBT_2026', 3.5, 'Exams on/after Jan 21, 2026 (1-6 scale), non-engineering majors. All Engineering majors: 4.'),
 ('IELTS', 6.0, 'Engineering: 6.5.'),
 ('DUOLINGO', 95, 'No separate Engineering minimum is listed.'),
 ('PTE', 44, 'Engineering: 53.')) v;
insert into score_codes (institution_id, test_key, code, notes, source_id)
select 'd32b990a-4357-5a99-81ab-626a5c04dcbe'::uuid, v.* from (values
 ('sat', '4687', 'SJSU school code for SAT results (SAT is not used in admission decisions).', 'e942f6d3-255c-529c-95be-6a9b322f412e'::uuid),
 ('act', null, 'ACT scores are not used in admission and no ACT code is listed on SJSU''s admissions pages.', 'cc481932-e8fd-52a3-8474-6d14d8b3d986'::uuid),
 ('toefl', '4687', 'SJSU school code for TOEFL results; scores must be sent electronically by ETS after you submit the Cal State Apply application.', 'e942f6d3-255c-529c-95be-6a9b322f412e'::uuid),
 ('ielts', null, 'Submit IELTS through your Cal State Apply application (no SJSU-specific code).', 'e942f6d3-255c-529c-95be-6a9b322f412e'::uuid),
 ('duolingo', null, 'No institution code is listed.', 'e942f6d3-255c-529c-95be-6a9b322f412e'::uuid),
 ('pte', null, 'No institution code is listed.', 'e942f6d3-255c-529c-95be-6a9b322f412e'::uuid)) v;
insert into cost_aid (institution_id, year, tuition_usd, tuition_out_of_state_usd, tuition_intl_usd, required_fees_usd, room_board_usd, books_usd, other_usd, total_coa_usd, intl_aid_policy, intl_need_aid, intl_need_aid_awarded, intl_avg_award_usd, meets_full_need, merit_scholarships, notes, source_id) values
 ('d32b990a-4357-5a99-81ab-626a5c04dcbe', '2026-2027', 6838, 20968, 20968, 2715, 22912, 1004, 4021, 51865, 'merit_only', false, 103, 9127, false, true, 'Computed from published rates: full-time undergraduate tuition $3,419 per semester plus nonresident tuition $471 per unit (Fall 2026 and Spring 2027), assuming 15 units a term; fees from the Bursar page. Room and board is campus housing $15,543 plus food $7,369; other = transportation $1,121 plus personal $2,900 (SJSU 2026-27 budget, marked draft). Total = SJSU''s $37,735 campus-housing budget plus $14,130 nonresident tuition (30 units). International students must also buy CSU-provided health insurance (cost not found).; CDS H6: 103 degree-seeking nonresident undergraduates received institutional aid (avg $9,127, total $940,096). CDS G1 tuition and fee fields were left blank, so costs come from SJSU''s Bursar and financial aid office pages (see cost notes).; SJSU''s financial aid office says international students are eligible only for merit-based scholarships; need-based aid is unavailable to them. No amounts or international-specific scholarship names are published on that page. SJSU''s international-programs page also mentions International Gateways, which offers academic and TOEFL preparation courses on campus; no conditional-admission pathway is described on the page.', '511ab863-8190-52e7-828a-f14dd068cd4c');
