insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('e4ff3ae7-8bc6-5099-bfc3-cef5bc8b0fb5', '2026-27', 'optional', 'SCAD is test-optional: SAT/ACT scores may be submitted but applications without them are considered, and lack of scores does not affect admission or scholarship consideration.', '42472d97-52d3-5207-91f6-c018b3664d5c');
insert into application_requirements (institution_id, cycle, platforms, supplemental_essays, portfolio, app_fee_usd, notes, source_id) values
 ('e4ff3ae7-8bc6-5099-bfc3-cef5bc8b0fb5', '2026-27', array['own','common_app']::text[], 'Statement of purpose (max 500 words) is optional supplementary material; the International Student Scholarship needs a 500-word essay.', 'Not required for undergraduate admission, but strongly encouraged: a portfolio, audition or writing submission is scored on a rubric and can make a student eligible for achievement/honors scholarships. See SCAD portfolio guidelines for each major.', 100, 'Apply on SCAD''s online application ($100 non-refundable) or the Common App; there is also a one-time $500 enrollment fee after admission. Required: unofficial high school transcripts or mark sheets (official ones before Aug. 1 for fall) and English proficiency evidence if the first language is not English. Recommendations, achievement profile and interview are optional. No minimum GPA is published; SCAD gives preference to a 3.0 GPA or above, and applicants below that are encouraged to add supplementary materials.', '42472d97-52d3-5207-91f6-c018b3664d5c');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, notes, source_id) values
 ('64198700-284d-50e1-b66c-aca8149d62b3', 'e4ff3ae7-8bc6-5099-bfc3-cef5bc8b0fb5', '2026-27', 'application', 'ROLLING', 'Rolling admission: no application deadline (fall 2027)', 'SCAD accepts applications year-round for fall (September), winter, spring and summer quarters; decisions take about 2-4 weeks. Apply at least 30 days before the start of the quarter, and ideally six months ahead to arrange financial aid and a visa. International scholarship funds are limited and go to the earliest qualifiers.', 'b85b5652-8d0c-5e78-a5fe-343d4f30b02b');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('e4ff3ae7-8bc6-5099-bfc3-cef5bc8b0fb5', 'recommended', 'English proficiency evidence is requested from non-native speakers, but a student below these scores can still be admitted and will take the SCAD Language Studio (SLS) placement test at international orientation to decide ESL classes. The ESL waiver is granted for the scores below, SAT reading 550+ or ACT reading 22+ and writing 8+, full secondary study in English-medium schools, or SLS completion within two years. Scores must come from one test sitting; TOEFL MyBest and superscoring are not accepted. Meeting the composite but not a section minimum is reviewed case by case; no exception if the composite is missed.', '42472d97-52d3-5207-91f6-c018b3664d5c');
insert into english_requirements (institution_id, status, source_id, test_key, recommended_total, min_subscores, notes)
select 'e4ff3ae7-8bc6-5099-bfc3-cef5bc8b0fb5'::uuid, 'recommended_option', '42472d97-52d3-5207-91f6-c018b3664d5c'::uuid, v.* from (values
 ('TOEFL_IBT', 85, '{"each_section": 20}'::jsonb, 'ESL waiver score for tests taken before Jan. 21, 2026.'),
 ('TOEFL_IBT_2026', 4.5, '{"listening": 4.0, "speaking": 4.0, "reading": 4.5, "writing": 4.5}'::jsonb, 'ESL waiver score for tests taken on or after Jan. 21, 2026 (1-6 scale).'),
 ('IELTS', 6.5, '{"reading": 6.5, "writing": 6.5}'::jsonb, null),
 ('DUOLINGO', 120, '{"listening": 115, "speaking": 115, "reading": 120, "writing": 120}'::jsonb, 'Section scores are minimums (Reading and Writing 120-125, Listening and Speaking 115-120).')) v;
insert into score_codes (institution_id, test_key, code, notes, source_id)
select 'e4ff3ae7-8bc6-5099-bfc3-cef5bc8b0fb5'::uuid, v.* from (values
 ('sat', '5631', 'SCAD SAT code (also the AP code).', '6c77bbb4-fd36-5dd1-bec6-8e6cf45c1454'::uuid),
 ('act', '0855', 'SCAD ACT code.', '6c77bbb4-fd36-5dd1-bec6-8e6cf45c1454'::uuid),
 ('toefl', '5631', 'SCAD TOEFL institution code; request scores be sent directly to SCAD. TOEFL MyBest is not accepted.', '6c77bbb4-fd36-5dd1-bec6-8e6cf45c1454'::uuid),
 ('ielts', null, 'No IELTS institution code is listed.', '6c77bbb4-fd36-5dd1-bec6-8e6cf45c1454'::uuid),
 ('duolingo', null, 'No institution code is listed.', '42472d97-52d3-5207-91f6-c018b3664d5c'::uuid)) v;
insert into cost_aid (institution_id, year, tuition_usd, tuition_intl_usd, required_fees_usd, intl_extra_fees_usd, intl_aid_policy, intl_need_aid, meets_full_need, merit_scholarships, notes, source_id) values
 ('e4ff3ae7-8bc6-5099-bfc3-cef5bc8b0fb5', '2026-2027', 42975, 42975, 125, 1417, 'merit_only', false, false, true, 'Full-time tuition $14,325 per quarter ($42,975 for three quarters, 15 credit hours). $125 annual student health fee (Savannah campus); mandatory international student health insurance $1,417 for Sept. 1, 2026 - Aug. 31, 2027. Housing in Savannah about $10,065-$18,849 per year plus a $750 application fee; meal plans $1,575-$6,750 per year (not summed into a room and board figure). One-time $500 enrollment fee and $100 application fee.; International students are not eligible for U.S. federal or state aid. Every admitted student is automatically reviewed for institutional scholarships (Academic, Achievement, Honors with a 3.5+ GPA or outstanding portfolio, Distinguished Scholars by nomination), and an International Student Scholarship needs a 500-word essay. Funds are limited and go to the earliest qualifiers; amounts are not published on the pages reviewed. Awards renew with a 3.0 GPA.', '859b8cd0-258d-5a7f-b72e-bf5703f1f444');
insert into institution_tiers (institution_id, category_key, tier_code, rationale)
select 'e4ff3ae7-8bc6-5099-bfc3-cef5bc8b0fb5'::uuid, v.* from (values
 ('general', 'D', 'Admit rate 83.0%'),
 ('arts_design', 'B', 'Editorial estimate: SCAD is one of the largest US art and design universities with well-known animation, film, illustration, fashion and design programs; no ranking cited, so placed in the 16-40 band.')) v;

