insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, notes, source_id, source_note) values
 ('720ca07a-12a9-5a94-b4f8-0b86eb412882', '2023-2024', 29878, 28727, 2985, 'Baseline from IPEDS (fall 2023 first-time, first-year class); College Navigator also shows fall 2024: 28,221 applicants, 96% admitted, 9% of admitted students enrolled (percentages are rounded). No current Common Data Set was found on ir.sfsu.edu or air.sfsu.edu. Undergraduate enrollment and international (nonresident) undergraduates are IPEDS fall 2023 totals. Applications by residency (international applicants and admits), GPA and score ranges are not in IPEDS, so they are left null. The CSU is test-blind, so no SAT/ACT percentiles are reported.', 'f2042ee8-9edc-5698-be4b-f5c8d8036d52', 'admissions_site');
insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('720ca07a-12a9-5a94-b4f8-0b86eb412882', '2026-27', 'blind', 'SF State''s admissions page says the CSU no longer uses ACT/SAT in determining admission eligibility; College Navigator lists SAT/ACT as ''Not considered (Test Blind)''. SAT ERW 550 or ACT English 22 can only be used to show English proficiency.', 'b6548f86-8359-5cc8-8775-5f424859eef5');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('720ca07a-12a9-5a94-b4f8-0b86eb412882', '2026-27', array['own']::text[], 70, 'Apply through Cal State Apply (not the Common App); $70 fee by credit card or PayPal. For a high school outside the U.S.: 12 years of schooling, eligible for university entry at home, and a 2.5 GPA (B- average) in academic courses after 9th grade; A-G coursework applies to U.S. high school graduates (non-California residents need a 3.0 GPA). Impacted majors are evaluated on supplemental factors. I-20 documents: Financial Affidavit, proof of finances, passport copy. Credential evaluations from third-party companies are not accepted. College Navigator shows essays and recommendations are not considered.', 'b6548f86-8359-5cc8-8775-5f424859eef5');
insert into deadlines (id, institution_id, cycle, kind, label, due_date, notes, source_id) values
 ('7ecc1ba9-3ff3-59c5-be00-4a1c3fa6e12b', '720ca07a-12a9-5a94-b4f8-0b86eb412882', '2026-27', 'application', 'International application deadline (fall 2027)', '2027-05-01', 'Cal State Apply opened Aug 1, 2026; submissions begin Oct 1, 2026. International applicants have until May 1, 2027, but majors may fill: the Nov 30, 2026 priority date applies to impacted majors.', '1afd4995-5946-5fcf-b926-4b6bc642caa6'),
 ('4bfc6dcb-7f16-51c7-a2d5-c714a60b6729', '720ca07a-12a9-5a94-b4f8-0b86eb412882', '2026-27', 'priority', 'Application priority deadline for impacted majors', '2026-11-30', 'Listed on the same table; the international deadline is the later May 1, 2027 date.', '1afd4995-5946-5fcf-b926-4b6bc642caa6'),
 ('696ffc6e-5d9e-5e3d-b2ec-7b980f253dbe', '720ca07a-12a9-5a94-b4f8-0b86eb412882', '2026-27', 'deposit', 'Accept admission offer and pay enrollment confirmation deposit', '2027-05-01', null, '1afd4995-5946-5fcf-b926-4b6bc642caa6'),
 ('9f9c32a6-c673-5bcb-a85c-e72112634676', '720ca07a-12a9-5a94-b4f8-0b86eb412882', '2026-27', 'other', 'Final official transcripts due', '2027-07-15', null, '1afd4995-5946-5fcf-b926-4b6bc642caa6');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('720ca07a-12a9-5a94-b4f8-0b86eb412882', 'required_nonnative', 'Required of all undergraduate applicants unless they attended a U.S. high school 3+ years or show 3 years of full-time study in a listed English-instruction country (e.g. Australia, Canada, England, Ireland, New Zealand, Scotland, Wales, South Africa, Jamaica, Kenya, Ghana). Alternatives: SAT ERW 550, ACT English 22, IB English A HL 4, AP English Language or Literature 3. TOEFL Home Edition and IELTS Indicator are accepted.', 'b6548f86-8359-5cc8-8775-5f424859eef5');
