insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('f8633771-8100-5f47-a466-08a6399a6520', '2026-27', 'optional', 'International undergraduate page: SAT or ACT scores, essays and recommendation letters are not required; only transcripts and proof of English are needed. Domestic first-year applicants with a 2.75 GPA do not need scores; automatic admission is also possible with a 23 ACT / 1130 SAT or top 10% of class. CDS C8A: scores ''not required, but considered if submitted''.', '7b314e94-f77b-58d1-9b3e-54c2116c3b59');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('f8633771-8100-5f47-a466-08a6399a6520', '2026-27', array['own']::text[], 40, 'SIU''s own online application, $40 non-refundable fee. International freshmen need a 2.75 GPA (4.0 scale) from high school, translated official transcripts (scans accepted for admission, originals needed on arrival) and proof of English. A specific major must be chosen (no ''Undecided'' for international applicants). After admission, ISS requests a passport copy, financial statement and affidavit of support for the I-20; an older CIE page cited a $40,000 minimum financial statement. Some programs have extra requirements.', '7b314e94-f77b-58d1-9b3e-54c2116c3b59');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('7835728f-d715-5ea5-92e1-dda49595aae0', 'f8633771-8100-5f47-a466-08a6399a6520', '2026-27', 'priority', null, 'Preferred application deadline (fall 2027 entry)', '2026-12-01', 'Dec. 1 is the university-wide preferred/priority date (apply page; catalog: ''preferred application deadline shall be December 1, for the following fall semester''). The international admissions page itself prints no separate deadline.', '3e4ca9cf-5ba6-517d-8d83-3886cbe74a38'),
 ('18114c40-10b1-50c8-90c0-6e2d7183d6ac', 'f8633771-8100-5f47-a466-08a6399a6520', '2026-27', 'application', 'ROLLING', 'Applications after this date reviewed case-by-case (fall 2027 entry)', '2027-05-01', 'Apply page: applications received after May 1 are reviewed case-by-case. No year is printed; taken as fall 2027. Admission is rolling and no international-specific date is published.', '3e4ca9cf-5ba6-517d-8d83-3886cbe74a38'),
 ('f58275fc-411c-53ca-97ec-8305b24c90b1', 'f8633771-8100-5f47-a466-08a6399a6520', '2026-27', 'scholarship', null, 'Campus-based scholarship deadline (most scholarships)', '2027-02-01', 'Apply page: ''February 1 is the deadline for most campus-based scholarships'' (year not printed, taken as 2027). The page is written for FAFSA filers; it does not say whether international students may apply.', '3e4ca9cf-5ba6-517d-8d83-3886cbe74a38');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('f8633771-8100-5f47-a466-08a6399a6520', 'required_nonnative', 'Waived with two face-to-face English composition courses at a U.S. college (grade A or B), more than 48 U.S. college credit hours, citizenship of an English-primary country (exempt list), the final two years at a U.S. high school, or domestic-style test scores of ACT 23+ / SAT 1140+. Official SAT and TOEFL reports must come directly from the testing agency. Conditional admission: applicants who meet academic standards but not the English score can start in SIU''s Center for English as a Second Language (CESL); passing the required CESL levels gives a Certificate of Completion that satisfies the English requirement. Also accepted: TOEFL paper 520 and ITEP Academic Plus 3.6 (ITEP is not in this tracker''s test list).', '7b314e94-f77b-58d1-9b3e-54c2116c3b59');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
select 'f8633771-8100-5f47-a466-08a6399a6520'::uuid, 'required_option', '7b314e94-f77b-58d1-9b3e-54c2116c3b59'::uuid, v.* from (values
 ('TOEFL_IBT', 68, 'No minimum on the new 1-6 scale is published.'),
 ('IELTS', 6.0, null),
 ('DUOLINGO', 95, null),
 ('PTE', 47, null)) v;
insert into score_codes (institution_id, source_id, test_key, notes)
select 'f8633771-8100-5f47-a466-08a6399a6520'::uuid, '7b314e94-f77b-58d1-9b3e-54c2116c3b59'::uuid, v.* from (values
 ('sat', 'No SAT code is printed on the SIU admissions pages; look it up in the College Board search.'),
 ('act', 'No ACT code is printed on the SIU admissions pages.'),
 ('toefl', 'No TOEFL code is printed; scores must be sent directly by ETS.'),
 ('ielts', 'No institution code is listed.'),
 ('duolingo', 'No institution code is listed.'),
 ('pte', 'No institution code is listed.')) v;
insert into cost_aid (institution_id, year, tuition_usd, tuition_out_of_state_usd, tuition_intl_usd, required_fees_usd, room_board_usd, books_usd, intl_need_aid_awarded, intl_avg_award_usd, merit_scholarships, notes, source_id) values
 ('f8633771-8100-5f47-a466-08a6399a6520', '2026-2027', 9833, 9833, 24581, 3951, 12341, 780, 44, 19488, true, 'CDS G1 (first-year; the CDS marks cost data as of June 2026). Tuition shown is the 15-credit-hour flat annual rate: $9,833 for Illinois residents and domestic nonresidents, $24,581.40 for international students (who may qualify for the in-state rate through the High Achievers Alternate Tuition Rate). Tuition varies by program (G4). CDS H6 ticks both need-based and non-need-based institutional aid for nonresidents: 44 nonresidents received it, average $19,488. The 44 count is for all degree-seeking undergraduate nonresidents, not just first-year.; High Achievers Alternate Tuition Rate: international freshmen with a 3.5 GPA, or ACT 26, or SAT 1240 pay in-state tuition (about $9,833 vs $24,581 per year in the CDS). The older tuition page lists SAT 1170 instead of 1240; the current international page is used here. Transfers need a 3.0 GPA and 26 credits. The CDS says institutional need-based and non-need-based aid exists for nonresidents (44 degree-seeking undergraduate nonresidents got aid, average $19,488), but the admissions pages do not describe international need-based aid, so it is left unconfirmed.', 'cff16217-6ea6-50ca-b05d-391a1d335c4f');
