insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('bcf9b470-86eb-5238-8ed1-73bef5fa1844', '2026-27', 'optional', 'SAT/ACT are not required for admission consideration; students are encouraged to submit them for course placement. First-year admission criteria: cumulative GPA 2.6+ (4.0 scale), or GPA 2.0-2.59 with ACT 19+ / SAT 990+, or top 10% class rank; others may get additional review. The international requirements page states no minimum GPA or test policy.', 'a5732b64-96cb-52db-9e98-f6b4f45d3bdb');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('bcf9b470-86eb-5238-8ed1-73bef5fa1844', '2026-27', array['common_app','own']::text[], 40, 'Two-step process for international applicants: online application with academic records (unofficial transcripts are accepted at first; official ones after admission), then financial documents so SIUE can issue the I-20. $40 non-refundable fee plus a $1.10 card convenience fee (international page). Domestic first-years may use the SIUE application or the Common App; whether international applicants may use the Common App is not stated. Essays and recommendations are not listed.', '6c0e06ad-7938-593d-94b2-d58fc8895b04');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('0c4d1e42-475d-5cd4-8c4d-f4347f9971bd', 'bcf9b470-86eb-5238-8ed1-73bef5fa1844', '2026-27', 'priority', 'ROLLING', 'Fall priority deadline - international (fall 2027 entry)', '2027-05-01', 'The page prints no year; taken as fall 2027. STEM and business applicants face the same May 1 (fall) cutoff and SIUE may not process applications from outside the US after it.', '889356a4-a456-583e-a7af-0e44c9f5b390'),
 ('2f8c906a-0e6c-5fee-95d2-4099f788729a', 'bcf9b470-86eb-5238-8ed1-73bef5fa1844', '2026-27', 'application', 'ROLLING', 'Fall final deadline - international (fall 2027 entry)', '2027-06-01', null, '889356a4-a456-583e-a7af-0e44c9f5b390'),
 ('21167c68-ad72-58e2-ad36-bbb537dac34c', 'bcf9b470-86eb-5238-8ed1-73bef5fa1844', '2026-27', 'other', null, 'Fall financial-documents deadline - international', '2027-06-15', null, '889356a4-a456-583e-a7af-0e44c9f5b390');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('bcf9b470-86eb-5238-8ed1-73bef5fa1844', 'required_nonnative', 'Waived or satisfied by: graduating from a US high school; an accredited diploma or degree from the US or a primarily English-speaking country (UK, Ireland, Australia, New Zealand, English-speaking Canada); an Intensive English Language Program certificate equivalent to TOEFL iBT 79; ACT English/Reading 21; SAT EBRW 530 (480 before March 2016); or English 101 and 102 with a C or better at a US regionally accredited institution. Michigan English Test 53 also accepted. Scores must be under two years old and sent directly. The Intensive English Pathway admits students below the standard minimums (IELTS 5.0 with no part under 4.5, TOEFL 45, Duolingo 80, MET 41) and lets them take some credit-bearing courses alongside English classes; whether it gives guaranteed conditional admission is not stated.', '38a9188d-b076-5199-ab63-35d9339be6a6');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, min_subscores, notes)
select 'bcf9b470-86eb-5238-8ed1-73bef5fa1844'::uuid, 'required_option', '38a9188d-b076-5199-ab63-35d9339be6a6'::uuid, v.* from (values
 ('TOEFL_IBT', 72, null, 'Page does not name the scale or mention the new 1-6 scale; the 0-120 scale is assumed. GEO Award eligibility cites TOEFL 79 or IELTS 6.5.'),
 ('IELTS', 6.0, '{"each_section": 5.5}'::jsonb, 'No component below 5.5.'),
 ('PTE', 50, null, null),
 ('DUOLINGO', 110, null, null)) v;
