insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('dd3198d3-b17b-5afc-a85b-e1f48c3c70f4', '2026-27', 'optional', 'SRU is test optional through 2028: ACT/SAT scores are not required, but students may submit them. Students applying to a LECOM pre-professional advising area must submit SAT or ACT scores to LECOM. Students with a 3.25 or higher cumulative core-course GPA are automatically admitted.', '7c1f8325-e672-5151-9e91-ec9f56d23710');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('dd3198d3-b17b-5afc-a85b-e1f48c3c70f4', '2026-27', array['own']::text[], 30, 'International freshmen apply on SRU''s online application ($30, non-refundable), then submit official English-translated secondary records (subjects and marks, certificates, exam results), TOEFL/IELTS/Duolingo (or other listed proof) if not a native English speaker, and a passport photo-page copy. Financial verification is required for the I-20/DS-2019 but is not used to judge admission. Not approved for F-1/J-1 (SEVP): Nursing BSN, Nursing 1+2+1, RN to BSN, Aviation, Construction Management, Electrical and Computer Engineering, Commercial Music. First-year students are required to live on campus. The domestic first-year page says students with a 3.25+ core GPA are automatically admitted and others are reviewed individually (possible waitlist). No essay or recommendation is listed.', '78b6baf7-6437-5b14-97f3-b5a4b43e2994');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('0d8c03d0-1fc5-5d8e-b2c6-fa57ac51f1ae', 'dd3198d3-b17b-5afc-a85b-e1f48c3c70f4', '2026-27', 'application', 'ROLLING', 'International fall admission date (fall 2027 entry)', '2027-05-01', 'The international admissions page lists ''Fall Admission: May 1'' (spring: Oct. 1) without a year; taken as fall 2027. The catalog says first-year students are admitted on a rolling basis for all terms and should apply early. Admission offers not confirmed with a deposit may be rescinded after May 1.', '78b6baf7-6437-5b14-97f3-b5a4b43e2994');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('dd3198d3-b17b-5afc-a85b-e1f48c3c70f4', 'required_nonnative', 'All non-native speakers of English must submit an official score report. The page directs exemption questions to international.admissions@sru.edu; the transfer and post-baccalaureate sections say the requirement may be waived with a C or better in College Writing (or equivalent) from a regionally accredited U.S. institution. Also accepted: ELS Schools score report of 112 or higher, or STEP Eiken Grade 2A. The page describes no ESL or conditional-admission pathway.', '78b6baf7-6437-5b14-97f3-b5a4b43e2994');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
select 'dd3198d3-b17b-5afc-a85b-e1f48c3c70f4'::uuid, 'required_option', '78b6baf7-6437-5b14-97f3-b5a4b43e2994'::uuid, v.* from (values
 ('TOEFL_IBT', 62, 'Also accepts 500 on the paper test or 173 on the computer-based test. SRU TOEFL code 2658.'),
 ('TOEFL_IBT_2026', 4.0, 'The page says ''New TOEFL iBT minimum score 4.0 or higher''; it does not name the 1-6 scale.'),
 ('IELTS', 6.0, 'Overall band 6.0 or above.'),
 ('DUOLINGO', 95, 'Only scores of 95 and above are accepted.')) v;
insert into score_codes (institution_id, test_key, code, notes, source_id)
