 ('act', '3716', 'SRU ACT code (test-optional).', '5b071d52-7e5a-5302-be6b-756d89b5b13e'::uuid),
 ('toefl', '2658', 'SRU TOEFL institution code.', '78b6baf7-6437-5b14-97f3-b5a4b43e2994'::uuid),
 ('ielts', null, 'No IELTS institution code is listed.', '78b6baf7-6437-5b14-97f3-b5a4b43e2994'::uuid),
 ('duolingo', null, 'No institution code is listed.', '78b6baf7-6437-5b14-97f3-b5a4b43e2994'::uuid),
 ('pte', null, 'PTE is not listed as an accepted English test on the international page.', '78b6baf7-6437-5b14-97f3-b5a4b43e2994'::uuid)) v;
insert into cost_aid (institution_id, year, tuition_out_of_state_usd, tuition_intl_usd, required_fees_usd, room_board_usd, books_usd, other_usd, total_coa_usd, intl_aid_policy, intl_need_aid_awarded, intl_avg_award_usd, meets_full_need, merit_scholarships, notes, source_id) values
 ('dd3198d3-b17b-5afc-a85b-e1f48c3c70f4', '2026-2027', 16500, 12504, 3271, 10900, 800, 1700, 29265, 'merit_only', 62, 1775, false, true, 'International cost matrix 2026-27 (bachelor''s degree, 15 credits, average on-campus room and meals): tuition $12,504 (SRU gives international students a reduced out-of-state rate, about $3,996 below the full non-Pennsylvania rate of $16,500; the international page says about $3,500), fees $3,271, room and meal $10,900, enrollment deposit $90, books $800, personal $1,700 = $29,265; the $1,500 Provost Scholarship brings the I-20 financial verification amount to $27,765. The 2027-28 estimate is $26,934.; CDS H6: 62 undergraduate degree-seeking nonresidents received institutional aid, average $1,775 (total $110,038); the CDS text does not show whether it was need- or non-need-based. CDS G1 for 2026-27 lists tuition $7,994 in-state and $11,992 out-of-state/nonresident, required fees $3,470, food and housing $11,098; the international cost matrix is used for the cost figures.; International students are not eligible for Title IV funds. All new undergraduate international students receive a non-need-based tuition reduction (about $3,500 per the international page, about $3,996 per the cost matrix) and the $1,500 Provost Scholarship for Global Diversity & Academic Achievement is awarded on admission with no extra application (renewal needs a 3.0 GPA; the reduced tuition needs a 2.5 GPA). A $500 Presidential Award follows after the first year or semester with a 3.5 cumulative GPA. Need-based institutional aid for internationals is not described.', '9787aa4b-1461-5165-8110-98ee24f43e6f');
