insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, pct_submit_sat, pct_submit_act, gpa_avg, pct_reporting_gpa, gpa_distribution, notes, source_id) values
 ('5b6d9841-5cf6-5fb1-a78a-20817f6fc65d', '2025-2026', 10360, 9795, 2137, 6.0, 83.0, 3.75, 99.81, '{"4.0": 34.04, "3.75-3.99": 20.39, "3.50-3.74": 17.21, "3.25-3.49": 11.77, "3.00-3.24": 10.17, "2.50-2.99": 5.72, "2.0-2.49": 0.7, "1.0-1.99": 0.0}'::jsonb, 'CDS C1 (Fall 2025): 10,360 applied (3,506 men, 6,854 women), 9,795 admitted (94.5%), 2,137 enrolled (1,524 in-state, 600 out-of-state, 13 international). The CDS international applicant and admit cells are blank. IPEDS reports 12,982 applicants and a 71% admit rate for fall 2024, but the fall 2024 CDS also shows about 9,200 admits (9,906 applied), so the two sources count applicants differently. Undergraduate enrollment 9,530 and nonresident count 111 are the B1/B2 ''Total Undergraduates'' figures. SAT/ACT percentile ranges come from IPEDS (fall 2024) because the 2025-26 CDS PDF text is partly garbled (it lists an SAT composite 25th/50th/75th of 1010/1090/1200). GPA bands are the ''all enrolled students'' column. The CDS checkbox sections (C7 factors, C8 policy, H6) are not reliably legible, so factors are omitted.', '6d353756-35c1-5915-944b-7fec70dc892c');
insert into test_score_percentiles (institution_id, cds_year, source_id, test, p25, p50, p75)
select '5b6d9841-5cf6-5fb1-a78a-20817f6fc65d'::uuid, '2024-2025', '9541a1fb-924d-5420-ad6d-9a6ba785ed56'::uuid, v.* from (values
 ('SAT_ERW', 500, 560, 610),
 ('SAT_MATH', 470, 550, 580),
 ('ACT_COMPOSITE', 20, 23, 26)) v;
insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('5b6d9841-5cf6-5fb1-a78a-20817f6fc65d', '2026-27', 'optional', 'Test-optional for spring, summer and fall 2027 applicants: a high school GPA of 3.4 or better is automatically admitted; below 3.4 goes to review and may be asked for an essay and letter of recommendation. ACT 21 / SAT 1060 or better is recommended for scholarship consideration. The international requirements page lists no SAT/ACT requirement and a minimum 2.5 GPA.', 'fc18ede1-a382-5a63-ae9b-bbc4862a4b7f');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('5b6d9841-5cf6-5fb1-a78a-20817f6fc65d', '2026-27', array['own']::text[], 35, 'International application with a $35 processing fee. Academic records need a cumulative GPA of at least 2.5 as calculated by the Office of International Admissions; unofficial copies are accepted for admission, official ones before check-in. A non-refundable $500 deposit is required before an I-20 or DS-2019 is issued, with bank statements showing funds for one year.', 'bc0fdc65-aa65-5bdf-a562-303c28260c08');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('f6cba1e7-aad2-5c56-bd1e-4389fda10031', '5b6d9841-5cf6-5fb1-a78a-20817f6fc65d', '2026-27', 'application', 'ROLLING', 'International application deadline, applicants outside the U.S. (fall 2027 entry)', '2027-04-01', 'International page: fall Apr 1 (outside the U.S.) and Jul 15 (inside the U.S.); later applications are considered for the next session. Printed without a year, treated as 2027. Domestic priority date for fall is also Jul 15.', 'bc0fdc65-aa65-5bdf-a562-303c28260c08'),
 ('e39c7f56-8d82-5b47-9ce4-33ce581038b7', '5b6d9841-5cf6-5fb1-a78a-20817f6fc65d', '2026-27', 'scholarship', null, 'Global Freshman Scholars priority deadline 1', '2027-01-15', 'Must be fully admitted by this date, then apply through JagSPOT. The award is competitive and limited.', '1395282e-d0e9-5b58-9385-30f6a6331c88'),
 ('da5696f4-e480-5a06-82b8-b257f9e3c5dd', '5b6d9841-5cf6-5fb1-a78a-20817f6fc65d', '2026-27', 'scholarship', null, 'Global Freshman Scholars priority deadline 2', '2027-05-01', 'Second priority date (fully admitted by then).', '1395282e-d0e9-5b58-9385-30f6a6331c88');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('5b6d9841-5cf6-5fb1-a78a-20817f6fc65d', 'required_nonnative', 'Citizens of, or those who completed secondary education in, listed English-exempt countries (including Australia, Canada, Ireland, Jamaica, Nigeria, Singapore, South Africa, the UK and the US) need no proof. Also accepted: iTEP 3.6 and a grade of A, B or C on UK Advanced-level English exams. No intensive English pathway or conditional admission for freshmen is described on the page.', 'bc0fdc65-aa65-5bdf-a562-303c28260c08');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
select '5b6d9841-5cf6-5fb1-a78a-20817f6fc65d'::uuid, 'required_option', 'bc0fdc65-aa65-5bdf-a562-303c28260c08'::uuid, v.* from (values
 ('TOEFL_IBT', 61, null),
 ('TOEFL_IBT_2026', 3.5, 'The page states ''TOEFL: 61 or 3.5 (6-point scoring)''.'),
 ('IELTS', 5.5, null),
 ('DUOLINGO', 95, null),
 ('PTE', 44, 'Pearson Academic.')) v;
