insert into cost_aid (institution_id, year, tuition_intl_usd, room_board_usd, books_usd, other_usd, total_coa_usd, intl_aid_policy, meets_full_need, merit_scholarships, notes, source_id) values
 ('5b6d9841-5cf6-5fb1-a78a-20817f6fc65d', '2026-2027', 20486, 9330, 1000, 3439, 34255, 'merit_only', false, true, 'International estimate used for I-20 issuance: tuition and fees $20,486 (12 credit hours per fall and spring semester), housing and food $9,330, books $1,000, health insurance $3,439 (other), total $34,255. Per-credit-hour undergraduate tuition is $386 in-state and $772 out-of-state for Arts and Sciences, higher in Computing and Allied Health ($802 out-of-state), Business ($822), Engineering ($832) and Nursing ($870); the tuition page''s title says 2025-2026 but the rate tables are headed 2026-2027.; Global Freshman Scholars Talent and Ability Scholarship (from fall 2026): competitive, for degree-seeking international freshmen on F-1/H-4/L-2 with a 3.0+ high school GPA; the award is in-state tuition rates, renewable up to four years with a 3.0 GPA each year; no dollar figure is listed. Endowed awards (Carter GlobalUSA, Pitsios, Constantine) need 3.0-3.5 GPAs; apply through JagSPOT. The CDS H6 section on aid to nonresidents is not reliably legible.', '34fd1bd3-d1e7-5694-8759-ff04201850b8');
