insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, pct_submit_sat, pct_submit_act, notes, source_id, source_note) values
 ('43709a15-6b1f-50c7-b209-bec4c4ba2c1b', '2023-2024', 5884, 5808, 2274, 2, 81, 'Baseline from IPEDS (fall 2023 entering class). College Navigator''s fall 2024 figures: 7,287 applicants, 98% admitted, 34% of admitted enrolled; ACT composite 19/22/25 (75% submitted), SAT ERW 530/570/610, SAT Math 530/560/630 (2% submitted). SDSU''s only readable public CDS is 2021-22 (newer years are listed but not linked), so GPA, residency and international applicant splits are not added. IPEDS reported no international first-year applicants. Undergrad 10,177 and 307 nonresident-alien undergrads are IPEDS fall 2023 (EF2023A).', '160b6c1e-9762-517f-b093-7ef34c4b394b', 'admissions_site');
