insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('bc39cf98-e440-55b8-8d89-db9c80d8d26a', '2026-27', 'optional', 'Test scores are optional for admission on the first-year international page; they may qualify for merit scholarships and are used for math/English placement. SAT EBRW 450+ or ACT English and Reading 21+ can also serve as English proof. CDS C8F says ''Test optional''.', 'fb537f48-9654-5384-bb8f-48f62a9abff3');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('bc39cf98-e440-55b8-8d89-db9c80d8d26a', '2026-27', array['own']::text[], 60, 'Own online application; $60 non-refundable international fee, no waivers. No minimum high school GPA is stated for first-year international applicants (the acceptance letter lists conditions). Unofficial transcripts and English scores are enough at application; official ones are needed after admission. NACES/AICE credential evaluations are accepted for first-time freshmen. After admission: Affidavit of Financial Support and bank statement covering estimated annual cost minus scholarship; no tuition deposit. Nursing and some programs have higher English standards. CDS C7: GPA and rigor very important, test scores and class rank considered, essay and recommendations not considered.', '5fd8c9a7-f85e-596a-922a-8a3309757b7b');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('121bcf0c-7aa1-5630-b81c-057c82433359', 'bc39cf98-e440-55b8-8d89-db9c80d8d26a', '2026-27', 'priority', null, 'Priority date (fall 2027 entry)', '2026-12-01', 'CDS C14 lists a priority date of Dec 1 and an application closing date of July 1; no year is printed, taken as the fall 2027 cycle. What the priority date affects is not explained.', '5fd8c9a7-f85e-596a-922a-8a3309757b7b'),
 ('8b4d47ef-1d14-586b-9d91-adf9225b43c0', 'bc39cf98-e440-55b8-8d89-db9c80d8d26a', '2026-27', 'application', 'ROLLING', 'International fall 2027 application deadline (regular)', '2027-07-01', 'Fall (August) deadline is July 1; students applying web-only or already holding a valid US visa have July 15. No year is printed, taken as fall 2027.', '5fd8c9a7-f85e-596a-922a-8a3309757b7b'),
 ('ac6a70eb-039b-5125-b6de-ce662ee951ba', 'bc39cf98-e440-55b8-8d89-db9c80d8d26a', '2026-27', 'application', 'ROLLING', 'International spring 2027 (January) application deadline (regular)', '2026-11-01', 'Spring deadline is November 1 (November 15 for web-only or valid-US-visa applicants); no year printed, taken as spring 2027 entry.', '5fd8c9a7-f85e-596a-922a-8a3309757b7b');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('bc39cf98-e440-55b8-8d89-db9c80d8d26a', 'required_nonnative', 'Proof can be a test score, a US high school diploma, O/A-level, WAEC, IB (English-medium), a US-accredited international school diploma, a secondary diploma from a listed English-official country, SAT EBRW 450 / ACT English and Reading 21, or Level 5 of SEMO''s Intensive English Program. Scores must be official and sent by the test provider. Conditionally admitted students may submit official scores by the last office day before classes start.', '5fd8c9a7-f85e-596a-922a-8a3309757b7b');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
select 'bc39cf98-e440-55b8-8d89-db9c80d8d26a'::uuid, 'required_option', '5fd8c9a7-f85e-596a-922a-8a3309757b7b'::uuid, v.* from (values
 ('TOEFL_IBT', 61, 'For tests taken before Jan 21, 2026. English Program Pathway applicants (conditional/IEP route): 52-60.'),
 ('TOEFL_IBT_2026', 3.5, 'Tests on or after Jan 21, 2026; the page prints 3.5 (pathway 3.0) without naming the scale, presumably the new 1-6 scale; confirm with admissions.'),
 ('IELTS', 5.5, 'Academic. Pathway applicants: 5.0.'),
 ('DUOLINGO', 95, 'Pathway applicants: 80-90.'),
 ('PTE', 45, 'Academic or Express. Pathway applicants: 40-43. Also accepted: Michigan English Test 48 (pathway 45), iTEP 3.7, Oxford ELLT 6 (pathway 5).')) v;
