insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('d4e6da63-3306-597b-9a38-ce6a8293ad76', '2026-27', 'required', 'The international freshman materials page states ''The SAT or ACT is required for beginning freshman international students to gain admission''; scores must come directly from the testing company. The CDS (C8) instead marks SAT/ACT as recommended, and the freshman criteria page uses ACT/SAT only for English (ACT English 18 / SAT ERW 500) and math placement (ACT Math 19 or SAT Math 510 for college math). Plan to submit a score.', '92a10f91-5b70-5c0e-aee1-f6b8a42fffe8');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('d4e6da63-3306-597b-9a38-ce6a8293ad76', '2026-27', array['own']::text[], 30, 'International application fee is $30 if the application and fee are submitted by July 15 (fall) and $80 after that. Required: official secondary school records with notarized English translation (sent directly; no email or fax), SAT or ACT scores, TOEFL or IELTS (education outside the US), proof of immunization, passport copy, and a financial statement of support for the I-20 (estimated costs at least $31,618 per year). Minimum secondary school GPA 2.35. Students in F-1 status cannot enter online-only programs. CDS C4 says a college-preparatory program is required and C5 lists a 19-unit distribution (4 English, 4 math, 4 science, 4 social studies, 2 foreign language, 1 arts); CDS C7 rates GPA very important.', '26271bca-77b3-5454-b265-0320f01d8a30');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('d268abc8-a771-5c7f-bbdc-b55b83e93944', 'd4e6da63-3306-597b-9a38-ce6a8293ad76', '2026-27', 'priority', null, 'International priority filing date, fall term (fall 2027 entry)', '2027-06-01', 'Priority-filing deadline for completed applications and fees so that the I-20/DS-2019 can be issued in time. The page prints no year, so treated as 2027. I-20s may not be issued for students outside the US if the application was not complete by July 1.', '649fcd64-f5d6-5e25-a80a-cb290d87805f'),
 ('782c4d7d-54d5-5f18-827b-6a04950ffb4f', 'd4e6da63-3306-597b-9a38-ce6a8293ad76', '2026-27', 'application', 'ROLLING', 'Final application deadline, fall term (fall 2027 entry)', '2027-08-01', 'Fee is $30 through July 15 and $80 after July 15; ''No applications accepted for fall after August 1''. The CDS gives a Jan. 15 priority date and Aug. 1 closing date for all first-year applicants and rolling notification.', '649fcd64-f5d6-5e25-a80a-cb290d87805f');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('d4e6da63-3306-597b-9a38-ce6a8293ad76', 'required_nonnative', 'Students whose education was earned outside the US or whose native language is not English must show proficiency. The criteria page lists ACT English 18, SAT ERW 500, or Accuplacer Next-Gen Writing 250 as alternatives to TOEFL/IELTS/Duolingo, while the materials page asks for TOEFL or IELTS scores sent directly from the testing company.', '26271bca-77b3-5454-b265-0320f01d8a30');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
select 'd4e6da63-3306-597b-9a38-ce6a8293ad76'::uuid, 'required_option', '26271bca-77b3-5454-b265-0320f01d8a30'::uuid, v.* from (values
 ('TOEFL_IBT', 79, '550 on the paper-based test. TOEFL school code 6656. The scholarship (fee waiver) page lists a lower 75 iBT for the non-resident fee waiver.'),
 ('IELTS', 6.5, 'The non-resident fee waiver page lists 6.0.'),
 ('DUOLINGO', 100, null)) v;
insert into score_codes (institution_id, test_key, code, notes, source_id)
select 'd4e6da63-3306-597b-9a38-ce6a8293ad76'::uuid, v.* from (values
 ('sat', null, 'Southeastern''s international pages do not list an SAT code; look it up in the College Board code search.', '92a10f91-5b70-5c0e-aee1-f6b8a42fffe8'::uuid),
 ('act', null, 'Southeastern''s international pages do not list an ACT code; look it up at act.org.', '92a10f91-5b70-5c0e-aee1-f6b8a42fffe8'::uuid),
 ('toefl', '6656', 'School code to send TOEFL scores to Southeastern, per the international materials page.', '92a10f91-5b70-5c0e-aee1-f6b8a42fffe8'::uuid),
 ('ielts', null, 'No institution code is listed; scores must be sent directly from the testing company.', '92a10f91-5b70-5c0e-aee1-f6b8a42fffe8'::uuid),
 ('duolingo', null, 'No institution code is listed.', '26271bca-77b3-5454-b265-0320f01d8a30'::uuid),
 ('pte', null, 'PTE is not listed as an accepted test on the international pages.', '26271bca-77b3-5454-b265-0320f01d8a30'::uuid)) v;
insert into cost_aid (institution_id, year, tuition_usd, tuition_out_of_state_usd, required_fees_usd, room_board_usd, books_usd, total_coa_usd, intl_aid_policy, intl_need_aid, intl_merit_aid, intl_need_aid_awarded, intl_avg_award_usd, meets_full_need, merit_scholarships, notes, source_id) values
 ('d4e6da63-3306-597b-9a38-ce6a8293ad76', '2025-2026', 5777, 18255, 3266, 10200, 1386, 31618, 'merit_only', false, true, 229, 15939, false, true, 'The international materials page says expenses are ''at least $31,618'' per year for undergraduates (tuition, housing, meals, textbook rental and health insurance, excluding travel); it prints no academic year. Before any fee waiver.; CDS G1 first-year figures for 2025-2026 (the 2026-27 figures are not yet published): in-state tuition $5,777, nonresident alien tuition $18,255 ($897 per credit hour), required fees $3,266, on-campus food and housing $10,200. CDS H6 (2024-25): 229 degree-seeking nonresident aliens received institutional non-need-based aid (average $15,939, total $3,649,929).; Non-resident fee waiver for international beginning freshmen (the admission application is the application): minimum TOEFL 75 iBT, IELTS 6.0 or Duolingo 100, a recognized secondary program with GPA 2.25 or higher, and no developmental coursework. It waives the out-of-state fees, which the page lists as up to $6,238 per semester for 12+ hours. Renewal needs full-time status and good standing. The Southeastern Honor Scholarship is also open to international students (ACT-based; SAT is converted). CDS H6: 229 nonresident aliens received institutional non-need-based aid averaging $15,939.', '92a10f91-5b70-5c0e-aee1-f6b8a42fffe8');
