insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('c7d8efd0-af04-5b63-8af1-b9688f70f1de', '2026-27', 'optional', 'International first-year applicants need a high school GPA of 2.7, OR an ACT composite of 20, OR an SAT of 1030; so scores are only one of three ways to qualify.', 'f2e180ec-c94b-5247-b093-078a63adc2c3');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('c7d8efd0-af04-5b63-8af1-b9688f70f1de', '2026-27', array['own']::text[], 30, 'US$30 non-refundable fee. Documents: transcripts evaluated by a NACES-member credential service, Undergraduate Affidavit of Financial Support, and an original bank statement (signed and stamped by a bank official, dated within 6 months of the start term) showing a liquid US$ balance that covers the first year. Essays, recommendations and interviews are not mentioned on the pages read.', 'f2e180ec-c94b-5247-b093-078a63adc2c3');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('3513c30a-aa0f-51ac-9fec-f4c1f56bfddd', 'c7d8efd0-af04-5b63-8af1-b9688f70f1de', '2026-27', 'scholarship', null, 'Honors, President''s Leadership Class, John Massey Leadership Scholars and Parsons Scholars applications (fall 2027)', '2027-01-31', 'Jan. 31, no year printed, treated as 2027. Only for new incoming freshmen; the page does not say whether international students are eligible.', '15641b08-83fd-5561-a42e-b92adf816dc6'),
 ('8a2b4947-2417-5616-9272-8a193637c1b2', 'c7d8efd0-af04-5b63-8af1-b9688f70f1de', '2026-27', 'scholarship', null, 'General Scholarship application: priority date (fall 2027)', '2027-03-01', 'Mar. 1, no year printed, treated as 2027. The final General Scholarship deadline is Aug. 1. You must be admitted first; the page does not say whether international students are eligible.', '15641b08-83fd-5561-a42e-b92adf816dc6'),
 ('f2da418f-8479-50f9-bb98-218d789a2f99', 'c7d8efd0-af04-5b63-8af1-b9688f70f1de', '2026-27', 'application', 'RD', 'International application deadline, fall 2027 (applicants outside the U.S.)', '2027-06-01', 'Fall deadline is June 1 for students outside the U.S. and July 1 for students already in the U.S.; no year is printed, so fall 2027 is assumed. Spring deadlines are Nov. 1 (outside U.S.) and Dec. 1 (in the U.S.). No summer admission for international students.', 'f96167b2-a678-5445-b1df-bbf5371bbaa9');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('c7d8efd0-af04-5b63-8af1-b9688f70f1de', 'required_nonnative', 'Test scores are not needed if English is your first language or you graduated from a U.S. high school with four years of English. Students with a TOEFL iBT of 48-60 (old 0-120 scale) or an IELTS of 5.0 may meet the requirement instead by completing at least 12 weeks in an ESL program approved by the Oklahoma State Regents.', 'f2e180ec-c94b-5247-b093-078a63adc2c3');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
select 'c7d8efd0-af04-5b63-8af1-b9688f70f1de'::uuid, 'required_option', 'f2e180ec-c94b-5247-b093-078a63adc2c3'::uuid, v.* from (values
 ('TOEFL_IBT_2026', 3.5, 'The page lists ''TOEFL Internet-Based (iBT) 3.5'' and says the iBT changed in 2026 to a new adaptive format with a 1-6 scale, so 3.5 is on the new scale. Paper-based 500 and computer-based 173 are also accepted. The old-scale iBT minimum is not printed (the ESL footnote covers 48-60).'),
 ('IELTS', 5.5, 'Overall band.'),
 ('PTE', 44, 'PTE Academic. iTEP Academic 3.5 is also accepted. Duolingo and Cambridge are not listed on the page.')) v;
