insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, pct_submit_sat, pct_submit_act, notes, source_id, source_note) values
 ('fecbbc18-e927-522a-a353-97c5349a8847', '2024-2025', 2907, 1904, 703, 46, 60, 'Baseline from IPEDS fall 2024 (no Common Data Set found on southern.edu): 2,907 applied, 1,904 admitted (65%), 703 enrolled (37% yield). College Navigator: SAT/ACT ''not required, but considered''; GPA and secondary school record required; English proficiency test required. SAT submitted by 321 enrolled first-time students (46%), ACT by 420 (60%). International applicant counts, GPA distribution and residency splits are not published.', '792f8be1-b527-5440-a4df-1886554683de', 'admissions_site');
