insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('fecbbc18-e927-522a-a353-97c5349a8847', '2026-27', 'optional', 'Minimum GPA 2.5 plus ACT 18 or SAT 960, but test scores are not required if the high school GPA is 2.75 or higher. Scores are still needed for certain programs (School of Education and Psychology, School of Journalism and Communication) and for classes with test prerequisites, and they set the Renewable Academic Scholarship. The international page lists ''ACT or SAT scores'' among documents to submit.', '50055e37-4678-5a85-bd3f-6f8bbcb98e9f');
insert into application_requirements (institution_id, cycle, platforms, notes, source_id) values
 ('fecbbc18-e927-522a-a353-97c5349a8847', '2026-27', array['own']::text[], 'Apply online at Southern''s own application. International documents: evaluated high school transcripts (SpanTran is recommended, about $140; not needed for Bermuda and Bahamas), ACT/SAT, English proficiency scores, declaration of finances, passport page, and a $3,000 international commitment deposit. Minimum 2.5 GPA on a 4.0 scale including English, math, natural science, religion, social science and foreign language. Applicants below the standard can be admitted on academic probation (GPA 2.25+ and ACT 16 or SAT 880). The application fee is not stated on the admissions pages (College Navigator listed $25 for 2024-25), so it is left blank.', '9bd551b8-0e8b-5526-97ed-77caab8543fb');
insert into deadlines (id, institution_id, cycle, kind, label, due_date, notes, source_id) values
 ('c3029f19-bb18-50ce-a6b1-f49765048d50', 'fecbbc18-e927-522a-a353-97c5349a8847', '2026-27', 'priority', 'Freshman priority deadline (priority processing and scholarship consideration), fall 2027', '2027-03-01', 'Dates are printed without a year; treated as fall 2027. There is no priority deadline for winter or summer.', '50055e37-4678-5a85-bd3f-6f8bbcb98e9f'),
 ('ee91de66-0550-5879-9043-3fa4814583cf', 'fecbbc18-e927-522a-a353-97c5349a8847', '2026-27', 'application', 'International acceptance deadline (fall 2027 entry)', '2027-06-01', 'International students must complete the acceptance process by this date or no I-20 is issued for the semester. Winter (January) semester acceptance deadline is October 5. Other fall dates: declaration of finances June 22, I-20 deadline July 6.', '9bd551b8-0e8b-5526-97ed-77caab8543fb'),
 ('7feeda6b-772b-590e-9c58-adea01b7af68', 'fecbbc18-e927-522a-a353-97c5349a8847', '2026-27', 'deposit', 'International commitment deposit ($3,000) due (fall 2027 entry)', '2027-06-24', 'Winter semester international deposit deadline is November 18.', '9bd551b8-0e8b-5526-97ed-77caab8543fb');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('fecbbc18-e927-522a-a353-97c5349a8847', 'required_nonnative', 'Exempt: citizens of Australia, The Bahamas, Bermuda, Canada, Ireland, Jamaica, New Zealand, Barbados, Trinidad and Tobago, South Africa or the United Kingdom; or students who complete four years of U.S. secondary school with a 2.5 GPA and either a 3.0 in English subjects or ACT Composite, English and Reading of 18+. iTEP is also accepted (4.0+ regular admit, 3.0-3.9 with ESL). Southern offers a limited ESL program: scores in the middle band admit the student with ESL support (conditional pathway); scores below it are not admitted.', '9bd551b8-0e8b-5526-97ed-77caab8543fb');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
select 'fecbbc18-e927-522a-a353-97c5349a8847'::uuid, 'required_option', '9bd551b8-0e8b-5526-97ed-77caab8543fb'::uuid, v.* from (values
 ('TOEFL_IBT', 79, '79+ = regular admit; 45-78 = admit with ESL support; 44 or lower = not admitted. Paper-delivered TOEFL: 550+ regular, 450-549 with ESL.'),
 ('IELTS', 6.5, '6.5+ = regular admit; 5.5-6.0 = admit with ESL support; 5.4 or lower = not admitted.'),
 ('DUOLINGO', 115, '115+ = regular admit; 85-114 = admit with ESL support; 84 or lower = not admitted. Duolingo has given Southern a limited number of fee-waiver coupons for high-achieving, low-income applicants (apply first, then request).')) v;
insert into cost_aid (institution_id, year, tuition_usd, required_fees_usd, room_board_usd, total_coa_usd, notes, source_id) values
 ('fecbbc18-e927-522a-a353-97c5349a8847', '2026-2027', 28900, 1500, 9900, 40300, 'Sample yearly cost for a residence hall student: tuition $28,900 (12-16 hours), general fee $1,500, residence hall rent $6,000, food allowance $3,900 = $40,300; commuter total $30,400. Southern says the typical out-of-pocket amount is $11,800 per year after scholarships and grants. The page does not mention separate international fees or health insurance.; Southern lists automatic freshman merit awards by GPA and ACT/SAT points (Honors $2,000, Dean $4,000, Presidential $6,000 per year, or 50% tuition at the top band) and a full-tuition award at ACT 33-36 depending on GPA, but the pages do not say whether international students are eligible. The Three-Way church scholarship match is explicitly open to international undergraduates ($500 per year maximum). Federal aid requires U.S. citizenship or eligible status. Ask the admissions office what international applicants receive.', '103f346e-b7d1-584c-8704-cf229235651d');
insert into institution_tiers (institution_id, tier_code, category_key, rationale)
select 'fecbbc18-e927-522a-a353-97c5349a8847'::uuid, 'D', v.* from (values
 ('general', 'Admit rate 65.5%'),
 ('computer_science', 'Editorial judgment (v1, reviewed 2026-10-20)'),
 ('engineering', 'Editorial judgment (v1, reviewed 2026-10-20)'),
 ('business', 'Editorial judgment (v1, reviewed 2026-10-20)'),
 ('biology_life_sci', 'Editorial judgment (v1, reviewed 2026-10-20)'),
 ('math_physics', 'Editorial judgment (v1, reviewed 2026-10-20)'),
 ('nursing', 'Editorial judgment (v1, reviewed 2026-10-20)'),
 ('arts_design', 'Editorial judgment (v1, reviewed 2026-10-20)'),
 ('humanities', 'Editorial judgment (v1, reviewed 2026-10-20)')) v;

