insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('9cec1fe5-c450-59be-b15e-0dbb28fca6cd', '2026-27', 'optional', 'USI lets students decide whether to submit SAT/ACT scores; if submitted USI superscores (best score per section). International freshmen should send official English proficiency results; Duolingo and SAT/ACT are considered case by case for that purpose.', 'd39dca1f-6179-5f51-b858-0bd243b8ce95');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('9cec1fe5-c450-59be-b15e-0dbb28fca6cd', '2026-27', array['common_app']::text[], 40, '$40 non-refundable application fee; international applicants cannot use the Common App fee waiver. Freshmen must submit an official document-by-document transcript evaluation from a NACES member (ECE preferred) before arriving; Chinese applicants need a CDGDC/CSSD verification report mailed directly. USI prefers a cumulative GPA of 2.5 (4-point scale). Whether USI also has its own application form was not confirmed on the pages read.', '01c73abf-2cb0-5cb3-8978-7a10e462de44');
insert into deadlines (id, institution_id, cycle, kind, label, due_date, notes, source_id) values
 ('87dad94d-c3ae-57b4-8acc-59bd9ac41562', '9cec1fe5-c450-59be-b15e-0dbb28fca6cd', '2026-27', 'priority', 'Priority date (fall 2027 entry)', '2027-08-15', 'CDS C14 lists ''Priority Date 8/15'' (no year; treated as fall 2027). USI''s international page says admission is rolling with no application deadline and encourages applying as early as possible to leave time for embassy processing of immigration documents.', 'b2a3f55d-cef4-51c4-b992-5a5afedbd8e2');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('9cec1fe5-c450-59be-b15e-0dbb28fca6cd', 'required_nonnative', 'Results must be sent to USI directly from the testing agency. Other accepted proof: ELS Level 112, O Level English grade B or higher, and 24+ transferable credits with a C or higher in ENG 101 and ENG 102 (transfer students). Duolingo, EIKEN and SAT/ACT are considered case by case. Conditional admission: applicants whose English needs improvement can be admitted conditionally without TOEFL/IELTS by completing USI''s Intensive English Program (IEP), and must graduate from the IEP before enrolling in a major.', 'd39dca1f-6179-5f51-b858-0bd243b8ce95');
insert into english_requirements (institution_id, source_id, test_key, status, min_total, notes)
select '9cec1fe5-c450-59be-b15e-0dbb28fca6cd'::uuid, 'd39dca1f-6179-5f51-b858-0bd243b8ce95'::uuid, v.* from (values
 ('TOEFL_IBT', 'required_option', 71, '71 for tests taken on or before Jan. 20, 2026; paper-based 527 (conditional-admission page) or high-intermediate in each section.'),
 ('TOEFL_IBT_2026', 'required_option', 4, 'Page lists 4 for tests taken on or after Jan. 21, 2026 without naming the 1-6 scale.'),
 ('IELTS', 'required_option', 6.0, null),
 ('DUOLINGO', 'accepted', null, 'Considered case by case; no minimum is published.'),
 ('PTE', 'required_option', 50, 'PTE Academic.'),
 ('CAMBRIDGE', 'required_option', 169, 'Cambridge English Advanced.')) v;
