insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('683215a9-4836-5015-bea4-dba45f177776', '2026-27', 'blind', 'Page says SAT and ACT scores do not influence the admission decision and are not required; scores may be submitted but are not used.', '0fcfb575-93ca-5f8f-b7b5-85a57da1b782');
insert into application_requirements (institution_id, cycle, platforms, counselor_rec, app_fee_usd, notes, source_id) values
 ('683215a9-4836-5015-bea4-dba45f177776', '2026-27', array['common_app','own']::text[], true, 50, 'Common Application or the University of Maine System application. The $50 application fee applies to international applicants only (free for US and Canadian applicants). International first-year applicants submit official secondary transcripts with certified English translations, financial documentation, and a school counselor statement and/or recommendation letter; a personal essay is recommended. Admission is based primarily on academic background, course rigor and grades. BS in Nursing first-year applications are due Feb 1 and nursing is admitted for fall only.', '0fcfb575-93ca-5f8f-b7b5-85a57da1b782');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('5461ce17-9509-5352-8205-8d72a45c7ebf', '683215a9-4836-5015-bea4-dba45f177776', '2026-27', 'application', 'EA', 'Early action application deadline', '2026-12-01', 'Supporting materials due Dec 15; admission decision guaranteed by Jan 15 if both are met. Dates print no year; taken as the fall 2027 entry cycle.', '0fcfb575-93ca-5f8f-b7b5-85a57da1b782'),
 ('a3eb3846-c7eb-5740-9954-871c130b5937', '683215a9-4836-5015-bea4-dba45f177776', '2026-27', 'priority', 'ROLLING', 'Priority deadline for academic scholarship consideration', '2027-02-01', 'Supporting materials due Feb 15. The international scholarship page says international applicants who apply by the stated deadline are automatically considered; the stated international deadline is June 1.', '0fcfb575-93ca-5f8f-b7b5-85a57da1b782'),
 ('eed57686-4f5b-5601-9cef-40a397db53d7', '683215a9-4836-5015-bea4-dba45f177776', '2026-27', 'application', 'ROLLING', 'International student application deadline - fall 2027 entry', '2027-06-01', 'USM admits on a rolling basis. Both the international programs page and the undergraduate admission page list June 1 for international fall applicants (the general final fall deadline is Aug 15). Spring entry deadline for international students is Oct 15. No year is printed; taken as fall 2027.', 'ebc98b16-6a95-5399-a098-e82fa84372d0'),
 ('d6c2c4c5-8128-54a8-ad1c-9c5cbebf4dbf', '683215a9-4836-5015-bea4-dba45f177776', '2026-27', 'deposit', null, 'Priority enrollment deposit deadline', '2027-05-01', null, '0fcfb575-93ca-5f8f-b7b5-85a57da1b782');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('683215a9-4836-5015-bea4-dba45f177776', 'required_nonnative', 'The English language requirements page lists minimum test scores only and states no waiver rules; confirm exemptions with the Office of Admissions. An Admissions Pathway Program (undergraduate only) accepts lower scores: TOEFL 60, IELTS 5.5-6.0, PTE 46, Duolingo 90. An Intensive ESOL program accepts TOEFL 45, IELTS 5.0, Duolingo 75.', '4b07673f-5c17-57ca-aab1-6ec4df72a868');
