insert into sources (id, institution_id, kind, title, url, cds_year, accessed_on) values
 ('715352fd-7034-5981-ae3b-abc415a88716', '3de0c2b4-c4da-5f6e-a951-d3949ea73162', 'cds', 'Southern Utah University Common Data Set 2025-2026 (PDF)', 'https://drive.google.com/file/d/1E5MHkccO8fNCM2z_GCuuxBe_Gxs06Lkx/view?usp=drive_link', '2025-2026', '2026-10-26'),
 ('85a6c448-3947-57d2-82bc-2c6b07f50b47', '3de0c2b4-c4da-5f6e-a951-d3949ea73162', 'ipeds', 'College Navigator - Southern Utah University (fall 2024 admissions summary)', 'https://nces.ed.gov/collegenavigator/?id=230603', '2024-2025', '2026-10-26'),
 ('c861df02-646a-5f2d-a5ac-860a491fa779', '3de0c2b4-c4da-5f6e-a951-d3949ea73162', 'admissions_site', 'SUU - International undergraduate admission requirements', 'https://www.suu.edu/international/undergraduate-admission-requirements.html', null, '2026-10-26'),
 ('e2056de4-e7be-5d81-9712-79758bbd25d1', '3de0c2b4-c4da-5f6e-a951-d3949ea73162', 'financial_aid_site', 'SUU - International student estimated costs and scholarships', 'https://www.suu.edu/international/estimated-costs.html', null, '2026-10-26'),
 ('62439e47-afa7-5540-bc50-2eb7cbbbf631', '3de0c2b4-c4da-5f6e-a951-d3949ea73162', 'admissions_site', 'SUU - First-year student admission', 'https://www.suu.edu/admissions/first-year/', null, '2026-10-26'),
 ('0a5c1290-85f7-5de9-9ae0-38e2c99af51c', '3de0c2b4-c4da-5f6e-a951-d3949ea73162', 'admissions_site', 'SUU - Intensive English Program admission requirements', 'https://www.suu.edu/international/intensive-english-admission-requirements.html', null, '2026-10-26');
insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, gpa_avg, pct_reporting_gpa, gpa_distribution, notes, source_id) values
 ('3de0c2b4-c4da-5f6e-a951-d3949ea73162', '2025-2026', 16235, 16231, 2150, 3.48, 99.44, '{"4.0": 7.4, "3.75-3.99": 35.8, "3.50-3.74": 16.6, "3.25-3.49": 13.0, "3.00-3.24": 10.2, "2.50-2.99": 11.0, "2.0-2.49": 4.4, "1.0-1.99": 1.5}'::jsonb, 'CDS C1 fall 2025 first-year class; C6 states an open admission policy for all students (virtually every applicant who completes the application is admitted). The CDS gives no residency or international split for applicants/admits. College Navigator (IPEDS fall 2024) counts differently: 19,080 applicants, 82% admitted, 14% of admits enrolled. No early decision; early action is rolling with no closing date. No waitlist. SUU does not use SAT/ACT in admission decisions (C8A = No) and reported no score percentiles. CDS B1/B2 total undergraduates 13,176 including part-time and non-degree students; 749 nonresident (international) undergraduates (621 degree-seeking). The fall 2025 first-year class has 127 nonresident students (B2).', '715352fd-7034-5981-ae3b-abc415a88716');
insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('3de0c2b4-c4da-5f6e-a951-d3949ea73162', '2026-27', 'blind', 'SUU does not use SAT/ACT scores in admission (CDS C8A). First-time freshmen with a cumulative unweighted GPA of 2.4 or higher are fully admitted; below 2.4 are provisionally admitted into the COMPASS program. International applicants need a foreign transcript that converts to at least a 2.0 on a 4.0 scale. An ACT 18 or SAT critical reading 450 can be used as English-proficiency proof (not as an admission test).', '62439e47-afa7-5540-bc50-2eb7cbbbf631');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('3de0c2b4-c4da-5f6e-a951-d3949ea73162', '2026-27', array['own']::text[], 60, 'International application fee is $60 (US currency only); the CDS lists no application fee for domestic applicants. Applicants show funds for the first year with an official bank document and the International Student Financial Form. No essay or recommendations are listed on the international requirements page; CDS C7 reports no weight on essays, recommendations or interviews.', 'c861df02-646a-5f2d-a5ac-860a491fa779');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('2a2015c6-217e-58e5-acc2-d84b1f43c9d1', '3de0c2b4-c4da-5f6e-a951-d3949ea73162', '2026-27', 'priority', 'ROLLING', 'Fall priority deadline - international (fall 2027 entry)', '2027-04-15', 'SUU admits on a rolling basis. The page prints no year; taken as fall 2027. Spring-semester priority date is October 15 and summer is February 15. Allow at least one month for processing, shipping and embassy appointments.', 'c861df02-646a-5f2d-a5ac-860a491fa779'),
 ('90fa3e59-1a16-58b4-ac4b-a0f62783934d', '3de0c2b4-c4da-5f6e-a951-d3949ea73162', '2026-27', 'application', 'ROLLING', 'Fall final deadline - international (fall 2027 entry)', '2027-07-15', null, 'c861df02-646a-5f2d-a5ac-860a491fa779');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('3de0c2b4-c4da-5f6e-a951-d3949ea73162', 'required_nonnative', 'Alternatives to a test: an undergraduate degree from an accredited US or English-speaking-country institution, or an official transcript from an English language program showing an 80% or B average; ACT 18 or SAT critical reading 450 also appear on the list of accepted proofs. Scores must be no more than two years old and official (screenshots not accepted). Other accepted tests: iTEP Academic 4.2, TOEFL Essentials 7.5, Michigan English Test 52, LanguageCert Academic 60. SUU offers an Intensive English Program; the pages reviewed do not describe a conditional-admission pathway into degree programs (contact intladm@suu.edu).', 'c861df02-646a-5f2d-a5ac-860a491fa779');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
