insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('2e1cf252-2d9e-5cf2-824d-6f6c42fbc5c4', '2026-27', 'optional', 'The 2025-26 catalog says submitting ACT or SAT scores is optional for international applicants because SWOSU is in a test-optional pilot program. International students are encouraged to take the Accuplacer CPT at the SWOSU Assessment Center before enrolling.', '73912dc4-730e-5da2-848b-4f16a005eccb');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('2e1cf252-2d9e-5cf2-824d-6f6c42fbc5c4', '2026-27', array['own']::text[], 100, 'US$100 non-refundable international application fee. Documents: high school transcript translated into English (course-by-course NACES-member evaluation for coursework outside the U.S.), passport photo page, signed Undergraduate Certificate of Financial Resources, and a sponsor-name bank statement showing 3-6 months of history and dated within 1 month of applying. Applicants from Gambia, Ghana, Nigeria, Liberia and Sierra Leone also provide WAEC scratch card details. Some mostly-online programs may not qualify for an I-20.', '639f0d94-9266-51ac-a97e-e9ef6d21d6e7');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('9d2a751e-db34-5af7-b464-ffbb213f134b', '2e1cf252-2d9e-5cf2-824d-6f6c42fbc5c4', '2026-27', 'application', 'ROLLING', 'Application (fall 2027): no international deadline published', null, 'The international undergraduate page and the 2025-26 catalog print no application deadline for first-year international students.', '639f0d94-9266-51ac-a97e-e9ef6d21d6e7'),
 ('ddb1b03c-18f7-5045-b10f-5df9b8bc0a18', '2e1cf252-2d9e-5cf2-824d-6f6c42fbc5c4', '2026-27', 'scholarship', null, 'Academic and Foundation scholarship paperwork: best-consideration date (fall 2027)', '2027-03-01', 'The 2025-26 catalog lists March 1 for Regents'' baccalaureate or academic scholarship documents and for the Foundation Scholarship Application (no year printed, treated as 2027). The catalog does not say whether international students are eligible.', '73912dc4-730e-5da2-848b-4f16a005eccb');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('2e1cf252-2d9e-5cf2-824d-6f6c42fbc5c4', 'required_nonnative', 'No test-score waiver is printed for first-year international applicants. Students slightly below the minimum (TOEFL iBT 48 or higher, IELTS 5.0, PTE 36, iTEP 3.0) may complete 12 weeks at The Language Company (ESL, with at least two-thirds advanced-level instruction); students below that can apply for ESL through The Language Company. International transfer students with at least 24 U.S. credit hours do not need scores.', '639f0d94-9266-51ac-a97e-e9ef6d21d6e7');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
select '2e1cf252-2d9e-5cf2-824d-6f6c42fbc5c4'::uuid, 'required_option', '639f0d94-9266-51ac-a97e-e9ef6d21d6e7'::uuid, v.* from (values
 ('TOEFL_IBT', 61, 'The page does not give a minimum on the new 1-6 scale.'),
 ('IELTS', 5.5, 'IELTS Academic, overall band.'),
 ('PTE', 44, 'PTE Academic. iTEP Academic 3.5 is also accepted. Duolingo and Cambridge are not listed.')) v;
