insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('09afff14-6d28-5867-a5bd-c05e44a6a170', '2026-27', 'optional', '''SCSU is completely test optional.'' Submit ACT/SAT only if they may enhance admission or scholarship consideration. Guaranteed admission with a 2.5 GPA (4.0 scale) for students with no college credits.', '190c777f-38c8-5247-9760-959997af8e9b');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('09afff14-6d28-5867-a5bd-c05e44a6a170', '2026-27', array['own']::text[], 0, 'SCSU''s own online application; no application fee (''SCSU no longer requires an application fee''). No essay or recommendations are required (optional). International applicants must show a bank statement of at least US$29,178 for the first year (dated within 6 months) and a Financial Form.', '190c777f-38c8-5247-9760-959997af8e9b');
insert into deadlines (id, institution_id, cycle, kind, label, due_date, notes, source_id) values
 ('086e1647-e511-5534-9f5d-50203c207e7e', '09afff14-6d28-5867-a5bd-c05e44a6a170', '2026-27', 'priority', 'International priority deadline, fall 2027 (applicants outside the U.S.)', '2027-07-01', 'Applicants inside the U.S.: July 15. Later applications are still considered but may be deferred to the next term. The page prints dates without a year; treated as fall 2027. CDS 2024-25 (C14) lists Aug. 15 as the general closing date with rolling admission.', 'cd19ab13-4329-56f1-97a7-5144b905ac53');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('09afff14-6d28-5867-a5bd-c05e44a6a170', 'required_nonnative', 'Alternatives to a test: graduation from a U.S. high school; English-medium high school or university graduation with a 2.5 GPA plus a principal''s letter; IGCSE/O-Levels with C or above in English, math, a hard science, a social science and one other subject; 12+ U.S. university credits with 2.5 GPA; completion of SCSU''s Intensive English Center; ELS level 112; SAT ERW 400+ (or Reading 20+); ACT English 15+; LanguageCERT 60. Reports must be under 2 years old. Conditional admission is available for qualified applicants whose English is below the requirement.', '2da88c06-3a86-5cbc-87d1-6ad01700691d');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, min_subscores, notes)
select '09afff14-6d28-5867-a5bd-c05e44a6a170'::uuid, 'required_option', '2da88c06-3a86-5cbc-87d1-6ad01700691d'::uuid, v.* from (values
 ('TOEFL_IBT', 61, '{"reading": 15, "writing": 15, "listening": 15}'::jsonb, 'Tests before 2026-01-21. Paper TOEFL 500.'),
 ('TOEFL_IBT_2026', 3.5, '{"reading": 3.5, "writing": 3.0, "listening": 3.0}'::jsonb, 'Tests on/after 2026-01-21 (page does not name the 1-6 scale).'),
 ('IELTS', 5.5, null, 'IELTS Indicator at 5.5 is accepted ''until further notice''.'),
 ('DUOLINGO', 95, null, 'Official report must come through the Duolingo dashboard. A separate graduate-admissions knowledge-base article says Duolingo will not be accepted from Summer 2026; the undergraduate page still lists it, so confirm with International Admissions.'),
 ('PTE', 47, null, 'PTE Academic, score report website only.')) v;
insert into score_codes (institution_id, test_key, code, notes, source_id) values
 ('09afff14-6d28-5867-a5bd-c05e44a6a170', 'toefl', '6679', 'SCSU TOEFL code from the international application page.', 'cd19ab13-4329-56f1-97a7-5144b905ac53');
insert into cost_aid (institution_id, year, tuition_intl_usd, required_fees_usd, room_board_usd, other_usd, total_coa_usd, intl_aid_policy, meets_full_need, merit_scholarships, notes, source_id) values
 ('09afff14-6d28-5867-a5bd-c05e44a6a170', '2025-2026', 19910, 1474, 10970, 5476, 37830, 'merit_only', false, true, 'SCSU international costs page (updated 2025-07-25, 9 months): tuition with the Academic and Cultural Sharing Scholarship (ACSS) $11,258; tuition and fees without it $21,384 ($19,910 tuition + $1,474 fees); room and board $10,970; insurance, books and supplies $5,476. The page''s I-20 total WITH ACSS is $29,178; $37,830 here is the sum of the published no-scholarship lines.; Academic and Cultural Sharing Scholarship (ACSS) lowers international undergraduate tuition (about $8,652 per year on the costs page; renewable each semester with a 2.5 GPA and cultural-sharing activities). The costs page says students opt in at orientation; other SCSU pages describe it as applied automatically to the first semester. Need-based awards depend on FAFSA, which international students cannot file.', 'cf093cc9-3f34-5699-b21b-0e2e77e577c3');
