insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('36a4d09d-8dfd-5d79-b672-4e65773a720d', '2026-27', 'optional', 'SAT or ACT scores are optional (the international page says so directly). The SAT essay is not required.', 'bc71e5dc-7e50-5e41-861a-95eb63283841');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('36a4d09d-8dfd-5d79-b672-4e65773a720d', '2026-27', array['common_app','own']::text[], 50, 'Apply through the Common App, the St. Edward''s application or ApplyTexas. The $50 fee is waived for applications by Jan. 1 (Early Application deadlines). Required: online application, essay, high school or college transcripts and an academic recommendation form; TOEFL, IELTS, Duolingo or Kaplan Test of English if English is not the first language (Kaplan accepted on a provisional basis). The undergraduate deadlines page lists an additional Nov. 1 ''First Review'' date; it does not appear on the international page. Whether the Early Application plans are binding is not stated; no early decision plan is mentioned.', 'bc71e5dc-7e50-5e41-861a-95eb63283841');
insert into deadlines (id, institution_id, cycle, kind, label, due_date, notes, source_id) values
 ('68963c7c-cd4f-5fcd-a61b-e0559a4128ac', '36a4d09d-8dfd-5d79-b672-4e65773a720d', '2026-27', 'application', 'Early Application (fall 2027 entry)', '2026-12-01', 'No application fee if applied by this date. Dates are printed without a year and treated as the fall 2027 cycle.', 'bc71e5dc-7e50-5e41-861a-95eb63283841'),
 ('16d9aded-fca5-5821-b16e-4c3ea607541f', '36a4d09d-8dfd-5d79-b672-4e65773a720d', '2026-27', 'application', 'Early Application II (fall 2027 entry)', '2027-01-01', 'No application fee if applied by this date.', 'bc71e5dc-7e50-5e41-861a-95eb63283841'),
 ('a80b25b4-91b4-5f09-81fe-bbde7327b054', '36a4d09d-8dfd-5d79-b672-4e65773a720d', '2026-27', 'priority', 'Priority Application (Moreau and other academic scholarships)', '2027-02-01', 'The international page ties this date to the Moreau Scholarship and other academic scholarships.', 'bc71e5dc-7e50-5e41-861a-95eb63283841'),
 ('0aa6faf7-9fd1-5e09-9792-fa142ab56186', '36a4d09d-8dfd-5d79-b672-4e65773a720d', '2026-27', 'application', 'Final Application (fall 2027 entry)', '2027-05-01', 'Last date to be considered for fall admission; earlier applications are encouraged.', 'bc71e5dc-7e50-5e41-861a-95eb63283841'),
 ('7c99bee3-c76b-52ec-9d2a-71959f1d0814', '36a4d09d-8dfd-5d79-b672-4e65773a720d', '2026-27', 'deposit', 'Final enrollment deposit', '2027-05-01', 'Non-refundable deposit (students admitted late deposit within two weeks of acceptance).', 'bc71e5dc-7e50-5e41-861a-95eb63283841'),
 ('15fde1e6-1044-5135-8658-12eed7f63ea6', '36a4d09d-8dfd-5d79-b672-4e65773a720d', '2026-27', 'financial_aid', 'CSS Profile priority deadline (international applicants, new students)', '2027-02-15', 'St. Edward''s CSS Profile code is 6619. No CSS Profile fee waiver.', '61c9cd50-2830-5fc5-80a2-c0f17d4cef12');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('36a4d09d-8dfd-5d79-b672-4e65773a720d', 'required_nonnative', 'The international page requires TOEFL, IELTS, Duolingo English Test or Kaplan Test of English (provisional) only ''if English is not your first language''. Exemption rules and minimum scores for first-year applicants are not published on the pages reviewed; the 79 iBT / 6.0 IELTS / 550 ITP figures found on the site apply to a partner dual-degree program, not to first-year applicants.', 'bc71e5dc-7e50-5e41-861a-95eb63283841');
