insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, pct_submit_sat, pct_submit_act, notes, source_id, source_note) values
 ('a641710d-4d4c-5d5b-b0be-0914ec099458', '2024-2025', 24208, 20196, 2350, 23, 2, 'Baseline from IPEDS (fall 2024 entering class): applicants, admits and enrollees from the Education Data Portal; test submission rates and percentiles from College Navigator. No public Common Data Set was found (St. John''s Institutional Research page links only an At a Glance PDF and a fast fact card), so GPA, residency splits and international applicant counts are not available. SAT/ACT percentiles cover the 23% (538) / 2% (43) of enrollees who submitted scores. Undergraduate enrollment and the nonresident count (335, about 2%) are IPEDS fall 2024 undergraduate headcounts.', '9247be64-d738-5b11-b4b0-c57847c07726', 'admissions_site');
