insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('a641710d-4d4c-5d5b-b0be-0914ec099458', '2026-27', 'optional', 'International first-year applicants who submit an English proficiency score do not need SAT/ACT (unless the program requires it); applicants exempt from the English test who skip SAT/ACT can request to be reviewed test-optional. SAT/ACT is not needed for conditional-admission review. School codes: SAT 2799, ACT 2888.', 'a06f8681-c77b-569c-8286-69115ec25949');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('a641710d-4d4c-5d5b-b0be-0914ec099458', '2026-27', array['common_app','own']::text[], 0, 'Apply with the free St. John''s application or the Common App; the requirements page says there is no application fee for online submissions (the FAQ page still mentions a $70 non-refundable fee). Required: official academic records with certified English translation and an English test unless exempt. Essay and recommendation letters are strongly encouraged but not required, except Pharmacy (both required). Applicants with an education gap over three months submit a statement of activity.', 'a06f8681-c77b-569c-8286-69115ec25949');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('a7eb6832-8846-590a-b921-78f418ccf1f5', 'a641710d-4d4c-5d5b-b0be-0914ec099458', '2026-27', 'application', 'EA', 'Early Action (fall 2027 entry)', '2026-12-01', 'Pharmacy and Bio-Optometry have their own deadlines and accept fall applicants only.', '109c8aea-db61-5acc-9238-f1fd58e17093'),
 ('f33d4e1b-9200-55b5-b825-a226543553d6', 'a641710d-4d4c-5d5b-b0be-0914ec099458', '2026-27', 'application', 'RD', 'Regular Decision (fall 2027 entry)', '2027-02-01', 'St. John''s follows a rolling admission policy: applications after the deadline are considered while space is available (not for Pharmacy and Bio-Optometry).', '109c8aea-db61-5acc-9238-f1fd58e17093');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('a641710d-4d4c-5d5b-b0be-0914ec099458', 'required_nonnative', 'Applicants who graduate from a secondary school in a country where English is an official language need no test. Three pathways: Direct Admission, the ELITE program (enroll full-time in the degree program with credit-bearing ESL courses), and Conditional Admission (full-time non-credit English Language Institute first, then the degree program; no English or SAT/ACT scores needed, but interest must be marked on the application). Thresholds are effective for fall 2026: TOEFL iBT 80+ direct / 61-79 ELITE / 33-60 conditional; IELTS 6.5+ / 6 / 3.0-5.5; Duolingo 110+ / 95-105 / 90 or below; PTE 53 / 44-52 / 43 or below; SAT EWR 440+ direct (400-430 ELITE); ACT English 15+ direct (14 ELITE).', 'a06f8681-c77b-569c-8286-69115ec25949');
insert into english_requirements (institution_id, source_id, test_key, status, min_total, notes)
