insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('08316a6f-ed91-529f-a791-815c11ef3cdb', '2026-27', 'optional', 'Applicants must submit ACT/SAT scores or a personal statement (''it is your choice, but one must be submitted''). Admission is rolling.', 'ce5e449c-1d46-54b9-be7d-0885c9fb9e64');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('08316a6f-ed91-529f-a791-815c11ef3cdb', '2026-27', array['common_app','coalition','own']::text[], 0, 'The St. Mary''s application, ApplyTexas, Common App and Coalition App are all accepted free of charge. Required: application, high school transcript, and either test scores or a personal statement; one recommendation letter and a resume are optional. International applicants submit the application plus official high school transcripts (scratch card information for West African exam countries). CDS C7 rates GPA very important, and rigor, test scores, essay, extracurriculars, character and volunteer work important.', 'cf06a02c-665e-5897-b05e-8615a9fce31a');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('92a66baf-27a4-5846-a4d8-ebb8f849e964', '08316a6f-ed91-529f-a791-815c11ef3cdb', '2026-27', 'application', 'ROLLING', 'International fall 2027 application: all items due by May 1', '2027-05-01', 'The international page lists fall (August-December) entry due May 1 and spring due Oct. 1; no year is printed, treated as fall 2027. Decisions come about 3-4 weeks after all materials, including transcripts and English scores, arrive.', 'cf06a02c-665e-5897-b05e-8615a9fce31a'),
 ('e9727beb-31b8-5a5f-84c9-6c59ed31fb6f', '08316a6f-ed91-529f-a791-815c11ef3cdb', '2026-27', 'priority', null, 'Priority date for admission and general merit scholarships (fall 2027)', '2026-12-15', 'The first-year page prints Dec. 15 without a year; treated as fall 2027. Admission is rolling.', 'ce5e449c-1d46-54b9-be7d-0885c9fb9e64'),
 ('1008c87d-87e2-560c-919d-03e17acb83ce', '08316a6f-ed91-529f-a791-815c11ef3cdb', '2026-27', 'scholarship', null, 'Preferred date for Specialty Scholarships (fall 2027)', '2026-10-31', 'Year not printed; treated as fall 2027 entry.', 'ce5e449c-1d46-54b9-be7d-0885c9fb9e64'),
 ('80004b61-8fca-53c5-9c1f-58595f9e1db1', '08316a6f-ed91-529f-a791-815c11ef3cdb', '2026-27', 'scholarship', null, 'Apply by Feb. 1 for automatic academic merit scholarship consideration', '2027-02-01', 'From the scholarships page for first-time freshmen who enroll full-time; the page does not say whether international students qualify.', 'c820669b-73d7-5ab2-b836-422db3eec9ff'),
 ('b2ccb566-c12b-588c-a9e9-b30a5144f4af', '08316a6f-ed91-529f-a791-815c11ef3cdb', '2026-27', 'deposit', null, 'Preferred enrollment deposit date', '2027-05-01', null, 'ce5e449c-1d46-54b9-be7d-0885c9fb9e64');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('08316a6f-ed91-529f-a791-815c11ef3cdb', 'required_nonnative', 'Exempt: applicants with a US high school diploma or a degree from an accredited US institution, a bachelor''s or equivalent from a non-US university in a country where English is the main language of instruction, and citizens of listed countries (e.g. Canada except Quebec, UK, Australia, Nigeria); waivers are decided case by case, and AP/IB and other curricula may be considered in place of tests. Scores must be within six months of the application date and come directly from the testing agency. Applicants without the scores can take the Intensive English Program (online, about $1,350 per course plus a $100 deposit; needs B1 level and an iTEP placement test); the pages do not describe a conditional-admission route for undergraduates.', 'e47e3d5f-1d90-5059-8826-35277b914d1b');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
select '08316a6f-ed91-529f-a791-815c11ef3cdb'::uuid, 'required_option', 'cf06a02c-665e-5897-b05e-8615a9fce31a'::uuid, v.* from (values
 ('TOEFL_IBT', 80, 'The pages do not list a minimum for the new 1-6 TOEFL.'),
 ('IELTS', 6.0, null),
 ('DUOLINGO', 110, '110 or higher for undergraduates (graduate minimum is 115).')) v;
insert into score_codes (institution_id, test_key, notes)
select '08316a6f-ed91-529f-a791-815c11ef3cdb'::uuid, v.* from (values
 ('sat', 'The pages read do not print a numeric SAT code; look it up in the College Board code search (FAFSA school code 003623 is not an SAT code).'),
 ('act', 'The pages read do not print a numeric ACT code; look it up at act.org.'),
 ('toefl', 'No TOEFL institution code is printed on the pages read.'),
 ('ielts', 'No institution code is listed on the pages read.'),
 ('duolingo', 'No institution code is listed on the pages read.'),
 ('pte', 'No institution code is listed on the pages read.')) v;
insert into cost_aid (institution_id, year, tuition_usd, required_fees_usd, room_board_usd, books_usd, intl_need_aid_awarded, intl_avg_award_usd, meets_full_need, merit_scholarships, notes, source_id) values
 ('08316a6f-ed91-529f-a791-815c11ef3cdb', '2026-2027', 38404, 1478, 13438, 1300, 55, 42263, false, true, 'CDS G1 (full 2026-2027 year): tuition $38,404, required fees $1,478, food and housing $13,438; books $1,300. CDS H6: 55 degree-seeking nonresidents received institutional aid, average $42,263 (total $2,324,499) for the aid year the CDS marks as 2023-24; the CDS does not say whether this is need-based or merit aid.; First-time freshmen who apply by Feb. 1 and enroll full-time are automatically considered for academic merit scholarships of $10,000-$26,000 per year; the page does not say whether international students are eligible. The Global Scholars Program gives international students $2,000 per year for academic excellence and cultural understanding (renewed annually). The university reports that nearly 98% of first-time freshmen receive scholarships or institutional grants. CDS H6: 55 nonresidents received institutional aid, average $42,263.', '10625a68-7526-5b6a-b1ca-204eb085da6f');
