 ('357205fa-c9b9-50b5-8f64-cd3a7792c17c', '949547d9-66fc-5db6-b06f-4a3fa2f05c10', 'other', 'St. Thomas University Undergraduate Catalog 2025-2026 (admissions, tuition, housing)', 'https://www.stu.edu/wp-content/uploads/2025/08/Final-UG-Catalog-2025-2026-08-27-25.pdf', null, '2026-10-26');
insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, notes, source_id, source_note) values
 ('949547d9-66fc-5db6-b06f-4a3fa2f05c10', '2024-2025', 7095, 6947, 726, 'Baseline from IPEDS fall 2024 (College Navigator percentages; exact counts from the NCES ADM2024 file via the Urban Institute Education Data Portal). No Common Data Set was read, so international applicants/admits, GPA and admission factors are not included. St. Thomas is test optional and reports no SAT/ACT percentiles.', 'bd4e5a1e-8a25-55f9-ab91-4879fe9246a6', 'admissions_site');
insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('949547d9-66fc-5db6-b06f-4a3fa2f05c10', '2026-27', 'optional', 'Test optional; applicants may send SAT/ACT scores for course placement. Freshman minimum is a weighted 2.50 GPA (lower GPAs reviewed case by case) and 18 high school units.', '357205fa-c9b9-50b5-8f64-cd3a7792c17c');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('949547d9-66fc-5db6-b06f-4a3fa2f05c10', '2026-27', array['own','common_app']::text[], 0, 'Free application at apply.stu.edu or the Common App. High school transcript (unofficial accepted for review) plus an official NACES or AICE credentials evaluation for non-U.S. schools. The I-20 is issued only after the enrollment deposit ($200 per the international page) with a Statement of Financial Sponsorship, passport page and bank affidavit covering at least one year''s cost of attendance.', '357205fa-c9b9-50b5-8f64-cd3a7792c17c');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('44c05d87-8089-5e55-bdfb-cc05a35f6170', '949547d9-66fc-5db6-b06f-4a3fa2f05c10', '2026-27', 'priority', 'ROLLING', 'Priority deadline, fall 2027 entry (rolling)', '2027-05-01', 'Catalog: applications are reviewed on a rolling basis; the application opens July 1; the fall priority deadline is May 1 and the spring one is December 1. Late applications face limits on scholarships, courses, orientation and housing. Dates print without a year (treated as fall 2027); no separate international deadline is published.', '357205fa-c9b9-50b5-8f64-cd3a7792c17c');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('949547d9-66fc-5db6-b06f-4a3fa2f05c10', 'required_nonnative', 'Required of applicants from countries where English is not the primary language who have not attended a U.S., UK or Canadian school; the international page lists 44 exempt countries and territories. Any one of the listed tests satisfies it. No conditional admission or ESL pathway is described on the pages read.', '2461706d-1d63-57c6-b55b-6d76edf68141');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
