insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('7fba1c54-a6dc-55d7-ae82-35e1d9c44efa', '2026-27', 'optional', 'Page heading: test-optional for the 2025-26 and 2026-27 terms; scores are not required, are encouraged because some scholarships use them, and will not disadvantage an applicant. Top 25% of class admitted automatically; second quarter needs SAT 1030 / ACT 20, third quarter SAT 1170 / ACT 24, fourth quarter file review; otherwise holistic review. The page does not say whether test-optional continues after 2026-27. The international page says test scores are never required for international admission (it also lists them as required in one place; confirm with the office).', 'd0835ca8-eba8-5da1-9b7b-e72dabf4da2e');
insert into application_requirements (institution_id, cycle, platforms, notes, source_id) values
 ('7fba1c54-a6dc-55d7-ae82-35e1d9c44efa', '2026-27', array['own']::text[], 'Application link is to SFA''s own application-for-admission page; the CDS lists applytexas.org and commonapp.org as application URLs. CDS C13 shows an application fee of $50, but the admissions pages read do not state a fee, so it is not recorded as the live figure. International first-year applicants need a minimum 2.5 cumulative GPA on a course-by-course credential evaluation of all secondary schools. SAT code 6682, ACT code 4188.', '92602651-93c8-524d-b1f8-95ba6ebb8ca1');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('79b05d30-313a-5aeb-947b-093ca8800f5d', '7fba1c54-a6dc-55d7-ae82-35e1d9c44efa', '2026-27', 'application', 'RD', 'International fall application deadline (fall 2027 entry)', '2027-06-01', 'International page: fall, submit all documents by June 1; spring, October 1; summer has no listed deadline (email international@sfasu.edu). The page prints no year; treated as fall 2027. Domestic first-year admission is rolling with no application deadline; CDS C16 says decisions begin March 15.', '92602651-93c8-524d-b1f8-95ba6ebb8ca1');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('7fba1c54-a6dc-55d7-ae82-35e1d9c44efa', 'required_nonnative', 'Waiver for students who earned a secondary or post-secondary diploma in English in listed countries (e.g. Canada except Quebec, UK, Australia, Ireland, Nigeria, Singapore, Ghana, Kenya). Also met by a US high school diploma or higher in the two years before starting, completion of ELS Level 112, or Texas Intensive English Program (TIEP) Level 160 (no grade below B) or Level 150 (all A). Tests must be no more than two years old. Educator Preparation programs allow no waivers. No conditional admission is mentioned; the ELS and TIEP completions are the only intensive-English routes listed.', '4b489fa2-8a6e-5b87-89eb-a0e4b4f11243');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
select '7fba1c54-a6dc-55d7-ae82-35e1d9c44efa'::uuid, 'required_option', '4b489fa2-8a6e-5b87-89eb-a0e4b4f11243'::uuid, v.* from (values
 ('TOEFL_IBT', 79, 'Listed minimum for tests taken before Jan. 21, 2026.'),
 ('TOEFL_IBT_2026', 4.5, 'Listed minimum for tests taken after Jan. 21, 2026. The page does not name the scale for 4.5; it is read as the new 1-6 scale.'),
 ('IELTS', 6.5, 'Overall band.'),
 ('DUOLINGO', 100, 'Accepted for undergraduate admission only.')) v;
insert into score_codes (institution_id, test_key, code, notes, source_id)
select '7fba1c54-a6dc-55d7-ae82-35e1d9c44efa'::uuid, v.* from (values
