insert into cost_aid (institution_id, year, tuition_usd, tuition_out_of_state_usd, required_fees_usd, room_board_usd, books_usd, other_usd, intl_aid_policy, intl_need_aid, meets_full_need, merit_scholarships, notes, source_id) values
 ('7fba1c54-a6dc-55d7-ae82-35e1d9c44efa', '2025-2026', 7761, 19911, 3467, 13940, 1206, 1850, 'merit_only', false, false, true, 'CDS G1 (first-year, 2025-2026): in-state tuition $7,761, out-of-state $19,911, required fees $3,467, food and housing $13,940; G5 books $1,206 and other expenses $1,850. No separate international tuition figure is printed in the CDS (the nonresident row is blank).; OIP scholarship is $1,000 per year (requires financial need, 2.75 GPA for undergraduates, application due April 30; the page does not say whether new freshmen can apply). Recipients of a competitive scholarship of $1,000 or more may pay Texas resident tuition (page: about $4,500 less per semester). Scholarship funds are limited. Financial proof for the I-20: $39,428, or $28,708 with a scholarship of $1,000 or more.', '36c70b1a-d05c-574b-bf3b-f32d2dd1398c');
