insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, pct_submit_sat, pct_submit_act, notes, source_id, source_note) values
 ('442e0a13-6127-56f6-a6ea-83aed820c1bd', '2024-2025', 10308, 8487, 923, 12, 2, 'Baseline from IPEDS (fall 2024 entering class): applicants, admits and enrollees from the Education Data Portal; test submission rates and percentiles from College Navigator. Suffolk does not publish a Common Data Set (its Institutional Research page lists a Factbook on the staff intranet only), so GPA, residency splits and international applicant counts are not available. SAT/ACT percentiles cover the 12% (115) / 2% (19) of enrollees who submitted scores. Undergraduate enrollment and the nonresident count (518, about 12%) are IPEDS fall 2024 undergraduate headcounts.', '034fe60f-32d2-5247-a986-eb52b9ba5758', 'admissions_site');
insert into test_score_percentiles (institution_id, cds_year, source_id, test, p25, p50, p75)
select '442e0a13-6127-56f6-a6ea-83aed820c1bd'::uuid, '2024-2025', '034fe60f-32d2-5247-a986-eb52b9ba5758'::uuid, v.* from (values
