insert into cost_aid (institution_id, year, tuition_usd, tuition_intl_usd, required_fees_usd, room_board_usd, books_usd, other_usd, total_coa_usd, intl_aid_policy, intl_need_aid, meets_full_need, merit_scholarships, merit_separate_app, notes, source_id) values
 ('442e0a13-6127-56f6-a6ea-83aed820c1bd', '2026-2027', 51340, 51340, 656, 25862, 1200, 3402, 82460, 'merit_only', false, false, true, false, 'Undergraduate resident (on-campus) estimate for 2026-27: tuition $51,340, fees $656, housing $19,962, food $5,900, books $1,200, loan fees $74, transportation $1,334, miscellaneous $1,994 (total $82,460). One tuition rate for all students.; All applicants are automatically considered for merit aid; Suffolk''s merit scholarships for international students cover up to 50 percent of tuition (no dollar range or GPA grid is published). Need-based financial aid is available to U.S. citizens and permanent residents only.', '428b0c2d-624b-5943-b5d6-d20d2fe71207');
