insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('3c83d810-cf89-564b-ac78-5efc9448b2a1', '2026-27', 'optional', 'CDS C8 (applying for fall 2026): SAT/ACT is ''not required for admission, but considered if submitted''; scores must arrive by 8/15 if sent. The international requirements page lists no test requirement beyond a 2.0 GPA and English proficiency.', '8810a589-4d17-5f7d-9d43-f1ca3a3e1c81');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('3c83d810-cf89-564b-ac78-5efc9448b2a1', '2026-27', array['common_app','own']::text[], 50, 'SUNY Canton accepts ApplySUNY or the Common App; the $50 fee is from CDS C13. International applicants need a cumulative GPA of 2.0 or higher (US scale) plus English proficiency, transcripts translated into English (SpanTran evaluation strongly encouraged), the International Student Financial form with supporting documents, and a color copy of the passport bio page. Nursing, Practical Nursing, Physical Therapist Assistant and the veterinary programs are selective with a separate Feb. 1 preferred deadline.', 'cbcef46f-e6e7-5566-96bb-22a84ae8bcaa');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('c08a9b6e-e491-5e98-9b31-bf04c319a933', '3c83d810-cf89-564b-ac78-5efc9448b2a1', '2026-27', 'priority', 'ROLLING', 'Fall priority deadline (fall 2027 entry)', '2027-04-01', 'Rolling admission; April 1 is the priority date and students are encouraged to apply by December 15. The page prints no year, so this is treated as fall 2027. No separate international application deadline is printed.', '001abe84-6135-51ac-be85-c227dc286a9a'),
 ('ed918057-fa46-545e-8c9e-1cf2923f6f84', '3c83d810-cf89-564b-ac78-5efc9448b2a1', '2026-27', 'priority', 'ROLLING', 'Preferred fall deadline for selective programs', '2027-02-01', 'Nursing, Nursing Dual Degree, Practical Nursing, Physical Therapist Assistant, Veterinary Science Technology and Veterinary Technology; no year printed, treated as fall 2027.', '001abe84-6135-51ac-be85-c227dc286a9a'),
 ('236a6bba-8caf-5ee1-a584-6dced5587646', '3c83d810-cf89-564b-ac78-5efc9448b2a1', '2026-27', 'other', null, 'International financial documentation due for I-20 (fall)', '2027-07-01', 'SUNY Canton considers I-20 status only for students who submit completed financial statements and documents by July 1 for fall (December 1 for spring); no year printed, treated as fall 2027.', '62ec9ac6-c74f-5437-9ed8-de846eb7960c');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('3c83d810-cf89-564b-ac78-5efc9448b2a1', 'required_nonnative', 'Proof of English proficiency is required when English is not the first language. A college-level English course with a final grade of C or higher also satisfies it. Students who meet the GPA requirement but not the English requirement can accept Conditional Admission and complete an ESL program at partner Fulton-Montgomery Community College (one to two semesters), after which admission is guaranteed.', '3675f3c5-cf15-57b1-b0e2-8e020315a924');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, min_subscores, notes)
select '3c83d810-cf89-564b-ac78-5efc9448b2a1'::uuid, 'required_option', '3675f3c5-cf15-57b1-b0e2-8e020315a924'::uuid, v.* from (values
 ('TOEFL_IBT', 61, null, 'Paper-based 500, computer-based 173. No 1-6 band value is given. Also accepted: iTEP 3.5 or higher.'),
 ('IELTS', 6.0, '{"each_section": 5.5}'::jsonb, null),
 ('PTE', 44, null, 'PTE Academic. The Duolingo English Test is not listed on the page.')) v;
insert into score_codes (institution_id, source_id, test_key, code, notes)
select '3c83d810-cf89-564b-ac78-5efc9448b2a1'::uuid, '3675f3c5-cf15-57b1-b0e2-8e020315a924'::uuid, v.* from (values
 ('sat', null, 'No SAT code is printed on the pages read.'),
 ('act', null, 'No ACT code is printed on the pages read.'),
 ('toefl', '2523', 'TOEFL school code printed on the English proficiency page.')) v;
insert into cost_aid (institution_id, year, tuition_usd, tuition_out_of_state_usd, tuition_intl_usd, required_fees_usd, room_board_usd, books_usd, other_usd, total_coa_usd, intl_aid_policy, meets_full_need, merit_scholarships, notes, source_id) values
 ('3c83d810-cf89-564b-ac78-5efc9448b2a1', '2026-2027', 8742, 13572, 17500, 2000, 18000, 1300, 3500, 41000, 'merit_only', false, true, 'International bachelor''s-degree table (per year): tuition $17,500, comprehensive fees $2,000, books/health insurance/travel/misc. $3,500, room and board $18,000, estimated cost $41,000 (the I-20 financial-support amount). The page prints no academic year, so it is treated as current.; College Navigator 2024-25: tuition includes required fees; total is the on-campus cost of attendance for New York residents ($32,880 at the out-of-state rate). The CDS G1 tuition boxes are blank in the PDF. See the cycle file for the published international cost table.; Accepted students (including international) can complete the general scholarship application, which opens October 1 and matches them to scholarships; amounts are not published. Need-based aid for international students is not mentioned, so it is left unconfirmed.', '62ec9ac6-c74f-5437-9ed8-de846eb7960c');
