insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, notes, source_id, source_note) values
 ('4ea14f48-8282-53e0-9b30-b1957e7773ba', '2024-2025', 7760, 6490, 806, 'Baseline from IPEDS (fall 2024 entering class): applicants, admits and enrollees from the Education Data Portal; enrollment and student-faculty ratio from College Navigator. No public Common Data Set was found. College Navigator shows no SAT/ACT percentiles or submission rates (test-optional); GPA, residency splits and international applicant counts are not available. Undergraduate enrollment is the IPEDS fall 2024 headcount (4,260).', '26db1709-87f2-56fc-abff-d316c5119520', 'admissions_site');
insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('4ea14f48-8282-53e0-9b30-b1957e7773ba', '2026-27', 'optional', 'SAT/ACT are optional for undergraduate admission (required only for special programs such as the B.S./D.O. in Biological Sciences); scores are considered if sent. SAT/ACT do not count as proof of English proficiency. SAT code 2866, ACT code 2939.', 'b83acca9-f1ce-5bdd-a459-09f022efb4e3');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('4ea14f48-8282-53e0-9b30-b1957e7773ba', '2026-27', array['common_app','own']::text[], 50, 'Apply with the Common App or the SUNY application (SUNY code 46); $50 non-refundable fee. International freshmen need an equivalent secondary school average of 80 (U.S. average) or above, a WES or ECE evaluation (waived only for a few countries), a roughly 250-word essay or the SUNY supplemental application, at least one counselor or teacher recommendation, a bank-issued financial statement and a notarized sponsor letter for the I-20, and immunization records.', '7c54f78e-086f-53ef-a147-031f7e3d4e19');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('c5a852a0-221c-5363-816c-51ca1a60ba59', '4ea14f48-8282-53e0-9b30-b1957e7773ba', '2026-27', 'application', 'EA', 'Early Action, recommended date (fall 2027 entry)', '2026-11-15', 'Domestic first-year page; printed without a year and the page header still says ''Apply for Fall 2026'', taken as the fall 2027 cycle. No separate international deadline is published.', 'b83acca9-f1ce-5bdd-a459-09f022efb4e3'),
 ('e1747183-4a67-59c0-9fc7-165d197377a7', '4ea14f48-8282-53e0-9b30-b1957e7773ba', '2026-27', 'application', 'ROLLING', 'Recommended application date, fall 2027 entry', '2027-03-15', 'Applications are reviewed on a rolling, first-come basis after the recommended dates until enrollment goals are met; spring entry date is Oct. 15. Printed without a year, taken as fall 2027. International applicants need time for the I-20 and visa, so apply well before March.', 'b83acca9-f1ce-5bdd-a459-09f022efb4e3');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('4ea14f48-8282-53e0-9b30-b1957e7773ba', 'required_nonnative', 'Required for international students whose native language is not English; no country-based waiver list is published. Accepted proofs: TOEFL (paper 513, computer 183, iBT 61), IELTS 6.0, iTEP 3.5 or Step EIKEN Grade Pre-1. Duolingo and PTE are not listed. Conditional-admission pathways: ELS Level 112 (English for Academic Purposes), Stony Brook Intensive English Center Level B, a C or higher in a U.S. college English composition course, Nassau Community College LINCC, Fulton-Montgomery Community College ESL, or qualifying CLEP/AP/IB exam scores. SAT/ACT do not count.', '132d44f8-df9c-5f7e-bfc7-92b7983b7f62');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
select '4ea14f48-8282-53e0-9b30-b1957e7773ba'::uuid, 'required_option', '132d44f8-df9c-5f7e-bfc7-92b7983b7f62'::uuid, v.* from (values
 ('TOEFL_IBT', 61, 'Internet-based minimum 61 (also 513 paper / 183 computer). The page gives no new 1-6 scale minimum.'),
 ('IELTS', 6.0, 'Minimum composite score.')) v;
