insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, intl_applicants, intl_admits, in_state_applicants, in_state_admits, out_state_applicants, out_state_admits, pct_submit_sat, gpa_avg, pct_reporting_gpa, notes, source_id) values
 ('200fa570-fa0a-5f39-87d2-42b55d19f4b8', '2024-2025', 15148, 12204, 1265, 491, 462, 13874, 11073, 783, 669, 23, 3.11, 99, 'CDS C1 (fall 2024 first-year class; residency by known physical address): 462 of 491 international applicants were admitted (94%) versus 81% overall; 31 international students enrolled. Average high school GPA 3.11 uses the CDS conversion (HS average x 0.08 - 4.0 from a 100-point scale); the GPA band table could not be read from the PDF text. 23% (291 students) submitted SAT; the CDS shows no ACT submitters (IPEDS: 3%, 34 students). IPEDS fall 2024 ranges: SAT EBRW 530-630, Math 540-640, ACT composite 23-29. No early decision/early action. Undergrad enrollment (5,517) is from College Navigator, fall 2024; it lists 3% nonresident (no headcount).', 'af310711-bf73-5cf8-b31a-2ddd30231084');
insert into test_score_percentiles (institution_id, cds_year, test, p25, p50, p75, source_id) values
 ('200fa570-fa0a-5f39-87d2-42b55d19f4b8', '2024-2025', 'SAT_TOTAL', 1080, 1180, 1250, 'af310711-bf73-5cf8-b31a-2ddd30231084');
insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('200fa570-fa0a-5f39-87d2-42b55d19f4b8', '2026-27', 'optional', '''SUNY Oswego is SAT/ACT optional''; international applicants are not required to submit SAT or ACT scores. Scores may be used for ALEKS/placement and scholarship profiles.', '7bb74865-dcc0-5fcc-9294-f13f62936aaa');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('200fa570-fa0a-5f39-87d2-42b55d19f4b8', '2026-27', array['common_app','own']::text[], 50, 'SUNY Application (plus the SUNY Supplemental Application) or Common App; $50 non-refundable fee. International applicants send official transcripts, proof of English, and a teacher/counselor evaluation; a minimum GPA equivalent to 2.5 on a 4.0 scale is stated. An original signed and stamped bank statement showing first-year funds is requested before applying (sponsor statement if a sponsor pays); a gap statement may be requested. A site banner offered a free application ''now through Nov. 2'' (year not stated).', '27469942-97f1-53fc-abaf-860d35053a90');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('6823b6bc-9629-5101-94c8-b064f3c62370', '200fa570-fa0a-5f39-87d2-42b55d19f4b8', '2026-27', 'application', 'ROLLING', 'Recommended deadline for international applicants: all documents in by mid-May (fall 2027 entry)', '2027-05-15', 'Rolling review; applicants are urged to submit everything by May 15 for fall (Nov. 15 for spring). Pages print no year; treated as fall 2027. The 2024-25 CDS lists a Feb. 1 priority date and rolling decisions beginning Oct. 1.', '27469942-97f1-53fc-abaf-860d35053a90'),
 ('831a1303-f672-5106-b6ba-cb05a1987941', '200fa570-fa0a-5f39-87d2-42b55d19f4b8', '2026-27', 'scholarship', null, 'Priority date for scholarship consideration, fall 2027', '2027-01-15', 'Scholarships page: apply by January 15 for fall admission (November 15 for spring) for priority consideration; no separate scholarship application.', 'b1aed8fb-019b-5209-b452-efc6b364fd2e');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('200fa570-fa0a-5f39-87d2-42b55d19f4b8', 'required_nonnative', '''Exemptions are possible under certain circumstances'' (contact the international office). Scores must be taken within two years of submission. Other accepted evidence includes SAT EBRW 500, ACT English and Reading average 19, IB HL English A 4, A-level English C, IGCSE First Language English C.', '455c33c6-4f93-54e2-a4aa-bce25e81b6a5');
insert into english_requirements (institution_id, source_id, test_key, status, min_total, notes)
select '200fa570-fa0a-5f39-87d2-42b55d19f4b8'::uuid, '455c33c6-4f93-54e2-a4aa-bce25e81b6a5'::uuid, v.* from (values
 ('TOEFL_IBT', 'required_option', 71, 'Exams taken before 1/21/2026. Test Center, Home Edition and Paper accepted. TOEFL Essentials: 8.'),
 ('TOEFL_IBT_2026', 'required_option', 4.0, 'Exams taken after 1/21/2026. The page prints ''4'' without naming the 1-6 scale.'),
 ('IELTS', 'required_option', 6.0, 'Overall band.'),
 ('DUOLINGO', 'required_option', 110, null),
 ('PTE', 'required_option', 55, 'PTE Academic.'),
 ('CAMBRIDGE', 'accepted', 180, 'Cambridge English Proficiency (CPE) or Advanced (CAE) at 180; B2 First is not listed. The page also accepts iTEP (80%+ final level), ELS Level 112, Michigan English Test 52, Oxford ELLT 6.')) v;
insert into score_codes (institution_id, test_key, notes, source_id)
select '200fa570-fa0a-5f39-87d2-42b55d19f4b8'::uuid, v.* from (values
 ('sat', 'No SAT institution code is printed on the pages checked; look it up in the College Board code search.', '7bb74865-dcc0-5fcc-9294-f13f62936aaa'::uuid),
 ('act', 'No ACT code is printed on the pages checked; look it up at act.org.', '7bb74865-dcc0-5fcc-9294-f13f62936aaa'::uuid),
 ('toefl', 'No TOEFL institution code is printed on the English proficiency page.', '455c33c6-4f93-54e2-a4aa-bce25e81b6a5'::uuid),
 ('ielts', 'No institution code is listed.', '455c33c6-4f93-54e2-a4aa-bce25e81b6a5'::uuid),
