insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('43261305-7384-5b16-8496-e718da0e2ede', '2026-27', 'optional', 'SAT/ACT are not required for admission; they may be used for placement (catalog) and CDS C8F says an ACT composite of 19 or SAT 1000 meets the admission requirement. Test scores are required for all Engineering majors. Scores can also serve as English proficiency (SAT 27 Reading or ACT English 21).', '905babd1-7e39-5c9a-ab03-561d8e7dbcdb');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('43261305-7384-5b16-8496-e718da0e2ede', '2026-27', array['own']::text[], 75, 'Apply through the Texas A&M-Kingsville application (admissions.tamuk.edu) or ApplyTexas; international application fee $75, non-refundable (CDS C13: $25 domestic, $75 international). Needed: official secondary school transcript, a university-approved foreign credential evaluation sent by the agency, a letter of sponsorship (dated within 6 months of first enrollment), a bank statement in U.S. dollars (within 12 months; amounts on the OISSS I-20 requirements page), and English proficiency. The I-20 follows admission; decisions take about two months if all documents arrive together. TSI testing is required before registration but is not an admission requirement.', 'eb70ec90-a424-55e2-b6d5-84aa2eadef4c');
insert into deadlines (id, institution_id, cycle, kind, label, due_date, notes, source_id) values
 ('11875dbb-165d-5acd-90cc-5d80ad8539a0', '43261305-7384-5b16-8496-e718da0e2ede', '2026-27', 'application', 'International application and all documents, fall 2027', '2027-06-01', 'Printed as Fall (August) June 1, Spring (January) Oct. 1, Summer (June) May 1, with no year; treated as fall 2027. The catalog lists the same dates. Documents must be in the office before these dates; allow time for TOEFL/IELTS (tests at least 8 weeks before the deadline).', 'eb70ec90-a424-55e2-b6d5-84aa2eadef4c'),
 ('9e297e21-5452-57fc-b0c1-9da186998c11', '43261305-7384-5b16-8496-e718da0e2ede', '2026-27', 'scholarship', 'Merit scholarship priority date (first-time students)', '2027-02-15', 'Complete application including fee, transcripts and test scores by Feb. 15 (no year printed; treated as 2027). The page does not say whether international students are eligible; confirm with scholarships@tamuk.edu.', '026e9516-4df1-5955-aa01-6e0744073bef');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('43261305-7384-5b16-8496-e718da0e2ede', 'required_nonnative', 'Exempt if the applicant completed all formal education in listed countries (including Canada except Quebec, the UK, Australia, Ghana, Nigeria, Jamaica; Puerto Rico applicants must still submit a TOEFL or equivalent), or earned 12+ transferable credits with a C or better including English composition I and II at a U.S. or listed-country institution. Other alternatives: TAMUK ELTC Intensive English program with ''Advanced Plus'' or the advanced level of the Texas Intensive English Program (TIEP); for the lower (61) tier also SAT 27 Reading, ACT English 21, or TSI 351 reading / 340 writing / 4 essay. Scores come directly from the testing body and must be no more than 2 years old. No separate conditional-admission program is described. The university-wide minimum (TOEFL 61) applies to most programs; the College of Arts and Sciences and the Dotterweich College of Engineering require the higher tier (TOEFL 79).', '905babd1-7e39-5c9a-ab03-561d8e7dbcdb');
insert into english_requirements (institution_id, status, test_key, min_total, notes, source_id)
select '43261305-7384-5b16-8496-e718da0e2ede'::uuid, 'required_option', v.* from (values
 ('TOEFL_IBT', 61, '61 iBT for most undergraduate programs; 79 iBT for the College of Arts and Sciences and the Dotterweich College of Engineering. Institution code 6822. The undergraduate pages do not give the new 1-6 scale (the graduate section says ''79 or a 4'').', '905babd1-7e39-5c9a-ab03-561d8e7dbcdb'::uuid),
 ('IELTS', 6.0, '6.0 overall for the 61 tier; 6.5 overall for the 79 tier (Arts and Sciences, Engineering). Electronic score reports only.', '905babd1-7e39-5c9a-ab03-561d8e7dbcdb'::uuid),
 ('DUOLINGO', 100, 'The catalog lists 100 as the equivalent of the 79 tier and prints no lower Duolingo equivalent for the 61 tier; the admissions page sets no minimum and says the most competitive applicants have 100 or higher.', '905babd1-7e39-5c9a-ab03-561d8e7dbcdb'::uuid),
 ('PTE', 53, 'The admissions page states a minimum of 53; the catalog lists 44 for the 61 tier and 53 for the 79 tier.', 'eb70ec90-a424-55e2-b6d5-84aa2eadef4c'::uuid)) v;
