insert into major_admissions (id, institution_id, program, category_key, admit_model, capped, notes) values
 ('fc370162-39f0-561c-9ec7-56bcbd8d459c', '43261305-7384-5b16-8496-e718da0e2ede', 'Engineering (Frank H. Dotterweich College of Engineering)', 'engineering', 'pre_major_competitive', false, 'Full admission needs ACT composite 21 with math 22, or SAT 1050 with math 560. Pre-Engineering (PPEN) takes ACT 18+ with math 19+, or SAT 890+ with math 530+; applicants below that go to Alternate Pre-Engineering (APEN). Test scores are required for all engineering majors.');

