insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('989bc60e-2a8d-5770-a34e-846babdf1dfc', '2026-27', 'optional', 'Automatic admission (accredited U.S. high school graduates) needs top 35% of class OR a 3.0 cumulative GPA with no SAT/ACT required; applicants with no minimum GPA need SAT 1020/1100 or ACT 22. Applicants educated outside the U.S. (including international students) are reviewed through the Committee Review Process, which may weigh high school attended, first-generation status, employment, special abilities, activities, achievement and leadership. Texas Success Initiative (TSI) placement testing applies to non-exempt students (international students can take it online).', 'a98736c7-8868-549c-aa23-f6ac67f0163a');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('989bc60e-2a8d-5770-a34e-846babdf1dfc', '2026-27', array['own']::text[], 30, 'Apply at BecomeAJaguar.com (fee waivers only through ApplyTexas). The first-year page states a $30 fee; the older international page says $50 by money order. International applicants need a course-by-course foreign credential evaluation sent directly from an approved agency (dated within 1 year), and meningitis vaccination evidence if 22 or younger. Essays and recommendations are not listed (CDS C7: not considered).', 'a98736c7-8868-549c-aa23-f6ac67f0163a');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('32cf55d7-9b16-5544-a8f8-7b4beabcc8fe', '989bc60e-2a8d-5770-a34e-846babdf1dfc', '2026-27', 'priority', null, 'Priority application deadline (fall 2027 entry)', '2027-01-15', 'Listed on the first-year page for Fall 2027. The international page does not give separate dates and points to these first-year deadlines. CDS C14 lists a Feb 15 priority date, which differs from the website.', 'a98736c7-8868-549c-aa23-f6ac67f0163a'),
 ('107a1c1f-df5a-51c4-8dab-454465b81031', '989bc60e-2a8d-5770-a34e-846babdf1dfc', '2026-27', 'application', 'ROLLING', 'Final application deadline (fall 2027 entry)', '2027-06-30', 'Rolling admission (CDS C16); no notification date published. International F-1 applicants need time for credential evaluation and the I-20, so apply well before this date.', 'a98736c7-8868-549c-aa23-f6ac67f0163a');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('989bc60e-2a8d-5770-a34e-846babdf1dfc', 'required_nonnative', 'All international students must show English proficiency unless they qualify for a waiver: full secondary or postsecondary education in an approved English-speaking country (list on the page; Puerto Rico not exempt), at least 12 credit hours with grade C or better at a U.S. or approved English-speaking institution, or completion of the advanced-level Texas Intensive English Program (TIEP). Waivers are reviewed individually. Scores must be under 2 years old, sent directly by the testing agency.', '85635d41-5f48-5d09-85ef-3ae274817840');
insert into english_requirements (institution_id, status, test_key, min_total, notes, source_id)
select '989bc60e-2a8d-5770-a34e-846babdf1dfc'::uuid, 'required_option', v.* from (values
 ('TOEFL_IBT', 61, 'Institution code 6712; paper-based 500 also accepted; institutional (residual) TOEFL not accepted.', '85635d41-5f48-5d09-85ef-3ae274817840'::uuid),
 ('TOEFL_IBT_2026', 3.5, 'The page prints ''3.5 (TOEFL iBT)'' next to 61 without naming the 1-6 scale; shown here as the new-scale equivalent.', '85635d41-5f48-5d09-85ef-3ae274817840'::uuid),
 ('IELTS', 6.0, 'The first-year admissions page says IELTS 6.0; the international freshman page says 5.0 overall. The higher figure is shown; confirm with admissions.', 'a98736c7-8868-549c-aa23-f6ac67f0163a'::uuid),
 ('DUOLINGO', 85, 'Can be taken online.', '85635d41-5f48-5d09-85ef-3ae274817840'::uuid),
 ('PTE', 43, null, '85635d41-5f48-5d09-85ef-3ae274817840'::uuid)) v;
