insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('e2959ff6-ac6b-572f-9502-8ea8b5dd8b9a', '2026-27', 'optional', 'SAT/ACT/CLT scores are not required for an admission decision; they are encouraged for scholarships or to fulfil the TSI requirement. First-time freshmen from a foreign high school are exempt from the Texas Uniform Admissions Policy and are reviewed individually (including GPA); scores can help individual review. Students at a U.S. high school on a visa follow the Texas public/private/out-of-state rank-and-curriculum rules.', '975f1270-823c-50eb-a5b9-d6bd966944ea');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('e2959ff6-ac6b-572f-9502-8ea8b5dd8b9a', '2026-27', array['own']::text[], 50, 'Online application, $50 non-refundable fee, official domestic transcript or an international transcript evaluation (NACES/AICE member, in English, must include GPA and GPA scale), proof of English proficiency. After admission: affidavit of financial support, bank letter or statement, and passport copy. Allow at least 60 days for document processing. Recommendation letters are not required but accepted.', 'f052b64b-6f6f-5d63-895f-2ba9692f9beb');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('abd01ee1-70bd-5870-b1cb-b9e22c025c2e', 'e2959ff6-ac6b-572f-9502-8ea8b5dd8b9a', '2026-27', 'application', 'ROLLING', 'International fall application deadline (fall 2027 entry)', '2027-06-15', 'Enforced international deadlines: Spring Nov. 1, Summer Mar. 15 (generally not accepted for undergraduates except Medical Laboratory Science majors), Fall June 15. Years are not printed; fall 2027 assumed. Domestic freshmen: fall Aug. 1 (CDS C14 also lists a Mar. 1 priority date).', '5d86b987-38c8-59f0-843d-bab5567551d3'),
 ('d53f1c0c-a0c7-5348-a388-0a830a98b14a', 'e2959ff6-ac6b-572f-9502-8ea8b5dd8b9a', '2026-27', 'scholarship', null, 'General scholarship application priority date (fall 2027 entry)', '2027-02-15', 'President''s Guaranteed Scholarship Program: applying through the Tarleton General Scholarship application is required; later applications are considered as funding allows. The page does not state whether international students are eligible.', '8866d77d-3dc5-5eb8-b486-03771fa8868c');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('e2959ff6-ac6b-572f-9502-8ea8b5dd8b9a', 'required_nonnative', 'Exempt: citizens of listed English-speaking countries (e.g. Australia, Canada except Quebec, Ireland, Jamaica, Ghana, Nigeria, New Zealand, United Kingdom); 6 college hours of English incl. 3 of composition (C or better) at a U.S., Canadian (non-Quebec), British or Australian institution; SAT EBRW 550 or ACT English 21; two years at an accredited U.S. high school; a school letter verifying all secondary education was in English (reviewed by Admissions); or completion of Level 9 at The Language Company. Scores must be no more than 2 years old at the start of the term (TOEFL/IELTS valid 3 years, PTE/Duolingo 2 years per the footnote).', 'f052b64b-6f6f-5d63-895f-2ba9692f9beb');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
select 'e2959ff6-ac6b-572f-9502-8ea8b5dd8b9a'::uuid, 'required_option', 'f052b64b-6f6f-5d63-895f-2ba9692f9beb'::uuid, v.* from (values
 ('TOEFL_IBT', 69, 'Internet-based TOEFL. The page also accepts TOEFL Essentials 7 and TOEFL ITP Plus for China 460.'),
 ('TOEFL_IBT_2026', 3.5, 'Listed as ''69 or 3.5 (effective 1/21/2026)''; the page does not name the 1-6 scale.'),
