insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('e23f16a9-8a9a-5efc-82f6-1c1e61dad791', '2026-27', 'required', 'TSU says it is not test-optional and does not accept superscores. Freshmen are guaranteed admission with a 3.2+ weighted high school GPA, or a 2.5+ weighted GPA with ACT 19 or SAT 990. The international page says freshman applicants under 21 must submit ACT/SAT scores; students over 21 do not. Applicants who are denied can appeal with a personal statement.', 'a18db827-b932-5393-91e0-cfb31743a921');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('e23f16a9-8a9a-5efc-82f6-1c1e61dad791', '2026-27', array['own']::text[], 25, 'Apply through the Future Tiger Portal ($25). International freshmen send a high school transcript plus a credential evaluation for any school outside the US (WES, The Evaluation Company/SpanTran, ECE, AES or IEE), ACT/SAT scores if under 21, English proficiency proof, a passport copy, notarized financial evidence for the I-20 (dated within 6 months; ask oia@tnstate.edu for the amount) and health/immunization forms. CDS C7 lists essays, recommendations and interview as not considered.', '14eed6aa-2da6-5760-ab86-8ac26ce8780b');
insert into deadlines (id, institution_id, cycle, kind, label, due_date, notes, source_id) values
 ('43dd4204-41ab-55c9-82ac-0d3d5216aa7c', 'e23f16a9-8a9a-5efc-82f6-1c1e61dad791', '2026-27', 'application', 'International applicants living overseas: fall 2027 application deadline', '2027-06-01', 'From the ''Students Currently Overseas'' column (fall: June 1). Students already in the US have different dates (fall: July 1, documents Aug 1). The page gives no year; treated as fall 2027. Spring: Nov 1 overseas.', '14eed6aa-2da6-5760-ab86-8ac26ce8780b'),
 ('ef0de9c2-5a37-51a0-9a62-491e146e62e5', 'e23f16a9-8a9a-5efc-82f6-1c1e61dad791', '2026-27', 'other', 'International applicants living overseas: all supporting documents due (fall 2027)', '2027-07-01', 'Transcripts, test scores, application fee and other documents must be received by July 1 to be considered (overseas column).', '14eed6aa-2da6-5760-ab86-8ac26ce8780b');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('e23f16a9-8a9a-5efc-82f6-1c1e61dad791', 'required_nonnative', 'Applicants whose native language is not English must meet one option: TOEFL iBT, IELTS, Duolingo, PTE, 12 hours of US college credit with a 2.0 cumulative GPA, or completion of TSU''s Intensive English Program Level 7. Older TSU Office of International Affairs material says test scores are valid for two years. Cambridge exams are not listed.', '14eed6aa-2da6-5760-ab86-8ac26ce8780b');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
select 'e23f16a9-8a9a-5efc-82f6-1c1e61dad791'::uuid, 'required_option', '14eed6aa-2da6-5760-ab86-8ac26ce8780b'::uuid, v.* from (values
 ('TOEFL_IBT', 61, 'The page does not give a score for the new 1-6 TOEFL scale and does not print a TOEFL institution code.'),
 ('IELTS', 5.0, 'Minimum overall score.'),
 ('DUOLINGO', 75, null),
 ('PTE', 50, 'Pearson PTE Academic.')) v;
insert into score_codes (institution_id, test_key, code, notes, source_id)
select 'e23f16a9-8a9a-5efc-82f6-1c1e61dad791'::uuid, v.* from (values
 ('sat', '1803', null, 'a18db827-b932-5393-91e0-cfb31743a921'::uuid),
 ('act', '4010', null, 'a18db827-b932-5393-91e0-cfb31743a921'::uuid),
 ('toefl', null, 'TSU''s admissions pages do not print a TOEFL institution code; pick Tennessee State University (Nashville) in the ETS list.', '14eed6aa-2da6-5760-ab86-8ac26ce8780b'::uuid),
 ('ielts', null, 'No institution code is listed.', '14eed6aa-2da6-5760-ab86-8ac26ce8780b'::uuid),
 ('duolingo', null, 'No institution code is listed.', '14eed6aa-2da6-5760-ab86-8ac26ce8780b'::uuid),
 ('pte', null, 'No institution code is listed.', '14eed6aa-2da6-5760-ab86-8ac26ce8780b'::uuid)) v;
insert into cost_aid (institution_id, year, tuition_usd, tuition_out_of_state_usd, room_board_usd, books_usd, other_usd, intl_need_aid, intl_avg_award_usd, meets_full_need, merit_scholarships, merit_separate_app, notes, source_id) values
 ('e23f16a9-8a9a-5efc-82f6-1c1e61dad791', '2024-2025', 8616, 22416, 11150, 1600, 5811, true, 19162, false, true, false, 'College Navigator estimates for full-time beginning undergraduates, 2024-25 (the latest published there): tuition AND fees in-state $8,616, out-of-state $22,416; on-campus food and housing $11,150; books $1,600; other expenses $5,811. The TSU 2025-26 CDS left section G blank (final costs due 7/1/2026) and its 2026-27 tuition schedule is a scanned image, so newer figures could not be read; TSU says to expect 2-5% increases. No separate international tuition rate is stated on the pages reviewed, so out-of-state is the likely rate. CDS H6 (nonresident undergraduates): institutional need-based aid is available; 84 received it, average $19,162, total $1,609,573.; Institutional merit scholarships are open to first-time freshmen and international students and are considered automatically once the admission application, official transcript and ACT/SAT scores are in (some awards need a separate application). Amounts per year for out-of-state/international students: Renaissance $8,500 (weighted GPA 3.75+ or ACT 28/SAT 1300+), 1912 Heritage $6,500 (GPA 3.25-3.74 or ACT 25-27/SAT 1200-1290), Torch Scholars $4,500 (GPA 3.0-3.24 or ACT 20-24/SAT 1030-1190). Renewal needs a 3.0 GPA, 15 credits a semester and, as printed, a FAFSA each year, which international students cannot file, so ask TSU how renewal works for them. Only one merit scholarship can be held. The full-ride awards (Presidential, Watkins) are for U.S. citizens. CDS H6 ticks institutional need-based aid for nonresident undergraduates (84 recipients, average $19,162), but the TSU international pages describe only merit awards. Amounts and criteria are for Fall 2026 entry; Fall 2027 terms are not yet posted.', '67de7d20-b578-5546-bf88-6ce3930be9e2');
