insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('6ad9d7bf-8578-5d42-8af0-cba533001c3a', '2026-27', 'required', 'The international undergraduate page lists official SAT or ACT results for freshmen: SAT 900 (Critical Reading and Math combined) or ACT 17 composite. The domestic freshman page says ''if required, see notice below'' but the notice is not on the page, so test-optional status could not be confirmed.', '402df2e1-023e-5709-8030-c4d79a878757');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('6ad9d7bf-8578-5d42-8af0-cba533001c3a', '2026-27', array['own']::text[], 78, 'Apply through ApplyTexas (goapplytexas.org). The fee is $78 for international applicants ($42 for domestic freshmen). Freshman page: minimum 2.50 unweighted GPA, ACT 17 or SAT 900, official transcript, placement testing after admission. International applicants also send complete official records (with certified English translations and a course-by-course evaluation for foreign transcripts) and an affidavit of financial support showing $48,568 or more.', '402df2e1-023e-5709-8030-c4d79a878757');
insert into deadlines (id, institution_id, cycle, kind, label, due_date, notes, source_id) values
 ('b60b7ad0-9bd7-580b-ade8-c6818f7b3d23', '6ad9d7bf-8578-5d42-8af0-cba533001c3a', '2026-27', 'application', 'Fall application deadline - international new students', '2027-07-15', 'The page prints ''Fall - July 15'' with no year; taken as fall 2027. Spring is Oct 31. Students already in the U.S. who are transferring have earlier dates (Fall June 15).', '402df2e1-023e-5709-8030-c4d79a878757');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('6ad9d7bf-8578-5d42-8af0-cba533001c3a', 'required_nonnative', 'Exempt if the applicant graduated from a U.S. accredited high school, English is the native language, or the applicant holds a degree from or is transferring from a U.S. accredited college; the page also lists exempt countries. No conditional admission or ESL pathway program is described on the page.', '402df2e1-023e-5709-8030-c4d79a878757');
