insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, intl_applicants, intl_admits, in_state_applicants, in_state_admits, out_state_applicants, out_state_admits, pct_submit_sat, pct_submit_act, notes, source_id) values
 ('4ac1c505-1fa6-56a9-ae96-e740f8bf178e', '2025-2026', 44436, 40515, 9369, 2117, 2037, 36941, 34047, 5351, 4404, 40.0, 6.0, 'CDS C1 (fall 2025 first-years). Residency split from the C1 table (in-state 36,941 / out-of-state 5,351 / international 2,117 / unknown 27 applicants); international admit rate is 96.2% (2,037 of 2,117), 442 enrolled. The CDS does not report high school GPA (C11/C12 blank), so GPA fields are omitted; 12% of enrollees were in the top tenth and 42% in the top quarter of their class (C10). Undergraduate enrollment 39,353 is CDS B1 total undergraduates; international 1,205 is degree-seeking nonresidents (B2). Student-faculty ratio 21:1 is from IPEDS College Navigator. Waitlist: none.', 'edbf3249-bf69-5114-b9fe-d0282c38583b');
