insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('4ac1c505-1fa6-56a9-ae96-e740f8bf178e', '2026-27', 'optional', 'SAT/ACT are not required for applicants ranked in the top 75% of their class (admission, Honors College, merit scholarships); scores are considered if submitted. Applicants in the bottom quarter must submit scores that meet assured-admission standards (4th quartile: ACT 29 / SAT 1330). Assured admission also lists ACT 22 / SAT 1090 for the 2nd quartile and ACT 26 / SAT 1250 for the 3rd quartile. Applicants from non-ranking schools are assigned a rank by Texas State. International applicants: scores are listed as optional.', '80e04951-2ec8-5ef6-8cfe-c4837df02d2e');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('4ac1c505-1fa6-56a9-ae96-e740f8bf178e', '2026-27', array['common_app','own']::text[], 90, 'Apply on the TXST Application, Common App or ApplyTexas (''own'' = TXST App/ApplyTexas); submit only one. Fee is $90 for international applicants (no waivers) and $75 domestic. The essay is optional on the freshman checklist; the admission review also considers curriculum, rigor and grades. International applicants send secondary transcripts and exam results with certified English translations if needed. McCoy College of Business BBA majors are limited access (freshmen not meeting assured admission may enter as Pre-Business).', 'c641539d-923f-5d24-8533-a25de9daf890');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('fd846d37-657f-55f3-a727-c4ed717e55ed', '4ac1c505-1fa6-56a9-ae96-e740f8bf178e', '2026-27', 'priority', 'ROLLING', 'International fall freshman priority date (fall 2027 entry)', '2026-12-01', 'Apply by the priority date to also meet the scholarship deadline. The page does not print a year; fall 2027 entry is assumed.', 'f4c02f9f-6232-5e83-b0b1-6f6f2fada44d'),
 ('a5560033-167e-5783-9018-53477986128b', '4ac1c505-1fa6-56a9-ae96-e740f8bf178e', '2026-27', 'application', 'ROLLING', 'International fall freshman final deadline', '2027-06-01', 'International Application Deadlines section of the Apply page: ''December 1 (Priority) / June 1 (Final)''. The domestic freshman section of the same page lists July 15 as final. Applicants who need a visa should finish at least a month early.', 'f4c02f9f-6232-5e83-b0b1-6f6f2fada44d'),
 ('f33b2696-fa61-5d21-9ae3-9b60fc62ee9a', '4ac1c505-1fa6-56a9-ae96-e740f8bf178e', '2026-27', 'scholarship', null, 'Good Neighbor Scholarship application (BOSS) for the following academic year', '2027-03-01', 'Open to students from nations of the Western Hemisphere other than Cuba and the U.S.; awards the resident/nonresident tuition difference. Date taken from the international scholarships page.', 'fa0b5262-24f8-5708-9923-d473824e369b');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('4ac1c505-1fa6-56a9-ae96-e740f8bf178e', 'required_nonnative', 'Exempt: diploma or bachelor''s degree from a listed English-speaking country (e.g. UK, Ireland, Canada except Quebec, Australia, New Zealand, Singapore, Nigeria, Kenya, Philippines and others listed); a U.S. high school diploma with 3 full years of non-ESL English; or 30+ transferable credits incl. College Writing I and II with C or higher. Other proofs: SAT EBRW 520, ACT English 21, IB English 4, GCE/IGCSE English C, WASSCE B3. Scores must be under 2 years old and not single-skill; teacher-certification programs require TOEFL iBT regardless of country.', 'c641539d-923f-5d24-8533-a25de9daf890');
insert into english_requirements (institution_id, source_id, test_key, status, min_total, min_subscores, notes)
select '4ac1c505-1fa6-56a9-ae96-e740f8bf178e'::uuid, 'c641539d-923f-5d24-8533-a25de9daf890'::uuid, v.* from (values
 ('TOEFL_IBT', 'required_option', 78, '{"each_section": 19, "writing": 18}'::jsonb, 'Each section 19 except Writing 18.'),
 ('TOEFL_IBT_2026', 'required_option', 4, '{"each_section": 4}'::jsonb, 'Updated 6-point scale: total 4, each section 4.'),
 ('IELTS', 'required_option', 6.5, '{"each_section": 6.0}'::jsonb, null),
 ('DUOLINGO', 'required_option', 105, null, 'Some online-program pages list 110.'),
 ('PTE', 'required_option', 52, null, 'PTE Academic overall.'),
 ('CAMBRIDGE', 'accepted', 176, null, 'B2 First, C1 Advanced or C2 Proficiency. Also accepted: TOEFL Essentials 8.5 and iTEP 3.8. No ESL or conditional-admission pathway was found on the international admissions page.')) v;
