insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, intl_applicants, intl_admits, pct_submit_sat, pct_submit_act, gpa_avg, pct_reporting_gpa, gpa_distribution, notes, source_id) values
 ('56be2e20-f239-56b0-9e15-076d0859a62d', '2023-2024', 4785, 3817, 504, 570, 206, 21.0, 52.0, 3.2, 97.0, '{"4.0": 10.2, "3.75-3.99": 16.19, "3.50-3.74": 17.29, "3.25-3.49": 13.53, "3.00-3.24": 14.63, "2.50-2.99": 18.0, "2.0-2.49": 7.54, "1.0-1.99": 1.11}'::jsonb, 'CDS C1 (fall 2023): applicants, admits and enrollees are the sums of the men/women/another-gender rows (4,785 / 3,817 / 504). The residency table shows 4,724 / 3,783 / 504 in total, with International 570 applied, 206 admitted, 17 enrolled (about 36% of international applicants admitted versus about 80% overall), In-state 2,197 / 1,911 / 322 and Out-of-state 1,957 / 1,666 / 165; the residency totals are slightly below the C1 totals, so in-state and out-of-state counts are left null. SAT submitted by 21% (108) and ACT by 52% (262) of enrolled first-years (C9). C11 All-enrolled GPA ranges; 1.5% of students were below 1.0. College Navigator for fall 2024 shows 5,949 applicants and about 80% admitted. Undergraduate enrollment 2,666 and nonresident count 115 are the B1 Total Undergraduates column (fall 2023); the C7 factor checkboxes could not be read from the PDF, so factors are omitted.', 'c4ef7228-0561-5145-bfbd-5ee29f9ea185');
insert into test_score_percentiles (institution_id, cds_year, source_id, test, p25, p50, p75)
select '56be2e20-f239-56b0-9e15-076d0859a62d'::uuid, '2023-2024', 'c4ef7228-0561-5145-bfbd-5ee29f9ea185'::uuid, v.* from (values
 ('SAT_TOTAL', 900, 1010, 1110),
 ('SAT_ERW', 440, 510, 560),
 ('SAT_MATH', 420, 500, 560),
 ('ACT_COMPOSITE', 15, 18, 22),
 ('ACT_ENGLISH', 14, 17, 21),
 ('ACT_MATH', 15, 17, 22)) v;
insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('56be2e20-f239-56b0-9e15-076d0859a62d', '2026-27', 'optional', 'SAT/ACT scores are not required for traditional acceptance; they are used for placement and may be requested for special consideration (for example if the GPA is below 2.0). Minimum cumulative high school GPA 2.0. International applicants may use ACT English 18 or SAT 880 as proof of English instead of a language test.', '6a3b86b8-4906-5c60-9272-19cee42736be');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('56be2e20-f239-56b0-9e15-076d0859a62d', '2026-27', array['own']::text[], 75, '$75 non-refundable fee, paid in the application portal. International freshmen need a high school transcript (2.0 GPA, English translation if needed), English proof, a bank or government statement showing funds for one academic year, and a passport copy; a visa copy if held. Unofficial copies are accepted for review and official originals are due by the first day of orientation. Essays and recommendations are not required (a writing sample, letters or an interview may be requested). Admission decisions are made immediately after review.', '633210f3-1908-50e7-851b-ab2b442b3cd3');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('67ddb06e-5262-5933-afaa-b26650b1260e', '56be2e20-f239-56b0-9e15-076d0859a62d', '2026-27', 'application', 'ROLLING', 'International application deadline, fall (August) intake (fall 2027 entry)', '2027-07-15', 'The international admissions page says the application deadline for the August (Fall) intake is July 15th and November 15th for the January (Spring) intake; no year is printed, so the date is treated as fall 2027. Domestic admission has no published deadline and decisions are made immediately.', '633210f3-1908-50e7-851b-ab2b442b3cd3');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('56be2e20-f239-56b0-9e15-076d0859a62d', 'required_nonnative', 'Applicants whose instruction was in English may be waived with a letter from the principal or registrar; applicants educated mainly in listed English-speaking countries (e.g. Canada excluding Quebec, Australia, Singapore, UK) are exempt. Admissions may still request proof from any applicant. Conditional admission and ESL pathways are not mentioned on the pages read.', '633210f3-1908-50e7-851b-ab2b442b3cd3');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
select '56be2e20-f239-56b0-9e15-076d0859a62d'::uuid, 'required_option', '633210f3-1908-50e7-851b-ab2b442b3cd3'::uuid, v.* from (values
 ('TOEFL_IBT', 61, 'The admissions table lists TOEFL 61 without naming iBT (TOEFL Home accepted). CONFLICT: the 2026-27 Academic Bulletin states TOEFL 72 iBT, IELTS 5, Duolingo 105, PTE 51 for international undergraduates; confirm with ia@tiffin.edu before relying on the lower figure.'),
 ('IELTS', 5.0, 'Admissions page; the bulletin also says 5.'),
 ('DUOLINGO', 85, 'Admissions table says 85; the page text also mentions 120, and the bulletin says 105.'),
 ('PTE', 42, 'Admissions page; the bulletin says 51.')) v;
insert into cost_aid (institution_id, year, tuition_usd, tuition_out_of_state_usd, tuition_intl_usd, required_fees_usd, room_board_usd, intl_aid_policy, intl_need_aid, intl_merit_aid, intl_need_aid_awarded, intl_avg_award_usd, merit_scholarships, notes, source_id) values
 ('56be2e20-f239-56b0-9e15-076d0859a62d', '2026-2027', 35700, 35700, 35700, 1000, 13388, 'merit_only', false, true, 74, 25437, true, 'Undergraduate on campus 2026-27: tuition $1,190 per credit hour, $35,700 per year; technology fee $225 and campus services fee $275 per semester ($1,000 per year). Housing and food in the cost estimate: $13,388. The page states tuition and fees are the same for international and domestic students. Books and a total are not published on the page. CDS H6 (fall 2023): 74 undergraduate nonresidents received institutional aid, average $25,437 (the CDS does not say need or non-need).; International first-year merit scholarships are decided during academic review (GPA tiers). For fall 2027 entry (the 2027-2028 column): Trustee $19,000 (3.8+), President $18,000 (3.5-3.79), Dean Grant $16,000 (3.0-3.49), 1888 Grant $14,000 (2.5-2.99), Green & Gold Grant $12,000 (2.49 and below); the 2026-27 column is $18,000 to $11,000. International students who qualify are also considered for a supplementary $1,000/year grant. Amounts are not increased after the first year; full-time enrollment is required. Whether the award is automatic is not stated.', '929a1a12-66cb-59c5-a77d-845a2a7fc91b');
