select '56be2e20-f239-56b0-9e15-076d0859a62d'::uuid, 'direct_major', false, v.* from (values
 ('156d8a11-4740-5ea2-97eb-e2c675748399'::uuid, 'Business (BBA: Accounting, Finance, Marketing, Management and others)', 'business', 'No separate admission criteria are published beyond general admission.'),
 ('d563709f-41cb-5ee8-94d1-eb32fcad7159'::uuid, 'Computer Science (BS: software development, network and systems administration, video game design and others) and Cybersecurity (BS)', 'computer_science', 'No separate admission criteria are published beyond general admission.'),
 ('dd471ecc-be50-54f6-a0f5-f429465f569a'::uuid, 'Biology (BS, Pre-Professional Pathway, on campus)', 'biology_life_sci', 'No separate admission criteria are published beyond general admission. There is no stand-alone nursing major (pre-licensure nursing is a dual-degree pathway with a partner college).')) v;

