insert into cost_aid (institution_id, year, tuition_usd, tuition_out_of_state_usd, tuition_intl_usd, required_fees_usd, room_board_usd, books_usd, intl_aid_policy, intl_need_aid, intl_need_aid_awarded, intl_avg_award_usd, meets_full_need, merit_scholarships, merit_separate_app, notes, source_id) values
 ('7a1beb6d-516a-550b-beb8-6abf954e03ba', '2026-2027', 11238, 20598, 20598, 1662, 16861, 1290, 'merit_only', false, 444, 5451, false, true, false, 'CDS G1 first-year 2026-27 (tuition has a guaranteed rate for four years). UToledo''s international page lists $12,900 tuition and general fees + $9,360 out-of-state surcharge + about $1,900 program fees (plus $600 for Engineering), $14,850 on-campus room and meals and $2,600 medical insurance. CDS H6: 444 nonresidents received institutional aid, average $5,451.; International Rocket Award: $8,000 per academic year for a 3.0+ GPA, awarded automatically on admission, applied to the out-of-state surcharge only (not in-state tuition, fees, housing or insurance). Students from Toledo''s Sister Cities pay Ohio-resident tuition instead and do not get the award. UToledo says more than 85% of its international undergraduates receive scholarships or special tuition rates; international students cannot get awards that require a FAFSA.', '9a112c26-0519-5772-88da-2d65e00c3097');
