insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('ad96250b-5f00-5d5b-b637-19b8c6ef56f3', '2026-27', 'optional', 'TU does not require the SAT or ACT for admission or scholarships; submitted scores are considered but do not hurt an application. SAT EBRW 540 or ACT English 21 can also be used to meet the English proficiency requirement.', '21648af9-b7ff-5cc4-b5a2-d766b3155c4c');
insert into application_requirements (institution_id, cycle, platforms, supplemental_essays, app_fee_usd, notes, source_id) values
 ('ad96250b-5f00-5d5b-b637-19b8c6ef56f3', '2026-27', array['common_app']::text[], 'Common App activities list and college essay are required (holistic review).', 50, 'Official high school transcript required (sent by the school, ideally through Common App); a non-English transcript needs an official translation by the school; college work outside the U.S. needs a NACES course-by-course evaluation. Fee waivers exist. Holistic review weighs courses, grades and rigor most; CDS C7 lists recommendations as not considered. A non-refundable $200 enrollment deposit is due after admission, before an I-20 is issued.', '21648af9-b7ff-5cc4-b5a2-d766b3155c4c');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('443ee47d-5c7f-58e5-acc7-1e5b11bb3d12', 'ad96250b-5f00-5d5b-b637-19b8c6ef56f3', '2026-27', 'application', 'EA', 'Early Action, Honors College and automatic merit scholarship deadline (fall 2027)', '2026-11-01', 'Applications complete after Nov 1 may not be considered for merit scholarships. EA decisions come by mid-January; merit awards by the end of February.', '21648af9-b7ff-5cc4-b5a2-d766b3155c4c'),
 ('b3cac963-6092-57c3-91b6-479e440fab51', 'ad96250b-5f00-5d5b-b637-19b8c6ef56f3', '2026-27', 'application', 'RD', 'Regular decision deadline (fall 2027)', '2027-02-01', 'Decisions by early March. The catalog also lists Feb 1 as the regular application deadline for international freshmen.', '21648af9-b7ff-5cc4-b5a2-d766b3155c4c'),
 ('71aa9980-fada-5fe0-8683-fce32b75f43a', 'ad96250b-5f00-5d5b-b637-19b8c6ef56f3', '2026-27', 'scholarship', null, 'International scholarship deadline (fall 2027)', '2027-02-01', 'No separate application for the International Student Scholarship; the You Are Welcome Here scholarship needs its own YAWH application, also due Feb 1. Fall awards are announced in March.', 'edfa72de-c2de-5705-bfe4-dc0d2c33e702'),
 ('f6f3b399-fffb-542f-b8a4-6335b1b7a2b4', 'ad96250b-5f00-5d5b-b637-19b8c6ef56f3', '2026-27', 'application', null, 'International freshman final deadline (fall 2027)', '2027-06-01', 'Late application deadline for international students only (listed as the International Freshman Deadline); scholarship consideration is tied to the earlier dates. Spring 2027 freshman deadline is Nov 1, 2026.', '21648af9-b7ff-5cc4-b5a2-d766b3155c4c');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('ad96250b-5f00-5d5b-b637-19b8c6ef56f3', 'required_nonnative', 'Anyone who attended school outside the U.S. must show English proficiency. Undergraduates may be exempt after at least 3 years of education in a listed English-speaking country (e.g. Australia, Canada except Quebec, Ireland, Ghana). Other ways to meet it: SAT EBRW 540, ACT English 21, IB English SL 5, GCSE/IGCSE English C, a C in U.S. college composition, or TU English Language Center level 5 completion. Applicants below the minimum can use the TU Academic Pathway (conditional pathway through the English Language Center).', '80bced9f-ee22-5f29-9622-e36d3aa9dbba');
