insert into major_admissions (institution_id, id, program, category_key, admit_model, capped, notes)
select 'ad96250b-5f00-5d5b-b637-19b8c6ef56f3'::uuid, v.* from (values
 ('f500bc43-c604-5a50-9052-f4fd99629607'::uuid, 'Nursing, basic/pre-licensure BS', 'nursing', 'pre_major_competitive', true, 'Screened, competitive major with its own application; students who list nursing are classified pre-nursing. Minimum criteria include a 3.0 GPA, prerequisite courses with C or better and a TEAS score of Proficient or higher; admission to TU does not guarantee admission to nursing.'),
 ('cf52ad34-16fb-50b0-97e9-1e7fc83fcfa3'::uuid, 'Business Administration (College of Business and Economics)', 'business', 'pre_major_competitive', false, 'Students enter as pre-Business Administration (PBUA) and are admitted to a business major, concentration or track after completing the required courses with at least a C; overall GPA of 2.00 or higher.'),
 ('0dc3f74a-9fa5-5f20-83b7-79c6733b7499'::uuid, 'Computer Science BS', 'computer_science', 'undeclared_open', false, 'Department of Computer & Information Sciences; tracks in AI, Cyber Operations and Software Engineering; the B.S. is ABET-accredited. The catalog page describes no separate admission screen.')) v;

