insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('23f57a4f-b4c7-50ab-8ad5-429bc04463a7', '2026-27', 'optional', 'Test-optional for Summer/Fall 2027 entry only for applicants with a 3.5+ weighted high school GPA (international students who graduate in 2027 are included). With a self-reported GPA of 3.49 or below, SAT/ACT scores are required for review; applicants who send scores are recommended to have at least ACT 20 or SAT 1030. The test-optional or with-scores choice is final once the application is submitted. UAB will not offer test-optional admission for Fall 2028 and later. Early medical, dental and optometry acceptance programs and the Honors College need scores.', 'c53ce37b-b139-580d-ae5f-38fd3cd4d9ac');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('23f57a4f-b4c7-50ab-8ad5-429bc04463a7', '2026-27', array['common_app','own']::text[], 40, 'Apply with the UAB application or the Common App ($40 nonrefundable). International applicants also send official proof of English proficiency (unless English is their first language) and official transcripts in English. UAB says applicants who live and attend high school outside the US apply through INTO UAB; INTO''s own fee and deadlines are not published on the UAB page. International freshmen need at least a 2.75 GPA on the US 4.0 scale (UAB evaluation), must declare a major, and need a bank statement or affidavit of support for the I-20.', '941d96f5-a5e6-5ee7-9812-aea2afe9c3ae');
insert into deadlines (id, institution_id, cycle, kind, label, due_date, notes, source_id) values
 ('f5918bb0-4346-56ce-abe6-3dc51c73d26b', '23f57a4f-b4c7-50ab-8ad5-429bc04463a7', '2026-27', 'priority', 'Fall 2027 priority admission deadline (international freshman)', '2027-06-01', 'UAB''s international freshman page and catalog list June 1 for fall without a year; treated as fall 2027. Later applications are considered as space allows. UAB advises international students to apply at least six months before the start date. Applicants outside the US apply through INTO UAB, whose fall 2027 date is not published.', '941d96f5-a5e6-5ee7-9812-aea2afe9c3ae'),
 ('8a7d1be5-37bb-5b18-b495-e348d086d0f9', '23f57a4f-b4c7-50ab-8ad5-429bc04463a7', '2026-27', 'scholarship', 'Accepted by this date to be considered for the UAB International Scholarship (August intake)', '2027-05-01', 'The page gives no year; treated as 2027. Students must already be accepted by May 1 (Nov 1 for the January intake), so the application should be complete well before then.', 'edc313fb-6d86-56ee-8356-e5882bacf6bd');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('23f57a4f-b4c7-50ab-8ad5-429bc04463a7', 'required_nonnative', 'No score needed if English is the first language, after 2+ years at a US high school, or with 24+ transferable semester hours from a US college. Scores must be from the last 2 years. TOEFL MyBest and IELTS OneSkill retakes are accepted. For writing placement (EH 101): TOEFL writing 23 or IELTS writing 6.0; below that a student is placed in the INTO UAB writing course.', '941d96f5-a5e6-5ee7-9812-aea2afe9c3ae');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, min_subscores, notes)
select '23f57a4f-b4c7-50ab-8ad5-429bc04463a7'::uuid, 'required_option', '941d96f5-a5e6-5ee7-9812-aea2afe9c3ae'::uuid, v.* from (values
 ('TOEFL_IBT', 77, null, 'Institution code 1856. TOEFL Essentials 8.5 also accepted. The page does not give a score for the new 1-6 TOEFL scale.'),
 ('IELTS', 6.0, '{"each_section": 5.5}'::jsonb, '6.0 overall with at least 5.5 on each section. IELTS is checked with the TRF code; no official report needed.'),
 ('DUOLINGO', 120, null, 'The page also lists IELA 176 and Gaokao 120 as accepted.')) v;
