insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, pct_submit_sat, pct_submit_act, notes, source_id, source_note) values
 ('633234d7-6014-58f7-8ef7-e9fd2cb5ec12', '2023-2024', 2677, 2181, 886, 0, 81, 'Baseline from IPEDS (fall 2023 entering class, exact counts). No Common Data Set was found (UAFS lists none on its institutional research pages), so SAT total, GPA, residency and international splits are not available. College Navigator fall 2024: 2,769 applicants, 80% admitted, 40% of admitted enrolled (admit count not published as a number). Undergraduate enrollment 5,459 and student-faculty ratio 18:1 are fall 2024 / 2024 figures. No SAT scores were reported to IPEDS for fall 2023 (0 SAT submitters).', 'cc133604-c41e-5ed5-80b1-24edc4a847e7', 'admissions_site');
