insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('633234d7-6014-58f7-8ef7-e9fd2cb5ec12', '2026-27', 'optional', 'No minimum SAT/ACT is required. Full admission is available with a 3.00 high school GPA (no test minimum), or top 50% of class, or ACT 19 (13 Math, 15 Reading, 15 English) / SAT 1010 (440 EBRW, 330 Math), or an Accuplacer math cutoff. Official placement scores (ACT, SAT, CLT or Accuplacer) are still required for course registration and scholarships; international students without ACT/SAT take the ACCUPLACER Next-Generation test.', '517b7762-07cc-5b55-a27c-3c1f60ac7dd5');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('633234d7-6014-58f7-8ef7-e9fd2cb5ec12', '2026-27', array['own']::text[], 0, 'Apply page says ''Applying is easy and FREE!''; the international page does not list a fee. International applicants need a bank statement showing $27,546 (another UAFS page shows $26,108, so confirm), a NACES course-by-course evaluation of non-U.S. post-secondary transcripts, and a passport copy. Applications use UAFS''s own online portal (not the Common App).', 'e0b6c864-6889-5cde-a570-c627f734a061');
insert into deadlines (id, institution_id, cycle, kind, label, due_date, notes, source_id) values
 ('b9b34113-e85b-53cb-8755-aab5539108c8', '633234d7-6014-58f7-8ef7-e9fd2cb5ec12', '2026-27', 'application', 'International application deadline, fall 2027 entry', '2027-06-01', 'Page: ''Students outside the U.S.: June 1, 2027'' for fall 2027 (applications open Aug. 1, 2026). The domestic fall 2027 deadline is not yet posted.', '81fe1a14-7876-58b4-bb62-1ab6d69ede58'),
 ('632a9b9c-a450-519b-af7d-1c9507c7cfa8', '633234d7-6014-58f7-8ef7-e9fd2cb5ec12', '2026-27', 'scholarship', 'Prestigious scholarships priority deadline (fall 2027 entry)', '2026-11-15', 'Final deadline Jan. 15, 2027.', 'd4fecd60-5964-5791-90b4-376ad88ed800'),
 ('91d0e05a-d4fc-536a-a186-d2c385a12a89', '633234d7-6014-58f7-8ef7-e9fd2cb5ec12', '2026-27', 'scholarship', 'Freshman merit scholarships deadline (fall 2027 cycle)', '2027-05-01', null, 'd4fecd60-5964-5791-90b4-376ad88ed800');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('633234d7-6014-58f7-8ef7-e9fd2cb5ec12', 'required_nonnative', 'The page lists ways to show English proficiency (any one): TOEFL iBT, IELTS, PTE Academic, Cambridge CPE/CAE/FCE, MET B2+, ACT English and Reading 19+, SAT Writing and Critical Reading 470+, or completion of EF Level C1-3 or ELS Level 112. Transfers from a U.S. institution: English I and II with C or better. No list of exempt countries was found. Duolingo is not mentioned. No conditional-admission or ESL pathway program is described on the page.', '81fe1a14-7876-58b4-bb62-1ab6d69ede58');
insert into english_requirements (institution_id, source_id, test_key, status, min_total, notes)
select '633234d7-6014-58f7-8ef7-e9fd2cb5ec12'::uuid, '81fe1a14-7876-58b4-bb62-1ab6d69ede58'::uuid, v.* from (values
 ('TOEFL_IBT_2026', 'required_option', 4, 'Page says ''TOEFL iBT: 4 or above'' without naming the scale; a 4 only makes sense on the new 1-6 scale. The old 0-120 minimum is not published.'),
 ('IELTS', 'required_option', 6.0, '6 or above.'),
 ('PTE', 'required_option', 45, 'PTE Academic 45 or above.'),
 ('CAMBRIDGE', 'accepted', null, 'CPE, CAE or FCE accepted; no minimum score listed.')) v;
insert into cost_aid (institution_id, year, tuition_usd, tuition_out_of_state_usd, room_board_usd, books_usd, other_usd, merit_scholarships, notes, source_id) values
 ('633234d7-6014-58f7-8ef7-e9fd2cb5ec12', '2024-2025', 7334, 12182, 10082, 1416, 5476, true, 'College Navigator 2024-25: tuition and fees $7,334 in-state / $12,182 out-of-state; on-campus food and housing $10,082. Published total cost on campus is $29,156 out-of-state ($24,308 in-state); total left blank because the two differ. International students pay the out-of-state rate (2026-27 per-credit rates are in the aid notes).; 2026-27 per-credit-hour rates: out-of-state and international $400 tuition + $106.50 mandatory fees = $506.50 (in-state $334.50), plus $73 per semester (registration and health) and an international Student Services Fee of $350 per semester. Freshman merit scholarships (ACT or GPA based, up to $1,000-$6,000 plus up to a $1,500 housing stipend) and prestigious scholarships (Myles Friedman Honors up to $34,000 over four years, ACT 27 or 3.5 GPA) exist. The international page says international students may apply for Myles Friedman and freshman merit scholarships but not those requiring Pell eligibility. No need-based aid for international students is described.', 'cc133604-c41e-5ed5-80b1-24edc4a847e7');
insert into institution_tiers (institution_id, tier_code, category_key, rationale)
