insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, pct_submit_sat, pct_submit_act, notes, source_id, source_note) values
 ('072e6cc7-6bf1-5fd9-8d04-0ebe3161b7b2', '2023-2024', 13103, 12653, 1747, 34, 6, 'Baseline from IPEDS via College Navigator (fall 2024 entering class). UCCS''s 2025-26 Common Data Set PDF is an empty template and its 2024-25 CDS keeps labels and values in separate text layers that cannot be matched reliably, so no CDS figures are used. IPEDS gives 97% admitted (rounded), so the admit count is left null; international applicant/admit counts, GPA and class-rank data are not added. Undergraduate enrollment is fall 2024 (9,302). Test-score percentiles apply to enrolled first-time students. Applicant/admit/enrolled counts replaced with exact IPEDS ADM2023 (fall 2023) figures, because the newer source gives only a rounded admit rate.', 'd990468d-9206-5ff9-8665-1c234b6d9a30', 'admissions_site');
insert into test_score_percentiles (institution_id, cds_year, source_id, test, p25, p50, p75)
select '072e6cc7-6bf1-5fd9-8d04-0ebe3161b7b2'::uuid, '2024-2025', '9d4f75bf-dfd3-5b4e-90ad-dc5ad8b4cd81'::uuid, v.* from (values
 ('SAT_ERW', 510, 580, 620),
 ('SAT_MATH', 500, 550, 600),
 ('ACT_COMPOSITE', 20, 23, 26),
 ('ACT_ENGLISH', 18, 23, 27),
 ('ACT_MATH', 18, 22, 25)) v;
insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('072e6cc7-6bf1-5fd9-8d04-0ebe3161b7b2', '2026-27', 'optional', 'UCCS is test-optional with no minimum GPA or ACT/SAT. Coursework strength and weighted GPA carry the most weight; the page says 75% of admitted students have a 3.0+ weighted GPA and an ACT 20+ or SAT 1070+. Applicants who miss nursing, business or engineering criteria are considered for the College of Letters, Arts, and Sciences until they qualify. Essay and two recommendation letters are reviewed for applicants below those figures.', '5ed67241-f59a-5308-91f0-dd7511572d18');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('072e6cc7-6bf1-5fd9-8d04-0ebe3161b7b2', '2026-27', array['own']::text[], 50, '$50 application fee for out-of-state applicants (waived for in-state; the international page does not give a separate fee). International applicants need official secondary transcripts and exam results with certified English translations, plus English proficiency (a passing score or an exception). Course-by-course evaluation by a NACES/AICE member is required only for college-level coursework taken outside the U.S.', '5ed67241-f59a-5308-91f0-dd7511572d18');
insert into deadlines (id, institution_id, cycle, kind, label, due_date, notes, source_id) values
 ('041f9e81-9c74-56b2-82db-dcf7bce7e681', '072e6cc7-6bf1-5fd9-8d04-0ebe3161b7b2', '2026-27', 'scholarship', 'Most UCCS scholarships (admitted students; fall 2027 entry)', '2027-03-01', 'The scholarship application sits in the MyUCCS portal and most scholarships close March 1 (year not printed; fall 2027 assumed). The international and first-year pages list no application deadline for fall entry, so none is recorded.', '721f9ca5-f1cd-5444-8571-111bbebdc76c');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('072e6cc7-6bf1-5fd9-8d04-0ebe3161b7b2', 'required_nonnative', 'Exceptions: completion of a UCCS-approved English language program with the approved scores (e.g. CU Boulder International English Center, HOFT or ELS Language Center); one year at a U.S. college including English Composition I with C or higher; citizens of listed English-speaking countries who finished all schooling in English (school letter); AP English Language or Literature 4; IB HL English A 4; A/AS-level English C; WAEC/WASSCE B3; Cambridge CPE C or CAE B. SAT ERWS 400 or ACT English 14 also satisfy the requirement. Official scores must be sent to UCCS on admission.', '678d4e8f-e3b7-564b-9366-88b43ae63566');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
select '072e6cc7-6bf1-5fd9-8d04-0ebe3161b7b2'::uuid, 'required_option', '678d4e8f-e3b7-564b-9366-88b43ae63566'::uuid, v.* from (values
 ('TOEFL_IBT_2026', 4.0, 'The page lists ''TOEFL (IBT) 4''; a 4 can only be the 1-6 scale, and no old 0-120 minimum is printed.'),
 ('IELTS', 6.0, null),
 ('DUOLINGO', 105, null),
 ('PTE', 58, 'PTE Academic.')) v;
