insert into cost_aid (institution_id, year, tuition_usd, tuition_out_of_state_usd, tuition_intl_usd, room_board_usd, books_usd, other_usd, meets_full_need, notes, source_id) values
 ('072e6cc7-6bf1-5fd9-8d04-0ebe3161b7b2', '2024-2025', 10149, 24336, 24336, 12918, 1800, 5488, false, 'College Navigator (IPEDS) estimated expenses for full-time beginning undergraduates, 2024-25: tuition and fees in-state $10,149, out-of-state $24,336; on-campus food and housing $12,918; books $1,800; other $5,488. Current (2026-27) rates were not confirmed; the bursar''s tuition pages and bill estimator carry them.; No international-specific scholarship or amount is published on the pages read. Accepted international students are told to check scholarship eligibility in the MyUCCS portal (most scholarships close March 1); the financial aid office says admitted students can apply Dec. 1 to May 1. Aid policy for nonresident internationals is left unset.', '9d4f75bf-dfd3-5b4e-90ad-dc5ad8b4cd81');
