insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('ba6f6326-df17-5b28-9055-e105ba1840ee', '2026-27', 'blind', 'UC does not consider SAT or ACT scores in admission decisions or scholarships; UCLA does not ask for them in the application.', '0beb74a9-de6f-51dd-97b1-8b328db2d0e8');
insert into application_requirements (institution_id, cycle, platforms, supplemental_essays, teacher_recs, counselor_rec, interview, app_fee_usd, notes, source_id) values
 ('ba6f6326-df17-5b28-9055-e105ba1840ee', '2026-27', array['uc_app']::text[], '4 Personal Insight Questions (choose 4 of 8)', 0, false, 'not_offered', 80, 'Fee is $80 per campus, $95 for international applicants; fee waivers cover up to four campuses but only for U.S. citizens, permanent residents and AB540-eligible applicants. UCLA does not require or accept letters of recommendation and does not offer admission interviews. Some arts, music, nursing and theater/film majors require a supplemental application.', 'aa8ab530-73d8-55f6-8e78-f509db6d9e06');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notification_note, notes, source_id) values
 ('f515c17d-4a25-585b-894f-d1d8e9e9b389', 'ba6f6326-df17-5b28-9055-e105ba1840ee', '2026-27', 'application', 'RD', 'UC application filing period closes', '2026-11-30', 'Admission decisions released March 1-31, 2027 (some campuses earlier)', 'No early plans. Application opens August 1, 2026 for fall 2027. Self-report English test scores in the application; UCLA asks that they be reported by January.', 'ae8c3e0e-3664-526d-b8c1-004c7780fec3'),
 ('bca1d8e7-549e-56ee-b386-95fb4d323a38', 'ba6f6326-df17-5b28-9055-e105ba1840ee', '2026-27', 'deposit', null, 'Statement of Intent to Register (SIR)', '2027-05-01', null, null, 'ae8c3e0e-3664-526d-b8c1-004c7780fec3');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('ba6f6326-df17-5b28-9055-e105ba1840ee', 'required_nonnative', 'Required if all or some secondary school was in a country where English was not the language of instruction and you have had less than 3 years of instruction in English. UCLA may also require its English-as-a-Second-Language Placement Exam after admission.', '32f3d373-c684-5288-bffd-29919fde8992');
