insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, pct_submit_sat, pct_submit_act, notes, source_id, source_note) values
 ('c51a2307-17cd-5eda-bd83-4ca792e13f04', '2023-2024', 7121, 5710, 622, 28, 2, 'Baseline from IPEDS / College Navigator for the Stamford campus (fall 2024): 10,937 applicants, 83% admitted (rounded; the admit count is not shown), 10% of admitted enrolled. UConn''s Common Data Set (see data/colleges/uconn.json) is for the whole university, not Stamford, so no CDS figures are used. SAT/ACT percentiles are for enrolled first-time students; 265 submitted SAT (28%) and only 15 submitted ACT (2%), so the ACT percentiles are very thin. IPEDS lists SAT/ACT as required to be considered, but UConn''s admissions pages say test scores are optional for the foreseeable future. Admissions rules are set by UConn Undergraduate Admissions for all five campuses; only the regional-campus May 1 deadline and campus-specific cost differ. Applicant/admit/enrolled counts replaced with exact IPEDS ADM2023 (fall 2023) figures, because the newer source gives only a rounded admit rate.', 'cce738cc-9006-5a99-9f57-cd580cd33720', 'admissions_site');
insert into test_score_percentiles (institution_id, cds_year, source_id, test, p25, p50, p75)
select 'c51a2307-17cd-5eda-bd83-4ca792e13f04'::uuid, '2024-2025', '97b1df5d-1edf-58fe-9de4-fad3d8cf53de'::uuid, v.* from (values
 ('SAT_ERW', 470, 550, 630),
 ('SAT_MATH', 460, 530, 630),
 ('ACT_COMPOSITE', 25, 29, 32),
 ('ACT_ENGLISH', 24, 27, 32)) v;
insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('c51a2307-17cd-5eda-bd83-4ca792e13f04', '2026-27', 'optional', 'UConn-wide: test-optional for the foreseeable future; official SAT/ACT may be sent and are superscored if the applicant wants them considered. Scores are not needed for merit scholarships or Honors. Middle 50% of fall 2026 admitted students who submitted scores at regional campuses: SAT 970-1250, ACT 19-28 (Storrs: SAT 1320-1460). IPEDS (fall 2024) shows the Stamford form as ''required to be considered'', which conflicts with the current admissions pages.', '679a8d38-1ad8-55f2-aa68-f4853420c0ff');
insert into application_requirements (institution_id, cycle, platforms, supplemental_essays, app_fee_usd, notes, source_id) values
 ('c51a2307-17cd-5eda-bd83-4ca792e13f04', '2026-27', array['common_app','coalition']::text[], 'Personal essay of 250-650 words is required (inside the Common App or Coalition App); no separate supplement.', 80, 'UConn-wide rules. $80 non-refundable fee (check or money order also accepted). Two letters of recommendation are optional but preferred. International applicants send secondary school transcripts (with senior classes, rank if any, latest grades) directly from the school with certified English translations; US-educated applicants may complete a STARS record. Four years of secondary school in the U.S. means the domestic requirements apply (4 English, 3 math, 2 social science, 2 foreign language, 2 lab science, 3 electives). Applicants choose a campus; regional-campus students may start at Stamford and move to Storrs after about 54 credits, or finish selected four-year majors at Stamford.', '679a8d38-1ad8-55f2-aa68-f4853420c0ff');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('9401f1ba-e827-5d7e-9057-7382b2039430', 'c51a2307-17cd-5eda-bd83-4ca792e13f04', '2026-27', 'application', 'ED', 'Early Decision (fall 2027), binding', '2026-11-01', 'UConn-wide. Notifications begin mid-December (no exact day printed); a binding offer at the first-choice campus and major needs the enrollment fee by Jan. 15. Early Decision applicants can also be deferred to the March regular release.', 'ac66f3b0-e7ef-53de-9b2d-a352a0a61cb3'),
 ('50ea8366-c619-5fd1-8362-ada6827a5f0f', 'c51a2307-17cd-5eda-bd83-4ca792e13f04', '2026-27', 'scholarship', 'RD', 'Priority deadline for merit and Honors consideration (fall 2027)', '2026-12-01', 'UConn-wide. Global Excellence, Global Distinction and Global Leader Awards are for international applicants, all campuses; also Academic Excellence, Husky Achievement and Leadership awards.', '2e2c337d-bc95-5b58-bf40-e4015d0d9ca3'),
 ('61ed3f5c-fe5f-5983-bc8e-904110da804e', 'c51a2307-17cd-5eda-bd83-4ca792e13f04', '2026-27', 'application', 'RD', 'Regional campus (incl. Stamford) first-year application deadline (fall 2027)', '2027-05-01', 'Regional campuses decide on a rolling basis starting early March (the international page says notifications begin March 1). Storrs applicants have Jan. 15 instead. Late applications are reviewed on a space-available basis; enrollment fee by May 1 or two weeks after a later decision.', '679a8d38-1ad8-55f2-aa68-f4853420c0ff');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('c51a2307-17cd-5eda-bd83-4ca792e13f04', 'required_nonnative', 'UConn-wide. Required for applicants whose primary language is not English, regardless of visa status. Waived for: English as primary language; 2+ years and graduation at a U.S. secondary school (non-ESL); SAT EBRW 510+; ACT 24+ on English, Reading and Composite; IB Higher Level English 5+; one year or more of full-time U.S. college work with GPA 3.0+; a degree from an English-medium institution abroad. Scores must be sent by the test provider; meeting the minimum does not guarantee admission.', '679a8d38-1ad8-55f2-aa68-f4853420c0ff');
