insert into admission_stats (institution_id, source_note, cds_year, applicants, admits, enrolled, pct_submit_sat, pct_submit_act, notes, source_id)
select 'a4c5ce15-0c73-5075-8f25-bdb90d1efb99'::uuid, 'admissions_site', v.* from (values
 ('2023-2024', 2348, 1768, 439, 75, 7, 'Baseline from IPEDS (fall 2023 entering class); no 2024-2025 or 2025-2026 Common Data Set was found on uhcl.edu (the Institutional Research pages list none; only 2000-2016 editions exist in the UHCL repository). Fall 2024 per College Navigator is in the next row. SAT total, GPA, international applicant counts and residency splits are not published and are left empty. Fall 2023 percentiles: SAT EBRW 500/560/590, SAT Math 490/550/580, ACT composite 18/20/23 (College Navigator fall 2024 shows SAT EBRW 490/530/580, Math 480/525/570, ACT 20/22/25).', '5b5c4e17-efc5-59f4-8997-38064a52bad4'::uuid),
 ('2024-2025', 2352, null, null, 69, 6, 'College Navigator, fall 2024: 2,352 applicants, 91% admitted (rounded; the admit count is not published there), 22% of admits enrolled; 325 first-time students submitted SAT (69%) and 27 ACT (6%). Admit count left empty rather than estimated. Undergraduate enrollment 6,139 (fall 2024).', 'cbebd64d-072a-5f6d-91a2-d1eaf31c04d8'::uuid)) v;
