insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('8fb2df3f-14e5-5968-a769-9d6e0158d975', '2026-27', 'optional', 'UHD is test-optional for freshmen, domestic and international: choose on the application to be reviewed with or without SAT/ACT scores (the international page offers an Admissions Application Update Form to request test-optional status). Guaranteed admission for top-quarter class rank; second quarter needs SAT 930 or 2.5 GPA; lower ranks need SAT 930 and 2.5 GPA (ACT 18 equivalent). Applicants without scores still need official scores for TSI placement and scholarships.', 'c4a02764-1470-526f-955c-91fa024cee9b');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('8fb2df3f-14e5-5968-a769-9d6e0158d975', '2026-27', array['own']::text[], 80, 'Apply through UHD''s own ''UHD Direct'' freshman application (connect.uhd.edu); the pages do not mention ApplyTexas or the Common App. International fee is $80 non-refundable (the domestic freshman fee is $50). Required: official transcript evaluation of secondary school scores with mark sheets and graduation date (certified English translation if needed) and either SAT/ACT scores or the test-optional request. International applicants also need an Affidavit of Support and a certified sponsor bank letter showing at least $35,000 issued within the past three months.', '9d20b18e-d061-5654-913b-a8579fc2ae54');
insert into deadlines (id, institution_id, cycle, kind, label, due_date, notes, source_id) values
 ('bd802310-ce57-5fcc-a946-556f3a1b0f82', '8fb2df3f-14e5-5968-a769-9d6e0158d975', '2026-27', 'application', 'International freshman application deadline, fall 2027', '2027-06-01', 'International page: freshman and freshman-transfer deadline June 1, 2027 (spring: Oct. 30, 2026; summer: April 2, 2027). The domestic freshman page lists a later fall priority date of Aug. 6, 2027; use the June 1 international date. CDS C14 also gives a fall closing date of 6/1.', '9d20b18e-d061-5654-913b-a8579fc2ae54');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('8fb2df3f-14e5-5968-a769-9d6e0158d975', 'required_nonnative', 'Exempt: graduates of secondary schools in Australia, the Bahamas, Belize, the British Islands, Ghana, Jamaica, Liberia, New Zealand, Sierra Leone, South Africa, Trinidad, the United States, the Virgin Islands, the West Indies and Zimbabwe. Transfer students are exempt with 12+ U.S. college-level hours including Composition I and II with a C or better. The pages mention no conditional admission and no ESL program.', '9f3db32c-420f-58fa-907a-951871cbced6');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
