insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, intl_applicants, intl_admits, in_state_applicants, in_state_admits, out_state_applicants, out_state_admits, pct_submit_sat, pct_submit_act, gpa_avg, pct_reporting_gpa, gpa_distribution, notes, source_id) values
 ('426b3118-c3d0-5bfd-94d8-255d0a711d1b', '2025-2026', 2768, 2302, 312, 69, 65, 2496, 2061, 203, 176, 29.5, 4.2, 3.4, 99.0, '{"4.0": 3.2, "3.75-3.99": 26.2, "3.50-3.74": 21.4, "3.25-3.49": 15.9, "3.00-3.24": 12.0, "2.50-2.99": 19.4, "2.0-2.49": 1.9, "1.0-1.99": 0.0}'::jsonb, 'CDS C1 (fall 2025 entering class): 69 international first-year applicants, 65 admitted, 12 enrolled. The CDS reports no waitlist; early action closing date is Dec. 1 with rolling notification. Percentiles are as printed in C9 for the 92 SAT and 13 ACT submitters; the workbook''s ACT sub-score rows look mis-aligned, so only the ACT composite is kept. Undergraduate enrollment 2,337 and nonresident undergraduates 77 are from CDS section B (fall 2025).', 'c924059b-58b2-5551-9cf3-5f00fb8ca1c9');
