insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('426b3118-c3d0-5bfd-94d8-255d0a711d1b', '2026-27', 'optional', 'SAT/ACT are optional for first-year applicants; scores on an official high-school transcript are accepted. The international steps page lists college-prep coursework, U.S.-equivalent GPA and a personal statement as the basis for first-year admission.', '99d58514-77c6-5223-92aa-0a94b2eba240');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('426b3118-c3d0-5bfd-94d8-255d0a711d1b', '2026-27', array['common_app','own']::text[], 60, 'Undergraduate application fee is $60. First-year applicants write a personal statement (the Common App essay satisfies it); minimum coursework is 4 English, 3 social studies, 3 math, 3 lab science and 2 foreign language or fine arts, and students lacking some units may be admitted conditionally. Applicants with non-U.S. schooling need a credential evaluation (waived for IB, CIS, U.S. State Dept-assisted and U.S.-accredited schools). Decisions are rolling (biweekly).', '39676848-c222-567a-9a66-5984080621e7');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('cf9d3817-bbde-59ae-a8ad-d58a6dd4e4a5', '426b3118-c3d0-5bfd-94d8-255d0a711d1b', '2026-27', 'application', 'ROLLING', 'International (F-1) application deadline, fall term (fall 2027 entry)', '2027-05-15', 'The page prints ''Fall Term Deadline: May 15th'' and ''Spring Term Deadline: Nov 15th'' without a year; treated as fall 2027. Applications should arrive at least 3 months before the intended start; some programs have earlier deadlines.', '39676848-c222-567a-9a66-5984080621e7'),
 ('a5d197b3-1ebd-5d16-bbcd-c45d8d69f328', '426b3118-c3d0-5bfd-94d8-255d0a711d1b', '2026-27', 'priority', null, 'Priority / early action date (fall 2027 entry)', '2026-12-01', 'From CDS C14 and C22 (Dec. 1, rolling notification), not repeated on the admissions pages; treated as the date for fall 2027 entry.', 'c924059b-58b2-5551-9cf3-5f00fb8ca1c9');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('426b3118-c3d0-5bfd-94d8-255d0a711d1b', 'required_nonnative', 'Citizens of a list of English-speaking countries (for example Australia, Canada except Quebec, Ghana, Kenya, Nigeria, Singapore, South Africa, UK) are waived automatically. Petition-based exemptions include 3+ years of U.S. or DoD high school, or 60 college credits in a listed country. Scores must be under 2 years old. Alternatives to a test: SAT verbal 570, ACT English 24, AP English 4+, IB English A 5+, ELS Level 112, or an English language program at CEFR B2. UIS Global partnership students are handled separately.', 'b6841fcc-6770-5914-a44a-d9fa42037961');
