insert into admission_stats (institution_id, cds_year, applicants, pct_submit_sat, pct_submit_act, notes, source_id, source_note) values
 ('a1139982-6511-5fbf-a792-1cdacc8d9610', '2024-2025', 4224, 14, 86, 'Baseline from IPEDS (fall 2024) as shown on College Navigator: 4,224 applicants, 85% admitted (80% of men, 88% of women), 35% of those admitted enrolled. College Navigator prints rounded percentages, so the admit and enrolled counts are left null. No ULM Common Data Set could be found (not listed on ulm.edu Academic Affairs data resources or in searches), so GPA, residency/international splits and admission factors are not added. Score percentiles are for enrolled first-time students; SAT 14% (165 students) and ACT 86% (1,040), so the SAT ranges rest on a small, self-selected group. Undergraduate enrollment is fall 2024 (6,761); the international undergraduate count is not published in the sources checked.', '9316d2fe-88f6-5008-8150-a0b19241851c', 'admissions_site');
insert into test_score_percentiles (institution_id, cds_year, source_id, test, p25, p50, p75)
select 'a1139982-6511-5fbf-a792-1cdacc8d9610'::uuid, '2024-2025', '9316d2fe-88f6-5008-8150-a0b19241851c'::uuid, v.* from (values
 ('SAT_ERW', 540, 600, 630),
 ('SAT_MATH', 620, 680, 730),
 ('ACT_COMPOSITE', 18, 21, 24),
 ('ACT_ENGLISH', 18, 21, 25),
 ('ACT_MATH', 17, 19, 24)) v;
insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('a1139982-6511-5fbf-a792-1cdacc8d9610', '2026-27', 'required', 'International first-time freshmen must submit the SAT or ACT to be admitted and to qualify for academic aid: SAT EBRW 500+ (ACT 18) and Math 510+ (ACT 19); if one section meets it, the other can be as low as SAT Math 430 (ACT Math 16) or SAT EBRW 440 (ACT English 15). IPEDS lists SAT/ACT as not required but considered (test-optional) for domestic applicants. Scores must be sent officially (SAT code 6482, ACT code 1598).', 'd484fcce-ee85-53a1-b36e-68226443b342');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('a1139982-6511-5fbf-a792-1cdacc8d9610', '2026-27', array['own']::text[], 30, 'International freshmen need a secondary program comparable to US high school graduation with a 2.50 minimum GPA (including English and math courses for scholarship consideration), SAT/ACT scores, an English proficiency score, translated official transcripts and mark sheets, a statement of financial backing with proof of funding, a valid passport and, after admission, immunization records. Documents may be uploaded for provisional admission, but transcripts and SAT scores count as official only when the hard copy arrives. An I-20 is sent 7-10 business days after admission.', 'd484fcce-ee85-53a1-b36e-68226443b342');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('4be9a33d-99c2-5814-970e-825a2b6cd1e7', 'a1139982-6511-5fbf-a792-1cdacc8d9610', '2026-27', 'application', 'ROLLING', 'International application and documents deadline (fall 2027 entry)', '2027-06-01', 'The page prints Fall June 1, Spring November 1 and Summer March 1 without a year; fall is treated as June 1, 2027. All required documents must be in by the date, and the deadlines page already shows the fall 2026 international on-campus window as closed.', 'd484fcce-ee85-53a1-b36e-68226443b342');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('a1139982-6511-5fbf-a792-1cdacc8d9610', 'required_nonnative', 'Testing may be waived with SAT EBRW 640 and a 1200 composite, or if the applicant''s country is on ULM''s English Placement Exempt list (list not reproduced here). Scores must be valid and taken within two years. IELTS 7, TOEFL 100 or Duolingo 120 exempts students from ESL; students admitted below those scores take a placement test on arrival.', 'd484fcce-ee85-53a1-b36e-68226443b342');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
select 'a1139982-6511-5fbf-a792-1cdacc8d9610'::uuid, 'required_option', 'd484fcce-ee85-53a1-b36e-68226443b342'::uuid, v.* from (values
 ('TOEFL_IBT', 79, '100 exempts from ESL. The out-of-state scholarship page lists lower scores (TOEFL 71, IELTS 6.0, Duolingo 95) than these admission minimums; confirm with ULM which applies.'),
 ('IELTS', 6.5, '7.0 exempts from ESL.'),
 ('DUOLINGO', 100, '120 exempts from ESL.')) v;
insert into score_codes (institution_id, source_id, test_key, code, notes)
