insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('5936e534-1437-56ae-a762-ff38e77e1972', '2026-27', 'optional', 'Test-optional: SAT/ACT are not required for admission and are used only to qualify for higher merit scholarships (never to lower an offer or change the decision). Applicants without scores can still get a First-Year Opportunity Scholarship based on GPA. The pages read were captured by the Internet Archive (June 2026 for the first-year page) because umflint.edu blocks automated requests.', 'b4abc2a7-2d5d-5a89-a5e5-d20ab009994f');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('5936e534-1437-56ae-a762-ff38e77e1972', '2026-27', array['common_app','own']::text[], 0, 'The first-year page calls the online application free (it can also be submitted through the Common App); CDS C13 shows a $30 fee with online applications free. International first-year applicants upload attested transcripts, proof of English, a passport copy and an affidavit of financial support (needed for the I-20) through iStart Services; the page says a response comes 2 to 4 weeks after the application and documents. The TOEFL institution code is 1853.', 'c86ebb99-1308-544a-820d-04fb5943d4d7');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('387c6fab-2a24-5a08-b743-10720f5c3107', '5936e534-1437-56ae-a762-ff38e77e1972', '2026-27', 'priority', 'ROLLING', 'International fall priority deadline (fall 2027 entry)', '2027-07-01', 'International pages: fall priority deadline July 1, winter priority Nov. 1; later applicants may not get a decision in time to enroll. The pages print no year; treated as fall 2027. Fall I-20 issue deadline is Aug. 1; priority housing application Feb. 1. The domestic first-year page (June 2026) lists only fall 2026 (Aug. 10) and winter 2027 (Dec. 18) application deadlines; no fall 2027 date was printed.', '2f3a908c-6fd9-56c5-abde-b3d15295322a');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('5936e534-1437-56ae-a762-ff38e77e1972', 'required_nonnative', 'Proof of English is required of all international applicants. Exemptions: four years in a US high school with C/2.0 or better in all English classes (official transcript), or citizenship in / previous education in an English-proficiency-exempt country (decided by International Admissions). Other accepted evidence: SAT Reading 480, ACT English 20, ELS Level 112 completion, iTEP Academic 3.5, MET 53, Michigan Language Center Advanced Star 1, TOEFL Essentials 6.5. No conditional-admission or ESL pathway is described. The English score table comes from the July 2025 Internet Archive copy of the page (the live site blocks automated reads), so confirm scores with admissions.', 'c86ebb99-1308-544a-820d-04fb5943d4d7');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
select '5936e534-1437-56ae-a762-ff38e77e1972'::uuid, 'required_option', 'c86ebb99-1308-544a-820d-04fb5943d4d7'::uuid, v.* from (values
 ('TOEFL_IBT', 61, 'Paper-based 500 also accepted. Institution code 1853. The page does not list the new 1-6 TOEFL scale.'),
 ('IELTS', 6.0, 'IELTS Academic, overall band.'),
 ('DUOLINGO', 100, 'Scores must be sent to UM-Flint directly from Duolingo, not uploaded.'),
 ('PTE', 46, 'Pearson PTE Academic.')) v;
