insert into cost_aid (institution_id, year, tuition_usd, tuition_out_of_state_usd, tuition_intl_usd, required_fees_usd, room_board_usd, books_usd, other_usd, intl_aid_policy, intl_need_aid, intl_need_aid_awarded, intl_avg_award_usd, meets_full_need, merit_scholarships, notes, source_id) values
 ('5936e534-1437-56ae-a762-ff38e77e1972', '2024-2025', 14208, 27744, 27744, 682, 12854, 700, 1310, 'merit_only', false, 30, 5815, false, true, 'CDS G1 (first-year, 2024-2025): in-state tuition $14,208, out-of-state and non-resident $27,744, required fees $682, food and housing $12,854; G5 books $700, other $1,310. CDS H6: only institutional non-need-based aid for nonresidents; 30 nonresidents awarded, average $5,815. The current International Tuition & Fees page (year not printed; captured Aug 2026) lists undergraduate lower-division tuition of $29,002 for 12 credits per semester, with estimated total international expenses of $45,215 (living $11,943, health insurance $2,470, books $800, miscellaneous $1,000); mandatory fees are not included.; International first-year students are automatically considered for First-Year Merit Scholarships (no separate application). The June 2025 scholarship page lists Maize & Blue awards of $1,000 to $10,000 per year for 4 years (renewal 2.75 GPA) based on GPA and optional test scores; a GPA-only First-Year Opportunity Scholarship gives $1,000 per year (2.7-3.7 GPA) or $3,000 per year (3.7+). The Aug 2026 tuition page says awards go up to $5,000 a year, so the current amounts need confirming. The True Blue award is described as full in-state tuition. CDS H6: only non-need-based institutional aid for nonresidents (30 recipients, average $5,815).', '8e4a3940-122f-5e5e-8008-516962f8142c');
