insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('4b498114-f00f-50c8-b50f-e87a704ecf30', '2026-27', 'optional', 'UMass Dartmouth is 100% test optional for SAT/ACT. A score of 1080+ SAT or 22+ ACT (1200 SAT and 25 ACT for nursing) is encouraged because many programs are competitive.', 'c0b1e43d-eb6b-5209-8e63-c3001610672b');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('4b498114-f00f-50c8-b50f-e87a704ecf30', '2026-27', array['common_app','own']::text[], 60, 'Apply with the Common App or the UMass Dartmouth application; $60 fee. International transcripts must be sealed official copies translated into English, with a minimum GPA of 2.5; 17 college-prep courses are required (4 English, 4 math, 2 foreign language, 3 lab science, 2 social science, 2 electives). Essay (up to 650 words) and a teacher/counselor letter are optional but recommended for competitive programs such as nursing, biology, engineering and psychology. Visual and Performing Arts programs require a portfolio or audition. Proof of funds of at least $54,000 (less any scholarship) is needed for the I-20.', '9811cfd6-28ff-55b7-aeb9-ae29e2e5f977');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('8c5e9c59-6ed8-5781-9050-66a2d399e86b', '4b498114-f00f-50c8-b50f-e87a704ecf30', '2026-27', 'application', 'EA', 'Early Action application deadline (fall 2027 entry)', '2026-11-15', 'The Dates & Deadlines page prints these dates under the heading ''Fall 2026'' with no year on the day itself; taken as the same month and day for fall 2027 entry.', 'a2f37bd5-9127-578f-9c32-04517ec59a4b'),
 ('792f4208-8ffb-5b94-bd04-d374c693a829', '4b498114-f00f-50c8-b50f-e87a704ecf30', '2026-27', 'priority', null, 'Priority date for admission applications (nursing priority is also Mar 1)', '2027-03-01', 'Rolling admissions continue through the summer; early applicants get priority for programs, housing and aid. Nursing applications close May 1.', 'a2f37bd5-9127-578f-9c32-04517ec59a4b'),
 ('f00135db-7974-5703-a49f-5ea60c78d4b0', '4b498114-f00f-50c8-b50f-e87a704ecf30', '2026-27', 'application', 'ROLLING', 'Last day to apply - first-year international students (fall)', '2027-07-15', 'International row of the table. The university advises applying about a month earlier because international files take longer. Spring entry: Dec 1.', 'a2f37bd5-9127-578f-9c32-04517ec59a4b'),
 ('f93156ed-d6f5-5ddc-945a-6f0ab9b4e884', '4b498114-f00f-50c8-b50f-e87a704ecf30', '2026-27', 'deposit', null, 'Last day to deposit - first-year international students (fall)', '2027-07-31', null, 'a2f37bd5-9127-578f-9c32-04517ec59a4b');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('4b498114-f00f-50c8-b50f-e87a704ecf30', 'required_nonnative', 'Not required for citizens of Australia, Canada (except Quebec), the UK, Ireland, New Zealand, Guyana and English-speaking countries of Africa and the West Indies. May be waived with written verification that secondary instruction was in English, an IB curriculum, an American school, or IGCSE/O-level/GCE A-level study. Applicants below the minimums who meet all academic requirements are considered for the Gateway Program (conditional pathway).', '9811cfd6-28ff-55b7-aeb9-ae29e2e5f977');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
