 ('TOEFL_IBT', 79, 'Old 0-120 scale. TOEFL Essential 9.0+ and an ELS level 112 certificate are also accepted.'),
 ('TOEFL_IBT_2026', 4, 'Page prints ''TOEFL (79+ or 4+ scale score)''; read as 4.0 on the new 1-6 scale.'),
 ('IELTS', 6.0, 'Overall; no sub-score minimum is published.'),
 ('DUOLINGO', 105, null),
 ('PTE', 53, null),
 ('CAMBRIDGE', 176, 'B2 First, C1 Advanced or C2 Proficiency.')) v;
