insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('62f8aac6-4b22-5a10-a8a1-7a936d20386e', '2026-27', 'optional', 'International first-year applicants may submit SAT or ACT scores (CEEB code 3911) or select the ''No Test'' option.', '603938cf-55af-5f0a-9df4-f84a5d528cde');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('62f8aac6-4b22-5a10-a8a1-7a936d20386e', '2026-27', array['common_app','own']::text[], 70, 'Apply with the UMass Lowell Application or the Common App; $70 fee (waivers available). Required: official secondary records sent directly from the school or Ministry of Education (professionally translated and notarized if not in English), SAT/ACT scores or the No Test option, an essay, a letter of recommendation, and English proficiency scores unless waived. All nursing applicants must apply Early Action I or II.', '603938cf-55af-5f0a-9df4-f84a5d528cde');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('14c5bebd-a5c8-5192-a5bd-4844dbf3b6ac', '62f8aac6-4b22-5a10-a8a1-7a936d20386e', '2026-27', 'application', 'EA', 'Early Action I (fall 2027 entry)', '2026-11-05', 'Listed under first-year deadlines on the Deadlines and Fees page; the page prints no year, taken as fall 2027 entry. Nursing applicants must use EA I or II. The international section of the same page lists only July 25 for fall.', '7b12b688-01fe-59f4-a1ce-ee9cebeb0d97'),
 ('6b385b65-c1de-5090-a425-9c9199971f41', '62f8aac6-4b22-5a10-a8a1-7a936d20386e', '2026-27', 'application', 'EA', 'Early Action II (fall 2027 entry)', '2027-01-15', null, '7b12b688-01fe-59f4-a1ce-ee9cebeb0d97'),
 ('cc481959-89d4-5cbd-94a6-2fb6d6c05fd4', '62f8aac6-4b22-5a10-a8a1-7a936d20386e', '2026-27', 'application', 'RD', 'Regular Decision (fall 2027 entry)', '2027-02-15', null, '7b12b688-01fe-59f4-a1ce-ee9cebeb0d97'),
 ('250b58b8-d698-5927-85cc-4a3a65e5a901', '62f8aac6-4b22-5a10-a8a1-7a936d20386e', '2026-27', 'application', 'ROLLING', 'International final application deadline (fall 2027 entry)', '2027-07-25', 'The page prints no year, taken as fall 2027 entry; international applicants are advised to start at least 12 months before enrollment. Visa (I-20) deadline for admitted applicants outside the U.S.: Aug. 2.', '603938cf-55af-5f0a-9df4-f84a5d528cde');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('62f8aac6-4b22-5a10-a8a1-7a936d20386e', 'required_nonnative', 'Required for all international applicants except citizens of Australia, Canada (except Quebec), United Kingdom, Ireland, New Zealand, Guyana and English-speaking countries of Africa and the West Indies. First-year applicants may also waive the test with written verification that English was the language of instruction, an IB curriculum, an American school, or a Cambridge IGCSE/O-Level/A-Level curriculum. Also accepted: ASC English (minimum 6, High Advanced) and LanguageCert Academic (70-74). Applicants who meet every other criterion but not the English minimum can be referred to ASC English (partner program preparing them for UMass Lowell degree programs). The International Bridge Program (12+ transferable credits at Middlesex Community College first) is another route.', '603938cf-55af-5f0a-9df4-f84a5d528cde');
