insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, notes, source_id, source_note) values
 ('6894f30d-eb57-54c0-9cda-fc0185e4c79b', '2024-2025', 9306, 8972, 774, 'Baseline from IPEDS fall 2024 (admit rate 96.4%). No Common Data Set was found on umes.edu (site search and its Decision Science & Visualization pages), so no international split, GPA or residency data. UMES is test-optional and College Navigator reports no SAT/ACT percentiles. College Navigator shows about 2% of undergraduates from foreign countries (rounded).', '01b27e5e-ab68-563a-b58f-243a859afed8', 'admissions_site');
insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('6894f30d-eb57-54c0-9cda-fc0185e4c79b', '2026-27', 'optional', 'UMES is test-optional for first-year admission; SAT/ACT scores are considered when submitted. A 2.5 GPA is desired (lower GPAs may be considered through programs such as Summer Bridge). Required courses: 4 English, 4 math, 3 natural science, 3 social science. International applicants may submit SAT/ACT in place of an English test.', '3c57d3f1-747e-56f4-9693-acae334a946f');
insert into application_requirements (institution_id, cycle, platforms, supplemental_essays, app_fee_usd, notes, source_id) values
 ('6894f30d-eb57-54c0-9cda-fc0185e4c79b', '2026-27', array['own','common_app']::text[], 'Essay not required (personal statement optional).', 35, 'Apply with the UMES Standard Application, the Common App or the Common Black College Application. Recommendation letters are optional. International applicants also need original secondary transcripts with an English-language credit evaluation, a passport copy, a Certificate of Finances with a bank statement (the manual states $33,500 per year must be verified, based on 2024-25 costs), and an Affidavit of Support. Non-refundable $100 enrollment deposit; $300 housing deposit.', '2044bca4-45b0-5097-9bc5-d40556848854');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('272c2180-49f4-5485-ba59-1431e4ef942b', '6894f30d-eb57-54c0-9cda-fc0185e4c79b', '2026-27', 'application', 'ROLLING', 'International fall application deadline (fall 2027 entry)', '2027-03-01', 'International manual: F-1 applicants must apply by Mar. 1 (later applicants are moved to the next term), submit financial documents and I-20 requirements by Apr. 15 and pay the enrollment deposit by May 1; the page prints no year, so fall 2027 is assumed. The domestic first-year page lists a Nov. 15 priority date and a Feb. 15 fall deadline, which the manual says should not be used by F-1 applicants.', 'a649a2a3-b718-5c77-9cfc-16f092bf3034'),
 ('6c990bef-13da-549e-b6dc-ebf65e24f309', '6894f30d-eb57-54c0-9cda-fc0185e4c79b', '2026-27', 'other', null, 'Financial documents and I-20 requirements due (fall 2027)', '2027-04-15', 'From the international manual; year assumed.', 'a649a2a3-b718-5c77-9cfc-16f092bf3034'),
 ('34a116d6-334b-5246-ba1b-5dd24679b03d', '6894f30d-eb57-54c0-9cda-fc0185e4c79b', '2026-27', 'deposit', null, 'Last day to confirm enrollment with the $100 deposit (fall 2027)', '2027-05-01', 'From the international manual; year assumed.', 'a649a2a3-b718-5c77-9cfc-16f092bf3034');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('6894f30d-eb57-54c0-9cda-fc0185e4c79b', 'required_nonnative', 'Waived for native speakers educated in the US, UK, Canada (except Quebec and Nunavut), Ireland, Australia, New Zealand or the Commonwealth Caribbean, for listed countries (Botswana, The Gambia, Ghana, Liberia, Malawi, Mauritius, Namibia, Nigeria, Samoa, Sierra Leone, Solomon Islands, South Africa), for graduates of a US high school and for transfers from accredited US colleges. SAT/ACT scores are accepted in place of an English test. Non-native speakers without an accepted score must complete ESL course(s) during their first year at UMES. Scores must be within 24 months.', 'a649a2a3-b718-5c77-9cfc-16f092bf3034');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
select '6894f30d-eb57-54c0-9cda-fc0185e4c79b'::uuid, 'required_option', 'a649a2a3-b718-5c77-9cfc-16f092bf3034'::uuid, v.* from (values
 ('TOEFL_IBT', 62, 'Internet-based. The web page and checklist say 62; an older instruction page in the same manual says 61. Applicants below the minimum are generally not considered unless they take ESL courses.'),
 ('IELTS', 7.0, 'Printed as ''minimum score of 7'' in the manual''s English Proficiency Exam Policy; this looks high next to TOEFL 62, so confirm with admissions.'),
 ('DUOLINGO', 110, 'Printed as a range, ''minimum score of 110-120''; the lower value is recorded.'),
 ('PTE', 56, null)) v;
