insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('b78d08d2-3ed6-5eba-bdad-7888146c3bc7', '2026-27', 'optional', 'ACT/SAT not required for admission through the fall 2027 term; official scores sent by the testing agency are used if received. International applicants may self-report scores but need not.', '96f0bb70-4c8c-5e1a-aa40-5c55e731da26');
insert into application_requirements (institution_id, cycle, platforms, supplemental_essays, teacher_recs, counselor_rec, app_fee_usd, notes, source_id) values
 ('b78d08d2-3ed6-5eba-bdad-7888146c3bc7', '2026-27', array['common_app']::text[], 'None; essay not required for admission.', 0, false, 55, 'A complete application is the application form, the $55 fee (automatic fee waiver based on application answers) and a self-reported academic record (Courses and Grades in Common App, or STARS). Essay, letters of recommendation and transcript not required. Freshman School of Nursing applicants must apply by Nov 1 (decisions by Dec 15).', '96f0bb70-4c8c-5e1a-aa40-5c55e731da26');
