insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('cc9f05d8-5e03-50e1-8d55-494b90189707', '2026-27', 'optional', 'Fall 2027 applicants with a weighted GPA of 2.8 or higher at the end of junior year do not need SAT/ACT (scores may be self-reported); applicants below 2.8 must submit SAT or ACT. The pages give no separate international rule. CLT scores are optional and cannot replace required SAT/ACT.', '750802b7-7f85-5413-a045-7989c6a08d2b');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('cc9f05d8-5e03-50e1-8d55-494b90189707', '2026-27', array['common_app','own']::text[], 80, 'International first-year fee is $80 (the domestic page and CDS list $75). Apply via the Future 49er Portal or Common App. Needs official high school transcripts for the last three years plus a course-by-course credential evaluation from a NACES agency (the university does not evaluate foreign transcripts), one essay, and proof of English proficiency. No interview or recommendation letters. Business, Nursing, Computer Science and Engineering are competitive majors that expect an above-average profile.', '37f0c927-0ee4-5f30-ab24-d9de78c7eaca');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('0d453108-2c22-5cd5-8637-469fb75b780b', 'cc9f05d8-5e03-50e1-8d55-494b90189707', '2026-27', 'application', 'EA', 'Early Action (fall 2027 entry)', '2026-11-01', 'The page prints no year; assumed the fall 2027 cycle. Decision by Jan 30. Required documents are due within 15 days after the deadline. Spring-term first-year applicants also apply by Nov 1.', '45518822-2c3f-5c0c-a264-c764ec87800d'),
 ('33af85e9-854b-5edb-9235-b053ca08f3cd', 'cc9f05d8-5e03-50e1-8d55-494b90189707', '2026-27', 'application', 'RD', 'Regular deadline (fall 2027 entry)', '2027-02-01', 'Decision by April 1; documents due within 15 days. Applications after Feb 1 are reviewed only as space is available (decisions after April 1). The CDS lists a June 1 closing date. The international page has a single table (no separate international dates) and advises applying early for visa processing.', '45518822-2c3f-5c0c-a264-c764ec87800d');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('cc9f05d8-5e03-50e1-8d55-494b90189707', 'required_nonnative', 'Citizens currently studying in a country on the English Proficiency Exempt Country List are exempt. Other routes: SAT EBRW 500, ACT Reading 19/20, ELTI Level 5, or a US high school diploma with two completed years. Applicants who need more English can apply for conditional admission through the on-campus English Language Training Institute (ELTI), with guaranteed bachelor''s admission after finishing it and no new application. Scores are valid for 2 years; minimums do not guarantee admission.', '03e6038d-7c7e-5011-9be3-5812cb8f4805');
insert into english_requirements (institution_id, status, test_key, min_total, min_subscores, notes, source_id)
select 'cc9f05d8-5e03-50e1-8d55-494b90189707'::uuid, 'required_option', v.* from (values
 ('TOEFL_IBT', 70, '{"each_section": 14}'::jsonb, 'Old 0-120 scale, from the Proof of English Proficiency page (institution code 5105). That page is older than the application checklist, which shows a new-scale figure.', '03e6038d-7c7e-5011-9be3-5812cb8f4805'::uuid),
 ('TOEFL_IBT_2026', 4, '{"each_section": 4}'::jsonb, 'Checklist page: ''TOEFL IBT: 4 or higher (minimum of 4 in each sub score)''. It does not name the 1-6 scale but the numbers fit it.', '37f0c927-0ee4-5f30-ab24-d9de78c7eaca'::uuid),
 ('IELTS', 6.0, null, 'Overall 6.0. The sub-score minimum is 5.5 on the application checklist but 5.0 on the Proof of English Proficiency page.', '37f0c927-0ee4-5f30-ab24-d9de78c7eaca'::uuid),
 ('DUOLINGO', 105, null, 'Both pages list 105.', '37f0c927-0ee4-5f30-ab24-d9de78c7eaca'::uuid),
 ('PTE', 52, '{"each_section": 42}'::jsonb, 'Application checklist: 52 (minimum 42 each). The Proof of English Proficiency page still lists 48 (minimum 35 each); the higher, newer figure is used.', '37f0c927-0ee4-5f30-ab24-d9de78c7eaca'::uuid)) v;
