insert into cost_aid (institution_id, year, tuition_usd, tuition_out_of_state_usd, tuition_intl_usd, required_fees_usd, room_board_usd, intl_aid_policy, intl_need_aid, meets_full_need, merit_scholarships, notes, source_id) values
 ('cc9f05d8-5e03-50e1-8d55-494b90189707', '2025-2026', 3812, 20018, 20018, 3505, 12390, 'merit_only', false, false, true, 'CDS G1 (2025-26, first-year): in-state tuition $3,812, out-of-state/nonresident $20,018, required fees $3,505, on-campus housing $7,310 + food $5,080 = $12,390. The tuition_usd field is the in-state figure. The 2025-26 CDS has no nonresident-specific financial aid counts, so those fields are left empty.; Need-based aid requires a FAFSA (US citizens and permanent residents only). Admitted students apply for merit scholarships through the NinerScholars portal; there is no automatic merit award and no international-specific amounts are published. Early scholarships for incoming first-years: Feb 15; most others Apr 1; the FAQ also lists Dec 1 for Honors College priority and university-wide merit scholarships.', 'e594ad86-3b64-57e6-a6ca-11ac9a4e6bd4');
