insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('5d82f698-8f9d-5e86-a511-923279e1b72e', '2026-27', 'optional', 'SAT/ACT are optional for applicants with a weighted high school GPA of 2.80 or higher. Weighted GPA 2.50-2.79 must submit SAT 930+ or ACT 17+ (same rule on the international page). The minimum weighted GPA is 2.5 (US high school only); for non-US schools the page asks for an equivalent GPA.', '80f6fe4b-7804-5fa8-8a28-525c09a45df9');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('5d82f698-8f9d-5e86-a511-923279e1b72e', '2026-27', array['common_app','own']::text[], 65, 'Apply via the UNCG application or the Common App. International applicants also send a copy of the passport photo page, official transcripts in English and a course-by-course credential evaluation (SpanTran preferred, or any NACES/AICE member; not needed with IB Diploma, India Standard XII, GCSE/IGCSE or WASSCE results), and proof of funds for the I-20. The essay is optional but recommended; recommendations are not mentioned. Some majors have extra admission criteria and deadlines.', '98bc93f4-206f-5873-9730-4208ec6753c8');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('1462682e-e864-51b2-8c4c-1aec98e3bd07', '5d82f698-8f9d-5e86-a511-923279e1b72e', '2026-27', 'application', 'EA', 'Early Action (fall 2027 entry)', '2026-11-01', 'Materials due Dec 15, 2026; decision from Jan 1, 2027. Submit all materials by Dec 15 for merit scholarship consideration. The page labels these ''Fall 2026'' but the dates match fall 2027 entry. No separate international column; international applicants are urged to apply well ahead for visa processing.', '3c748855-f254-5a8d-8f57-b6ac460c7663'),
 ('9abe9473-d6bd-5715-9d57-091c96087cde', '5d82f698-8f9d-5e86-a511-923279e1b72e', '2026-27', 'application', 'RD', 'Regular Decision (fall 2027 entry)', '2027-03-01', 'Materials due Mar 15, 2027; decision Apr 1, 2027; enroll by May 1. Applications after Mar 1 are reviewed on a space-available, rolling basis. Spring-term first-year applications: Dec 1, 2026.', '3c748855-f254-5a8d-8f57-b6ac460c7663'),
 ('67336b5d-cc5a-5d69-a507-7cda8431370f', '5d82f698-8f9d-5e86-a511-923279e1b72e', '2026-27', 'scholarship', null, 'International student scholarship priority date (fall 2027 entry)', '2027-02-01', 'Feb 1 priority and Apr 1 regular dates for fall are listed on the scholarship page for new international students; no separate scholarship application is needed. Page prints no year, assumed fall 2027.', '27df0c15-334f-5e6e-8014-8caecdcf7a4b');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('5d82f698-8f9d-5e86-a511-923279e1b72e', 'required_nonnative', 'The English score is waived for graduates of a US high school, of an international school/IB school taught entirely in English, with an English Composition grade of C or better at a US college, with the highest level of an approved English academic program, or from Australia, Canada (English curriculum), Bahamas, Cayman Islands, Ireland, New Zealand, South Africa or the United Kingdom. UNCG offers conditional admission to otherwise qualified applicants below the minimums through the on-campus INTERLINK intensive English program (INTERLINK Level 6 meets the requirement).', '98bc93f4-206f-5873-9730-4208ec6753c8');
insert into english_requirements (institution_id, test_key, status, min_total, notes, source_id)
