 ('TOEFL_IBT', 'required_option', 79, 'Old 0-120 scale, from the UNCG Catalog. The Home Edition score is also accepted.', '4acbbc0f-4a7b-5b30-b030-b4e651daed3d'::uuid),
 ('TOEFL_IBT_2026', 'required_option', 4, 'The International Requirements page says ''IBT TOEFL 4'' where the catalog says 79, so the 4 is read as the new 1-6 scale; the page does not name the scale. Confirm with admissions.', '98bc93f4-206f-5873-9730-4208ec6753c8'::uuid),
 ('IELTS', 'required_option', 6.5, 'IELTS Indicator also accepted at the same band score.', '98bc93f4-206f-5873-9730-4208ec6753c8'::uuid),
 ('DUOLINGO', 'required_option', 105, null, '98bc93f4-206f-5873-9730-4208ec6753c8'::uuid),
 ('PTE', 'required_option', 53, null, '98bc93f4-206f-5873-9730-4208ec6753c8'::uuid),
 ('CAMBRIDGE', 'accepted', null, 'Accepted: Cambridge C1 Advanced; no minimum score is listed. Other accepted tests include ELS 112, iTEP 3.8, GTEC 1204 and Kaplan Higher Intermediate.', '98bc93f4-206f-5873-9730-4208ec6753c8'::uuid)) v;
