insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('fd51551f-066b-55a6-8a40-cbe361308c63', '2026-27', 'optional', 'SAT/ACT are not needed for most applicants. Students with a weighted high school GPA of 2.50-2.79 must submit a score (ACT 17+ or SAT 930+ per the CDS); the minimum weighted GPA is 2.5. International pages say applicants ''may be required'' to submit English-proficiency and test scores.', '50be10a3-9417-58a3-8af1-a4327eadb1b3');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('fd51551f-066b-55a6-8a40-cbe361308c63', '2026-27', array['common_app','own']::text[], 55, 'Apply through the UNCP application, CFNC or the Common App (a UNCP account is still needed). International first-year applicants also send an English translation of the official high school transcript and proof of financial support for the I-20; the international page does not state a different fee. Minimum course units follow UNC System rules (4 English, 4 math, 3 science, 2 social studies incl. US history).', '50be10a3-9417-58a3-8af1-a4327eadb1b3');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('7ed735f7-cc11-521e-b5b9-927fc069f639', 'fd51551f-066b-55a6-8a40-cbe361308c63', '2026-27', 'application', 'EA', 'Early Action (fall 2027 entry)', '2026-12-01', 'Early admission and merit scholarship consideration; same dates on the freshman and international pages. Decisions are typically sent within two weeks of a complete file.', '94324b6c-1656-5e3b-85d9-9a6a70b3b273'),
 ('849a2a64-8c38-54f8-b94e-29d47bb68bcd', 'fd51551f-066b-55a6-8a40-cbe361308c63', '2026-27', 'priority', null, 'Priority admission (fall 2027 entry)', '2027-02-01', 'Priority consideration for admission, financial aid and the Maynor Honors College.', '94324b6c-1656-5e3b-85d9-9a6a70b3b273'),
 ('6f2310fc-ad33-53fc-8447-6fee3023c487', 'fd51551f-066b-55a6-8a40-cbe361308c63', '2026-27', 'application', 'ROLLING', 'Final application deadline (fall 2027 entry)', '2027-08-01', 'Rolling admission. The international page lists the same dates as the freshman table (no separate international column). Spring 2027: EA Oct 1, priority Nov 1, final Jan 1. The CDS also lists 8/1 as the closing date. The English Language Institute page separately lists June 17 (fall) and Nov 11 (spring) as priority dates for ELI applicants.', '50be10a3-9417-58a3-8af1-a4327eadb1b3');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('fd51551f-066b-55a6-8a40-cbe361308c63', 'required_nonnative', 'Applicants who do not meet the English minimum can apply to the English Language Institute (ELI) and move into academic classes after finishing the program (conditional pathway). The pages do not list an exemption rule; a staging copy of the ELI page (snappy.uncp.edu, Nov 2024) showed older minimums TOEFL 68 / Duolingo 95.', '0a9ed61c-d3d5-5844-b7dc-32d7b124c2bd');
