insert into cost_aid (institution_id, year, tuition_usd, tuition_out_of_state_usd, tuition_intl_usd, required_fees_usd, room_board_usd, books_usd, intl_aid_policy, intl_need_aid, intl_need_aid_awarded, intl_avg_award_usd, meets_full_need, merit_scholarships, notes, source_id) values
 ('fd51551f-066b-55a6-8a40-cbe361308c63', '2026-2027', 1000, 7000, 7000, 2685, 12120, 1000, 'merit_only', false, 66, 6293, false, true, 'CDS G1 (2026-27, first-year): in-state tuition $1,000 and out-of-state/nonresident $7,000 (NC Promise tuition); housing $6,094 + food $6,026 = $12,120. CDS H6: only institutional non-need-based aid is available to nonresidents; 66 nonresident undergraduates received it (avg $6,293, total $415,326). The tuition_usd field is the in-state figure.; F-1 students get no federal aid. Institutional scholarships are matched through the BraveAssist portal after a general application; Early Action (Dec 1 for fall) is the merit-scholarship consideration date. No international scholarship amounts are published; CDS H6: 66 nonresident undergraduates got institutional non-need-based aid, avg $6,293.', '1cc9026b-4001-5e41-badd-d8fec27ba946');
