insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('c23bd466-96a4-5d5a-b54d-13ebf4ac231c', 'required_nonnative', 'Exempt if English was your primary language of instruction for at least three years (high school, college, or both) by the time you enroll. Official scores only, from tests taken on or after 2025-04-01. Penn does not accept MyBest, IELTS Indicator or IELTS One Skill Retake.', '4d6c9086-9db2-50ac-b3ee-cc63ecfe44fa');
