insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, pct_submit_sat, pct_submit_act, notes, source_id, source_note) values
 ('20ec9d47-b144-5b1c-a254-f7ff6daced39', '2024-2025', 452, 436, 148, 2, 13, 'Baseline from IPEDS (fall 2024 entering class); no Common Data Set was found on Upper Iowa''s website or in web search. Counts from the IPEDS ADM2024 file (via the Urban Institute API mirror): 452 applicants, 436 admitted, 148 enrolled (all full-time). College Navigator shows 2% of enrollees submitting SAT (3 students, no SAT percentiles reported) and 13% submitting ACT (19 students); ACT percentiles rest on that small group. International applicant counts, GPA and class rank are not published. Undergraduate enrollment (3,054, fall 2024) includes online and regional-center students, not only the Fayette campus.', 'abbf1f48-432e-5674-bf99-71285249a4f6', 'admissions_site');
insert into test_score_percentiles (institution_id, cds_year, source_id, test, p25, p50, p75)
