insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('20ec9d47-b144-5b1c-a254-f7ff6daced39', '2026-27', 'optional', 'Fayette freshmen: ACT/SAT submission is optional for applicants with a cumulative high school GPA of 2.4 or higher on a 4.0 scale; below 2.4, ACT or SAT scores must be submitted. International applicants are asked for official secondary transcripts; the international page does not mention an SAT/ACT requirement (SAT/ACT sub-scores are only one way to show English proficiency).', 'ada2cd9f-224f-53a6-8b97-fc9440ab4c70');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('20ec9d47-b144-5b1c-a254-f7ff6daced39', '2026-27', array['own']::text[], 0, 'UIU''s own online application, free (about 15 minutes). International freshman steps: official secondary transcripts in English (or evaluated by WES, ECE or SpanTran; WAEC/WASSCE students may give scratch-card details), proof of English proficiency, passport copy, official bank statement showing funds for one full year (sent by the bank, no older than 6 months; affidavit of support if sponsored) and the non-refundable deposit (International Student Deposit $250 on the 2026-27 costs page). Fayette says it decides within two business days of a complete file. UIU may request additional documents or an interview.', 'b0834f82-a811-5a9f-9624-4e4cb7bb9294');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('a132a9ff-6d77-5230-b955-a596e4da515a', '20ec9d47-b144-5b1c-a254-f7ff6daced39', '2026-27', 'application', 'ROLLING', 'Rolling admission (fall 2027 entry)', null, 'No admission deadline for international students; UIU advises applying at least two months ahead to get a visa in time. The Fayette campus uses semesters, but the international page also says courses start every 8 weeks.', 'd9fecd89-7b31-5d42-988d-83005b4314a4'),
 ('f7e4847a-c634-5f6d-bdea-0438331cf18a', '20ec9d47-b144-5b1c-a254-f7ff6daced39', '2026-27', 'deposit', null, 'Enrollment deposit refund cutoff', '2027-05-01', 'Fayette page: the $100 enrollment deposit is refundable through May 1 of the application year (December 31 for second-semester applicants). The international student deposit is a separate non-refundable $250.', 'ada2cd9f-224f-53a6-8b97-fc9440ab4c70');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('20ec9d47-b144-5b1c-a254-f7ff6daced39', 'required_nonnative', 'Waived for students transferring from a US institution or educated in one of UIU''s listed waiver countries (PDF list on the page). Test scores must be within the last two calendar years. Also accepted: MELAB 69, MUET 4.0, Cambridge O Level English D, IGCSE English D, HKCEE English (Syllabus B) D, HKALE English (AS) E, HKDSE 3, ELS 112, Oxford Online Placement Test 70, SAT critical reading sub-score 430 (institution code 6885), ACT English 18 (code 1360), TOEFL paper 500. Conditional admission: a student who meets all other requirements can be admitted if they complete UIU''s Intensive English program (at least one semester level; no testing out) before academic classes.', 'b0834f82-a811-5a9f-9624-4e4cb7bb9294');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, min_subscores, notes)
select '20ec9d47-b144-5b1c-a254-f7ff6daced39'::uuid, 'required_option', 'b0834f82-a811-5a9f-9624-4e4cb7bb9294'::uuid, v.* from (values
 ('TOEFL_IBT', 61, null, 'Internet-based 61 or higher (paper-based 500). Institution code 6885. No minimum on the new 1-6 scale is printed.'),
 ('IELTS', 5.0, '{"writing": 5.0}'::jsonb, 'Overall band 5.0 and writing band 5.0 or higher.'),
 ('DUOLINGO', 83, null, null),
 ('PTE', 44, null, null)) v;
insert into score_codes (institution_id, source_id, test_key, code, notes)
select '20ec9d47-b144-5b1c-a254-f7ff6daced39'::uuid, 'b0834f82-a811-5a9f-9624-4e4cb7bb9294'::uuid, v.* from (values
 ('sat', '6885', 'SAT institution code given on the international how-to-apply page.'),
