insert into cost_aid (institution_id, year, tuition_usd, tuition_out_of_state_usd, tuition_intl_usd, required_fees_usd, intl_extra_fees_usd, room_board_usd, merit_scholarships, notes, source_id) values
 ('20ec9d47-b144-5b1c-a254-f7ff6daced39', '2026-2027', 19180, 19180, 19180, 1275, 250, 9874, true, 'Fayette campus, full-time 12-18 credits: tuition $9,590 per semester ($19,180 per year), student fees $637.50 per semester ($1,275). One-time International Student Orientation $250 (shown as extra fees). Room and board shown is a sum of published items, not a published total: Garbee Hall double room $4,034 per year plus Peacock Blue unlimited meal plan $5,840 per year (undergraduates living on campus must have a meal plan; the cheaper Peacock Basic plan is only for Lee Tower and Hofmaster residents). Other rooms run $4,766-$7,944 per year. Books are not priced. No separate international tuition rate is published. Heading on the costs page: 2026-27 tuition and fees.; International scholarships are automatic at admission, based on high school GPA, no separate application: Trustee (3.50-4.00) $4,000 per year, Presidential (3.00-3.49) $2,500, Dean''s (2.50-2.99) $1,000, Achievement (2.00-2.49) $500. Transfer awards $500-$1,500 per year (a $5,500 Fayette transfer award needs 48 transferable credits). International students who get an athletic scholarship are not eligible. No international need-based aid was found; FAFSA aid is for US citizens and eligible non-citizens.', '3ca90a92-61f0-5c5b-85cf-9829b5be591f');
insert into institution_tiers (institution_id, tier_code, category_key, rationale)
