insert into cost_aid (institution_id, year, tuition_usd, tuition_out_of_state_usd, room_board_usd, books_usd, other_usd, total_coa_usd, notes, source_id) values
 ('b13f8b0e-6d29-5ac0-a848-77420782c6c3', '2024-2025', 11588, 23090, 10533, 1600, 3600, 27321, 'College Navigator 2024-25: tuition includes required fees; on-campus cost of attendance for South Carolina residents ($38,823 total at the out-of-state tuition rate).; The first-year page lists Chancellor, Valedictorian, Provost, Dean, Promise and Meeting Street Scholars scholarships and a USC System Scholarship but prints no amounts and does not say whether international students are eligible; the international page does not mention scholarships. Left unconfirmed.', '8c663f40-f96b-5b47-87a6-ee877a68c2ec');
