insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, intl_applicants, intl_admits, in_state_applicants, in_state_admits, out_state_applicants, out_state_admits, notes, source_id) values
 ('159ac21f-c009-5d9e-9d09-b6ff8f6e10ad', '2025-2026', 90690, 20154, 9900, 8543, 673, 46879, 16828, 35268, 2653, 'UT''s CDS leaves C9 (test scores), C11/C12 (GPA), C2 (waitlist) and C21 blank. Its C7 boxes mark almost every factor ''Considered'' (only interview, alumni, religion and interest ''Not considered''), which looks like a default fill, so no factors are recorded. Enrolled by residency: 8,958 in-state, 758 out-of-state, 184 international. SAT/ACT percentiles kept from the earlier IPEDS baseline (scores_source ipeds).', '576e905d-8f93-514c-bb87-cf66e61c7897');
