insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('8cdc9d9c-a7c6-54d1-8e30-5ab04be6cb8d', '2026-27', 'required', 'The Freshman Requirements page lists GPA plus ACT combinations (2.85 GPA with ACT 18, or 2.5 GPA with ACT 21) for all first-time freshmen and says all applicants must submit ACT/SAT scores. An older ''Test Optional Admission'' page (written for spring and fall 2022: 3.0 GPA plus one teacher recommendation) is still online, and IPEDS shows 94% of fall 2024 entrants submitted the ACT, so the sources conflict. These pages were read through search extracts because utc.edu could not be fetched here; confirm with admissions whether international applicants may apply test-optional.', 'db04e9b0-d8d8-5fcc-a70c-367caef3600e');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('8cdc9d9c-a7c6-54d1-8e30-5ab04be6cb8d', '2026-27', '{}'::text[], 30, '$30 non-refundable international application fee. International applicants submit an official attested and sealed final secondary transcript or diploma (and transcripts from any college attended), proof of funding dated within six months of applying, a passport photo page and, once enrolled, medical insurance. The application platform is not stated on the pages read.', 'fe5d67d2-f5e3-54fe-a3ab-f5101efee88c');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('e33b3a1e-521c-58f9-832b-6066e478d935', '8cdc9d9c-a7c6-54d1-8e30-5ab04be6cb8d', '2026-27', 'application', 'ROLLING', 'International application documentation deadline, fall 2027', '2027-07-01', 'The international page lists an Application Documentation Deadline of July 1 without naming the term; an older catalog says materials are due July 1 for fall and Nov. 1 for spring, so it is treated as fall 2027. The general first-year page lists a fall priority date, but sources disagree (Dec. 1 vs May 1), so it is not recorded.', 'fe5d67d2-f5e3-54fe-a3ab-f5101efee88c'),
 ('d0c9969d-a5f3-5e6c-b6fe-c3de734e3b43', '8cdc9d9c-a7c6-54d1-8e30-5ab04be6cb8d', '2026-27', 'scholarship', null, 'International Undergraduate Student Scholarship application (fall entry)', '2027-07-01', 'Applicants must already be fully accepted, hold a UTCID and complete a ''Why UTC?'' project; fall-semester entrants only because funding is limited.', '15a6cfe5-751d-5e06-8340-0675e7a55530');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('8cdc9d9c-a7c6-54d1-8e30-5ab04be6cb8d', 'required_nonnative', 'Applicants from an approved English-speaking country, or with a degree from a U.S. institution within the past two years, may request an exemption with a waiver form. Scores must be no more than two years old. No conditional-admission or ESL pathway into the undergraduate program was confirmed on the pages read.', 'fe5d67d2-f5e3-54fe-a3ab-f5101efee88c');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
select '8cdc9d9c-a7c6-54d1-8e30-5ab04be6cb8d'::uuid, 'required_option', 'fe5d67d2-f5e3-54fe-a3ab-f5101efee88c'::uuid, v.* from (values
 ('TOEFL_IBT', 61, 'Undergraduate minimum. No 1-6 scale value is given on the page.'),
 ('IELTS', 5.5, 'Undergraduate minimum.'),
 ('DUOLINGO', 85, 'Undergraduate minimum on the 10-160 scale.')) v;
insert into score_codes (institution_id, source_id, test_key, code, notes)
select '8cdc9d9c-a7c6-54d1-8e30-5ab04be6cb8d'::uuid, 'fe5d67d2-f5e3-54fe-a3ab-f5101efee88c'::uuid, v.* from (values
 ('sat', null, 'Not printed on the pages read; look up in the College Board code search.'),
 ('act', null, 'Not printed on the pages read; look up at act.org.'),
 ('toefl', '1831', 'Institution code given on the international page for score reporting (read through a search extract).'),
 ('ielts', null, 'No institution code is listed.'),
 ('duolingo', null, 'No institution code is listed.')) v;
insert into cost_aid (institution_id, year, tuition_usd, tuition_out_of_state_usd, room_board_usd, books_usd, other_usd, intl_aid_policy, intl_need_aid, meets_full_need, merit_scholarships, notes, source_id) values
 ('8cdc9d9c-a7c6-54d1-8e30-5ab04be6cb8d', '2024-2025', 10448, 18512, 12604, 1400, 4100, 'merit_only', false, false, true, 'College Navigator 2024-25 (tuition and fees, first-year full-time): in-state $10,448, out-of-state $18,512; books $1,400; on-campus food and housing $12,604; other expenses $4,100. UTC''s international cost page lists full-time tuition and fees of $28,134 per year, living expenses $16,632 and a total of $47,022, but does not label the academic year, so those are not stored as structured figures.; Federal financial aid is not available to international students. UTC International Undergraduate Student Scholarship: up to $5,000 for one academic year, not renewable, for first-time international students entering in the fall who are fully accepted; apply by July 1; students already receiving other scholarships are not eligible.', '4d4afbb8-ac6c-54ce-8760-6f998f6f14ed');
