insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('81d84e01-1c08-57f5-a6df-4c57b70596a7', '2026-27', 'optional', 'SAT and ACT are optional for admission; scores are supporting documents for admission and scholarship decisions and can earn a TSI exemption. Automatic admission at a 3.0 unweighted GPA or top 25% of class; 2.75-2.99 is reviewed holistically; below 2.75 gets additional review and possible conditional admission.', '6773c9eb-27a5-5d44-b075-bc0f624cb1de');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('81d84e01-1c08-57f5-a6df-4c57b70596a7', '2026-27', array['common_app','own']::text[], 40, 'Apply through ApplyTexas (''own'') or the Common App (freshman page); the international page names ApplyTexas. $40 fee. All academic records must be evaluated by a credential service (WES, The Evaluation Company, FCSA, ECE, GCE or GEO) and sent to admissions@utpb.edu, with certified English translations. A Certification of Finances form with a bank, institution or sponsor letter is needed for the I-20 (no minimum amount stated). Bacterial meningitis vaccination is required for most on-campus students under 22.', '6258e853-7477-5896-855b-4033edab5b27');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('0d1bf721-adea-5ac9-9ae2-b6ed45f3c071', '81d84e01-1c08-57f5-a6df-4c57b70596a7', '2026-27', 'application', 'ROLLING', 'International: submit transcripts and documents at least 120 days before the fall 2027 term starts', null, 'No calendar date is published. The international page says documents are due at least 120 days before the semester begins; the catalog says apply at least 120 days before enrollment, with test scores and academic records received no later than 60 days before. Fall classes normally begin in late August, so plan for roughly late April 2027 (estimate, not a published date).', '6258e853-7477-5896-855b-4033edab5b27'),
 ('73ae92d4-ad38-580d-bedc-37045d795daf', '81d84e01-1c08-57f5-a6df-4c57b70596a7', '2026-27', 'scholarship', null, 'Presidential Scholarship application (full tuition and designated fees)', '2026-12-01', 'Page says applications are due each December 1 (the current-cycle window is open until Dec. 1, 2026) and recipients are notified by January 15. It does not say whether international students are eligible.', '72b01b16-f645-5199-b2d6-8c9f32fe1ec2'),
 ('c44bb452-78e0-51b9-93d0-9b92c982a37d', '81d84e01-1c08-57f5-a6df-4c57b70596a7', '2026-27', 'scholarship', null, 'Freshman merit scholarship: apply for admission by this date to be eligible', '2027-04-15', 'Freshman merit page says applicants must have applied by April 15 (awards made Sept. 1 to April 15) and register for orientation by June 1. The page prints no year (it is partly out of date); treated as fall 2027. International eligibility is not stated.', 'a35bb90a-1698-53e6-856b-0c905a156bd5');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('81d84e01-1c08-57f5-a6df-4c57b70596a7', 'required_nonnative', 'Exempt: applicants from countries where English is the sole official and primary conversational language (the page lists e.g. Australia, Canada except Quebec, Ghana, India, Ireland, Jamaica, Kenya, Nigeria, Singapore, United Kingdom, among others). The catalog also exempts students with 24 transferable semester hours from a regionally accredited U.S. institution including English 1301 and 1302 with a C or better. Scores must be sent directly from the testing service.', '6258e853-7477-5896-855b-4033edab5b27');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, min_subscores, notes)
select '81d84e01-1c08-57f5-a6df-4c57b70596a7'::uuid, 'required_option', '6258e853-7477-5896-855b-4033edab5b27'::uuid, v.* from (values
 ('TOEFL_IBT', 79, null, 'Paper-based 550 (computer-based 213 in the catalog). The page does not mention the new 1-6 TOEFL scale.'),
 ('IELTS', 6.5, '{"each_section": 6.0}'::jsonb, 'Overall band 6.5 with at least 6.0 in each subsection.'),
 ('DUOLINGO', 100, null, null)) v;
