insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('7abaddc4-3816-50e0-a8e4-abb14b5a2ed0', '2026-27', 'optional', 'The first-year page asks applicants to send ACT or SAT scores ''if available''; the international page says UT Tyler does not require ACT/SAT for admission but encourages scores for class placement (that sentence still names the 2022-2023 and 2023-2024 years). Admission rests on class rank/GPA: top 25% automatic, other quartiles need a 2.75 GPA.', '7fefdb10-e050-58f8-9883-fd443e145e9a');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('7abaddc4-3816-50e0-a8e4-abb14b5a2ed0', '2026-27', array['common_app','own']::text[], 75, 'International freshmen apply on ApplyTexas (''own''; opens Aug. 1); the first-year page also mentions the Common App. $75 non-refundable international fee ($60 domestic). Requirements: accredited high school program; top 25% of class is automatic, 2nd to 4th quartile need a minimum 2.75 GPA, and a school that does not rank needs a 2.75 GPA. Foreign transcripts need translation and a course-by-course evaluation with a GPA from WES, The Evaluation Company or another listed agency. ACT/SAT are optional. TSI is required before enrollment.', '7fefdb10-e050-58f8-9883-fd443e145e9a');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('ce64abed-d132-5434-97cd-e805013c46b6', '7abaddc4-3816-50e0-a8e4-abb14b5a2ed0', '2026-27', 'application', 'ROLLING', 'International undergraduate fall deadline, applicants outside the U.S. (fall 2027)', '2027-05-31', 'International table: Fall May 31 (if out of country) or June 30 (if already in the United States); Spring Oct. 31 / Nov. 30; Summer Feb. 28 / March 30. The table prints no year, so fall 2027 is assumed. Application opens Aug. 1.', '7fefdb10-e050-58f8-9883-fd443e145e9a'),
 ('a38baf25-667a-5e65-a4b9-2e578af3b0a6', '7abaddc4-3816-50e0-a8e4-abb14b5a2ed0', '2026-27', 'scholarship', null, 'Scholarship application deadline (fall 2027 entry)', '2026-12-01', 'First-year page: December 1 is the ''application deadline to be eligible for scholarships''. The international scholarship page (headed 2022-2023) lists December 1 priority and March 1 final dates for the Patriot Scholarship and Academic Excellence Scholarship; Honors Scholars is December 1 only. Confirm the current year with international admissions.', '10b3b267-6c63-5a1a-9525-82167962d671');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('7abaddc4-3816-50e0-a8e4-abb14b5a2ed0', 'required_nonnative', 'Waived for a high school diploma or any degree from a U.S. institution, a B or higher in ENGL 1301 and 1302 (or equivalent) at an accredited U.S. institution, naturalized U.S. citizens, and citizens or degree holders of exempt countries (e.g. Australia, Canada except Quebec, Ghana, Ireland, Jamaica, Kenya, New Zealand, Nigeria, United Kingdom). Completing Level 6 of UT Tyler''s Intensive English Language Institute (IELI) with no grade below A, or Level 7 with no grade below B, may earn a waiver. Scores must be less than 2 years old at the start of the term. The pages read do not describe a conditional admission pathway through IELI.', '7fefdb10-e050-58f8-9883-fd443e145e9a');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, min_subscores, notes)
select '7abaddc4-3816-50e0-a8e4-abb14b5a2ed0'::uuid, 'required_option', '7fefdb10-e050-58f8-9883-fd443e145e9a'::uuid, v.* from (values
 ('TOEFL_IBT', 79, null, 'Paper-based TOEFL 550 is also accepted. The page does not give the new 1-6 scale.'),
 ('IELTS', 6.5, '{"each_section": 6.0}'::jsonb, '6.5 band score with 6.0 in each subsection (stated in the shared English-proficiency block).'),
 ('DUOLINGO', 105, null, null),
 ('PTE', 53, null, 'Pearson PTE Academic. EIKEN Grade 1 is also listed.')) v;
insert into score_codes (institution_id, source_id, test_key, code, notes)
select '7abaddc4-3816-50e0-a8e4-abb14b5a2ed0'::uuid, '7fefdb10-e050-58f8-9883-fd443e145e9a'::uuid, v.* from (values
 ('sat', null, 'The international admissions pages do not print an SAT code; look it up in the College Board code search.'),
 ('act', null, 'No ACT code is printed on the pages read; look it up at act.org.'),
 ('toefl', '6850', 'UT Tyler ETS code for TOEFL.'),
 ('ielts', null, 'No institution code is needed; ask the IELTS test center to send scores electronically to UT Tyler.'),
 ('duolingo', null, 'No institution code is listed.'),
 ('pte', null, 'No institution code is listed.')) v;
insert into cost_aid (institution_id, year, tuition_usd, tuition_out_of_state_usd, tuition_intl_usd, required_fees_usd, room_board_usd, books_usd, other_usd, intl_aid_policy, intl_need_aid, meets_full_need, merit_scholarships, notes, source_id) values
 ('7abaddc4-3816-50e0-a8e4-abb14b5a2ed0', '2026-2027', 7232, 22680, 22680, 2504, 13756, 2920, 3138, 'merit_only', false, false, true, 'CDS G1 (first-year, full-time, as printed under the 2026-2027 heading): in-state tuition $7,232, nonresident tuition $22,680 (about $756/credit hour x 30), required fees $2,504, on-campus food and housing $13,756 (housing $9,074 + meal plan $4,684). G5 resident estimates: books $2,920, transportation $1,424, other $1,714 (other_usd = transportation + other). UT Tyler publishes no separate international tuition rate on the pages read; tuition_intl_usd is the nonresident rate.; The international scholarship page (headed 2022-2023, so confirm amounts) lists: Honors Scholars $10,000 (3.75+ GPA, Dec. 1, interview, four-year eligibility); Patriot Scholarship $1,000-$5,000 (3.5+ GPA, priority Dec. 1, final March 1); Academic Excellence Scholarship $2,000 (top 25% with 3.0 GPA, or 3.5 GPA for international/unranked students; no application). Awards must be confirmed by May 1 and funding is limited. CDS nonresident aid figures are blank in the PDF.', '9b6e0e55-4268-5645-aec4-f83eed56881f');
