insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('ca2e421f-9ec4-5bb6-b843-00dac93b0912', '2026-27', 'optional', 'The international admissions steps page asks for transcripts (minimum GPA 2.7) and English proof; SAT and ACT appear there only as ways to show English (SAT EBRW 500, ACT English 18). CDS C8A marks SAT/ACT as not required for admission but considered if submitted.', 'd0dee595-4215-5a00-9e94-68bcff55b4d7');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, fee_waiver, notes, source_id) values
 ('ca2e421f-9ec4-5bb6-b843-00dac93b0912', '2026-27', array['own']::text[], 50, false, 'USU undergraduate application with a $50 non-refundable fee (no waivers for international undergraduates). Official transcripts for the last three years of high school with certified English translations; minimum GPA 2.7 (some majors require more); English proficiency scores sent at least a month before the deadline. Admitted students pay a $200 enrollment deposit before the I-20 process and must show a year of funds. F-1 students must take most classes face-to-face on the Logan main campus. The CDS shows no essay, interview or extracurricular consideration.', 'd0dee595-4215-5a00-9e94-68bcff55b4d7');
insert into deadlines (id, institution_id, cycle, kind, label, due_date, notes, source_id) values
 ('9b7ae6ad-9878-5f5a-b489-5a1fd81f539f', 'ca2e421f-9ec4-5bb6-b843-00dac93b0912', '2026-27', 'priority', 'Fall priority application deadline (fall 2027 entry)', '2027-03-01', 'Printed as March 01 without a year (treated as fall 2027). No later final fall deadline is listed on the page; late applications may be processed for the next available semester. Spring priority deadline is Oct. 1.', 'd0dee595-4215-5a00-9e94-68bcff55b4d7'),
 ('56c16a82-551d-54b8-b546-5f8262bf0680', 'ca2e421f-9ec4-5bb6-b843-00dac93b0912', '2026-27', 'deposit', 'Fall priority enrollment deposit ($200)', '2027-04-01', 'Spring deposit deadline is Nov. 1. The $200 deposit is required before starting the I-20 process.', 'd0dee595-4215-5a00-9e94-68bcff55b4d7');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('ca2e421f-9ec4-5bb6-b843-00dac93b0912', 'required_nonnative', 'Waived with at least 3 years of secondary education completed in English with satisfactory English courses (ESL excluded), or at least 24 credits of English-medium coursework at an accredited US institution (ESL excluded); applicants who think they qualify can file an English Language Proficiency Appeal after applying. Other accepted proof: MET 52, SAT EBRW 500, ACT English 18. Scores older than two years are not accepted and must be sent by the testing agency (IELTS, MET and Cambridge student copies can be uploaded). PTE is not mentioned on the page. No conditional-admission or ESL pathway is described on the pages reviewed.', '8b8015ea-e470-53f5-8bca-0418772c5f04');
insert into english_requirements (institution_id, source_id, test_key, status, min_total, min_subscores, notes)
select 'ca2e421f-9ec4-5bb6-b843-00dac93b0912'::uuid, '8b8015ea-e470-53f5-8bca-0418772c5f04'::uuid, v.* from (values
 ('TOEFL_IBT', 'required_option', 71, null, 'Tests taken before 2026-01-21; Home Edition accepted. The page does not label the scale.'),
 ('TOEFL_IBT_2026', 'required_option', 4.0, null, 'Tests taken on or after 2026-01-21: at least 4.0 on the 1-6 scale.'),
 ('IELTS', 'required_option', 6.0, '{"each_section": 5.0}'::jsonb, 'IELTS Academic: 6.0 overall with at least 5.0 in each subscale. General Training not accepted.'),
 ('DUOLINGO', 'required_option', 105, null, null),
 ('CAMBRIDGE', 'accepted', 169, null, 'B2 First, C1 Advanced or C2 Proficiency score of 169.')) v;
insert into score_codes (institution_id, test_key, code, notes, source_id)
select 'ca2e421f-9ec4-5bb6-b843-00dac93b0912'::uuid, v.* from (values
 ('sat', '4857', 'USU institution code for SAT.', 'd0dee595-4215-5a00-9e94-68bcff55b4d7'::uuid),
 ('act', '4276', 'USU institution code for ACT.', 'd0dee595-4215-5a00-9e94-68bcff55b4d7'::uuid),
 ('toefl', '4857', 'USU institution code for TOEFL; the English page gives 4857.', '8b8015ea-e470-53f5-8bca-0418772c5f04'::uuid),
 ('ielts', null, 'Upload the student copy of the score report to the online application; no institution code is listed.', null),
 ('duolingo', null, 'Send results to USU from the Duolingo portal; no institution code is listed.', null)) v;
insert into cost_aid (institution_id, year, tuition_usd, tuition_out_of_state_usd, tuition_intl_usd, required_fees_usd, intl_extra_fees_usd, room_board_usd, books_usd, other_usd, total_coa_usd, merit_scholarships, notes, source_id) values
 ('ca2e421f-9ec4-5bb6-b843-00dac93b0912', '2026-2027', 8272, 25717, 25717, 793, 250, 9746, 856, 8442, 46062, true, 'International undergraduate estimate for Fall 2026 and Spring 2027 (9 months, Logan): tuition and fees $29,222, international student fee $250, living expenses $8,148, personal expenses $8,442, total $46,062. The $29,222 tuition-and-fees estimate is higher than CDS tuition plus required fees ($25,717 + $793), and the page does not itemize the difference (it notes differential tuition and program fees may apply). Proof of one year of funds is required for the I-20.; CDS G1/G5 first-year 2026-27: in-state tuition $8,272, out-of-state and nonresident $25,717, required fees $793, on-campus food and housing $9,746, books $856, transportation $2,648, other $1,628. Tuition varies by program (G4 = yes).; The international undergraduate scholarship list shows the Afton B. Tew Scholarship ($1,000, 1-4 years), the Kim Nam Kyun Scholarship ($2,000, 1-4 years, must be admitted to apply), an International Nonresident Tuition Waiver (HB118, amount varies, 1-4 years) and an International Alumni Legacy Nonresident Waiver (amount varies, 1 year). CDS H6 checks both need-based and non-need-based institutional aid for nonresidents and reports 1,564 recipients averaging $15,299, but that count is far larger than the 218 nonresident undergraduates in B2, so it is not used as an international figure. Eligibility rules for each award were not reviewed.', 'ec7fed23-9f38-5660-a17f-c2d073aa9cce');
