insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('43870941-5645-5abb-a696-bdbbca1f7b7a', '2026-27', 'optional', 'The 2024-25 catalog says UTRGV is test optional for the current catalog cycle; freshman applicants may submit SAT or ACT. International first-year applicants are admitted on academic records (foreign credential evaluation required) plus English proficiency.', 'b657640b-178c-50bc-a1c6-e6fca831196a');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('43870941-5645-5abb-a696-bdbbca1f7b7a', '2026-27', array['own']::text[], 50, 'Apply through ApplyTexas (''own''); $50 non-refundable international fee paid through the UTRGV Marketplace. Applicants with foreign schooling need a credential evaluation (WES, FCSA, The Evaluation Company or IEE) sent directly to UTRGV. After admission: Certificate of Financial Responsibility, bank statement and passport for the I-20. TSI testing and meningitis vaccination are required for enrollment, not admission.', 'e64759ba-758f-5987-bc57-7b965a38a762');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('ebf1e6cc-e0b5-5d01-b0c2-3cd3b4c11a6c', '43870941-5645-5abb-a696-bdbbca1f7b7a', '2026-27', 'priority', 'ROLLING', 'Fall priority deadline (international undergraduate, fall 2027 entry)', '2027-05-01', 'The page lists priority deadlines of April 1 (summer), May 1 (fall) and Nov. 1 (spring) with no year; treated as fall 2027. Applications completed after the priority date are still considered but processing may take longer.', 'e64759ba-758f-5987-bc57-7b965a38a762');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('43870941-5645-5abb-a696-bdbbca1f7b7a', 'required_nonnative', 'No test needed for citizens of listed English-speaking countries (e.g. UK, Ireland, Canada except Quebec, Australia, New Zealand, Nigeria, Ghana, Jamaica and others on the UTRGV list). Exemptions after official transcripts: 30+ credit hours from an accredited U.S. university, two semesters of U.S. freshman English composition with a C or better, a U.S. bachelor''s degree, three years of U.S. high school, or completing the Advanced level of UTRGV''s English Language Programs intensive program.', 'e64759ba-758f-5987-bc57-7b965a38a762');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
