insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, intl_applicants, intl_admits, in_state_applicants, in_state_admits, out_state_applicants, out_state_admits, waitlist_offered, waitlist_accepted, waitlist_admitted, pct_submit_sat, pct_submit_act, gpa_avg, pct_reporting_gpa, gpa_distribution, notes, source_id) values
 ('5b8bb0fc-03b3-5f81-b244-d857249bbd8f', '2025-2026', 5616, 4852, 1157, 49, 45, 4585, 4067, 982, 740, 665, 370, 334, 14.78, 1.98, 3.53, 100.0, '{"4.0": 3.35, "3.75-3.99": 28.18, "3.50-3.74": 26.89, "3.25-3.49": 21.05, "3.00-3.24": 14.0, "2.50-2.99": 6.53, "2.0-2.49": 0.0, "1.0-1.99": 0.0}'::jsonb, 'CDS C1 fall 2025 first-year class, read from the PDF''s fillable fields: 2,704 men + 2,904 women + 8 unknown = 5,616 applicants; 4,852 admitted (86%); 1,157 enrolled. Residency: in-state 4,585 applied / 4,067 admitted / 1,126 enrolled; out-of-state 982 / 740 / 16; international 49 / 45 / 15 (92% admitted). UW Bothell has an early action plan (Nov 15) and a waitlist. Undergraduate enrollment 5,753 and 139 nonresident undergraduates are the B1/B2 totals. The SAT range comes from the 14.8% (172) of enrolled first-years who submitted SAT; UW Bothell is test-optional, so it is not an admission benchmark. SAT ERW/Math and ACT percentiles are fractional in the CDS and are not loaded. The C7 factor checkboxes could not be mapped reliably, so factors are omitted.', '07276126-89af-5963-9bd3-05af804efb8a');
insert into test_score_percentiles (institution_id, cds_year, test, p25, p50, p75, source_id) values
 ('5b8bb0fc-03b3-5f81-b244-d857249bbd8f', '2025-2026', 'SAT_TOTAL', 1030, 1215, 1360, '07276126-89af-5963-9bd3-05af804efb8a');
insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('5b8bb0fc-03b3-5f81-b244-d857249bbd8f', '2026-27', 'optional', 'UW Bothell''s FAQ says it does not require SAT or ACT scores; students who have taken them are welcome to send scores, with no advantage or disadvantage. College Navigator (fall 2024) lists SAT/ACT as ''not required, but considered (test optional)''. This is a Bothell policy; UW Seattle and Tacoma have their own admissions.', 'e4f6e1db-00b4-54be-bad3-50c7ec7cb8cd');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('5b8bb0fc-03b3-5f81-b244-d857249bbd8f', '2026-27', array['common_app']::text[], 85, 'First-year international applicants apply through the Common App; the online fee is $85 for international students ($70 domestic). Minimum cumulative GPA 2.0 and Washington''s College Academic Distribution Requirements (4 English, 3 math, 3 social studies, 3 science, 2 world language, 1 senior-year math-based quantitative course, 1/2 arts, 1/2 elective); students who must prove English proficiency are exempt from the world language requirement. Holistic review: College Navigator shows GPA, school record, college-prep program, essay and English proficiency are required to be considered. Documents: official records from every school, certified English translations, and credential evaluations for post-secondary work. The application stays ''Incomplete'' until English proficiency is met. A $250 deposit follows acceptance. Which rules are UW-wide: only the state-set course requirements. UW Bothell has its own admissions office, application dates, English minimums and Common Data Set, separate from UW Seattle and UW Tacoma.', 'ceb9b446-1027-5520-a5bf-8d02908afbe3');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('869ad440-3679-51a0-a1be-a020deb88d98', '5b8bb0fc-03b3-5f81-b244-d857249bbd8f', '2026-27', 'application', 'EA', 'Early Action deadline (autumn 2027 first-year)', '2026-11-15', 'The dates page lists Autumn 2027 first-year dates: application opens Aug 15, 2026; early action decisions in January 2027. It gives no separate international deadline.', 'a56c6132-97da-5288-8326-14ba39c5e219'),
 ('f4376146-ae6f-5807-8e0c-7dedb1283a41', '5b8bb0fc-03b3-5f81-b244-d857249bbd8f', '2026-27', 'application', 'RD', 'Regular Decision deadline (autumn 2027 first-year)', '2027-01-15', 'Regular decision notifications in March 2027. The first-year page also says the final application date is January 15. No separate international deadline is published; international applicants must also complete English proficiency or the application is incomplete.', 'a56c6132-97da-5288-8326-14ba39c5e219');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('5b8bb0fc-03b3-5f81-b244-d857249bbd8f', 'required_nonnative', 'Proof is required for students who did not complete most of their primary and secondary education in the U.S., Australia, Canada, Ireland, New Zealand or the U.K. UW Bothell decides whether proficiency is met. Without a test: four years of U.S. high school English with 3.0+ each year plus SAT EBRW 560 (or SAT Critical Reading 500) or ACT English 21; or 90 quarter transferable credits from a U.S. regionally accredited college with a 2.75 GPA and 3.0 in English 131 and 141 equivalents; or a U.S. bachelor''s degree. Scores are valid two years. iTEP 3.9 and GATEWAY 475 are also accepted but are not selectable tests here. No conditional admission or ESL pathway is described on the pages checked.', '1599f049-2607-5a8c-82b5-58a0036e1004');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
select '5b8bb0fc-03b3-5f81-b244-d857249bbd8f'::uuid, 'required_option', '1599f049-2607-5a8c-82b5-58a0036e1004'::uuid, v.* from (values
 ('TOEFL_IBT', 83, 'For exams taken before Jan 21, 2026.'),
 ('TOEFL_IBT_2026', 4.0, 'For exams taken on or after Jan 21, 2026 (1-6 scale).'),
 ('IELTS', 6.5, 'Overall band score.'),
 ('DUOLINGO', 105, 'Duolingo English Test.')) v;
insert into score_codes (institution_id, test_key, code, notes, source_id) values
 ('5b8bb0fc-03b3-5f81-b244-d857249bbd8f', 'toefl', '9964', 'UW Bothell TOEFL institution code.', '1599f049-2607-5a8c-82b5-58a0036e1004');
insert into cost_aid (institution_id, year, tuition_intl_usd, room_board_usd, books_usd, meets_full_need, notes, source_id) values
 ('5b8bb0fc-03b3-5f81-b244-d857249bbd8f', '2026-2027', 45822, 17538, 900, false, 'Nonresident tuition and fees are $15,274 per quarter (10-18 credits) for autumn, winter and spring = $45,822 (tuition_intl_usd is tuition and fees combined; the page gives no split). room_board_usd and books_usd are CDS G1/G5 figures (on-campus food and housing $17,538, books $900), whose academic year is not clearly stated (the CDS checkbox says final 2026-27 costs were due 6/1/2026). UW Bothell''s I-20 funding requirement for undergraduate nonresidents is $74,823 per academic year (tuition, living expenses and health insurance; no breakdown given).; International students have limited institutional funding. The UW Bothell General Scholarship is open to international students who meet the enrollment and GPA conditions, by invitation email and a separate application; amount and deadline are not listed. The Husky Promise is for Washington residents only. The CDS H6 box for nonresidents (INTL_NO) appears to be marked, meaning no institutional aid reported for them.', '7100ea34-6707-5dbc-8c0d-c841785f7695');
