insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('edcfaab5-448b-5f96-afe6-b2c3486580ed', '2026-27', 'optional', '''ACT and SAT test scores aren''t required and won''t impact your admission decision''; they can help with scholarships and course placement. Codes: ACT 4688, SAT 1859.', '2c0c3f71-2df5-554d-91c6-3fc3961bfb8f');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('edcfaab5-448b-5f96-afe6-b2c3486580ed', '2026-27', array['own']::text[], 50, 'Apply with the Universities of Wisconsin application. International applicants need the official secondary transcript, diploma or exam results (certified English translation if needed), an English proficiency score, a bank statement or letter and a signed financial support statement, and a passport copy. The $50 application fee comes from the CDS (C13); the international page does not mention it and instead lists a $50 International Student Processing Fee payable after acceptance, before the I-20 is issued.', '76c27387-db98-521f-abe1-aea74101c4c0');
insert into deadlines (id, institution_id, cycle, kind, label, due_date, notes, source_id) values
 ('8beddc5a-7a10-5008-99df-ad0b9620f757', 'edcfaab5-448b-5f96-afe6-b2c3486580ed', '2026-27', 'application', 'Last day to apply for fall 2027 (international students)', '2027-07-01', 'The page says international deadlines stay the same each year and prints no year; treated as fall 2027. Documents to complete the application are due the next day (July 2). Spring: Dec. 1 (documents Dec. 2). The domestic first-year fall deadline is Aug. 23, 2027.', '76c27387-db98-521f-abe1-aea74101c4c0');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('edcfaab5-448b-5f96-afe6-b2c3486580ed', 'required_nonnative', 'Scores must be no more than 2 years old. Other accepted proofs: ACT English+Reading combined 34 (neither below 17), SAT reading/writing 480+, Michigan English Test 53+, IGCSE (five C or higher), and Wisconsin ESL Institute (WESLI) level 600. Four years at a U.S. high school do not exempt a student. Waived for a U.S. post-secondary degree (or one from a listed English-speaking country), 15 transferable U.S. credits with a 2.5 GPA (transfer), or citizenship of a listed English-speaking country (e.g. Canada excluding Quebec, UK, Ireland, Australia, New Zealand, Singapore, Nigeria, Ghana, Kenya, South Africa).', '76c27387-db98-521f-abe1-aea74101c4c0');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
