insert into cost_aid (institution_id, year, tuition_usd, tuition_out_of_state_usd, tuition_intl_usd, intl_extra_fees_usd, room_board_usd, books_usd, merit_scholarships, notes, source_id) values
 ('edcfaab5-448b-5f96-afe6-b2c3486580ed', '2026-2027', 9133, 17721, 17721, 50, 8244, 800, true, 'Cost page for 2026-27: tuition and fees $9,133 for Wisconsin residents and $17,721 for out-of-state/non-resident students (fees included; international students pay the non-resident rate). Housing $4,854 plus meal plan $3,390 = $8,244 (as listed; the page does not say which room or plan). Books about $800; new student fee $217; optional parking $210. Extra fees $50 = one-time International Student Processing Fee after acceptance.; Phoenix Scholar Award is an automatic tuition remission (not a scholarship or financial aid) for new first-year or transfer out-of-state and international students in in-person classes: Gold (100% of the non-resident portion of tuition) with SAT 1230+, ACT 26+ or GPA 3.51+; Green (75%) with SAT 1130-1220, ACT 23-25 or GPA 3.25-3.50. Dollar amounts for international students are not published; the page says to call or email. The CDS H6 marks both institutional need-based and non-need-based aid as available to nonresidents, but no international need-based program is described, so the aid policy is left blank.', 'ba54c2f7-149a-51ff-b582-2ef7ed43a9cd');
