insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('408c4ede-4468-5bbb-a10c-2f53e828bf0a', '2026-27', 'optional', 'ACT/SAT are optional for applicants through the spring 2028 term (application deadline Oct 1, 2027); the choice made on the application is final and no disadvantage for omitting scores.', '944b25a1-ff83-5389-a79a-3b62a075c3c4');
insert into application_requirements (institution_id, cycle, platforms, supplemental_essays, app_fee_usd, fee_waiver, notes, source_id) values
 ('408c4ede-4468-5bbb-a10c-2f53e828bf0a', '2026-27', array['common_app','own']::text[], 'Two essays: a personal essay (Common App prompt, or the Universities of Wisconsin Application prompt) plus a ''Why UW-Madison and your chosen major(s)'' essay.', 80, true, 'Common Application or the Universities of Wisconsin Application (no preference between them). One letter of recommendation is required from someone who can attest to academic ability (teacher, school counselor or faculty member); a second is optional. First and second choice major requested.', '944b25a1-ff83-5389-a79a-3b62a075c3c4');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notification_date, notes, source_id) values
 ('54e702ac-07dc-509b-bc04-0e9f9bcdb2f3', '408c4ede-4468-5bbb-a10c-2f53e828bf0a', '2026-27', 'application', 'EA', 'Early Action (non-binding)', '2026-11-01', '2027-01-31', 'Materials deadline Nov 9. Decision released on or before Jan 31. Non-binding; reply by May 1.', '18188c2c-ef3f-5e22-adef-5e528cb1fb61'),
 ('df9ab2d8-e954-5bdf-86ba-1eb1f6f98183', '408c4ede-4468-5bbb-a10c-2f53e828bf0a', '2026-27', 'application', 'RD', 'Regular Decision', '2027-01-15', '2027-03-31', 'Materials deadline Jan 22. Decision released on or before Mar 31.', '18188c2c-ef3f-5e22-adef-5e528cb1fb61');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('408c4ede-4468-5bbb-a10c-2f53e828bf0a', 'required_nonnative', 'Required of first-year applicants educated in non-English-speaking countries unless English was the primary language of instruction in all four years of secondary school. Waiver requests go through the ELP Waiver Request eForm in the Student Center. No superscoring; scores no older than two years; MyBest not accepted.', '944b25a1-ff83-5389-a79a-3b62a075c3c4');
