insert into cost_aid (institution_id, year, tuition_intl_usd, required_fees_usd, other_usd, total_coa_usd, intl_aid_policy, intl_need_aid_awarded, intl_avg_award_usd, meets_full_need, merit_scholarships, notes, source_id) values
 ('cb2a3dbe-19e1-5294-93fc-de79851e7042', '2026-2027', 22247, 2158, 15000, 41663, 'merit_only', 152, 4117, false, true, 'UWM international cost page (2026-27, two semesters): nonresident tuition $22,247 plus segregated and international student fees $2,158; page estimate of $41,663 includes $15,000 living expenses (12 months) and $2,258 international health insurance (12 months). CDS H6 (2024-25 aid): 152 degree-seeking nonresident undergraduates received institutional aid, average $4,117. A $200 International Student Processing Fee is due after admission.; Newly admitted international degree-seeking undergraduates are automatically considered for an academic-merit scholarship of up to $6,000 per academic year ($3,000 per semester), renewable for up to four years; no separate application. CDS H6 also ticks institutional need-based and non-need-based aid for nonresidents, but no international need-based program is described on the CIE page.', '25e8d501-d3c5-5afb-81bf-fd105b053b89');
