insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('7d77439f-974b-5f2b-a913-62dfc85d3075', '2026-27', 'optional', 'The international first-year page says ACT and SAT scores are not required for admission.', '9381ef43-c15e-500e-a8bb-fd9ecac1dbc1');
insert into application_requirements (institution_id, cycle, platforms, notes, source_id) values
 ('7d77439f-974b-5f2b-a913-62dfc85d3075', '2026-27', array['own']::text[], 'Apply with the Universities of Wisconsin Application (apply.wisconsin.edu). Send high school transcripts (official or unofficial; original language plus official English translation) to applyworldwide@uwosh.edu; final official transcripts are needed after graduation. The international page states no application fee amount (the CDS 2023-24 C13 says UW Oshkosh has no application fee). After admission the immigration document application needs a financial verification form, bank statement and passport copy. No minimum GPA is published for international first-year applicants.', '9381ef43-c15e-500e-a8bb-fd9ecac1dbc1');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('9b7c89a0-534c-53fe-9283-9b0b3a57f562', '7d77439f-974b-5f2b-a913-62dfc85d3075', '2026-27', 'application', 'ROLLING', 'International fall term application deadline (fall 2027 entry)', '2027-07-15', 'The international FAQ lists Summer April 15, Fall July 15 and Spring December 1 with no year; taken as fall 2027. The application opens August 1 of the year before. Titan Global Scholars needs no separate application.', '6be14f1a-1238-59d2-ae52-80e85ea9d442');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('7d77439f-974b-5f2b-a913-62dfc85d3075', 'required_nonnative', 'Not required if English is an official language of the applicant''s country of origin (list on the page, e.g. Canada excluding Quebec, UK, Ireland, Nigeria, Ghana, Kenya, South Africa, Philippines, Australia, New Zealand), or after the most recent two semesters or academic year of study in the United States immediately before attending UWO. The FAQ says otherwise the requirement cannot be waived. The page also accepts ACT English 18, SAT evidence-based writing 460, IGCSE English C or higher, British A-Level English C or better, HKDSE English level 4 or higher, WESLI 700 level B or better and Kings Go Prepared level 3 or 4 with 70 percent. No on-campus ESL conditional admission is described on the pages read.', '9381ef43-c15e-500e-a8bb-fd9ecac1dbc1');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
select '7d77439f-974b-5f2b-a913-62dfc85d3075'::uuid, 'required_option', '9381ef43-c15e-500e-a8bb-fd9ecac1dbc1'::uuid, v.* from (values
 ('TOEFL_IBT', 71, 'Table row ''TOEFL iBT (Pre-January 2026)''; undergraduate minimum 71.'),
 ('TOEFL_IBT_2026', 4.0, 'Table row ''TOEFL iBT'' (new scale): 4.0 or higher for undergraduates.'),
 ('IELTS', 6.0, null),
 ('DUOLINGO', 95, null),
 ('PTE', 48, null)) v;
insert into cost_aid (institution_id, year, tuition_usd, tuition_out_of_state_usd, tuition_intl_usd, room_board_usd, books_usd, other_usd, intl_merit_aid, meets_full_need, merit_scholarships, merit_separate_app, notes, source_id) values
 ('7d77439f-974b-5f2b-a913-62dfc85d3075', '2024-2025', 8531, 16213, 16213, 8548, 1200, 2000, true, false, true, false, 'CDS 2023-24 section G1/G5 (2024-25 costs, firm and final): in-state tuition and fees $8,531, out-of-state and international $16,213 per year; on-campus food and housing $8,548; books $1,200; other expenses $2,000 plus $1,500 transportation. College Navigator lists out-of-state tuition and fees of $16,446 for 2024-25. No 2026-27 international cost page could be read, so these are older figures. Titan Global Scholars can cut the nonresident tuition by 50-100 percent.; Titan Global Scholars: all international applicants sponsored for an F-1 or J-1 visa by UW Oshkosh are automatically considered (no separate application). Nonresident tuition discount by cumulative GPA: 3.75-4.00 = 100 percent (Black and Gold Elite), 3.00-3.74 = 75 percent (Advantage), 2.50-2.99 = 50 percent (Access); worth about $16,000 to $32,000+ over four years. Requires full-time degree enrollment (12+ credits) and a 2.5 cumulative GPA to keep it; lasts up to 150 attempted credits. The FAQ also says admitted students get a chance to apply for a need-based scholarship during the immigration application, but no amounts or rules are published, so the international need-aid flag and aid policy are left empty.', 'cd81548c-bdaa-5fe7-87bf-8cccf91815d1');
insert into institution_tiers (institution_id, tier_code, category_key, rationale)
