insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, pct_submit_act, notes, source_id, source_note) values
 ('aa7d3201-e519-5c01-a654-4d078ce4d364', '2023-2024', 5903, 4818, 1063, 39, 'Baseline from IPEDS (fall 2023 entering class; exact counts). UWRF''s Institutional Research page does not list a Common Data Set, so none was used; SAT, GPA, international and residency splits are not added (no SAT percentiles reported). College Navigator for fall 2024 shows 5,519 applicants, 82% admitted (exact count not published there) and ACT composite 19/23/26 for the 19% who submitted; undergraduate enrollment and the 19:1 student-faculty ratio are fall 2024.', '71439e50-4645-5775-b1bd-e58eda73c794', 'admissions_site');
