insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('aa7d3201-e519-5c01-a654-4d078ce4d364', '2026-27', 'optional', 'First-year applicants may include ACT/SAT or apply test-optional; scores are not penalized when omitted and are not required for merit scholarships. Scores are used for the Honors Program (ACT 27+) as one of three alternative criteria.', '3de75b7b-d1f7-58a3-9001-3ad7c8033f62');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('aa7d3201-e519-5c01-a654-4d078ce4d364', '2026-27', array['common_app','own']::text[], 50, 'First-year applicants (Common App or the Universities of Wisconsin application) pay no fee and write no essay. International F-1 applicants use the Universities of Wisconsin application and pay a $50 non-refundable international processing fee. They also submit a passport copy, English proficiency evidence, official final secondary records (certified English translation if needed), a Certification of Finances Form and proof of funds. Letters of recommendation (max two) are only encouraged. Fall 2027 minimum units: 4 English, 3 math, 3 science, 3 social studies, 4 electives.', 'bd340d86-40db-5b8c-9f6c-cb49fc5aebb3');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, notes, source_id) values
 ('7af9a68d-9ee9-5988-a16a-e6fa43afff30', 'aa7d3201-e519-5c01-a654-4d078ce4d364', '2026-27', 'application', 'ROLLING', 'Application (fall 2027 entry), rolling', 'No application deadline is printed on the current first-year or international admissions pages. First-year decisions take about two weeks after review.', '3de75b7b-d1f7-58a3-9001-3ad7c8033f62');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('aa7d3201-e519-5c01-a654-4d078ce4d364', 'required_nonnative', 'Exemptions: native English speaker from an approved English-speaking country (Australia, Canada excl. Quebec, Ireland, New Zealand, South Africa, UK and listed Anglophone Caribbean countries), ENG 100-equivalent transfer credit, or a U.S. high school graduate meeting year/GPA criteria. Other accepted evidence in the undergraduate table: TOEFL Essentials 8, CEFR B2, TOEIC 750, EIKEN Pre-1, IB English A/B HL 4, IGCSE/GCSE/GCE English B, WAEC/KCSE English B, ACT English 18, and SAT EBRW printed as ''950'' (a section score cannot exceed 800, so this entry is unclear). No separate ESL or conditional admission pathway was found on the pages reviewed.', '20839567-dfb9-5852-9a4f-6effca0fb02f');
insert into english_requirements (institution_id, source_id, test_key, status, min_total, notes)
select 'aa7d3201-e519-5c01-a654-4d078ce4d364'::uuid, '20839567-dfb9-5852-9a4f-6effca0fb02f'::uuid, v.* from (values
 ('TOEFL_IBT', 'required_option', 78, 'Exams taken before 2026-01-20 (undergraduate; MyBest accepted per the options sheet).'),
 ('TOEFL_IBT_2026', 'required_option', 4, 'Exams after 2026-01-20 (new 1-6 scale), undergraduate minimum 4.'),
 ('IELTS', 'required_option', 6.0, 'Undergraduate minimum overall 6.0 (graduate 6.5).'),
 ('DUOLINGO', 'required_option', 105, 'Undergraduate minimum 105.'),
 ('PTE', 'required_option', 54, 'Undergraduate minimum 54 (graduate 62).'),
 ('CAMBRIDGE', 'accepted', null, 'Cambridge English exams listed at the B2 level (B2 First / FCE) for undergraduate admission; no numeric score is printed.')) v;
insert into cost_aid (institution_id, year, tuition_usd, tuition_out_of_state_usd, tuition_intl_usd, intl_extra_fees_usd, room_board_usd, merit_scholarships, notes, source_id) values
 ('aa7d3201-e519-5c01-a654-4d078ce4d364', '2026-2027', 9440, 18330, 19748, 2234, 8759, true, 'International Certification of Finances Form 2026-27: tuition and fees $19,748, housing and meals (double room, 21 meals a week) $8,759, required UW international student health insurance $2,234, less $5,120 renewable tuition remission = $25,621 total estimated amount. Tuition rows 9,440 (Wisconsin resident) and 18,330 (other non-resident) are from the tuition page for tuition only (room/meals/total there use a different meal plan).; The 2026-27 international Certification of Finances Form lists a ''Renewable Tuition Remission'' of $5,120 off the first-year estimate (stay full-time with a 2.5 cumulative GPA). Domestic first-year Soar Achievement guaranteed awards are $1,000 (3.3 GPA), $1,500 (3.75) and $2,000 (4.0); the pages do not say whether international students receive them. International students are not eligible for U.S. federal or state aid.', '65c9738e-d7fd-5175-b290-26628e80482e');
