insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, pct_submit_act, notes, source_id, source_note) values
 ('b8f74f7b-c708-50dc-be88-3b1f7cfd18de', '2023-2024', 6440, 5457, 1267, 39, 'Baseline from IPEDS (fall 2023 entering class, ADM2023). UW-Stout''s 2025-26 Common Data Set is linked from uwstout.edu but sits behind a Microsoft SharePoint sign-in and could not be read as text, so CDS figures (international applicants/admits, GPA, SAT/ACT) are not added. IPEDS reports ACT scores only (no SAT) and no residency split. College Navigator also shows fall 2024: 5,547 applicants, 88% admitted, 24% of admits enrolled; about 5% of undergraduates are U.S. nonresidents (fall 2024).', 'bb202e9e-6aa7-5ddb-9344-e1dd9191a9a5', 'admissions_site');
insert into test_score_percentiles (institution_id, cds_year, source_id, test, p25, p50, p75)
select 'b8f74f7b-c708-50dc-be88-3b1f7cfd18de'::uuid, '2023-2024', 'bb202e9e-6aa7-5ddb-9344-e1dd9191a9a5'::uuid, v.* from (values
