insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('0da9a1c7-178e-5fad-a201-bf2a0a9cf302', '2026-27', 'optional', 'The international page says SAT or ACT scores are encouraged but not required for admission.', '0fd3b179-a510-505f-8ee3-6c800d274269');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('0da9a1c7-178e-5fad-a201-bf2a0a9cf302', '2026-27', array['own']::text[], 50, 'Apply with the UW System application. There is no application fee, but a $50 International Admissions Processing Service (IAPS) fee is required after submitting. Needs official (or clear scans of official) secondary records with literal English translations, English proficiency evidence, a financial verification form with bank documents covering the first year, and a passport copy; the written statement is preferred but optional. No minimum GPA is published for international first-year applicants. Decisions take about 2-3 weeks after all documents arrive.', '0fd3b179-a510-505f-8ee3-6c800d274269');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('9d922e15-bbe0-5e8c-b096-b30d2227daaf', '0da9a1c7-178e-5fad-a201-bf2a0a9cf302', '2026-27', 'priority', null, 'Preferred deadline, fall 2027 (international)', '2027-05-01', 'Page prints May 1 as the preferred fall deadline with no year; taken as fall 2027. Spring term: preferred October 1, final November 15. Students in F-1 status in the U.S. are considered after the deadline case by case.', '0fd3b179-a510-505f-8ee3-6c800d274269'),
 ('66d94bef-8aae-534c-9eb8-31e24cb91f0b', '0da9a1c7-178e-5fad-a201-bf2a0a9cf302', '2026-27', 'application', 'ROLLING', 'Final deadline, fall 2027 (international)', '2027-07-01', 'Applications and all required materials must arrive by 11:59 PM Central Time. No year is printed; taken as fall 2027.', '0fd3b179-a510-505f-8ee3-6c800d274269');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('0da9a1c7-178e-5fad-a201-bf2a0a9cf302', 'required_nonnative', 'International applicants educated primarily outside the U.S. must show proficiency, except applicants primarily educated in a listed English-speaking country, three years at a U.S. (or U.S.-accredited) high school with a diploma, or a U.S. degree or two years at a U.S. college. UW-Superior may require evidence from any applicant. Other accepted measures: SAT ERW 470, ACT English 18, MET 69, TOEFL paper 500, iTEP Academic 4.0, Cambridge C1/C2 pass, and partner language programs (ELS level 110, FLS level 16, TLC level 9, WESLI recommendation). Depending on scores, students may take a combination of ESL and non-ESL courses in the first semester. Online undergraduate programs need higher scores (IELTS 6.5, TOEFL 80, Duolingo 115).', '0fd3b179-a510-505f-8ee3-6c800d274269');
