insert into cost_aid (institution_id, year, tuition_intl_usd, room_board_usd, books_usd, other_usd, total_coa_usd, intl_aid_policy, intl_merit_aid, meets_full_need, merit_scholarships, merit_separate_app, notes, source_id) values
 ('0da9a1c7-178e-5fad-a201-bf2a0a9cf302', '2026-2027', 18155, 7945, 1090, 2255, 32385, 'merit_only', true, false, true, false, 'UW-Superior international page, 2026-27 estimate for full-time on-campus students: nonresident tuition and fees $18,155; most affordable double room with a 13-meal plan $7,945 (room_board_usd; the page suggests $1,285 more for extra meals); required health insurance $2,255 (other_usd); books about $1,090; orientation fee $255 once. total_coa_usd is the page''s minimum funding to show for an F-1 visa without a scholarship ($32,385; it also includes personal expenses). With the NTW scholarship the page''s total is $22,710 or $20,510.; Nonresident Tuition Waiver (NTW): automatic for qualifying international degree-seeking undergraduates, no separate application; more than 90 percent of international students receive it. First-year GPA 2.90-3.39 waives $5,900 per year (tuition and fees then $12,255); GPA 3.40+ (NTW Scholar) waives $8,100 per year ($10,055). Renewable up to four years. Separately, two #YouAreWelcomeHere scholarships of $8,400 per year are awarded each fall (GPA 3.5+, separate application, cannot be combined with NTW). No need-based aid for international students is described.', '5c8596ad-99f5-5e09-9fd9-91b46beab23a');
insert into institution_tiers (institution_id, tier_code, category_key, rationale)
select '0da9a1c7-178e-5fad-a201-bf2a0a9cf302'::uuid, 'D', v.* from (values
 ('general', 'Admit rate 93.6%'),
 ('business', 'Editorial judgment (v1, reviewed 2026-10-20)'),
 ('biology_life_sci', 'Editorial judgment (v1, reviewed 2026-10-20)')) v;

