insert into cost_aid (institution_id, year, tuition_usd, tuition_out_of_state_usd, tuition_intl_usd, room_board_usd, books_usd, other_usd, intl_aid_policy, intl_need_aid, meets_full_need, merit_scholarships, notes, source_id) values
 ('7c59415c-611b-5028-b696-dd3e234c6830', '2026-2027', 14002, 45918, 45918, 17631, 900, 3582, 'merit_only', false, false, true, 'Tuition page 2026-27 annual rates (autumn, winter, spring; rates include student fees): resident $14,002, nonresident $45,918 (nonresident covers international students). Housing and food $17,631 (living on or off campus), books $900, personal $2,508 plus transportation $1,074 from the 2026-27 student budget (which still shows 2025-26 tuition of $45,111).; The admissions site says the university does consider international students for merit scholarships, and federal aid is only for U.S. citizens and permanent residents. The Incoming First-Year Merit Scholarship page is written for Washington legal residents, and no international-specific award or amount is published, so confirm eligibility with admissions.', '410248ac-f2b7-5a64-8395-03f6959088ab');
