insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, pct_submit_act, notes, source_id, source_note) values
 ('32827e83-1e8c-5565-8501-40529c72b567', '2023-2024', 11190, 9261, 2217, 73, 'Baseline from IPEDS (fall 2023 entering class); no Common Data Set could be found on the UW-Whitewater site. ACT percentiles are from IPEDS for the 73% of enrolled first-time students who submitted ACT; IPEDS lists no SAT percentiles. College Navigator fall 2024 shows 10,187 applicants and 86% admitted. No GPA, international-applicant or residency splits are available. Undergraduate enrollment (10,084) and the 21:1 student-faculty ratio are from College Navigator, fall 2024.', 'f916896f-68cf-5c97-8b0a-b36a80cdb7ad', 'admissions_site');
insert into test_score_percentiles (institution_id, cds_year, source_id, test, p25, p50, p75)
