insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('32827e83-1e8c-5565-8501-40529c72b567', '2026-27', 'optional', 'The freshman application page lists ACT/SAT scores as optional (ACT code 4684, SAT code 1921). For international applicants, SAT EBRW 430 or ACT English 17 can also satisfy the English proficiency requirement.', '132919ca-7e02-5609-b96f-0e6c48db9200');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('32827e83-1e8c-5565-8501-40529c72b567', '2026-27', array['common_app','own']::text[], 0, 'Apply with the Universities of Wisconsin application or the Common App; the freshman page calls both free. International freshman file: an official credential evaluation of secondary records that includes a GPA, from ECE, WES or OneEarthEvaluation only (other companies not accepted); proof of English; a passport biographical page. Financial documents (bank statement, certification of finance) are needed for the I-20 but not for the admission decision. International students can start only in fall or spring. The page lists minimum units of 4 English, 3 math, 3 natural science, 3 social science and 4 electives and says non-academic factors (leadership, service, talents) are also considered; essays and recommendations are not mentioned.', '64f62093-0c74-593b-b6ce-fe5b3208108a');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('95692b3e-634c-5edb-8378-542b80bedaf1', '32827e83-1e8c-5565-8501-40529c72b567', '2026-27', 'application', 'ROLLING', 'International freshman recommended application and documents date (fall 2027 entry)', '2027-07-01', 'The page says to submit the application and all supporting materials before ''Fall semester start: July 1'' (year not printed; treated as fall 2027). Later applications may be considered depending on time left for visa processing. For comparison, the general freshman page recommends applying before May 1, 2027 and may close applications at capacity.', '64f62093-0c74-593b-b6ce-fe5b3208108a'),
 ('0924c70e-ab0b-5167-81b9-bb5cdaf9be55', '32827e83-1e8c-5565-8501-40529c72b567', '2026-27', 'scholarship', null, 'International Freshman Excellence scholarship: must be admitted by (fall 2027 entry)', '2027-07-01', 'Year not printed; treated as fall 2027. Excellence needs an equivalent GPA of 3.4 or higher.', '64f62093-0c74-593b-b6ce-fe5b3208108a'),
 ('369ca9b1-5681-56b3-a2d3-55ea037d98a2', '32827e83-1e8c-5565-8501-40529c72b567', '2026-27', 'scholarship', null, 'International Freshman Merit and Distinction scholarships: must be admitted by (fall 2027 entry)', '2027-07-15', 'Year not printed; treated as fall 2027. Merit needs an equivalent GPA of 2.5 or higher, Distinction 3.0 or higher.', '64f62093-0c74-593b-b6ce-fe5b3208108a');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('32827e83-1e8c-5565-8501-40529c72b567', 'required_nonnative', 'One score from the accepted list is enough, taken within the 24 months before applying. Met automatically by freshmen who attended and graduated from a US high school for at least two years, by citizens who lived for the two prior years in listed English-speaking countries (e.g. Australia, Canada except Quebec, Ireland, New Zealand, United Kingdom, Jamaica), or with IB English A1/A2 grade 4+. Other accepted options: SAT EBRW 430 and ACT English 17 (freshmen only), EIKEN Pre-1, iTEP 3.7, GTEC 1150, or completing WESLI level 700 coursework with a B or better. The page describes no conditional-admission or pathway program of the university''s own.', '64f62093-0c74-593b-b6ce-fe5b3208108a');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
select '32827e83-1e8c-5565-8501-40529c72b567'::uuid, 'required_option', '64f62093-0c74-593b-b6ce-fe5b3208108a'::uuid, v.* from (values
 ('TOEFL_IBT', 71, 'Listed as ''TOEFL iBT: 4.0 (71 on previous scale)''. ETS institution code 1921.'),
 ('TOEFL_IBT_2026', 4.0, 'The new-scale minimum printed on the page, 4.0 (equal to 71 on the previous 0-120 scale).'),
 ('IELTS', 6.0, 'IELTS Academic, 6.0 overall band; no subscore minimum is printed. A clear scan of your own Test Report Form is accepted.'),
 ('DUOLINGO', 110, 'Duolingo English Test 110.'),
 ('PTE', 48, 'PTE Academic 48. Contact intladmission@uww.edu for how to send PTE and other non-ETS scores.')) v;
insert into score_codes (institution_id, test_key, code, notes, source_id)
select '32827e83-1e8c-5565-8501-40529c72b567'::uuid, v.* from (values
 ('sat', '1921', 'SAT code on the freshman application page; scores are optional.', '132919ca-7e02-5609-b96f-0e6c48db9200'::uuid),
 ('act', '4684', 'ACT code on the freshman application page; scores are optional.', '132919ca-7e02-5609-b96f-0e6c48db9200'::uuid),
 ('toefl', '1921', 'ETS institution code for TOEFL score submission.', '64f62093-0c74-593b-b6ce-fe5b3208108a'::uuid)) v;
insert into cost_aid (institution_id, year, tuition_usd, tuition_out_of_state_usd, tuition_intl_usd, room_board_usd, other_usd, total_coa_usd, merit_scholarships, notes, source_id) values
 ('32827e83-1e8c-5565-8501-40529c72b567', '2026-2027', 9235, 19336, 19756, 8830, 3510, 34276, true, '2026-27 tuition and fees: $9,235 Wisconsin resident, $19,336 nonresident, $19,756 international (international page). The international room-and-food estimate is $8,830. Required UW System international student health insurance adds $2,180 a year, and personal expenses are estimated at $3,510; the $34,276 total (tuition and fees, housing and food, insurance, personal) is the amount the page lists as proof of funds for an I-20.; Automatic-by-GPA international freshman scholarships, renewable for up to 8 semesters: Merit $2,000 per year (equivalent GPA 2.5+), Distinction $4,000 (3.0+), Excellence $6,000 (3.4+). Not open to fully sponsored students. Renewal needs active F-1 status, a 2.5 GPA at UW-Whitewater and involvement in at least three intercultural programs or organizations each semester. A separate $1,000-per-year Business and Computer Science International Student Provost Scholarship goes to international undergraduates in those majors. Whether need-based aid exists for international students is not stated.', '64f62093-0c74-593b-b6ce-fe5b3208108a');
