insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, intl_applicants, intl_admits, in_state_applicants, in_state_admits, out_state_applicants, out_state_admits, pct_submit_sat, pct_submit_act, gpa_avg, pct_reporting_gpa, gpa_distribution, notes, source_id) values
 ('32e2ae27-77ab-517a-9f14-97d4380dc680', '2024-2025', 6267, 4521, 1132, 87, 41, 4320, 3111, 1813, 1334, 31, 13, 3.43, 97.7, '{"4.0": 10.1, "3.75-3.99": 17.7, "3.50-3.74": 19.7, "3.25-3.49": 23.5, "3.00-3.24": 15.9, "2.50-2.99": 10.1, "2.0-2.49": 2.7, "1.0-1.99": 0.2}'::jsonb, 'From VSU''s Fall 2024 Common Data Set (C1, C9, C11). CDS counts differ slightly from IPEDS (6,267 vs 6,253 applicants). Residency split: in-state 4,320, out-of-state 1,813, international 87, unknown 47 applicants; international admits 41 (47% of international applicants vs 72% overall) and 9 enrolled. GPA bands are the ''all enrolled students'' column; 0.1% had a GPA below 1.0. A 2025-2026 CDS PDF is posted but its filled-in values did not extract as text, so the 2024-2025 edition was used. Undergraduate enrollment and student-faculty ratio are IPEDS fall 2024. The CDS marks one importance box per factor with no readable column, so ''factors'' is omitted.', '2c91d800-c294-53c8-9d08-465cf69e61a2');
insert into test_score_percentiles (institution_id, cds_year, source_id, test, p25, p50, p75)
select '32e2ae27-77ab-517a-9f14-97d4380dc680'::uuid, '2024-2025', '2c91d800-c294-53c8-9d08-465cf69e61a2'::uuid, v.* from (values
 ('SAT_TOTAL', 930, 1000, 1108),
 ('SAT_ERW', 480, 520, 570),
 ('SAT_MATH', 440, 490, 530),
 ('ACT_COMPOSITE', 16, 19, 22),
 ('ACT_ENGLISH', 15, 18, 22),
 ('ACT_MATH', 16, 17, 20)) v;
insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('32e2ae27-77ab-517a-9f14-97d4380dc680', '2026-27', 'flexible', 'Applicants with an academic GPA of 3.2 or higher can be admitted without ACT/SAT; those with a GPA of 3.1 or lower should submit official scores. Listed score minimums are SAT EBRW 480 and Math 440, or ACT English or Reading 17 and Math 17; the page also states a Freshman Index minimum of 2040 (500 x HSGPA + SAT EBRW + SAT Math). Required high school curriculum is 17 units (4 English, 4 math, 4 science, 3 social science, 2 foreign language). The international page does not mention ACT/SAT.', '8e6b4fe2-0ee3-5c00-a235-1aadbd61eea5');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('32e2ae27-77ab-517a-9f14-97d4380dc680', '2026-27', array['own']::text[], 40, 'Apply through the VSU application portal (apply.valdosta.edu); the Common App is not mentioned. The FAQ states a $40 application fee. International applicants send sealed official transcripts (non-U.S. coursework evaluated by a NACES member), a Certificate of Finance form (minimum $35,284 for nine months), medical form with immunization proof, a copy of passport and visa, and must buy the VSU medical insurance plan. The international page lists no minimum GPA.', 'fa6361dc-0af8-5179-821c-004e77e54365');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('3d3cd4b8-9501-5d4d-a7b4-5963584d13b5', '32e2ae27-77ab-517a-9f14-97d4380dc680', '2026-27', 'application', 'RD', 'International application deadline (fall 2027)', '2027-04-01', 'International page: fall April 1, spring August 1, summer February 1. Printed without a year; treated as fall 2027. The freshman and FAQ pages print no domestic deadline.', 'fa6361dc-0af8-5179-821c-004e77e54365');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('32e2ae27-77ab-517a-9f14-97d4380dc680', 'required_nonnative', 'Required of non-native speakers. Completing Level 6 of the VSU English Language Institute (ELI) with a B or better in each class lets a student be admitted without TOEFL or IELTS if all other requirements are met; the page does not call this conditional admission. Cambridge IGCSE/O Level English ''D'' or better also counts. Duolingo and SAT/ACT are not listed on the international page, although the TOEFL information page lists SAT 900 combined.', 'fa6361dc-0af8-5179-821c-004e77e54365');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
select '32e2ae27-77ab-517a-9f14-97d4380dc680'::uuid, 'required_option', 'fa6361dc-0af8-5179-821c-004e77e54365'::uuid, v.* from (values
 ('TOEFL_IBT', 69, 'Paper-based 523 also listed. No 1-6 band value given.'),
 ('IELTS', 6.0, null),
 ('PTE', 53, null),
 ('CAMBRIDGE', 169, 'Cambridge English Scale score from B2 First, C1 Advanced or C2 Proficiency (Proficiency 180). Michigan English Test 55 is also accepted.')) v;
insert into score_codes (institution_id, test_key, code, notes, source_id)
select '32e2ae27-77ab-517a-9f14-97d4380dc680'::uuid, v.* from (values
 ('sat', '5855', 'School code given for SAT registration.', '7570b73b-0756-51c1-b8f4-09849c17dcf8'::uuid),
 ('act', null, 'No ACT code is printed on the pages read.', '7570b73b-0756-51c1-b8f4-09849c17dcf8'::uuid),
 ('toefl', '5855', 'Same school code given for TOEFL.', '7570b73b-0756-51c1-b8f4-09849c17dcf8'::uuid),
 ('ielts', null, 'No institution code is listed.', 'fa6361dc-0af8-5179-821c-004e77e54365'::uuid)) v;
insert into cost_aid (institution_id, year, tuition_usd, tuition_out_of_state_usd, tuition_intl_usd, required_fees_usd, room_board_usd, intl_aid_policy, intl_need_aid, meets_full_need, merit_scholarships, notes, source_id) values
 ('32e2ae27-77ab-517a-9f14-97d4380dc680', '2026-2027', 5670, 21300, 21900, 1636, 8718, 'merit_only', false, false, true, 'From the Fall 2026 fee schedule, doubled for two semesters at 15 credit hours: out-of-country tuition $10,950 per semester, mandatory fees $818 per semester ($1,636 per year, matching the CDS). Room and board is the schedule''s minimum housing ($2,701, basic double room) plus the Blazer Weekly 8 meal plan ($1,658) per term; freshmen are listed on the Unlimited or 10-meal plans, so actual cost is higher. International students must buy the VSU health insurance (rate not read). The schedule estimates $33,454 for two semesters including $600 books per term.; The international page says partial out-of-state tuition-waiver scholarships are available on a limited basis; contact the Center for International Programs. No amounts are published on the page read.', '74474387-fc4a-5b72-9a7d-7ec3c995c64b');
