insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('181f6451-d7cc-54ec-9f09-69615eb6b7fb', 'required_nonnative', 'Required if English was not the primary language of instruction in the secondary schools attended for the last three years. TOEFL Essentials and IELTS General Training are not accepted. Duolingo scores must be sent directly from Duolingo. No minimum scores are published. Interviews (InitialView, Vericant) are recommended with TOEFL/IELTS.', '92cfe95c-a209-5379-8ae3-452ddea1dc76');
