insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('8889d13b-a5ef-5323-bc09-9bfd66dc6640', '2026-27', 'optional', 'Test-optional for students entering through Fall 2028; applicants choose whether scores are reviewed and not submitting does not affect the decision. SAT/ACT writing sections are not reviewed. Also optional for international applicants.', '09306949-415e-59a4-b6b9-951cee9d290e');
insert into application_requirements (institution_id, cycle, platforms, supplemental_essays, teacher_recs, counselor_rec, app_fee_usd, notes, source_id) values
 ('8889d13b-a5ef-5323-bc09-9bfd66dc6640', '2026-27', array['common_app']::text[], 'None required; optional Additional Information prompt on Common App.', 0, false, 60, 'Letters of recommendation are not required or requested and are not considered. Self-reported STARS record (or transcripts for students who studied outside the U.S.) due Dec 1 (EA) / Jan 24 (RD). Fee of $60 comes from CDS 2025-26 C13 (last cycle); the 2026-27 fee was not stated on the pages opened. Admission is reviewed by requested major.', '09306949-415e-59a4-b6b9-951cee9d290e');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('77e8d051-f948-502d-a8da-62fdb6b8651d', '8889d13b-a5ef-5323-bc09-9bfd66dc6640', '2026-27', 'application', 'EA', 'Early Action (non-binding), fall 2027', '2026-11-15', 'Notified late February. STARS/transcripts and English test results due Dec 1. Reply due May 1. Virginia Tech has no early decision.', '4de34e20-8458-58e4-bce3-b9cb33d08ee9'),
 ('4cb92b00-c325-5f02-863b-0b9d8b94b01c', '8889d13b-a5ef-5323-bc09-9bfd66dc6640', '2026-27', 'application', 'RD', 'Regular Decision (space available), fall 2027', '2027-01-15', 'Notified mid-March. STARS/transcripts and English test results due Jan 24.', '4de34e20-8458-58e4-bce3-b9cb33d08ee9'),
 ('a1f92b41-c7f9-56cb-9144-165465b81f13', '8889d13b-a5ef-5323-bc09-9bfd66dc6640', '2026-27', 'scholarship', 'RD', 'General Scholarship application and FAFSA deadline', '2027-01-22', 'For maximum scholarship and aid consideration; FAFSA priority date March 1.', '4de34e20-8458-58e4-bce3-b9cb33d08ee9'),
 ('3067c98c-735b-5616-9883-acb483ae192e', '8889d13b-a5ef-5323-bc09-9bfd66dc6640', '2026-27', 'deposit', 'RD', 'Deadline to accept an offer of admission (EA and RD)', '2027-05-01', null, '4de34e20-8458-58e4-bce3-b9cb33d08ee9');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('8889d13b-a5ef-5323-bc09-9bfd66dc6640', 'required_nonnative', 'Waived if the applicant completed four years of study (grades 9-12) in a native English-speaking country (US, UK, Ireland, Australia, NZ, Canada except Quebec, Singapore, Ghana, Kenya, Nigeria, South Africa and others listed), English-only instruction, no ESL. Also met by SAT EBRW 550, ACT English 24, IGCSE/GCSE/GCE English A-C (6-9), or IB English A 5+. Tests must be within two years; MyBest, TOEFL Essentials and ITP not accepted.', '4a0816dc-0959-58c2-b70f-79db33d727df');
