insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('f4125e0a-3041-53dd-a4c4-4e8d97917c73', '2026-27', 'blind', 'WSU does not require SAT/ACT and says it will not use them in admission decisions. International applicants may still submit SAT/ACT (or other tests) only to show English proficiency or for the Undergraduate Foundation placement.', '72711199-bb06-5af0-9169-6c800712e8ce');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('f4125e0a-3041-53dd-a4c4-4e8d97917c73', '2026-27', array['common_app','own']::text[], 70, 'Apply with the WSU application, the Common App (first-year), or Cialfo if your school is a member. International first-year applicants need a minimum 2.70 GPA on a U.S. 4.0 scale as converted by WSU (12 years of schooling with humanities, math, basic sciences and social sciences). Admission is decided from unofficial transcripts; official ones are required before arrival. A passport copy is required. CDS C7: essay is ''considered''; recommendations and tests are not considered.', '666960d1-4f25-54e0-82af-6be254cc8d52');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('c99e4e8b-c183-5cbb-ba88-27c4f491ebd9', 'f4125e0a-3041-53dd-a4c4-4e8d97917c73', '2026-27', 'application', 'ROLLING', 'International fall 2027 application deadline', '2027-06-15', 'International applications are reviewed on a rolling basis; June 15 is the final submission date for fall, with all required documents due July 1, 2027. After the deadline applicants are asked to email international@wsu.edu.', '37896e87-4e15-5376-ba90-3fb0fcb3cfff'),
 ('a6a3ce98-63be-5056-8aef-798ab192739a', 'f4125e0a-3041-53dd-a4c4-4e8d97917c73', '2026-27', 'other', null, 'International deadline for all required documents and response (fall 2027)', '2027-07-01', 'Response = pay the $500 Enrollment and Orientation Fee or request a change of campus; due July 1 or 2 weeks after receiving the offer, whichever is later.', '37896e87-4e15-5376-ba90-3fb0fcb3cfff'),
 ('e39cbe93-61b0-5983-a9c9-02e384d50431', 'f4125e0a-3041-53dd-a4c4-4e8d97917c73', '2026-27', 'priority', null, 'First-year priority admission date (automatic university awards)', '2027-03-31', 'Applying by Mar 31 is needed for automatic university waivers (e.g. UAA); applications after that are accepted on a space-available basis. International applicants are separately guaranteed the International Academic Award on admission.', '7c634bc3-d23c-5923-a815-486e6512fb6b'),
 ('4ef86cd7-360e-552b-a949-7d5507764ebf', 'f4125e0a-3041-53dd-a4c4-4e8d97917c73', '2026-27', 'scholarship', null, 'WSU General Scholarship application priority date', '2027-01-31', 'Also the Top Scholar consideration deadline for first-year students (main admission page). The international page says to submit the general scholarship form by the application deadlines.', '7c634bc3-d23c-5923-a815-486e6512fb6b'),
 ('bb4ed3b3-b68a-5283-928d-a6ce033d1f06', 'f4125e0a-3041-53dd-a4c4-4e8d97917c73', '2026-27', 'deposit', null, 'Admission acceptance priority date ($500 Enrollment and Orientation Fee)', '2027-05-01', 'You may still pay after May 1 but housing choices and space may be limited.', '37896e87-4e15-5376-ba90-3fb0fcb3cfff');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('f4125e0a-3041-53dd-a4c4-4e8d97917c73', 'required_nonnative', 'Waived with 3+ years at a U.S. regionally accredited high school (or one accredited abroad), U.S. college English 101/102 plus 27 credits, 53 college credits, a U.S. associate degree, citizenship of a listed English-speaking country (UK, Ireland, Canada, Australia, New Zealand, Singapore, South Africa, Nigeria, Kenya, Ghana and others on the list), or schooling in English with an official school letter. Scores must be under 2 years old. Applicants below the traditional-admission scores can enter the Undergraduate Foundation program.', '666960d1-4f25-54e0-82af-6be254cc8d52');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
select 'f4125e0a-3041-53dd-a4c4-4e8d97917c73'::uuid, 'required_option', '666960d1-4f25-54e0-82af-6be254cc8d52'::uuid, v.* from (values
 ('TOEFL_IBT_2026', 4.0, 'Traditional admission = 4 (the page lists TOEFL iBT scores on the new 1-6 scale; the old 0-120 equivalent is not published there). Undergraduate Foundation: 3.5 for 1 term, 3 for 2 semesters. TOEFL Essentials 8 also accepted. ETS code 4705.'),
 ('IELTS', 6.5, 'Traditional admission 6.5. Undergraduate Foundation: 6 for 1 term, 5.5 for 2 semesters/1 year.'),
 ('DUOLINGO', 105, 'Traditional admission 105. Undergraduate Foundation: 95 for 1 term, 85 for 2 semesters/1 year.'),
 ('PTE', 58, 'Pearson PTE Academic: traditional admission 58. Undergraduate Foundation: 47 for 1 term, 44 for 2 semesters/1 year.'),
 ('CAMBRIDGE', null, 'Traditional admission = C1 Advanced. Undergraduate Foundation: B2 First (1 term or 2 semesters). The page names grades rather than numeric scores.')) v;
insert into score_codes (institution_id, source_id, test_key, code, notes)
select 'f4125e0a-3041-53dd-a4c4-4e8d97917c73'::uuid, '666960d1-4f25-54e0-82af-6be254cc8d52'::uuid, v.* from (values
 ('sat', null, 'WSU does not use SAT/ACT in admission; SAT EBRW 500 / ACT English 17 and Reading 19 can serve as English proficiency evidence only. No SAT code is published on the international pages.'),
 ('act', null, 'No ACT code is published on the international pages.'),
 ('toefl', '4705', 'School code for TOEFL score reports.'),
 ('ielts', null, 'No code; ask your test center to send results to International Undergraduate Admissions (international@wsu.edu), or send electronically.'),
 ('duolingo', null, 'Select Washington State University and level Undergraduate when sending results from your Duolingo account.'),
 ('pte', null, 'No institution code is listed.')) v;
insert into cost_aid (institution_id, year, tuition_usd, tuition_out_of_state_usd, tuition_intl_usd, required_fees_usd, room_board_usd, books_usd, other_usd, total_coa_usd, intl_aid_policy, intl_need_aid, intl_need_aid_awarded, intl_avg_award_usd, meets_full_need, merit_scholarships, notes, source_id) values
 ('f4125e0a-3041-53dd-a4c4-4e8d97917c73', '2026-2027', 12063, 29734, 29734, 2298, 15245, 900, 3684, 59207, 'merit_only', false, 216, 10094, false, true, 'CDS G1/G5 (2026-27): tuition and fees from the CDS; other = transportation $1,716 plus personal $1,968. total_coa_usd is WSU International Programs'' estimate for an international undergraduate for fall plus spring (tuition and fees $33,087, books $900, medical insurance $4,290, living $17,246, other $3,684; page does not name the year). CDS H6: only institutional non-need-based aid is available to nonresidents; 216 nonresident undergraduates received it (avg $10,094).; International students are automatically considered for scholarships on admission. The International Academic Award is guaranteed to high-achieving first-year admits: $4,000 per year tuition waiver for GPA 3.60+ or $2,000 per year for GPA 3.0-3.59, renewable 3 more years (3.0 GPA, 12 credits a term). Students who finish the Undergraduate Foundation program with a 3.5 GPA get a $4,000 per year Year One Progression Award instead. A $2,000-per-semester International Merit Award is available after enrolling. CDS H6: only non-need-based institutional aid for nonresidents.', '944fc8db-66e4-5279-8679-6aa534a28137');
