select '4bc510cd-fb37-5e33-85d5-fec61f03d70f'::uuid, '2025-2026', 'aaf45be6-8b85-5859-b2c2-d31108a205af'::uuid, v.* from (values
 ('SAT_TOTAL', 1180, 1300, 1390),
