 ('SAT_MATH', 590, 650, 700),
 ('ACT_COMPOSITE', 25.75, 30, 33)) v;
insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('4bc510cd-fb37-5e33-85d5-fec61f03d70f', '2026-27', 'optional', 'Test-optional since 2018. International students need not submit SAT/ACT but must prove English proficiency. Merit scholarship eligibility does not depend on submitting scores. Home-schooled applicants and applicants from schools with narrative assessments instead of 4.0 grades are excluded from the test-optional policy.', 'f4b0c162-6b4c-535b-8765-88216a975da0');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('4bc510cd-fb37-5e33-85d5-fec61f03d70f', '2026-27', array['common_app','own']::text[], 50, 'Common Application or the Wentworth application; $50 fee (waivable for financial need per CDS). Applicants apply to a specific major. Official transcript sent directly from the school (Naviance/Parchment accepted); up to two recommendation letters are optional; no portfolio required for first-year applicants, including architecture and design majors. Prerequisites: four years of English, Algebra II and one lab science (CDS: 9 required units). Optional one-on-one interview for international applicants. A bank letter showing funds of USD $71,382 is required for the I-20, not for admission.', 'f1c62483-0f7a-5848-9af9-0706066902b3');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('d85ee888-6049-5602-91d0-578d9cf4fb44', '4bc510cd-fb37-5e33-85d5-fec61f03d70f', '2026-27', 'application', 'ED', 'Early Decision, fall 2027 entry', '2026-11-01', 'Notification by early December; enrollment deposit by May 1. The 2025-26 CDS answered No to an early decision plan, but the current admissions pages list this round. Pages print no year; taken as fall 2027 entry.', '60a985ec-8361-5e3a-a69d-ebd9dedc979e'),
 ('bbda32db-7778-5860-bf5f-c24a5b87d65c', '4bc510cd-fb37-5e33-85d5-fec61f03d70f', '2026-27', 'application', 'EA', 'Early Action round 1', '2026-11-15', 'Notified by mid-December. Early application scholarship ($2,000) is awarded to students applying by ED (Nov 1), EA1 (Nov 15) or EA2 (Jan 1). No year is printed; taken as fall 2027 entry.', '60a985ec-8361-5e3a-a69d-ebd9dedc979e'),
 ('a5d436ed-25de-5c94-b6ca-0f01d69fd49d', '4bc510cd-fb37-5e33-85d5-fec61f03d70f', '2026-27', 'application', 'EA', 'Early Action round 2', '2027-01-01', 'Notified by mid-February.', '60a985ec-8361-5e3a-a69d-ebd9dedc979e'),
 ('d7760f03-6abe-5fd7-93de-dc039e725446', '4bc510cd-fb37-5e33-85d5-fec61f03d70f', '2026-27', 'application', 'RD', 'Regular Decision', '2027-02-01', 'Notified by April 1; enroll by May 1. The international undergraduate page lists no separate international deadlines, so the first-year dates apply.', 'f4b0c162-6b4c-535b-8765-88216a975da0'),
 ('6b88fde2-6fdd-5727-9aed-66e02b119a35', '4bc510cd-fb37-5e33-85d5-fec61f03d70f', '2026-27', 'financial_aid', null, 'International need-based aid application: ED, EA1, EA2 applicants', '2027-02-01', 'Must be submitted before the admission decision. Limited International Grant for admitted international students.', 'f1c62483-0f7a-5848-9af9-0706066902b3'),
 ('1288174d-6a5d-5967-a5a6-487f9d549ecb', '4bc510cd-fb37-5e33-85d5-fec61f03d70f', '2026-27', 'financial_aid', null, 'International need-based aid application: Regular Decision applicants', '2027-03-01', null, 'f1c62483-0f7a-5848-9af9-0706066902b3');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('4bc510cd-fb37-5e33-85d5-fec61f03d70f', 'required_nonnative', 'Exempt: secondary education in a listed English-speaking country (or a bachelor''s degree from one); 3+ years of college-prep English at an English-language high school; C or higher in English I and II at a U.S. college; SAT EBRW 525+ (code 3958) or ACT reading 18 and English 20 (code 1928). Intensive English alternative: completion of listed ESL levels (Approach ISC B2, ASC English Level 5, BU CELOP, EF, ELS, FLS) with a letter from the center director or teacher. TOEFL, IELTS and DET scores are valid for two years.', '53f89cee-598f-5d66-a621-7fa9fc85d19f');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, min_subscores, notes)
select '4bc510cd-fb37-5e33-85d5-fec61f03d70f'::uuid, 'required_option', '53f89cee-598f-5d66-a621-7fa9fc85d19f'::uuid, v.* from (values
 ('TOEFL_IBT', 79, '{"each_section": 17}'::jsonb, 'Tests taken on or before Jan 20, 2026; no subsection below 17. ETS code 3958.'),
 ('TOEFL_IBT_2026', 4, '{"each_section": 4}'::jsonb, 'Tests taken on or after Jan 21, 2026; page prints 4 with no subsection lower than 4 without naming the scale (it is the 1-6 scale).'),
 ('IELTS', 6.5, '{"each_section": 5.5}'::jsonb, 'IELTS Academic; no subscore below 5.5.'),
 ('DUOLINGO', 105, null, null),
 ('PTE', 58, null, 'PTE Academic or PTE Express.')) v;
insert into score_codes (institution_id, test_key, code, notes, source_id)
