 ('sat', '3958', 'Wentworth school code (also its TOEFL code).', '53f89cee-598f-5d66-a621-7fa9fc85d19f'::uuid),
 ('act', '1928', 'Wentworth ACT code.', '53f89cee-598f-5d66-a621-7fa9fc85d19f'::uuid),
 ('toefl', '3958', 'ETS school code; send scores directly via ETS.', '53f89cee-598f-5d66-a621-7fa9fc85d19f'::uuid),
 ('ielts', null, 'No institution code is listed; official results must be sent to the school.', 'f1c62483-0f7a-5848-9af9-0706066902b3'::uuid),
 ('duolingo', null, 'No institution code is listed.', '53f89cee-598f-5d66-a621-7fa9fc85d19f'::uuid),
