insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, pct_submit_sat, pct_submit_act, notes, source_id, source_note) values
 ('844babaf-ef1f-55cd-a85e-81d8baa2f4e7', '2024-2025', 2729, 1164, 389, 3, 61, 'Baseline from IPEDS fall 2024 (exact counts from the NCES ADM2024 file via the Urban Institute Education Data Portal; percentages and percentiles from College Navigator). No Common Data Set was found on UWA''s site (the Institutional Effectiveness pages link none), so international applicants/admits, GPA, SAT total and admission factors are not included. SAT/ACT percentiles cover enrolled first-time students who submitted scores (SAT 3%, ACT 61%); the SAT figures rest on very few students. The 43% admit rate is as IPEDS reports it; UWA''s published minimums are low (ACT 17, SAT 920 or 2.5 GPA), so the counting of applicants may differ from other schools.', '2ecf1943-cfbb-504c-8997-c32035e6cc84', 'admissions_site');
insert into test_score_percentiles (institution_id, cds_year, source_id, test, p25, p50, p75)
