insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('6fa831fb-9732-5279-8ee8-b2c388a146fb', '2026-27', 'optional', 'CDS C8A (Fall 2027): SAT or ACT ''not required for admission, but considered if submitted''. The international freshman page lists no SAT/ACT requirement; ACT English 21 or SAT EBRW 560 can be used as English proficiency (freshmen only).', '5d890b0c-e948-5077-a764-cac1fd93f69e');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, fee_waiver, notes, source_id) values
 ('6fa831fb-9732-5279-8ee8-b2c388a146fb', '2026-27', array['own']::text[], 90, false, 'Apply through the WTAMU applicant portal; non-refundable international application fee $90, no fee waivers. Needed: high school transcript and completion certificate (unofficial copies accepted at the admission stage, official copies if admitted), a foreign credential evaluation report sent directly by the agency (student-submitted evaluations are not accepted), proof of English proficiency, and a minimum U.S.-equivalent GPA of 2.0/4.0. Non-English documents need a certified English translation. Financial verification (and an affidavit of support if needed) is uploaded after admission, for F-1 applicants only.', '464a7134-d0a5-5c19-a0a9-38a0b4874907');
insert into deadlines (id, institution_id, cycle, kind, label, due_date, notes, source_id) values
 ('9f5967a1-3cf2-57b6-ad46-a595bf9e7091', '6fa831fb-9732-5279-8ee8-b2c388a146fb', '2026-27', 'application', 'Application submission deadline, fall 2027', '2027-06-15', 'Dates are printed without a year; treated as fall 2027. Application fee payment is due July 1. Spring entry: application Nov. 1; summer: May 1 (no I-20s are issued for summer terms). No priority or final dates are listed.', '9d033c6e-9d61-5e44-9a9b-31bd5054078a'),
 ('3e39caf9-b824-5ace-815a-1bbe6acd05f8', '6fa831fb-9732-5279-8ee8-b2c388a146fb', '2026-27', 'other', 'Document and I-20 document submission deadline, fall 2027', '2027-07-15', 'All supporting documents and the I-20 documents are due July 15.', '9d033c6e-9d61-5e44-9a9b-31bd5054078a'),
 ('d86041b3-f410-54e3-9dcb-0d2dd1d80585', '6fa831fb-9732-5279-8ee8-b2c388a146fb', '2026-27', 'other', 'Last day I-20s are issued for fall 2027', '2027-08-01', 'Printed as ''Last Day I-20s Will Be Issued: August 1st''.', '9d033c6e-9d61-5e44-9a9b-31bd5054078a');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('6fa831fb-9732-5279-8ee8-b2c388a146fb', 'required_nonnative', 'Citizens of Australia, Canada (except Quebec), Ireland, Liberia, Nigeria, New Zealand, the United Kingdom, the United States, Ghana and listed Commonwealth Caribbean countries are exempt; applicants educated in those countries may be exempt after transcript review. If the language of instruction at the current or most recent school was entirely English, the registrar can send a letter saying so. Scores must come directly from the testing agency and are valid for 2 years. TOEFL Essentials and MyBest scores and IELTS One Skill Retake are not accepted. Freshmen may also use ACT English 21 or SAT EBRW 560. The pages describe no conditional admission or ESL pathway.', '339ccbc8-13c8-55b1-b980-8add4b8546fd');
insert into english_requirements (institution_id, source_id, test_key, status, min_total, notes)
