insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, pct_submit_sat, pct_submit_act, notes, source_id, source_note) values
 ('8d9059ef-9d53-570b-8f98-cc677f0baf84', '2024-2025', 6163, 5914, 326, 2, 2, 'Baseline from IPEDS fall 2024 (exact counts from the NCES ADM2024 file via the Urban Institute Education Data Portal; nonresident-alien undergraduates from NCES IPEDS fall 2024 enrollment by race (same portal)). No Common Data Set could be found online, so international applicants/admits, GPA and admission factors are not included. SAT/ACT ranges cover enrolled first-time students who submitted scores (SAT 6 students, ACT 6 students), so they rest on very few students. Undergraduate enrollment 3,110 and 4 nonresident-alien undergraduates are IPEDS fall 2024; College Navigator prints the student-to-faculty ratio as 13 to 1.', '86d1f01f-c260-5cff-a6b9-9436890d16ea', 'admissions_site');
insert into test_score_percentiles (institution_id, cds_year, source_id, test, p25, p50, p75)
