insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('490cfaec-cd3c-550a-ad1b-b32e8b9dee6a', '2026-27', 'optional', 'For students entering fall 2025 or spring 2026, a standardized test score (SAT or ACT) is required only when the weighted high school GPA is below 2.80; otherwise it is optional. The page does not restate this for fall 2027. International students who graduate from a US high school must take the SAT or ACT (minimums SAT 880, ACT 18).', 'e6ea661b-6a51-5d94-8041-c20b2a43f746');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('490cfaec-cd3c-550a-ad1b-b32e8b9dee6a', '2026-27', array['own']::text[], 65, 'Application fee $65 per CDS 2025-2026 C13 (the international page gives no separate rate; fee waivers need third-party verified financial need). Minimum course requirements: 4 English, 2 social studies, 4 math, 3 science, 2 other academic units. Required: international transcript evaluation by a NACES member (except US-school transcripts), official transcripts, English proof. Essays are not required of all applicants. Common App use not confirmed on the pages read.', 'e6ea661b-6a51-5d94-8041-c20b2a43f746');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('96b143f2-59f2-59d5-ba95-131404e88fd6', '490cfaec-cd3c-550a-ad1b-b32e8b9dee6a', '2026-27', 'application', 'RD', 'International freshman application deadline, fall 2027', '2027-02-01', 'Page prints no year; treated as fall 2027. Applies to the application plus official test scores and transcripts. WCU makes many decisions after its Jan. 1 and Feb. 1 regular deadlines, so apply well before Feb. 1. Spring entry: Oct. 1 (all applicants). The WCU early-college page lists April 1 for international freshmen, which conflicts with the main international page.', '2f1f5733-6187-564e-83cc-184d4e6223a3');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('490cfaec-cd3c-550a-ad1b-b32e8b9dee6a', 'required_nonnative', 'All international students must show English proficiency unless they come from a listed English-primary country, completed the IB diploma, completed high school or higher education in an English-medium institution (the school must send a letter to WCU), or finished 24+ credit hours at a US college.', '2f1f5733-6187-564e-83cc-184d4e6223a3');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, min_subscores, notes)
