insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('f750efff-5353-5499-bf9c-cc6e8797a8f1', '2026-27', 'optional', 'CDS C8: SAT/ACT not required for admission if the unweighted high school GPA is 2.50 or higher (encouraged for placement); 2.00-2.49 requires a test and a Composite Admission Index of at least 60 (Summer Scholars Program). International freshmen need a 2.5 GPA (converted to a 4-point scale) and each application is reviewed case by case. An SAT EBRW of 460 is one accepted proof of English proficiency.', '3b1da309-670a-5bf0-aa49-2ae258cafea2');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('f750efff-5353-5499-bf9c-cc6e8797a8f1', '2026-27', array['own']::text[], 75, 'International application fee is a $75 non-refundable fee (domestic fee is $50 per CDS C13). Required: online application, official academic records from every school (literal English translation if not in English), English proficiency proof, and financial documentation (one year of funds, bank statement; affidavit of support if the account belongs to someone else) for the I-20. Common App use is not confirmed on the pages read.', '49e54279-97d0-5d7f-805f-84aefd9ea11a');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('7a352155-2df0-5236-989d-81669d48e5e4', 'f750efff-5353-5499-bf9c-cc6e8797a8f1', '2026-27', 'application', 'ROLLING', 'Application closing date (fall 2027 entry)', '2027-08-01', 'CDS C14 prints ''Aug 1'' with no year; treated as fall 2027. WKU admits on a rolling basis. For international applicants all documents, English proof, financial proof and the fee must arrive before a decision is made; the international page asks for them by December 14 to be processed before the winter-break closure (Dec. 18 to Jan. 4), which is a processing cutoff, not an admission deadline. No separate international fall deadline is published.', '3b1da309-670a-5bf0-aa49-2ae258cafea2');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('f750efff-5353-5499-bf9c-cc6e8797a8f1', 'required_nonnative', 'Applicants from non-English-speaking countries must meet one of the listed options; scores must be within two years of application (undergraduate catalog). Accepted alternatives to a test: SAT EBRW 460 (or Critical Reading 450 before March 2016), ELS Language Center Level 109 or higher, or completing the ESLi program at WKU. Nursing requires higher scores than other programs (thresholds not on the page). Conditional pathway: WKU''s International Pathway to Academic Success (IPAS) admits students with lower English scores and a 2.25 GPA, at no additional cost. Pathways minimums: TOEFL iBT 61-70, IELTS 5.5, PTE 45-51, Duolingo 90 (a 100 Duolingo is needed for the one-semester pathway and 90 for the two-semester pathway).', '0bc09fd1-441a-5860-8c89-4d0256a6e130');
insert into english_requirements (institution_id, status, test_key, min_total, notes, source_id)
select 'f750efff-5353-5499-bf9c-cc6e8797a8f1'::uuid, 'required_option', v.* from (values
 ('TOEFL_IBT', 71, 'Direct admission minimum 71 (paper 525, computer 197). IPAS pathway: 61-70. No 1-6 scale value is given; the English page was last modified 8/30/22.', '0bc09fd1-441a-5860-8c89-4d0256a6e130'::uuid),
 ('IELTS', 6.0, 'Direct admission 6.0; IPAS pathway 5.5.', '0bc09fd1-441a-5860-8c89-4d0256a6e130'::uuid),
 ('DUOLINGO', 100, 'Direct admission 100; IPAS pathway 90 (two-semester) or 100 (one-semester).', '49e54279-97d0-5d7f-805f-84aefd9ea11a'::uuid),
 ('PTE', 52, 'PTE Academic 52 for direct admission; IPAS pathway 45-51.', '0bc09fd1-441a-5860-8c89-4d0256a6e130'::uuid)) v;
