insert into major_admissions (id, institution_id, program, category_key, admit_model, notes) values
 ('e2aefb43-7811-5cae-b124-4936513ca495', 'f750efff-5353-5499-bf9c-cc6e8797a8f1', 'Nursing, Bachelor of Science in Nursing (BSN)', 'nursing', 'pre_major_competitive', 'BSN admission is competitive and needs a separate application after admission to WKU (fall deadline Feb. 1, spring Sept. 1; HESI entrance exam; minimum 3.0 GPA for students admitted fall 2024 or later). Guaranteed Nursing Admission exists for first-time full-time freshmen with a 3.6 GPA or ACT 23 / SAT 1130.');

