insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('98e9cab9-81a4-5cde-a912-c263d89f7f42', '2026-27', 'optional', 'WMU''s CDS says SAT/ACT scores will only be used if they benefit a student and students will not be penalized for them. The international page lists no SAT/ACT requirement; SAT EBRW 500 can be used to meet the English requirement.', '0da89cb9-2457-581c-b852-a87f5695468d');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('98e9cab9-81a4-5cde-a912-c263d89f7f42', '2026-27', array['own']::text[], 100, 'International undergraduates apply through WMU''s own application and pay a non-refundable $100 fee (CDS C13 lists $40 for domestic applicants). Unofficial transcripts are enough for the decision; official ones are due by the end of the first semester. A passport identification page is required. Some colleges (Business, Engineering and Applied Sciences) charge additional tuition and fees.', 'ddfd588c-c1b6-5c0d-b6e4-10b3217ff428');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('b8403776-d5b1-5498-99e8-99f97ff85940', '98e9cab9-81a4-5cde-a912-c263d89f7f42', '2026-27', 'application', 'ROLLING', 'International undergraduate fall deadline (fall 2027)', '2027-06-01', 'Spring deadline is Sept 1 and summer is Feb 1. WMU says many programs admit on a rolling basis and late applications may still be processed but admission for the desired term is not guaranteed. The page gives month/day only; the year is assumed for fall 2027.', 'ddfd588c-c1b6-5c0d-b6e4-10b3217ff428');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('98e9cab9-81a4-5cde-a912-c263d89f7f42', 'required_nonnative', 'No proof of English is needed after four years of upper secondary school or one year of full-time university study in a listed English-speaking country (for some countries only in an English-language system). Other routes: IB English HL grade 5, IGCSE English A-C, Cambridge Advanced A-C, ELS level 112, SAT EBRW 500, WMU Pathway II or the CELCIS English program. Tests must be taken within two years of applying. Students below the minimum can start in WMU''s Center for English Language and Culture for International Students (CELCIS). Aviation Flight Science needs higher scores.', '0da89cb9-2457-581c-b852-a87f5695468d');
insert into english_requirements (institution_id, source_id, test_key, status, min_total, notes)
select '98e9cab9-81a4-5cde-a912-c263d89f7f42'::uuid, '0da89cb9-2457-581c-b852-a87f5695468d'::uuid, v.* from (values
 ('TOEFL_IBT', 'required_option', 71, 'Aviation Flight Science: 91. TOEFL Essentials 7 (Aviation 9) also accepted.'),
 ('TOEFL_IBT_2026', 'required_option', 4, 'Exams from 2026 on; Aviation Flight Science 4.5. The page lists these values without naming the 1-6 scale.'),
 ('IELTS', 'required_option', 6.0, 'IELTS Academic; Aviation Flight Science 7.0.'),
 ('DUOLINGO', 'required_option', 100, 'Aviation Flight Science 115.'),
 ('PTE', 'required_option', 48, 'PTE Academic and Pearson English Express; Aviation Flight Science 64. Michigan English Test also accepted (48; Aviation 64).'),
 ('CAMBRIDGE', 'accepted', null, 'Cambridge Advanced English Certificate with grade A, B or C; no numeric score given.')) v;
