insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, pct_submit_sat, notes, source_id, source_note) values
 ('db235192-8215-58cd-90b1-998dfb2136c2', '2024-2025', 9165, 8256, 1037, 0, 'Baseline from IPEDS fall 2024 (exact counts from the NCES ADM2024 file via the Urban Institute Education Data Portal; College Navigator shows 90% admitted and 13% of admits enrolled). No usable Common Data Set: the university''s CDS page lists nothing newer than 2021-22, so GPA, international applicants/admits and factors are not recorded. IPEDS shows only 2 enrolled first-years (0%) submitting SAT, so SAT/ACT percentiles are not published; William Paterson is test-optional. Undergraduate enrollment 6,647 and 172 nonresident-alien undergraduates are IPEDS fall 2024 (College Navigator and Urban Institute Education Data Portal).', 'bb8438d4-84ce-5dff-a8af-1a43a99e35a5', 'admissions_site');
insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('db235192-8215-58cd-90b1-998dfb2136c2', '2026-27', 'optional', 'Official SAT/ACT scores are optional for international freshmen. Scores can help for BSN Nursing (a 3.0 GPA with SAT 1130 and EBRW 550, versus a 3.5 GPA test-optional), merit scholarships and University Honors College admission.', 'bc9d995f-6609-5c24-86e8-e3c936ffe875');
insert into application_requirements (institution_id, cycle, platforms, portfolio, app_fee_usd, notes, source_id) values
 ('db235192-8215-58cd-90b1-998dfb2136c2', '2026-27', array['own']::text[], 'Fine/studio art majors submit a digital portfolio after applying; music majors must audition (online upload for most programs, in person for classical performance).', 50, 'Application fee $50 is the IPEDS 2024-25 figure (not restated on the pages reviewed). International applicants email secondary transcripts and diplomas (with notarized English translations) to international@wpunj.edu; the office converts foreign grades. Personal statement, resume and recommendation letters are optional unless the major requires them. Required high school units: English 4, math 3, lab science 2, social science 2, plus 5 additional. All new students take placement tests in reading, writing and math. The Common App was not confirmed on the pages reviewed.', 'bc9d995f-6609-5c24-86e8-e3c936ffe875');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('923f08a4-5ca0-516d-94eb-b6967f80ae0f', 'db235192-8215-58cd-90b1-998dfb2136c2', '2026-27', 'priority', null, 'Priority deadline for Nursing (BSN), fall 2027 entry', '2026-12-01', 'Nursing applications completed after Dec. 1 are considered on a rolling basis until capacity. Pages print no year; taken as fall 2027 entry.', 'f324e396-0170-5c86-ab32-db90867c71fa'),
 ('5f74b7e3-c7c2-5f39-82a6-a693e53322dc', 'db235192-8215-58cd-90b1-998dfb2136c2', '2026-27', 'scholarship', null, 'Merit scholarship consideration (fall 2027 entry)', '2027-01-01', 'The international freshman page says Jan. 1; the international Deadlines page says ''February 1 - Merit Scholarship package deadline''. The earlier date is used here to be safe. No year is printed; taken as 2027.', 'bc9d995f-6609-5c24-86e8-e3c936ffe875'),
 ('1ec0f922-8d31-50fa-8122-79d0dee79fc1', 'db235192-8215-58cd-90b1-998dfb2136c2', '2026-27', 'other', null, 'University Honors College consideration (fall 2027 entry)', '2027-03-01', null, 'f324e396-0170-5c86-ab32-db90867c71fa'),
 ('033d981b-c164-571d-b367-4aa4c9e6ad7a', 'db235192-8215-58cd-90b1-998dfb2136c2', '2026-27', 'application', 'ROLLING', 'Regular deadline for fall 2027 admission', '2027-06-01', 'Freshman decisions are rolling; applications after June 1 are still handled on a rolling basis. Pages print no year; taken as fall 2027. Spring regular deadline is Dec. 1.', 'f324e396-0170-5c86-ab32-db90867c71fa');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('db235192-8215-58cd-90b1-998dfb2136c2', 'required_nonnative', 'Waived for U.S. citizens and permanent residents, citizens of the listed English-proficiency waiver countries, graduates (or students) of high schools in the U.S. or those countries, and students of international schools following those systems. An English-medium-of-instruction letter on school letterhead with signature and seal is accepted for up to five years. All new students take placement tests, and non-credit remedial English may be assigned. The page describes no separate ESL or conditional-admission pathway.', 'bc9d995f-6609-5c24-86e8-e3c936ffe875');
