insert into cost_aid (institution_id, year, tuition_usd, tuition_out_of_state_usd, tuition_intl_usd, required_fees_usd, intl_aid_policy, meets_full_need, merit_scholarships, notes, source_id) values
 ('db235192-8215-58cd-90b1-998dfb2136c2', '2026-2027', 16758, 27384, 27384, 566, 'merit_only', false, true, 'Student Accounts 2026-27 full-time (12-19 credits) per semester: tuition $8,379 in-state and $13,692 out-of-state, plus $178 technology and $105 student government fees; annual figures are two semesters. International students pay the out-of-state rate before the Pioneer Award (about $8,500 off for undergraduates in 2026-27). Housing and board for 2026-27 were not found; IPEDS 2024-25 lists on-campus food and housing $16,240 and books $1,600.; The Pioneer Award gives new main-campus international students an 80% discount on the difference between in-state and out-of-state tuition (about $8,500 for 2026-27, estimated; automatic, no application; renewable with full-time enrollment and a 2.0 GPA; needs a valid F-1/J-1 visa). The university also awards close to 2,000 merit scholarships a year to freshmen and transfers, and all admitted students are generally considered automatically, but no international-specific merit amounts are published. FAFSA applies to U.S. aid-eligible students only.', 'bfec626c-be1d-597a-bfbd-1375d4922672');
