insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('7e3e1d53-3af2-5072-94b1-18ac2faff41a', '2026-27', 'optional', 'Wingate advertises ''test score optional''. The recommended application items are a self-reported GPA and an SAT, ACT or CLT score; applicants who cannot provide a score are asked for a 250-word personal essay instead. The international page says to submit official test scores ''if applicable''.', '344e4773-594e-53a5-8565-e0f33aa3b371');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('7e3e1d53-3af2-5072-94b1-18ac2faff41a', '2026-27', array['common_app','own']::text[], 0, 'No application fee. International applicants also email a passport copy and have a school official send the official high school transcript to internationaladmissions@wingate.edu. After admission: $100 non-refundable international processing fee, then a $2,500 enrollment and tuition deposit ($300 enrollment + $2,200 tuition deposit) before the I-20 is issued. Decision within two weeks of a complete file. Applicants must be at least 17 by the first day of class.', '9829de7d-3be0-5ca0-885b-d244f8a7b5c8');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('9bffc9a1-c0c4-5134-bf62-ee10b925e6f7', '7e3e1d53-3af2-5072-94b1-18ac2faff41a', '2026-27', 'application', 'ROLLING', 'International application deadline, fall 2027 entry', '2027-06-01', 'Page gives ''fall semester applications must be received no later than June 1'' with no year; taken as 2027 for fall 2027 entry. Spring applications by Nov 1. Domestic first-year admission is rolling with no deadline.', '9829de7d-3be0-5ca0-885b-d244f8a7b5c8'),
 ('bebdee60-9906-5146-9ca3-b9e540915a13', '7e3e1d53-3af2-5072-94b1-18ac2faff41a', '2026-27', 'other', null, 'Recommended deadline for all I-20 documents (fall entry)', '2027-07-01', 'Wingate recommends all I-20 documentation be submitted by July 1 for fall (Nov 1 for spring). Year not printed; taken as 2027.', '9829de7d-3be0-5ca0-885b-d244f8a7b5c8');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('7e3e1d53-3af2-5072-94b1-18ac2faff41a', 'required_nonnative', 'English proficiency is required before the I-20 is issued rather than for the admission decision. Exempt: citizens of listed English-speaking countries; 3+ years at a high school (international or American) taught in English with a school letter or transcript; or 24 transferable US college hours with a C or better in English composition. Otherwise any one of: SAT EBRW 450, ACT Reading and English 17 each, ELS level 112, ELTI (UNC Charlotte) level 6, or the test scores listed. Scores must be under 24 months old.', '9829de7d-3be0-5ca0-885b-d244f8a7b5c8');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
select '7e3e1d53-3af2-5072-94b1-18ac2faff41a'::uuid, 'required_option', '9829de7d-3be0-5ca0-885b-d244f8a7b5c8'::uuid, v.* from (values
 ('TOEFL_IBT', 70, 'The English Proficiency section lists ''TOEFL iBT 70''.'),
 ('TOEFL_IBT_2026', 4, 'The Student Visa Information section of the same page lists ''TOEFL iBT score of 4''; the page does not name the 1-6 scale, but 4 cannot be on the 0-120 scale.'),
 ('IELTS', 5.5, 'Academic module.'),
 ('DUOLINGO', 100, null)) v;
