insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('7c85ddd8-639a-5e71-b21a-2b1f88888ed4', '2026-27', 'optional', 'ACT and SAT are not required for admission. First-year applicants with a cumulative high school GPA of 3.0 or higher (4.0 scale) are guaranteed admission once the required courses (4 English, 3 math, 3 science, 3 social studies, 1 elective) are done; others are reviewed individually. Scores help with course placement and some scholarships. For international applicants, ACT 19 or SAT 1060 is also accepted as proof of English.', '21ac5199-0f90-516b-ab41-0c855ad48f47');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('7c85ddd8-639a-5e71-b21a-2b1f88888ed4', '2026-27', array['own']::text[], 20, 'International applicants pay a $20 application fee plus a $100 processing fee before review starts. Records are uploaded to the My Warrior Life portal; unofficial transcripts are enough for the decision but original or certified copies with English translation are due before the first semester. Decisions are given 2-3 weeks after all documents (first-year page). The first-year page waives the application fee for applications completed Oct 1-31, but the international page does not mention that. Some degree programs have extra entrance requirements.', 'e0d94a33-10d0-5e66-9d2e-51dd9efe395e');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('e59130d0-cb6e-5e32-a1b5-2b17991ed3ab', '7c85ddd8-639a-5e71-b21a-2b1f88888ed4', '2026-27', 'application', 'ROLLING', 'International fall application deadline (applicants not attending a U.S. school), fall 2027 entry', '2027-05-01', 'Page lists May 1 for students not currently in a U.S. high school or college and Aug. 10 for those who are. It prints fall 2026 class dates, so the same dates are assumed for fall 2027. Spring: Sep. 1 (outside U.S.) or Dec. 1 (in U.S.). Program deadlines can differ.', 'e0d94a33-10d0-5e66-9d2e-51dd9efe395e'),
 ('e829a0aa-3665-5fe5-9287-b123861f3a9e', '7c85ddd8-639a-5e71-b21a-2b1f88888ed4', '2026-27', 'application', 'ROLLING', 'International fall application deadline (applicants already attending a U.S. school), fall 2027 entry', '2027-08-10', 'Assumed to repeat for fall 2027; the page does not print the year.', 'e0d94a33-10d0-5e66-9d2e-51dd9efe395e');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('7c85ddd8-639a-5e71-b21a-2b1f88888ed4', 'required_nonnative', 'The page says the English requirement may be waived in some cases; applicants log into the My Warrior Life portal to ask. ACT 19 or SAT 1060 is accepted in place of an English test. Pre-licensure Nursing needs TOEFL iBT 84 with a speaking score of 26, or IELTS 6.5 with 6.0 on every module. No conditional admission or ESL pathway is mentioned on the page.', 'e0d94a33-10d0-5e66-9d2e-51dd9efe395e');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
select '7c85ddd8-639a-5e71-b21a-2b1f88888ed4'::uuid, 'required_option', 'e0d94a33-10d0-5e66-9d2e-51dd9efe395e'::uuid, v.* from (values
 ('TOEFL_IBT', 68, 'Undergraduate minimum (graduate 80). Paper TOEFL 520 also listed. Nursing needs 84 with speaking 26.'),
 ('TOEFL_IBT_2026', 4, 'Listed as ''New TOEFL IBT'' 4 for undergraduate (4.5 graduate); the page does not name the 1-6 scale.'),
 ('IELTS', 5.5, 'Undergraduate minimum (graduate 6.5). Nursing needs 6.5 overall with 6.0 on all modules.'),
 ('DUOLINGO', null, 'The undergraduate cell on the page reads just ''5'' (graduate 110+, nursing graduate 115+), which looks like a typo, so no minimum is stored. Confirm with admissions before testing.'),
 ('PTE', 47, 'PTE Academic, undergraduate minimum (graduate 58).')) v;
insert into score_codes (institution_id, test_key, code, notes, source_id)
