insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, intl_applicants, intl_admits, in_state_applicants, in_state_admits, out_state_applicants, out_state_admits, pct_submit_sat, pct_submit_act, notes, source_id) values
 ('3bf1994d-18aa-5b5e-8890-32c9e4bb38ef', '2025-2026', 7356, 6018, 1014, 167, 57, 6171, 5110, 1018, 851, 28, 11, 'CDS C1 residency table (fall 2025): applicants 6,171 in-state / 1,018 out-of-state / 167 international (7,356 total); admits 5,110 / 851 / 57 (6,018); enrolled 885 / 119 / 10 (1,014). International applicants were admitted at a much lower rate than the total (57 of 167). The CDS sex-split rows of C1 show only 6,171 applicants and 5,110 admits, so the residency table totals are used. Undergraduate enrollment 4,289 is the CDS B1 ''Total all undergraduates'' (fall 2025); 14:1 ratio is CDS I-2. Winthrop reports a high school GPA average of 3.99 (C12) and a GPA distribution whose alignment could not be read reliably, so GPA fields are omitted. SAT/ACT percentiles are for enrolled first-year students (C9). The CDS checkboxes in C7 contradict C8A (test scores marked very important yet not used), so the factors are omitted.', 'ec16d4c8-1e40-5cab-a765-ee70c44c6e01');
insert into test_score_percentiles (institution_id, cds_year, source_id, test, p25, p50, p75)
select '3bf1994d-18aa-5b5e-8890-32c9e4bb38ef'::uuid, '2025-2026', 'ec16d4c8-1e40-5cab-a765-ee70c44c6e01'::uuid, v.* from (values
 ('SAT_TOTAL', 1020, 1120, 1210),
 ('SAT_ERW', 535, 590, 640),
 ('SAT_MATH', 480, 530, 580),
 ('ACT_COMPOSITE', 20, 23, 26)) v;
insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('3bf1994d-18aa-5b5e-8890-32c9e4bb38ef', '2026-27', 'optional', 'International pages: SAT/ACT not required but ''highly recommended for potential scholarship eligibility''. Freshman process page: ''Winthrop is test optional''; applicants indicate on the application whether they want scores considered. Freshman academic scholarships for out-of-state students are scored on GPA, or GPA plus SAT/ACT.', '76dacbba-0031-5a28-9a82-e7fea8600ff9');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('3bf1994d-18aa-5b5e-8890-32c9e4bb38ef', '2026-27', array['own']::text[], 60, 'International applicants pay a non-refundable US$60 fee (domestic freshmen $50). Required: official transcripts and mark sheets sent directly by the issuing school (portal uploads are not accepted), a course-by-course credential evaluation with GPA from a foreign evaluation agency (a NACES member is recommended), English proficiency proof, and a passport photo page. Letters of recommendation, essays and activities are ''considered if submitted'', not required (domestic freshman page). F/J applicants must show funds for one year (affidavit of support plus bank letter); no dollar amount is printed.', '76fe999a-5b79-5efc-8f29-dc8cbf4a9da8');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('6abf414f-32ad-53d5-9f52-2473718637a7', '3bf1994d-18aa-5b5e-8890-32c9e4bb38ef', '2026-27', 'priority', 'RD', 'Fall priority deadline for freshmen (fall 2027 entry)', '2026-11-01', 'The timeline page prints ''Fall Priority Deadline - November 1'' with no year; Nov. 1, 2026 is assumed for fall 2027. The page has no notes for international applicants, and the international pages print no deadline, so it is unclear whether this applies to them. Completed applications after Feb. 1 are reviewed monthly; the CDS says Winthrop has no application closing date.', 'd7d0a3b6-35aa-5afe-857b-f06a76087c7a'),
 ('19b2c47f-9341-5689-90aa-b8bea13092e9', '3bf1994d-18aa-5b5e-8890-32c9e4bb38ef', '2026-27', 'scholarship', null, 'Freshman scholarship deadline (fall 2027)', '2027-02-01', 'Completed application, fee and transcript by Feb. 1 (year assumed 2027); the FAQ page says Feb. 15 elsewhere. The scholarships page notes the Winthrop Scholars Guarantee details for fall 2027 are ''coming in late Fall 2026''.', 'fc413690-b242-5d42-8272-5587a2395d98'),
 ('065e9bcc-ef36-58d4-8926-70c407e2e346', '3bf1994d-18aa-5b5e-8890-32c9e4bb38ef', '2026-27', 'application', 'RD', 'Regular deadline for freshmen (fall 2027 entry)', '2027-05-01', 'The timeline page prints ''Regular Deadline - May 1'' with an asterisk and no year (May 1, 2027 assumed); applications after the posted deadlines are ''evaluated if space is available''. No separate international date is published.', 'd7d0a3b6-35aa-5afe-857b-f06a76087c7a');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('3bf1994d-18aa-5b5e-8890-32c9e4bb38ef', 'required_nonnative', 'Waived for graduates of a high school where English is the primary language of instruction, for two full-time semesters at an accredited U.S. institution plus two English composition courses with C- or higher (online composition not accepted), and for citizens of listed countries (e.g. Australia, Canada except Quebec, India, Ireland, Jamaica, New Zealand, Nigeria, Philippines, Singapore, South Africa, United Kingdom). First-year applicants may also use an SAT Evidence-Based Reading and Writing score of 480 or higher, Oxford ELLT 6 (no subscore below 5), or completion of ELS level 112. Official score reports must come directly from the testing agency.', '76fe999a-5b79-5efc-8f29-dc8cbf4a9da8');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, min_subscores, notes)
select '3bf1994d-18aa-5b5e-8890-32c9e4bb38ef'::uuid, 'required_option', '76fe999a-5b79-5efc-8f29-dc8cbf4a9da8'::uuid, v.* from (values
 ('TOEFL_IBT', 68, null, '520 on the paper-based test is also accepted. The page does not give a new 1-6 scale minimum.'),
 ('IELTS', 6.0, '{"each_section": 5.0}'::jsonb, 'Overall band 6.0 with no subscore lower than 5.'),
 ('DUOLINGO', 95, null, 'Duolingo English Test.'),
 ('PTE', 47, null, 'PTE Academic and PTE Academic Online.')) v;
insert into score_codes (institution_id, source_id, test_key, notes)
select '3bf1994d-18aa-5b5e-8890-32c9e4bb38ef'::uuid, '76fe999a-5b79-5efc-8f29-dc8cbf4a9da8'::uuid, v.* from (values
 ('sat', 'Winthrop''s international pages do not print an SAT code; look it up in the College Board code search.'),
 ('act', 'No ACT code is printed on the pages read; look it up at act.org.'),
 ('toefl', 'No TOEFL institution code is printed on the pages read; look it up in the ETS code search.'),
 ('ielts', 'No institution code is listed.'),
 ('duolingo', 'No institution code is listed.'),
 ('pte', 'No institution code is listed.')) v;
insert into cost_aid (institution_id, year, tuition_usd, tuition_out_of_state_usd, required_fees_usd, room_board_usd, books_usd, intl_aid_policy, intl_need_aid_awarded, intl_avg_award_usd, meets_full_need, merit_scholarships, notes, source_id) values
 ('3bf1994d-18aa-5b5e-8890-32c9e4bb38ef', '2025-2026', 11130, 25170, 3550, 14112, 1200, 'merit_only', 61, 24492, false, true, 'CDS G1 (first-year, 2025-26): in-state tuition $11,130, out-of-state $25,170, required fees $3,550, on-campus food and housing $14,112; G5 books $1,200, transportation $2,702 and other expenses $4,168 for residents. H6: 61 undergraduate degree-seeking nonresidents received institutional aid (avg $24,492; total $1,494,033); the need-based versus non-need-based checkbox could not be read.; The International Center says freshman academic scholarships (first-time undergraduates who submit SAT/ACT) are evaluated automatically at admission. Out-of-state freshman awards pair an annual scholarship ($1,000 to $6,000) with an out-of-state tuition waiver, but the page does not say whether international students are treated as out-of-state. International Ambassador Scholarship: $250 per semester plus an out-of-state grant for F/J students, with 30 service hours per semester; the total grant cannot exceed the out-of-state tuition portion. CDS H6: 61 nonresidents received institutional aid (average $24,492). Federal aid is not available to international students.', 'ec16d4c8-1e40-5cab-a765-ee70c44c6e01');
