insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('8b254d23-dd7a-5c62-b72c-40cf53e4a173', '2026-27', 'optional', 'Test-optional: SAT/ACT are not required and international applicants may opt in to the test-optional policy; the catalog recommends submitting a personal essay to support the application. CDS C8: not required for admission, but considered if submitted.', 'c9764af3-ee8e-5419-a3a5-a9164bb685d0');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('8b254d23-dd7a-5c62-b72c-40cf53e4a173', '2026-27', array['common_app','own']::text[], 50, 'Common App or the Worcester State Application. International documents: official secondary transcript or national exam results with a professional credential evaluation, English test if applicable, original bank letter or notarized financial affidavit (currently at least $34,900 for one year, subject to change) and a passport copy; minimum 2.0 cumulative GPA, and meeting minimums does not guarantee admission. Nursing (BSN) and Occupational Studies are selective majors with firm deadlines.', '81702725-27e0-5ec3-b42f-46fe9eaac343');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('9082aaa2-ea6f-5304-a9ce-fb4dc952f348', '8b254d23-dd7a-5c62-b72c-40cf53e4a173', '2026-27', 'application', 'EA', 'Early Action (first-year, fall 2027 entry)', '2026-11-15', 'Listed as ''Early Action (First-Years Only)'' in the deadlines table; the page does not say whether international applicants can use it. The page prints no year, so it is taken as the current cycle.', '55439277-7454-5e56-87e2-b55670534d8a'),
 ('f16df0f2-29e8-579f-9028-8878ed920fac', '8b254d23-dd7a-5c62-b72c-40cf53e4a173', '2026-27', 'priority', null, 'Nursing (BSN) and Occupational Studies fall deadline', '2027-01-15', 'The catalog gives January 15 for Fall-only Nursing (BSN) and Occupational Studies applicants instead of April 1; no year printed, taken as fall 2027.', 'c9764af3-ee8e-5419-a3a5-a9164bb685d0'),
 ('80c6f24a-992b-550a-8650-1f09d1513cd9', '8b254d23-dd7a-5c62-b72c-40cf53e4a173', '2026-27', 'priority', 'RD', 'Regular Decision priority date (domestic first-year, fall)', '2027-03-01', 'Domestic first-year priority date in the deadlines table; international students use the April 1 date below. CDS C13 lists rolling admission starting Nov 1 and a May 1 application closing date.', '55439277-7454-5e56-87e2-b55670534d8a'),
 ('38c866d9-b479-593d-b6d8-4f949ae819e3', '8b254d23-dd7a-5c62-b72c-40cf53e4a173', '2026-27', 'priority', null, 'International students: fall priority deadline', '2027-04-01', 'Deadlines table: ''International Students - Fall entrance priority deadline April 1''; the catalog says all documents must be submitted before April 1 for fall. Spring (Nov 15) is open to international applicants only in limited cases listed in the catalog. No year printed, taken as fall 2027.', '55439277-7454-5e56-87e2-b55670534d8a'),
 ('a67c8ebc-5165-5663-b035-d95068c2a30d', '8b254d23-dd7a-5c62-b72c-40cf53e4a173', '2026-27', 'deposit', null, 'Admissions deposit (needed before an I-20 is issued)', '2027-05-01', 'Catalog: Worcester State will not issue a Form I-20 until the admissions deposit is paid; the fall deposit deadline is May 1 with no exceptions.', 'c9764af3-ee8e-5419-a3a5-a9164bb685d0');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('8b254d23-dd7a-5c62-b72c-40cf53e4a173', 'required_nonnative', 'Required for applicants whose native language is not English or who studied in a country where English is not the native language. Applicants with an Associate of Arts or Science degree from a regionally accredited U.S. college are not required to submit a test.', '81702725-27e0-5ec3-b42f-46fe9eaac343');
