insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('c924079a-913d-5949-af67-21c8074dff6f', '2026-27', 'optional', 'SAT/ACT scores are optional for international applicants; the checklist says they are not mandatory but help with scholarship decisions. CDS C8 says scores are ''not required, but consider if submitted''. SAT EBRW 510 can be used to meet the English requirement.', '0394036f-f632-5c20-aca4-709a0fcf1f48');
insert into application_requirements (institution_id, cycle, platforms, notes, source_id) values
 ('c924079a-913d-5949-af67-21c8074dff6f', '2026-27', array['own']::text[], 'Applicants use Wright State''s own admissions portal (the pages do not mention the Common App). The international landing page says international applicants can apply for free, while the checklist still mentions a $30 non-refundable fee, so the fee is left null. Minimum 2.5 cumulative high school GPA. Required: passport copy, official records from all schools, and an I-20 request form with a current bank statement in USD (the application-instructions page says proof of funds is not needed when applying). Admission decisions can take up to four weeks.', '0394036f-f632-5c20-aca4-709a0fcf1f48');
insert into deadlines (id, institution_id, cycle, kind, label, due_date, notes, source_id) values
 ('54a4b831-3a69-5e49-af36-ded1873f7182', 'c924079a-913d-5949-af67-21c8074dff6f', '2026-27', 'application', 'International fall semester application deadline (fall 2027)', '2027-06-30', 'Page prints ''Fall Semester: June 30'' with no year; fall 2027 assumed. Spring deadline is Nov 30 and summer is Mar 31. Apply early: scholarship funds are limited.', 'bba6511e-d6d0-5282-982b-039384762d7d'),
 ('7b2a512a-dd3a-50c5-a57d-cb7765c02c3a', 'c924079a-913d-5949-af67-21c8074dff6f', '2026-27', 'scholarship', 'International Ambassador Scholarship essay deadline', '2027-03-12', '$10,000 per year; two first-year students selected for fall 2027. Requires admission as a first-year international applicant and a scholarship essay.', '65d30c99-4b1d-55a3-83da-3562de270da5');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('c924079a-913d-5949-af67-21c8074dff6f', 'required_nonnative', 'Exempt with an Intensive English Program completed at an accredited institution (or a program accepted by international admissions), graduation from an accredited U.S. high school, or graduation from a school in a country where English is the official language of higher education (list linked on the page). The page does not describe a Wright State ESL or conditional-admission pathway; a 2023 policy draft says the former LEAP program is no longer offered.', '4330224e-a725-5404-8d15-53da5192fd03');
