insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, intl_applicants, intl_admits, in_state_applicants, in_state_admits, out_state_applicants, out_state_admits, pct_submit_sat, pct_submit_act, gpa_avg, pct_reporting_gpa, gpa_distribution, notes, source_id) values
 ('9e70eb57-a907-5091-9a9f-9ad35fb4525e', '2025-2026', 6167, 5979, 1444, 96, 87, 1710, 1662, 4360, 4229, 15, 67, 3.53, 99.4, '{"4.0": 12.1, "3.75-3.99": 31.3, "3.50-3.74": 18.8, "3.25-3.49": 14.1, "3.00-3.24": 9.6, "2.50-2.99": 12.0, "2.0-2.49": 2.3, "1.0-1.99": 0.0}'::jsonb, 'CDS C1 (fall 2025 entering class). Applied and admitted counts include 1 applicant of unknown residency (6,167 total applied, 5,979 admitted); the international row (96 applied, 87 admitted, 10 enrolled) is by residency at application. SAT/ACT percentages are C9 (79% submitted either). GPA distribution is the published ''all enrolled students'' column and sums to 100.2 because of rounding. Undergraduate enrollment is the CDS B1 ''Total all undergraduates'' (8,138) for fall 2025; student-faculty ratio is the fall 2025 CDS figure (12.4 to 1). No early decision or early action. intl_undergrads left null: the CDS B2 nonresident row could not be identified reliably from the extracted text.', '5bd208d7-1f85-55e1-9429-0d29bd6a655f');
insert into test_score_percentiles (institution_id, cds_year, source_id, test, p25, p50, p75)
select '9e70eb57-a907-5091-9a9f-9ad35fb4525e'::uuid, '2025-2026', '5bd208d7-1f85-55e1-9429-0d29bd6a655f'::uuid, v.* from (values
