insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('9e70eb57-a907-5091-9a9f-9ad35fb4525e', '2026-27', 'optional', 'Test scores are not required for admission but can help secure higher financial awards. Assured admission needs a cumulative high school GPA of 3.00-4.00; applicants with 2.50-2.99 are admitted with support. The page gives no separate GPA rule for international applicants.', 'a738bfdf-6ed9-5649-9fc2-d5eed1aeba4a');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('9e70eb57-a907-5091-9a9f-9ad35fb4525e', '2026-27', array['common_app','own']::text[], 40, 'Non-refundable $40 fee. International applicants submit official transcripts (native language plus official English translation, or via a NACES-approved agency), proof of English proficiency, an official bank statement as proof of financial support, and a passport copy. The Common App is also accepted for first-year students.', '7c4a6dd8-bb5f-52a4-b4ec-cb47b6a2c022');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('cd9cda97-b731-5e12-9b4b-f6f836a0ea58', '9e70eb57-a907-5091-9a9f-9ad35fb4525e', '2026-27', 'application', 'ROLLING', 'International recommended application date, fall 2027 entry', '2027-06-01', 'UW admits on a rolling basis and keeps accepting applications after this date, but a later application may not leave time to finish immigration steps. Same page: spring Nov. 1, summer April 1. The page prints no year; treated as fall 2027. CDS C14 also lists June 1 and August 10 as fall closing dates (the extracted text does not label which is international).', '7c4a6dd8-bb5f-52a4-b4ec-cb47b6a2c022'),
 ('0001caef-d03c-5160-b1e9-9210f0b7cee4', '9e70eb57-a907-5091-9a9f-9ad35fb4525e', '2026-27', 'scholarship', null, 'Brown and Gold Commitment: confirm enrollment (fall 2027)', '2027-08-01', 'International students selected for the commitment must confirm enrollment by August 1, 11:59 pm MDT. They must also submit the UW Confidential Financial Statement. Date printed without a year on a page for the fall 2027/spring 2028 year.', 'c55cbcb9-4332-566e-96ff-ffbcd8401b82');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('9e70eb57-a907-5091-9a9f-9ad35fb4525e', 'required_nonnative', 'Applicants whose native language is English and who are citizens of, or hold a university-level degree from, a listed country may be exempt: Antigua and Barbuda, Australia, Bahamas, Belize, Bermuda, Canada (not Quebec), Ghana, Grenada, Guyana, Ireland, Jamaica, New Zealand, Nigeria, Singapore, St. Kitts and Nevis, St. Lucia, Dominica, St. Vincent and the Grenadines, Trinidad and Tobago, United Kingdom, United States. Other accepted proof: SAT EBRW 460, ACT English 20, IB English HL 4+, AP English Language or Literature 4+, IGCSE/GCE C or above in English, GTEC 1,140, TOEIC 675, EIKEN Pre-1, Gaokao 120 (94 in Jiangsu and Shanghai), HKDSE 4. Page notes some programs have specific requirements.', '7bd4f509-e881-5336-8c3f-179cccd5aefb');
insert into english_requirements (institution_id, source_id, test_key, status, min_total, notes)
select '9e70eb57-a907-5091-9a9f-9ad35fb4525e'::uuid, '7bd4f509-e881-5336-8c3f-179cccd5aefb'::uuid, v.* from (values
 ('TOEFL_IBT_2026', 'required_option', 4.0, 'Page lists ''iBT/TOEFL, MyBest scores, TOEFL Home Edition: 4'', which is the 1-6 scale. No 0-120 minimum is printed. Some programs may require more.'),
 ('IELTS', 'required_option', 6.0, 'IELTS Indicator also accepted.'),
 ('DUOLINGO', 'required_option', 100, null),
 ('PTE', 'required_option', 50, null),
 ('CAMBRIDGE', 'accepted', null, 'B2 First (no numeric score printed).')) v;
