insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('b229f2ff-856b-5373-bd59-8eb80202f0e1', '2026-27', 'optional', 'The freshman page says Xavier is test-optional (it describes the policy in pandemic terms, so confirm it still applies); applicants who do not submit SAT/ACT must submit an essay and resume instead. The CDS (C8F) says test scores are required for students with a GPA below 3.0. The page states there is no minimum GPA or test score for admission.', '7f45439e-86e5-531d-8b92-10f0e31a7f30');
insert into application_requirements (institution_id, cycle, platforms, counselor_rec, app_fee_usd, notes, source_id) values
 ('b229f2ff-856b-5373-bd59-8eb80202f0e1', '2026-27', array['common_app','own']::text[], true, 0, 'Application is free (Xavier application or Common App). Freshmen need an official transcript and a counselor recommendation; the international page also lists a personal statement and financial documentation. Non-native English speakers submit TOEFL, IELTS or Duolingo. The pages print no cycle year; deadlines are assumed to repeat for fall 2027.', '474bd2db-6191-55c1-88db-8e50554b55d8');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('7ba6fa0a-7f61-5052-96de-b786133642f5', 'b229f2ff-856b-5373-bd59-8eb80202f0e1', '2026-27', 'scholarship', null, 'Preferred scholarship deadline (fall 2027 entry)', '2026-12-01', 'Printed as December 1 with no year; assumed Dec. 1, 2026 for fall 2027 entry.', '474bd2db-6191-55c1-88db-8e50554b55d8'),
 ('c0201cde-9f22-5a59-9a0c-332f7a1dcc0a', 'b229f2ff-856b-5373-bd59-8eb80202f0e1', '2026-27', 'application', 'ROLLING', 'Preferred application deadline, fall (fall 2027 entry)', '2027-03-01', 'Printed as March 1 with no year; assumed 2027. Late international applications may be cut off June 1 because of visa processing time. CDS C16: decisions on a rolling basis beginning Oct. 1; reply by May 1. The international page also gives Sept. 1 for spring entry.', '474bd2db-6191-55c1-88db-8e50554b55d8');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('b229f2ff-856b-5373-bd59-8eb80202f0e1', 'required_nonnative', 'Students whose native language is English or who come from countries where English is the native language are exempt; transfer applicants with U.S. high school or college work may qualify for a waiver. The freshman page says TOEFL/IELTS are required only for non-native speakers. Conditional admission or an ESL pathway is not described.', '474bd2db-6191-55c1-88db-8e50554b55d8');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
select 'b229f2ff-856b-5373-bd59-8eb80202f0e1'::uuid, 'required_option', '474bd2db-6191-55c1-88db-8e50554b55d8'::uuid, v.* from (values
 ('TOEFL_IBT', 80, 'Internet-based 80; paper-based 550. No minimum is given on the 1-6 scale.'),
 ('IELTS', 7.0, 'Overall band 7.0.'),
 ('DUOLINGO', 105, 'The page lists ''between 105 and 115''; 105 is taken as the minimum.')) v;
insert into score_codes (institution_id, test_key, notes, source_id)
select 'b229f2ff-856b-5373-bd59-8eb80202f0e1'::uuid, v.* from (values
 ('sat', 'No SAT code is printed on the admissions pages found.', '7f45439e-86e5-531d-8b92-10f0e31a7f30'::uuid),
 ('act', 'No ACT code is printed on the admissions pages found.', '7f45439e-86e5-531d-8b92-10f0e31a7f30'::uuid),
 ('toefl', 'No TOEFL institution code is printed on the admissions pages found.', '474bd2db-6191-55c1-88db-8e50554b55d8'::uuid),
 ('ielts', 'No institution code is listed.', '474bd2db-6191-55c1-88db-8e50554b55d8'::uuid),
 ('duolingo', 'No institution code is listed.', '474bd2db-6191-55c1-88db-8e50554b55d8'::uuid),
