insert into cost_aid (institution_id, year, tuition_usd, merit_scholarships, notes, source_id) values
 ('b229f2ff-856b-5373-bd59-8eb80202f0e1', '2026-2027', 27670, true, 'Full-time tuition (12-18 hours) is $13,835 per semester, $27,670 per year, for the College of Arts and Sciences and Pre-Pharmacy (fee sheet, fall 2026 and spring 2027). Separate per-semester fees on the sheet include information technology $462, health and wellness $214, student activity $144, ID $11 and a $350 book bundle; annual student health insurance is $2,327. Room and board is not published on the pages found. The international page lists a U.S. visa fee of $185 and a SEVIS fee of $350.; CDS G1 and G5 columns lost their headers in the PDF text, so CDS tuition, fee and housing figures are not copied here; see the cycle file for the 2026-27 tuition schedule.; International applicants are automatically considered for merit scholarships on admission (Board of Trustees, Presidential, Xavier University Academic); Music Department awards up to $10,000; pre-med Board of Trustees and JW Carmichael scholarship up to $40,000; athletic awards case by case. International students are not eligible for federal aid. CDS H6 checkboxes are unreadable, but it shows 66 nonresident aid recipients with an average institutional award of $17,229 (the table''s year is not clear).', '9ed27e2c-a8d6-5991-b16f-717488fd5a92');
insert into institution_tiers (institution_id, category_key, tier_code, rationale)
select 'b229f2ff-856b-5373-bd59-8eb80202f0e1'::uuid, v.* from (values
 ('general', 'D+', 'Admit rate 67.4%; SAT middle 50% 950-1150'),
 ('biology_life_sci', 'C', 'C: the largest bachelor''s program by completions (134 biology, 15 neuroscience, 14 biochemistry in IPEDS 2024-25), a fully accredited College of Pharmacy and a broad life-science pipeline. Editorial judgment.'),
 ('pre_med', 'C', 'C: pre-health is the school''s core strength: biology, chemistry (37), public health (65) and psychology (62) bachelor''s completions feed health-professions graduate programs. Editorial judgment.'),
 ('computer_science', 'D', 'Editorial judgment (v1, reviewed 2026-10-20)'),
 ('business', 'D', 'Editorial judgment (v1, reviewed 2026-10-20)'),
 ('math_physics', 'D', 'Editorial judgment (v1, reviewed 2026-10-20)'),
 ('humanities', 'D', 'Editorial judgment (v1, reviewed 2026-10-20)'),
 ('arts_design', 'D', 'Editorial judgment (v1, reviewed 2026-10-20)')) v;

