insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('63892b3f-7d76-58af-a7b1-6c8cd6ef393d', '2026-27', 'optional', 'SAT/ACT are not required for admission (CDS C8: considered if submitted). A 26 ACT / 1240 SAT is the Sokolov Honors College threshold (for 2026-27, applicants with a 3.5+ GPA and no test are also encouraged to apply). SAT 920 or ACT 17 can be used to meet the English requirement.', '0a2a7a6f-cafb-512f-beb3-375f26ad1e1b');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('63892b3f-7d76-58af-a7b1-6c8cd6ef393d', '2026-27', array['own']::text[], 75, 'International freshmen apply through YSU''s own portal; the $75 non-refundable fee can be paid via Flywire. Minimum 2.00 high school GPA. Passport copy and official credentials are required: a NACES credential evaluation (IEE, TEC or Scholaro), except applicants from Nepal, Bangladesh, India, Sri Lanka, Malaysia, Vietnam, Taiwan and Thailand, whose school sends records by email to intadm@ysu.edu. F-1 students must show funds for one year. Decisions take at least 10 business days after the file is complete. The page says applications from countries affected by U.S. travel restrictions are temporarily not being processed.', '11eef09f-cddb-58fb-bbe3-b71b8387050c');
insert into deadlines (id, institution_id, cycle, kind, label, due_date, notes, source_id) values
 ('e8f7c6a2-a302-558c-b202-8c43ca8e9465', '63892b3f-7d76-58af-a7b1-6c8cd6ef393d', '2026-27', 'priority', 'International freshman priority deadline, fall 2027', '2027-06-01', 'Catalog lists fall June 1 and spring Nov 1 as priority deadlines (no year printed; fall 2027 assumed). Summer admission is not available to international students.', '9730c8a6-3f32-527e-9b81-fd048b36c8a0');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('63892b3f-7d76-58af-a7b1-6c8cd6ef393d', 'required_nonnative', 'Exempt if education was in English at a secondary or post-secondary school in a listed country (Australia, Canada, Ghana, Ireland, Kenya, Nigeria, South Africa, United Kingdom and others), after 24 semester hours of English-medium college work, or after ELI Level 5. SAT 920 (EBRW+Math) or ACT 17 also meets the requirement. Scores older than two years are not accepted. Conditional admission is offered with English study at YSU''s English Language Institute (ELI); the 1-semester International Pathway Program accepts IELTS 5.0, TOEFL 46 or Duolingo 85.', '52de9ca6-de4f-5e7e-b664-01ccbc48bbdb');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, min_subscores, notes)
select '63892b3f-7d76-58af-a7b1-6c8cd6ef393d'::uuid, 'required_option', '52de9ca6-de4f-5e7e-b664-01ccbc48bbdb'::uuid, v.* from (values
 ('TOEFL_IBT', 67, null, null),
 ('TOEFL_IBT_2026', 4, null, 'Page lists ''Updated 2026 TOEFL iBT scoring system: 4'' without naming the 1-6 scale. Pre-nursing and dental hygiene also need a writing subscore of 4.0.'),
 ('IELTS', 6.0, '{"each_section": 5.0}'::jsonb, 'At least 5.0 on each subscale; writing 6.0 for pre-nursing and dental hygiene.'),
 ('DUOLINGO', 95, null, 'Writing subscore 105 for pre-nursing and dental hygiene.'),
 ('PTE', 50, null, null)) v;
