insert into major_admissions (id, institution_id, program, category_key, admit_model, capped, notes) values
 ('505795da-6d0b-54b3-a76e-9e39cefd185f', '63892b3f-7d76-58af-a7b1-6c8cd6ef393d', 'Nursing (BSN), Dental Hygiene (BDH), Radiologic Technology, Respiratory Care and related health programs', 'nursing', 'pre_major_competitive', true, 'Restricted programs: applicants are admitted to a pre-major (e.g. Pre-Nursing) and apply later; the major cannot be changed into a restricted program after the initial decision. Pre-Nursing needs high school chemistry with a C or better plus a minimum English writing subscore.');
